# MAA 掉落统计：回调随时可能到达，模块级初值保证首次回调不会因缺名而中断。
stage_drop = {"details": [], "summary": {}}


def _drop_entries(value):
    """掉落条目必须是对象列表；畸形负载不得进入 maa_stop 汇报模板。"""
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, dict)]


def reset_stage_drop():
    """开始新一轮 MAA 前清空掉落统计，供回调累积与 maa_stop 汇报共用。"""
    stage_drop["details"] = []
    stage_drop["summary"] = {}


class ProductSwitchDeferred(Exception):
    def __init__(
        self,
        message: str,
        *,
        ready_at=None,
        dependencies=(),
        rooms=(),
        room_deferrals=(),
        log_reason=None,
    ):
        super().__init__(message)
        self.ready_at = ready_at
        self.dependencies = tuple(dependencies)
        self.rooms = tuple(rooms)
        self.room_deferrals = tuple(room_deferrals)
        self.log_reason = log_reason


class ProductSwitchFailed(RuntimeError):
    def __init__(self, message, rooms):
        super().__init__(message)
        self.rooms = tuple(rooms)


class ProductSwitchPriorityDeferred(Exception):
    """整批操作尚未开始，等待已有关键任务完成后重新准入。"""


class GroupShiftBlocked(ProductSwitchDeferred):
    def __init__(
        self,
        groups=(),
        *,
        predecessors=(),
        recovery_names=(),
        recovery_reason="离岗成员的恢复床位",
    ):
        self.groups = set(groups)
        self.predecessors = tuple(predecessors)
        self.recovery_names = tuple(recovery_names)
        waiting = (
            "前置换班确认"
            if self.predecessors
            else recovery_reason
            if self.recovery_names
            else "、".join(sorted(groups)) + "回班"
            if groups
            else "替班可用"
        )
        super().__init__(f"绑组依赖未解除，挂起换班，等待{waiting}")


@dataclass(eq=False, slots=True)
class _DormRemovalFrame:
    task: SchedulerTask
    room: str
    names: tuple[str, ...]
    recognizer: Recognizer
    device: Device
    touch_control: object | None
    image: np.ndarray | None
    gray: np.ndarray
    capture_started_at: datetime

    def matches_plan(self, task):
        return task is not None and tuple(task.plan.get(self.room, ())) == self.names

    def is_current(self, solver, image):
        # 识别器记录抓屏请求时间，这一秒包括取图和点床前的核验。
        return (
            image is not None
            and solver.task is self.task
            and self.matches_plan(solver.task)
            and self.room not in getattr(self.task, "dorm_recovery_restore", ())
            and solver.recog is self.recognizer
            and solver.device is self.device is self.recognizer.device
            and getattr(self.device, "control", None) is self.touch_control
            and self.recognizer._img is image
            and self.recognizer._gray is self.gray
            and self.recognizer.capture_started_at == self.capture_started_at
            and 0 <= (datetime.now() - self.capture_started_at).total_seconds() <= 1
        )


class BaseSchedulerSolver(
    ClueCreditMixin, ClueGiftMixin, EmergencyRecoveryMixin, SceneGraphSolver, BaseMixin
):
    """
    收集基建的产物：物资、赤金、信赖
    """

    # MAA 回调日志：每次 initialize_maa 建立新实例，本轮 MAA 的可读进度行来自它。
    maa_callback: MaaCallbackLog | None = None

    def __init__(
        self,
        device: Device = None,
        recog: Recognizer = None,
        *,
        connection_retries: int = 3,
    ) -> None:
        self._monthly_card_reminder = MonthlyCardReminder()
        super().__init__(device, recog, connection_retries=connection_retries)
        self.op_data = None
        self.party_time = None
        self.drone_time = None
        self.reload_time = None
        self.clue_count_limit = 9
        self.enable_party = True
        self.leifeng_mode = False
        self.digit_reader = DigitReader()
        self.error = False
        self.clue_count = 0
        self.task = None
        self.tasks = []
        self.waiting_group_shifts = []
        self.backup_group_task_issued = set()
        self.free_clue = None
        self.credit_fight = None
        self.maa_daily_completed = {}
        self.maa_daily_tasks = {}
        self.display_observations = {}
        self.task_count = 0
        self.refresh_connecting = False
        self.recruit_time = None
        self.last_clue = None
        self.sleeping = False
        self._simulator_closed_for_idle = False
        self._idle_observation_pending = False
        self.operators = {}
        self.last_execution = {"maa": None, "recruit": None, "todo": None}
        self.annihilation_lock_mail_day = None
        self.order_reader = TradingOrder()
        self.sign_in = (datetime.now() - timedelta(days=1, hours=4)).date()
        # 尚无记录时取上一游戏日；本机时钟在 UTC+8 以东时，按本地日期推算可能落在当前游戏日。
        previous_game_day = get_server_time().date() - timedelta(days=1)
        self.daily_report = previous_game_day
        self.daily_skland = previous_game_day
        self.daily_skland_attempt = None
        self.daily_mail = previous_game_day
        self.daily_event_sign_in = previous_game_day
        self.daily_event_sign_in_attempt = None
        self.daily_visit_friend = previous_game_day
        self.daily_visit_friend_attempt = None
        self.maa_copilot_progress = {}
        self.maa_copilot_task = None
        self.maa_paradox_task = None
        self.maa_sss_task = None
        self.maa_blackflow_task = None
        self.maa_event_shop_task = None
        self.ideal_resting_count = 4
        self.choose_error = set()
        self.drop_send = False
        self.global_plan = {}
        self.local_operation_followup_time = None
        self.train_room_state = None
        self.emergency_state = None
        self._emergency_startup_pending = False
        self._startup_run_order_check_pending = True
        self._startup_mood_observations = {}
        workshop_inventory_changed.set()
        self._register_network_wait_observer()

    @property
    def drone_room(self):
        effective = getattr(getattr(self, "op_data", None), "config", None)
        room = getattr(effective, "drone_room", None)
        if room is not None:
            return room or None
        return getattr(self, "_drone_room", None)

    @drone_room.setter
    def drone_room(self, room):
        self._drone_room = room

    @property
    def drone_count_limit(self):
        effective = getattr(getattr(self, "op_data", None), "config", None)
        limit = getattr(effective, "drone_count_limit", None)
        return config.conf.drone_count_limit if limit is None else limit

    def _register_network_wait_observer(self):
        owner = getattr(self, "recog", None)
        if owner is None:
            return
        get_network_adaptation(owner).set_observation_callback(
            self._on_network_wait_observed
        )

    def _on_network_wait_observed(self, event):
        # 只更新待执行任务的参数，队列仍由下一次正常调度排序。
        bind_run_order_network(
            self.tasks,
            self.recog,
            config.conf,
            event.observed_at,
            op_data=getattr(self, "op_data", None),
        )

    def find_next_task(
        self,
        compare_time: datetime | None = None,
        task_type="",
        compare_type: Literal["<", "=", ">"] = "<",
        meta_data="",
        *,
        scope=TaskScope.DISPATCH,
    ):
        """找符合条件的下一个任务

        Args:
            tasks: 任务列表
            compare_time: 截止时间
        """
        return find_next_task(
            self.tasks,
            compare_time,
            task_type,
            compare_type,
            meta_data,
            scope=scope,
            op_data=getattr(self, "op_data", None),
        )

    @property
    def party_time(self):
        return self._party_time

    @party_time.setter
    def party_time(self, value):
        self._party_time = value
        if self.op_data is not None:
            current_party_time = getattr(self.op_data, "party_time", None)
            if current_party_time is None or (
                isinstance(current_party_time, datetime)
                and current_party_time <= datetime.now()
            ):
                self.op_data.party_time = value

    def set_detected_party_time(self, value):
        """写入会客室界面确认过的线索交流状态。

        ``party_time`` 的普通 setter 会保留尚未到期的旧值，避免开始刷新时的
        临时清空让依赖它的副表误切换。界面读取结果不是临时状态：读不到倒计时
        表示交流已经结束，必须覆盖旧预测，哪怕旧预测时间仍在未来。
        """
        self._party_time = value
        if self.op_data is not None:
            self.op_data.party_time = value

    def read_party_time(self):
        """读取线索交流结束时间；空倒计时表示交流已经结束。"""
        remaining = self.read_time(((1768, 438), (1902, 480)), None)
        if remaining is None:
            return None
        return datetime.now() + timedelta(seconds=remaining)

    @staticmethod
    def _room_slot_distracted(gray, top):
        # 只匹配心情下方的状态文字，排除头像上的同名提示和右侧倒计时。
        status = gray[top + 132 : top + 174, 1470:1620]
        template = loadres("infra_distracted", gray=True)
        if status.shape[0] < template.shape[0] or status.shape[1] < template.shape[1]:
            return False
        return cv2.matchTemplate(status, template, cv2.TM_CCOEFF_NORMED).max() >= 0.95

    def read_operator_time(self, room, index, cord):
        """从采集时刻计算干员倒计时的终点。空值按非工作状态或心情耗尽处理。"""
        remaining = self.read_time(cord, None)
        if remaining is None:
            logger.info(
                f"{facility_label(room, getattr(self, 'op_data', None))} "
                f"{index + 1}号位未显示干员倒计时，按非工作状态或心情耗尽处理",
                extra={"log_room": room},
            )
            return datetime.now()
        if (
            not isinstance(remaining, (int, float))
            or not math.isfinite(remaining)
            or remaining < 0
        ):
            raise RecognizeError(f"房间 {room} 第 {index + 1} 槽位倒计时未核实")
        sampled_at = getattr(getattr(self, "recog", None), "capture_started_at", None)
        if not isinstance(sampled_at, datetime):
            sampled_at = datetime.now()
        return sampled_at + timedelta(seconds=remaining)

    def _task_failure_snapshot(self, task, rooms, *, arrangement_room=None):
        """失败任务仅由新观测或相关安排变化重新准入，不使用时钟计时。"""
        if pending := getattr(task, "credit_shop_pending", None):
            return copy.deepcopy(pending["observation"])
        if getattr(task, "clue_access_record_pending", False):
            return {"access_record_visible": self._clue_access_record_visible()}
        if getattr(task, "clue_receipt_pending", False):
            return self._clue_receipt_observation()
        if task.type in MANUAL_TASK_TYPES:
            from arknights_mower.solvers.manual_tasks import manual_task_snapshot

            return manual_task_snapshot(self, task)
        data = self.op_data
        plan = (
            task.plan
            if arrangement_room is None
            else {arrangement_room: task.plan.get(arrangement_room, [])}
        )
        names = {name for row in plan.values() for name in row}
        from arknights_mower.utils.replacement_coordination import (
            coordination_reservations,
            replacement_dependencies,
        )

        if arrangement_room is None and (
            task.type == TaskTypes.EXHAUST_OFF
            or getattr(task, "coordination_request_names", ())
        ):
            names.update(
                replacement_dependencies(
                    data,
                    getattr(task, "coordination_request_names", ())
                    or task.meta_data.split(","),
                )
            )
            rooms = tuple(
                dict.fromkeys(
                    [
                        *rooms,
                        *(room for room in data.plan if room.startswith("dorm")),
                        *(
                            op.room
                            for name in names
                            if (op := data.operators.get(name)) is not None
                        ),
                        *(
                            op.current_room
                            for name in names
                            if (op := data.operators.get(name)) is not None
                            and op.current_room
                        ),
                    ]
                )
            )
        reserved, slots = coordination_reservations(data, self.tasks, task)
        dorm_plan = getattr(task, "run_order_dorm_plan", {})
        dorm_slots = getattr(task, "run_order_dorm_slots", {})
        if dorm_plan or dorm_slots:
            rooms = tuple(dict.fromkeys([*rooms, *dorm_plan, *dorm_slots]))
            names.update(name for row in dorm_plan.values() for name in row)
            if not dorm_plan or any(
                name in ("", "Free") for row in dorm_plan.values() for name in row
            ):
                # 空闲候选的释放及实测可解除缺人；忙碌者读数和预测计时不触发重试。
                names.update(
                    name
                    for name, op in data.operators.items()
                    if not op.current_room
                    and (not op.is_high() or data.is_standby(name))
                    and name not in reserved
                    and name not in data.config.free_blacklist
                    and not op.workaholic
                )
        correction_groups = set()
        if getattr(task, "derived_correction", False):
            owners = names | {
                data.plan[room][index].agent
                for room, row in plan.items()
                for index, name in enumerate(row)
                if name != "Current" and index < len(data.plan.get(room, ()))
            }
            correction_groups = {
                binding["group"]
                for name in owners
                if (op := data.operators.get(name)) is not None
                for binding in op.group_bindings
                if binding["group"]
            }
        from arknights_mower.utils.backup_group_tasks import active_group_tasks

        snapshot = {
            "plan": plan,
            "correction_groups": {
                group: data.group_is_resting(group) for group in correction_groups
            },
            "reservations": (
                sorted(names & reserved),
                sorted(slot for slot in slots if slot[0] in rooms),
            ),
            "effective_plan": {
                room: [vars(slot) for slot in data.plan.get(room, [])] for room in rooms
            },
            "products": {
                room: getattr(data, "products", {}).get(room) for room in rooms
            },
            "observations": {
                name: (
                    op.current_room,
                    op.current_index,
                    None if getattr(op, "mood_is_prediction", False) else op.time_stamp,
                )
                for name, op in data.operators.items()
                if name in names or op.current_room in rooms
            },
            "facilities": {
                room: getattr(data, "facility_states", {}).get(room) for room in rooms
            },
            "room_observations": {
                room: getattr(data, "room_observations", {}).get(room) for room in rooms
            },
        }
        if arrangement_room is None:
            snapshot["meta_data"] = task.meta_data
            snapshot["backup_group_tasks"] = tuple(active_group_tasks(data))
        if dorm_plan or dorm_slots:
            snapshot["run_order_dorm_plan"] = dorm_plan
        if (
            task.type == TaskTypes.EXHAUST_OFF
            and not task.plan
            and not getattr(task, "mood_physical_started", False)
            and getattr(data, "mood_calculation_enabled", False)
        ):
            model = data.mood_model
            snapshot["calculated_exhaustion"] = {
                "rules_hash": model.rules_hash,
                "rooms": model.rooms,
                "stages": model.stages,
                "single_targets": model.single_targets,
                "limits": {
                    name: (op.lower_limit, op.upper_limit)
                    for name, op in data.operators.items()
                    if name in names or name in task.meta_data.split(",")
                },
                "known": sorted(model.moods),
                "observed": model.observed,
                "pending_events": model.pending_events,
                "observations": {
                    name: (
                        op.current_room,
                        op.current_index,
                        op.mood
                        if op.time_stamp is not None
                        and not getattr(op, "mood_is_prediction", False)
                        else None,
                        None
                        if getattr(op, "mood_is_prediction", False)
                        else op.time_stamp,
                    )
                    for name, op in data.operators.items()
                },
            }
        if plan:
            snapshot["card_moods"] = {
                name: getattr(data, "dorm_mood_estimates", {}).get(name)
                for name in names
                if (op := data.operators.get(name)) is not None
                and (getattr(op, "rest_in_full", False) or getattr(op, "group", ""))
            }
        if getattr(task, "mastery_observation_pending", False):
            from arknights_mower.solvers.mastery import PROF_MAP
            from arknights_mower.utils.mastery_db import (
                get_active_plan,
                get_all_plans,
                get_plan_by_id,
                get_route,
                get_route_settings,
            )
            from arknights_mower.utils.mastery_recommendation import get_skill_data

            plan_key = getattr(task, "plan_key", None)
            plan = get_plan_by_id(plan_key) if plan_key else get_active_plan()
            try:
                character = (
                    get_skill_data()
                    .get("characters", {})
                    .get((plan or {}).get("char_id"), {})
                )
                profession = PROF_MAP.get(character.get("profession"))
            except Exception:
                # 静态资源读取失败也不能阻止保留原任务。
                profession = None
            snapshot["mastery"] = {
                "observation": getattr(self, "last_mastery_observation", None),
                "enabled": config.conf.mastery_enabled,
                "assistant_follows_schedule": config.conf.assistant_follows_schedule,
                "plan": plan,
                "route": get_route(profession) if profession else None,
                "successors": [
                    item
                    for item in get_all_plans()
                    if plan and item["char_id"] == plan.get("char_id")
                ],
                "settings": get_route_settings(),
            }
        if getattr(task, "replacement_check", None):
            snapshot["replacement_check"] = replacement_check_snapshot(self, task)
        if run_order_waits_for_staffing(task):
            # 缺员订单等待实际驻员或安排变化，同一空房的新读数不重启读取。
            snapshot["reservations"] = ([], [])
            snapshot["observations"] = {}
            snapshot["room_observations"] = {}
            snapshot["facilities"] = {
                room: {
                    key: getattr(data, "facility_states", {}).get(room, {}).get(key)
                    for key in ("facility", "product")
                }
                for room in rooms
            }
            snapshot["staffing"] = {
                room: data.get_current_room(room, bypass=True) for room in rooms
            }
            snapshot["run_order_eligible"] = data.is_run_order_room(task.meta_data)
        if pending := getattr(task, "run_order_confirmation_pending", None):
            # 同名单的新时间戳不证明迟到提交已结束，不能重启已耗尽的观察。
            snapshot["observations"] = {}
            snapshot["room_observations"] = {}
            snapshot.pop("card_moods", None)
            snapshot["staffing"] = {
                room: data.get_current_room(room, bypass=True) for room in rooms
            }
            snapshot["facilities"] = {
                room: {
                    key: getattr(data, "facility_states", {}).get(room, {}).get(key)
                    for key in ("facility", "product")
                }
                for room in rooms
            }
            snapshot["confirmation_target"] = pending["target"]
        return copy.deepcopy(snapshot)

    def _run_mastery_with_recovery(self, action):
        """本次执行内有限复核，耗尽后交给原任务的失败保留边界。"""
        for attempt in range(3):
            try:
                return action(self)
            except TrainingObservationError:
                if attempt == 2:
                    raise
                logger.warning(
                    "训练状态未确认，本次执行重新进房复核（%s/3）", attempt + 2
                )
                self.back_to_infrastructure()

    def _retain_failed_task(
        self,
        task,
        reason,
        rooms,
        *,
        dependency=False,
        log_group=None,
        arrangement_room=None,
    ):
        rooms = tuple(rooms)
        task.execution_failure = {
            "reason": reason,
            "rooms": rooms,
            "snapshot": self._task_failure_snapshot(
                task, rooms, arrangement_room=arrangement_room
            ),
            "dependency": dependency,
        }
        if arrangement_room is not None:
            task.execution_failure["arrangement_room"] = arrangement_room
            task.__dict__.setdefault("arrangement_failures", {})[arrangement_room] = (
                task.execution_failure
            )
        parent = self._rescue_staffing_log_parent(task)
        self._fail_rescue_staffing_log(task, reason)
        log = logger.info if dependency else logger.error
        log(
            "%s；保留原任务及时间，相关观测或安排更新后复核",
            reason,
            extra={
                "log_group": log_group,
                **({"log_parent": parent} if parent else {}),
            },
        )

    def _retain_credit_shop_failure(self, task, error):
        pending = copy.deepcopy(
            {"reward": error.pending_reward, "observation": error.observation}
        )
        continuation = copy.deepcopy(getattr(error, "continuation", None) or {})
        continuation.setdefault("on_demand", False)
        continuation["reward"] = pending["reward"]
        task.credit_shop_pending = pending
        task.credit_shop_continuation = continuation
        self._retain_failed_task(
            task, str(error), (), dependency=True, log_group="credit-shop"
        )

    def _observe_failed_arrangement_confirmation(self):
        """确认失败后只补一次完整实读，任务阶段仍由原执行流程处理。"""
        ordinary = {
            TaskTypes.SHIFT_ON,
            TaskTypes.SHIFT_OFF,
            TaskTypes.EXHAUST_OFF,
            TaskTypes.SELF_CORRECTION,
            TaskTypes.RE_ORDER,
            TaskTypes.FILL_DORM,
            TaskTypes.RELEASE_DORM,
            TaskTypes.NOT_SPECIFIC,
        }

        def failures_for(task):
            active = getattr(task, "execution_failure", None)
            if active and "arrangement_room" not in active:
                return (active,)
            return getattr(task, "arrangement_failures", {}).values()

        pending = [
            (task, failure, training_slot)
            for task in self.tasks
            if (
                task.type in ordinary
                or task.type == TaskTypes.RUN_ORDER
                and getattr(task, "run_order_restore_pending", False)
                and not task.meta_data
            )
            for failure in failures_for(task)
            if failure
            and (
                (
                    training_slot := TrainingSubmissionUnconfirmed.retained_slot(
                        task, failure
                    )
                )
                is not None
                or failure.get("reason", "").startswith("干员确认")
            )
        ]
        if not pending or self.scene() != Scene.INFRA_MAIN:
            return False
        for task, failure, training_slot in pending:
            recovery = getattr(task, "confirmation_recovery_rooms", {})
            for room in failure.get("rooms", ()):
                if room not in task.plan or recovery.get(room) == "consumed":
                    continue
                observation = SchedulerTask(
                    task_type=task.type, task_plan={room: task.plan[room]}
                )
                budget = estimate_task_duration(observation, op_data=self.op_data)
                budget += timedelta(seconds=60 if room.startswith("dorm") else 15)
                if any(
                    pending is not task
                    and pending.time <= datetime.now() + budget
                    and (
                        pending.type
                        in MAINTENANCE_TASK_TYPES
                        | {
                            TaskTypes.RUN_ORDER,
                            TaskTypes.FIAMMETTA,
                            TaskTypes.SKILL_UPGRADE,
                            TaskTypes.SWAP_SUPPORT,
                        }
                        or getattr(pending, "strict_mood_limit", False)
                    )
                    for pending in task_view(
                        self.tasks, TaskScope.DISPATCH, self.op_data
                    )
                ):
                    continue
                # 旧存档按失败原因补齐；同一任务的同一房间不因重登重新获权。
                recovery[room] = "consumed"
                task.confirmation_recovery_rooms = recovery
                try:
                    saved = save_current_state()
                except Exception as exc:
                    logger.error("保存确认恢复状态失败，保留原任务：%s", exc)
                    return True
                if saved is not True:
                    logger.error("保存确认恢复状态失败，保留原任务")
                    return True
                current_task = self.task
                self.task = task
                complete = False
                revision = getattr(self.op_data, "room_observations", {}).get(room, 0)
                try:
                    self.enter_room(room)
                    rows = self.get_agent_from_room(room, strict_observation=True)
                    length = RIGHT_SIDE_ROOM_CAPACITY.get(
                        room, len(self.op_data.plan.get(room, ()))
                    )
                    if room == "recycle":
                        length = getattr(self.op_data, "recycle_capacity", length)
                    names = [row["agent"] for row in rows if row["agent"]]
                    complete = (
                        bool(rows)
                        and len(rows) == length
                        and all(row.get("observed", True) for row in rows)
                        and len(names) == len(set(names))
                        and getattr(self.op_data, "room_observations", {}).get(room, 0)
                        > revision
                    )
                    if complete and room == "train" and training_slot is not None:
                        index, target = training_slot
                        occupant = rows[index]["agent"]
                        complete = self._training_slot_matches(
                            index, target, occupant
                        ) or self._submitted_training_occupant_changed(
                            failure, index, occupant
                        )
                except (MowerExit, DeviceRecoveryError, SharedADBError):
                    raise
                except Exception as exc:
                    logger.warning("确认结果补充实读未完成，保留原任务：%s", exc)
                finally:
                    if not complete:
                        # 补读不完整或仍为原驻员时，本次读数不解除失败。
                        failure["snapshot"] = self._task_failure_snapshot(
                            task,
                            failure["rooms"],
                            arrangement_room=failure.get("arrangement_room"),
                        )
                    self.task = current_task
                self.back_to_infrastructure()
                if complete:
                    self._resume_failed_tasks()
                return True
        return False

    def _run_order_restoration_failures(self):
        """读取仍在原队列中的原班恢复失败，保留本次失败的引用。"""
        return [
            (task, failure)
            for task in getattr(self, "tasks", ())
            if task.type == TaskTypes.RUN_ORDER
            and getattr(task, "run_order_restore_pending", False)
            and (failure := getattr(task, "execution_failure", None))
        ]

    def _request_run_order_restoration_observations(self, failures=None):
        """正常唤醒或载入后，由既有巡检为原有失败补一次实际驻员观察。"""
        current = {
            id(task): failure
            for task, failure in self._run_order_restoration_failures()
        }
        if failures is None:
            failures = self._run_order_restoration_failures()
        self._run_order_restoration_observations = {
            room: (task, failure)
            for task, failure in failures
            if current.get(id(task)) is failure
            for room in task.run_order_original_roster
        }

    def _refresh_backup_dorm_migration(self, task):
        """按实际住客重算仍试图迁走合法固定宿舍替班的旧副表安排。"""
        if (
            task.type != TaskTypes.RE_ORDER
            or task.meta_data != "副表内存收敛"
            or not task.plan
            or not all(room.startswith("dormitory_") for room in task.plan)
            or task.retains_execution
            or task.adjusted
            or task.strict_mood_limit
            or task.mood_limit is not None
            or any(
                getattr(task, flag, False)
                for flag in (
                    "mood_physical_started",
                    "derived_correction_started",
                    "group_shift_expected",
                    "backup_shift_active",
                    "backup_explicit_slots",
                    "product_shift_locked",
                    "product_switched_before_arrangement",
                    "backup_retention_started",
                    "backup_retention_admissions",
                    "backup_retention_releases",
                    "backup_retention_empty_slots",
                    "dorm_recovery_restore",
                    "ordinary_coordination",
                    "exhaust_support",
                    "emergency_staffing",
                    "arrangement_retry_room",
                    "initial_fia",
                    "departure_recovery_names",
                )
            )
            or hasattr(task, "backup_shift_intent")
            or hasattr(task, "backup_shift_conditions")
        ):
            return False
        stale = any(
            (current := self.op_data.get_current_operator(*bed.position)) is not None
            and self.op_data.is_recovery_dorm(bed, current.name)
            and task.plan.get(bed.position[0], [])[
                bed.position[1] : bed.position[1] + 1
            ]
            == [self.op_data.plan[bed.position[0]][bed.position[1]].agent]
            for bed in self.op_data.group_dorm
        )
        if not stale:
            return False
        simulation = copy.copy(self)
        simulation.op_data = self.op_data.project_arrangements([{}])
        simulation.tasks, simulation.waiting_group_shifts = copy.deepcopy(
            (
                [pending for pending in self.tasks if pending is not task],
                [
                    pending
                    for pending in getattr(self, "waiting_group_shifts", ())
                    if pending is not task
                ],
            )
        )
        data = simulation.op_data
        names, slots, _, _ = simulation._dorm_recovery_reservations(simulation.tasks)
        sources = [
            copy.deepcopy(bed)
            for bed in [*data.all_dorms(), *getattr(data, "displaced_dorms", ())]
            if bed.name in data.operators
            and (op := data.operators[bed.name]).is_resting()
            and (op.current_room, op.current_index) == bed.position
        ]
        tracked = {bed.name for bed in sources}
        proposed_names = {
            name
            for row in task.plan.values()
            for name in row
            if name not in ("", "Current", "Free")
        }
        for name in proposed_names - tracked:
            op = data.operators.get(name)
            if (
                op is not None
                and op.is_resting()
                and not op.room.startswith("dorm")
                and not data.is_dorm_replacement(name)
            ):
                sources.append(Dormitory((op.current_room, op.current_index), name))
        task.plan = rebalance_plan_swap_dorms(
            data, sources, reserved_names=names, reserved_slots=slots
        )
        for field in ("group_shift_transitions", "dorm_fill_plan"):
            task.__dict__.pop(field, None)
        logger.debug("固定宿舍替班仍有效，重算原副表宿舍迁移：%s", task.plan)
        return True

    def _refresh_derived_correction(self, task):
        """重算未开始的普通派生纠错及来源明确、岗位职责已失效的宿舍迁移。"""
        if task.type == TaskTypes.RE_ORDER:
            return self._refresh_backup_dorm_migration(task)
        if (
            task.type != TaskTypes.SELF_CORRECTION
            or not getattr(task, "derived_correction", False)
            or task.meta_data
            or any(
                getattr(task, name, False)
                for name in (
                    "derived_correction_started",
                    "group_shift_expected",
                    "backup_shift_active",
                    "backup_explicit_slots",
                    "backup_refresh_rules",
                    "product_shift_locked",
                    "product_switched_before_arrangement",
                    "exhaust_support",
                    "ordinary_coordination",
                    "preferred_replacement_restore",
                    "dorm_recovery_restore",
                    "emergency_staffing",
                    "arrangement_retry_room",
                    "strict_mood_limit",
                )
            )
            or hasattr(task, "backup_shift_intent")
            or hasattr(task, "backup_shift_conditions")
        ):
            return False
        simulation = copy.copy(self)
        simulation.op_data = self.op_data.project_arrangements([])
        simulation.tasks = [pending for pending in self.tasks if pending is not task]
        simulation.task = task
        plan = simulation.agent_get_mood(
            skip_dorm=getattr(task, "correction_skip_dorm", False),
            read_rooms=False,
            return_plan=True,
        )
        task.plan = plan or {}
        for name in ("group_shift_transitions", "dorm_fill_plan"):
            task.__dict__.pop(name, None)
        logger.debug("相关观测已更新，重新计算原纠错任务：%s", task.plan)
        return True

    def _submitted_training_occupant_changed(self, failure, index, occupant):
        previous = next(
            (
                name
                for name, observation in failure["snapshot"]["observations"].items()
                if tuple(observation[:2]) == ("train", index)
            ),
            "",
        )
        saved_revision = (
            failure["snapshot"].get("room_observations", {}).get("train") or 0
        )
        revision = getattr(self.op_data, "room_observations", {}).get("train", 0)
        return revision > saved_revision and occupant != previous

    def _failure_snapshot_changed(self, task, failure):
        if wait := failure.get("training_selection_wait"):
            from arknights_mower.utils.training_selection_recovery import (
                training_selection_ready,
            )

            ready = training_selection_ready(self, task, wait)
            if ready is not None:
                return ready
        if submitted := TrainingSubmissionUnconfirmed.retained_slot(task, failure):
            index, target = submitted
            if task.plan.get("train", [])[index : index + 1] == [target]:
                operator = self.op_data.get_current_operator("train", index)
                occupant = operator.name if operator is not None else ""
                if not self._training_slot_matches(
                    index, target, occupant
                ) and not self._submitted_training_occupant_changed(
                    failure, index, occupant
                ):
                    return False
        current_snapshot = self._task_failure_snapshot(
            task, failure["rooms"], arrangement_room=failure.get("arrangement_room")
        )
        if "arrangement_room" in failure:
            failure["snapshot"].pop("meta_data", None)
        current_cards = current_snapshot.get("card_moods", {})
        now = datetime.now()
        saved_cards = failure["snapshot"].setdefault("card_moods", current_cards)
        for name, estimate in current_cards.items():
            # 预估失效或丢失不构成新观测，也不能按时钟重新准入。
            if (
                dorm_candidate_mood(self.op_data, name, now) or 0
            ) < self.op_data.operators[name].upper_limit:
                saved_cards[name] = estimate
        if "card_moods" not in current_snapshot:
            failure["snapshot"].pop("card_moods", None)
        failure["snapshot"].setdefault("correction_groups", {})
        failure["snapshot"].setdefault(
            "reservations",
            current_snapshot["reservations"],
        )
        failure["snapshot"].setdefault(
            "room_observations", {room: None for room in failure["rooms"]}
        )
        mastery = failure["snapshot"].get("mastery")
        if mastery and getattr(self, "last_mastery_observation", None) is None:
            # 重启丢失进程内观测时间不构成新的训练实测。
            mastery["observation"] = None
        # 旧快照中的预测时间也不构成实测证据；预测失效不解除失败。
        for name, observation in failure["snapshot"]["observations"].items():
            op = self.op_data.operators.get(name)
            if op is not None and getattr(op, "mood_is_prediction", False):
                failure["snapshot"]["observations"][name] = (
                    *observation[:2],
                    None,
                )
        return current_snapshot != failure["snapshot"]

    def _blocked_arrangement_rooms(self, task, failed_room=None):
        blocked = {
            room
            for room, failure in getattr(task, "arrangement_failures", {}).items()
            if failure and room in task.plan
        }
        if failed_room in task.plan:
            blocked.add(failed_room)
        while blocked:
            reserved = {
                name
                for room in blocked
                for name in task.plan[room]
                if name not in ("", "Free", "Current")
            }
            reserved.update(
                name
                for name, op in self.op_data.operators.items()
                if op.current_room in blocked
            )
            dependents = {
                room
                for room, row in task.plan.items()
                if room not in blocked and not reserved.isdisjoint(row)
            }
            if not dependents:
                break
            blocked.update(dependents)
        return blocked

    def _suppress_dispatchable_arrangement(self, task, plan):
        held = (
            self._blocked_arrangement_rooms(task)
            if getattr(task, "arrangement_failures", None)
            else set()
        )
        if not held:
            self._suppress_facility_arrangement(plan)
            return
        # 保护规则只修改本次能执行的岗位，尤其不能在续做宿舍时撤销尚待补读的训练位。
        ready = {room: row for room, row in plan.items() if room not in held}
        self._suppress_facility_arrangement(ready)
        for room in plan.keys() - held - ready.keys():
            del plan[room]

    def _resume_observed_task(self, task):
        from arknights_mower.utils.retained_recovery import (
            reconcile_retained_recovery,
        )

        refreshed = self._refresh_derived_correction(task)
        if not refreshed:
            reconcile_retained_recovery(self.op_data, task)
        # 已开始的剩余执行继续保留；普通派生纠错重新经过完整预演。
        task.execution_retained = not refreshed
        del task.execution_failure
        task.__dict__.pop("product_shift_predecessors", None)
        task.__dict__.pop("process_recovery_fia_wait", None)
        self._log_arrangement(
            "相关观测或安排已更新，恢复原任务",
            task=task,
            log_group="credit-shop"
            if task.type in (TaskTypes.CREDIT_SHOP, TaskTypes.MAA_MALL)
            else "clue"
            if task.type in (TaskTypes.CLUE, TaskTypes.CLUE_PARTY)
            else None,
        )

    def _set_arrangement_dispatch(self, task):
        failures = task.arrangement_failures
        if task.plan and self._blocked_arrangement_rooms(task) == task.plan.keys():
            task.execution_failure = next(
                failure for failure in failures.values() if failure
            )
        else:
            task.__dict__.pop("execution_failure", None)
        if not failures:
            del task.arrangement_failures
        task.execution_retained = True

    def _resume_arrangement_rooms(self, task):
        if any(
            failure and failure.get("product_reservation")
            for failure in task.arrangement_failures.values()
        ):
            reserved_rooms = {
                room
                for _, slots in self._product_slot_conflicts(task)
                for room, _ in slots
            }
        else:
            reserved_rooms = set()
        for room, failure in list(task.arrangement_failures.items()):
            if room not in task.plan:
                del task.arrangement_failures[room]
            elif failure and (
                room not in reserved_rooms
                if failure.get("product_reservation")
                else self._failure_snapshot_changed(task, failure)
            ):
                task.execution_failure = failure
                self._resume_observed_task(task)
                # 新观测允许执行。保留房间标记，重入时先核对实读，再决定是否重选。
                task.arrangement_failures[room] = None
        self._set_arrangement_dispatch(task)

    @staticmethod
    def _legacy_selection_failure(task, failure):
        # 旧存档的重试房间也可能残留在切产物等前置失败上，只迁移可辨认的选人失败。
        room = getattr(task, "arrangement_retry_room", None)
        return (
            room in task.plan
            and len(task.plan) > 1
            and tuple(failure["rooms"]) == (room,)
            and not failure.get("dependency")
            and not getattr(task, "arrangement_failures", None)
            and BaseSchedulerSolver._is_ordinary_facility_arrangement(task)
            and (
                failure["reason"].startswith(
                    (
                        "干员确认",
                        "检测到干员选择错误",
                        "检测到安排干员未成功",
                        "两次滑动后整页干员及位置均未变化",
                    )
                )
                or failure["reason"].endswith("返回房间重试")
                or TrainingSubmissionUnconfirmed.retained_slot(task, failure)
                is not None
            )
        )

    def _restore_legacy_room_failure(self, task, failure):
        room = task.arrangement_retry_room
        saved = failure["snapshot"]
        names = set(saved["plan"].get(room, ()))
        # 从失败时的整项快照中提取旧读数，保留此后已发生的相关变化。
        saved.pop("backup_group_tasks", None)
        for key in (
            "plan",
            "effective_plan",
            "room_observations",
            "facilities",
            "products",
        ):
            if key in saved:
                saved[key] = {room: saved[key][room]} if room in saved[key] else {}
        saved["observations"] = {
            name: value
            for name, value in saved["observations"].items()
            if name in names or value[0] == room
        }
        if "card_moods" in saved:
            saved["card_moods"] = {
                name: value
                for name, value in saved["card_moods"].items()
                if name in names
            }
        if "reservations" in saved:
            reserved, slots = saved["reservations"]
            saved["reservations"] = (
                sorted(names.intersection(reserved)),
                [slot for slot in slots if slot[0] == room],
            )
        if groups := saved.get("correction_groups"):
            relevant = self._task_failure_snapshot(
                task, (room,), arrangement_room=room
            )["correction_groups"]
            saved["correction_groups"] = {
                group: groups[group] for group in groups.keys() & relevant.keys()
            }
        failure["arrangement_room"] = room
        task.arrangement_failures = {room: failure}

    def _resume_failed_tasks(self):
        self._discard_legacy_ordinary_requests()
        self._discard_legacy_recovery_checks()
        self._discard_legacy_run_order_waits()
        waiting_for_initial_charge = getattr(
            self, "_initial_fia_checked", False
        ) and any(getattr(task, "initial_fia", False) for task in self.tasks)
        for task in list(self.tasks):
            if waiting_for_initial_charge or self._is_startup_priority_task(task):
                # 实读完成或任务本身是读取前置时，不保留旧门控的观察挂起。
                task.__dict__.pop("startup_observation_pending", None)
            failure = getattr(task, "execution_failure", None)
            if (
                failure
                and (refresh := getattr(task, "maa_refresh_until", None)) is not None
                and datetime.now() >= refresh
            ):
                del task.execution_failure
                del task.maa_refresh_until
                task.execution_retained = True
                continue
            if failure:
                from arknights_mower.utils.retained_recovery import (
                    completed_ordinary_rest_request,
                )

                if completed_ordinary_rest_request(self.op_data, task):
                    self.tasks = [
                        pending for pending in self.tasks if pending is not task
                    ]
                    logger.debug("普通下班目标已实际入住，完成原请求：%s", task)
                    continue
            if failure and (trainee := getattr(task, "mastery_trainee_wait", None)):
                from arknights_mower.utils.mastery_schedule import (
                    trainee_runtime_conflict,
                )

                if trainee_runtime_conflict(self, trainee):
                    continue
                del task.execution_failure
                del task.mastery_trainee_wait
                task.execution_retained = True
                continue
            if failure and (waiting := getattr(task, "mastery_mood_wait", None)):
                from arknights_mower.utils.mastery_mood import (
                    support_mood_context,
                    support_mood_shortages,
                )

                changed = (
                    support_mood_context(waiting["plan_id"], self.op_data)
                    != waiting["context"]
                )
                shortages = support_mood_shortages(self.op_data, waiting["required"])
                observation_pending = getattr(
                    task, "mastery_mood_observation_pending", False
                ) and not any(
                    pending is not task
                    and pending.time <= datetime.now() + timedelta(minutes=1)
                    for pending in task_view(
                        self.tasks, TaskScope.DISPATCH, self.op_data
                    )
                )
                replacement_ready = any(
                    not support_mood_shortages(self.op_data, required)
                    for required in waiting.get("alternatives", ())
                )
                if (
                    not config.conf.assistant_follows_schedule
                    and not changed
                    and shortages
                    and not observation_pending
                    and not replacement_ready
                ):
                    continue
                del task.execution_failure
                del task.mastery_mood_wait
                task.execution_retained = True
                continue
            if failure and (pending := getattr(task, "credit_shop_pending", None)):
                if CreditShop.can_resume(self.recog, pending):
                    del task.execution_failure
                continue
            if failure and getattr(task, "clue_access_record_pending", False):
                if self._clue_access_record_cleared():
                    del task.execution_failure
                    del task.clue_access_record_pending
                continue
            if failure and getattr(task, "clue_receipt_pending", False):
                self._resume_clue_receipt(task, self._clue_receipt_observation())
                continue
            predecessors = getattr(task, "product_shift_predecessors", ())
            if failure and predecessors:
                dispatch = task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
                if any(
                    any(queued is predecessor for queued in self.tasks)
                    and (
                        getattr(predecessor, "product_shift_locked", False)
                        or getattr(predecessor, "backup_shift_active", False)
                        or any(queued is predecessor for queued in dispatch)
                    )
                    for predecessor in predecessors
                ):
                    continue
            if failure and getattr(task, "process_recovery_fia_wait", False):
                fia = self.op_data.operators.get("菲亚梅塔")
                if (
                    fia is None
                    or (dorm_candidate_mood(self.op_data, fia.name) or 0) < 24
                ):
                    continue
            if failure and "arrangement_room" not in failure:
                if self._legacy_selection_failure(task, failure) and not predecessors:
                    self._restore_legacy_room_failure(task, failure)
                elif predecessors or self._failure_snapshot_changed(task, failure):
                    self._resume_observed_task(task)
                else:
                    continue
            if getattr(task, "arrangement_failures", None):
                self._resume_arrangement_rooms(task)

    def _prepare_manual_maintenance(self, info):
        """先执行完提前跑单、原班恢复及换人，再暂停或停服。"""
        windows = [
            task
            for task in self.tasks
            if task.type in MAINTENANCE_TASK_TYPES
            and task.maintenance_info.announcement_id == info.announcement_id
        ]
        if not windows:
            return True
        if not any(
            getattr(task, "maintenance_preparation_pending", False) for task in windows
        ):
            scheduling(self.tasks, op_data=self.op_data)
        pending = any(
            getattr(task, "maintenance_start", None) == info.start
            or task.type == TaskTypes.SWAP_SUPPORT
            and getattr(task, "advance_support_swap", False)
            and task.time <= info.start
            for task in self.tasks
        )
        has_backup = info.update_type == "major" and any(
            backup.uses_major_maintenance_condition
            for backup in getattr(self.op_data, "backup_plans", ())
        )
        if has_backup:
            for task in windows:
                task.maintenance_preparation_pending = True
            self.backup_plan_solver()
            selection = self._evaluate_backup_selection()
            pending = pending or (
                selection.conditions != self.op_data.plan_condition
                or selection.group_id != self.op_data.backup_group
                or getattr(self, "maintenance_entry_pending", False)
                or any(
                    getattr(task, "backup_shift_active", False)
                    or task.meta_data == "副表内存收敛"
                    or getattr(task, "group_shift_expected", {})
                    or getattr(task, "maintenance_replacement_run", False)
                    or getattr(task, "maintenance_advance_before_backup", False)
                    for task in self.tasks
                )
            )
        for task in windows:
            task.maintenance_preparation_pending = bool(pending)
        return not pending

    def _defer_mastery_start_for_backup(self):
        """待开始的专精保留原任务，等待副表实际换人完成。"""
        task = self.task
        if (
            not config.conf.mastery_enabled
            or task is None
            or task.type != TaskTypes.SKILL_UPGRADE
            or getattr(task, "plan_key", None) is None
        ):
            return
        predecessors = tuple(
            pending
            for pending in [*self.tasks, *getattr(self, "waiting_group_shifts", ())]
            if pending.meta_data == "副表内存收敛" and pending.plan
        )
        if not predecessors:
            return
        from arknights_mower.utils.mastery_db import get_plan_by_id

        try:
            plan = get_plan_by_id(int(task.plan_key))
        except (TypeError, ValueError):
            return
        if plan is None or plan["status"] != "idle":
            return
        task.mastery_backup_predecessors = tuple(
            {
                id(previous): previous
                for previous in (
                    *getattr(task, "mastery_backup_predecessors", ()),
                    *predecessors,
                )
            }.values()
        )
        scheduling(self.tasks, op_data=self.op_data)
        self.task = self.find_next_task()
        if self.task is not None and self.task.time > datetime.now():
            self.task = None

    def run(self) -> None:
        """
        :param clue_collect: bool, 是否收取线索
        """

        if config.stop_mower.is_set():
            raise MowerExit
        from arknights_mower.solvers.mastery_reader import (
            discard_completed_mastery_tasks,
        )

        discard_completed_mastery_tasks(self)
        self._register_network_wait_observer()
        if config.maintenance_recheck.is_set():
            return
        self._discard_legacy_mood_control_tasks()
        if any(
            task.type in MAINTENANCE_TASK_TYPES
            and task.maintenance_info.active_at(datetime.now())
            and not getattr(task, "maintenance_preparation_pending", False)
            for task in self.tasks
        ):
            config.maintenance_recheck.set()
            return
        self.error = False
        from arknights_mower.utils.backup_group_tasks import (
            filter_held_returns,
            sync_group_tasks,
        )

        sync_group_tasks(self)
        filter_held_returns(self.op_data, self.tasks)
        self._refresh_observed_recovery_tasks()
        sync_replacement_checks(self)
        self._resume_failed_tasks()
        self._card_moods_scanned_this_run = False
        self._workshop_card_moods_scanned_this_run = False
        self.handle_error(True)
        self._emergency_filter_tasks()
        self._schedule_maintenance_backup_check()

        while True:
            if config.stop_mower.is_set():
                raise MowerExit
            discard_completed_mastery_tasks(self)
            if config.maintenance_recheck.is_set():
                return
            self._sync_run_order_tasks()
            if any(getattr(task, "execution_failure", None) for task in self.tasks):
                self._queue_missing_run_order_reads()
            self._resume_waiting_group_shifts()
            self._fill_empty_dorms()
            reconcile_run_order_network(self.tasks, config.conf)
            scheduling(self.tasks, op_data=getattr(self, "op_data", None))
            self.task = self.find_next_task()
            if self.task is None:
                break
            reschedule_time = (self.task.time - datetime.now()).total_seconds()
            if reschedule_time > 300:
                self.task = None
                break
            if reschedule_time <= 0:
                break
            logger.info(f"出现任务调度情况休息{reschedule_time}秒等待下一个任务开始")
            # 休眠可能被新增任务唤醒；返回后重新排序、选择并检查到期时间。
            self._idle_sleep(reschedule_time)
        if self.task is not None and self.task.type in MAINTENANCE_TASK_TYPES:
            config.maintenance_recheck.set()
            return
        if config.maintenance_recheck.is_set():
            return
        if self.party_time is not None and self.party_time < datetime.now():
            self.party_time = None
        if self.free_clue is not None and self.free_clue != get_server_weekday():
            self.free_clue = None
        if self.credit_fight is not None and self.credit_fight != get_server_weekday():
            self.credit_fight = None
        self.todo_task = False
        self.collect_notification = False
        self.planned = False
        if self.op_data is None or self.op_data.operators is None:
            self.initialize_operators()
        if not self._product_switching_enabled():
            self._discard_product_switches()
        self.op_data.correct_dorm(group_transitions=self._pending_group_transitions())
        if not getattr(self, "defer_backup_plan_until_mood_read", False):
            self.backup_plan_solver()
            # 首次启动先随心情读取刷新实际产物；恢复缓存后也以实际状态为准。
            if not self._emergency_frozen():
                self.queue_product_switches()
        self._defer_mastery_start_for_backup()
        logMsg = "||".join([str(t) for t in self.tasks])
        logger.debug("当前任务: " + logMsg)
        save_log(logMsg, "{}" if not self.task else str(self.task), level="INFO")
        if config.maintenance_recheck.is_set():
            return
        dispatched_task = self.task
        try:
            with run_order_network_scope(self):
                return super().run()
        finally:
            if (
                dispatched_task is not None
                and not getattr(dispatched_task, "run_order_restore_pending", False)
                and not any(task is dispatched_task for task in self.tasks)
            ):
                finish_run_order_network(dispatched_task, getattr(self, "recog", None))

    def _fill_empty_dorms(self, *, primary_planned=False):
        """统一空床入口：日常规划和调度前均检查，不等待五分钟空档或跑单延期事件。"""
        op_data = getattr(self, "op_data", None)
        if (
            self._emergency_frozen()
            or op_data is None
            or self._initial_mood_read_pending()
            or getattr(self, "_initial_staffing_pending", False)
        ):
            return False
        due_fills = [
            task
            for task in task_view(self.tasks, TaskScope.REPLAN)
            if task.type == TaskTypes.FILL_DORM
            and task.time <= datetime.now()
            and not getattr(task, "arrangement_retry_room", None)
            and not getattr(task, "dorm_recovery_restore", [])
            and not getattr(task, "product_shift_locked", False)
            and not getattr(task, "backup_shift_active", False)
            and not getattr(task, "strict_mood_limit", False)
            and set(task.plan) == set(getattr(task, "dorm_fill_plan", task.plan))
        ]
        due_fill_ids = {id(task) for task in due_fills}
        if not due_fills and not vacant_dorm_slots(op_data):
            return False
        if not primary_planned:
            if any(
                task.type
                in (
                    TaskTypes.SHIFT_OFF,
                    TaskTypes.EXHAUST_OFF,
                )
                or task.type == TaskTypes.FILL_DORM
                and id(task) not in due_fill_ids
                or task.time <= datetime.now()
                and task.type
                in (
                    TaskTypes.SHIFT_ON,
                    TaskTypes.FIAMMETTA,
                    TaskTypes.SELF_CORRECTION,
                    TaskTypes.RE_ORDER,
                )
                or task.type == TaskTypes.NOT_SPECIFIC
                and any(room.startswith("dorm") for room in task.plan)
                for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            ):
                return False
            # 延期补位到期后先释放其预约，给新出现的主班轮休需求让床。
            self.tasks[:] = [
                task for task in self.tasks if id(task) not in due_fill_ids
            ]
            _, reserved_slots, _, _ = self._dorm_recovery_reservations(self.tasks)
            if not due_fills and not vacant_dorm_slots(op_data, reserved_slots):
                return False
            superseded = False
            try:
                if not self._plan_primary_recovery():
                    return False
                if any(
                    task.time <= datetime.now()
                    and (
                        task.type in (TaskTypes.SHIFT_ON, TaskTypes.SHIFT_OFF)
                        or any(room.startswith("dorm") for room in task.plan)
                    )
                    for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
                ):
                    superseded = True
                    return False
            finally:
                if not superseded:
                    self.tasks.extend(
                        task
                        for task in due_fills
                        if not any(queued is task for queued in self.tasks)
                    )
            if due_fills:
                return False
        had_tasks = len(self.tasks)
        _, _, reserved_names, reserved_slots = self._dorm_recovery_reservations(
            self.tasks
        )
        try_add_release_dorm(
            {},
            None,
            op_data,
            self.tasks,
            empty_only=True,
            reserved_names=reserved_names,
            reserved_slots=reserved_slots,
        )
        return len(self.tasks) > had_tasks

    def scene(self) -> int:
        scene = super().scene()
        if reminder := getattr(self, "_monthly_card_reminder", None):
            reminder.observe(scene, self.recog)
        return scene

    def transition(self) -> None:
        if "_order_return_unresolved" in self.__dict__:
            self._return_after_order_countdown()
            return
        if getattr(self, "_recycling_pending", None):
            if (
                self._recycling_pending.get("recorded")
                or self.scene() == Scene.MATERIEL
            ):
                self._finish_recycling_collection()
                return
            self._recycling_pending = None
        if (scene := self.scene()) == Scene.INFRA_MAIN:
            return self.infra_main()
        elif scene == Scene.INFRA_TODOLIST:
            return self.todo_list()
        elif scene == Scene.RIIC_OPERATOR_SELECT:
            self.tap_element("confirm_blue")
        elif scene in self.waiting_scene:
            self.waiting_solver()
        else:
            if scene in CLUE_RECEIPT_SCENES:
                pending = [
                    task
                    for task in self.tasks
                    if getattr(task, "clue_receipt_pending", False)
                    and getattr(task, "execution_failure", None)
                ]
                if pending:
                    observation = self._clue_receipt_observation()
                    for task in pending:
                        self._resume_clue_receipt(task, observation)
            self.scene_graph_navigation(Scene.INFRA_MAIN)
            self.last_room = ""
            logger.debug("重设上次房间为空")

    def overtake_room(self):
        request_names = list(
            getattr(self.task, "coordination_request_names", ())
            or self.task.meta_data.split(",")
        )
        if not request_names:
            return
        candidates = list(
            dict.fromkeys(
                member
                for name in request_names
                for op in [self.op_data.operators[name]]
                for member in (
                    self.op_data.shift_group_members(op.group) if op.group else [name]
                )
            )
        )
        if getattr(
            self.task, "ordinary_coordination", False
        ) and not self._ordinary_coordination_needed(request_names):
            return
        logger.debug(f"更新下班小组信息为{candidates}")
        resting_members = [
            self.op_data.operators[name]
            for name in candidates
            if not self.op_data.operators[name].room.startswith("dorm")
            and not self.op_data.operators[name].workaholic
            and (
                not self.op_data.operators[name].multi_group
                or self.op_data.operators[name].shift_group
                in self.op_data.shift_request_groups(request_names)
                or name in request_names
                and self.op_data.operators[name].independent_rest
            )
        ]
        if resting_members and all(op.is_resting() for op in resting_members):
            logger.info(f"{self.task.meta_data} 已完成用尽下班，继续正常规划")
            return
        if self._has_pending_exhausted_shift(candidates, request_names=request_names):
            logger.debug("用尽下班已有完整待执行恢复安排：%s", candidates)
            return
        support = next(
            (
                pending
                for pending in self.tasks
                if pending is not self.task
                and getattr(pending, "exhaust_support", False)
                and set(getattr(pending, "coordination_request_names", ()))
                & set(candidates)
            ),
            None,
        )
        if support is not None:
            if not any(queued is self.task for queued in self.tasks):
                self.tasks.append(self.task)
            self.task.coordination_request_names = list(request_names)
            self._retain_failed_task(
                self.task, "等待已排定的替班交接", list(support.plan), dependency=True
            )
            self.skip()
            return
        # 在candidate 中，计算出需要的high free 和 Low free 数量
        # 只计算无法直接接管的主力床位。低优、替班和临时休息干员会让床，
        # 不能在这里阻止整个大组尝试下班。
        current_resting = self.op_data.active_high_resting_count()
        plan = {}
        self.get_resting_plan(
            candidates, [], plan, current_resting, request_names=request_names
        )
        if len(plan.items()) > 0:
            re_order_dorm_plan = self._reorder_dorm_recovery(plan)
            if re_order_dorm_plan:
                logger.debug(f"合并宿舍任务{re_order_dorm_plan}")
                _merge_dorm_arrangement(plan, re_order_dorm_plan)
            task = SchedulerTask(
                datetime.now(), task_plan=plan, task_type=TaskTypes.SHIFT_OFF
            )
            if getattr(self.task, "ordinary_coordination", False):
                task.ordinary_coordination = True
                task.coordination_request_names = list(request_names)
            from arknights_mower.utils.urgent_recovery import PENDING_FIELDS

            for field in PENDING_FIELDS:
                if hasattr(self.task, field):
                    setattr(task, field, copy.deepcopy(getattr(self.task, field)))
            if hasattr(self.task, "backup_group_request"):
                task.backup_group_request = self.task.backup_group_request
            self.tasks.append(task)
        else:
            support = self._plan_exhaust_support(
                candidates,
                urgent=not getattr(self.task, "ordinary_coordination", False),
                request_names=request_names,
            )
            if support:
                self._log_arrangement("用尽下班优先协调替班和床位", plan=support)
                support_task = SchedulerTask(
                    task_plan=support, task_type=TaskTypes.SELF_CORRECTION
                )
                support_task.exhaust_support = True
                if hasattr(self.task, "backup_group_request"):
                    support_task.backup_group_request = self.task.backup_group_request
                support_task.ordinary_coordination = getattr(
                    self.task, "ordinary_coordination", False
                )
                self.tasks.append(support_task)
                support_task.coordination_request_names = list(request_names)
                if not support_task.ordinary_coordination:
                    from arknights_mower.utils.urgent_recovery import (
                        prepare_urgent_support,
                    )

                    prepare_urgent_support(self.op_data, support_task, request_names)
                    if hasattr(support_task, "urgent_recovery_request_names"):
                        self.task.urgent_recovery_request_names = list(
                            support_task.urgent_recovery_request_names
                        )
                # 前置安排完成后才释放原请求，不重建其任务时刻。
                if not any(queued is self.task for queued in self.tasks):
                    self.tasks.append(self.task)
                self.task.coordination_request_names = list(request_names)
                self._retain_failed_task(
                    self.task, "等待替班交接完成", list(support), dependency=True
                )
            else:
                msg = f"无法完成 {self.task.meta_data} 的排班：没有同时满足替班和床位的方案"
                logger.warning(msg)
                self.task.coordination_request_names = list(request_names)
                if not any(queued is self.task for queued in self.tasks):
                    self.tasks.append(self.task)
                self._retain_failed_task(self.task, msg, [])
            self.skip()

    def _has_pending_exhausted_shift(self, candidates, *, request_names=None):
        """A concrete off-shift task covers every recovery-requiring member."""
        request_names = candidates if request_names is None else request_names
        members = [
            self.op_data.operators[name]
            for name in candidates
            if not self.op_data.operators[name].room.startswith("dorm")
            and not self.op_data.operators[name].workaholic
            and (
                not self.op_data.operators[name].multi_group
                or self.op_data.operators[name].shift_group
                in self.op_data.shift_request_groups(request_names)
                or name in request_names
                and self.op_data.operators[name].independent_rest
            )
        ]
        if not members:
            return False
        for task in self.tasks:
            if task.type != TaskTypes.SHIFT_OFF:
                continue
            resting = {
                name
                for room, names in task.plan.items()
                if room.startswith("dorm")
                for name in names
                if name not in ("", "Current", "Free")
            }
            working = {
                name
                for room, names in task.plan.items()
                if not room.startswith("dorm")
                for name in names
            }
            for member in members:
                if not member.is_resting():
                    continue
                target = task.plan.get(member.current_room)
                if target is None or (
                    member.current_index >= 0
                    and target[member.current_index : member.current_index + 1]
                    in (["Current"], [member.name])
                ):
                    resting.add(member.name)
            resting.difference_update(working)
            if all(member.name in resting for member in members):
                return True
        return False

    def _coordination_admission_plan(self, data, candidates, *, request_names=None):
        request_names = list(candidates if request_names is None else request_names)
        candidates = list(
            dict.fromkeys(
                [
                    *candidates,
                    *(
                        name
                        for group in data.shift_request_groups(request_names)
                        for name in data.shift_group_members(group)
                    ),
                ]
            )
        )
        simulation = copy.copy(self)
        simulation.op_data = data.project_arrangements([])
        simulation._coordination_projection = True
        simulation.tasks = [
            copy.deepcopy(task)
            for task in self.tasks
            if task is not getattr(self, "task", None)
        ]
        result = {}
        simulation.get_resting_plan(
            list(candidates),
            [],
            result,
            data.active_high_resting_count(),
            request_names=request_names,
        )
        if not result:
            return None
        reorder = simulation._reorder_dorm_recovery(result)
        if reorder:
            _merge_dorm_arrangement(result, reorder)
        return result

    def _coordination_admission(self, data, candidates, *, request_names=None):
        result = self._coordination_admission_plan(
            data, candidates, request_names=request_names
        )
        return data.project_arrangements([result]) if result else None

    def _queue_ordinary_coordination_admission(self, task):
        """召回已确认后接续具名下班安排，由实际入宿登记恢复保护。"""
        saved = getattr(task, "coordination_admission_plan", None)
        if not saved or not getattr(task, "ordinary_coordination", False):
            return
        names = list(getattr(task, "urgent_recovery_request_names", ()))
        request_names = list(getattr(task, "coordination_request_names", ()) or names)
        if not names or not getattr(task, "urgent_recovery_support_names", ()):
            task.__dict__.pop("coordination_admission_plan", None)
            return
        if any(
            pending.type == TaskTypes.SHIFT_OFF
            and set(getattr(pending, "urgent_recovery_request_names", ())) == set(names)
            for pending in self.tasks
        ):
            task.__dict__.pop("coordination_admission_plan", None)
            return
        plan = (
            self._coordination_admission_plan(
                self.op_data, names, request_names=request_names
            )
            or saved
        )
        departure = SchedulerTask(
            time=task.time, task_plan=plan, task_type=TaskTypes.SHIFT_OFF
        )
        departure.ordinary_coordination = True
        departure.coordination_request_names = request_names
        from arknights_mower.utils.urgent_recovery import PENDING_FIELDS

        for field in PENDING_FIELDS:
            if hasattr(task, field):
                setattr(departure, field, copy.deepcopy(getattr(task, field)))
        self.tasks.append(departure)
        task.__dict__.pop("coordination_admission_plan", None)

    def _coordination_support_valid(
        self, plan, candidates, *, request_names=None, now=None
    ):
        from arknights_mower.utils.replacement_coordination import (
            coordination_reservations,
            recall_can_sustain,
        )

        data = self.op_data
        if now is not None:
            # 当前实际阵容先推进到提交时点，之后才投影前置交接和受援入宿。
            data = data.project_arrangements([], now=now)
        request_names = list(candidates if request_names is None else request_names)
        conditions = getattr(self.task, "backup_shift_conditions", None)
        if conditions is not None and list(conditions) != data.plan_condition:
            data = data.project_arrangements([])
            if data.swap_plan(conditions, refresh=True):
                return False
        reserved, slots = coordination_reservations(
            data, self.tasks, getattr(self, "task", None)
        )
        if any(
            name != "Current" and ((room, index) in slots or name in reserved)
            for room, row in plan.items()
            for index, name in enumerate(row)
        ):
            return False
        from arknights_mower.utils.backup_group_tasks import (
            forced_group_cover_reservations,
        )

        forced_names, forced_slots = forced_group_cover_reservations(data)
        if any(
            name != "Current"
            and ((room, index) in forced_slots or name in forced_names)
            and (
                (actual := data.get_current_operator(room, index)) is None
                or actual.name != name
            )
            for room, row in plan.items()
            for index, name in enumerate(row)
        ):
            return False
        supported = data.project_arrangements([plan])
        admitted = self._coordination_admission(
            supported, candidates, request_names=request_names
        )
        if admitted is None:
            return False
        if any(
            (
                admitted.operators[name].current_room,
                admitted.operators[name].current_index,
            )
            != (data.operators[name].current_room, data.operators[name].current_index)
            for name in forced_names
        ):
            return False
        recalled = {
            op.name
            for op in data.operators.values()
            if op.is_high()
            and not op.room.startswith("dorm")
            and admitted.operators[op.name].is_working()
            and (
                op.is_resting()
                or op.is_working()
                and (op.current_room, op.current_index) != (op.room, op.index)
                and (
                    admitted.operators[op.name].current_room,
                    admitted.operators[op.name].current_index,
                )
                == (op.room, op.index)
            )
        }
        if not recalled:
            return True
        urgent = getattr(self.task, "exhaust_support", False) and not getattr(
            self.task, "ordinary_coordination", False
        )
        now = getattr(data, "_projection_now", None) or datetime.now()
        return recall_can_sustain(
            data,
            admitted,
            recalled,
            candidates,
            urgent=urgent,
            now=now,
            request_names=request_names,
            reserved_names=reserved,
            reserved_slots=slots,
        )

    def _plan_exhaust_support(self, candidates, *, urgent=False, request_names=None):
        from arknights_mower.utils.exhaust_replacement import plan_exhaust_support
        from arknights_mower.utils.replacement_coordination import (
            coordination_reservations,
        )
        from arknights_mower.utils.urgent_recovery import urgent_support_blocked

        excluded = self._protected_facility_names()
        request_names = list(candidates if request_names is None else request_names)
        request_names = [name for name in request_names if name not in excluded]
        candidates = list(
            dict.fromkeys(
                [
                    *(name for name in candidates if name not in excluded),
                    *(
                        name
                        for group in self.op_data.shift_request_groups(request_names)
                        for name in self.op_data.shift_group_members(group)
                        if name not in excluded
                    ),
                ]
            )
        )
        recall_blocked = urgent_support_blocked(
            self.op_data, candidates, self.tasks, getattr(self, "task", None)
        )

        def can_rest(data):
            admitted = self._coordination_admission(
                data, candidates, request_names=request_names
            )
            if admitted is None:
                return None
            from arknights_mower.utils.replacement_coordination import (
                recall_can_sustain,
            )

            recalled = {
                op.name
                for op in self.op_data.operators.values()
                if op.is_high()
                and not op.room.startswith("dorm")
                and admitted.operators[op.name].is_working()
                and (
                    op.is_resting()
                    or op.is_working()
                    and (op.current_room, op.current_index) != (op.room, op.index)
                    and (
                        admitted.operators[op.name].current_room,
                        admitted.operators[op.name].current_index,
                    )
                    == (op.room, op.index)
                )
            }
            if not recalled:
                return True
            now = getattr(self.op_data, "_projection_now", None) or datetime.now()
            return recall_can_sustain(
                self.op_data,
                admitted,
                recalled,
                candidates,
                urgent=urgent,
                now=now,
                request_names=request_names,
                reserved_names=protected,
                reserved_slots=slots,
            )

        protected, slots = coordination_reservations(
            self.op_data, self.tasks, getattr(self, "task", None)
        )
        protected.update(self._protected_facility_names(include_configured=False))
        fia, _ = self.check_fia()
        return plan_exhaust_support(
            self.op_data,
            candidates,
            can_rest,
            _is_mastery_busy,
            protected,
            fia,
            slots,
            urgent=urgent,
            recall_blocked=recall_blocked,
            recall_viability=can_rest,
            excluded_names=excluded,
            request_names=request_names,
        )

    def _schedule_group_coordination(self, candidates):
        """普通互斥继续等待；仅完整可执行的交接进入安排队列。"""
        if getattr(self, "_coordination_projection", False):
            return
        names = list(dict.fromkeys(candidates))
        if any(
            getattr(task, "exhaust_support", False)
            and set(getattr(task, "coordination_request_names", ())) == set(names)
            for task in self.tasks
        ):
            return
        support = self._plan_exhaust_support(names, request_names=names)
        if not support:
            return
        task = SchedulerTask(task_plan=support, task_type=TaskTypes.SELF_CORRECTION)
        task.exhaust_support = True
        task.coordination_request_names = names
        task.ordinary_coordination = True
        self.tasks.append(task)

    def _discard_legacy_mood_control_tasks(self):
        """撤销旧版未开始的提前下班和预测唤醒，保留已开始的执行责任。"""
        removed = {
            id(task)
            for task in self.tasks
            if (
                getattr(task, "mood_control_event", None)
                or getattr(task, "mood_control_evidence", None)
            )
            and not task.retains_execution
            and not getattr(task, "mood_physical_started", False)
        }
        if not removed:
            return
        self.tasks[:] = [task for task in self.tasks if id(task) not in removed]
        if id(getattr(self, "task", None)) in removed:
            self.task = None
        self.planned = False

    def _discard_legacy_ordinary_requests(self):
        """旧版普通互斥占位请求回归普通规划，实际换班和用尽任务保留。"""
        previous = len(self.tasks)
        self.tasks[:] = [
            task
            for task in self.tasks
            if not (
                task.type == TaskTypes.EXHAUST_OFF
                and getattr(task, "ordinary_coordination", False)
                and not task.plan
            )
        ]
        if len(self.tasks) != previous and not any(
            task.type == TaskTypes.NOT_SPECIFIC
            and not task.plan
            and not task.meta_data
            and task.time <= datetime.now()
            for task in self.tasks
        ):
            self.tasks.append(SchedulerTask())

    def _ordinary_coordination_needed(self, names):
        from arknights_mower.utils.backup_group_tasks import forced_work_groups

        working = forced_work_groups(self.op_data)
        protected = self._protected_facility_names()
        request_groups = set(self.op_data.shift_request_groups(names))
        names = list(
            dict.fromkeys(
                [
                    *names,
                    *(
                        name
                        for group in request_groups
                        for name in self.op_data.shift_group_members(group)
                    ),
                ]
            )
        )
        for name in names:
            op = self.op_data.operators.get(name)
            if (
                op is None
                or not op.is_high()
                or op.multi_group
                and not op.independent_rest
                and not op.shift_group
                or op.group
                and not self.op_data.is_group_shift_anchor(op)
                or op.group
                and op.group not in request_groups
                or op.is_resting()
                or self.op_data.is_standby(name)
                or op.current_room in ("factory", "train")
                or op.room in ("factory", "train")
                or name in protected
                or name in self.op_data.reserved_product_replacements
                or name in self.op_data.exhaust_agent
                or op.group in self.op_data.exhaust_group
                or op.group in working
                or self._resting_tier(op) == RestingTier.EXCLUDED
            ):
                continue
            mood = dorm_candidate_mood(
                self.op_data,
                name,
                getattr(self.op_data, "_projection_now", None) or datetime.now(),
            )
            if mood is None or mood > self.op_data.resting_mood_threshold(op):
                continue
            if mood < op.upper_limit and (
                self.op_data.custom_mood_limits(name) is not None
                or op.upper_limit - mood >= 2
            ):
                return True
        return False

    def _prepare_ordinary_departure(self, task):
        """普通下班先应用真实状态触发的副表，再复核每个请求。"""
        if (
            task.type != TaskTypes.SHIFT_OFF
            or task.retains_execution
            or getattr(task, "mood_physical_started", False)
            or not getattr(task, "ordinary_coordination", False)
            or getattr(task, "backup_shift_active", False)
            or getattr(task, "group_shift_expected", {})
            or getattr(task, "product_shift_locked", False)
            or getattr(task, "backup_explicit_slots", ())
        ):
            return True
        if not getattr(task, "backup_shift_active", False):
            self.backup_plan_solver()
        if not any(queued is task for queued in self.tasks):
            return False
        requests = {}
        for name in task.coordination_request_names:
            op = self.op_data.operators.get(name)
            if op is None:
                return False
            key = ("group", op.group) if op.group else ("operator", name)
            requests[key] = self.op_data.groups[op.group] if op.group else [name]
        return bool(requests) and all(
            self._ordinary_coordination_needed(names) for names in requests.values()
        )

    def _coordination_commit_started(self, task):
        """仅提交标记或初始位置到已确认原岗的变化证明支援已经开始。"""
        if getattr(task, "mood_physical_started", False) or getattr(
            task, "urgent_recovery_started", False
        ):
            return True
        initial = getattr(task, "urgent_recovery_initial_positions", {})
        return any(
            name in initial
            and (op := self.op_data.operators.get(name)) is not None
            and initial[name] != (op.current_room, op.current_index)
            and (op.current_room, op.current_index) == (op.room, op.index)
            for name in getattr(task, "urgent_recovery_support_names", ())
        )

    def _validate_coordination_commit(self):
        """首次提交前复核完整支援；已确认的部分交接继续按原剩余安排恢复。"""
        task = self.task
        coordination = task is not None and getattr(task, "exhaust_support", False)
        if coordination and self._coordination_commit_started(task):
            return
        if coordination:
            names = getattr(task, "coordination_request_names", ())
            if not names or not self._coordination_support_valid(
                task.plan, names, now=datetime.now()
            ):
                task.coordination_commit_pending = True
                raise ProductSwitchDeferred(
                    "首次提交前替班交接条件已经变化", rooms=tuple(task.plan)
                )
        validator = self
        if coordination and task.retains_execution:
            # 失败保留不证明已经提交；只读副本重查原有进房心情门槛。
            validator = copy.copy(self)
            validator.task = copy.copy(task)
            validator.task.execution_retained = False
            validator.task.__dict__.pop("execution_failure", None)
        try:
            validator._validate_calculated_arrangement()
        except MoodArrangementChanged as error:
            if not coordination:
                raise
            task.coordination_commit_pending = True
            raise ProductSwitchDeferred(str(error), rooms=tuple(task.plan)) from error

    def _validate_calculated_arrangement(self):
        """首次提交前用正常进房读数复核本次计算心情派生的条件。"""
        task = self.task
        if (
            not getattr(self.op_data, "mood_calculation_enabled", False)
            or task is None
            or task.retains_execution
            or getattr(task, "mood_physical_started", False)
            or getattr(task, "backup_shift_active", False)
            or getattr(task, "backup_explicit_slots", ())
            or getattr(task, "product_shift_locked", False)
            or getattr(task, "dorm_recovery_restore", ())
            or getattr(task, "run_order_restore_pending", False)
        ):
            return
        from arknights_mower.utils.backup_group_tasks import forced_work_return
        from arknights_mower.utils.calculated_mood import sync_model
        from arknights_mower.utils.recovery_execution import (
            arrangement_recovery_required_members,
        )

        now = datetime.now()
        sync_model(self.op_data, now)
        if task.type == TaskTypes.RELEASE_DORM:
            for name in task.release_dorm_targets():
                op = self.op_data.operators.get(name)
                target = getattr(task, "mood_limit", None)
                if target is None and op is not None:
                    target = op.upper_limit
                mood = self.op_data.calculated_mood(name, now)
                if mood is None or target is None or mood < target:
                    raise MoodArrangementChanged("进房心情未达到离宿目标")
            return
        if task.type not in (
            TaskTypes.SHIFT_ON,
            TaskTypes.SHIFT_OFF,
            TaskTypes.EXHAUST_OFF,
            TaskTypes.SELF_CORRECTION,
        ):
            return
        if task.type == TaskTypes.SHIFT_OFF and getattr(
            task, "ordinary_coordination", False
        ):
            groups = []
            for name in task.coordination_request_names:
                op = self.op_data.operators.get(name)
                if op is not None:
                    groups.append(self.op_data.groups[op.group] if op.group else [name])
            if not groups or not all(
                self._ordinary_coordination_needed(names) for names in groups
            ):
                raise MoodArrangementChanged("心情观测已改变普通下班条件")
        for room, names in task.plan.items():
            if room.startswith("dorm"):
                continue
            for index, name in enumerate(names):
                op = self.op_data.operators.get(name)
                if op is None or (op.current_room, op.current_index) == (room, index):
                    continue
                if (op.room, op.index) == (room, index) and forced_work_return(
                    self.op_data, name
                ):
                    continue
                required = arrangement_recovery_required_members(
                    self.op_data,
                    name,
                    now=now,
                    require_mood_limit=getattr(task, "mood_limit_return_name", None)
                    != name,
                    bypass_automatic_wait=task.type == TaskTypes.EXHAUST_OFF
                    or getattr(task, "exhaust_support", False),
                )
                if any(
                    (mood := self.op_data.calculated_mood(member, now)) is None
                    or mood < self.op_data.operators[member].upper_limit
                    for member in required
                ):
                    raise MoodArrangementChanged("进房心情未达到本轮回班要求")
                slots = self.op_data.plan.get(room, [])
                primary = (
                    self.op_data.operators.get(slots[index].agent)
                    if index < len(slots)
                    else None
                )
                if self.op_data.replacement_exhausted(name, now, operator=primary):
                    raise MoodArrangementChanged("选人期间替班心情跨过下限")

    def _filter_ordinary_exhaust_departures(self, task, intent, effective):
        """用尽副表取消普通组下班时，保留其他组及明确副表安排。"""
        if (
            not getattr(task, "ordinary_coordination", False)
            or getattr(task, "backup_shift_active", False)
            or getattr(task, "group_shift_expected", {})
            or getattr(task, "product_shift_locked", False)
        ):
            return False
        blocked, kept = set(), set()
        blocked_requests, blocked_groups = set(), set()
        explicit = set(getattr(task, "backup_explicit_slots", ()))
        explicit_names = set()
        for room, index in explicit:
            slots = self.op_data.plan.get(room, [])
            if index < len(slots):
                explicit_names.add(slots[index].agent)
            row = intent.get(room, [])
            if index < len(row):
                explicit_names.add(row[index])
        for name in task.coordination_request_names:
            op = effective.operators.get(name)
            if op is None:
                continue
            members = (
                set(effective.shift_group_members(op.group)) if op.group else {name}
            )
            if members & explicit_names:
                kept.update(members)
            elif name in effective.exhaust_agent or op.group in effective.exhaust_group:
                blocked.update(members)
                blocked_requests.add(name)
                if op.group:
                    blocked_groups.add(op.group)
            else:
                kept.update(members)
        if not blocked_requests:
            return False
        remaining_transitions = self.op_data.arrangement_group_transitions(intent)
        remaining_transitions.update({group: False for group in blocked_groups})
        kept.update(
            name
            for name in blocked
            if self.op_data.operators[name].multi_group
            and self.op_data.resting_binding_groups(
                self.op_data.operators[name], remaining_transitions
            )
        )
        blocked.difference_update(kept)
        removed_covers = set()
        for room, names in list(intent.items()):
            for index, name in enumerate(names):
                if (room, index) in explicit:
                    continue
                current = self.op_data.get_current_operator(room, index)
                if (
                    current is not None
                    and current.name in blocked
                    and (current.room, current.index) == (room, index)
                    or room.startswith("dorm")
                    and name in blocked
                    and not self.op_data.operators[name].is_resting()
                ):
                    if name in self.op_data.operators and name not in blocked:
                        removed_covers.add(name)
                    names[index] = "Current"
            if all(name == "Current" for name in names):
                del intent[room]
        assigned = _assigned_operator_names(intent)
        for room, names in list(intent.items()):
            if not room.startswith("dorm"):
                continue
            for index, name in enumerate(names):
                current = self.op_data.get_current_operator(room, index)
                if (
                    name == "Free"
                    and (room, index) not in explicit
                    and current is not None
                    and current.name in removed_covers - assigned
                ):
                    names[index] = "Current"
            if all(name == "Current" for name in names):
                del intent[room]
        task.coordination_request_names = [
            name
            for name in task.coordination_request_names
            if name not in blocked_requests
        ]
        task.ordinary_exhaust_blocked_groups = (
            set(getattr(task, "ordinary_exhaust_blocked_groups", ())) | blocked_groups
        )
        task.group_shift_transitions = {
            group: resting
            for group, resting in getattr(task, "group_shift_transitions", {}).items()
            if group not in blocked_groups
        }
        return True

    def _unsubmitted_coordination(self, task):
        return (
            getattr(task, "exhaust_support", False)
            and getattr(task, "coordination_commit_pending", False)
            and not self._coordination_commit_started(task)
            and not any(
                getattr(task, flag, False)
                for flag in (
                    "backup_shift_active",
                    "backup_explicit_slots",
                    "product_shift_locked",
                    "product_switched_before_arrangement",
                )
            )
        )

    def _refresh_coordination_support(self, task):
        refresh_unsubmitted = self._unsubmitted_coordination(task) and not getattr(
            task, "execution_failure", None
        )
        if (
            not getattr(task, "exhaust_support", False)
            or self._coordination_commit_started(task)
            or getattr(task, "coordination_commit_pending", False)
            and not refresh_unsubmitted
            or getattr(task, "backup_shift_active", False)
            or getattr(task, "group_shift_expected", {})
            and not refresh_unsubmitted
        ):
            return
        names = [
            name
            for name in task.coordination_request_names
            if name in self.op_data.operators
        ]
        planner = self
        if refresh_unsubmitted:
            planner = copy.copy(self)
            planner.task = task
            planner.op_data = self.op_data.project_arrangements([], now=datetime.now())
        if (
            not names
            or getattr(task, "ordinary_coordination", False)
            and not planner._ordinary_coordination_needed(names)
        ):
            task.plan = {}
        else:
            # 只有尚未提交的支援可重建；已执行及显式承诺保留剩余安排。
            plan = planner._plan_exhaust_support(
                names,
                urgent=not getattr(task, "ordinary_coordination", False),
                request_names=names,
            )
            if refresh_unsubmitted and not plan:
                raise ProductSwitchDeferred(
                    "尚无完整可执行的替班交接", rooms=tuple(task.plan)
                )
            task.plan = plan or {}
        if refresh_unsubmitted:
            for field in (
                "group_shift_expected",
                "group_shift_transitions",
                "coordination_admission_plan",
                "coordination_commit_pending",
            ):
                task.__dict__.pop(field, None)
            task.execution_retained = False
        from arknights_mower.utils.urgent_recovery import prepare_urgent_support

        prepare_urgent_support(self.op_data, task, names)
        if not task.plan:
            task.__dict__.pop("coordination_admission_plan", None)
        if hasattr(task, "backup_shift_intent"):
            task.backup_shift_intent = copy.deepcopy(task.plan)

    def _plan_preferred_replacements(self):
        from arknights_mower.utils.replacement_coordination import (
            coordination_reservations,
            preferred_replacement_restore,
            replacement_dependencies,
        )

        protected, slots = coordination_reservations(
            self.op_data, self.tasks, getattr(self, "task", None)
        )
        protected.update(self._protected_facility_names(include_configured=False))
        for task in self.tasks:
            if task.type == TaskTypes.EXHAUST_OFF and task.time <= datetime.now():
                protected.update(
                    replacement_dependencies(self.op_data, task.meta_data.split(","))
                )
            if task.type == TaskTypes.SHIFT_OFF:
                protected.update(_assigned_operator_names(task.plan))
        plan = preferred_replacement_restore(
            self.op_data, _is_mastery_busy, protected, slots
        )
        if plan and not any(
            getattr(task, "preferred_replacement_restore", False) for task in self.tasks
        ):
            task = SchedulerTask(task_plan=plan, task_type=TaskTypes.SELF_CORRECTION)
            task.preferred_replacement_restore = True
            self.tasks.append(task)

    def handle_error(self, force=False, *, idle_deadline: datetime | None = None):
        if config.stop_mower.is_set():
            raise MowerExit
        recover_base_scene(self)
        if self.error or force:
            now = datetime.now()
            preserved_ids = retain_mastery_backup_tasks(
                self.tasks, self.__dict__.setdefault("waiting_group_shifts", [])
            )
            for task in self.tasks:
                if task.plan.keys() & getattr(task, "dorm_roommate_targets", ()):
                    preserved_ids.add(id(task))
                if getattr(task, "run_order_restore_pending", False):
                    task.prepare_run_order_restoration()
            if self._emergency_active():
                for task in self.tasks:
                    if (
                        task.type == TaskTypes.RUN_ORDER
                        and task.meta_data
                        and hasattr(task, "emergency_original_roster")
                        and task.time < now - timedelta(minutes=15)
                    ):
                        task.plan = copy.deepcopy(task.emergency_original_roster)
                        task.meta_data = ""
                        task.time = now
                        logger.warning("过期跑单停止插拔，保留原临时驻员恢复")
            # 如果没有任何时间小于当前时间的任务才生成空任务
            if (
                self.find_next_task(now) is None
                and self.find_next_task(task_type=TaskTypes.SKILL_UPGRADE) is None
            ):
                logger.debug("由于出现错误情况，生成一次空任务来执行纠错")
                self.tasks.append(SchedulerTask())
            # 普通任务超过 15 分钟时重建排班；关键预约不因别的房间失败丢失。
            preserved = {
                TaskTypes.SKILL_UPGRADE,
                TaskTypes.SWAP_SUPPORT,
                TaskTypes.REFRESH_TIME,
                TaskTypes.SWITCH_PRODUCT,
                TaskTypes.FIAMMETTA,
            }
            future_preserved = (
                {
                    TaskTypes.RUN_ORDER,
                    TaskTypes.FURNITURE,
                    TaskTypes.DEPOT,
                    TaskTypes.CLUE,
                    TaskTypes.WORKSHOP,
                }
                | MANUAL_TASK_TYPES
                | MAINTENANCE_TASK_TYPES
            )
            if any(
                t.time < now - timedelta(minutes=15)
                and t.type not in preserved
                and id(t) not in preserved_ids
                and not getattr(t, "strict_mood_limit", False)
                and not hasattr(t, "emergency_original_roster")
                and not getattr(t, "run_order_restore_pending", False)
                and not getattr(t, "group_shift_expected", {})
                and not getattr(t, "backup_shift_active", False)
                and not getattr(t, "execution_failure", None)
                and not getattr(t, "execution_retained", False)
                and not getattr(t, "replacement_check", None)
                and not getattr(t, "maintenance_preparation_pending", False)
                and getattr(t, "maintenance_start", None) is None
                for t in self.tasks
            ):
                logger.info(
                    "检测到执行超过15分钟的任务，重建普通排班并保留关键预约与未来显式任务"
                )
                self.tasks = [
                    t
                    for t in self.tasks
                    if t.type in preserved
                    or id(t) in preserved_ids
                    or getattr(t, "strict_mood_limit", False)
                    or (t.type in future_preserved and t.time > now)
                    or hasattr(t, "emergency_original_roster")
                    or getattr(t, "run_order_restore_pending", False)
                    or getattr(t, "group_shift_expected", {})
                    or getattr(t, "backup_shift_active", False)
                    or getattr(t, "execution_failure", None)
                    or getattr(t, "execution_retained", False)
                    or getattr(t, "replacement_check", None)
                    or getattr(t, "maintenance_preparation_pending", False)
                    or getattr(t, "maintenance_start", None) is not None
                ]
                # #144：清队后补立即空任务——队列只剩远期专精重检时，让下一次
                # run() 走正常 planned 分支重读心情/换班/跑单，而不是睡到远期任务开始
                logger.debug("清队后补立即空任务，下一轮走正常流程重读心情/换班/跑单")
                self.tasks.append(SchedulerTask())
        else:
            now = datetime.now()
            wake_at = now + timedelta(hours=2.5)
            if idle_deadline is not None and now < idle_deadline:
                wake_at = min(wake_at, idle_deadline)
            if self.find_next_task(wake_at) is None:
                logger.debug("%s 前没有其他可派发任务，生成空任务", wake_at)
                self.tasks.append(SchedulerTask(time=wake_at))
        return True

    def plan_fia(self):
        if getattr(self.task, "fia_return_queued", False):
            self.skip()
            return
        fia_plan, fia_room = self.check_fia()
        if fia_room is None or fia_plan is None:
            return
        self._refresh_fia_candidate_moods(fia_plan)
        configured_full = self._fia_targets_all_full(fia_plan)
        fallback = self._emergency_fia_fallback(fia_plan)
        if fallback is not None:
            self._refresh_fia_candidate_moods(fallback)
            fia_plan = self._emergency_fia_fallback(fia_plan) or []
            logger.info(
                "自动救急：配置的充能干员已满心情，按心情选择正常主班：%s",
                "、".join(f"[[operator:{name}]]" for name in fia_plan) or "暂无候选",
                extra={"log_agents": list(fia_plan)},
            )
        if self._fia_targets_all_full(fia_plan) or (not fia_plan and configured_full):
            logger.info("菲亚充能目标均已满心情，跳过本次充能")
            return
        # 肥鸭充能新模式：https://github.com/ArkMowers/arknights-mower/issues/551
        target = None
        if not config.conf.fia_fool:
            fia_threshold = config.conf.fia_threshold
            logger.info(f"菲亚防呆设计未开启，菲亚阈值为{fia_threshold}")
        else:
            fia_threshold = 0.9
            logger.info(f"菲亚防呆设计已开启，菲亚阈值为{fia_threshold}")
        for operator in fia_plan:
            data = self.op_data.operators[operator]
            operator_morale = data.current_mood()
            operator_limit = data.lower_limit
            logger.debug(f"{operator}的心情为{operator_morale}")
            if operator_morale >= 24 or operator_morale > fia_threshold * 24:
                logger.debug(f"{operator}的心情高于阈值，跳过充能")
                continue
            if data.rest_in_full and data.exhaust_require and not data.is_resting():
                logger.debug(f"{operator}为暖机干员但不在宿舍，跳过充能")
                continue
            if data.group:
                lowest = True
                for member in self.op_data.groups[data.group]:
                    if member == operator:
                        continue
                    # Lancet-2
                    if (
                        fallback is not None
                        and self.op_data.has_rest_mood_limit(member)
                        or self.op_data.operators[member].multi_group
                        or self.op_data.operators[member].room.startswith("dorm")
                        or self.op_data.operators[member].workaholic
                        and member not in fia_plan
                    ):
                        continue
                    member_morale = self.op_data.operators[member].current_mood()
                    member_limit = self.op_data.operators[member].lower_limit
                    logger.debug(f"{data.group}组内{member}的心情为{member_morale}")
                    if member_morale - member_limit < operator_morale - operator_limit:
                        lowest = False
                        logger.debug(f"{operator}的心情高于{member}，跳过充能")
                        break
                if not lowest:
                    continue
            target = operator
            break
        # 若全部跳过且关闭防呆则令目标干员为心情最低干员
        if target is None and fia_plan and not config.conf.fia_fool:
            op_mood = 24
            for op in fia_plan:
                data = self.op_data.operators[op]
                op_mood_t = data.current_mood()
                if data.rest_in_full and data.exhaust_require and not data.is_resting():
                    logger.debug(f"{operator}为暖机干员但不在宿舍，跳过充能")
                    continue
                if op_mood_t < op_mood:
                    target = op
                    op_mood = op_mood_t
        if target:
            self.tasks.append(
                SchedulerTask(
                    time=self.task.time,
                    task_type=TaskTypes.FIAMMETTA,
                    task_plan={fia_room: [target, "菲亚梅塔"]},
                    meta_data=target,
                    initial_fia=getattr(self.task, "initial_fia", False),
                )
            )
            self.tasks[-1].emergency_fia_fallback = fallback is not None
            charge = self.tasks[-1]
            operator = self.op_data.operators[target]
            if (
                not self._emergency_frozen()
                and operator.is_high()
                and not operator.room.startswith("dorm")
                and (operator.is_resting() or not operator.current_room)
            ):
                charge.fia_return_target = target
                charge.fia_return_time = self.task.time + timedelta(seconds=1)
            # 充能结束后整组立即上班
            for task in task_view(self.tasks, TaskScope.REPLAN):
                if task.type == TaskTypes.SHIFT_ON:
                    for room, operators in task.plan.items():
                        if target in operators:
                            charge.fia_return_target = target
                            charge.fia_return_time = self.task.time + timedelta(
                                seconds=1
                            )
                            task.time = charge.fia_return_time
                            self.tasks.sort(
                                key=lambda task: (
                                    bool(getattr(task, "execution_failure", None)),
                                    task.time,
                                )
                            )
                            return
        else:
            logger.info("肥鸭充能干员不足，请添加更多干员！")
            retry = SchedulerTask(
                time=self.task.time + timedelta(hours=24 * (1 - fia_threshold) / 2),
                task_type=TaskTypes.FIAMMETTA,
            )
            retry.fia_retry_after = retry.time
            self.tasks.append(retry)
            self.tasks.sort(
                key=lambda task: (
                    bool(getattr(task, "execution_failure", None)),
                    task.time,
                )
            )

    def _queue_fia_return(self):
        """原班恢复后独立保留已确认充能所要求的回班。"""
        target = getattr(self.task, "fia_return_target", None)
        if (
            not target
            or not getattr(self.task, "fia_charge_confirmed", False)
            or getattr(self.task, "fia_return_queued", False)
        ):
            return
        from arknights_mower.utils.scheduler_task import (
            _native_return,
            rebalance_closing_dorm_slots,
        )

        operator = self.op_data.operators.get(target)
        if operator is None:
            return
        members = (
            self.op_data.shift_group_members(operator.group)
            if operator.group
            else [target]
        )
        plan = {}
        projected = self.op_data.project_arrangements([])
        _native_return(projected, plan, members)
        projected.commit_group_shifts(projected.arrangement_group_transitions(plan))
        rebalance_closing_dorm_slots(projected, plan, members)
        if not plan:
            return
        task = SchedulerTask(
            time=self.task.fia_return_time,
            task_plan=plan,
            task_type=TaskTypes.SHIFT_ON,
        )
        task.fia_return_target = target
        task.fia_return_time = task.time
        task.execution_retained = True
        self.tasks.append(task)
        self.task.fia_return_queued = True
        logger.info("肥鸭充能及原班恢复完成，保留回班安排：%s", plan)

    def _prepare_fia_return(self, task):
        """充能回班不再等待普通恢复计时，明确回满要求仍须满足。"""
        target = getattr(task, "fia_return_target", None)
        if (
            not target
            or getattr(task, "mood_physical_started", False)
            or getattr(task, "group_shift_expected", {})
        ):
            return
        from arknights_mower.utils.group_recovery import (
            group_recovery_deadline,
            observed_recovery_deadline,
            recovery_mood_complete,
        )

        operator = self.op_data.operators.get(target)
        if operator is None:
            return
        now = datetime.now()
        required, deadline = (
            group_recovery_deadline(self.op_data, operator.group, now=now)
            if operator.group
            else ([target] if operator.rest_in_full else [], None)
        )
        conf = self.op_data.runtime_conf or config.conf
        capped = (
            operator.group in self.op_data.group_recovery_return_time
            and conf.group_mood_gap_max_extra_wait_hours > 0
        )
        unknown = [
            name
            for name in required
            if not recovery_mood_complete(
                self.op_data, self.op_data.operators[name], now
            )
            and observed_recovery_deadline(self.op_data, name, now) is None
            and (self.op_data.operators[name].rest_in_full or not capped)
        ]
        if unknown:
            raise GroupShiftBlocked(
                recovery_names=unknown, recovery_reason="充能回班成员的有效恢复观测"
            )
        task.time = max(
            task.fia_return_time,
            deadline
            if deadline is not None and deadline > now
            else task.fia_return_time,
        )

    def _fia_targets_all_full(self, names):
        return bool(names) and all(
            scheduling_mood_reaches(self.op_data, name, 24) for name in names
        )

    def _refresh_fia_candidate_moods(self, names):
        """挑选充能对象前补读失效缓存，同房候选只进房一次，不触发纠错或切表。"""
        if getattr(self.op_data, "mood_calculation_enabled", False):
            for name in names:
                self.op_data.calculated_mood(name)
            return
        rooms = {}
        for name in names:
            op = self.op_data.operators[name]
            room = op.current_room
            if (
                room
                and op.current_index >= 0
                and (
                    op.need_to_refresh(r=room)
                    or (op.is_working() and op.depletion_rate == 0)
                )
            ):
                rooms.setdefault(room, set()).add(op.current_index)
        for room, indexes in rooms.items():
            self.enter_room(room)
            self.get_agent_from_room(room, sorted(indexes))
            self.back()

    def _queue_initial_fia(self):
        """初始化实测满心情后优先充能，沿用目标筛选与原班恢复。"""
        if getattr(self, "_initial_fia_checked", False):
            return False
        self._initial_fia_checked = True
        for task in self.tasks:
            if getattr(task, "initial_fia", False):
                task.initial_fia = False
        targets, room = self.check_fia()
        fia = self.op_data.operators.get("菲亚梅塔")
        if (
            not targets
            or not room
            or fia is None
            or (dorm_candidate_mood(self.op_data, fia.name) or 0) < 24
            or not fia.current_room.startswith("dorm")
            or fia.current_index < 0
        ):
            return False
        existing = [task for task in self.tasks if task.type == TaskTypes.FIAMMETTA]
        if any(task.retains_execution for task in existing):
            return False
        # 未完成的充能或回岗沿用原任务；防呆延期不在初始化时强行重试。
        if any(
            getattr(task, "fia_retry_after", datetime.min) > datetime.now()
            for task in existing
        ):
            return False
        if any(task.plan for task in existing):
            for task in existing:
                if task.plan and task.time <= datetime.now():
                    task.initial_fia = True
            return any(getattr(task, "initial_fia", False) for task in existing)
        task = existing[0] if existing else SchedulerTask(task_type=TaskTypes.FIAMMETTA)
        task.time = datetime.now()
        task.initial_fia = True
        self.tasks[:] = [
            queued for queued in self.tasks if queued.type != TaskTypes.FIAMMETTA
        ]
        self.tasks.append(task)
        logger.info("初始化确认菲亚梅塔心情已满，优先执行充能任务")
        return True

    def _refresh_fiammetta_task(self, ready_at):
        """读到新的回满时间后更新充能预约，保留正在执行的充能／回岗任务。"""
        if self._initial_mood_read_pending():
            return
        if ready_at is None:
            self.tasks[:] = [
                task
                for task in self.tasks
                if task.retains_execution
                or task.type != TaskTypes.FIAMMETTA
                or task.plan
                or task is self.task
            ]
            return
        for task in task_view(self.tasks, TaskScope.REPLAN):
            if (
                task.type == TaskTypes.FIAMMETTA
                and not task.plan
                and task is not self.task
            ):
                task.time = max(ready_at, getattr(task, "fia_retry_after", ready_at))

    def craft_material(self):
        first_task = self.task
        if (
            first_task.type == TaskTypes.WORKSHOP
            and not first_task.plan
            and self._read_missing_workshop_moods(refresh=True)
        ):
            try_workshop_tasks(self.op_data, self.tasks)
        restore_plan = {}
        last_agent = None
        processed_agents = set()
        try:
            while True:
                try:
                    agent = self._craft_material(restore_plan)
                    if agent is not None:
                        last_agent = agent
                        processed_agents.add(agent)
                except MowerExit:
                    raise
                except Exception as e:
                    last_agent = None
                    save_exception(e)
                    logger.exception("工厂任务失败: %s", e)
                    break
                # 后续任务按对象身份移除；首个任务在恢复成功后完成收尾。
                if self.task is not first_task:
                    self.tasks[:] = [t for t in self.tasks if t is not self.task]
                if first_task.type != TaskTypes.WORKSHOP or first_task.plan:
                    break
                next_task = self._next_workshop_task(first_task)
                if next_task is None:
                    break
                logger.info(f"连续加工，直接切换至{next_task.meta_data}")
                self.task = next_task
        finally:
            self.task = first_task

        if restore_plan and (
            len(restore_plan) > 1 or restore_plan["factory"] != [last_agent]
        ):
            try:
                logger.info("本轮加工结束，统一恢复干员位置")
                if self.agent_arrange(restore_plan, get_time=True) is False:
                    return
            except MowerExit:
                raise
            except Exception as e:
                save_exception(e)
                logger.exception("加工后恢复干员失败: %s", e)
                return
        if processed_agents:
            if (
                first_task.type == TaskTypes.WORKSHOP
                and not first_task.plan
                and first_task.meta_data in processed_agents
            ):
                # 已完成的加工不再占用任务预约，其他临近任务继续保留。
                self.tasks[:] = [t for t in self.tasks if t is not first_task]
            self.op_data.refresh_idle_dorm_search(
                reason="加工结束后复核恢复需求", names=processed_agents
            )
            if not self._plan_dorm_recovery(scan_moods=False):
                self.plan_metadata()

    def _next_workshop_task(self, first_task):
        # 每次交接重新检查队列，兼容新增/删除任务和专精换人保护。
        tasks = getattr(self, "tasks", [])
        op_data = getattr(self, "op_data", None)
        protect_priority_tasks(tasks, op_data=op_data)
        pending = sorted(
            (
                task
                for task in task_view(tasks, TaskScope.DISPATCH, op_data)
                if task is not first_task
            ),
            key=lambda task: task.time,
        )
        if not pending:
            return None
        task = pending[0]
        if (
            task.type == TaskTypes.WORKSHOP
            and not task.plan
            and task.time <= datetime.now()
        ):
            return task
        return None

    def _craft_material(self, restore_plan):
        task = self.task
        from arknights_mower.utils.workshop_automation import workshop_task_snapshot

        snapshot = workshop_task_snapshot(task)
        if snapshot is None:
            logger.info("加工配置已更新，跳过旧的自动加工任务")
            return
        from arknights_mower.utils.workshop_limits import (
            workshop_candidate_mood,
            workshop_material_block_reason,
            workshop_operator_block_reason,
        )

        setting = next(
            (item for item in snapshot.settings if item.operator == task.meta_data),
            None,
        )
        if setting is None:
            logger.info(f"{task.meta_data}不在加工站配置中，调人前跳过")
            return
        if not setting.enabled:
            logger.info(f"{task.meta_data}加工站任务被禁用，调人前跳过")
            return
        operator = self.op_data.operators.get(task.meta_data)
        mood = workshop_candidate_mood(self.op_data, task.meta_data)
        reason = workshop_operator_block_reason(
            self.op_data,
            task.meta_data,
            getattr(self, "tasks", []),
            current_task=task,
            require_known_mood=config.conf.workshop_auto_active
            and setting.source == "mastery",
        ) or workshop_material_block_reason(
            task.meta_data, setting.items, get_inventory_counts(), mood
        )
        if reason:
            logger.info(f"{task.meta_data}加工跳过：{reason}")
            return
        self.enter_room("factory")
        previous_restore_plan = copy.deepcopy(restore_plan)
        if "factory" not in restore_plan:
            restore_plan["factory"] = [
                row["agent"]
                for row in self.get_agent_from_room("factory")
                if row["agent"]
            ] or [task.meta_data]
            # 原本无人时沿用单次加工行为，首位加工干员作为最终留驻干员。
        agent_room = operator.current_room if operator is not None else ""
        agent_index = operator.current_index if operator is not None else -1
        logger.debug(f"本轮加工前工厂干员: {restore_plan['factory']}")
        logger.debug(f"当前加工干员位置: {agent_room}")
        if (
            restore_plan["factory"]
            and task.meta_data not in restore_plan["factory"]
            and agent_room
            and agent_room != "factory"
            and agent_index >= 0
        ):
            restore_plan.setdefault(
                agent_room, ["Current"] * len(self.op_data.plan[agent_room])
            )[agent_index] = task.meta_data
        previous_selection_target = getattr(self, "_workshop_selection_target", None)
        self._workshop_selection_target = task.meta_data
        previous_handoff = getattr(self, "_workshop_room_handoff", False) is True
        self._workshop_room_handoff = True
        try:
            if not (
                previous_restore_plan and agent_room == "factory" and agent_index == 0
            ):
                if self.agent_arrange({"factory": [task.meta_data]}) is False:
                    return
        except WorkshopSelectionBlocked as reason:
            restore_plan.clear()
            restore_plan.update(previous_restore_plan)
            self.back_to_infrastructure()
            logger.info(f"{task.meta_data}加工跳过：{reason}")
            return
        finally:
            self._workshop_selection_target = previous_selection_target
            self._workshop_room_handoff = previous_handoff
        if self.generate_product(task.meta_data, snapshot=snapshot) is False:
            raise RuntimeError("加工执行失败，停止本轮连续换人")
        deer_first = config.conf.workshop_auto_active and any(
            setting.operator == "九色鹿" for setting in snapshot.settings
        )
        if config.conf.workshop_auto_active and (
            not snapshot.is_current() or deer_first
        ):
            # A confirmed batch advances the recipe generation. Continue with
            # remaining mood instead of waiting for the normal fresh-task gate.
            if deer_first:
                try_workshop_tasks(
                    self.op_data, self.tasks, minimum_mood=0, completed_task=task
                )
            else:
                try_workshop_tasks(self.op_data, self.tasks, minimum_mood=0)
        return task.meta_data

    def _discard_legacy_recovery_checks(self):
        """旧版回满核验不再暂停换人，保留原任务及其尚未完成的安排。"""
        reasons = {
            "需要回满的主班尚未实读确认恢复完成",
            "需要回满的主班心情尚未满足要求，且缺少有效恢复期限",
        }
        waiting = getattr(self, "waiting_group_shifts", [])
        for task in [*self.tasks, *waiting]:
            legacy_wait = hasattr(task, "recovery_waiting_observations")
            failure = getattr(task, "execution_failure", None)
            if not legacy_wait and (
                not failure or failure.get("reason") not in reasons
            ):
                continue
            if failure and failure.get("reason") in reasons:
                del task.execution_failure
            task.execution_retained = True
            task.__dict__.pop("recovery_waiting_observations", None)
            self._refresh_derived_correction(task)
            self._prepare_correction_recovery(task)
            if legacy_wait and not (
                getattr(task, "group_shift_waiting", ())
                or getattr(task, "group_shift_predecessors", ())
                or getattr(task, "departure_recovery_names", ())
            ):
                task.__dict__.pop("group_shift_waiting", None)
                task.__dict__.pop("group_shift_predecessors", None)
                waiting[:] = [pending for pending in waiting if pending is not task]
                if all(pending is not task for pending in self.tasks):
                    self.tasks.append(task)
        self.tasks[:] = [
            task
            for task in self.tasks
            if not (
                task.type == TaskTypes.REFRESH_TIME
                and getattr(task, "recovery_observation_rooms", None)
            )
        ]

    def _refresh_observed_recovery_tasks(self):
        """正常读房后的安全边界更新回班安排，不改动正在执行的换班。"""
        if not getattr(self, "_recovery_plan_dirty", False):
            return
        if self._initial_mood_read_pending() or self._emergency_frozen():
            return
        if any(
            getattr(task, "group_shift_expected", {})
            or getattr(task, "backup_shift_active", False)
            for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
        ):
            return
        self.plan_metadata()
        self._recovery_plan_dirty = False

    def _waiting_shift_reservations(
        self,
        *,
        returning_groups=(),
        returning_names=(),
        current_task=None,
        recovering_name=None,
    ):
        """等待任务保留目标，但不阻止其依赖组回班释放替班。"""
        names, slots = set(), set()
        for task in getattr(self, "waiting_group_shifts", ()):
            if task is current_task:
                continue
            if set(returning_groups).intersection(
                getattr(task, "group_shift_waiting", ())
            ):
                continue
            released = set()
            if not task.retains_execution and not any(
                getattr(task, flag, False)
                for flag in (
                    "mood_physical_started",
                    "derived_correction_started",
                    "group_shift_expected",
                    "product_shift_locked",
                )
            ):
                # 副表生效不等于已经换人；相同回班目标可先独立执行并释放床位。
                for name in returning_names:
                    op = self.op_data.operators.get(name)
                    if (
                        op is not None
                        and op.room
                        and not op.room.startswith("dorm")
                        and task.plan.get(op.room, [])[op.index : op.index + 1]
                        == [name]
                    ):
                        released.add(name)
            from arknights_mower.utils.retained_recovery import (
                pending_return_allows_recovery,
                pending_return_recovery_slots,
            )

            recovering = (
                {recovering_name}
                if recovering_name
                and pending_return_allows_recovery(self.op_data, task, recovering_name)
                else set()
            )
            recovery_slots = (
                pending_return_recovery_slots(self.op_data, task, recovering_name)
                if recovering
                else set()
            )
            names.update(
                name
                for row in task.plan.values()
                for name in row
                if name in self.op_data.operators and name not in released | recovering
            )
            # 尚未离岗的干员同样占有目标床位，不能仅预约其当前源岗位。
            slots.update(
                (room, index)
                for room, row in task.plan.items()
                if room.startswith("dorm")
                for index, name in enumerate(row)
                if name != "Current"
                and name not in released
                and (room, index) not in recovery_slots
            )
            for position, name in getattr(task, "group_shift_expected", {}).items():
                if name != "Current" and name not in released:
                    slots.add(position)
                    if name in self.op_data.operators:
                        names.add(name)
        slots.update(
            (op.current_room, op.current_index)
            for name in names
            if (op := self.op_data.operators[name]).current_room
        )
        return names, slots

    def _dorm_recovery_reservations(
        self,
        tasks,
        *,
        op_data=None,
        returning_groups=(),
        current_task=None,
        recovering_name=None,
    ):
        """返回合并预约及等待队列预约，保留各规划阶段的释放边界。

        普通补床调用仅取后两项作为额外保护，由补床器自行读取主队列。
        """
        data = self.op_data if op_data is None else op_data
        names, slots = dorm_task_reservations(
            data, tasks, recovering_name=recovering_name
        )
        view = self
        if data is not self.op_data:
            view = copy.copy(self)
            view.op_data = data
        waiting_names, waiting_slots = view._waiting_shift_reservations(
            returning_groups=returning_groups,
            current_task=current_task,
            recovering_name=recovering_name,
        )
        names.update(waiting_names)
        slots.update(waiting_slots)
        return names, slots, waiting_names, waiting_slots

    def _returning_groups_releasing_waits(self, task):
        return {
            group
            for group, resting in getattr(task, "group_shift_transitions", {}).items()
            if not getattr(task, "initial_staffing", False)
            and not resting
            and self.op_data.group_is_resting(group)
        }

    def _reorder_dorm_recovery(self, plan):
        current = getattr(self, "task", None)
        names, slots = self._waiting_shift_reservations(
            returning_groups=self._returning_groups_releasing_waits(current),
            current_task=current,
        )
        return try_reorder(
            self.op_data,
            plan,
            tasks=self.tasks,
            reserved_names=names,
            reserved_slots=slots,
        )

    def plan_metadata(self):
        if self._emergency_frozen():
            self._emergency_filter_tasks()
            self._emergency_replan_releases()
            return
        waiting_names = set()
        for task in getattr(self, "waiting_group_shifts", ()):
            if task.type == TaskTypes.SHIFT_ON:
                dependencies = set(getattr(task, "group_shift_waiting", ()))
                waiting_names.update(
                    name
                    for row in task.plan.values()
                    for name in row
                    if not (
                        (op := self.op_data.operators.get(name)) is not None
                        and op.group in dependencies
                    )
                )
                waiting_names.update(getattr(task, "group_shift_expected", {}).values())
        self.tasks = plan_metadata(
            self.op_data,
            self.tasks,
            excluded_names=self._protected_facility_names() | waiting_names,
            excluded_replacements=self._protected_facility_names(
                include_configured=False
            )
            | waiting_names,
        )
        from arknights_mower.utils.backup_group_tasks import filter_held_returns

        filter_held_returns(self.op_data, self.tasks)
        self._resume_waiting_group_shifts()
        sync_replacement_checks(self)

    def _prepare_correction_recovery(self, task):
        """普通纠错先补齐离岗回满主班的替班和床位。"""
        if (
            task.type != TaskTypes.SELF_CORRECTION
            or task.meta_data
            or not (
                getattr(task, "derived_correction", False)
                or getattr(task, "initial_staffing", False)
            )
            or any(
                getattr(task, flag, False)
                for flag in (
                    "derived_correction_started",
                    "group_shift_expected",
                    "backup_shift_active",
                    "backup_explicit_slots",
                    "product_shift_locked",
                    "exhaust_support",
                    "ordinary_coordination",
                    "preferred_replacement_restore",
                    "dorm_recovery_restore",
                    "emergency_staffing",
                )
            )
        ):
            return False
        from arknights_mower.utils.resting_correction import (
            off_duty_full_recovery_members,
            prefer_resting_replacements,
        )

        names = {
            name
            for name in off_duty_full_recovery_members(self.op_data)
            - self._protected_facility_names()
            - set(getattr(task, "initial_staffing_returns", ()))
            if (op := self.op_data.operators[name]).index
            < len(task.plan.get(op.room, []))
            and task.plan[op.room][op.index] != "Current"
        }
        if not names:
            return False
        previous = copy.deepcopy(task.plan)
        prefer_resting_replacements(self.op_data, task.plan, _is_mastery_busy)
        self._complete_departed_recovery(task.plan, names)
        if task.plan == previous:
            return False
        for field in (
            "backup_shift_intent",
            "backup_shift_conditions",
            "group_shift_transitions",
            "dorm_fill_plan",
        ):
            task.__dict__.pop(field, None)
        return True

    def _sync_idle_release_tasks(self):
        ordinary = []
        if self.op_data.config.free_room:
            # 复用普通规划的候选、预约和时刻，只替换普通清退；保留当前换班及其他任务。
            planned = plan_metadata(
                self.op_data,
                copy.deepcopy(self.tasks),
                excluded_names=self._protected_facility_names(),
                excluded_replacements=self._protected_facility_names(
                    include_configured=False
                ),
            )
            ordinary = [
                task
                for task in planned
                if task.type == TaskTypes.RELEASE_DORM
                and not getattr(task, "strict_mood_limit", False)
            ]
        self.tasks[:] = [
            task
            for task in self.tasks
            if task.type != TaskTypes.RELEASE_DORM
            or getattr(task, "strict_mood_limit", False)
        ] + ordinary

    def prepare_release_dorm(self, task):
        """合并任务逐人核验；一人失效不取消其他人的清退。"""
        if not hasattr(task, "release_targets"):
            return self._prepare_release_dorm_member(task)
        plan, valid = {}, {}
        get_time = False
        for name, (room, index) in task.release_dorm_targets().items():
            row = ["Current"] * len(task.plan[room])
            row[index] = "Free"
            member = SchedulerTask(
                time=task.time,
                task_plan={room: row},
                task_type=TaskTypes.RELEASE_DORM,
                meta_data=name,
                strict_mood_limit=getattr(task, "strict_mood_limit", False),
                mood_limit=getattr(task, "mood_limit", None),
            )
            get_time |= self._prepare_release_dorm_member(member)
            if not member.plan:
                continue
            _merge_dorm_arrangement(plan, member.plan)
            valid[name] = (room, index)
        task.plan, task.release_targets = plan, valid
        task.meta_data = ",".join(valid)
        return get_time

    def _prepare_release_dorm_member(self, task):
        """逐人校验身份、床位和回满时刻，再更新原回班引用。"""
        strict = getattr(task, "strict_mood_limit", False)
        operator = self.op_data.operators.get(task.meta_data)
        if (
            self.op_data.is_free_room_excluded(task.meta_data)
            or strict
            and not (
                operator is not None
                and self.op_data.has_rest_mood_limit(task.meta_data)
                and getattr(task, "mood_limit", None) in (None, operator.upper_limit)
            )
            or (not strict)
            and (
                not self.op_data.config.free_room
                or self.op_data.skip_idle_dorm_release(task.meta_data)
            )
        ):
            # 配置变化或宿舍保留使本人的清退失效，其他住客分别核验。
            task.plan = {}
            return False
        room = next(iter(task.plan), None)
        if room is None or "Free" not in task.plan[room]:
            task.plan = {}
            return False
        index = task.plan[room].index("Free")
        if operator is None or (operator.current_room, operator.current_index) != (
            room,
            index,
        ):
            # 旧住客已离开或换位，不能清退后来的入住者。
            task.plan = {}
            return False
        now = datetime.now()
        mood = None if strict else dorm_candidate_mood(self.op_data, operator.name, now)
        if not strict and (mood is None or mood < operator.upper_limit):
            _, bed = self.op_data.get_dorm_by_name(operator.name)
            due = (
                self.op_data.calculated_mood_deadline(
                    operator.name, operator.upper_limit, now
                )
                if getattr(self.op_data, "mood_calculation_enabled", False)
                else bed.time
                if bed
                else None
            )
            if due is None:
                # 未知心情和未读到的恢复时刻不能证明已经回满。
                task.plan = {}
                return False
            if due > now:
                # 单人和合并清退共用重排；原任务仍由派发入口收尾。
                pending = copy.deepcopy(task)
                pending.time = due
                self.tasks.append(pending)
                task.plan = {}
                return False
        # 宿舍清退只处理床位；加工使用独立任务。
        if operator.is_high() and operator.mood > 0:
            idx, dorm = self.op_data.get_dorm_by_name(operator.name)
            if idx is not None:
                update_task = find_next_task(
                    self.tasks,
                    task_type=TaskTypes.SHIFT_ON,
                    meta_data="dorm" + str(idx),
                )
                if update_task:
                    logger.debug("开始更新宿舍信息")
                    dorm_list = update_task.meta_data.split(",")
                    dorm_list.remove("dorm" + str(idx))
                    update_task.meta_data = ",".join(dorm_list)
                    from arknights_mower.utils.group_recovery import observed_full_mood

                    if (
                        not getattr(self.op_data, "mood_calculation_enabled", False)
                        and not strict
                        and not observed_full_mood(operator)
                    ):
                        operator.mood = operator.upper_limit
                        operator.time_stamp = dorm.time
                        operator.mood_is_prediction = True
        return True

    def arrange_release_dorm(self):
        """执行队列中的合并清退；失败只重试尚未完成的房间。"""
        task = self.task
        get_time = self.prepare_release_dorm(task)
        original_plan = copy.deepcopy(task.plan)
        before = {
            room: self.op_data.get_current_room(room, True) for room in original_plan
        }
        completed = False
        if len(original_plan) == 1:
            self._release_dorm_readings = {}
        try:
            result = self.agent_arrange(task.plan, get_time)
            completed = result is not False
            return result, get_time
        finally:
            readings = self.__dict__.pop("_release_dorm_readings", {})
            # 成功也可能保留原住客；只用已完成房间的前后驻员触发分床。
            previous_arrangements = {
                room: names
                for room, names in before.items()
                if (completed or room not in task.plan)
                and names != self.op_data.get_current_room(room, True)
            }
            reserved_names, reserved_slots, _, _ = self._dorm_recovery_reservations(
                [
                    pending
                    for pending in self.tasks
                    if pending is not task
                    and (
                        pending.type != TaskTypes.SHIFT_ON or pending.retains_execution
                    )
                ],
            )
            if not completed:
                reserved_slots.update(
                    (room, index)
                    for room, names in task.plan.items()
                    for index, name in enumerate(names)
                    if name != "Current"
                )
            rearranged = prioritize_new_dorm_recovery(
                self.op_data,
                {},
                reserved_slots,
                reserved_names=reserved_names,
                previous_arrangements=previous_arrangements,
            )
            if completed and readings and rearranged and len(rearranged) == 1:
                room = next(iter(rearranged))
                if room in readings and keep_measured_dorm_swap(
                    self.op_data, room, rearranged[room], readings[room]
                ):
                    logger.info(
                        f"{facility_label(room, self.op_data)}：单回目标已在原床受益，保留两名住客的床位"
                    )
                    del rearranged[room]
            if rearranged:
                self.tasks.append(
                    SchedulerTask(task_type=TaskTypes.RE_ORDER, task_plan=rearranged)
                )
            # Free 在选人时会解析成姓名；重试仍按原身份核验，已完成房间不复原。
            task.plan = (
                {} if completed else {room: original_plan[room] for room in task.plan}
            )

    @log_mood_calculation("基建调度")
    def infra_main(self):
        """位于基建首页"""
        self._discard_legacy_mood_control_tasks()
        if getattr(self.op_data, "mood_calculation_enabled", False):
            from arknights_mower.utils.calculated_mood import sync_model

            sync_model(self.op_data)
            finish_mood_calculation()
        if self.find("control_central") is None:
            self.back()
            return
        from arknights_mower.utils.backup_group_tasks import (
            filter_held_returns,
            sync_group_tasks,
        )

        sync_group_tasks(self)
        filter_held_returns(self.op_data, self.tasks)
        self._refresh_observed_recovery_tasks()
        sync_replacement_checks(self)
        self._resume_failed_tasks()
        if self._observe_failed_arrangement_confirmation():
            self.skip()
            return True
        if getattr(self.task, "execution_failure", None):
            self.task = None
        if not self._product_switching_enabled():
            self._discard_product_switches()
        if self.task is not None and self.task.type == TaskTypes.SWITCH_PRODUCT:
            # 到期换班先收敛最终阵容，再由该任务执行前置切产物。
            # 独立切换仍留在队列，收敛或换班失败不能丢失其执行责任。
            product_room = parse_product_task_meta(self.task.meta_data)[0]
            due = [
                task
                for task in self.tasks
                if task.type
                in (
                    TaskTypes.SHIFT_ON,
                    TaskTypes.SHIFT_OFF,
                    TaskTypes.EXHAUST_OFF,
                    TaskTypes.SELF_CORRECTION,
                    TaskTypes.RE_ORDER,
                )
                and task.plan
                and task.time <= datetime.now()
                and not getattr(task, "strict_mood_limit", False)
                and not getattr(task, "exhaust_support", False)
                and not getattr(task, "product_shift_locked", False)
                and not getattr(task, "backup_shift_active", False)
                and (
                    product_room in task.plan
                    or self._products_after_arrangement(task.plan)[0].get(product_room)
                    != self.op_data.products.get(product_room)
                )
            ]
            ready = [
                task for task in due if not getattr(task, "execution_failure", None)
            ]
            if ready:
                self.task = min(ready, key=lambda task: task.time)
            elif due:
                rooms = set().union(*(task.plan for task in due))
                rooms.add(parse_product_task_meta(self.task.meta_data)[0])
                self._retain_failed_task(
                    self.task, "等待到期换班确认最终产物", sorted(rooms)
                )
                self.skip()
                return True
        self._initialize_startup_facilities()
        self._reconcile_initial_staffing()
        initial_fia_pending = any(
            getattr(task, "initial_fia", False) for task in self.tasks
        )
        if initial_fia_pending:
            protect_priority_tasks(self.tasks, op_data=getattr(self, "op_data", None))
            candidate = next(
                iter(task_view(self.tasks, TaskScope.DISPATCH, self.op_data)), None
            )
            if (
                candidate is not None
                and candidate.time <= datetime.now()
                and getattr(candidate, "initial_fia", False)
            ):
                self.task = candidate
        if (
            getattr(self, "_emergency_startup_pending", False)
            # 初始充能只在实读完成后入队；等待充能结果不再阻挡独立任务。
            and not (
                initial_fia_pending and getattr(self, "_initial_fia_checked", False)
            )
            and not (
                self._emergency_continuation_checkpoint() is not None
                and self.task is not None
                and not self.task.plan
                and self.task.type
                in MANUAL_TASK_TYPES
                | MAINTENANCE_TASK_TYPES
                | {
                    TaskTypes.CLUE,
                    TaskTypes.CLUE_PARTY,
                    TaskTypes.DEPOT,
                    TaskTypes.FURNITURE,
                    TaskTypes.MAA_MALL,
                }
            )
        ) and not (
            getattr(self.task, "strict_mood_limit", False)
            or getattr(self.task, "initial_fia", False)
            or any(task is self.task for task in self._startup_priority_tasks())
        ):
            if self.task is not None:
                # 保留旧安排供实读后重算，但不让它反复派发或挡住独立任务。
                self.task.startup_observation_pending = True
            self.skip()
            return True
        if self.task is not None:
            if getattr(self.task, "run_order_restore_pending", False):
                self.task.prepare_run_order_restoration()
            # Navigation/reconnection may have consumed the margin since run().
            # Recheck at a safe boundary, before any staff arrangement has started.
            protect_priority_tasks(self.tasks, op_data=getattr(self, "op_data", None))
            blocked_orders = blocked_run_order_ids(
                self.tasks, getattr(self, "op_data", None)
            )
            from arknights_mower.utils.group_recovery import mood_limit_release_yields

            if (
                self.task.time > datetime.now()
                or id(self.task) in blocked_orders
                or not any(task is self.task for task in self.tasks)
                or (
                    self.tasks
                    and self.tasks[0] is not self.task
                    and not mood_limit_release_yields(
                        self.op_data, self.tasks[0], self.task
                    )
                    and (
                        getattr(self.tasks[0], "emergency_takeover", False)
                        or getattr(self.tasks[0], "strict_mood_limit", False)
                        or getattr(self.tasks[0], "initial_fia", False)
                        or (
                            self.tasks[0].type == TaskTypes.RUN_ORDER
                            and id(self.tasks[0]) not in blocked_orders
                            or config.conf.mastery_enabled
                            and self.tasks[0].type == TaskTypes.SWAP_SUPPORT
                        )
                    )
                    and (
                        self.task.retains_execution
                        or self.tasks[0].time <= datetime.now()
                    )
                )
            ):
                self.task = None
                self.skip()
                return True
            if (
                self.task.type in (TaskTypes.CLUE_PARTY, TaskTypes.CLUE)
                and getattr(self.task, "credit_shop_continuation", None) is None
                and (resume_time := self._clue_flow_resume_time()) is not None
            ):
                # 执行前再次检查，覆盖旧存档及被其他任务拖延的线索任务。
                self.task.time = resume_time
                logger.info(
                    "临近 04:00 刷新，线索任务延后至 %s",
                    resume_time,
                    extra={"log_group": "clue"},
                )
                self.task = None
                self.skip()
                return True
            if not self._emergency_frozen() and not getattr(
                self.task, "initial_fia", False
            ):
                from arknights_mower.utils.group_recovery import mood_limit_group_return

                returning = mood_limit_group_return(self.op_data, self.task, self.tasks)
                if returning is not None:
                    self.task = returning
            product_tasks = []
            remove_current_task = True
            arrangement_deferred = False
            completed_task = None
            inserting_order = self.task.type == TaskTypes.RUN_ORDER and bool(
                self.task.meta_data
            )
            try:
                departure_ready = self._prepare_ordinary_departure(self.task)
                finish_mood_calculation()
                if not departure_ready:
                    # 副表或心情变化已取消普通下班需求，重新规划尚未开始的整批安排。
                    self.planned = False
                elif getattr(self.task, "replacement_check", None):
                    remove_current_task = run_replacement_check(self, self.task)
                    self.skip(["todo_task", "collect_notification"])
                elif self.task.meta_data == RESUME_META or (
                    getattr(self.task, "emergency_recovery_release", False)
                    and not getattr(self.task, "emergency_staffing", False)
                ):
                    if self._emergency_active():
                        self._emergency_tick()
                elif self.task.type == TaskTypes.SKILL_UPGRADE:
                    from arknights_mower.solvers.mastery import run_mastery_task

                    self._run_mastery_with_recovery(run_mastery_task)
                    from arknights_mower.utils.workshop_automation import (
                        restore_if_no_plans,
                    )

                    restore_if_no_plans()
                elif self.task.type == TaskTypes.SWAP_SUPPORT:
                    from arknights_mower.solvers.mastery import run_swap_support

                    self._run_mastery_with_recovery(run_swap_support)
                elif self.task.type == TaskTypes.FURNITURE:
                    from arknights_mower.solvers.furniture import FurnitureDismantler
                    from arknights_mower.utils.furniture_task import (
                        FurnitureNavigationError,
                    )

                    try:
                        FurnitureDismantler(self).run()
                    except (MowerExit, FurnitureNavigationError, ConnectionError):
                        raise
                    except Exception:
                        # 保护失败、识别异常及提交结果不明都只执行一次。
                        # 先移除再交给通用异常记录，避免下一轮重跑同一任务。
                        self.tasks[:] = [t for t in self.tasks if t is not self.task]
                        raise
                elif self.task.type == TaskTypes.SWITCH_PRODUCT:
                    batch_cutoff = datetime.now()
                    product_tasks = [
                        task
                        for task in self.tasks
                        if task.type == TaskTypes.SWITCH_PRODUCT
                        and task.time <= batch_cutoff
                        and not getattr(task, "execution_failure", None)
                    ]
                    self.switch_base_products(product_tasks)
                    # 批量切换自行移除已完成任务；失败目标保留原任务。
                    remove_current_task = False
                elif (
                    self.task.plan
                    or getattr(self.task, "group_shift_transitions", {})
                    or getattr(self.task, "group_shift_expected", {})
                ):
                    get_time = False
                    if TaskTypes.SHIFT_OFF == self.task.type or (
                        self.task.type
                        in (TaskTypes.SELF_CORRECTION, TaskTypes.RE_ORDER)
                        or (
                            self.task.type
                            in (TaskTypes.NOT_SPECIFIC, TaskTypes.FILL_DORM)
                            and any(room.startswith("dorm") for room in self.task.plan)
                        )
                    ):
                        # 纠偏／迁移／补床都可能更换单回目标；完成后以实际
                        # 读到的床位时间重建派生回班。
                        get_time = True
                    if (
                        config.conf.run_order_grandet_mode.back_to_index
                        and TaskTypes.RUN_ORDER == self.task.type
                        and self.task.meta_data
                        and not self.refresh_connecting
                        and config.conf.run_order_buffer_time > 0
                        and datetime.now() + timedelta(seconds=45)
                        < self.task.time
                        + timedelta(
                            seconds=run_order_entry_seconds(self.task, config.conf)
                        )
                    ):
                        # 有45秒冗余时间才返回基地主界面
                        logger.info("跑单前返回主界面以保持登录状态")
                        self.back_to_index()
                        self.refresh_connecting = True
                        return
                    self.refresh_connecting = False
                    if self.task.type in (
                        TaskTypes.SHIFT_OFF,
                        TaskTypes.SHIFT_ON,
                        TaskTypes.EXHAUST_OFF,
                        TaskTypes.RE_ORDER,
                        TaskTypes.SELF_CORRECTION,
                    ):
                        if (
                            getattr(self.task, "preferred_replacement_restore", False)
                            and not self.task.retains_execution
                            and not any(
                                getattr(self.task, flag, False)
                                for flag in (
                                    "mood_physical_started",
                                    "backup_shift_active",
                                    "group_shift_expected",
                                    "product_shift_locked",
                                )
                            )
                        ):
                            from arknights_mower.utils.replacement_coordination import (
                                coordination_reservations,
                                preferred_replacement_restore,
                                replacement_dependencies,
                            )

                            protected, slots = coordination_reservations(
                                self.op_data, self.tasks, self.task
                            )
                            protected.update(
                                self._protected_facility_names(include_configured=False)
                            )
                            for pending in self.tasks:
                                if (
                                    pending is not self.task
                                    and pending.type == TaskTypes.EXHAUST_OFF
                                    and pending.time <= datetime.now()
                                ):
                                    protected.update(
                                        replacement_dependencies(
                                            self.op_data, pending.meta_data.split(",")
                                        )
                                    )
                            self.task.plan = preferred_replacement_restore(
                                self.op_data, _is_mastery_busy, protected, slots
                            )
                            if not self.task.plan:
                                self.tasks[:] = [
                                    t for t in self.tasks if t is not self.task
                                ]
                                self.skip()
                                return True
                        if unstarted_product_wait(self.task):
                            # 依赖解除后重新复核整条准备流程；尚未派发时仍保留清理保护。
                            self.task.execution_retained = False
                            self.task.__dict__.pop("product_shift_waiting", None)
                        self._refresh_coordination_support(self.task)
                        self._prepare_correction_recovery(self.task)
                        self._prepare_group_shift(self.task)
                        self._prepare_shift_cycle(self.task)
                        if self.task.time > datetime.now():
                            self.tasks.sort(key=lambda pending: pending.time)
                            self.task = None
                            self.skip()
                            return True
                        self._defer_conflicting_product_shift_slots(self.task)
                        if getattr(self.task, "execution_failure", None):
                            self.skip()
                            return True
                        if (
                            getattr(self.task, "initial_staffing", False)
                            and not getattr(
                                self.task, "derived_correction_started", False
                            )
                            and not hasattr(self.task, "initial_staffing_idle_members")
                        ):
                            from arknights_mower.utils.recovery_execution import (
                                initial_idle_staffing_members,
                            )

                            self.task.initial_staffing_idle_members = (
                                initial_idle_staffing_members(
                                    self.op_data, self.task, now=datetime.now()
                                )
                            )
                        if (
                            self.task.plan
                            and getattr(self.task, "exhaust_support", False)
                            and not self._coordination_support_valid(
                                self.task.plan, self.task.coordination_request_names
                            )
                        ):
                            if (
                                getattr(self.task, "ordinary_coordination", False)
                                and not getattr(self.task, "backup_shift_active", False)
                                and not getattr(self.task, "group_shift_expected", {})
                                and not self.task.retains_execution
                            ):
                                self.tasks[:] = [
                                    t for t in self.tasks if t is not self.task
                                ]
                            else:
                                self._retain_failed_task(
                                    self.task,
                                    "替班交接条件已经变化",
                                    list(self.task.plan),
                                )
                            self.skip()
                            return True
                        self._switch_products_before_arrangement(self.task)
                        self._activate_shift_backup(self.task)
                        self._prepare_group_shift(self.task, remember_targets=True)
                        get_time |= getattr(self.task, "backup_shift_active", False)
                        get_time |= any(
                            room.startswith("dorm") for room in self.task.plan
                        )
                    if self.task.type == TaskTypes.RELEASE_DORM:
                        result, get_time = self.arrange_release_dorm()
                        arrangement_deferred = result is False
                    else:
                        arrangement_deferred = (
                            self._arrange_with_shift_refresh_rules(self.task, get_time)
                            is False
                        )
                    if not arrangement_deferred:
                        arrangement_deferred = not self._complete_group_shift(self.task)
                    if not arrangement_deferred:
                        self.task.backup_shift_active = False
                    if arrangement_deferred:
                        # 已处理的工作房间从原任务移除；副表覆盖的宿舍也会从
                        # 原任务移除。仅在还有未覆盖的宿舍时保留原任务续行。
                        remove_current_task = not self.task.plan
                        self.skip()
                    elif get_time:
                        generated_tasks = []
                        if not self.backup_plan_solver(
                            generated_tasks=generated_tasks,
                        ):
                            self.plan_metadata()
                        else:
                            logger.info("排班表切换已在缓存中收敛为单次最终任务")
                    if not arrangement_deferred and getattr(
                        self.task, "product_switched_before_arrangement", False
                    ):
                        self._refresh_orders_after_product_switch()
                    if (
                        not arrangement_deferred
                        and TaskTypes.RE_ORDER == self.task.type
                    ):
                        self.skip()
                # 如果任务名称包含干员名,则为动态生成的
                elif self.task.type == TaskTypes.FIAMMETTA:
                    self.plan_fia()
                elif self.task.type == TaskTypes.WORKSHOP:
                    self.craft_material()
                elif (
                    self.task.meta_data.split(",")[0] in agent_list
                    and self.task.type == TaskTypes.EXHAUST_OFF
                ):
                    remove_current_task = self.overtake_room() is not False
                elif self.task.type == TaskTypes.CLUE_PARTY:
                    remove_current_task = self._run_clue_flow() is not False
                elif self.task.type == TaskTypes.CLUE:
                    # 手动触发的会客室任务，与定时触发走同一条路径
                    remove_current_task = self._run_clue_flow() is not False
                elif self.task.type == TaskTypes.REFRESH_TIME:
                    self.plan_run_order(self.task.meta_data)
                    self.skip(["todo_task", "collect_notification"])
                elif self.task.type == TaskTypes.DEPOT:
                    self.仓库扫描()
                elif self.task.type in MANUAL_TASK_TYPES:
                    from arknights_mower.solvers.manual_tasks import run_manual_task

                    remove_current_task = run_manual_task(self, self.task)
                    self.skip()
                elif self.task.type == TaskTypes.NOT_SPECIFIC:
                    pass
                if getattr(self.task, "execution_failure", None):
                    remove_current_task = False
                if remove_current_task:
                    completed_task = self.task
                    resolve_mastery_backup_tasks(self.tasks, (completed_task,))
                    self.tasks[:] = [t for t in self.tasks if t is not self.task]
                    self._refresh_deferred_product_reservations()
                    self._prune_order_read_log_cohorts()
                    self._prune_rescue_staffing_logs()
                if (
                    not arrangement_deferred
                    and self.tasks
                    and self.tasks[0].type in [TaskTypes.SHIFT_ON]
                ):
                    self.backup_plan_solver()
            except RunOrderMissed as e:
                # 漏单结束本次插拔；新订单使用正常读单流程，不保留失效时间。
                self.tasks[:] = [task for task in self.tasks if task is not self.task]
                self._queue_order_refresh(e.room)
                self.skip()
                self.back_to_infrastructure()
            except OrderReturnUnresolved:
                self.skip()
            except RunOrderConfirmationUnresolved as e:
                self._retain_run_order_restoration(failure=str(e))
                self.skip()
                self.back_to_infrastructure()
            except TrainingObservationError as e:
                self.task.mastery_observation_pending = True
                self._retain_failed_task(self.task, str(e), ["train"])
                self.skip()
                self.back_to_infrastructure()
            except MoodArrangementChanged:
                self.tasks[:] = [task for task in self.tasks if task is not self.task]
                self.planned = False
                self._refresh_deferred_product_reservations()
                self.back_to_infrastructure()
            except RoomArrangementDeferred as e:
                task = self.task
                attempts = (
                    getattr(task, "arrangement_retry_count", 0)
                    if getattr(task, "arrangement_retry_room", None) == e.room
                    else 0
                ) + 1
                if not hasattr(task, "arrangement_retry_due_at"):
                    task.arrangement_retry_due_at = task.time
                task.arrangement_retry_room = e.room
                task.arrangement_retry_count = attempts
                if not (
                    inserting_order
                    and getattr(task, "run_order_restore_pending", False)
                ):
                    isolate_room = (
                        e.room in task.plan
                        and self._is_ordinary_facility_arrangement(task)
                        and (
                            len(task.plan) > 1
                            or getattr(task, "arrangement_failures", None)
                        )
                    )
                    self._retain_failed_task(
                        task,
                        str(e),
                        [e.room],
                        arrangement_room=e.room if isolate_room else None,
                    )
                    if e.submitted_training_slot is not None:
                        task.execution_failure["submitted_training_slot"] = (
                            e.submitted_training_slot
                        )
                    if e.training_selection_wait is not None:
                        task.execution_failure["training_selection_wait"] = (
                            e.training_selection_wait
                        )
                    if isolate_room:
                        self._set_arrangement_dispatch(task)
                self.skip()
                self.back_to_infrastructure()
            except ProductSwitchFailed as e:
                pending = (
                    [self.task]
                    if self.task.type != TaskTypes.SWITCH_PRODUCT
                    else [
                        task
                        for task in self.tasks
                        if task.type == TaskTypes.SWITCH_PRODUCT
                        and task.meta_data.split(",", 1)[0] in e.rooms
                    ]
                )
                for task in pending:
                    self._retain_failed_task(task, str(e), e.rooms)
                self.skip()
            except GroupShiftBlocked as e:
                self._suspend_group_shift(
                    self.task,
                    e.groups,
                    predecessors=e.predecessors,
                    recovery_names=e.recovery_names,
                )
                logger.debug(str(e))
                # Suspended arrangements must not occupy the dispatch queue or
                # prevent the returning groups from receiving their tasks.
                self.plan_metadata()
                self.skip()
            except ProductSwitchPriorityDeferred as e:
                for task in product_tasks or [self.task]:
                    task.execution_retained = True
                protect_priority_tasks(self.tasks, op_data=self.op_data)
                logger.info(str(e))
                self.skip()
            except ProductSwitchDeferred as e:
                pending_ids = {id(task) for task in self.tasks}
                deferred_tasks = [
                    task
                    for task in product_tasks or [self.task]
                    if id(task) in pending_ids
                ]
                for task in deferred_tasks:
                    reason = e
                    if task.type == TaskTypes.SWITCH_PRODUCT and e.room_deferrals:
                        room = task.meta_data.split(",", 1)[0]
                        reason = next(
                            (item for item in e.room_deferrals if room in item.rooms),
                            None,
                        )
                        if reason is None:
                            continue
                    if reason.ready_at is not None:
                        task.time = max(task.time, reason.ready_at)
                        logger.info("%s，按实测进度等待至 %s", reason, reason.ready_at)
                    else:
                        task.product_shift_waiting = True
                        if reason.dependencies:
                            task.product_shift_predecessors = reason.dependencies
                        self._retain_failed_task(
                            task,
                            str(reason),
                            reason.rooms
                            or tuple(task.plan)
                            or (task.meta_data.split(",", 1)[0],),
                            dependency=True,
                        )
                self._refresh_deferred_product_reservations()
                self.tasks.sort(
                    key=lambda task: (
                        bool(getattr(task, "execution_failure", None)),
                        task.time,
                    )
                )
                self.skip()
            except CreditShopIncomplete as e:
                self._retain_credit_shop_failure(self.task, e)
                self.skip()
            except FriendClueReceiptIncomplete as e:
                self._retain_clue_receipt_failure(self.task, e)
                self.skip()
            except (MowerExit, DeviceRecoveryError, SharedADBError) as error:
                self._fail_rescue_staffing_log(self.task, str(error))
                raise
            except Exception as e:
                save_exception(e)
                logger.exception(e)
                if (
                    type(e) is ConnectionAbortedError
                    or type(e) is AttributeError
                    or type(e) is ConnectionError
                ):
                    raise e
                else:
                    pending = product_tasks or [self.task]
                    for task in pending:
                        if inserting_order and getattr(
                            task, "run_order_restore_pending", False
                        ):
                            logger.warning("跑单插拔中断，原任务立即转为恢复原驻员")
                        elif getattr(task, "replacement_check", None):
                            self._retain_failed_task(
                                task, str(e), [task.replacement_check["room"]]
                            )
                        elif (
                            task.plan
                            or task.type == TaskTypes.SWITCH_PRODUCT
                            or task.type in MANUAL_TASK_TYPES
                        ) and any(queued is task for queued in self.tasks):
                            rooms = task.plan or (
                                [task.meta_data.split(",", 1)[0]]
                                if task.type == TaskTypes.SWITCH_PRODUCT
                                else []
                            )
                            self._retain_failed_task(task, str(e), rooms)
                        elif not task.plan:
                            self.error = True
                    self.skip()
            finally:
                self._product_batch_active = False
                self._prune_rescue_staffing_logs()
            self.task = None
            if self._emergency_active() and not getattr(
                self, "_emergency_startup_pending", False
            ):
                self._emergency_tick(completed_task=completed_task)
            if completed_task is not None and (
                getattr(completed_task, "initial_fia", False)
                and not any(getattr(task, "initial_fia", False) for task in self.tasks)
                or not arrangement_deferred
                and (
                    completed_task.type == TaskTypes.RE_ORDER
                    or getattr(completed_task, "exhaust_support", False)
                    and getattr(completed_task, "ordinary_coordination", False)
                    or completed_task.type == TaskTypes.SELF_CORRECTION
                    and completed_task.meta_data == "副表内存收敛"
                )
            ):
                # 延期或重启可能已消费切表时的空任务；完成边界补回规划责任。
                # 复用已到期的空任务，远期回班不能代替立即正常规划。
                self._ensure_ordinary_planning_wake()
                self.skip()
                return True
        elif not self.planned:
            if self._emergency_active():
                self._emergency_tick()
                self.planned = True
                # 队列无可派发任务时沿用轮末空闲唤醒，按可执行的复查时间提前。
                if self.find_next_task() is None:
                    next_read = None
                    if (
                        self._emergency_active()
                        and self._emergency_continuation_checkpoint() is None
                    ):
                        next_read = self.emergency_state.get("next_read")
                    return self.handle_error(idle_deadline=next_read)
                return True
            try:
                # 如果有任何type 则会最后修正
                if not self._initial_mood_read_pending() and not self.no_pending_task(
                    1
                ):
                    self.skip(["planned", "todo_task", "collect_notification"])
                else:
                    # 正常运行保留原有心情读取间隔：缓存未过期直接信任，过期
                    # 才进房复核；缓存清零后 time_stamp 为空，会自然触发全量读取。
                    if getattr(self, "defer_backup_plan_until_mood_read", False):
                        # 首次读取不生成主表纠错；副表确定后才按最终排班规划。
                        if self._read_agent_mood() is False:
                            # 跑单或训练换人进入临近窗口时，保留初始化门闸，
                            # 先让高优先级任务执行，下一轮继续剩余房间观测。
                            self.skip(["planned", "todo_task", "collect_notification"])
                            return True
                        self._initial_card_scan_required = True
                        self._read_initial_card_mood()
                        self.defer_backup_plan_until_mood_read = False
                        if self._queue_initial_fia():
                            self.skip()
                            return True
                        self.backup_plan_solver()
                        self.queue_product_switches()
                        # 先执行副表差异、产物切换或扫描恢复出的训练室任务，
                        # 避免普通纠错覆盖这些任务的明确安排。
                        if not self.no_pending_task(1):
                            self.skip(["planned", "todo_task", "collect_notification"])
                            return True
                        if self._reconcile_initial_staffing():
                            self.skip(["planned", "todo_task", "collect_notification"])
                            return True
                        mood_result = self.agent_get_mood(
                            skip_dorm=True, read_rooms=False
                        )
                    else:
                        mood_result = self.agent_get_mood(skip_dorm=True)
                    # 初始化完成后恢复正常规划。
                    self.defer_backup_plan_until_mood_read = False
                    if mood_result is not None:
                        self.skip(["planned", "todo_task", "collect_notification"])
                        return True
                    self.run_order_solver()
                    self.plan_solver()
            except OrderReturnUnresolved:
                return
            except (MowerExit, DeviceRecoveryError):
                raise
            except Exception as e:
                save_exception(e)
                logger.exception(e)
                if (
                    type(e) is ConnectionAbortedError
                    or type(e) is AttributeError
                    or type(e) is ConnectionError
                ):
                    raise e
                else:
                    self.error = True
            self.planned = True
        elif not self.todo_task:
            if (
                (
                    self.enable_party
                    or getattr(config.conf, "should_run_mower_mall", False)
                )
                and (
                    self.last_clue is None
                    or datetime.now() - self.last_clue > timedelta(hours=1)
                )
                and self.no_pending_task(3)
                and self._clue_flow_resume_time() is None
                and not (
                    self.enable_party
                    and any(
                        getattr(task, "clue_receipt_pending", False)
                        for task in self.tasks
                    )
                )
            ):
                clue_started_at = datetime.now()
                try:
                    clue_result = (
                        self.clue_new() if self.enable_party else self._run_clue_shop()
                    )
                except CreditShopIncomplete as e:
                    task = SchedulerTask(time=clue_started_at, task_type=TaskTypes.CLUE)
                    self.tasks.append(task)
                    self._retain_credit_shop_failure(task, e)
                    self.last_clue = datetime.now()
                except FriendClueReceiptIncomplete as e:
                    task = SchedulerTask(time=clue_started_at, task_type=TaskTypes.CLUE)
                    self.tasks.append(task)
                    self._retain_clue_receipt_failure(task, e)
                else:
                    if clue_result is not False:
                        self.last_clue = datetime.now()
            if (
                self.drone_room not in self.op_data.run_order_rooms
                and (
                    self.drone_time is None
                    or self.drone_time
                    < datetime.now() - timedelta(hours=config.conf.drone_interval)
                )
                and self.drone_room is not None
                and self.no_pending_task(2)
            ):
                self.drone(self.drone_room)
                logger.info(f"记录本次无人机使用时间为:{datetime.now()}")
                self.drone_time = datetime.now()
            if self.no_pending_task(2) and (
                self.reload_time is None
                or self.reload_time
                < datetime.now() - timedelta(hours=config.conf.maa_gap)
            ):
                self.reload()
                logger.info(f"记录本次补货时间为:{datetime.now()}")
            self.todo_task = True
        elif not self.collect_notification:
            if self.no_pending_task(1):
                if self.collect_recycling():
                    return
                notification = detector.infra_notification(self.recog.img)
                if notification is None:
                    self.sleep(1)
                    notification = detector.infra_notification(self.recog.img)
                if notification is not None:
                    self.tap(notification)
            self.collect_notification = True
        else:
            return self.handle_error()

    def translate_room(self, room):
        translations = {
            "room": lambda parts: f"B{parts[1]}0{parts[2]}",
            "dormitory": lambda parts: f"{parts[1]}层宿舍",
            "contact": lambda parts: "办公室",
            "central": lambda parts: "控制中枢",
            "factory": lambda parts: "加工站",
            "meeting": lambda parts: "会客室",
            "train": lambda parts: "训练室",
            "recycle": lambda parts: "回收站",
        }

        for keyword, translation_func in translations.items():
            if keyword in room:
                parts = room.split("_")
                return translation_func(parts)

        return room

    def _read_agent_mood(self, *, rooms=None):
        """只刷新实际位置、心情及训练室状态，不按当前排班生成纠错。"""
        # 暂时规定纠错只适用于主班表
        need_read = {
            v.room
            for v in self.op_data.operators.values()
            if v.need_to_refresh() and v.room in base_room_list
        }
        initial_calculation = (
            getattr(self.op_data, "mood_calculation_enabled", False)
            and self._initial_mood_read_pending()
        )
        startup_observations = {
            room: signature
            for room, signature in getattr(
                self, "_startup_mood_observations", {}
            ).items()
            if signature == self._room_mood_signature(room)
            and all(
                observed_at is not None
                and observed_at
                > datetime.now()
                - timedelta(hours=0.5 if name in ("歌蕾蒂娅", "见行者") else 2.5)
                for name, _, observed_at in signature
            )
        }
        self._startup_mood_observations = (
            startup_observations if self._initial_mood_read_pending() else {}
        )
        if initial_calculation:
            self._initial_mood_room_observations = {
                name
                for signature in startup_observations.values()
                for name, _, _ in signature
            }
        initial_rooms = (
            {room for room in base_room_list if not room.startswith("gaming_")}
            if initial_calculation
            else set()
        )
        if getattr(self.op_data, "mood_calculation_enabled", False):
            need_read = initial_rooms

        force_rooms = {
            room
            for room in getattr(self, "_initial_mood_refresh_rooms", ())
            if (room in self.op_data.plan or room == "train") and room in base_room_list
        }
        # 训练室的首次强制读取由启动待办负责，续行不重新追加。
        force_rooms.update(initial_rooms - {"train"})
        self._initial_mood_refresh_rooms = force_rooms
        need_read.update(force_rooms)
        current_failures = {
            id(task): failure
            for task, failure in self._run_order_restoration_failures()
        }
        restoration_observations = {
            room: (task, failure)
            for room, (task, failure) in getattr(
                self, "_run_order_restoration_observations", {}
            ).items()
            if current_failures.get(id(task)) is failure
            and room in self.op_data.plan
            and room in base_room_list
        }
        self._run_order_restoration_observations = restoration_observations
        need_read.update(restoration_observations)
        for room in startup_observations.keys() - restoration_observations.keys():
            force_rooms.discard(room)
            need_read.discard(room)

        # 正常心情刷新检查未设为 0 级的训练室，包含未启用专精时的手动训练。
        # 实际扫描仍受房间级 2.5 小时限频保护。
        if (
            not getattr(self.op_data, "mood_calculation_enabled", False)
            or self._initial_mood_read_pending()
        ):
            need_read.add("train")

        if rooms is not None:
            need_read.intersection_update(rooms)

        initial_observation = initial_calculation or self._initial_mood_read_pending()

        facility_levels = getattr(self.op_data, "facility_levels", {})
        # 初始化先读取跑单设施与训练室，尽早取得会影响派单和训练冲突判断的实测状态。
        # 其余设施保持稳定排序，避免同一轮初始化的访问顺序漂移。
        run_order_rooms = set(getattr(self.op_data, "run_order_rooms", ()) or ())
        priority_rooms = sorted(
            room
            for room in need_read & run_order_rooms
            if facility_levels.get(room) != 0
        )
        if "train" in need_read and facility_levels.get("train") != 0:
            priority_rooms.append("train")
        ordered_rooms = priority_rooms + sorted(need_read - set(priority_rooms))
        for room_index, room in enumerate(ordered_rooms):
            # 优先设施实读或复用近期结果后，统一检查是否该先执行临近任务。
            if (
                initial_observation
                and room_index == len(priority_rooms)
                and self._yield_initial_mood_to_priority_task()
            ):
                return False
            if facility_levels.get(room) == 0:
                force_rooms.discard(room)
                restoration_observations.pop(room, None)
                continue
            if (
                room == "recycle"
                and getattr(self, "_recycle_unavailable", False) is True
            ):
                force_rooms.discard(room)
                continue
            if room == "train":
                last_read = max(
                    (
                        observed_at
                        for observed_at in (
                            getattr(self, "last_train_mood_read", None),
                            getattr(self, "last_train_mood_attempt", None),
                        )
                        if isinstance(observed_at, datetime)
                    ),
                    default=None,
                )
                if (
                    room not in force_rooms
                    and last_read
                    and datetime.now() - last_read < timedelta(hours=2.5)
                ):
                    continue
            error_count = 0
            # 近期可信读过的房内干员无需重复扫描；训练室保持原有巡检间隔。
            current_working = [
                value
                for key, value in self.op_data.operators.items()
                if value.current_room == room
            ]

            if (
                room not in force_rooms
                and room not in restoration_observations
                and current_working
                and all(
                    operator.time_stamp
                    and operator.time_stamp
                    > datetime.now()
                    - timedelta(
                        hours=0.5 if operator.name in ["歌蕾蒂娅", "见行者"] else 2.5
                    )
                    for operator in current_working
                )
            ):
                for e in current_working:
                    logger.debug(e.time_stamp)
                logger.debug(f"{room} 所有干员不满足扫描条件，跳过")
                continue
            if room in restoration_observations and not self.no_pending_task(1):
                continue
            if getattr(
                self, "_emergency_startup_pending", False
            ) and not self._emergency_operation_fits(
                estimate_dorm_minutes(room, 1.5) * 60
            ):
                finish_mood_calculation()
                self.back_to_infrastructure()
                return False
            skip_room_exit = False
            room_entered = False
            # 进入既有有界读房前消费本轮机会；读取失败不在同轮另起一次巡检。
            restoration_observations.pop(room, None)
            finish_mood_calculation()
            while True:
                try:
                    if room == "train":
                        self.enter_room(room, max_attempts=1)
                    else:
                        self.enter_room(room)
                    room_entered = True
                    if room == "train":
                        if config.conf.mastery_enabled:
                            # #94 统一读取：一次 read_room_state(want_mood=True) 开一次
                            # 浮窗读全（协助位+训练位+心情）+ 左下角面板，消除原来
                            # get_agent_from_room（读心情）后再开一次浮窗读槽位的重复
                            # 浮窗开关（铁律 3 一次进房做全部）。
                            from arknights_mower.solvers.mastery_reader import (
                                read_room_state,
                                reconcile_short,
                            )

                            try:
                                room_state, mood_data = read_room_state(
                                    self, enter=False, want_mood=True
                                )
                                self.train_room_state = room_state
                                if room_state.slots_reliable is True:
                                    self.last_train_mood_read = datetime.now()
                                if room_state.read_failed or room_state.state not in (
                                    "empty",
                                    "training",
                                    "waiting_collect",
                                ):
                                    logger.warning(
                                        "训练室房态读取不可信，本轮跳过训练位排班冲突判定"
                                    )
                                else:
                                    trainee = room_state.train_slot or getattr(
                                        room_state.panel, "operator_name", ""
                                    )
                                    _stop_if_scheduled_trainee(
                                        self, trainee, room_state
                                    )
                                if any(item.get("agent") for item in mood_data):
                                    self._log_room_mood(room, mood_data)
                                # 重启后训练室可能停在待收取（专精练完但没人收）：进训练室读
                                # 心情时顺便 reconcile——发现待收取就收（defer_collect=False
                                # 此刻就是要收），修正 DB（截图为准），打破「不收→等级不刷新
                                # →材料不够→不调度→更不收」死锁。enable_mastery 关闭时不跑
                                # 读取器（铁律 10），保留通用心情读取。
                                if room_state is not None:
                                    reconcile_short(
                                        self, room_state, defer_collect=False
                                    )
                            except (MowerExit, DeviceRecoveryError):
                                raise
                            except Exception as e:
                                logger.warning(f"训练室顺路更新状态失败: {e}")
                                raise
                        else:
                            # 手动训练也读取当前面板，但不启动专精调度或收取。
                            from arknights_mower.solvers.mastery_reader import (
                                read_room_state,
                            )

                            self.train_room_state = None
                            manual_room_state = read_room_state(self, enter=False)
                            _mood_data = self.get_agent_from_room(room, None)
                            if len(_mood_data) == 2:
                                self.last_train_mood_read = datetime.now()
                            trainee = (
                                _mood_data[1].get("agent", "")
                                if len(_mood_data) > 1
                                else ""
                            )
                            _stop_if_scheduled_trainee(
                                self, trainee, manual_room_state, detail_open=True
                            )
                            if any(item.get("agent") for item in _mood_data):
                                self._log_room_mood(room, _mood_data)
                        self.last_train_mood_attempt = datetime.now()
                    else:
                        self._read_room_mood(room, force_mood=room in force_rooms)
                    if initial_calculation:
                        self._initial_mood_room_observations.update(
                            op.name
                            for op in self.op_data.operators.values()
                            if op.current_room == room and op.time_stamp is not None
                        )
                    break
                except (MowerExit, DeviceRecoveryError):
                    raise
                except Exception as e:
                    if room == "train":
                        from arknights_mower.solvers.mastery_reader import RoomState

                        self.train_room_state = RoomState("unknown", read_failed=True)
                        logger.warning(f"训练室本次进房或读取失败，跳过本轮巡检：{e}")
                        self.last_train_mood_attempt = datetime.now()
                        self.back_to_infrastructure()
                        skip_room_exit = True
                        break
                    if (
                        initial_calculation
                        and room not in self.op_data.plan
                        and not room_entered
                    ):
                        logger.warning(
                            f"初始化设施{room}未建造或无法进入，保留未知状态：{e}"
                        )
                        self.back_to_infrastructure()
                        skip_room_exit = True
                        break
                    save_exception(e)
                    logger.exception(e)
                    if error_count > 3:
                        raise e
                    error_count += 1
                    self.back()
                    continue
            if not skip_room_exit:
                self.back()
            if (
                room == "train"
                and initial_calculation
                and getattr(self.train_room_state, "slots_reliable", False) is True
            ):
                self._startup_mood_observations[room] = self._room_mood_signature(room)
            force_rooms.discard(room)
            if getattr(self, "_emergency_startup_pending", False):
                self._emergency_replan_releases()
                protect_priority_tasks(
                    self.tasks, op_data=getattr(self, "op_data", None)
                )
                self._emergency_save()

        if (
            initial_observation
            and len(ordered_rooms) == len(priority_rooms)
            and self._yield_initial_mood_to_priority_task()
        ):
            return False

    def _is_startup_priority_task(self, task):
        return task.type == TaskTypes.RUN_ORDER or (
            config.conf.mastery_enabled
            and task.type in (TaskTypes.SKILL_UPGRADE, TaskTypes.SWAP_SUPPORT)
        )

    def _startup_priority_tasks(self):
        tasks = list(getattr(self, "tasks", ()))
        current = getattr(self, "task", None)
        if current is not None and all(task is not current for task in tasks):
            tasks.append(current)
        return [
            task
            for task in task_view(tasks, TaskScope.DISPATCH, self.op_data)
            if self._is_startup_priority_task(task)
        ]

    def _yield_initial_mood_to_priority_task(self):
        imminent_priority_task = any(
            task.time <= datetime.now() + timedelta(minutes=1)
            for task in self._startup_priority_tasks()
        )
        if not imminent_priority_task:
            return False
        logger.info("跑单或训练换人临近，暂停初始化其余设施读取")
        self.back_to_infrastructure()
        return True

    def _read_room_mood(
        self, room, *, force_mood=False, strict_observation=False, pending_order=None
    ):
        """实读普通房间的驻员与心情，清除已离开房间的缓存驻员。"""
        if room == "recycle" and getattr(self, "_recycle_unavailable", False) is True:
            return
        observation = {} if pending_order is None else pending_order
        capture = room.startswith("room_") and (
            self._product_switching_enabled()
            or getattr(self.op_data, "mood_calculation_enabled", False)
        )
        with ExitStack() as observation_scope:
            observation_args = {}
            if capture:
                observation_args = {
                    "facility_observation": observation,
                    "facility_observation_scope": observation_scope,
                }
                if pending_order is not None:
                    observation_args["defer_trade_order"] = True
            try:
                mood_data = self.get_agent_from_room(
                    room,
                    list(range(len(self.op_data.plan[room])))
                    if room in self.op_data.true_exhaust_room
                    else None,
                    **({"force_mood": True} if force_mood else {}),
                    **({"strict_observation": True} if strict_observation else {}),
                    **observation_args,
                )
            except BaseException:
                if observation:
                    self._log_facility_observation(
                        room,
                        observation,
                        "failed",
                        observation.get("failure_detail", "干员心情读取未完成"),
                    )
                raise
            if pending_order is None or not observation.get("order_pending"):
                self._log_room_mood(room, mood_data, observation=observation or None)
        return mood_data

    def _start_facility_observation(self, room, observation, scope, state_summary):
        observation.update(
            id=uuid4().hex,
            label=facility_label(room, self.op_data),
            state_summary=state_summary,
            moods={},
        )
        if scope is not None:
            scope.enter_context(
                log_parent_context(
                    {"type": "facility-observation", "id": observation["id"]}
                )
            )
        self._log_facility_observation(room, observation, "started", "正在读取干员心情")

    def _log_facility_observation(self, room, observation, phase, detail, agents=()):
        label = observation["label"]
        message = f"{label}：{observation['state_summary']}，{detail}"
        agents = list(agents)
        logger.info(
            message,
            extra={
                "log_room": room,
                "log_agents": agents,
                "log_parent": {"type": "facility-observation", "id": observation["id"]},
                "log_event": {
                    "type": "facility-observation",
                    "id": observation["id"],
                    "phase": phase,
                    "anchor": phase == "started",
                    "room": room,
                    "label": label,
                    "agents": agents,
                    "summary": message,
                },
            },
        )

    def _log_room_mood(self, room, mood_data, *, observation=None):
        """保留读房返回的驻员顺序和心情，区分确认空位与未识别位置。"""
        details, agents = [], []
        for index, item in enumerate(mood_data, 1):
            if item.get("observed", True) is False:
                details.append(f"第{index}位干员未识别")
            elif name := item.get("agent"):
                agents.append(name)
                mood = (
                    item["mood"]
                    if observation is None
                    else observation["moods"].get(index)
                )
                mood_text = (
                    f"心情{round(mood, 3)}" if mood is not None else "心情未实读"
                )
                details.append(f"[[operator:{name}]]（{mood_text}）")
            else:
                details.append(f"第{index}位空位")
        summary = "、".join(details) if details else "未读取到干员心情"
        if observation is not None:
            self._log_facility_observation(
                room, observation, "completed", summary, agents
            )
            return
        logger.info(
            f"{facility_label(room, self.op_data)}：{summary}",
            extra={"log_room": room, "log_agents": agents},
        )

    def _log_arrangement(self, description, *, task=None, plan=None, log_group=None):
        """只读记录已有任务或尚未入队的安排，不参与规划或派发。"""
        agents = []
        if task is not None:
            snapshot = build_task_presentation(task, self.op_data)
            if not snapshot["title"]:
                snapshot["title"] = (
                    task.meta_data
                    if isinstance(task.meta_data, str) and task.meta_data
                    else task.display_name
                )
            header = f"{description}「{snapshot['title']}」，执行时间 {task.time}"
            if (
                not snapshot["rooms"]
                and isinstance(task.meta_data, str)
                and task.meta_data
                and not snapshot["targets"]
            ):
                if task.type == TaskTypes.SWITCH_PRODUCT:
                    room, target = parse_product_task_meta(task.meta_data)
                    product = (
                        MANUFACTURE_PRODUCTS[target].name
                        if target in MANUFACTURE_PRODUCTS
                        else TRADE_PRODUCTS[target].strategy_name
                    )
                    snapshot["targets"].append(
                        {
                            "id": room,
                            "label": f"{facility_label(room, self.op_data)} → {product}",
                        }
                    )
                elif task.meta_data not in snapshot["title"]:
                    if task.type == TaskTypes.WORKSHOP:
                        agents.append(task.meta_data)
                        header += f"，目标干员：[[operator:{task.meta_data}]]"
                    else:
                        header += f"，任务目标：{task.meta_data}"
        else:
            snapshot = {
                "title": description,
                "rooms": [
                    {
                        "id": room,
                        "label": facility_label(room, self.op_data),
                        "agents": list(agents),
                    }
                    for room, agents in plan.items()
                ],
                "backups": [],
                "targets": [],
                "actions": [],
            }
            header = description
        snapshot["header"] = header
        logger.info(
            format_task_log_message(snapshot, header),
            extra={"log_task": snapshot, "log_agents": agents, "log_group": log_group},
        )

    def _read_initial_card_mood(self):
        """初始化必须尝试有界选人页扫描，不选人或确认换班。"""
        required = getattr(self, "_initial_card_scan_required", False)
        self._initial_card_scan_required = False
        # 自动救急启动沿用其按需扫描约定；普通初始化和演算初始化仍由调用方
        # 固定尝试扫描，确保排班基线不会因临近任务而缺失。
        if (
            not required
            and not getattr(self.op_data, "mood_calculation_enabled", False)
            and not getattr(self, "defer_backup_plan_until_mood_read", False)
        ):
            if not config.conf.automatic_rescue_enable:
                return
            from arknights_mower.utils.emergency_plan import configured_rescue_names

            if not any(
                name not in self.op_data.dorm_mood_estimates
                for name in configured_rescue_names(config.rescue_plan)
            ):
                return
        self._scan_card_moods(initial=True)

    def _read_missing_calculated_moods(self):
        """候选缺少演算基线时补扫一次；相同缺项与位置不重复尝试。"""
        if (
            not getattr(self.op_data, "mood_calculation_enabled", False)
            or self._initial_mood_read_pending()
            or getattr(self, "_card_moods_scanned_this_run", False)
        ):
            return
        model = self.op_data.mood_model
        targets = set(self.op_data.operators) | {
            item.operator for item in config.conf.workshop_settings if item.enabled
        }
        missing = targets - model.moods.keys()
        if not missing:
            return
        observation = tuple(
            (
                name,
                model.observed.get(name),
                model.barriers.get(name),
                model.positions.get(name),
            )
            for name in sorted(missing)
        )
        if observation == getattr(self, "_missing_mood_scan_attempt", None):
            return
        self._scan_card_moods(missing_calculated=missing)
        if getattr(self, "_card_moods_scanned_this_run", False):
            self._missing_mood_scan_attempt = observation

    def _read_missing_workshop_moods(self, *, refresh=False):
        """加工前统一读取候选卡片；日常补读仅处理变化后的未知候选。"""
        from arknights_mower.utils.workshop_limits import workshop_candidate_mood

        if (
            getattr(self, "recog", None) is None
            or self._initial_mood_read_pending()
            or getattr(self, "_workshop_card_moods_scanned_this_run", False)
        ):
            return
        missing = {
            setting.operator
            for setting in config.conf.workshop_settings
            if setting.enabled
            and (
                refresh
                or workshop_candidate_mood(self.op_data, setting.operator) is None
                and (
                    not getattr(self.op_data, "mood_calculation_enabled", False)
                    or setting.operator not in self.op_data.mood_model.moods
                )
            )
        }
        if not missing:
            return

        def observation():
            from arknights_mower.utils.dorm_candidates import card_mood_estimate

            return tuple(
                (
                    name,
                    getattr(op := self.op_data.operators.get(name), "time_stamp", None),
                    getattr(op, "mood", None),
                    getattr(op, "current_room", ""),
                    getattr(op, "current_index", -1),
                    self.op_data.dorm_mood_estimates.get(name),
                    card_mood_estimate(self.op_data, name) is not None,
                )
                for name in sorted(missing)
                if workshop_candidate_mood(self.op_data, name) is None
            )

        if not refresh and observation() == getattr(
            self, "_missing_workshop_mood_scan_attempt", None
        ):
            return
        self._scan_card_moods(workshop=True)
        if getattr(self, "_workshop_card_moods_scanned_this_run", False):
            self._missing_workshop_mood_scan_attempt = observation()
            return True

    @fixed_selection_profile
    def _scan_card_moods(
        self, *, missing_calculated=(), initial=False, workshop=False, mastery=False
    ):
        """升序扫描心情；临近任务阻止进入时返回 False，供依赖解除后继续。"""
        initial = initial or self._initial_mood_read_pending()
        # 启动恢复的离线调用可能只构造了排班数据而没有设备识别器；此时
        # 保留已恢复任务，待真实设备启动后再由完整初始化执行扫描。
        if getattr(self, "recog", None) is None:
            if initial:
                logger.info("初始化选人页心情扫描暂缓：设备识别器尚未就绪")
            return
        if (
            getattr(self.op_data, "mood_calculation_enabled", False)
            and not initial
            and not missing_calculated
            and not workshop
            and not mastery
        ):
            return
        if (
            not workshop
            and not mastery
            and getattr(self, "_card_moods_scanned_this_run", False)
        ):
            return

        room = (
            "factory"
            if workshop
            else next(
                (
                    room
                    for room, slots in self.op_data.plan.items()
                    if slots
                    and getattr(self.op_data, "facility_levels", {}).get(room) != 0
                    and not room.startswith("dorm")
                    and room not in ("train", "factory")
                ),
                None,
            )
        )
        if room is None or getattr(self.op_data, "facility_levels", {}).get(room) == 0:
            if initial:
                logger.warning("初始化选人页心情扫描未执行：没有可进入的普通设施")
            return

        def can_continue():
            if not workshop and not mastery:
                return self.no_pending_task(1)
            deadline = datetime.now() + timedelta(minutes=1)
            return not any(
                (not mastery or task is not getattr(self, "task", None))
                and task.time <= deadline
                and (mastery or task.type != TaskTypes.WORKSHOP or task.plan)
                for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            )

        if not initial and not can_continue():
            return False
        if workshop:
            self._workshop_card_moods_scanned_this_run = True
        else:
            self._card_moods_scanned_this_run = True
        if initial:
            logger.info("开始初始化选人页心情扫描")
        known_calculated = (
            set(self.op_data.mood_model.moods)
            if (
                getattr(self.op_data, "mood_calculation_enabled", False) and not initial
            )
            else set()
        )
        protected = (
            getattr(self, "_initial_mood_room_observations", set())
            if initial
            else known_calculated
        )
        deadline = monotonic() + 45
        estimates = self.op_data.dorm_mood_estimates
        scan_complete = False
        incomplete_reason = "未观测到满心情卡牌"
        unreadable_names = set()
        station_filter = None
        idle_only = not workshop and not mastery
        scan_names = set(agent_list)
        if idle_only:
            scan_names.difference_update(
                name for name, op in self.op_data.operators.items() if op.current_room
            )
        finish_mood_calculation()
        try:
            self.enter_room(room, max_attempts=1)
            self.turn_on_room_detail(room)
            for _ in range(4):
                if self.find("confirm_blue") is not None:
                    break
                if monotonic() >= deadline:
                    incomplete_reason = "进入选人页超过 45 秒上限"
                    return
                self.tap((self.recog.w * 0.82, self.recog.h * 0.2))
            else:
                raise AgentSelectionNotReady("未进入卡牌观测页，继续正常巡检")
            # 清除选人页暂选，避免原住客置顶的绿色卡片截断心情升序扫描。
            # 返回基建时取消此页，实际驻员不变。
            self.tap((self.recog.w * 0.38, self.recog.h * 0.95), interval=0.5)
            self.swipe_left(1, "ALL")
            station_filter = self.agent_station_filter()
            self.agent_station_filter("未进驻" if idle_only else "全部")
            self.switch_arrange_order("心情", room, True, refresh=False)
            previous = None
            observation = None
            observed_names = set()
            for page_index in range(20):
                if monotonic() >= deadline or (not initial and not can_continue()):
                    incomplete_reason = "达到扫描时间上限或临近任务"
                    break
                page = self.wait_for_agent_page(
                    before=previous, observation=observation
                )
                if previous is not None and self.same_agent_page(
                    page, previous, allow_unknown=True
                ):
                    incomplete_reason = "翻页后页面未变化"
                    break
                observed_at = datetime.now()
                full_card = False
                for name, scope in page:
                    if agent_card_selected(self.recog.img, scope) is not False:
                        raise AgentSelectionNotReady(
                            "卡牌仍选中或边框不明，取消本轮心情预估"
                        )
                    first_observation = name not in observed_names
                    if name:
                        observed_names.add(name)
                    mood = estimate_agent_mood(self.recog.img, scope)
                    if name:
                        if mood is None:
                            unreadable_names.add(name)
                            if first_observation:
                                if not getattr(
                                    self.op_data, "mood_calculation_enabled", False
                                ):
                                    estimates.pop(name, None)
                        else:
                            unreadable_names.discard(name)
                            estimates[name] = (mood, observed_at)
                            if (
                                getattr(self.op_data, "mood_calculation_enabled", False)
                                and name not in protected
                            ):
                                self.op_data.mood_model.observe(name, mood, observed_at)
                    if mood == 24:
                        # 心情升序首次出现绿色后，其余姓名只获得短期满值预估。
                        # 绿色之前已观测但不可读的卡牌不被默认值覆盖。
                        estimates.update(
                            (candidate, (24, observed_at, False))
                            for candidate in scan_names
                            if candidate not in observed_names
                        )
                        if getattr(self.op_data, "mood_calculation_enabled", False):
                            for candidate in scan_names:
                                if (
                                    candidate not in observed_names
                                    and candidate not in protected
                                ):
                                    self.op_data.mood_model.observe(
                                        candidate, 24, observed_at
                                    )
                        full_card = True
                        scan_complete = True
                        logger.info(
                            "心情升序遇到绿色笑脸，停止翻页，其余筛选范围内干员按 24 预估"
                        )
                        break
                if full_card or page_index == 19 or monotonic() >= deadline:
                    if not full_card:
                        incomplete_reason = "达到 20 页或 45 秒扫描上限"
                    break
                previous = page
                _, observation = self.swipe_agent_page(
                    page, "心情升序扫描", return_page=True
                )
        except (
            MowerExit,
            DeviceRecoveryError,
            ConnectionError,
            ConnectionAbortedError,
        ):
            raise
        except Exception as e:
            incomplete_reason = str(e)
            logger.warning(f"卡牌心情预估未完成，继续正常巡检：{e}")
        finally:
            if initial and unreadable_names:
                logger.warning(
                    "初始化选人页有 %s 名干员心情无法识别，未使用满值预估覆盖",
                    len(unreadable_names),
                )
            if initial and not scan_complete:
                logger.warning(
                    "初始化选人页心情扫描未完成：%s；保留已取得的观测，其余保持未知",
                    incomplete_reason,
                )
            self._recovery_plan_dirty = True
            try:
                if station_filter is not None:
                    self.agent_station_filter(station_filter)
            finally:
                self.back_to_infrastructure()

    def _observed_group_return_plan(self):
        """完整在岗观测生成回班意图，实际组状态仍由任务确认提交。"""
        if self._initial_mood_read_pending() or self._emergency_frozen():
            return {}
        pending = [
            getattr(self, "task", None),
            *getattr(self, "tasks", []),
            *getattr(self, "waiting_group_shifts", []),
        ]
        if any(
            getattr(task, "group_shift_expected", {})
            or getattr(task, "backup_shift_active", False)
            or getattr(task, "dorm_recovery_restore", [])
            or task is not None
            and task.type == TaskTypes.FIAMMETTA
            and task.time <= datetime.now()
            for task in pending
        ):
            return {}
        protected_training = self._protected_facility_names()
        plan = {}
        for group, resting in self.op_data.group_shift_state.items():
            if not resting:
                continue
            members = [
                self.op_data.operators[name]
                for name in self.op_data.shift_group_members(group)
                if self.op_data.is_group_shift_anchor(self.op_data.operators[name])
                and name not in protected_training
            ]
            if not members or any(
                op.time_stamp is None
                or (op.current_room, op.current_index) != (op.room, op.index)
                for op in members
            ):
                continue
            anchor = next(
                (op for op in members if op.room not in ("train", "factory")), None
            )
            if anchor is None:
                training = {}
                for op in members:
                    if op.room == "train":
                        training.setdefault(
                            "train", ["Current"] * len(self.op_data.plan["train"])
                        )[op.index] = op.name
                self._suppress_train_correction(training)
                anchor = next(
                    (
                        self.op_data.operators[name]
                        for name in training.get("train", [])
                        if name != "Current"
                    ),
                    None,
                )
            if anchor is not None:
                plan.setdefault(
                    anchor.room, ["Current"] * len(self.op_data.plan[anchor.room])
                )[anchor.index] = anchor.name
        return plan

    def agent_get_mood(
        self,
        skip_dorm=False,
        force=False,
        *,
        read_rooms=True,
        return_plan=False,
        explicit_slots=(),
    ):
        """刷新缓存并生成纠偏计划。

        ``read_rooms=False`` 只使用已经缓存的干员位置和心情。副表切换使用
        这个模式在内存中收敛最终排班，禁止为了推导结果反复进入游戏房间。
        ``return_plan=True`` 返回差异而不把纠错任务塞进队列。
        ``explicit_slots`` 保留预演中已应用的副表显式驻员，优先于普通纠错。
        """
        if read_rooms:
            observations = getattr(self.op_data, "idle_dorm_release_observations", None)
            if (
                getattr(self.op_data, "idle_dorm_release_suspended", False)
                and observations is None
            ):
                # 旧运行状态没有暂停时的观测版本，从当前版本等待后续新观测。
                observations = dict(self.op_data.room_observations)
                self.op_data.idle_dorm_release_observations = observations
            if self._read_agent_mood() is False:
                return {} if return_plan else None
            if getattr(self.op_data, "idle_dorm_release_suspended", False) and any(
                revision != observations.get(room)
                for room, revision in self.op_data.room_observations.items()
            ):
                self.op_data.idle_dorm_release_suspended = False
                self.op_data.idle_dorm_release_observations = None
                self.op_data.refresh_idle_dorm_search(
                    reason="心情检测已取得新的房间观测"
                )
        if self._emergency_frozen():
            return {} if return_plan else None
        plan = self.op_data.plan
        fix_plan = {}
        for key in plan:
            need_fix = False
            _current_room = self.op_data.get_current_room(key, True)
            # 训练室读取固定两格；纠错只管理排班中明确配置的槽位。
            for idx, name in enumerate(_current_room[: len(plan[key])]):
                slot = plan[key][idx]
                owner = self.op_data.operators.get(slot.agent)
                replacements = (
                    owner.replacement if owner is not None else slot.replacement
                )
                if (key.startswith("dorm")) and plan[key][idx].agent == "Free":
                    # 动态床位允许空着；补床由需要休息的候选触发。
                    continue
                # 如果是空房间
                if name == "":
                    if not need_fix:
                        fix_plan[key] = ["Current"] * len(plan[key])
                        need_fix = True
                    fix_plan[key][idx] = plan[key][idx].agent
                    continue
                # 随意人员则跳过
                if plan[key][idx].agent == "Free":
                    continue
                if not (
                    name == plan[key][idx].agent
                    or (
                        (name in replacements and name not in TRADE_ORDER_AGENTS)
                        and len(replacements) > 0
                    )
                ):
                    if not need_fix:
                        fix_plan[key] = ["Current"] * len(plan[key])
                        need_fix = True
                    fix_plan[key][idx] = plan[key][idx].agent
        # 最后如果有任何高效组心情没有记录 或者高效组在宿舍
        # 宿舍绑组成员由组状态纠错处理；下班期间离开固定位置是正常状态。
        if (
            not config.conf.mastery_enabled
            and getattr(self, "train_room_state", None) is not None
        ):
            self.train_room_state = None
        protected_training = self._protected_facility_names()
        miss_list = {
            k: v
            for k, v in self.op_data.operators.items()
            if v.not_valid()
            # 列表预估已确认低心情时，不能按默认 24 将恢复成员清退回岗。
            and not (
                v.is_resting()
                and (mood := dorm_candidate_mood(self.op_data, k)) is not None
                and mood < v.upper_limit
            )
            and not (v.group and v.room.startswith("dorm"))
            and not v.multi_group
            and not self.op_data.is_standby(k)
            and k not in protected_training
        }
        if len(miss_list.keys()) > 0:
            # 替换到他应该的位置
            logger.debug(f"高效组心情没有记录{str(miss_list)}")
            for key in miss_list:
                _agent = miss_list[key]
                if (
                    _agent.group != ""
                    and self.op_data.group_is_resting(_agent.group)
                    and (
                        _agent.workaholic
                        or self.op_data.rest_mood_complete(key)
                        or _agent.time_stamp is not None
                        and (
                            _agent.current_mood() >= _agent.upper_limit
                            or not getattr(
                                self.op_data, "mood_calculation_enabled", False
                            )
                            and _agent.mood >= _agent.upper_limit
                        )
                    )
                ):
                    logger.debug(f"跳过检查{_agent}")
                    continue
                elif (
                    _agent.group
                    and self.op_data.is_group_shift_anchor(_agent)
                    and (_agent.current_room, _agent.current_index)
                    != (_agent.room, _agent.index)
                ):
                    # 原位重读只核对该成员，实际回岗才补齐组内回班安排。
                    _add_group_to_fix_plan(fix_plan, self.op_data, _agent.group)
                if _agent.room not in fix_plan.keys():
                    fix_plan[_agent.room] = ["Current"] * len(
                        self.op_data.plan[_agent.room]
                    )
                fix_plan[_agent.room][_agent.index] = key
                # 如果是错位：
                if (
                    _agent.current_index != -1 and _agent.current_index != _agent.index
                ) or (_agent.current_room != "" and _agent.room != _agent.current_room):
                    moved_room = _agent.current_room
                    moved_index = _agent.current_index
                    # 真实位置可能在未配置的训练室；只恢复排班明确管理的原槽位。
                    moved_slots = self.op_data.plan.get(moved_room, [])
                    if 0 <= moved_index < len(moved_slots):
                        fix_plan.setdefault(moved_room, ["Current"] * len(moved_slots))[
                            moved_index
                        ] = moved_slots[moved_index].agent
        from arknights_mower.utils.resting_correction import (
            covered_recovery_members,
            off_duty_full_recovery_members,
        )

        intentional_resting_groups = {
            self.op_data.operators[name].group
            for name in covered_recovery_members(self.op_data)
        }
        # 副表明确部分离岗后，同组仍有人在岗不等于需要提前召回恢复成员。
        for g in self.op_data.groups:
            if g in intentional_resting_groups:
                continue
            g_agents = [
                name
                for name in self.op_data.groups[g]
                if not self.op_data.operators[name].room.startswith("dorm")
                and not self.op_data.operators[name].multi_group
                and not self.op_data.operators[name].workaholic
                and not self.op_data._can_standby(self.op_data.operators[name])
            ]
            is_any_working = next(
                (
                    x
                    for x in g_agents
                    if self.op_data.operators[x].current_room != ""
                    and not self.op_data.operators[x].is_resting()
                ),
                None,
            )
            if is_any_working is not None:
                # 确保所有人同时在上班
                is_any_resting = next(
                    (
                        x
                        for x in g_agents
                        if self.op_data.operators[x].current_room == ""
                        or self.op_data.operators[x].is_resting()
                    ),
                    None,
                )
                if is_any_resting is not None:
                    # 生成纠错任务
                    for x in g_agents:
                        if (
                            self.op_data.operators[x].current_room == ""
                            or self.op_data.operators[x].is_resting()
                        ):
                            room = self.op_data.operators[x].room
                            if room not in fix_plan:
                                fix_plan[room] = ["Current"] * len(plan[room])
                            fix_plan[room][self.op_data.operators[x].index] = x
        if len(fix_plan.keys()) > 0:
            # 不能在房间里安排同一个人 如果有重复则换成Free
            remove_keys = []
            logger.debug(f"Fix_plan {str(fix_plan)}")
            for key in fix_plan:
                if "dormitory" in key:
                    # 如果宿舍差Free干员  则跳过
                    if (
                        next(
                            (e for e in fix_plan[key] if e not in ["Free", "Current"]),
                            None,
                        )
                        is None
                        and skip_dorm
                    ):
                        remove_keys.append(key)
                        continue
            if len(remove_keys) > 0:
                for item in remove_keys:
                    del fix_plan[item]
            # #207：训练室受专精管理或受保护时不参与纠错——弹掉 fix_plan 里的 train 项
            # （受保护时发节流提醒邮件）。fix_plan 拿 op_data 缓存比对静态计划，专精
            # 活跃/受保护时缓存与计划必然错位，不弹会每轮生成训练室纠错（反复进出）。
            self._suppress_train_correction(fix_plan)
            # Prefer replacements after all correction passes; if none are available,
            # retain the original correction's recall instead of blocking it.
            from arknights_mower.utils.resting_correction import (
                prefer_resting_replacements,
            )

            for room, index in explicit_slots:
                if room in fix_plan and 0 <= index < len(fix_plan[room]):
                    fix_plan[room][index] = "Current"
            prefer_resting_replacements(self.op_data, fix_plan, _is_mastery_busy)
            # 整组回班可能补入训练位，仍须经过相同的专精保护。
            self._suppress_train_correction(fix_plan)
        from arknights_mower.utils.resting_correction import (
            correct_group_dorms,
            suppress_completed_dorm_returns,
        )

        if read_rooms and not return_plan:
            _merge_plan_overlay(
                fix_plan, self._observed_group_return_plan(), self.op_data
            )
        if self.op_data.has_dorm_groups():
            correct_group_dorms(self.op_data, fix_plan, _is_mastery_busy)
        if read_rooms:
            from arknights_mower.utils.resting_correction import (
                reconsider_low_mood_replacements,
            )

            reconsider_low_mood_replacements(self.op_data, fix_plan, _is_mastery_busy)
        suppress_completed_dorm_returns(self.op_data, fix_plan)
        departed = (
            covered_recovery_members(self.op_data)
            | off_duty_full_recovery_members(self.op_data)
        ) - protected_training
        # 固定宿管位上的恢复成员也必须先迁入合法床位，不能在纠错中丢失。
        displaced_recovery = {
            name
            for name, op in self.op_data.operators.items()
            if op.is_high()
            and op.is_resting()
            and not op.room.startswith("dorm")
            and not op.workaholic
            and name not in protected_training
            and self.op_data.get_dorm_by_name(name)[1] is None
            and (mood := dorm_candidate_mood(self.op_data, name)) is not None
            and mood < op.upper_limit
            and fix_plan.get(op.current_room, [])[
                op.current_index : op.current_index + 1
            ]
            not in ([], ["Current"], [name])
        }
        departed.update(displaced_recovery)
        # 组内部分显式下班不授权纠错召回仍在恢复的成员。
        for room, row in fix_plan.items():
            for index, name in enumerate(row):
                if name in departed and not room.startswith("dorm"):
                    row[index] = "Current"
        recovery_plan = copy.deepcopy(fix_plan)
        if self._complete_departed_recovery(
            recovery_plan, departed, reserved_slots=explicit_slots
        ):
            fix_plan = recovery_plan
        else:
            for name in displaced_recovery:
                op = self.op_data.operators[name]
                fix_plan[op.current_room][op.current_index] = "Current"
        explicit = {}
        for room, index in explicit_slots:
            if room in plan and 0 <= index < len(plan[room]):
                current = self.op_data.get_current_operator(room, index)
                explicit.setdefault(room, ["Current"] * len(plan[room]))[index] = (
                    current.name if current else "Free"
                )
        _merge_shift_transition(fix_plan, explicit, self.op_data)
        # 先移除仍在等待恢复的回班动作，再由剩余意图解析共享宿舍岗位。
        self._suppress_retained_arrangements(fix_plan)
        changed_plan = copy.deepcopy(fix_plan)
        for room, names in changed_plan.items():
            for index, name in enumerate(names):
                current = self.op_data.get_current_operator(room, index)
                if current is not None and current.name == name:
                    names[index] = "Current"
        if not self.op_data.normalize_shared_arrangement(
            fix_plan,
            transitions=self.op_data.arrangement_group_transitions(changed_plan),
            explicit_slots=explicit_slots,
            excluded_names=self._protected_facility_names(),
            excluded_replacements=self._protected_facility_names(
                include_configured=False
            ),
        ):
            logger.debug("多绑组纠错替班暂不可用，保留当前安排")
            return {} if return_plan else None
        self._suppress_train_correction(fix_plan)
        self._suppress_retained_arrangements(fix_plan)
        if return_plan:
            return fix_plan
        if len(fix_plan.keys()) > 0:
            # 如果5分钟之内有任务则跳过心情读取
            next_task = self.find_next_task()
            next_shift_off = self.find_next_task(task_type=TaskTypes.SHIFT_OFF)
            second = (
                0
                if next_task is None
                else (next_task.time - datetime.now()).total_seconds()
            )
            # 如果下个任务的操作时间超过下个任务，则跳过
            shift_off_blocks = next_shift_off is not None and not (
                force and next_shift_off is self.task
            )
            if (
                not force
                and next_task is not None
                and len(fix_plan.keys()) * 45 > second
            ) or shift_off_blocks:
                logger.info("有未完成的任务，跳过纠错")
                self.skip()
                return
            else:
                correction = SchedulerTask(
                    task_plan=fix_plan, task_type=TaskTypes.SELF_CORRECTION
                )
                correction.derived_correction = True
                correction.initial_staffing = getattr(
                    self, "_initial_staffing_pending", False
                )
                correction.correction_skip_dorm = skip_dorm
                current_task = getattr(self, "task", None)
                duplicate = next(
                    (
                        task
                        for task in self.tasks
                        if task is not current_task
                        and task.type == TaskTypes.SELF_CORRECTION
                        and task.plan == fix_plan
                    ),
                    None,
                )
                if duplicate is not None:
                    logger.info("已存在相同纠错任务，跳过重复生成")
                    return "self_correction"
                self.tasks.append(correction)
                self._log_arrangement("已生成任务", task=correction)
                return "self_correction"

    def _train_mastery_active(self) -> bool:
        """训练室是否受专精管理：自动专精生效，且 DB 有 active 计划或队列有专精任务。

        #59：队列重启后可能没补回来，DB 为准；队列补队覆盖「idle 计划即将排」的竞态窗口。
        """
        if not config.conf.mastery_enabled:
            return False
        try:
            from arknights_mower.utils.mastery_db import get_active_plan

            if get_active_plan() is not None:
                return True
        except Exception:
            pass
        return any(
            task.type in (TaskTypes.SKILL_UPGRADE, TaskTypes.SWAP_SUPPORT)
            for task in self.tasks
        )

    def _train_protected(self) -> bool:
        """复用可靠的空闲保护深读；缺少当前观察时按协助位保守保护。"""
        if not config.conf.mastery_enabled:
            return False
        state = getattr(self, "train_room_state", None)
        # 空闲房间的保护结论来自本次可靠的两槽读取和技能深读。此时不能再用
        # op_data 中的旧协助位推断保护，否则专精已结束仍会把训练位锁作替班。
        if (
            getattr(state, "state", None) == "empty"
            and getattr(state, "slots_read", False) is True
            and getattr(state, "slots_reliable", False) is True
            and getattr(state, "read_failed", False) is not True
            and self._training_observation_matches(state)
        ):
            return getattr(state, "protected", False) is True
        return self.op_data.get_train_support() in ("逻各斯", "艾丽妮")

    def _training_observation_matches(self, state) -> bool:
        """两槽观察必须仍对应实际缓存，换人后的旧空闲观察不能继续放行。"""
        observed = (
            getattr(state, "support_slot", ""),
            getattr(state, "train_slot", ""),
        )
        occupants = [
            op for op in self.op_data.operators.values() if op.current_room == "train"
        ]
        return len(occupants) == sum(bool(name) for name in observed) and all(
            op.current_index in (0, 1) and observed[op.current_index] == op.name
            for op in occupants
        )

    def _training_replacement_allowed(self, operator) -> bool:
        """可靠观察允许未被专精接管的训练室岗位参与普通替班。"""
        if operator.current_room != "train":
            return False
        if any(
            slot.agent == operator.name for slot in self.op_data.plan.get("train", [])
        ):
            return False
        state = getattr(self, "train_room_state", None)
        if not (
            config.conf.mastery_enabled
            and getattr(state, "state", None)
            in ("empty", "training", "waiting_collect")
            and getattr(state, "slots_read", False) is True
            and getattr(state, "slots_reliable", False) is True
            and getattr(state, "read_failed", False) is not True
            and operator.current_index not in self._protected_training_slots()
            and self._training_observation_matches(state)
        ):
            return False
        return True

    def _suppress_train_correction(self, fix_plan: dict) -> None:
        """纠错使用统一训练室保护范围。"""
        if "train" in fix_plan and not config.conf.mastery_enabled:
            self.train_room_state = None
        if self._suppress_facility_arrangement(fix_plan):
            self._notify_train_correction_skipped()

    def _evaluate_backup_selection(self, data=None):
        """副表条件和驻员过滤共用当前训练室保护判断。"""
        if data is None:
            data = self.op_data
        data.training_scheduling_protected = bool(self._protected_training_slots())
        return data.evaluate_backup_selection()

    def _protected_training_slots(self):
        """专精接管的岗位不参与普通排班；开启跟随时保留协助位。"""
        if not config.conf.mastery_enabled:
            return set()
        state = getattr(self, "train_room_state", None)
        protected = (
            self._train_mastery_active()
            or self._train_protected()
            or any(
                getattr(state, field, False) is True
                for field in (
                    "locked",
                    "protected",
                    "read_failed",
                    "amiya_form_waiting",
                )
            )
            or getattr(state, "slots_read", False) is True
            and getattr(state, "slots_reliable", False) is not True
        )
        if not protected:
            return set()
        if getattr(state, "amiya_form_waiting", False) is True:
            return {0, 1}
        return {1} if config.conf.assistant_follows_schedule else {0, 1}

    def _protected_training_names(self, *, include_configured=True):
        """换班可排除配置岗位成员；替班禁用只取实际训练室驻员。"""
        slots = self._protected_training_slots()
        return {
            op.name
            for op in self.op_data.operators.values()
            if op.current_room == "train"
            and op.current_index in slots
            or include_configured
            and op.room == "train"
            and op.index in slots
        }

    def _protected_facility_names(self, *, include_configured=True):
        """返回训练室及本轮停用回收站在对应判断中的保护名单。"""
        names = self._protected_training_names(include_configured=include_configured)
        if getattr(self, "_recycle_unavailable", False) is True:
            names.update(
                op.name
                for op in self.op_data.operators.values()
                if op.room == "recycle" or op.current_room == "recycle"
            )
        return names

    def _disable_recycling(self):
        """一级回收站的两人安排只告警一次，本轮运行不再操作该设施。"""
        if getattr(self, "_recycle_unavailable", False) is True:
            return
        self._recycle_unavailable = True
        logger.warning(
            "一级回收站仅有一个岗位，但排班配置了两名干员；"
            "本轮运行跳过回收站的读取、收取和换人，其他设施继续调度。"
            "请将回收站排班改为一人或升级设施，重新启动后再检查。"
        )

    def _suppress_facility_arrangement(self, plan: dict) -> bool:
        """排除受保护设施及相关驻员，保留其他房间的安排。"""
        notify_training = self._suppress_train_arrangement(plan)
        if (
            getattr(self.op_data, "recycle_capacity", 2) == 1
            and len(plan.get("recycle", ())) > 1
        ):
            self._disable_recycling()
        if getattr(self, "_recycle_unavailable", False) is not True:
            return notify_training
        plan.pop("recycle", None)
        protected = self._protected_facility_names(include_configured=False)
        for room, names in list(plan.items()):
            for index, name in enumerate(names):
                actual = self.op_data.get_current_operator(room, index)
                if name in protected or actual is not None and actual.name in protected:
                    names[index] = "Current"
            if all(name == "Current" for name in names):
                del plan[room]
        return notify_training

    def _suppress_train_arrangement(self, fix_plan: dict) -> bool:
        """排除被接管的训练岗位与实际驻员，其他岗位继续换班。"""
        slots = self._protected_training_slots()
        if not slots:
            return False
        protected = self._protected_training_names(include_configured=False)
        removed = "train" in fix_plan and slots == {0, 1}
        for room, names in list(fix_plan.items()):
            changed = False
            for index, name in enumerate(names):
                actual = self.op_data.get_current_operator(room, index)
                if (
                    room == "train"
                    and index in slots
                    or name in protected
                    or actual is not None
                    and actual.name in protected
                ):
                    names[index] = "Current"
                    changed = True
            if changed and all(name == "Current" for name in names):
                del fix_plan[room]
        return (
            removed
            and not self._train_mastery_active()
            and (
                self._train_protected()
                or getattr(getattr(self, "train_room_state", None), "protected", False)
                is True
            )
        )

    def _notify_train_correction_skipped(self) -> None:
        """训练室受保护导致纠错跳过 → 发节流提醒邮件（⑤ protected，key=协助位:训练位）。

        复用 ⑤ 类型与其 key 约定（铁律 8 通知共 8 类）；与 mastery_reader 的
        _notify_protected（mower 无法开始训练）同 key 去重——同一受保护组合至多一封。
        """
        from arknights_mower.utils.email import send_message
        from arknights_mower.utils.mastery_db import should_notify

        current = self.op_data.get_current_room("train", True)
        support = current[0] if current and current[0] else "未知"
        train_slot = current[1] if current and len(current) > 1 and current[1] else "空"
        key = f"{support}:{train_slot}"
        if should_notify("protected", key):
            msg = (
                f"训练室受保护（协助位 {support}，训练位 {train_slot}），"
                "为保留当前训练位干员的专精减半效果，排班纠错已跳过该训练室。"
                "如需更换训练位干员，请先确认放弃减半效果，再手动清空训练室协助位的减半干员；"
                "mower 下次进入训练室确认保护解除后恢复换人。"
            )
            send_message(msg, subject="训练室受保护，已跳过排班纠错", level="WARNING")

    def generate_product(self, agent: str, *, task=None, snapshot=None):
        """
        Process materials in a factory with specified operators
        Args:
            agent: List of operators that need two production cycles
        """

        from arknights_mower.utils.workshop_automation import (
            restore_if_no_plans,
            workshop_task_snapshot,
        )
        from arknights_mower.utils.workshop_config import workshop_lock
        from arknights_mower.utils.workshop_limits import (
            batch_delta,
            batch_limit,
            blocked_workshop_recipes,
            deer_batch_limit,
            deer_recipe_ready,
            recipe_quantities,
            reject_workshop_recipe,
            workshop_candidate_mood,
        )
        from arknights_mower.utils.workshop_mood import mood_cost, operator_mood_rules

        try:
            if snapshot is None:
                snapshot = workshop_task_snapshot(task)
            if snapshot is None or not snapshot.is_current():
                return
            settings = snapshot.settings
            is_9colored = agent == "九色鹿"
            deer_page_changed = object()

            def deer_gap():
                for attempt in range(3):
                    if attempt:
                        self.sleep()
                        self.recog.update()
                        if self.factory_scene() != Scene.FACTORY_DASHBOARD:
                            return deer_page_changed
                    causality = self.digit_reader.get_deer_causality(self.recog.gray)
                    if causality is not None:
                        return 40 - causality
                logger.error("九色鹿因果数字模板匹配失败，停止加工")
                return None

            if agent not in [s.operator for s in settings]:
                logger.info(f"当前干员{agent}不在加工站配置中")
                return
            item_list = next((s.items for s in settings if s.operator == agent))
            from arknights_mower.utils.workshop_recommendation import (
                scope_workshop_items,
            )

            item_list = scope_workshop_items(agent, item_list, workshop_formula)
            if not item_list:
                logger.info(f"{agent}没有符合材料范围的加工配置，跳过")
                return
            operator = self.op_data.operators[agent]
            mood = workshop_candidate_mood(self.op_data, agent)
            mood_budget = max(0, min(24, mood)) if mood is not None else 0
            if mood_budget < 1:
                logger.info(f"{agent}心情不足1点，跳过加工任务")
                return
            if getattr(self.op_data, "mood_calculation_enabled", False):
                # 卡片下界只收紧预测，不写入房间实读或刷新观测时间。
                self.op_data.mood_model.moods[agent] = mood_budget
                self.op_data.mood_model.revision += 1
            restore_if_no_plans()
            if not snapshot.is_current():
                return
            mood_rules, mood_rules_known = operator_mood_rules(
                agent,
                assume_maximum=getattr(self.op_data, "mood_calculation_enabled", False),
            )
            unknown_cnt = 0
            inventory_data = get_inventory_counts()
            seen = set()
            group = defaultdict(dict)
            recipe_moods = {}
            for item in item_list:
                for name in item.item_names:
                    if name in seen:
                        logger.warning(
                            f"当前干员{agent}的加工站配置中存在重复材料{item.item_names}，以第一个设置为准"
                        )
                        continue
                    seen.add(name)
                    metadata = workshop_formula[name]
                    if is_9colored and metadata["apCost"] > 4:
                        logger.warning("跳过心情大于4消耗的材料")
                    else:
                        group[metadata["tab"]][name] = item
                        recipe_moods[name] = mood_cost(
                            name, metadata, mood_rules, mood_rules_known
                        )
            blocked_materials = set()
            gap = None

            def available_groups():
                rejected = blocked_workshop_recipes(inventory_data)
                eligible_groups = {
                    tab: eligible
                    for tab, entries in group.items()
                    if (
                        eligible := {
                            name: setting
                            for name, setting in entries.items()
                            if name not in blocked_materials
                            and name not in rejected
                            and (
                                not is_9colored
                                or gap is None
                                or deer_recipe_ready(workshop_formula[name], gap)
                            )
                            and recipe_moods[name] <= mood_budget
                            and batch_limit(
                                name,
                                workshop_formula[name],
                                setting,
                                inventory_data,
                                operator=agent,
                            )
                            > 0
                        }
                    )
                }
                if is_9colored and eligible_groups:
                    tab, entries = next(iter(eligible_groups.items()))
                    name, setting = next(iter(entries.items()))
                    return {tab: {name: setting}}
                return eligible_groups

            tab_queue = deque(available_groups().items())
            reset_scan = True
            if not tab_queue:
                logger.info(
                    f"{agent}当前心情{mood_budget:.2f}，没有可加工材料，跳过加工"
                )
                return
            tab_pos = {
                name: scale_point(self.recog, point)
                for name, point in FORMULA_TABS.items()
            }
            current_material = None
            current_name = None
            tasks = ["enter", "select", "process"]
            inf_material = "基建材料"
            start_time = datetime.now()
            while tasks:
                if not snapshot.is_current():
                    break
                if datetime.now() - start_time > timedelta(
                    minutes=5
                ):  # 检测是否超过 5 分钟
                    raise Exception("循环运行时间超过 5 分钟，可能卡死")
                scene = self.factory_scene()
                if tasks[0] == "open_formula" and scene in (
                    Scene.FACTORY_ROOM,
                    Scene.INFRA_MAIN,
                ):
                    tasks[0] = "select"
                if scene == Scene.UNKNOWN:
                    unknown_cnt += 1
                    if unknown_cnt > 5:
                        unknown_cnt = 0
                        self.back_to_infrastructure()
                        self.enter_room("factory")
                        if tasks[0] == "open_formula":
                            tasks[0] = "select"
                    else:
                        self.sleep()
                elif scene == Scene.CONNECTING:
                    self.sleep()
                elif self.find("arrange_check_in") or self.find(
                    "arrange_check_in_small"
                ):
                    self.tap(scale_point(self.recog, CONFIRM_OPERATOR), interval=0.5)
                elif scene == Scene.FACTORY_DASHBOARD:
                    if tasks[0] == "enter":
                        if is_9colored:
                            observed_gap = deer_gap()
                            if observed_gap is deer_page_changed:
                                continue
                            gap = observed_gap
                            if gap is None:
                                return
                            logger.debug(f"初次记录九色鹿技能差值{gap}")
                        del tasks[0]
                    elif tasks[0] == "select":
                        if is_9colored:
                            observed_gap = deer_gap()
                            if observed_gap is deer_page_changed:
                                continue
                            gap = observed_gap
                            if gap is None:
                                return
                            tab_queue = deque(available_groups().items())
                            if not tab_queue:
                                logger.info(
                                    "九色鹿当前因果阶段没有可加工材料，结束加工"
                                )
                                break
                        self.tap(scale_point(self.recog, OPEN_FORMULA), interval=0.5)
                        tasks[0] = "open_formula"
                    elif tasks[0] == "open_formula":
                        # 点击后迟到的工作台帧只继续现有观察，不重复输入或读因果。
                        pass
                    else:
                        add_btn = (self.recog.w * 0.84, self.recog.h * 0.4)
                        inventory_data = get_inventory_counts()
                        batch_count = batch_limit(
                            current_name,
                            current_material,
                            group[current_material["tab"]][current_name],
                            inventory_data,
                            operator=agent,
                        )
                        if batch_count == 0:
                            tasks.insert(0, "select")
                            tab_queue = deque(available_groups().items())
                            reset_scan = True
                            continue
                        ap_cost = current_material["apCost"]
                        material_tab = current_material["tab"]
                        per_craft_mood = recipe_moods[current_name]
                        batch_count = min(
                            batch_count, int(mood_budget // per_craft_mood)
                        )
                        if batch_count == 0:
                            blocked_materials.add(current_name)
                            tasks.insert(0, "select")
                            tab_queue = deque(available_groups().items())
                            reset_scan = True
                            continue
                        is_crit = ap_cost == 4 and material_tab == "精英材料"
                        if is_9colored:
                            mood = (
                                mood_budget
                                if getattr(
                                    self.op_data, "mood_calculation_enabled", False
                                )
                                else self.op_data.operators[agent].mood
                            )
                            observed_gap = deer_gap()
                            if observed_gap is deer_page_changed:
                                continue
                            gap = observed_gap
                            if gap is None:
                                return
                            logger.debug(f"九色鹿技能差值{gap}")
                            if gap > 40:
                                logger.error("识别九色鹿阈值出错拉!任务停止")
                                return
                            if 0 <= gap < 5:
                                if mood >= 4:
                                    if not is_crit:
                                        tasks.insert(0, "select")
                                        tab_queue = deque(available_groups().items())
                                        reset_scan = True
                                        logger.info(
                                            "检测到九色鹿即将暴击，即将切换成暴击用材料"
                                        )
                                        continue
                                else:
                                    logger.info("暴击心情不足，任务结束")
                                    tasks = []
                                    continue
                            if gap >= 5:
                                if is_crit:
                                    tasks.insert(0, "select")
                                    tab_queue = deque(available_groups().items())
                                    reset_scan = True
                                    logger.info("切换成垫刀材料")
                                    continue
                            batch_count = (
                                1
                                if is_crit
                                else min(batch_count, deer_batch_limit(gap, ap_cost))
                            )
                        produce_btn = (self.recog.w * 0.88, self.recog.h * 0.88)
                        batch_count = int(batch_count)
                        output, _, costs = recipe_quantities(
                            current_name, current_material
                        )
                        product = {"name": current_name, "item": output}
                        logger.info(
                            f"[[operator:{agent}]]加工{current_name}：库存{inventory_data[output]}，"
                            f"上限{group[material_tab][current_name].self_upper_limit}，"
                            f"本批最多{batch_count}次",
                            extra={
                                "log_room": "factory",
                                "log_agents": [agent],
                                "log_event": {"type": "workshop-material", **product},
                            },
                        )
                        # The selected formula starts at one, as in the deer logic.
                        # Never use MAX: mood can allow more than the stock deficit.
                        for _ in range(batch_count - 1):
                            self.tap(add_btn, interval=0.1)
                        warning = self.find("factory_warning")
                        valid = self.item_valid()
                        if warning or not valid:
                            if not valid and not warning:
                                # Retain the rejection across workers with the same stock.
                                reject_workshop_recipe(current_name, inventory_data)
                                blocked_materials.add(current_name)
                                tasks.insert(0, "select")
                                tab_queue = deque(available_groups().items())
                                reset_scan = True
                                logger.info("检测到当前材料用完，切换其他材料")
                                continue
                            tasks = []
                            logger.info("检测到干员心情见底或材料不足，任务结束")
                            if not getattr(
                                self.op_data, "mood_calculation_enabled", False
                            ):
                                self.op_data.operators[agent].mood = 0
                                self.op_data.operators[
                                    agent
                                ].time_stamp = datetime.now()
                                self.op_data.operators[agent].mood_is_prediction = True
                            continue
                        batches = batch_count
                        mood_event_id = str(uuid4())
                        mood_delta = {agent: -batches * per_craft_mood}
                        submission_attempted = False
                        try:
                            # Only submission holds the config lock; result reads don't.
                            with workshop_lock:
                                if not snapshot.is_current():
                                    break
                                if getattr(
                                    self.op_data, "mood_calculation_enabled", False
                                ):
                                    self.op_data.mood_model.begin_event(
                                        mood_event_id, mood_delta
                                    )
                                    if save_current_state() is False:
                                        self.op_data.mood_model.pending_events.pop(
                                            mood_event_id, None
                                        )
                                        raise RuntimeError(
                                            "加工前无法保存心情事件，取消本次提交"
                                        )
                                submission_attempted = True
                                self.tap(produce_btn, interval=2)
                            for _ in range(11):
                                if (
                                    self.factory_scene()
                                    == Scene.FACTORY_PRODUCT_COLLECT
                                ):
                                    break
                                self.sleep()
                            else:
                                raise ValueError("未确认加工完成")
                            self.recog.save_screencap("workshop")
                            delta = batch_delta(
                                current_name, current_material, batches, operator=agent
                            )
                            apply_workshop_inventory(delta)
                            if getattr(self.op_data, "mood_calculation_enabled", False):
                                self.op_data.mood_model.event(mood_event_id, mood_delta)
                                # 固定成本给出保守预测；条件减耗与返还留待正常读房校准。
                                save_current_state()
                        except Exception:
                            if submission_attempted:
                                uncertain = [output, *costs]
                                if current_material.get("goldCost"):
                                    uncertain.append("龙门币")
                                invalidate_workshop_inventory(uncertain)
                                send_message(
                                    f"{agent}加工{current_name}后未能确认加工完成，"
                                    "已暂停相关材料的加工，请重新读取仓库。",
                                    subject="材料加工结果未确认",
                                    level="WARNING",
                                )
                            raise
                        # Finish Deer's current fodder/T4 cycle before replacing
                        # its bounded quota or dispatching prepared training.
                        finish_deer_cycle = is_9colored and not is_crit
                        if config.conf.mastery_enabled and not finish_deer_cycle:
                            from arknights_mower.utils.mastery_recommendation import (
                                auto_schedule_mastery_tasks,
                            )

                            try:
                                ready = auto_schedule_mastery_tasks(
                                    inventory=get_inventory_counts()
                                )
                                self._dispatch_scan_start_tasks(ready["scheduled"])
                            except MowerExit:
                                raise
                            except Exception:
                                logger.exception("加工库存已确认，但专精任务派发失败")
                        if config.conf.workshop_auto_active and not finish_deer_cycle:
                            from arknights_mower.utils.workshop_automation import (
                                update_workshop_config,
                            )

                            update_workshop_config()
                        logger.info(
                            f"[[operator:{agent}]]加工{current_name}完成{batches}次，"
                            "库存变化："
                            + "、".join(
                                f"{name}{change:+d}" for name, change in delta.items()
                            ),
                            extra={
                                "log_room": "factory",
                                "log_agents": [agent],
                                "log_event": {
                                    "type": "workshop-result",
                                    "product": product,
                                    "changes": [
                                        {"name": name, "delta": change}
                                        for name, change in delta.items()
                                    ],
                                },
                            },
                        )
                        inventory_data = get_inventory_counts()
                        blocked_materials.clear()
                        mood_budget = max(0, mood_budget - batches * per_craft_mood)
                        if is_9colored:
                            gap = None
                        if not getattr(self.op_data, "mood_calculation_enabled", False):
                            operator.mood = mood_budget
                            operator.time_stamp = datetime.now()
                            operator.mood_is_prediction = True
                        tab_queue = deque(available_groups().items())
                        if not tab_queue:
                            logger.info(
                                f"{agent}当前心情{mood_budget:.2f}，已无可加工材料，结束加工"
                            )
                            break
                        tasks.insert(0, "select")
                        reset_scan = True
                elif scene == Scene.FACTORY_FORMULA:
                    if tasks[0] == "open_formula":
                        tasks[0] = "select"
                    if tasks[0] in ["enter", "process"]:
                        self.back()
                    else:
                        if reset_scan:
                            # 重新切换材料则重头开始
                            self.tap(tab_pos["芯片"], interval=0.2)
                            self.tap(tab_pos[inf_material], interval=0.2)
                            logger.debug("切换到基建材料页")
                            reset_scan = False
                        if not tab_queue:
                            logger.info("没有任何材料满足条件，任务结束")
                            tasks = []
                            continue
                        tab, item_list = tab_queue.popleft()
                        item_list = set(item_list)
                        self.tap(tab_pos[tab], interval=0.2)
                        logger.info(f"开始检索{tab}的材料")
                        logger.debug(
                            f"[workshop-scan] tab={tab} initial_candidates={sorted(item_list)}"
                        )
                        last_scaned = []
                        scan_round = 0
                        while item_list:
                            scanned_items = self.item_list()
                            current_scan = [item for item, pos, valid in scanned_items]
                            logger.debug(
                                f"[workshop-scan] tab={tab} round={scan_round} "
                                f"current_scan={current_scan} remaining_candidates={sorted(item_list)}"
                            )
                            if current_scan == last_scaned:
                                logger.debug(
                                    f"[workshop-scan] tab={tab} reached_bottom "
                                    f"round={scan_round} last_scan={last_scaned}"
                                )
                                logger.info("已经到底了")
                                break
                            last_scaned = current_scan
                            for item, pos, valid in scanned_items:
                                if item in item_list:
                                    recipe = workshop_formula[item]
                                    quantities = recipe_quantities(item, recipe)
                                    produced_item = (
                                        quantities[0] if quantities else item
                                    )
                                    log_extra = {
                                        "log_room": "factory",
                                        "log_event": {
                                            "type": "workshop-material",
                                            "name": item,
                                            "item": produced_item,
                                        },
                                    }
                                    good_to_go = True
                                    if is_9colored:
                                        good_to_go = deer_recipe_ready(recipe, gap)
                                    if valid and good_to_go:
                                        logger.info(
                                            f"检测到{item}满足条件，开始加工",
                                            extra=log_extra,
                                        )
                                        self.tap(
                                            (
                                                (pos[0][0] + pos[1][0]) / 2,
                                                (pos[0][1] + pos[1][1]) / 2,
                                            ),
                                            interval=0.5,
                                        )
                                        current_material = recipe
                                        current_name = item
                                        item_list = []
                                        del tasks[0]
                                        break
                                    else:
                                        if not valid:
                                            reject_workshop_recipe(item, inventory_data)
                                            blocked_materials.add(item)
                                        logger.info(
                                            f"检测到{item}不满足条件，跳过",
                                            extra=log_extra,
                                        )
                                        item_list.remove(item)
                            scan_round += 1
                            self.swipe_noinertia(
                                (0.5 * self.recog.w, 0.9 * self.recog.h),
                                (0, -700),
                                interval=1,
                            )
                        if (
                            is_9colored
                            and tasks
                            and tasks[0] == "select"
                            and not item_list
                        ):
                            # The first candidate may have been rejected on screen.
                            # Rebuild in saved order so this visit can use its fallback.
                            tab_queue = deque(available_groups().items())
                            reset_scan = True

                elif scene == Scene.FACTORY_PRODUCT_COLLECT:
                    self.recog.save_screencap("workshop")
                    self.back()
                elif scene == Scene.FACTORY_ROOM:
                    self.tap((self.recog.w * 0.1, self.recog.h * 0.95), 0.5)
                elif scene == Scene.INFRA_MAIN:
                    self.enter_room("factory")
                self.recog.update()
            self.back()
            self.back_to_infrastructure()
        except MowerExit:
            raise
        except Exception as e:
            save_exception(e)
            logger.exception(e)
            return False

    def _sync_run_order_tasks(self):
        op_data = getattr(self, "op_data", None)
        op_data.refresh_run_order_rooms()
        if self._emergency_frozen():
            self._emergency_filter_tasks()
        # 缺员等待没有插拔或恢复副作用，失去跑单资格时结束读取责任。
        self.tasks[:] = [
            task
            for task in self.tasks
            if not (
                run_order_waits_for_staffing(task)
                and task.meta_data not in op_data.run_order_rooms
            )
        ]
        invalid_rooms = {
            task.meta_data
            for task in task_view(self.tasks, TaskScope.REPLAN)
            if task.type in (TaskTypes.RUN_ORDER, TaskTypes.REFRESH_TIME)
            and task.meta_data
            and (
                task.meta_data not in op_data.run_order_rooms
                or task.type == TaskTypes.RUN_ORDER
                and bool(getattr(task, "run_order_collect_only", False))
                != op_data.is_order_collection_room(task.meta_data)
            )
        }
        self._invalidate_order_estimates(invalid_rooms)

    def _invalidate_order_estimates(self, rooms):
        """仅作废可重规划的订单估计，保留未完成执行与原班恢复。"""
        invalid_ids = {
            id(task)
            for task in task_view(self.tasks, TaskScope.REPLAN)
            if task.type in (TaskTypes.RUN_ORDER, TaskTypes.REFRESH_TIME)
            and task.meta_data in rooms
            and not hasattr(task, "emergency_original_roster")
            and not getattr(task, "run_order_restore_pending", False)
            and not getattr(task, "maintenance_replacement_run", False)
        }
        self.tasks[:] = [task for task in self.tasks if id(task) not in invalid_ids]
        self._prune_order_read_log_cohorts()

    def _queue_order_refresh(self, room):
        """每个跑单房间只保留一份未完成的订单读取或执行责任。"""
        if room not in self.op_data.run_order_rooms:
            return
        pending = next(
            (
                task
                for task in task_view(self.tasks, TaskScope.PENDING)
                if task.type in (TaskTypes.RUN_ORDER, TaskTypes.REFRESH_TIME)
                and (
                    task.meta_data == room
                    or room in task.plan
                    or room in getattr(task, "run_order_original_roster", {})
                    or room in getattr(task, "emergency_original_roster", {})
                )
            ),
            None,
        )
        if pending is not None:
            return (
                pending
                if pending.type == TaskTypes.REFRESH_TIME and pending.meta_data == room
                else None
            )
        refresh = SchedulerTask(task_type=TaskTypes.REFRESH_TIME, meta_data=room)
        self.tasks.append(refresh)
        return refresh

    def _discard_legacy_run_order_waits(self):
        """旧版超窗等待改为正常读单，已开始的原班恢复仍保留。"""
        rooms = set()
        for task in list(self.tasks):
            if getattr(task, "run_order_window_observation", False):
                rooms.add(task.meta_data)
                self.tasks.remove(task)
                continue
            failure = getattr(task, "execution_failure", None) or {}
            countdown_failure = re.match(
                r"订单倒计时 -?\d+(?:\.\d+)? 秒(?:不在|尚未进入)跑单窗口",
                failure.get("reason", ""),
            )
            if task.type != TaskTypes.RUN_ORDER:
                continue
            window_wait = task.__dict__.pop("run_order_window_wait", False)
            if getattr(task, "run_order_restore_pending", False) or not (
                countdown_failure or window_wait and not failure
            ):
                continue
            if hasattr(task, "emergency_original_roster"):
                # 救急临时换人仍有实测原班，先完成恢复再重新读单。
                task.run_order_original_roster = copy.deepcopy(
                    task.emergency_original_roster
                )
                task.run_order_restore_pending = True
                task.prepare_run_order_restoration()
                task.__dict__.pop("execution_failure", None)
                task.execution_retained = True
            else:
                rooms.add(task.meta_data)
                self.tasks.remove(task)
        for room in sorted(rooms):
            # 原班恢复或其他真实执行仍拥有该房间时，不清除其观测或重复读单。
            if any(
                task.meta_data == room and task.type == TaskTypes.RUN_ORDER
                for task in self.tasks
            ):
                continue
            self.reset_room_time(room)
            self._queue_order_refresh(room)
            logger.info("清理旧版跑单倒计时等待，按当前订单重新规划：%s", room)

    def _report_missed_order(self, room, remaining):
        logger.error(
            "检测到漏单：%s 订单倒计时 %s 秒超出跑单窗口",
            room,
            remaining,
            extra={"archive_screenshots": True},
        )
        save_exception(Exception("检测到漏单"))
        room_label = self.translate_room(room) if room in base_room_list else str(room)
        send_message(
            f"检测到漏单：{room_label}。",
            subject="贸易站漏单提醒",
            level="WARNING",
            archive_screenshots=True,
            screenshot_source=getattr(self, "device", None),
        )
        self.reset_room_time(room)

    def _queue_missing_run_order_reads(self):
        """补齐订单读取责任；初始化或维护尚未就绪时返回 False。"""
        if self._initial_mood_read_pending() or getattr(
            self, "_initial_staffing_pending", False
        ):
            return False
        if getattr(self, "maintenance_entry_pending", False) or any(
            getattr(task, "maintenance_replacement_run", False) for task in self.tasks
        ):
            return False
        self._sync_run_order_tasks()
        for room in self.op_data.run_order_rooms:
            if self._emergency_run_order_available(room):
                self._queue_order_refresh(room)
        return True

    def _room_mood_signature(self, room):
        return tuple(
            sorted(
                (operator.name, operator.current_index, operator.time_stamp)
                for operator in self.op_data.operators.values()
                if operator.current_room == room
            )
        )

    def _startup_order_check_fits(self):
        return not any(
            pending.time <= datetime.now() + timedelta(minutes=1)
            and (
                self._is_startup_priority_task(pending)
                or getattr(pending, "strict_mood_limit", False)
                and pending.plan
            )
            for pending in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
        )

    def _initialize_startup_facilities(self):
        """进入基建后统一检查启动设施，沿用完整初始化及救急恢复顺序。"""
        if not getattr(self, "_state_restore_complete", True):
            return
        self._check_startup_run_orders()
        if getattr(self, "_emergency_startup_pending", False):
            if (
                self.task is not None
                and self.task.type == TaskTypes.NOT_SPECIFIC
                and not self.task.plan
                and not self.task.meta_data
            ):
                self.tasks[:] = [task for task in self.tasks if task is not self.task]
                self.task = None
            self._emergency_startup()
            self._refresh_observed_recovery_tasks()
            if self._emergency_active() and not self._emergency_startup_pending:
                self._emergency_tick()
        elif "train" in getattr(self, "_initial_mood_refresh_rooms", ()):
            self._read_agent_mood(rooms={"train"} | set(self.op_data.run_order_rooms))

    def _check_startup_run_orders(self):
        """启动时检查一次订单；临时读数只发布保护窗口内的跑单任务。"""
        if not getattr(self, "_startup_run_order_check_pending", False):
            return
        self._startup_run_order_check_pending = False
        if any(task.type == TaskTypes.RUN_ORDER for task in self.tasks):
            return
        if getattr(self, "maintenance_entry_pending", False) or any(
            getattr(task, "maintenance_replacement_run", False) for task in self.tasks
        ):
            return
        self._sync_run_order_tasks()
        provisional = []
        return_error = None
        for room in list(self.op_data.run_order_rooms):
            if not self._startup_order_check_fits():
                break
            if not self._emergency_run_order_available(room):
                continue
            refresh = self.find_next_task(
                meta_data=room,
                task_type=TaskTypes.REFRESH_TIME,
                scope=TaskScope.PENDING,
            )
            if refresh is not None and getattr(refresh, "execution_failure", None):
                continue
            try:
                execute_time = self.get_run_order_time(room, read_mood=True)
                self._sync_run_order_tasks()
                if execute_time is None or room not in self.op_data.run_order_rooms:
                    continue
                provisional.append(self._new_run_order_task(room, execute_time))
            except (MowerExit, DeviceRecoveryError, SharedADBError):
                raise
            except OrderReturnUnresolved as e:
                return_error = e
                break
            except Exception as e:
                logger.warning("启动检查 %s 订单失败，继续初始化：%s", room, e)
                self.back_to_infrastructure()
        # scheduling 会改写任务，启动的远期读数不能进入持久化任务队列。
        temporary_tasks = copy.deepcopy(self.tasks) + provisional
        try:
            if return_error is None:
                self._adjust_run_orders(temporary_tasks, startup=True)
                self.scene_graph_navigation(Scene.INFRA_MAIN)
        except (MowerExit, DeviceRecoveryError, SharedADBError):
            raise
        except Exception as e:
            logger.warning("启动调整订单失败，继续初始化：%s", e)
            self.back_to_infrastructure()
        deadline = datetime.now() + timedelta(
            minutes=max(10, config.conf.run_order_delay * 2)
        )
        for task in provisional:
            if task.time <= deadline and task.meta_data in self.op_data.run_order_rooms:
                if self.task is not None and self._can_defer_arrangement():
                    self.task.execution_retained = True
                self.tasks.append(task)
                self.tasks[:] = [
                    pending
                    for pending in self.tasks
                    if not (
                        pending.type == TaskTypes.REFRESH_TIME
                        and pending.meta_data == task.meta_data
                        and not getattr(pending, "execution_failure", None)
                    )
                ]

        if return_error is not None:
            raise return_error

    def _new_run_order_task(self, room, execute_time):
        task = SchedulerTask(
            time=execute_time,
            task_plan={room: self.op_data.run_order_plan(room)},
            task_type=TaskTypes.RUN_ORDER,
            meta_data=room,
        )
        task.run_order_collect_only = self.op_data.is_order_collection_room(room)
        return task

    @log_mood_calculation("跑单规划")
    def plan_run_order(self, room):
        """按实际订单倒计时规划跑单。"""
        if any(
            room in getattr(task, "run_order_original_roster", {})
            for task in self.tasks
        ):
            return
        if not self._emergency_run_order_available(room):
            return
        if getattr(self, "maintenance_entry_pending", False) or any(
            getattr(task, "maintenance_replacement_run", False) for task in self.tasks
        ):
            return
        self._sync_run_order_tasks()
        if room not in self.op_data.run_order_rooms:
            return
        if self.find_next_task(
            meta_data=room, task_type=TaskTypes.RUN_ORDER, scope=TaskScope.PENDING
        ):
            return
        refresh = self.find_next_task(
            meta_data=room, task_type=TaskTypes.REFRESH_TIME, scope=TaskScope.PENDING
        )
        if refresh is not None and getattr(refresh, "execution_failure", None):
            return
        previous_request = getattr(self, "_order_read_log_request", None)
        self._order_read_log_request = (room, self._order_read_log_for_refresh(refresh))
        try:
            execute_time = self.get_run_order_time(room)
        finally:
            if previous_request is None:
                self.__dict__.pop("_order_read_log_request", None)
            else:
                self._order_read_log_request = previous_request
        # 实读可能改变订单类型，按最新状态决定收单或插拔。
        self._sync_run_order_tasks()
        if execute_time is None:
            # 暂停订单已实读驻员，空岗位由普通纠错接管，不等待有效倒计时。
            current = self.op_data.get_current_room(room, bypass=True)
            if current and "" in current:
                refresh = self._queue_order_refresh(room)
                if refresh is not None:
                    refresh.run_order_staffing_wait = True
                    self._retain_failed_task(
                        refresh,
                        f"房间 {self.translate_room(room)} 缺少进驻干员，等待进驻后读取订单",
                        [room],
                        dependency=True,
                    )
            if self.task is None:
                self.agent_get_mood(skip_dorm=True, read_rooms=False)
            else:
                # 让出缺员等待或消费本次读取后，继续普通规划。
                self.planned = False
            return True
        if room not in self.op_data.run_order_rooms:
            return
        self.tasks.append(self._new_run_order_task(room, execute_time))
        return True

    def _arrangement_priority_tasks(self):
        from arknights_mower.utils.group_recovery import mood_limit_release_yields

        data = getattr(self, "op_data", None)
        return [
            pending
            for pending in task_view(self.tasks, TaskScope.DISPATCH, data)
            if pending is not getattr(self, "task", None)
            and not mood_limit_release_yields(
                data, pending, getattr(self, "task", None)
            )
            and (
                pending.type == TaskTypes.RUN_ORDER
                and pending.meta_data
                and not getattr(pending, "run_order_restore_pending", False)
                or pending.type == TaskTypes.SWAP_SUPPORT
                and config.conf.mastery_enabled
                or getattr(pending, "strict_mood_limit", False)
                and pending.plan
            )
        ]

    def _read_arrangement_order_times(self, room):
        """整批换班完成后正式读单，失败保留原有独立刷新责任。"""
        if self.task.plan or getattr(self, "_product_batch_active", False):
            return False
        self.task.execution_retained = True
        self._resume_failed_tasks()
        for order_room in self.op_data.run_order_rooms:
            if self._emergency_run_order_available(order_room):
                self._queue_order_refresh(order_room)
        self._read_pending_order_times(room)
        return False

    def _read_pending_order_times(self, room=None):
        """消费可执行的订单读取任务，失败保留原任务并让出调度。"""
        refreshes = [
            refresh
            for refresh in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            if refresh.type == TaskTypes.REFRESH_TIME
            and refresh.meta_data in self.op_data.run_order_rooms
            and refresh.time <= datetime.now()
        ]
        refreshes.sort(key=lambda refresh: refresh.meta_data != room)
        observed_any = False
        for refresh in refreshes:
            if observed_any:
                protect_priority_tasks(self.tasks, op_data=self.op_data)
            if any(
                pending.time <= datetime.now() + timedelta(minutes=1)
                for pending in self._arrangement_priority_tasks()
            ):
                self._retire_order_read_log_refresh(refresh)
                break
            observed_any = True
            try:
                observed = self.plan_run_order(refresh.meta_data)
            except (MowerExit, DeviceRecoveryError, SharedADBError):
                raise
            except OrderReturnUnresolved:
                break
            except Exception as e:
                logger.warning("读取订单失败，保留独立刷新任务：%s", e)
                self._retain_failed_task(refresh, str(e), [refresh.meta_data])
                self.back_to_infrastructure()
                continue
            if observed and not getattr(refresh, "execution_failure", None):
                self.tasks[:] = [task for task in self.tasks if task is not refresh]
            elif not observed:
                self._retire_order_read_log_refresh(refresh)
            self._prune_order_read_log_cohorts()
        if observed_any:
            scheduling(self.tasks, op_data=self.op_data)

    def _arrangement_room_budget(self, room, plan):
        operation = SchedulerTask(
            time=datetime.now(), task_plan={room: plan[room]}, task_type=self.task.type
        )
        margin = timedelta(seconds=60 if room.startswith("dormitory_") else 15)
        return estimate_task_duration(operation, op_data=self.op_data) + margin

    def _can_defer_arrangement(self):
        task = self.task
        return (
            task.type
            in (
                TaskTypes.SELF_CORRECTION,
                TaskTypes.RE_ORDER,
                TaskTypes.SHIFT_ON,
                TaskTypes.SHIFT_OFF,
                TaskTypes.EXHAUST_OFF,
                TaskTypes.NOT_SPECIFIC,
                TaskTypes.FILL_DORM,
            )
            and not getattr(task, "strict_mood_limit", False)
            and not getattr(task, "dorm_recovery_restore", [])
        )

    def _defer_arrangement_for_priority_task(self, room, plan):
        """下一房操作可能挤占关键任务时，保留原安排并让出调度。"""
        if (
            getattr(self, "_product_batch_active", False)
            or not self._can_defer_arrangement()
        ):
            return False
        task = self.task
        now = datetime.now()
        has_dorm = room.startswith("dormitory_")
        finish = now + self._arrangement_room_budget(room, plan)
        deadline = next(
            (
                pending
                for pending in self._arrangement_priority_tasks()
                if (finish >= pending.time if has_dorm else finish > pending.time)
            ),
            None,
        )
        if deadline is None:
            return False
        task.execution_retained = True
        protect_priority_tasks(self.tasks, op_data=self.op_data)
        logger.info(
            "保留 %s 的剩余安排，先执行 %s（%s）",
            task.type.display_value,
            deadline.type.display_value,
            deadline.meta_data,
        )
        return True

    def _adjust_run_orders(self, order_tasks, *, startup=False):
        run_order_rooms = self.op_data.run_order_rooms
        adj_tasks = scheduling(
            order_tasks, op_data=self.op_data
        )  # 修改scheduling 同时输出撞在一起的前后两个任务
        max_execution = 3
        adj_count = 0

        if run_order_rooms is not None and len(run_order_rooms) >= 3:
            n = len(run_order_rooms)
            dp = [0] * (n + 1)
            dp[1] = 0
            if n > 1:
                dp[2] = 1
            for i in range(3, n + 1):
                dp[i] = 3 * dp[i - 1] + 2 * dp[i - 2]
            max_execution = min(
                dp[n] * 1.25, 15
            )  # 通过跑单房间计算得到循环次数 同时限制最大次数
            logger.debug(f"max_execution = {max_execution}")
            logger.debug("跑单设施内部记录：%s", run_order_rooms)
            logger.info(
                "跑单设施：%s",
                "、".join(
                    facility_label(room, self.op_data) for room in run_order_rooms
                ),
            )
            logger.debug(
                f"当前跑单房间数量为：{n}，计算最大循环次数为: {max_execution + 1}"
            )
        while (
            adj_tasks is not None and adj_count <= max_execution
        ):  # 由于改动会增加触发次数 改为<= 多触发一次
            # logger.error("<UNK>,<UNK>")
            adjust_0_room = self.get_run_order_adjust_room(adj_tasks)  # 抽离成单独的
            if adjust_0_room is None:
                logger.error("未能确定需要无人机加速的贸易站，停止调整跑单时间")
                return False
            if startup and not self._startup_order_check_fits():
                return False
            is_run = self.drone(
                adjust_0_room,
                adjust_time=True,
                **({"order_tasks": order_tasks} if startup else {}),
            )
            adj_tasks = scheduling(order_tasks, op_data=getattr(self, "op_data", None))
            adj_count += 1
            logger.debug(f"第{adj_count}次循环结束")
            if is_run is not None and not is_run:
                return False
        return True

    def run_order_solver(self):
        self._sync_run_order_tasks()
        if len(self.op_data.run_order_rooms) > 0:
            valid = True
            if valid:
                # 处理龙舌兰/但书/佩佩的插拔
                run_order_rooms = self.op_data.run_order_rooms
                for k in list(run_order_rooms):
                    self.plan_run_order(k)
                run_order_rooms = self.op_data.run_order_rooms
                if self._adjust_run_orders(self.tasks) is False:
                    return
        fia_plan, fia_room = self.check_fia()
        if fia_room is not None:
            # 副表可能把肥鸭移到另一宿舍或暂时撤下；只读实际所在的槽位。
            actual_room = self.op_data.operators["菲亚梅塔"].current_room
            fia_room = actual_room if actual_room.startswith("dorm") else None
            if fia_room is None:
                self._refresh_fiammetta_task(None)
        if (
            fia_room is not None
            and fia_plan is not None
            and (
                not self._fia_targets_all_full(fia_plan)
                or self._emergency_fia_fallback(fia_plan)
            )
        ):
            if (
                self.find_next_task(
                    task_type=TaskTypes.FIAMMETTA, scope=TaskScope.PENDING
                )
                is None
            ):
                fia_data = self.op_data.operators["菲亚梅塔"]
                fia_idx = (
                    fia_data.current_index
                    if fia_data.current_index != -1
                    else fia_data.index
                )
                if getattr(self.op_data, "mood_calculation_enabled", False):
                    ready_at = self.op_data.calculated_mood_deadline("菲亚梅塔", 24)
                else:
                    self.enter_room(fia_room)
                    result = self.get_agent_from_room(fia_room, [fia_idx])
                    self.back()
                    ready_at = (
                        result[fia_idx].get("time")
                        if fia_idx < len(result)
                        and result[fia_idx].get("agent") == "菲亚梅塔"
                        else None
                    )
                    if ready_at is None:
                        logger.info("肥鸭实际位置已变化，等待纠偏后重新读取充能时间")
                if isinstance(ready_at, datetime):
                    logger.info(
                        "下一次进行菲亚梅塔充能：" + ready_at.strftime("%H:%M:%S")
                    )
                    self.tasks.append(
                        SchedulerTask(time=ready_at, task_type=TaskTypes.FIAMMETTA)
                    )
        if self._emergency_frozen():
            return
        from arknights_mower.utils.backup_group_tasks import forced_work_groups

        working = forced_work_groups(self.op_data)
        for name in self.op_data.exhaust_agent:
            op = self.op_data.operators[name]
            if op.group in working:
                continue
            # skip operator_protected check (TrainingStateMachine removed)
            if (
                op.is_resting()
                or not op.is_high()
                or op.current_room not in base_room_list
            ):
                continue
            if op.current_mood() <= op.lower_limit + 2:
                candidates = self.op_data.groups[op.group] if op.group else [name]
                if self._has_pending_exhausted_shift(candidates):
                    continue
                if (
                    self.find_next_task(
                        task_type=TaskTypes.EXHAUST_OFF,
                        meta_data=op.name,
                        scope=TaskScope.PENDING,
                    )
                    is None
                ):
                    observed_room, observed_index = op.current_room, op.current_index
                    self.enter_room(observed_room)
                    result = self.get_agent_from_room(observed_room, [observed_index])
                    observed = (
                        result[observed_index]
                        if 0 <= observed_index < len(result)
                        else {}
                    )
                    observed_time = observed.get("time")
                    if (
                        observed.get("observed") is False
                        or observed.get("agent") != name
                        or not isinstance(observed_time, datetime)
                    ):
                        logger.warning(f"干员 {name} 的用尽时间未核实，跳过本次预约")
                        self.back()
                        continue
                    _time = datetime.now()
                    margin = (
                        0
                        if op.rest_in_full
                        or op.group in self.op_data.rest_in_full_group
                        else 20
                    )
                    if observed_time > _time:
                        zero_time = observed_time
                        zero_time = Operator.exhaust_time_at_lower_limit(
                            op, zero_time, _time
                        )
                        _time = zero_time - timedelta(minutes=10 + margin)
                    elif (
                        op.current_mood() > 0.25 + op.lower_limit
                        and op.depletion_rate != 0
                    ):
                        _time = (
                            datetime.now()
                            + timedelta(
                                hours=(op.current_mood() - op.lower_limit - 0.25)
                                / op.depletion_rate
                            )
                            - timedelta(minutes=10 + margin)
                        )
                    self.back()
                    exhausted_time = _time < datetime.now()
                    if exhausted_time:
                        logger.info(
                            f"{op.name}的下班任务时间{_time}已早于当前时间，改为立即执行"
                        )
                        _time = datetime.now()
                    # plan 是空的是因为得动态生成
                    update_time = False
                    if op.group != "":
                        # 检查是否有其他同组任务，刷新时间
                        for item in self.op_data.groups[op.group]:
                            if item not in self.op_data.exhaust_agent:
                                continue
                            elif self.find_next_task(
                                task_type=TaskTypes.EXHAUST_OFF,
                                meta_data=item,
                                scope=TaskScope.PENDING,
                            ):
                                update_time = True
                                exh_task = self.find_next_task(
                                    task_type=TaskTypes.EXHAUST_OFF,
                                    meta_data=item,
                                    scope=TaskScope.PENDING,
                                )
                                if exh_task.retains_execution:
                                    continue
                                if _time < exh_task.time:
                                    logger.info(
                                        f"检测到用尽同组{op.name}比{item}提前下班，更新任务时间为{_time}"
                                    )
                                    exh_task.time = _time
                                exh_task.meta_data += f",{op.name}"
                                logger.debug(f"更新用尽meta_data为{exh_task.meta_data}")
                    if not update_time:
                        logger.info(f"生成{op.name}的下班任务")

                        self.tasks.append(
                            SchedulerTask(
                                time=_time,
                                task_type=TaskTypes.EXHAUST_OFF,
                                meta_data=op.name,
                            )
                        )
                    # 如果是生成的过去时间，则停止 plan 其他
                    if exhausted_time:
                        break

    # 根据优先级获取跑单冲突时应该要加速的房间
    def get_run_order_adjust_room(self, adj_tasks):
        # 此处出异常会一直运行，抛出None会终止循环，下面还没考虑过会出什么问题，可自行添加
        try:
            adj_0_task, adj_task = adj_tasks
        except TypeError:
            return None
        # Only trade order runs can be Drone Acceleration targets.
        run_orders = [
            t
            for t in adj_tasks
            if t.type == TaskTypes.RUN_ORDER
            and t.meta_data
            and not getattr(t, "run_order_collect_only", False)
            and not self.op_data.is_orundum_trade_room(t.meta_data)
        ]
        if len(run_orders) != 2:
            return run_orders[0].meta_data if len(run_orders) == 1 else None
        adjust_0_room = adj_0_task.meta_data
        adjust_room = adj_task.meta_data
        # 如果加速房间为跑单房间，则优先使用
        drone_room = self.drone_room
        if any(task.meta_data == drone_room for task in adj_tasks):
            logger.debug("检测到加速房间在冲突的跑单任务中，直接采用")
            adjust_0_room = drone_room
        else:
            logger.debug("开始比较跑单任务")
            run_order_rooms = self.op_data.run_order_rooms
            logger.debug(f"run_order_rooms：{run_order_rooms}")
            logger.debug(f"adjust_0_room：{adjust_0_room}")
            logger.debug(f"adjust_room：{adjust_room}")

            adjust_0_room_len = len(self.op_data.plan[adjust_0_room])  # 跑单任务首个
            adjust_room_len = len(self.op_data.plan[adjust_room])  # 跑单任务第二个
            # 正常情况按照82算法 1>3>2 进行加速
            # 如果 adjust_0_room 为 2 adjust_room 为 3 则是 2>3, 两者收益比较接近，先加速前面的订单可能更优，故保留特性
            if (
                adjust_0_room_len == 3 and adjust_room_len != 1
            ):  # 参考82算法 优先加速3级
                logger.debug(f"adjust_0_room_len ===> {adjust_0_room_len}")
                logger.debug(f"adjust_room_len ===> {adjust_room_len}")
            elif (
                adjust_0_room_len > adjust_room_len
            ):  # 如果首个任务房间比第二个大 #参考82算法
                adjust_0_room = adjust_room
                adjust_0_room_len = adjust_room_len
            logger.debug(f"加速房间 :{adjust_0_room}")
            logger.debug(f"加速房间长度 :{adjust_0_room_len}")

        # return adjust_0_room , adjust_0_room_len
        return adjust_0_room

    def _plan_primary_recovery(self, *, scan_moods=True):
        """共用主班轮休规划；普通补位和加工随后安排。"""
        if any(
            task.type == TaskTypes.FIAMMETTA and task.time <= datetime.now()
            for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
        ):
            logger.info("肥鸭任务已到期，充能回岗后再规划下班")
            return
        if scan_moods:
            self._read_missing_calculated_moods()
        # 准备数据
        # 根据剩余心情排序
        self.total_agent = list(
            v
            for v in self.op_data.operators.values()
            if (v.is_high() or (v.current_room == "" and v.room == ""))
            and not v.room.startswith("dorm")
        )
        self.total_agent.sort(key=lambda x: x.current_mood(), reverse=False)
        # 目前有换班的计划后面改
        logger.debug("主班恢复候选：%d 名干员", len(self.total_agent))
        new_plan = {}
        try:
            # 重新排序
            if self.find_next_task(task_type=TaskTypes.SHIFT_OFF):
                logger.info("有未完成的下班任务")
                return
            if scan_moods and not self._initial_mood_read_pending():
                reserved, _ = dorm_task_reservations(
                    self.op_data, [self.task, *self.tasks]
                )
                candidates = dorm_candidates(self.op_data, reserved)
                if not (candidates.recovering or candidates.estimated_recovering):
                    self._scan_card_moods()
            new_plan = self.resting()
        except (
            MowerExit,
            DeviceRecoveryError,
            ConnectionError,
            ConnectionAbortedError,
        ):
            raise
        except Exception as e:
            save_exception(e)
            logger.exception(e)
        # 更新宿舍任务
        re_order_dorm_plan = self._reorder_dorm_recovery(new_plan)
        if re_order_dorm_plan:
            if new_plan:
                # resting() 已把 new_plan 原对象放入 SHIFT_OFF；直接合并可确保
                # 工作站换班与宿舍入住一次执行，副表不会在两者之间看到
                # “已离岗但尚未入住宿舍”的瞬时状态并错误叫回整组。
                logger.debug(f"合并宿舍任务{re_order_dorm_plan}")
                _merge_dorm_arrangement(new_plan, re_order_dorm_plan)
            else:
                logger.debug(f"新增宿舍任务{re_order_dorm_plan}")
                self.tasks.append(
                    SchedulerTask(
                        task_plan=re_order_dorm_plan,
                        task_type=TaskTypes.NOT_SPECIFIC,
                    )
                )
        return True

    def _plan_dorm_recovery(self, *, scan_moods=True):
        """共用主班、空床和不养闲人规划；宿舍事件不等待加工入队空档。"""
        if self._emergency_frozen():
            self._emergency_tick()
            return True
        if self._initial_mood_read_pending():
            return False
        if not self._plan_primary_recovery(scan_moods=scan_moods):
            return False
        self._plan_preferred_replacements()
        self._fill_empty_dorms(primary_planned=True)
        _, _, reserved_names, reserved_slots = self._dorm_recovery_reservations(
            self.tasks
        )
        try_add_release_dorm(
            {},
            None,
            self.op_data,
            self.tasks,
            reserved_names=reserved_names,
            reserved_slots=reserved_slots,
        )
        return True

    @log_mood_calculation("普通换班规划")
    def plan_solver(self):
        if self._emergency_frozen():
            self._emergency_tick()
            return
        if not self._plan_dorm_recovery():
            return
        if not self.find_next_task(datetime.now() + timedelta(minutes=5)):
            self._read_missing_workshop_moods()
            try_workshop_tasks(self.op_data, self.tasks)
        if self.find_next_task(datetime.now() + timedelta(seconds=15)):
            logger.info("有其他任务,跳过宿舍纠错")
            return
        if self.agent_get_mood() is None:
            self.backup_plan_solver()

    def resting(self, *, returning=(), returning_groups=()):
        from arknights_mower.utils.backup_group_tasks import forced_work_groups

        working = forced_work_groups(self.op_data)
        self._refresh_deferred_product_reservations()
        reserved_names = self.op_data.reserved_product_replacements
        now = getattr(self.op_data, "_projection_now", None) or datetime.now()
        # 沿用原下班顺序：只比较距心情下限的余量。显式名单、高低优和
        # 候补均属于宿舍分床规则，不能让仍有心情的组抢走红脸组的替班。
        moods = {
            op.name: dorm_candidate_mood(self.op_data, op.name, now)
            for op in self.total_agent
        }
        self.total_agent.sort(
            key=lambda op: (
                moods[op.name] is None,
                (moods[op.name] or 0) - op.lower_limit,
            )
        )
        shift_candidates = [
            op
            for op in self.total_agent
            if op.is_high()
            and (not op.multi_group or op.independent_rest or op.shift_group)
            and (not op.group or self.op_data.is_group_shift_anchor(op))
        ]
        # 宿舍的普通空闲者统一交给补床入口，不依赖不养闲人开关；否则先预约
        # 床位并生成普通重排任务，会使真空床又被跑单避让推迟。
        self.plan_metadata()
        # 理想休息人数只描述主力轮休；低优占床另由 available_free("low")
        # 管理，不能抬高这里的当前人数或挡住可接管床位上的大组。
        current_resting = self.op_data.active_high_resting_count()
        effective_dorm_count = sum(
            1 for dorm in self.op_data.dorm if self.op_data.is_effective_free_slot(dorm)
        )
        # 阈值暂定为 0.5；理想休息人数不能超过当前副表下真实可用床位。
        self.ideal_resting_count = (
            min(4, effective_dorm_count)
            if self.op_data.average_mood()
            > self.op_data.config.resting_threshold
            * (self.op_data.runtime_conf or config.conf).rescue_threshold
            else effective_dorm_count
        )
        logger.debug(f"当前理想休息人数是{self.ideal_resting_count}")
        protected_training = self._protected_facility_names()
        _replacement = []
        _plan = {}
        dorm_admissions = {}
        _high_done = False
        attempted_groups = set()
        ordinary_requests = []
        # 工作组先取得床位预约，空闲干员随后由统一补床入口安排。
        for op in shift_candidates:
            if op.group in working:
                continue
            if op.independent_rest and self.op_data.resting_binding_groups(
                op, self.op_data.arrangement_group_transitions(_plan)
            ):
                continue
            mood = moods[op.name]
            if mood is None:
                continue
            if op.group in returning_groups or not op.group and op.name in returning:
                continue
            if op.name in _replacement:
                # 本轮已接工作替班的人不能又预约休息床位。
                continue
            if self._resting_tier(op) == RestingTier.EXCLUDED:
                continue
            if op.name in reserved_names:
                continue
            standby_scope = self.op_data.groups[op.group] if op.group else [op.name]
            can_standby = self.op_data.standby_candidates(standby_scope)
            can_preempt = self._resting_tier(op) <= RestingTier.LOW_MAIN and any(
                bed.name
                and resting_tier(self.op_data, bed.name) > self._resting_tier(op)
                and self.op_data._slot_takable(bed, requester=op.name)
                for bed in self.op_data.dorm
            )
            has_group_dorm_bed = op.group and self.op_data.group_dorm_bed_count(
                op.group
            )
            if _high_done and not (can_standby or can_preempt or has_group_dorm_bed):
                continue
            if (
                not can_standby
                and not can_preempt
                and not has_group_dorm_bed
                and current_resting + len(_replacement) >= self.ideal_resting_count
                and self.op_data.available_free() == 0
            ):
                _high_done = True
                continue
            if op.name in self.op_data.workaholic_agent:
                continue
            if (
                op.is_resting()
                or self.op_data.is_standby(op.name)
                or op.current_room in ["factory"]
                or op.name in protected_training
                or op.room in ["factory"]
            ):
                continue
            # 忽略掉心情太高的
            if (
                mood >= op.upper_limit
                if self.op_data.custom_mood_limits(op.name) is not None
                else op.upper_limit - mood < 2
            ):
                continue
            # 忽略 用尽，已经处理
            if op.name in self.op_data.exhaust_agent:
                continue
            # 忽略掉心情值没低于上限的的
            if mood > self.op_data.resting_mood_threshold(op):
                continue
            members = (
                self.op_data.shift_group_members(op.group) if op.group else [op.name]
            )
            if self._has_pending_exhausted_shift(members, request_names=[op.name]):
                continue
            previous_plan = copy.deepcopy(_plan)
            if op.group != "":
                if op.group in self.op_data.exhaust_group:
                    # 忽略掉用尽心情的分组
                    continue
                if op.group in attempted_groups:
                    continue
                attempted_groups.add(op.group)
                group_resting = self.op_data.groups[op.group]
                self.get_resting_plan(
                    group_resting,
                    _replacement,
                    _plan,
                    current_resting,
                    dorm_admissions=dorm_admissions,
                    request_names=[op.name],
                )
            else:
                self.get_resting_plan(
                    [op.name],
                    _replacement,
                    _plan,
                    current_resting,
                    dorm_admissions=dorm_admissions,
                    request_names=[op.name],
                )
            if _plan == previous_plan:
                self._schedule_group_coordination([op.name])
            else:
                ordinary_requests.append(op.name)
        if len(_plan.keys()) > 0:
            task = SchedulerTask(task_plan=_plan, task_type=TaskTypes.SHIFT_OFF)
            task.ordinary_coordination = True
            task.coordination_request_names = ordinary_requests
            self.tasks.append(task)
            self._log_arrangement("已生成任务", task=task)
        return _plan

    def _resting_tier(self, op):
        return resting_tier(self.op_data, op.name)

    def _cached_changed_slot_plan(self, previous_plan, restored_slots=()):
        """合并副表改动的固定岗位，宿舍绑组沿用轮休规则，动态床位另行迁移。"""
        result = {}
        group_dorm_positions = set()
        replacement_positions = set()
        joining_resting = set()
        previous_owners = {
            slot.agent: (old_room, slot)
            for old_room, slots in previous_plan.items()
            for slot in slots
            if slot.agent not in ("", "Free", "Current")
        }
        for room, slots in self.op_data.plan.items():
            old_slots = previous_plan.get(room, [])
            for index, slot in enumerate(slots):
                if room.startswith("dormitory_") and slot.agent == "Free":
                    continue
                old = old_slots[index] if index < len(old_slots) else None
                unchanged = old is not None and (
                    old.agent,
                    old.group,
                    tuple(old.replacement),
                    old.group_bindings,
                ) == (
                    slot.agent,
                    slot.group,
                    tuple(slot.replacement),
                    slot.group_bindings,
                )
                if unchanged:
                    if (room, index) not in restored_slots:
                        continue
                    if room.startswith("dorm"):
                        if slot.group:
                            group_dorm_positions.add((room, index))
                        continue
                    # 仅执行任务的副表退出时，也不能召回仍在宿舍的主班。
                    if not self.op_data.operators[slot.agent].is_resting():
                        continue
                current = self.op_data.get_current_operator(room, index)
                owner = self.op_data.operators[slot.agent]
                previous_room, previous = previous_owners.get(slot.agent, (None, None))
                relocated = old is None or old.agent != slot.agent
                if (
                    self.op_data.is_group_shift_anchor(owner)
                    and self.op_data.group_is_resting(slot.group)
                    and (not owner.current_room or owner.is_resting())
                    and owner.name not in self._protected_facility_names()
                ):
                    # 切表后的离岗工作主班跟随组内休息，不因原岗位或组名跳过。
                    replacement_positions.add((room, index))
                    joining_resting.add(owner.name)
                    continue
                if previous is not None and (
                    # 未读驻员和心情的岗位沿用初始化纠错，不推断为离岗。
                    (
                        current is not None
                        or owner.current_room
                        or owner.time_stamp is not None
                    )
                    and previous.group == slot.group
                    and previous.facility == slot.facility
                    and (not relocated or slot.facility or previous_room == room)
                    and [b["group"] for b in previous.group_bindings]
                    == [b["group"] for b in slot.group_bindings]
                    # 在岗主班迁移到新岗位；离岗主班由新岗位的替班接替。
                    and (not relocated or not owner.current_room or owner.is_resting())
                    and (not relocated or not room.startswith("dorm"))
                ):
                    replacement_positions.add((room, index))
                    continue
                if room.startswith("dormitory_") and slot.group:
                    group_dorm_positions.add((room, index))
                    continue
                if current is not None and (
                    current.name == slot.agent
                    or not (relocated and previous is not None)
                    and current.name in self.op_data.operators[slot.agent].replacement
                    and current.name not in TRADE_ORDER_AGENTS
                ):
                    continue
                result.setdefault(room, ["Current"] * len(self.op_data.plan[room]))[
                    index
                ] = slot.agent
        return result, group_dorm_positions, replacement_positions, joining_resting

    def _switch_products_before_backup_plan(self):
        """独立条件触发副表时，等切产物任务完成再切表。"""
        if not self._product_switching_enabled():
            self._discard_product_switches()
            return True
        pending = [
            task
            for task in self.tasks
            if getattr(task, "pending_backup_product_switch", False)
        ]
        desired_products, desired_plan = self._products_after_arrangement({})
        targets = {}
        for room, target in desired_products.items():
            if target == self.op_data.products.get(room):
                continue
            room_plan = desired_plan.get(room) or []
            if not room_plan:
                continue
            facility = room_plan[0].facility
            if not (
                facility == "制造站"
                and target in MANUFACTURE_PRODUCTS
                or facility == "贸易站"
                and target in TRADE_PRODUCTS
            ):
                continue
            targets[room] = target
        existing = {}
        stale_ids = set()
        for task in pending:
            room, product = parse_product_task_meta(task.meta_data)
            if targets.get(room) != product or room in existing:
                stale_ids.add(id(task))
            else:
                existing[room] = task
        self.tasks[:] = [task for task in self.tasks if id(task) not in stale_ids]
        waiting = False
        for room, target in targets.items():
            current = existing.get(room)
            if current is not None:
                waiting = True
                continue
            if self.op_data.facility_states.get(room, {}).get("product") == target:
                continue
            task = SchedulerTask(
                task_type=TaskTypes.SWITCH_PRODUCT,
                meta_data=product_task_meta(room, target),
            )
            task.pending_backup_product_switch = True
            task.pending_product_targets = {room: target}
            self.tasks.append(task)
            waiting = True
            logger.info("副表产物先切换%s：%s", self.translate_room(room), target)
        return not waiting

    def _complete_departed_recovery(
        self, plan, names, *, reserved_slots=(), failure_reasons=None
    ):
        """在隔离投影中补齐离岗者的床位；不足时不提交部分换班。"""
        projected = self.op_data.project_arrangements([plan])
        missing = [
            name
            for name in names
            if not (op := projected.operators[name]).workaholic
            and not op.room.startswith("dorm")
            and not op.current_room
            and (
                projected.is_free_room_excluded(name)
                or not projected.rest_mood_complete(name)
                and (
                    (mood := dorm_candidate_mood(projected, name)) is None
                    or mood < op.upper_limit
                )
            )
        ]
        if not missing:
            return True
        pending = [
            task for task in self.tasks if task is not getattr(self, "task", None)
        ]
        reservation_options = {
            "op_data": projected,
            "returning_groups": self._returning_groups_releasing_waits(
                getattr(self, "task", None)
            ),
            "current_task": getattr(self, "task", None),
        }
        _, all_reserved_slots, _, _ = self._dorm_recovery_reservations(
            pending, **reservation_options
        )
        reservations, preferred = {}, {}
        for name in missing:
            reserved_names, occupied, _, _ = self._dorm_recovery_reservations(
                pending,
                **reservation_options,
                recovering_name=name,
            )
            if name in reserved_names:
                if failure_reasons is not None:
                    failure_reasons.append("副表离岗成员已被其他任务预约：" + name)
                return False
            reservations[name] = occupied
            preferred[name] = all_reserved_slots - occupied
        occupied = set(reserved_slots)
        occupied.update(
            (room, index)
            for room, row in plan.items()
            if room.startswith("dorm")
            for index, name in enumerate(row)
            if name != "Current"
        )
        for positions in preferred.values():
            positions.difference_update(occupied)
        beds = projected.assign_dorm_group(
            missing,
            active_groups={projected.operators[name].group for name in missing},
            plan=plan,
            reserved_slots=occupied,
            reserved_slots_by_name=reservations,
            preferred_slots_by_name=preferred,
        )
        if beds is None:
            if failure_reasons is not None:
                failure_reasons.append(
                    "宿舍床位无法满足副表离岗成员的休息安排："
                    + "、".join(sorted(missing))
                )
            return False
        for bed in beds:
            room, index = bed.position
            plan.setdefault(room, ["Current"] * len(projected.plan[room]))[index] = (
                bed.name
            )
        return True

    def _backup_transition_plan(
        self,
        previous_plan,
        original,
        conditions,
        previous_dorms,
        previous_dorm_layout,
        previous_retention_names=(),
        *,
        failure_reasons=None,
    ):
        """普通切表与换班推演共用最终岗位、显式任务和宿舍迁移规则。"""
        self._backup_departure_waiting_names = ()
        pending = self._cancel_stale_retention_admissions(preview=True)
        if any(left is not right for left, right in zip(pending, self.tasks)):
            simulation = copy.copy(self)
            simulation.op_data = self.op_data.project_arrangements([])
            simulation.tasks = pending
            simulation._refresh_deferred_product_reservations()
            result = simulation._backup_transition_plan(
                previous_plan,
                original,
                conditions,
                previous_dorms,
                previous_dorm_layout,
                previous_retention_names,
                failure_reasons=failure_reasons,
            )
            self._backup_departure_waiting_names = (
                simulation._backup_departure_waiting_names
            )
            return result
        transition_plan = {}
        deactivated_slots = {}
        # 退出副表时恢复其任务写过的槽位；切入任务在最后覆盖，确保多个
        # 同时生效的副表与合并排班表的覆盖顺序一致。
        for index, bp in enumerate(self.op_data.backup_plans):
            if original[index] and not conditions[index] and bp.task:
                for room, names in bp.task.items():
                    indexes = deactivated_slots.setdefault(room, set())
                    indexes.update(
                        i for i, name in enumerate(names) if name != "Current"
                    )
        restore_plan = {}
        for room, indexes in deactivated_slots.items():
            active_room = self.op_data.plan.get(room)
            if active_room is None:
                continue
            names = ["Current"] * len(active_room)
            for index in indexes:
                if index < len(active_room):
                    names[index] = active_room[index].agent
            if any(name != "Current" for name in names):
                restore_plan[room] = names

        correction, group_dorm_positions, replacement_positions, joining_resting = (
            self._cached_changed_slot_plan(
                previous_plan,
                {
                    (room, index)
                    for room, indexes in deactivated_slots.items()
                    for index in indexes
                },
            )
        )
        # 退出副表恢复岗位时，保留休息的主班仍经替班匹配，不强制回班。
        for room, index in replacement_positions:
            if room in restore_plan:
                restore_plan[room][index] = "Current"
        _merge_plan_overlay(transition_plan, correction, self.op_data)
        _merge_plan_overlay(transition_plan, restore_plan, self.op_data)

        for index, bp in enumerate(self.op_data.backup_plans):
            if not original[index] and conditions[index] and bp.task:
                _merge_plan_overlay(
                    transition_plan, copy.deepcopy(bp.task), self.op_data
                )
                # 副表显式安排优先，不再用绑组默认岗位覆盖。
                group_dorm_positions.difference_update(
                    (room, index)
                    for room, names in bp.task.items()
                    for index, name in enumerate(names)
                    if name != "Current"
                )

        self._suppress_facility_arrangement(transition_plan)
        departing = {
            owner.name
            for bp_index, bp in enumerate(self.op_data.backup_plans)
            if not original[bp_index] and conditions[bp_index]
            for room, names in (bp.task or {}).items()
            if not room.startswith("dorm")
            for index, name in enumerate(names)
            if index < len(self.op_data.plan.get(room, ()))
            and (
                owner := self.op_data.operators.get(
                    self.op_data.plan[room][index].agent
                )
            )
            is not None
            and name in self.op_data.replacement_candidates(owner)
            and name not in TRADE_ORDER_AGENTS
            and transition_plan.get(room, [])[index : index + 1] == [name]
            and owner.name not in self._protected_facility_names()
        }
        if not self._complete_departed_recovery(
            transition_plan, departing, failure_reasons=failure_reasons
        ):
            self._backup_departure_waiting_names = tuple(sorted(departing))
            return None

        from arknights_mower.utils.resting_correction import (
            preserve_backup_replacements,
        )

        explicit_names = _assigned_operator_names(transition_plan)
        explicit_dorm_slots = {
            (room, index)
            for room, names in transition_plan.items()
            if room.startswith("dorm")
            for index, name in enumerate(names)
            if name != "Current"
        }
        preserved = {
            op.name: (op.current_room, op.current_index)
            for room, index in replacement_positions
            if (op := self.op_data.operators[self.op_data.plan[room][index].agent]).name
            not in explicit_names
            and transition_plan.get(room, [])[index : index + 1] in ([], ["Current"])
        }
        reserved_names, reserved_slots, waiting_names, waiting_slots = (
            self._dorm_recovery_reservations(
                [
                    task
                    for task in self.tasks
                    if task is not getattr(self, "task", None)
                    and (
                        task.type != TaskTypes.SHIFT_ON
                        or getattr(task, "product_shift_locked", False)
                    )
                ],
                returning_groups=self._returning_groups_releasing_waits(
                    getattr(self, "task", None)
                ),
            )
        )
        if not preserve_backup_replacements(
            self.op_data,
            transition_plan,
            replacement_positions,
            previous_dorms,
            _is_mastery_busy,
            reserved_names,
            reserved_slots,
            failure_reasons=failure_reasons,
        ):
            return None
        if joining_resting:
            simulation = copy.copy(self)
            simulation.op_data = self.op_data.project_arrangements([transition_plan])
            missing = [
                name
                for name in sorted(joining_resting)
                if (op := simulation.op_data.operators[name]).group
                and simulation.op_data.group_is_resting(op.group)
                and name not in explicit_names
                and simulation.op_data.get_dorm_by_name(name)[0] is None
                and not (
                    not op.current_room
                    and op.time_stamp is not None
                    and (
                        op.current_mood() >= op.upper_limit
                        if getattr(self.op_data, "mood_calculation_enabled", False)
                        else op.mood >= op.upper_limit
                    )
                )
            ]
            if missing:
                # 新成员尚未恢复时复用正常替班与分床；只改投影中的床位缓存。
                admissions = {}
                if not simulation._get_resting_plan(
                    missing,
                    list(_assigned_operator_names(transition_plan)),
                    transition_plan,
                    simulation.op_data.active_high_resting_count(),
                    dorm_admissions=admissions,
                    excluded_names=reserved_names,
                    reserved_slots=reserved_slots | explicit_dorm_slots,
                    failure_reasons=failure_reasons,
                    request_names=[],
                ):
                    return None
                for (room, index), name in admissions.items():
                    transition_plan.setdefault(
                        room, ["Current"] * len(self.op_data.plan[room])
                    )[index] = name
                    preserved.pop(name, None)
        # 替班不足时允许召回本人；其余主班保留位置，阵容变化可使计时失效。
        assigned = _assigned_operator_names(transition_plan)
        preserved = {
            name: position
            for name, position in preserved.items()
            if name not in assigned
        }
        recovery = {
            bed.name: (bed.position, bed.time)
            for bed in previous_dorms
            if bed.name in preserved
        }

        if group_dorm_positions:
            from arknights_mower.utils.resting_correction import correct_group_dorms

            # 等工作岗位与副表任务合并后再判断回班，避免把将被替班覆盖的
            # 中间岗位误判为整组召回；只处理切表实际改动的宿舍位置。
            correct_group_dorms(
                self.op_data,
                transition_plan,
                _is_mastery_busy,
                positions=group_dorm_positions,
            )

        current_dorm_layout = dorm_rebalance_signature(self.op_data)
        priority_changed = (
            previous_dorm_layout is not None
            and previous_dorm_layout[0] != current_dorm_layout[0]
        )
        if previous_dorm_layout is None or previous_dorm_layout != current_dorm_layout:
            # 迁移须与副表已提出的槽位安排比较，不能把被该安排覆盖的
            # 原住者误判为无需移动，导致合并后丢失其床位。
            migration_data = self.op_data.project_arrangements([transition_plan])
            dorm_migration = rebalance_plan_swap_dorms(
                migration_data,
                previous_dorms,
                reserved_names=_assigned_operator_names(transition_plan)
                | (reserved_names if priority_changed else waiting_names),
                # 生效床序变化时重新分配，已有单回位置不覆盖用户的新顺序。
                reorder=priority_changed,
                reserved_slots=(
                    reserved_slots
                    | {
                        (room, index)
                        for room, names in transition_plan.items()
                        for index, name in enumerate(names)
                        if name != "Current"
                    }
                    if priority_changed
                    else waiting_slots
                ),
            )
            _merge_shift_transition(transition_plan, dorm_migration, self.op_data)
            # 副表收回原床位时沿用宿舍迁移结果；新床的恢复时间须重新读取。
            for room, names in dorm_migration.items():
                for index, name in enumerate(names):
                    if name in recovery and recovery[name][0] != (room, index):
                        preserved[name] = (room, index)
                        recovery[name] = ((room, index), None)
        else:
            logger.debug("副表未改变宿舍床位或房间顺序，跳过宿舍重排")

        from arknights_mower.utils.resting_correction import (
            suppress_completed_dorm_returns,
        )

        suppress_completed_dorm_returns(self.op_data, transition_plan)
        if preserved:
            projected = self.op_data.project_arrangements([transition_plan])
            moved = [
                name
                for name, position in preserved.items()
                if (
                    projected.operators[name].current_room,
                    projected.operators[name].current_index,
                )
                != position
            ]
            if moved:
                if failure_reasons is not None:
                    failure_reasons.append(
                        f"无法保留休息成员的位置：{'、'.join(sorted(moved))}"
                    )
                return None
            projected_recovery = {
                bed.name: (bed.position, bed.time)
                for bed in projected.all_dorms()
                if bed.name in preserved
            }
            changed = [
                name
                for name, expected in recovery.items()
                if projected_recovery.get(name) not in (expected, (expected[0], None))
            ]
            if changed:
                if failure_reasons is not None:
                    failure_reasons.append(
                        f"无法保留休息成员的床位和恢复时间：{'、'.join(sorted(changed))}"
                    )
                return None
        transition_plan = {
            room: names
            for room, names in transition_plan.items()
            if any(name != "Current" for name in names)
        }
        from arknights_mower.utils.resting_correction import (
            reconcile_backup_dorm_retention,
        )

        transition_plan = reconcile_backup_dorm_retention(
            self.op_data,
            transition_plan,
            previous_retention_names,
            explicit_slots=self._backup_explicit_slots(original, conditions),
            reserved_names=reserved_names,
            reserved_slots=reserved_slots,
        )
        if transition_plan is None:
            self._backup_departure_waiting_names = tuple(
                sorted(
                    set(previous_retention_names)
                    | set(self.op_data.config.free_room_exclusions)
                )
            )
            if failure_reasons is not None:
                failure_reasons.append(
                    "无法安置宿舍保留干员："
                    + "、".join(self._backup_departure_waiting_names)
                )
            return None
        transition_plan = prioritize_new_dorm_recovery(
            self.op_data,
            transition_plan,
            reserved_slots | explicit_dorm_slots,
            reserved_names=reserved_names,
            configuration_changed=previous_dorm_layout != current_dorm_layout,
        )
        if priority_changed:
            transition_plan = plan_dorm_isolation(
                self.op_data,
                transition_plan,
                reserved_slots | explicit_dorm_slots,
                reserved_names=reserved_names,
                reallocating_names={bed.name for bed in previous_dorms if bed.name},
            )
        return transition_plan

    def _coalesce_backup_transition(self, transition):
        """切表的新意图替换同轮旧安排，保留同批其他成员；返回被合并的任务。"""
        now = datetime.now()
        ordinary = {
            TaskTypes.SHIFT_ON,
            TaskTypes.SHIFT_OFF,
            TaskTypes.SELF_CORRECTION,
            TaskTypes.RE_ORDER,
            TaskTypes.NOT_SPECIFIC,
            TaskTypes.FILL_DORM,
        }

        def footprint(plan):
            names, slots = set(), set()
            for room, agents in plan.items():
                for index, name in enumerate(agents):
                    if name != "Current":
                        slots.add((room, index))
                    if name not in ("Current", "Free", ""):
                        names.add(name)
            return names, slots

        def connected_tasks(transition, tasks):
            names, slots = footprint(transition)
            remaining = list(tasks)
            connected = []
            while remaining:
                matched = []
                for task in remaining:
                    task_names, task_slots = footprint(task.plan)
                    if names & task_names or slots & task_slots:
                        matched.append(task)
                        names.update(task_names)
                        slots.update(task_slots)
                if not matched:
                    break
                connected.extend(matched)
                ids = {id(task) for task in matched}
                remaining = [task for task in remaining if id(task) not in ids]
            return connected

        candidates = [
            task
            for task in task_view(self.tasks, TaskScope.REPLAN)
            if task.type in ordinary
            and task.plan
            and not getattr(task, "exhaust_support", False)
            and not getattr(task, "urgent_recovery_request_names", ())
            and min(task.time, getattr(task, "arrangement_retry_due_at", task.time))
            <= now + timedelta(minutes=1)
            and not getattr(task, "strict_mood_limit", False)
            and not getattr(task, "dorm_recovery_restore", [])
        ]
        # 仅在当前候选确实接替旧安排时放开预约。每次重算至少移除一个
        # 候选，未接替的任务重新保护其岗位及当前驻员。
        source = transition
        while True:
            exempt = {
                id(task)
                for task in candidates
                if getattr(task, "backup_shift_active", False)
            }
            reservations = [task for task in self.tasks if id(task) not in exempt]
            transition = copy.deepcopy(source)
            self._suppress_retained_arrangements(
                transition, reservation_tasks=reservations
            )
            merged_tasks = connected_tasks(transition, candidates)
            if exempt.difference(id(task) for task in merged_tasks):
                candidates = merged_tasks
                continue
            if not merged_tasks:
                return transition, []
            merged = {}
            for task in sorted(merged_tasks, key=lambda task: task.time):
                planned = copy.deepcopy(task.plan)
                self._filter_ordinary_exhaust_departures(task, planned, self.op_data)
                _merge_shift_transition(merged, planned, self.op_data)
            _merge_shift_transition(merged, transition, self.op_data)
            # 旧任务也可能带入其他预约保护的调人操作。核对最终名单，
            # 只保留仍能完整交接剩余安排的任务，再重验它们之间的关联。
            _, slots = footprint(merged)
            self._suppress_retained_arrangements(merged, reservation_tasks=reservations)
            blocked = slots - footprint(merged)[1]
            if not blocked:
                break
            candidates = [
                task for task in merged_tasks if not footprint(task.plan)[1] & blocked
            ]
            if len(candidates) == len(merged_tasks):
                # 合并后整组回班条件也可能改变新意图的准入，保留原任务。
                candidates = []
        logger.debug(
            "副表收敛合并 %s 条旧安排，直接执行最终换班：%s", len(merged_tasks), merged
        )
        self._log_arrangement(
            f"副表收敛合并 {len(merged_tasks)} 条旧安排，执行最终换班：", plan=merged
        )
        return merged, merged_tasks

    def _record_backup_retention(self, task, previous_names, data=None):
        """自动保留动作记录来源，执行和后续切表只修改这些具名动作。"""
        data = data or self.op_data
        previous = set(previous_names) - {""}
        retained = set(data.config.free_room_exclusions) - {""}
        explicit = {
            task.plan[room][index]
            for room, index in getattr(task, "backup_explicit_slots", ())
            if index < len(task.plan.get(room, ()))
        }
        task.backup_retention_admissions = (
            set(getattr(task, "backup_retention_admissions", ()))
            | {
                name
                for names in task.plan.values()
                for name in names
                if name in retained
                and (op := data.operators.get(name)) is not None
                and not op.room
                and not getattr(self.op_data.operators.get(name), "current_room", "")
            }
        ) & retained - explicit
        releases = dict(getattr(task, "backup_retention_releases", {}))
        releases.update(
            {
                name: (op.current_room, op.current_index)
                for name in previous - retained
                if (op := self.op_data.operators.get(name)) is not None
                and name in data.operators
                and not data.operators[name].room
                and op.is_resting()
                and not any(name in names for names in task.plan.values())
            }
        )
        task.backup_retention_releases = {
            name: position
            for name, position in releases.items()
            if name not in retained
            and name not in explicit
            and not any(name in names for names in task.plan.values())
        }
        for name, (room, index) in task.backup_retention_releases.items():
            if (
                index < len(task.plan.get(room, ()))
                and task.plan[room][index] == "Free"
                and (current := self.op_data.get_current_operator(room, index))
                is not None
                and current.name == name
            ):
                task.plan[room][index] = ""
        empty_slots = getattr(task, "backup_retention_empty_slots", {})
        task.backup_retention_empty_slots = {
            (room, index): empty_slots.get((room, index), current.name)
            for room, names in task.plan.items()
            if room.startswith("dorm")
            for index, name in enumerate(names)
            if name == ""
            and (current := self.op_data.get_current_operator(room, index)) is not None
        }

    def _cancel_stale_retention_admissions(self, *, preview=False):
        """尚未执行的自动保留入住随最终配置撤销，同批其他安排继续执行。"""
        pending = []
        for original in self.tasks:
            task = original
            pending.append(task)
            if task.retains_execution or any(
                getattr(task, field, False)
                for field in (
                    "backup_shift_active",
                    "backup_retention_started",
                    "group_shift_expected",
                )
            ):
                continue
            stale = {
                name
                for name in getattr(task, "backup_retention_admissions", ())
                if not self.op_data.is_free_room_excluded(name)
            }
            if not stale:
                continue
            if preview:
                task = copy.deepcopy(task)
                pending[-1] = task
            for field in ("plan", "backup_shift_intent", "dorm_fill_plan"):
                plan = getattr(task, field, None)
                if plan is not None:
                    for room, names in list(plan.items()):
                        plan[room] = [
                            "Current" if name in stale else name for name in names
                        ]
                        if all(name == "Current" for name in plan[room]):
                            del plan[room]
            task.backup_retention_admissions = (
                set(task.backup_retention_admissions) - stale
            )
            if hasattr(task, "product_lock_names"):
                task.product_lock_names = set(task.product_lock_names) - stale
        if not preview:
            self._refresh_deferred_product_reservations()
        return pending

    def _reconcile_initial_staffing(self):
        """清零启动观测后生成驻员建议，与轮休和补床一起预演最终安排。"""
        if (
            not getattr(self, "_initial_staffing_pending", False)
            or self._initial_mood_read_pending()
            or self._emergency_active()
            or getattr(self, "_emergency_startup_pending", False)
        ):
            return False
        # 明确换班先完成；普通清退任务不能跳过初始化驻员纠错。
        if any(
            task.type
            in (TaskTypes.SHIFT_ON, TaskTypes.SHIFT_OFF, TaskTypes.SELF_CORRECTION)
            and task.plan
            and task.time <= datetime.now()
            or getattr(task, "backup_shift_active", False)
            or getattr(task, "initial_fia", False)
            or getattr(task, "group_shift_expected", {})
            for task in [*self.tasks, *getattr(self, "waiting_group_shifts", [])]
        ):
            return False
        result = self.agent_get_mood(force=True, read_rooms=False)
        self._initial_staffing_pending = False
        return result is not None

    def _initial_mood_read_pending(self):
        return getattr(self, "defer_backup_plan_until_mood_read", False)

    @staticmethod
    def _merge_refresh_rules(left, right):
        drained = left[0] or right[0]
        active = [rule[1] for rule in (left, right) if rule[1][0]]
        rooms = (
            list(dict.fromkeys(room for _, targets in active for room in targets))
            if all(targets for _, targets in active)
            else []
        )
        return drained, [bool(active), rooms]

    def _capture_shift_refresh_rules(self, task, previous):
        """仅任务保留旧刷新规则，实际换人前不触发回调。"""
        rules = getattr(task, "backup_refresh_rules", {})
        for name, old in previous.items():
            current = (
                self.op_data.config.is_refresh_drained(name),
                self.op_data.config.is_refresh_trading(name),
            )
            if old != current or name in rules:
                rules[name] = self._merge_refresh_rules(
                    rules.get(name, (False, [False, []])), old
                )
        if rules:
            task.backup_refresh_rules = rules

    def _arrange_with_shift_refresh_rules(self, task, get_time):
        """旧规则只在本任务的实际换人期间生效，延期和失败均恢复配置值。"""
        rules = getattr(task, "backup_refresh_rules", {})
        try:
            for name, old in rules.items():
                op = self.op_data.operators.get(name)
                if op is None:
                    continue
                current = (
                    self.op_data.config.is_refresh_drained(name),
                    self.op_data.config.is_refresh_trading(name),
                )
                op.refresh_drained, op.refresh_order_room = self._merge_refresh_rules(
                    old, current
                )
            if getattr(task, "derived_correction", False):
                task.derived_correction_started = True
            if getattr(task, "backup_retention_admissions", ()) or getattr(
                task, "backup_retention_releases", ()
            ):
                task.backup_retention_started = True
            with log_parent_context(
                self._rescue_staffing_log_parent(task)
                if task is getattr(self, "task", None)
                else None
            ):
                return self.agent_arrange(task.plan, get_time)
        finally:
            for name in rules:
                op = self.op_data.operators.get(name)
                if op is not None:
                    op.refresh_drained = self.op_data.config.is_refresh_drained(name)
                    op.refresh_order_room = self.op_data.config.is_refresh_trading(name)

    def _exhaust_task_signatures(self, *, tasks=None):
        """动态用尽预约依赖生效岗位和组配置，不依赖临时驻员或心情读数。"""
        signatures = {}
        for task in task_view(self.tasks if tasks is None else tasks, TaskScope.REPLAN):
            if (
                task.type != TaskTypes.EXHAUST_OFF
                or task.plan
                or getattr(task, "backup_group_request", None)
            ):
                continue
            names = set(task.meta_data.split(","))
            for name in tuple(names):
                op = self.op_data.operators.get(name)
                if op is not None and op.group:
                    names.update(self.op_data.groups.get(op.group, []))
            members = []
            for name in sorted(names):
                op = self.op_data.operators.get(name)
                if op is None:
                    members.append((name, None))
                    continue
                slots = self.op_data.plan.get(op.room, [])
                facility = (
                    slots[op.index].facility if 0 <= op.index < len(slots) else None
                )
                members.append(
                    (
                        name,
                        op.room,
                        op.index,
                        op.group,
                        tuple(op.replacement),
                        op.is_high(),
                        op.exhaust_require,
                        op.workaholic,
                        op.rest_in_full,
                        op.lower_limit,
                        op.upper_limit,
                        facility,
                        self.op_data.products.get(op.room),
                    )
                )
            signatures[id(task)] = tuple(members)
        return signatures

    def _invalidate_changed_exhaust_tasks(self, previous, *, tasks=None):
        tasks = self.tasks if tasks is None else tasks
        current = self._exhaust_task_signatures(tasks=tasks)
        invalid = {
            task_id
            for task_id, signature in previous.items()
            if task_id in current and current[task_id] != signature
        }
        if invalid:
            tasks[:] = [task for task in tasks if id(task) not in invalid]
            if tasks is self.tasks:
                logger.info(
                    "副表生效后移除 %s 条配置已改变的动态用尽预约", len(invalid)
                )
            else:
                logger.debug("换班预演忽略 %s 条配置已改变的动态用尽预约", len(invalid))
        return bool(invalid)

    def _advance_orders_before_maintenance(self, conditions, backup_group=None):
        """先完成维护主班的跑单替班任务，或原有停服前跑单批次。"""
        entering = any(
            active
            and (
                not previous
                or backup_group is not None
                and backup_group != self.op_data.backup_group
                and not backup.uses_condition(
                    "major_maintenance_remaining_hours", self.op_data.backup_group
                )
            )
            and backup.uses_condition(
                "major_maintenance_remaining_hours",
                backup_group or self.op_data.backup_group,
            )
            for active, previous, backup in zip(
                conditions, self.op_data.plan_condition, self.op_data.backup_plans
            )
        )
        if not entering:
            self.maintenance_entry_pending = False
            return False
        projected = copy.deepcopy(
            self.op_data, {id(self.op_data.eval_model): self.op_data.eval_model}
        )
        if error := projected.swap_plan(conditions, backup_group=backup_group):
            raise ValueError(f"维护副表预演失败：{error}")
        if projected.run_order_paused:
            pending = [
                task
                for task in self.tasks
                if getattr(task, "maintenance_replacement_run", False)
            ]
            if not pending and not getattr(self, "maintenance_entry_pending", False):
                plans = {}
                for room, index in sorted(projected.maintenance_primary_slots):
                    if (
                        not room.startswith("room")
                        or projected.products.get(room) == "orundum"
                        or projected.facility_states.get(room, {}).get("product")
                        == "orundum"
                    ):
                        continue
                    slot = projected.plan[room][index]
                    replacement = next(
                        (
                            name
                            for name in slot.all_replacements
                            if name in TRADE_ORDER_AGENTS and name != slot.agent
                        ),
                        None,
                    )
                    if replacement is None:
                        continue
                    plans.setdefault(room, ["Current"] * len(projected.plan[room]))[
                        index
                    ] = replacement
                    if replacement not in self.op_data.operators:
                        self.op_data.add(Operator(replacement, ""))
                self._invalidate_order_estimates(plans)
                for room, names in plans.items():
                    task = SchedulerTask(
                        task_plan={room: names},
                        task_type=TaskTypes.RUN_ORDER,
                        meta_data=room,
                        adjusted=True,
                    )
                    task.maintenance_advance_before_backup = True
                    task.maintenance_replacement_run = True
                    pending.append(task)
                    self.tasks.append(task)
                if pending:
                    self.tasks.sort(
                        key=lambda task: (
                            bool(getattr(task, "execution_failure", None)),
                            task.time,
                        )
                    )
                    logger.info("先用维护主班的跑单替班加速订单，恢复原班后再切表")
            self.maintenance_entry_pending = bool(pending)
            return self.maintenance_entry_pending
        blocked_orders = blocked_run_order_ids(self.tasks, self.op_data)
        pending = [
            task
            for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            if getattr(task, "maintenance_advance_before_backup", False)
            and id(task) not in blocked_orders
        ]
        if not pending and not getattr(self, "maintenance_entry_pending", False):
            pending = adjust_run_order_for_maintenance(
                self.tasks,
                config.conf.run_order_delay,
                advance_time=datetime.now(),
                op_data=self.op_data,
            )
            for task in pending:
                task.maintenance_advance_before_backup = True
            if pending:
                self.tasks.sort(
                    key=lambda task: (
                        bool(getattr(task, "execution_failure", None)),
                        task.time,
                    )
                )
                logger.info("提前执行停服前跑单任务，完成后再切换维护副表")
        self.maintenance_entry_pending = bool(pending)
        return self.maintenance_entry_pending

    def _schedule_maintenance_backup_check(self):
        if self._emergency_frozen():
            return
        op_data = getattr(self, "op_data", None)
        if not isinstance(op_data, Operators):
            return
        deadline = op_data.next_major_maintenance_check()
        checks = [
            task
            for task in self.tasks
            if task.type == TaskTypes.NOT_SPECIFIC
            and task.meta_data == "maintenance_backup_check"
        ]
        # 保留已到期检查，避免睡眠刚结束就删除尚未执行的唤醒。
        if any(task.time <= datetime.now() for task in checks):
            return
        if deadline is not None and len(checks) == 1 and checks[0].time == deadline:
            return
        check_ids = {id(task) for task in checks}
        self.tasks[:] = [task for task in self.tasks if id(task) not in check_ids]
        if deadline is not None:
            self.tasks.append(
                SchedulerTask(time=deadline, meta_data="maintenance_backup_check")
            )
            self.tasks.sort(
                key=lambda task: (
                    bool(getattr(task, "execution_failure", None)),
                    task.time,
                )
            )

    def _ensure_ordinary_planning_wake(self, custom_task_time=None):
        followup = SchedulerTask(time=custom_task_time)
        if any(
            task is not getattr(self, "task", None)
            and type(task) is type(followup)
            and task.time <= followup.time
            and vars(task) == {**vars(followup), "time": task.time}
            for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
        ):
            return None
        self.tasks.append(followup)
        return followup

    @log_mood_calculation("副表切换")
    @_log_backup_calculation("副表切换")
    def backup_plan_solver(
        self,
        custom_task_time=None,
        generated_tasks=None,
    ):
        """用缓存状态一次性收敛副表，并只生成一张最终差异任务。

        每次检查计算全部条件直到稳定，再把副表任务、岗位纠偏和宿舍迁移合并。
        """
        if self._emergency_frozen() or self._initial_mood_read_pending():
            return False
        # 肥鸭充能中的临时离岗不能作为副表条件；任务间隙和重启恢复时，
        # 已到期的充能／回岗任务也属于同一流程，须等回岗完成再判断。
        now = datetime.now()
        if getattr(
            getattr(self, "task", None), "type", None
        ) == TaskTypes.FIAMMETTA or any(
            task.type == TaskTypes.FIAMMETTA and task.time <= now
            for task in getattr(self, "tasks", [])
        ):
            logger.debug("肥鸭充能或回岗任务尚未完成，跳过副表切换")
            return False
        if any(
            getattr(task, "backup_shift_active", False)
            or getattr(task, "group_shift_expected", {})
            for task in getattr(self, "tasks", [])
        ):
            logger.debug("换班最终安排尚未完成，避免用中间驻员状态重新切表")
            return False
        previous_data = None
        try:
            if not self.op_data.backup_plans:
                self.maintenance_entry_pending = False
                return False

            selection_started = perf_counter()
            selection = self._evaluate_backup_selection()
            selection_elapsed = perf_counter() - selection_started
            initial_conditions = selection.conditions
            original_group = self.op_data.backup_group
            if self._advance_orders_before_maintenance(
                initial_conditions, selection.group_id
            ):
                return False

            if any(
                getattr(plan, "products", None) for plan in self.op_data.backup_plans
            ):
                if not self._switch_products_before_backup_plan():
                    return False

            original = list(self.op_data.plan_condition)
            if initial_conditions == original:
                if selection.group_id != original_group:
                    if error := self.op_data.swap_plan(
                        original, backup_group=selection.group_id
                    ):
                        raise ValueError(f"副表分组切换失败：{error}")
                    self._sync_run_order_tasks()
                return False
            timing = _backup_timing_runtime.current
            timing.start(selection_elapsed)
            previous_data = self.op_data.project_arrangements([])
            previous_exhaust = self._exhaust_task_signatures()
            previous_plan = copy.deepcopy(self.op_data.plan)
            previous_dorms = copy.deepcopy(self.op_data.all_dorms())
            previous_dorm_layout = dorm_rebalance_signature(self.op_data)
            seen = {tuple(original)}
            current = original
            conditions = initial_conditions
            while True:
                timing.rounds["副表切换"] += 1
                for bp in self.op_data.backup_plans:
                    logger.debug(str(bp.trigger))
                if conditions == current:
                    self.op_data.backup_group = selection.group_id
                    break
                if current != original and self._advance_orders_before_maintenance(
                    conditions, selection.group_id
                ):
                    self.op_data.swap_plan(
                        original, refresh=True, backup_group=original_group
                    )
                    timing.result = "等待提前跑单"
                    return False
                key = tuple(conditions)
                if key in seen:
                    timing.result = "循环未收敛"
                    logger.error(
                        "副表条件在内存演算中出现循环 %s -> %s，保持切换前状态",
                        current,
                        conditions,
                    )
                    if current != original:
                        self.op_data.swap_plan(
                            original, refresh=True, backup_group=original_group
                        )
                    return False
                seen.add(key)
                error = self.op_data.swap_plan(
                    conditions, refresh=True, backup_group=selection.group_id
                )
                if error:
                    timing.result = "演算失败"
                    logger.error("副表内存演算失败：%s", error)
                    self.op_data.swap_plan(
                        original, refresh=True, backup_group=original_group
                    )
                    return False
                current = conditions
                selection = self._evaluate_backup_selection()
                conditions = selection.conditions

            timing.result = "已收敛"
            if current == original:
                return False

            logger.debug("副表条件一次性收敛：%s -> %s", original, current)
            had_rest_schedule = any(
                task.type in (TaskTypes.SHIFT_ON, TaskTypes.RELEASE_DORM)
                for task in self.tasks
            )
            failure_reasons = []
            transition_plan = self._backup_transition_plan(
                previous_plan,
                original,
                current,
                previous_dorms,
                previous_dorm_layout,
                previous_data.config.free_room_exclusions,
                failure_reasons=failure_reasons,
            )
            if transition_plan is None:
                reason = "；".join(failure_reasons) or "无法完成副表驻员与休息安排"
                timing.result = "切换暂缓，保留原排班"
                self.op_data = previous_data
                logger.info("副表切换暂缓：%s；保留原排班和休息状态", reason)
                return False
            activated_changes = backup_changes(self.op_data, original, current)
            if activated_changes:
                logger.info(
                    format_backup_changes(activated_changes, completed=True),
                    extra={"log_backups": activated_changes},
                )
            self._cancel_stale_retention_admissions()
            self._invalidate_changed_exhaust_tasks(previous_exhaust)
            self._sync_run_order_tasks()
            self.queue_product_switches()
            generated = None
            if transition_plan:
                transition_plan, superseded = self._coalesce_backup_transition(
                    transition_plan
                )
                generated = SchedulerTask(
                    time=custom_task_time,
                    task_plan=transition_plan,
                    task_type=TaskTypes.RE_ORDER
                    if any(room.startswith("dormitory_") for room in transition_plan)
                    else TaskTypes.SELF_CORRECTION,
                    meta_data="副表内存收敛",
                )
                generated.backup_explicit_slots = self._backup_explicit_slots(
                    original, current
                )
                if activated_changes:
                    generated.log_source_title = format_backup_staffing_title(
                        activated_changes
                    )
                self._record_backup_retention(
                    generated, previous_data.config.free_room_exclusions
                )
                self._capture_shift_refresh_rules(
                    generated,
                    {
                        name: (op.refresh_drained, op.refresh_order_room)
                        for name, op in previous_data.operators.items()
                    },
                )
                generated.coordination_request_names = list(
                    dict.fromkeys(
                        name
                        for pending in superseded
                        if getattr(pending, "ordinary_coordination", False)
                        for name in pending.coordination_request_names
                    )
                )
                generated.ordinary_coordination = bool(
                    generated.coordination_request_names
                )
                for pending in superseded:
                    self._capture_shift_refresh_rules(
                        generated, getattr(pending, "backup_refresh_rules", {})
                    )
                    generated.backup_explicit_slots.update(
                        (room, index)
                        for room, index in getattr(pending, "backup_explicit_slots", ())
                        if transition_plan.get(room, [])[index : index + 1]
                        == pending.plan.get(room, [])[index : index + 1]
                    )
                # 完整最终任务先入队，再撤销旧任务，避免丢失同批有效动作。
                self.tasks.append(generated)
                resolve_mastery_backup_tasks(self.tasks, superseded, generated)
                superseded_ids = {id(task) for task in superseded}
                self.tasks[:] = [
                    task for task in self.tasks if id(task) not in superseded_ids
                ]
                self._refresh_deferred_product_reservations()
                if generated_tasks is not None:
                    generated_tasks.append(generated)
                self._log_arrangement("已生成任务", task=generated)

            self._sync_idle_release_tasks()
            # 只重建已有的回班队列，不凭切表制造普通回班。
            if had_rest_schedule:
                self.plan_metadata()
            # 回班重建和唤醒常规规划是两个独立步骤；没有实际换人也要规划。
            # 实际换班的完成边界会补回被延期或重启提前消费的空任务。
            followup = self._ensure_ordinary_planning_wake(custom_task_time)
            if followup is not None and generated_tasks is not None:
                generated_tasks.append(followup)
            return generated is not None
        except MowerExit:
            raise
        except Exception as e:
            _backup_timing_runtime.current.result = "演算失败"
            if previous_data is not None:
                self.op_data = previous_data
            save_exception(e)
            logger.exception(e)
        return False

    def rearrange_resting_priority(self, group):
        operators = [
            name
            for name in self.op_data.groups[group]
            if self.op_data.is_group_shift_anchor(self.op_data.operators[name])
        ]
        if len(operators) == len(self.op_data.groups[group]):
            operators = self.op_data.groups[group]
        # 肥鸭充能新模式：https://github.com/ArkMowers/arknights-mower/issues/551
        fia_plan, fia_room = self.check_fia()
        # 排序
        # 1. 肥鸭充能列表中的干员靠前
        # 2. 不在加工站的干员靠前
        # 3. 心情低的干员靠前
        operators.sort(
            key=lambda y: (
                y not in fia_plan if fia_plan else True,
                self.op_data.operators[y].current_room in ["factory", "train"],
                self.op_data.operators[y].current_mood()
                - self.op_data.operators[y].lower_limit,
            )
        )

        high_count = 0
        for operator in operators:
            if self.op_data.operators[operator].workaholic:
                continue
            if self.op_data.operators[operator].resting_priority == "high":
                high_count += 1
        for operator in operators:
            if self.op_data.operators[operator].workaholic:
                continue
            self.op_data.operators[operator].resting_priority = (
                "high" if high_count > 0 else "low"
            )
            high_count -= 1

    def get_resting_plan(
        self,
        agents,
        exist_replacement,
        plan,
        current_resting,
        *,
        dorm_admissions=None,
        request_names=None,
    ):
        excluded = self._protected_facility_names()
        if excluded:
            agents = [name for name in agents if name not in excluded]
        request_names = list(agents if request_names is None else request_names)
        request_names = [name for name in request_names if name not in excluded]
        groups = self.op_data.shift_request_groups(request_names)
        from arknights_mower.utils.backup_group_tasks import forced_work_groups

        if set(groups) & forced_work_groups(self.op_data):
            return False
        followers = {
            name
            for group in groups
            for name in self.op_data.shift_group_members(group)
            if self.op_data.operators[name].multi_group and name not in excluded
        }
        if not followers:
            return self._get_resting_plan(
                agents,
                exist_replacement,
                plan,
                current_resting,
                dorm_admissions=dorm_admissions,
                request_names=request_names,
            )
        transitions = self.op_data.arrangement_group_transitions(plan)
        transitions.update({group: True for group in groups})
        for name in followers:
            op = self.op_data.operators[name]
            resting = self.op_data.resting_binding_groups(op, transitions)
            common = self.op_data.shared_replacements(op, resting)
            if not common:
                logger.debug(
                    "多绑组替班不兼容，暂缓下班：%s，休息组：%s", name, resting
                )
                return
            if op.room.startswith("dorm"):
                bed = next(
                    (
                        bed
                        for bed in self.op_data.dorm
                        if bed.position == (op.room, op.index)
                    ),
                    None,
                )
                if bed is not None and bed.name and "Free" not in common:
                    return
        members = list(
            dict.fromkeys(
                [
                    *agents,
                    *(
                        name
                        for group in groups
                        for name in self.op_data.shift_group_members(group)
                        if name not in excluded
                    ),
                ]
            )
        )
        previous_groups = copy.deepcopy(self.op_data.groups)
        previous_state = self.op_data.group_shift_state
        previous_recovery = copy.deepcopy(
            getattr(self.op_data, "group_recovery_full_members", {})
        )
        previous_return_time = dict(
            getattr(self.op_data, "group_recovery_return_time", {})
        )
        previous = {
            name: (op.group, list(op.replacement))
            for name, op in self.op_data.operators.items()
            if op.multi_group
        }
        try:
            # Bed reservation is retained on admission; group state and bindings
            # remain hypothetical until the arrangement completes.
            self.op_data.group_shift_state = dict(previous_state)
            self.op_data.commit_group_shifts(transitions)
            return self._get_resting_plan(
                members,
                exist_replacement,
                plan,
                current_resting,
                dorm_admissions=dorm_admissions,
                request_names=request_names,
            )
        finally:
            self.op_data.group_shift_state = previous_state
            self.op_data.group_recovery_full_members = previous_recovery
            self.op_data.group_recovery_return_time = previous_return_time
            for name, (group, replacements) in previous.items():
                self.op_data.operators[name].group = group
                self.op_data.operators[name].replacement = replacements
            self.op_data.groups = previous_groups

    def _get_resting_plan(
        self,
        agents,
        exist_replacement,
        plan,
        current_resting,
        *,
        dorm_admissions=None,
        excluded_names=(),
        reserved_slots=(),
        failure_reasons=None,
        request_names=None,
    ):
        from arknights_mower.utils.exhaust_replacement import match_replacements

        excluded = self._protected_facility_names()
        request_names = list(agents if request_names is None else request_names)
        request_names = [name for name in request_names if name not in excluded]
        request_groups = self.op_data.shift_request_groups(request_names)
        if excluded:
            agents = [name for name in agents if name not in excluded]
        protected_training = self._protected_facility_names(include_configured=False)
        if not agents:
            if failure_reasons is not None:
                failure_reasons.append("待休息成员均受训练岗位保护")
            return
        self._refresh_deferred_product_reservations()
        retained_names, retained_slots = retained_task_reservations(
            self.op_data, self.tasks, current_task=getattr(self, "task", None)
        )
        waiting_names, waiting_slots = self._waiting_shift_reservations(
            returning_groups=self._returning_groups_releasing_waits(
                getattr(self, "task", None)
            ),
            current_task=getattr(self, "task", None),
        )
        retained_names.update(waiting_names)
        retained_slots.update(waiting_slots)
        retained_slots |= set(reserved_slots)
        reserved_names = (
            self.op_data.reserved_product_replacements
            | retained_names
            | set(excluded_names)
        )
        if any(name in reserved_names for name in agents):
            if failure_reasons is not None:
                failure_reasons.append(
                    "待休息成员已被其他任务预约："
                    + "、".join(sorted(set(agents) & reserved_names))
                )
            logger.debug(
                "整组含保留任务或延期切产物换班预约干员，保留当前安排：%s", agents
            )
            return
        # 宿舍成员只跟随换班，不以自身心情抢占组内替班或休息优先级。
        dorm_agents = [
            name
            for name in agents
            if self.op_data.operators[name].room.startswith("dorm")
        ]
        if dorm_agents:
            agents = [name for name in agents if name not in dorm_agents]
        __replacement = []
        __plan = {}
        replacement_options = {
            owner: [name]
            for owner, name in self.op_data.working_replacement_assignments(
                [*agents, *dorm_agents], plan
            ).items()
            if self.op_data.operators[name].multi_group
        }
        active_groups = {
            self.op_data.operators[name].group
            for name in [*agents, *dorm_agents]
            if self.op_data.operators[name].group
            and not self.op_data.operators[name].shift_group
        } | set(request_groups)
        if blockers := self.op_data.working_replacement_blockers(
            [*agents, *dorm_agents], plan, request_groups=request_groups
        ):
            if failure_reasons is not None:
                failure_reasons.append(
                    "待休息成员仍在为其他组替班：" + "、".join(sorted(blockers))
                )
            logger.debug("整组成员仍在为其他组替班，暂缓下班：%s", sorted(blockers))
            return
        already_resting = {
            name
            for name in [*agents, *dorm_agents]
            if not self.op_data.operators[name].multi_group
            and self.op_data.get_dorm_by_name(name)[0] is not None
        }
        required = 0
        for x in agents:
            op = self.op_data.operators[x]
            if op.workaholic or op.room.startswith("dorm") or x in already_resting:
                continue
            required += 1
        logger.debug(f"需求:{current_resting} 当前休息")
        logger.debug(f"需求:{required}宿舍空位")
        logger.debug(f"需求:{exist_replacement} 当前安排")
        logger.debug(f"当前计划{plan}")
        success = True

        fia_plan, fia_room = self.check_fia()
        agents.sort(
            key=lambda y: (
                y not in fia_plan if fia_plan else True,
                self.op_data.operators[y].current_room in ["factory", "train"],
                self.op_data.operators[y].current_mood()
                - self.op_data.operators[y].lower_limit,
            )
        )
        agents.extend(dorm_agents)
        logger.debug(f"计算排班:{agents}")
        superseded_covers = {
            previous[0]
            for name in agents
            if (op := self.op_data.operators[name]).independent_rest
            and (groups := self.op_data.resting_binding_groups(op))
            and (previous := plan.get(op.room, [])[op.index : op.index + 1])
            and previous[0] not in self.op_data.shared_replacements(op, groups)
        }
        for agent in agents:
            if not success:
                break
            x = self.op_data.operators[agent]
            if (x.room, x.index) in self.op_data.reserved_product_beds or (
                x.room,
                x.index,
            ) in retained_slots:
                if failure_reasons is not None:
                    failure_reasons.append(f"{agent}的主班岗位已被其他任务预约")
                success = False
                break
            if x.room not in base_room_list:
                if failure_reasons is not None:
                    failure_reasons.append(f"{agent}的主班房间无效：{x.room}")
                logger.debug(f"干员房间出错:{agent}")
                success = False
                break
            if agent in already_resting:
                # 已休息成员保留原床位和岗位替班，继续安排其余成员下班。
                continue

            if self.op_data.is_auto_free_dorm_operator(x):
                # 同组姓名只开启这张临时床；不把该姓名安排进宿舍，固定
                # 宿舍成员离岗期间由统一动态床位算法决定实际入住者。
                actual = self.op_data.get_current_operator(x.room, x.index)
                __plan.setdefault(x.room, ["Current"] * len(self.op_data.plan[x.room]))[
                    x.index
                ] = (
                    "Current"
                    if x.multi_group and actual is not None and actual.name != x.name
                    else "Free"
                )
                continue

            def replacement_available(obj):
                replacement = self.op_data.operators[obj]
                in_slot = (replacement.current_room, replacement.current_index) == (
                    x.room,
                    x.index,
                )
                same_group_cover = self.op_data.is_same_group_primary_replacement(
                    x, obj
                )
                if (
                    replacement.current_room
                    and not replacement.is_resting()
                    and not in_slot
                    and not self._training_replacement_allowed(replacement)
                    and not (
                        same_group_cover
                        and obj in agents
                        and (replacement.current_room, replacement.current_index)
                        == (replacement.room, replacement.index)
                    )
                ):
                    return False
                if not in_slot and self.op_data.replacement_exhausted(obj, operator=x):
                    return False
                return (
                    obj not in TRADE_ORDER_AGENTS
                    and obj not in already_resting
                    and not _is_mastery_busy(obj)
                    and obj not in protected_training
                    and (
                        obj not in exist_replacement
                        or obj in superseded_covers
                        or plan.get(x.room, [])[x.index : x.index + 1] == [obj]
                    )
                    and obj not in reserved_names
                    and (not self.op_data.is_dorm_replacement(obj) or in_slot)
                    and (
                        x.room.startswith("dorm")
                        or replacement.current_room != x.room
                        or same_group_cover
                        and obj in agents
                        or in_slot
                    )
                )

            replacement_options[agent] = [
                obj
                for obj in self.op_data.replacement_candidates(x)
                if replacement_available(obj)
            ]
        assignments = {}
        if success:
            assignments = match_replacements(replacement_options)
            if assignments is None:
                matched = match_replacements(replacement_options, allow_partial=True)
                missing = [name for name in replacement_options if name not in matched]
                if failure_reasons is not None:
                    failure_reasons.append(
                        f"无法为{'、'.join(missing)}匹配完整替班；"
                        f"可用替班：{replacement_options}"
                    )
                logger.debug(
                    "整组替班不足，暂缓下班：%s；缺%s名替班，未匹配成员：%s；可用替班：%s",
                    agents,
                    len(missing),
                    missing,
                    replacement_options,
                )
                return
        if success:
            working = tuple(
                name
                for name in agents
                if not self.op_data.operators[name].room.startswith("dorm")
                and not self.op_data.operators[name].workaholic
            )
            allocation_plan = copy.deepcopy({**plan, **__plan})
            admissions = {}
            for task in sorted(self.tasks, key=lambda task: task.time):
                if task is getattr(self, "task", None) or (
                    task.type != TaskTypes.SHIFT_OFF and not task.retains_execution
                ):
                    continue
                for room, names in task.plan.items():
                    if not room.startswith("dorm"):
                        continue
                    for index, name in enumerate(names):
                        if index < len(self.op_data.plan.get(room, [])) and (
                            name in self.op_data.operators
                        ):
                            admissions.setdefault((room, index), name)
            queued_slots = set(admissions)
            admissions.update(dorm_admissions or {})
            # 已入队和本轮成功分床显式占用额度，不从陈旧床位缓存推断预约。
            for (room, index), name in admissions.items():
                row = allocation_plan.setdefault(
                    room, ["Current"] * len(self.op_data.plan[room])
                )
                if row[index] in ("Current", "Free"):
                    row[index] = name
            for attempt in range(2):
                if attempt:
                    assignments = match_replacements(
                        replacement_options, preferred=working
                    )
                    if assignments is None:
                        if failure_reasons is not None:
                            failure_reasons.append(
                                f"保留恢复床位时无法匹配完整替班：{replacement_options}"
                            )
                        return
                assigned_covers = set(assignments.values())
                resting_agents = [
                    x
                    for x in agents
                    if not self.op_data.operators[x].workaholic
                    and not self.op_data.operators[x].room.startswith("dorm")
                    and x not in assigned_covers
                    and self.op_data.get_dorm_by_name(x)[0] is None
                    and not (
                        self.op_data.operators[x].multi_group
                        and any(bed.name == x for bed in self.op_data.all_dorms())
                        and plan.get(self.op_data.operators[x].room, [])[
                            self.op_data.operators[x].index : self.op_data.operators[
                                x
                            ].index
                            + 1
                        ]
                        not in ([], ["Current"])
                    )
                ]
                # 先按配置首选验证整组分床；床位不足时，完整匹配优先
                # 保留可恢复工作替班，不把固定宿舍位开放为普通 Free。
                cover_plan = copy.deepcopy(allocation_plan)
                for agent, replacement in assignments.items():
                    owner = self.op_data.operators[agent]
                    cover_plan.setdefault(
                        owner.room, ["Current"] * len(self.op_data.plan[owner.room])
                    )[owner.index] = replacement
                # 接岗替班先在副本离宿，分床才能使用同次换班腾出的床位。
                projected = self.op_data.project_arrangements([cover_plan])
                dorms = projected.assign_dorm_group(
                    resting_agents,
                    active_groups=active_groups,
                    plan=allocation_plan,
                    reserved_slots=retained_slots | queued_slots,
                )
                if dorms is not None:
                    actual_beds = {bed.position: bed for bed in self.op_data.dorm}
                    for bed in dorms:
                        actual_beds[bed.position].name = bed.name
                        actual_beds[bed.position].time = bed.time
                    dorms = [actual_beds[bed.position] for bed in dorms]
                    break
            else:
                if failure_reasons is not None:
                    failure_reasons.append(
                        "宿舍床位无法满足休息安排：" + "、".join(resting_agents)
                    )
                return
            for agent, replacement in assignments.items():
                x = self.op_data.operators[agent]
                __replacement.append(replacement)
                cover = self.op_data.operators[replacement]
                if agent not in agents and (
                    cover.current_room,
                    cover.current_index,
                ) == (
                    x.room,
                    x.index,
                ):
                    continue
                __plan.setdefault(x.room, ["Current"] * len(self.op_data.plan[x.room]))[
                    x.index
                ] = replacement
            logger.debug(f"当前替换{__replacement}")
            exist_replacement.extend(
                name for name in __replacement if name not in exist_replacement
            )
            logger.debug(dorms)
            for k, v in __plan.items():
                if k not in plan.keys():
                    plan[k] = __plan[k]
                for idx, name in enumerate(__plan[k]):
                    owner = self.op_data.operators.get(self.op_data.plan[k][idx].agent)
                    if name != "Current" and (
                        plan[k][idx] == "Current"
                        or owner is not None
                        and owner.multi_group
                    ):
                        previous_cover = plan[k][idx]
                        if (
                            previous_cover in exist_replacement
                            and previous_cover != name
                        ):
                            exist_replacement.remove(previous_cover)
                        plan[k][idx] = name
            logger.debug(f"当前plan{plan}")
            if dorm_admissions is not None:
                dorm_admissions.update({bed.position: bed.name for bed in dorms})
            return True

    def initialize_operators(self):
        self.op_data = Operators(
            self.global_plan,
            facility_levels=getattr(self, "source_plan", {}).get("facility_levels"),
        )
        Operators.current_room_changed_callback = self.current_room_changed
        return self.op_data.init_and_validate()

    @staticmethod
    def _product_switching_enabled():
        return getattr(getattr(config.conf, "product_switching", None), "enable", False)

    def _discard_product_switches(self):
        """停用切换时移除专用任务，释放预留并保留原换班安排。"""
        display_states = getattr(self, "_product_switch_log_states", {})
        for state in tuple(display_states.values()):
            self._publish_product_switch_log(state, "failed", "产物切换已停用")
        display_states.clear()
        self.tasks[:] = [
            task for task in self.tasks if task.type != TaskTypes.SWITCH_PRODUCT
        ]
        for task in self.tasks:
            if getattr(task, "product_shift_locked", False):
                task.time = min(task.time, datetime.now())
            for attr in (
                "pending_product_targets",
                "product_shift_locked",
                "product_lock_slots",
                "product_lock_names",
                "product_switched_before_arrangement",
                "product_switch_progress",
                "product_switch_budget_seconds",
            ):
                if hasattr(task, attr):
                    delattr(task, attr)
        self.tasks.sort(
            key=lambda task: (bool(getattr(task, "execution_failure", None)), task.time)
        )
        selected = getattr(self, "task", None)
        if selected is not None and selected.type == TaskTypes.SWITCH_PRODUCT:
            self.task = None
        self._refresh_deferred_product_reservations()

    def queue_product_switches(self):
        """仅为已识别且与当前排班目标不一致的生产站生成任务。"""
        if not self._product_switching_enabled():
            self._discard_product_switches()
            return
        products = getattr(self.op_data, "products", None)
        if products is None:
            return
        plan = getattr(self.op_data, "plan", {})
        facility_states = getattr(self.op_data, "facility_states", {})
        configured_rooms = set()
        pending_targets = {}
        for task in self.tasks if self._product_switching_enabled() else ():
            pending_targets.update(getattr(task, "pending_product_targets", {}))
        for room, target_product in (products | pending_targets).items():
            room_plan = plan.get(room) or []
            if not room_plan:
                continue
            facility = room_plan[0].facility
            supported = (
                facility == "制造站" and target_product in MANUFACTURE_PRODUCTS
            ) or (facility == "贸易站" and target_product in TRADE_PRODUCTS)
            if not supported:
                continue
            configured_rooms.add(room)

            existing = [
                task
                for task in self.tasks
                if task.type == TaskTypes.SWITCH_PRODUCT
                and task.meta_data.split(",", 1)[0] == room
            ]
            if room in pending_targets:
                # 关联换班或副表前置任务负责切换，不能被旧排班反向覆盖。
                obsolete_ids = {
                    id(task)
                    for task in existing
                    if not getattr(task, "pending_backup_product_switch", False)
                }
                self.tasks[:] = [
                    task for task in self.tasks if id(task) not in obsolete_ids
                ]
                continue
            state = facility_states.get(room)
            expected_facility = "manufacture" if facility == "制造站" else "trade"
            if not state or state.get("facility") != expected_facility:
                self.tasks[:] = [
                    task
                    for task in self.tasks
                    if all(task is not previous for previous in existing)
                ]
                logger.debug(
                    f"{self.translate_room(room)}尚无设施状态缓存，暂不生成切换任务"
                )
                continue
            if state.get("product") == target_product:
                if existing:
                    self.tasks[:] = [
                        task
                        for task in self.tasks
                        if all(task is not previous for previous in existing)
                    ]
                    logger.info(
                        f"{self.translate_room(room)}实际产物或订单已符合排班，"
                        "移除待切换任务"
                    )
                continue

            target_meta = product_task_meta(room, target_product)
            if len(existing) == 1 and existing[0].meta_data == target_meta:
                continue
            self.tasks[:] = [
                task
                for task in self.tasks
                if all(task is not previous for previous in existing)
            ]
            self.tasks.append(
                SchedulerTask(
                    task_type=TaskTypes.SWITCH_PRODUCT,
                    meta_data=target_meta,
                )
            )
            logger.info(
                f"生成{self.translate_room(room)}切换产物或订单的任务：{target_product}"
            )

        self.tasks[:] = [
            task
            for task in self.tasks
            if task.type != TaskTypes.SWITCH_PRODUCT
            or task.meta_data.split(",", 1)[0] in configured_rooms
        ]
        selected = getattr(self, "task", None)
        if (
            selected is not None
            and selected.type == TaskTypes.SWITCH_PRODUCT
            and selected not in self.tasks
        ):
            self.task = None

    def _products_after_arrangement(self, plan):
        """在排班快照上推演换班后的副表，不改动真实排班缓存。"""
        if self._initial_mood_read_pending():
            return self.op_data.products, self.op_data.plan
        projected = self.op_data.project_arrangements([plan])

        seen = {tuple(projected.plan_condition)}
        while projected.backup_plans:
            selection = self._evaluate_backup_selection(projected)
            conditions = selection.conditions
            if conditions == projected.plan_condition:
                break
            if tuple(conditions) in seen:
                logger.warning("换班前副表产物推演出现循环，维持当前目标")
                break
            seen.add(tuple(conditions))
            if error := projected.swap_plan(
                conditions, backup_group=selection.group_id
            ):
                raise ValueError(f"换班前副表产物推演失败：{error}")
        return projected.products, projected.plan

    def _backup_explicit_slots(self, original, conditions):
        """Return concrete entry-task slots owned by newly activated backups."""
        return {
            (room, index)
            for active, enabled, bp in zip(
                original, conditions, self.op_data.backup_plans
            )
            if enabled and not active
            for room, names in (bp.task or {}).items()
            for index, name in enumerate(names)
            if name != "Current"
        }

    def _prepare_group_shift(self, task, *, remember_targets=False):
        """Complete group targets and admit only independent unconfirmed shifts."""
        self._prepare_fia_return(task)
        self._prepare_group_shift_execution_targets(task)
        self.op_data.commit_group_shifts({})
        proposed = copy.deepcopy(task.plan)
        returning_zero_groups = {
            op.group
            for room, row in proposed.items()
            if not room.startswith("dorm")
            for index, name in enumerate(row)
            if (op := self.op_data.operators.get(name)) is not None
            and not op.multi_group
            and (op.room, op.index) == (room, index)
            and self.op_data.group_is_resting(op.group)
            and self.op_data.is_workaholic_group(op.group)
        }
        for group in returning_zero_groups:
            for name in self.op_data.shift_group_members(group):
                op = self.op_data.operators[name]
                if op.multi_group:
                    continue
                target = proposed.get(op.room, [])[op.index : op.index + 1]
                if target in ([], ["Current"]) and (
                    op.current_room,
                    op.current_index,
                ) != (op.room, op.index):
                    proposed.setdefault(
                        op.room, ["Current"] * len(self.op_data.plan[op.room])
                    )[op.index] = name
        self._suppress_dispatchable_arrangement(task, proposed)
        complete_returns = self.op_data.arrangement_group_transitions(proposed)
        incomplete_rooms = {
            op.room
            for group in returning_zero_groups
            if complete_returns.get(group) is not False
            for name in self.op_data.shift_group_members(group)
            if not (op := self.op_data.operators[name]).multi_group
            and proposed.get(op.room, [])[op.index : op.index + 1] != [name]
            and not (
                proposed.get(op.room, [])[op.index : op.index + 1] in ([], ["Current"])
                and (op.current_room, op.current_index) == (op.room, op.index)
            )
        }
        if incomplete_rooms:
            raise ProductSwitchDeferred(
                "全零心情组的完整回班安排尚不可用",
                rooms=tuple(sorted(incomplete_rooms)),
            )
        transitions = dict(getattr(task, "group_shift_transitions", {}))
        transitions.update(complete_returns)
        from arknights_mower.utils.backup_group_tasks import (
            forced_work_groups,
            held_rest_groups,
        )

        predecessors = self._group_shift_predecessors(task, proposed, transitions)
        if predecessors:
            raise GroupShiftBlocked(predecessors=predecessors)
        reserved = {
            name
            for pending in self._deferred_product_locks(exclude=task)
            for name in pending.product_lock_names
        }
        if not task.retains_execution and not getattr(
            task, "product_shift_locked", False
        ):
            # Resolve fixed shared dormitory covers before allocating recovery beds.
            if not self.op_data.normalize_shared_arrangement(
                proposed,
                transitions,
                reserved_replacements=reserved,
                explicit_slots=getattr(task, "backup_explicit_slots", ()),
                excluded_names=self._protected_facility_names(),
                excluded_replacements=self._protected_facility_names(
                    include_configured=False
                ),
            ):
                raise GroupShiftBlocked(self._shared_shift_blockers(task, transitions))
            self._complete_ordinary_group_targets(task, proposed, transitions)
        normalized = copy.deepcopy(proposed) if task.retains_execution else proposed
        if (
            not self.op_data.normalize_shared_arrangement(
                normalized,
                transitions,
                reserved_replacements=reserved,
                explicit_slots=getattr(task, "backup_explicit_slots", ()),
                excluded_names=self._protected_facility_names(),
                excluded_replacements=self._protected_facility_names(
                    include_configured=False
                ),
            )
            or task.retains_execution
            and any(
                name != "Current"
                and normalized.get(room, [])[index : index + 1] != [name]
                and not (
                    normalized.get(room, [])[index : index + 1] in ([], ["Current"])
                    and (actual := self.op_data.get_current_operator(room, index))
                    is not None
                    and actual.name == name
                )
                for room, row in proposed.items()
                for index, name in enumerate(row)
            )
        ):
            raise GroupShiftBlocked(self._shared_shift_blockers(task, transitions))
        predecessors = self._group_shift_predecessors(task, proposed, transitions)
        if predecessors:
            raise GroupShiftBlocked(predecessors=predecessors)
        forced = held_rest_groups(self.op_data, forced_only=True)
        if any(
            not resting and group in forced for group, resting in transitions.items()
        ) and not (
            getattr(task, "mood_physical_started", False)
            or getattr(task, "group_shift_expected", {})
        ):
            raise ProductSwitchDeferred(
                "副表要求整组强制下班，等待副表退出", rooms=tuple(proposed)
            )
        if any(
            resting and group in forced_work_groups(self.op_data)
            for group, resting in transitions.items()
        ) and not (
            getattr(task, "mood_physical_started", False)
            or getattr(task, "group_shift_expected", {})
        ):
            raise ProductSwitchDeferred(
                "副表要求整组强制上班，等待副表退出", rooms=tuple(proposed)
            )
        task.plan = proposed
        task.group_shift_transitions = transitions
        if getattr(task, "exhaust_support", False):
            from arknights_mower.utils.urgent_recovery import prepare_urgent_support

            prepare_urgent_support(self.op_data, task, task.coordination_request_names)
            if getattr(task, "ordinary_coordination", False) and getattr(
                task, "urgent_recovery_support_names", ()
            ):
                admission = self._coordination_admission_plan(
                    self.op_data.project_arrangements([task.plan]),
                    task.coordination_request_names,
                )
                if admission:
                    task.coordination_admission_plan = admission
        if remember_targets and transitions:
            expected = getattr(task, "group_shift_expected", {})
            for room, names in proposed.items():
                for index, name in enumerate(names):
                    if name == "Current":
                        continue
                    expected.pop((room, index), None)
                    if name not in ("Free", ""):
                        expected = {
                            slot: occupant
                            for slot, occupant in expected.items()
                            if occupant != name
                        }
                        expected[room, index] = name
            task.group_shift_expected = expected
        self._prepare_group_shift_execution_targets(task)

    def _prepare_group_shift_execution_targets(self, task):
        """执行前同步合法取消与岗位保护，不补回已经完成的房间。"""
        if not hasattr(task, "group_shift_transitions"):
            return
        pending_zero_returns = {}
        for (room, index), name in getattr(task, "group_shift_expected", {}).items():
            op = self.op_data.operators.get(name)
            if (
                op is not None
                and not op.multi_group
                and getattr(task, "group_shift_transitions", {}).get(op.group) is False
                and self.op_data.group_is_resting(op.group)
                and self.op_data.is_workaholic_group(op.group)
                and (op.current_room, op.current_index) != (room, index)
            ):
                pending_zero_returns.setdefault(
                    room, ["Current"] * len(self.op_data.plan[room])
                )[index] = name
        permitted = copy.deepcopy(pending_zero_returns)
        self._suppress_facility_arrangement(permitted)
        blocked_rooms = {
            room
            for room, row in pending_zero_returns.items()
            for index, name in enumerate(row)
            if name != "Current"
            and permitted.get(room, [])[index : index + 1] != [name]
        }
        if blocked_rooms:
            raise ProductSwitchDeferred(
                "全零心情组的未完成回班岗位仍受保护",
                rooms=tuple(sorted(blocked_rooms)),
            )
        for room, row in pending_zero_returns.items():
            for index, name in enumerate(row):
                if name != "Current":
                    task.plan.setdefault(
                        room, ["Current"] * len(self.op_data.plan[room])
                    )[index] = name
        expected_plan = {}
        for (room, index), name in getattr(task, "group_shift_expected", {}).items():
            expected_plan.setdefault(
                room, ["Current"] * len(self.op_data.get_current_room(room, True))
            )[index] = name
        original_transitions = self.op_data.arrangement_group_transitions(expected_plan)
        transitions = self.op_data.arrangement_group_transitions(
            task.plan, group_transitions=task.group_shift_transitions
        )
        self._cancel_dorm_recovery_targets(expected_plan, transitions, task=task)
        skipped = getattr(task, "training_skipped_slots", ())
        if skipped and getattr(task, "arrangement_failures", {}).get("train"):
            skipped = ()
        for plan in (task.plan, expected_plan):
            for index in skipped:
                if index < len(plan.get("train", [])) and pending_zero_returns.get(
                    "train", []
                )[index : index + 1] in ([], ["Current"]):
                    plan["train"][index] = "Current"
            self._suppress_dispatchable_arrangement(task, plan)
        remaining_transitions = self.op_data.arrangement_group_transitions(
            expected_plan
        )
        for group in original_transitions.keys() - remaining_transitions.keys():
            task.group_shift_transitions.pop(group, None)
        for group, resting in remaining_transitions.items():
            if resting != original_transitions[group]:
                task.group_shift_transitions[group] = resting
        task.group_shift_expected = {
            (room, index): name
            for room, names in expected_plan.items()
            for index, name in enumerate(names)
            if name not in ("Current", "Free", "")
        }

    def _complete_ordinary_group_targets(self, task, plan, transitions):
        """Complete fixed and shared departures with both covers and recovery beds."""
        explicit = set(getattr(task, "backup_explicit_slots", ()))
        explicit_names = {
            row[index]
            for room, index in explicit
            if index < len(row := plan.get(room, []))
        }
        training_targets = {
            "train": [slot.agent for slot in self.op_data.plan.get("train", [])]
        }
        self._suppress_facility_arrangement(training_targets)
        protected_training = self._protected_facility_names()
        skipped_training = set(getattr(task, "training_skipped_slots", ()))
        missing = set()
        returns = {}
        ordinary_intent = self.op_data.arrangement_group_transitions(
            {room: row for room, row in plan.items() if room != "train"}
        )
        for group, resting in transitions.items():
            if (
                self.op_data.group_is_resting(group) == resting
                or group not in ordinary_intent
            ):
                continue
            for name in self.op_data.shift_group_members(group):
                op = self.op_data.operators[name]
                if (
                    name in protected_training
                    or self.op_data._can_standby(op)
                    or op.multi_group
                    and (op.workaholic or op.room.startswith("dorm"))
                ):
                    continue
                if (op.room, op.index) in explicit or name in explicit_names:
                    continue
                if op.room == "train" and (
                    op.index in skipped_training
                    or op.index >= len(training_targets.get("train", []))
                    or training_targets["train"][op.index] == "Current"
                ):
                    continue
                target = plan.get(op.room, [])[op.index : op.index + 1]
                member_resting = (
                    bool(self.op_data.resting_binding_groups(op, transitions))
                    if op.multi_group
                    else resting
                )
                if not member_resting and not (op.independent_rest and op.is_resting()):
                    returns.setdefault(
                        op.room, ["Current"] * len(self.op_data.plan[op.room])
                    )[op.index] = name
                else:
                    if not target or target == ["Current"]:
                        actual = self.op_data.get_current_operator(op.room, op.index)
                        if actual is not None and actual.name in op.replacement:
                            plan.setdefault(
                                op.room, ["Current"] * len(self.op_data.plan[op.room])
                            )[op.index] = actual.name
                        elif not op.is_resting():
                            missing.add(name)
                    if (
                        not op.workaholic
                        and not op.room.startswith("dorm")
                        and not op.is_resting()
                        and not any(name in row for row in plan.values())
                    ):
                        missing.add(name)
        _merge_shift_transition(plan, returns, self.op_data)
        if missing:
            simulation = copy.copy(self)
            simulation.op_data = self.op_data.project_arrangements([plan])
            simulation.op_data.commit_group_shifts(transitions)
            simulation.tasks = [
                pending for pending in self.tasks if pending is not task
            ]
            simulation.task = task
            replacements = list(_assigned_operator_names(plan))
            admissions = {}
            if not simulation._get_resting_plan(
                sorted(missing),
                replacements,
                plan,
                self.op_data.active_high_resting_count(),
                dorm_admissions=admissions,
                request_names=[],
            ):
                raise GroupShiftBlocked(self._shared_shift_blockers(task, transitions))
            for (room, index), name in admissions.items():
                plan.setdefault(room, ["Current"] * len(self.op_data.plan[room]))[
                    index
                ] = name
        before_training = self.op_data.arrangement_group_transitions(plan)
        self._suppress_facility_arrangement(plan)
        after_training = self.op_data.arrangement_group_transitions(plan)
        for group in before_training.keys() - after_training.keys():
            transitions.pop(group, None)

    def _group_shift_predecessors(self, task, plan, transitions):
        """Started shifts own their group, shared bindings, named slots and occupants."""
        protected_training = self._protected_facility_names()

        def footprint(arrangement, shifts):
            arrangement = copy.deepcopy(arrangement)
            original = self.op_data.arrangement_group_transitions(arrangement)
            self._suppress_facility_arrangement(arrangement)
            remaining = self.op_data.arrangement_group_transitions(arrangement)
            if not arrangement:
                return set(), set(), set()
            shifts = {
                key: value
                for key, value in shifts.items()
                if key not in original.keys() - remaining.keys()
            }
            groups = set(shifts)
            slots = {
                (room, index)
                for room, row in arrangement.items()
                for index, name in enumerate(row)
                if name != "Current"
            }
            names = set(_assigned_operator_names(arrangement))
            for op in self.op_data.operators.values():
                if (
                    op.multi_group
                    and op.name not in protected_training
                    and any(binding["group"] in groups for binding in op.group_bindings)
                ):
                    names.add(op.name)
                    slots.add((op.room, op.index))
            names.update(
                actual.name
                for room, index in slots
                if (actual := self.op_data.get_current_operator(room, index))
                is not None
            )
            return groups, slots, names

        desired = footprint(plan, transitions)
        predecessors = []
        for pending in self.tasks:
            expected = getattr(pending, "group_shift_expected", {})
            if pending is task or not expected:
                continue
            from arknights_mower.utils.retained_recovery import (
                retained_recovery_may_return,
            )

            returning = [group for group, resting in transitions.items() if not resting]
            arrangement = copy.deepcopy(pending.plan)
            for (room, index), name in expected.items():
                arrangement.setdefault(
                    room, ["Current"] * len(self.op_data.get_current_room(room, True))
                )[index] = name
            owned = footprint(
                arrangement, getattr(pending, "group_shift_transitions", {})
            )
            released_groups = {
                group
                for group in returning
                if retained_recovery_may_return(self.op_data, pending, group)
            }
            released_names = {
                name
                for group in released_groups
                for name in self.op_data.shift_group_members(group)
            }
            released_slots = {
                position
                for name in released_names
                for op in (self.op_data.operators[name],)
                for position in (
                    (op.room, op.index),
                    (op.current_room, op.current_index),
                )
            }
            owned = (
                owned[0] - released_groups,
                owned[1] - released_slots,
                owned[2] - released_names,
            )
            if any(left & right for left, right in zip(desired, owned)):
                predecessors.append(pending)
        return predecessors

    def _shared_shift_blockers(self, task, transitions):
        """Identify confirmed resting dependencies without guessing return times."""
        protected_training = self._protected_facility_names()
        groups = self.op_data.working_replacement_blockers(
            {
                name
                for group, resting in transitions.items()
                if resting
                for name in self.op_data.shift_group_members(group)
                if name not in protected_training
            },
            task.plan,
            request_groups=[group for group, resting in transitions.items() if resting],
        )
        if (
            any(transitions.values())
            and not task.retains_execution
            and not any(
                getattr(task, flag, False)
                for flag in (
                    "mood_physical_started",
                    "derived_correction_started",
                    "group_shift_expected",
                    "product_shift_locked",
                )
            )
        ):
            groups.update(
                group
                for group, resting in transitions.items()
                if not resting and self.op_data.group_is_resting(group)
            )
        explicit = getattr(task, "backup_explicit_slots", ())
        for op in self.op_data.operators.values():
            if (
                not op.multi_group
                or op.name in protected_training
                or (op.room, op.index) in explicit
                or not (
                    op.index < len(task.plan.get(op.room, []))
                    or any(b["group"] in transitions for b in op.group_bindings)
                )
            ):
                continue
            groups.update(
                group
                for group in self.op_data.resting_binding_groups(op, transitions)
                if self.op_data.group_is_resting(group)
            )
        return groups

    def _departure_recovery_signature(self, names, *, current_task=None):
        members = set(names)
        members.update(
            cover
            for name in names
            if name in self.op_data.operators
            for cover in self.op_data.replacement_candidates(
                self.op_data.operators[name]
            )
        )
        members.update(
            op.name for op in self.op_data.operators.values() if op.is_resting()
        )
        reserved_names, reserved_slots, _, _ = self._dorm_recovery_reservations(
            [task for task in self.tasks if task is not current_task],
            current_task=current_task,
        )
        return (
            tuple(self.op_data.plan_condition),
            tuple(sorted(reserved_names & members)),
            tuple(sorted(reserved_slots)),
            tuple(sorted(self.op_data.reserved_product_beds.items())),
            tuple(
                (name, op.current_room, op.current_index, op.time_stamp, op.mood)
                for name in sorted(members)
                if (op := self.op_data.operators.get(name)) is not None
            ),
            tuple(
                (bed.position, bed.name, bed.time) for bed in self.op_data.all_dorms()
            ),
        )

    def _suspend_group_shift(self, task, groups, *, predecessors=(), recovery_names=()):
        task.group_shift_waiting = set(groups)
        if recovery_names:
            task.departure_recovery_names = tuple(recovery_names)
            task.departure_recovery_observation = self._departure_recovery_signature(
                recovery_names, current_task=task
            )
        task.group_shift_predecessors = tuple(predecessors)
        waiting = getattr(self, "waiting_group_shifts", [])
        if all(pending is not task for pending in waiting):
            waiting.append(task)
        self.waiting_group_shifts = waiting
        self.tasks[:] = [pending for pending in self.tasks if pending is not task]
        self._refresh_deferred_product_reservations()
        self.op_data.correct_dorm(group_transitions=self._pending_group_transitions())

    def _resume_waiting_group_shifts(self, *, refresh_migrations_only=False):
        """Cached state changes release suspended work; no timer dispatch is used."""
        if not refresh_migrations_only:
            self._discard_legacy_recovery_checks()
        if not getattr(self, "waiting_group_shifts", ()):
            return
        if self._initial_mood_read_pending() or self._emergency_frozen():
            return
        for task in list(getattr(self, "waiting_group_shifts", ())):
            refreshed_migration = (
                task.type == TaskTypes.RE_ORDER
                and self._refresh_derived_correction(task)
            )
            if refresh_migrations_only and not refreshed_migration:
                continue
            departure_names = getattr(task, "departure_recovery_names", ())
            if departure_names and getattr(
                task, "departure_recovery_observation", None
            ) == (
                self._departure_recovery_signature(departure_names, current_task=task)
            ):
                continue
            if any(
                getattr(pending, "group_shift_expected", {})
                and any(queued is pending for queued in self.tasks)
                for pending in getattr(task, "group_shift_predecessors", ())
            ):
                continue
            if not refreshed_migration and any(
                self.op_data.group_is_resting(group)
                for group in task.group_shift_waiting
            ):
                continue
            try:
                if departure_names:
                    self._prepare_shift_backup(task)
                    task.__dict__.pop("departure_recovery_names", None)
                    task.__dict__.pop("departure_recovery_observation", None)
                self._refresh_derived_correction(task)
                self._prepare_group_shift(task)
            except GroupShiftBlocked as error:
                task.group_shift_waiting = error.groups
                task.group_shift_predecessors = error.predecessors
                if error.recovery_names:
                    task.departure_recovery_names = error.recovery_names
                    task.departure_recovery_observation = (
                        self._departure_recovery_signature(
                            error.recovery_names, current_task=task
                        )
                    )
                continue
            except ProductSwitchDeferred as error:
                task.product_shift_waiting = True
                if error.dependencies:
                    task.product_shift_predecessors = error.dependencies
                self._retain_failed_task(
                    task,
                    str(error),
                    error.rooms or tuple(task.plan),
                    dependency=True,
                )
            task.__dict__.pop("departure_recovery_names", None)
            task.__dict__.pop("departure_recovery_observation", None)
            del task.group_shift_waiting
            task.__dict__.pop("group_shift_predecessors", None)
            self.waiting_group_shifts[:] = [
                pending for pending in self.waiting_group_shifts if pending is not task
            ]
            self.tasks.append(task)
            self._refresh_deferred_product_reservations()
            logger.debug("换班等待条件已满足，恢复原安排：%s", task.plan)

    def _complete_group_shift(self, task):
        """Confirm required targets; mastery-owned slots retain their protection."""
        if not hasattr(task, "group_shift_transitions"):
            task.__dict__.pop("backup_refresh_rules", None)
            from arknights_mower.utils.urgent_recovery import complete_urgent_recovery

            self._queue_ordinary_coordination_admission(task)
            complete_urgent_recovery(self.op_data, task, self.tasks)
            return True
        missing = {}
        differences = []
        for (room, index), name in getattr(task, "group_shift_expected", {}).items():
            actual = self.op_data.get_current_operator(room, index)
            if actual is None or actual.name != name:
                missing.setdefault(
                    room, ["Current"] * len(self.op_data.get_current_room(room, True))
                )[index] = name
                differences.append(
                    {
                        "room": room,
                        "position": index + 1,
                        "expected": name,
                        "actual": actual.name if actual is not None else "",
                    }
                )
        if missing:
            task.plan = missing
            logger.warning(
                "换班核验差异：任务=%s@%s，差异=%s",
                task.type.display_value,
                task.time.isoformat(),
                differences,
            )
            self._retain_failed_task(task, "换班实测驻员与目标不一致", missing)
            return False
        transitions = getattr(task, "group_shift_transitions", {})
        changes = {
            group: "下班" if resting else "上班"
            for group, resting in transitions.items()
            if self.op_data.group_is_resting(group) != resting
        }
        self.op_data.commit_group_shifts(transitions)
        from arknights_mower.utils.urgent_recovery import complete_urgent_recovery

        self._queue_ordinary_coordination_admission(task)
        complete_urgent_recovery(self.op_data, task, self.tasks)
        if changes:
            descriptions, agents = [], []
            for group, action in changes.items():
                members = self.op_data.shift_group_members(group)
                if len(members) == 1:
                    agents.append(members[0])
                    subject = f"[[operator:{members[0]}]]"
                else:
                    subject = group
                descriptions.append(subject + action)
            logger.info(
                "绑组换班确认完成：%s",
                "；".join(descriptions),
                extra={"log_agents": agents},
            )
        task.group_shift_expected = {}
        task.__dict__.pop("training_skipped_slots", None)
        # 全部目标已实测确认，完成的换班不再占用失败保留预约。
        task.__dict__.pop("execution_failure", None)
        task.__dict__.pop("execution_retained", None)
        task.__dict__.pop("backup_refresh_rules", None)
        self._resume_waiting_group_shifts()
        return True

    def _suppress_retained_arrangements(
        self, plan, *, returning_groups=(), reservation_tasks=None
    ):
        """派生安排不重做保留任务，也不挪用其目标和当前驻员。"""
        returning = [
            group
            for group, resting in self.op_data.arrangement_group_transitions(
                plan
            ).items()
            if not resting
        ]

        def reservations(recovering_name=None):
            waiting_names, waiting_slots = self._waiting_shift_reservations(
                returning_groups=returning_groups, recovering_name=recovering_name
            )
            names, slots = retained_task_reservations(
                self.op_data,
                self.tasks if reservation_tasks is None else reservation_tasks,
                current_task=getattr(self, "task", None),
                returning_groups=returning,
                recovering_name=recovering_name,
            )
            return names | waiting_names, slots | waiting_slots

        names, slots = reservations()
        recovery = {}
        for room, row in list(plan.items()):
            for index, name in enumerate(row):
                if (room, index) in slots or name in names:
                    if room.startswith("dorm") and name in self.op_data.operators:
                        if name not in recovery:
                            recovery[name] = reservations(name)
                        actor_names, actor_slots = recovery[name]
                        if name not in actor_names and (room, index) not in actor_slots:
                            bed = next(
                                (
                                    bed
                                    for bed in self.op_data.all_dorms()
                                    if bed.position == (room, index)
                                ),
                                None,
                            )
                            if bed is not None and self.op_data._slot_takable(
                                bed,
                                requester=name,
                                active_groups={self.op_data.operators[name].group},
                                plan=plan,
                            ):
                                continue
                    row[index] = "Current"
            if all(name == "Current" for name in row):
                del plan[room]

    def _waiting_return_can_progress(self, task):
        """只放行与挂起整批目标一致、且不占用其余预约的正常回班。"""
        if task.type != TaskTypes.SHIFT_ON:
            return False
        returning_names = {
            name
            for room, row in task.plan.items()
            if not room.startswith("dorm")
            for index, name in enumerate(row)
            if (op := self.op_data.operators.get(name)) is not None
            and (op.room, op.index) == (room, index)
        }
        original_names, _ = self._waiting_shift_reservations()
        returning_groups = {
            group
            for group, resting in self.op_data.arrangement_group_transitions(
                task.plan,
                group_transitions=getattr(task, "group_shift_transitions", {}),
            ).items()
            if not resting and self.op_data.group_is_resting(group)
        }
        names, slots = self._waiting_shift_reservations(
            returning_groups=returning_groups, returning_names=returning_names
        )
        return bool(original_names - names) and not any(
            name != "Current" and (name in names or (room, index) in slots)
            for room, row in task.plan.items()
            for index, name in enumerate(row)
        )

    def _return_releases_waiting_recovery(self, task, plan, *, now):
        """预演回班腾床后，核对挂起任务能否恢复并使用该床位。"""
        returning_names = _assigned_operator_names(
            {room: row for room, row in plan.items() if not room.startswith("dorm")}
        )
        source_beds = {
            bed.position
            for bed in self.op_data.dorm
            if (op := self.op_data.get_current_operator(*bed.position)) is not None
            and op.name in returning_names
        }
        if not source_beds:
            return False
        admissible = copy.deepcopy(plan)
        self._suppress_retained_arrangements(
            admissible, returning_groups=self._returning_groups_releasing_waits(task)
        )
        if admissible != plan:
            return False
        simulation = copy.copy(self)
        simulation.op_data = self.op_data.project_arrangements([plan], now=now)
        vacancies = {
            slot
            for slot in source_beds
            if simulation.op_data.get_current_operator(*slot) is None
        }
        if not vacancies:
            return False
        simulation.tasks, simulation.waiting_group_shifts = copy.deepcopy(
            (
                [pending for pending in self.tasks if pending is not task],
                self.waiting_group_shifts,
            )
        )
        simulation.task = None
        waiting = {id(pending) for pending in simulation.waiting_group_shifts}
        simulation._resume_waiting_group_shifts()
        return any(
            id(pending) in waiting
            and not getattr(pending, "execution_failure", None)
            and any(
                (room, index) in vacancies and name in simulation.op_data.operators
                for room, row in pending.plan.items()
                if room.startswith("dorm")
                for index, name in enumerate(row)
            )
            for pending in simulation.tasks
        )

    def _keep_measured_shift_beds(
        self, data, step, requested, vacated_beds, protected_slots, reserved_names
    ):
        """核对已有分床结果，只保留仍能满足本次换班的实测座次。"""
        locked_rooms = {
            room for room, _ in protected_slots.union(data.reserved_product_beds)
        }
        # 本轮从别房抽人时，那间房的原名单随之失效。
        for destination, row in step.plan.items():
            for name in row:
                op = data.operators.get(name)
                if op is not None and op.current_room != destination:
                    locked_rooms.add(op.current_room)

        targets = {}
        for room, allocation in list(step.plan.items()):
            if not room.startswith("dorm") or room in locked_rooms:
                continue
            current = data.get_current_room(room, True)
            if not reserved_names.isdisjoint((*current, *allocation)):
                continue
            if (
                room not in requested or step.type == TaskTypes.RE_ORDER
            ) and keep_measured_dorm_swap(data, room, allocation):
                del step.plan[room]
                continue

            fill = step.dorm_fill_plan.get(room)
            if not fill or fill != requested.get(room):
                continue
            if not any(
                (room, i) in vacated_beds and not current[i] and name in data.operators
                for i, name in enumerate(fill)
            ):
                continue
            intended = [
                old if name == "Current" else name for old, name in zip(current, fill)
            ]
            if "" in intended and any(intended[intended.index("") + 1 :]):
                # 进本房确认会把中间空床挤到末尾。
                continue
            target = continuing_roommate(self.op_data, room, intended)
            if not target:
                continue
            allocated = [
                old if name == "Current" else name
                for old, name in zip(current, allocation)
            ]
            if sorted(allocated) != sorted(intended) or any(
                new != planned and slot.agent != "Free"
                for new, planned, slot in zip(intended, allocated, data.plan[room])
            ):
                continue
            chosen = recovery_target(data, room, allocated)
            if chosen and chosen.name == target:
                step.plan[room] = fill.copy()
                targets[room] = (intended, target)
        return targets

    @log_mood_calculation("完整换班")
    @_log_backup_calculation("完整换班")
    def _prepare_shift_cycle(self, task):
        """在副本中收敛换班、副表、后续轮休和补床，成功后一次提交最终安排。"""
        self._resume_waiting_group_shifts(refresh_migrations_only=True)
        preceding = getattr(task, "product_wait_return_task", None)
        if preceding is not None and any(
            pending is preceding for pending in self.tasks
        ):
            raise ProductSwitchDeferred(
                "等待独立回班完成后继续切产物", dependencies=(preceding,)
            )
        if getattr(task, "product_wait_independent_return", False):
            # 已独立推演的回班只执行自身目标，不能再次合并等待切产物的下班。
            return
        if getattr(self, "maintenance_entry_pending", False):
            pending = [
                queued
                for queued in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
                if queued is not task
                and getattr(queued, "maintenance_advance_before_backup", False)
            ]
            if pending:
                raise ProductSwitchDeferred(
                    "等待停服前提前跑单及原班恢复完成后再换班", dependencies=pending
                )
            self.maintenance_entry_pending = False
        if task.plan.keys() & getattr(task, "dorm_roommate_targets", ()):
            # 名单相同仍可能给错单回，原任务需要进房核对。
            return
        if task.retains_execution or (
            getattr(task, "product_shift_locked", False)
            and hasattr(task, "backup_shift_conditions")
        ):
            # 已完成副表推演的整批预约保留最终安排；仅预约槽位的任务仍需准备换班。
            return
        if (self._initial_mood_read_pending()) or getattr(
            task, "backup_shift_active", False
        ):
            return
        projection_now = getattr(self.op_data, "_projection_now", None)
        if projection_now is None and self.op_data.mood_calculation_enabled:
            projection_now = datetime.now()
        waiting_shifts = task.type == TaskTypes.SHIFT_ON and getattr(
            self, "waiting_group_shifts", ()
        )
        agreed_return = self._waiting_return_can_progress(task)
        releases_bed = (
            not agreed_return
            and waiting_shifts
            and self._return_releases_waiting_recovery(
                task, task.plan, now=projection_now
            )
        )
        if agreed_return or releases_bed:
            prepared = copy.copy(task)
            prepared.plan = copy.deepcopy(task.plan)
            self._prepare_shift_backup(prepared, now=projection_now)
            if (
                getattr(
                    prepared, "backup_shift_conditions", self.op_data.plan_condition
                )
                == self.op_data.plan_condition
                and getattr(prepared, "backup_group", self.op_data.backup_group)
                == self.op_data.backup_group
                and (
                    self._waiting_return_can_progress(prepared)
                    or releases_bed
                    and (
                        prepared.plan == task.plan
                        or self._return_releases_waiting_recovery(
                            task, prepared.plan, now=projection_now
                        )
                    )
                )
            ):
                # 先完成这份回班，实际释放床位后再重验挂起的整批换班。
                # 不把其他普通轮休并入前置回班，避免重新占用刚释放的床位。
                task.__dict__.update(prepared.__dict__)
                return
        if getattr(task, "exhaust_support", False):
            # 先确认前置接岗，再由原用尽任务重算下班；普通轮休不能在此抢床。
            self._prepare_shift_backup(task, now=projection_now)
            return
        # 肥鸭、延期切产物和临近关键任务仍由原有调度边界处理。
        probe = SchedulerTask(task_type=TaskTypes.FILL_DORM)
        simplify_dorm_fill(probe, self.tasks, op_data=self.op_data)
        if (
            getattr(probe, "simple_dorm_fill", False)
            or any(
                getattr(t, "backup_shift_active", False)
                for t in self.tasks
                if t is not task
            )
            or any(
                t.type == TaskTypes.FIAMMETTA
                and t.time <= datetime.now()
                or getattr(t, "backup_shift_active", False)
                or getattr(t, "product_shift_locked", False)
                for t in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
                if t is not task
            )
            or getattr(task, "product_shift_locked", False)
        ):
            self._prepare_shift_backup(task, now=projection_now)
            recovery_data = self.op_data
            conditions = getattr(
                task, "backup_shift_conditions", self.op_data.plan_condition
            )
            backup_group = getattr(task, "backup_group", self.op_data.backup_group)
            if (
                conditions != self.op_data.plan_condition
                or backup_group != self.op_data.backup_group
            ):
                recovery_data = self.op_data.project_arrangements(
                    [], now=projection_now
                )
                if error := recovery_data.swap_plan(
                    conditions, refresh=True, backup_group=backup_group
                ):
                    raise ValueError(f"换班恢复分配预演失败：{error}")
            order_changed = (
                dorm_rebalance_signature(self.op_data)[0]
                != dorm_rebalance_signature(recovery_data)[0]
            )
            reserved_names, reserved_slots, _, _ = self._dorm_recovery_reservations(
                [
                    pending
                    for pending in self.tasks
                    if pending is not task
                    and (
                        pending.type != TaskTypes.SHIFT_ON or pending.retains_execution
                    )
                ],
                op_data=recovery_data,
                returning_groups=self._returning_groups_releasing_waits(task),
            )
            task.plan = prioritize_new_dorm_recovery(
                recovery_data,
                task.plan,
                reserved_slots | set(getattr(task, "backup_explicit_slots", ())),
                reserved_names=reserved_names,
                configuration_changed=order_changed,
            )
            task.plan = plan_dorm_isolation(
                recovery_data,
                task.plan,
                reserved_slots | set(getattr(task, "backup_explicit_slots", ())),
                reserved_names=reserved_names,
                reallocating_names=(
                    {bed.name for bed in self.op_data.dorm if bed.name}
                    if order_changed
                    else ()
                ),
            )
            return
        timing = _backup_timing_runtime.current
        if self.op_data.backup_plans:
            timing.start()
        intent = copy.deepcopy(getattr(task, "backup_shift_intent", task.plan))
        explicit_slots = set(getattr(task, "backup_explicit_slots", ()))
        ordinary = {
            TaskTypes.SHIFT_ON,
            TaskTypes.SHIFT_OFF,
            TaskTypes.EXHAUST_OFF,
            TaskTypes.SELF_CORRECTION,
            TaskTypes.RE_ORDER,
            TaskTypes.FILL_DORM,
        }

        def required_departure_names(planned):
            if getattr(planned, "ordinary_coordination", False) or planned.type not in (
                TaskTypes.SHIFT_OFF,
                TaskTypes.EXHAUST_OFF,
            ):
                return set()
            return {
                name
                for room, names in getattr(
                    planned, "backup_shift_intent", planned.plan
                ).items()
                if room.startswith("dorm")
                for name in names
                if (op := self.op_data.operators.get(name)) is not None
                and op.is_high()
                and not op.room.startswith("dorm")
                and not op.workaholic
                and op.is_working()
                and (
                    (mood := dorm_candidate_mood(self.op_data, name)) is None
                    or mood < op.upper_limit
                )
            }

        current_required = required_departure_names(task)
        coalesced = [
            t
            for t in task_view(self.tasks, TaskScope.REPLAN)
            if t is not task
            and t.type in ordinary
            and t.plan
            and not getattr(t, "exhaust_support", False)
            and not getattr(t, "urgent_recovery_request_names", ())
            and t.time <= datetime.now()
            and not getattr(t, "strict_mood_limit", False)
            and not getattr(t, "dorm_recovery_restore", [])
            and not (t.plan.keys() & getattr(t, "dorm_roommate_targets", ()))
        ]
        consumed = set()
        ordinary_requests = list(
            getattr(task, "coordination_request_names", ())
            if getattr(task, "ordinary_coordination", False)
            else ()
        )
        for queued in sorted(coalesced, key=lambda t: t.time):
            if not current_required and required_departure_names(queued):
                continue
            # 未执行的普通补床重新计算，不能作为轮休前必须保留的入住意图。
            if queued.type != TaskTypes.FILL_DORM:
                combined = copy.deepcopy(intent)
                _merge_shift_transition(
                    combined,
                    getattr(queued, "backup_shift_intent", queued.plan),
                    self.op_data,
                )
                explicit = self._plan_for_slots(intent, explicit_slots)
                _merge_shift_transition(
                    explicit,
                    self._plan_for_slots(
                        queued.plan, getattr(queued, "backup_explicit_slots", ())
                    ),
                    self.op_data,
                )
                _merge_shift_transition(combined, explicit, self.op_data)
                combined_explicit = explicit_slots | set(
                    getattr(queued, "backup_explicit_slots", ())
                )
                if not self.op_data.normalize_shared_arrangement(
                    combined,
                    explicit_slots=combined_explicit,
                    excluded_names=self._protected_facility_names(),
                    excluded_replacements=self._protected_facility_names(
                        include_configured=False
                    ),
                ):
                    continue
                intent = combined
                explicit_slots = combined_explicit
                if getattr(queued, "ordinary_coordination", False):
                    ordinary_requests.extend(queued.coordination_request_names)
            consumed.add(id(queued))
        explicit_work = {
            (room, index, name)
            for source in (task, *coalesced)
            if source is task or id(source) in consumed
            for room, row in source.plan.items()
            if not room.startswith("dorm")
            for index, name in enumerate(row)
            if (room, index) in getattr(source, "backup_explicit_slots", ())
            and name not in ("", "Current", "Free")
        }
        required_names = set().union(
            current_required,
            *(
                required_departure_names(planned)
                for planned in coalesced
                if id(planned) in consumed
            ),
        )
        required_recovery = {
            name
            for planned in [task, *coalesced]
            if (planned is task or id(planned) in consumed)
            and planned.type in (TaskTypes.SHIFT_OFF, TaskTypes.EXHAUST_OFF)
            and not getattr(planned, "ordinary_coordination", False)
            for room, names in planned.plan.items()
            if room.startswith("dorm")
            for name in names
            if name in self.op_data.operators
        }
        required_groups = {
            self.op_data.operators[name].group
            for name in required_recovery
            if self.op_data.operators[name].group
        }
        ordinary_requests = [
            name
            for name in ordinary_requests
            if name not in required_recovery
            and self.op_data.operators[name].group not in required_groups
        ]
        simulation = copy.copy(self)
        # 求值模型只读复用；eval 注入的 Python 内建对象不能全部深拷贝。
        simulation.op_data = copy.deepcopy(
            self.op_data, {id(self.op_data.eval_model): self.op_data.eval_model}
        )
        if projection_now is not None:
            simulation.op_data._projection_now = projection_now
            simulation.op_data._projection_deadlines = {}
            for operator in simulation.op_data.operators.values():
                operator._projection_now = projection_now
                operator._projection_deadlines = (
                    simulation.op_data._projection_deadlines
                )
        simulation.op_data.commit_group_shifts(
            getattr(task, "group_shift_transitions", {})
        )
        pending = [t for t in self.tasks if t is not task and id(t) not in consumed]
        pending_exhaust = self._exhaust_task_signatures(tasks=pending)
        step = SchedulerTask(task_type=task.type, task_plan=copy.deepcopy(intent))
        step.backup_explicit_slots = explicit_slots
        step.ordinary_coordination = bool(ordinary_requests)
        step.coordination_request_names = list(dict.fromkeys(ordinary_requests))
        step.dorm_fill_plan = copy.deepcopy(getattr(task, "dorm_fill_plan", {}))
        initial_correction = getattr(task, "initial_staffing", False)
        returning_groups = self._returning_groups_releasing_waits(task)
        returning = set()
        seen = set()
        # Free 是执行时按游戏列表选人的占位符，预演不能把它当作已知干员。
        unresolved = set()
        ordinary_unknown = set()
        # 仅跟踪尚无本房安排的原床。住客调往别房时，这些床随调动腾出。
        untouched_beds = {
            (op.current_room, op.current_index): op.name
            for op in self.op_data.operators.values()
            if op.current_room.startswith("dorm")
        }
        vacated_beds = set()
        roommate_targets = {}
        initial_dorm_order = tuple(self.op_data.config.dorm_order)

        initial_step = True
        for _ in range(64):
            timing.rounds["完整换班"] += 1
            simulation.tasks, simulation.waiting_group_shifts = copy.deepcopy(
                (pending, getattr(self, "waiting_group_shifts", []))
            )
            simulation.task = step
            previous_dorm_layout = dorm_rebalance_signature(simulation.op_data)
            simulation._prepare_shift_backup(step)
            if initial_step:
                intent = copy.deepcopy(getattr(step, "backup_shift_intent", step.plan))
                ordinary_requests = list(step.coordination_request_names)
                initial_step = False
            else:
                ordinary_requests.extend(step.coordination_request_names)
            simulation.op_data.commit_group_shifts(
                {
                    group: False
                    for group in getattr(step, "ordinary_exhaust_blocked_groups", ())
                }
            )
            explicit_slots = set(getattr(step, "backup_explicit_slots", ()))
            conditions = getattr(
                step, "backup_shift_conditions", simulation.op_data.plan_condition
            )
            if error := simulation.op_data.swap_plan(
                conditions,
                refresh=True,
                backup_group=getattr(step, "backup_group", None),
            ):
                raise ValueError(f"完整换班预演失败：{error}")
            if projection_now is not None:
                simulation.op_data._projection_deadlines.clear()
            # 后续轮次和最终补床均从 pending 复制，失效预约不能重新进入演算。
            if simulation._invalidate_changed_exhaust_tasks(
                pending_exhaust, tasks=pending
            ):
                simulation.tasks = copy.deepcopy(pending)
            reserved_names, reserved_slots, waiting_names, waiting_slots = (
                simulation._dorm_recovery_reservations(
                    [
                        pending
                        for pending in simulation.tasks
                        if pending.type != TaskTypes.SHIFT_ON
                        or pending.retains_execution
                    ],
                    returning_groups=returning_groups,
                )
            )
            waiting_names.update(getattr(task, "backup_retention_releases", ()))
            # 本批退出保留的无主岗位住客清为空闲，不由后续普通补床立即吸回。
            waiting_names.update(
                name
                for name in set(self.op_data.config.free_room_exclusions)
                - set(simulation.op_data.config.free_room_exclusions)
                if (op := simulation.op_data.operators.get(name)) is not None
                and not op.room
            )
            reserved_names.update(waiting_names)
            reserved_slots.update(waiting_slots)
            requested = step.plan
            current_layout = dorm_rebalance_signature(simulation.op_data)
            layout_changed = previous_dorm_layout != current_layout
            order_changed = initial_dorm_order != current_layout[0]
            protected_slots = reserved_slots | explicit_slots
            step.plan = prioritize_new_dorm_recovery(
                simulation.op_data,
                requested,
                protected_slots,
                reserved_names=reserved_names,
                configuration_changed=layout_changed,
            )
            step.plan = plan_dorm_isolation(
                simulation.op_data,
                step.plan,
                protected_slots,
                reserved_names=reserved_names,
                reallocating_names=(
                    {bed.name for bed in simulation.op_data.dorm if bed.name}
                    if order_changed
                    else ()
                ),
            )
            if layout_changed or order_changed:
                roommate_targets.clear()
            elif not (simulation.op_data.runtime_conf or config.conf).dorm_isolation:
                roommate_targets.update(
                    self._keep_measured_shift_beds(
                        simulation.op_data,
                        step,
                        requested,
                        vacated_beds,
                        protected_slots,
                        reserved_names,
                    )
                )
            simulation._suppress_train_arrangement(step.plan)
            simulation._suppress_retained_arrangements(
                step.plan, returning_groups=returning_groups
            )
            return_plan = step.plan
            if initial_correction:
                # 初始化纠错只是驻员建议，允许低心情主班在本轮直接下班。
                # 已到期的明确换班及副表岗位仍保留原有回班意图。
                return_plan = self._plan_for_slots(step.plan, explicit_slots)
                for queued in coalesced:
                    if id(queued) in consumed and not getattr(
                        queued, "initial_staffing", False
                    ):
                        _merge_shift_transition(
                            return_plan, queued.plan, simulation.op_data
                        )
                task.initial_staffing_returns = set(
                    getattr(task, "initial_staffing_returns", ())
                ) | _assigned_operator_names(return_plan)
                returning_groups.update(
                    group
                    for group, resting in simulation.op_data.arrangement_group_transitions(
                        return_plan
                    ).items()
                    if not resting
                )
                initial_correction = False
            returning.update(
                name
                for name in _assigned_operator_names(return_plan)
                if name in simulation.op_data.operators
                and not simulation.op_data.operators[name].is_working()
            )
            previous_positions = {
                name: (op.current_room, op.current_index)
                for name, op in simulation.op_data.operators.items()
            }
            returning_groups.update(
                group
                for group, resting in simulation.op_data.arrangement_group_transitions(
                    return_plan
                ).items()
                if not resting and simulation.op_data.group_is_resting(group)
            )
            simulation.op_data._apply_projected_arrangements([step.plan])
            for room, names in step.plan.items():
                for index, name in enumerate(names):
                    if name in previous_positions:
                        simulation._record_dorm_admission(
                            name, room, index, previous_positions[name]
                        )
            for room, names in step.plan.items():
                fill_row = step.dorm_fill_plan.get(room, [])
                for index, name in enumerate(names):
                    if name != "Current":
                        untouched_beds.pop((room, index), None)
                    if name == "Free":
                        unresolved.add((room, index))
                        if index < len(fill_row) and fill_row[index] == "Free":
                            ordinary_unknown.add((room, index))
                        else:
                            ordinary_unknown.discard((room, index))
                    elif name != "Current":
                        unresolved.discard((room, index))
                        ordinary_unknown.discard((room, index))
            vacated_beds = {
                bed
                for bed, name in untouched_beds.items()
                if bed not in explicit_slots
                and (resident := simulation.op_data.operators.get(name)) is not None
                and resident.current_room not in ("", bed[0])
            }
            state = (
                tuple(conditions),
                tuple(sorted(unresolved)),
                tuple(sorted(explicit_slots)),
                tuple(
                    (name, op.current_room, op.current_index)
                    for name, op in simulation.op_data.operators.items()
                ),
            )
            if state in seen:
                raise ValueError("完整换班预演出现循环，保留原任务，暂不执行换人")
            seen.add(state)
            simulation.total_agent = [
                op
                for op in simulation.op_data.operators.values()
                if op.is_high() and not op.room.startswith("dorm")
            ]
            previous_task_count = len(simulation.tasks)
            rest = simulation.resting(
                returning=returning, returning_groups=returning_groups
            )
            rest_requests = [
                name
                for planned in simulation.tasks[previous_task_count:]
                if planned.type == TaskTypes.SHIFT_OFF
                and getattr(planned, "ordinary_coordination", False)
                for name in planned.coordination_request_names
            ]
            _merge_dorm_arrangement(
                rest,
                try_reorder(
                    simulation.op_data,
                    rest,
                    tasks=simulation.tasks,
                    reserved_names=waiting_names,
                    reserved_slots=waiting_slots,
                )
                or {},
            )
            ordinary_fill = {}
            if not rest:
                # 副表可能改变刚选中的替班合法性；缓存纠错也在预演中完成。
                rest = (
                    simulation.agent_get_mood(
                        read_rooms=False,
                        return_plan=True,
                        explicit_slots=explicit_slots,
                    )
                    or {}
                )
                for room, names in rest.items():
                    for index, name in enumerate(names):
                        current = simulation.op_data.get_current_operator(room, index)
                        if current is not None and current.name == name:
                            names[index] = "Current"
                rest = {
                    room: names
                    for room, names in rest.items()
                    if any(name != "Current" for name in names)
                }
            if not rest:
                # 所有可下班组已安排后才补最终空床；补床触发的副表继续参与收敛。
                simulation.tasks, simulation.waiting_group_shifts = copy.deepcopy(
                    (pending, getattr(self, "waiting_group_shifts", []))
                )
                count = len(simulation.tasks)
                try_add_release_dorm(
                    {},
                    None,
                    simulation.op_data,
                    simulation.tasks,
                    empty_only=True,
                    reserved_names=waiting_names,
                    reserved_slots=waiting_slots | explicit_slots,
                    defer_vacancy_allocation=True,
                )
                for fill in simulation.tasks[count:]:
                    _merge_shift_transition(rest, fill.plan, simulation.op_data)
                    _merge_dorm_arrangement(ordinary_fill, fill.plan)
            # 不重复预演无法缓存的游戏选人，留给最终换人时一次读取。
            for room, names in rest.items():
                for index, name in enumerate(names):
                    if name == "Free" and (room, index) in unresolved:
                        names[index] = "Current"
            rest = {
                room: names
                for room, names in rest.items()
                if any(name != "Current" for name in names)
            }
            simulation._suppress_retained_arrangements(
                rest, returning_groups=returning_groups
            )
            if rest:
                step = SchedulerTask(task_type=TaskTypes.SHIFT_OFF, task_plan=rest)
                step.ordinary_coordination = bool(rest_requests)
                step.coordination_request_names = rest_requests
                step.backup_explicit_slots = explicit_slots
                step.dorm_fill_plan = ordinary_fill
                continue
            final = {}
            retention_exits = (
                set(self.op_data.config.free_room_exclusions)
                | set(getattr(task, "backup_retention_releases", ()))
            ) - set(simulation.op_data.config.free_room_exclusions)
            room_sizes = {
                room: len(slots) for room, slots in simulation.op_data.plan.items()
            }
            # 副表可显式安排未配入主表的右侧设施，最终差异仍需保留。
            for room, _ in explicit_slots:
                if room in RIGHT_SIDE_ROOM_CAPACITY:
                    room_sizes.setdefault(
                        room, len(simulation.op_data.get_current_room(room, True))
                    )
            for room, size in room_sizes.items():
                for index in range(size):
                    old = self.op_data.get_current_operator(room, index)
                    new = simulation.op_data.get_current_operator(room, index)
                    old_name = old.name if old else ""
                    new_name = new.name if new else ""
                    # 别房接走住客即已腾床，只有原宿舍自身的床位安排才需要进房。
                    if (
                        (room, index) in vacated_beds
                        and not new_name
                        and old_name not in retention_exits
                    ):
                        continue
                    if old_name != new_name or (room, index) in unresolved:
                        final.setdefault(room, ["Current"] * size)[index] = (
                            new_name or ("" if old_name in retention_exits else "Free")
                        )
            if required_names:
                declared_explicit = simulation._backup_explicit_slots(
                    [False] * len(conditions), [True] * len(conditions)
                )
                effective_explicit = {}
                for room, index, name in explicit_work:
                    if (room, index) not in declared_explicit:
                        effective_explicit.setdefault(
                            room,
                            ["Current"] * len(simulation.op_data.plan.get(room, [])),
                        )[index] = name
                for enabled, backup_plan in zip(
                    conditions, simulation.op_data.backup_plans
                ):
                    if enabled:
                        _merge_shift_transition(
                            effective_explicit,
                            backup_plan.task or {},
                            simulation.op_data,
                        )
                effective_explicit_work = {
                    (room, index, name)
                    for room, row in effective_explicit.items()
                    if not room.startswith("dorm")
                    for index, name in enumerate(row)
                    if name not in ("", "Current", "Free")
                }
                optional = simulation.op_data.standby_candidates(required_names)
                protected = simulation._protected_facility_names()
                for name in required_names:
                    op = simulation.op_data.operators[name]
                    if op.workaholic or name in protected or op.is_resting():
                        continue
                    if not op.current_room:
                        mood = dorm_candidate_mood(simulation.op_data, name)
                        if (
                            name in optional
                            or mood is not None
                            and mood >= op.upper_limit
                        ):
                            continue
                    elif (
                        op.current_room,
                        op.current_index,
                        name,
                    ) in effective_explicit_work:
                        continue
                    else:
                        slots = simulation.op_data.plan.get(op.current_room, [])
                        owner = (
                            simulation.op_data.operators.get(
                                slots[op.current_index].agent
                            )
                            if 0 <= op.current_index < len(slots)
                            else None
                        )
                        if (
                            owner
                            and simulation.op_data.is_same_group_primary_replacement(
                                owner, name
                            )
                        ):
                            continue
                    raise ValueError("原下班目标未完成，保留原任务并等待岗位释放")
            # 回班预演附带的副表任务不能让原普通回班跳过恢复要求。
            if (
                task.type == TaskTypes.SHIFT_ON
                and not getattr(task, "initial_staffing", False)
                and not task.retains_execution
                and not getattr(task, "group_shift_expected", {})
                and not getattr(task, "backup_shift_active", False)
                and not getattr(task, "product_shift_locked", False)
                and not getattr(task, "backup_explicit_slots", ())
                and not getattr(task, "exhaust_support", False)
                and not getattr(task, "dorm_recovery_restore", ())
            ):
                from arknights_mower.utils.group_recovery import (
                    restored_group_recovery_deadline,
                    split_recovery_return,
                )

                effective = self.op_data.project_arrangements([])
                if error := effective.swap_plan(
                    conditions,
                    refresh=True,
                    backup_group=simulation.op_data.backup_group,
                ):
                    raise ValueError(error)
                delayed_groups = set()
                deadline = restored_group_recovery_deadline(
                    self.op_data,
                    effective,
                    returning_groups,
                    now=projection_now,
                    delayed_groups=delayed_groups,
                )
                if deadline is not None:
                    # 附带宿舍重排分别重算，不能把无关组的回班也连成恢复依赖。
                    split = SchedulerTask(
                        task.time,
                        {
                            room: list(row)
                            for room, row in intent.items()
                            if not room.startswith("dorm")
                        },
                        task.type,
                    )
                    independent = []
                    split_recovery_return(
                        self.op_data,
                        split,
                        independent,
                        [
                            name
                            for group in delayed_groups
                            for name in effective.shift_group_members(group)
                        ],
                    )
                    if independent:
                        for sibling in independent:
                            source_times = []
                            for source in (task, *coalesced):
                                if source is not task and id(source) not in consumed:
                                    continue
                                source_intent = getattr(
                                    source, "backup_shift_intent", source.plan
                                )
                                if any(
                                    name != "Current"
                                    and source_intent.get(room, [])[index : index + 1]
                                    == [name]
                                    for room, row in sibling.plan.items()
                                    for index, name in enumerate(row)
                                ):
                                    source_times.append(source.time)
                            sibling.time = min(source_times, default=task.time)
                        trial_solver = copy.copy(self)
                        trial = copy.deepcopy(task)
                        trial.plan = split.plan
                        trial.group_shift_transitions = {}
                        trial.__dict__.pop("backup_shift_intent", None)
                        trial.__dict__.pop("backup_shift_conditions", None)
                        trial.time = max(task.time, deadline)
                        trial_solver.tasks, trial_solver.task = [*pending, trial], trial
                        for sibling in independent:
                            trial_solver.tasks.append(sibling)
                            trial_solver.task = sibling
                            trial_solver._prepare_shift_cycle(sibling)
                        task.__dict__.update(trial.__dict__)
                        resolve_mastery_backup_tasks(trial_solver.tasks, (trial,), task)
                        resolve_mastery_backup_tasks(
                            trial_solver.tasks,
                            [queued for queued in self.tasks if id(queued) in consumed],
                            task,
                        )
                        self.tasks[:] = [
                            task if queued is trial else queued
                            for queued in trial_solver.tasks
                        ]
                        return
                    # 恢复完成前保留原回班意图，不提交预演中的副表安排。
                    task.time = max(task.time, deadline)
                    return
            task.group_shift_transitions = {
                group: resting
                for group, resting in simulation.op_data.group_shift_state.items()
                if self.op_data.group_is_resting(group) != resting
            }
            task.backup_shift_intent = intent
            task.ordinary_coordination = bool(ordinary_requests)
            task.coordination_request_names = list(dict.fromkeys(ordinary_requests))
            task.backup_explicit_slots = explicit_slots
            task.backup_shift_conditions = list(conditions)
            remember_backup_changes(
                task, self.op_data, self.op_data.plan_condition, conditions
            )
            task.backup_group = simulation.op_data.backup_group
            task.plan = final
            for room, (names, target) in roommate_targets.items():
                if (
                    room in final
                    and simulation.op_data.get_current_room(room, True) == names
                ):
                    remember_roommate_target(task, room, names, target)
            self._record_backup_retention(
                task, self.op_data.config.free_room_exclusions, simulation.op_data
            )
            task.dorm_fill_plan = {
                room: [
                    name
                    if name in simulation.op_data.operators
                    and simulation.op_data.operators[name].temporary_dorm_fill
                    or (room, index) in ordinary_unknown
                    else "Current"
                    for index, name in enumerate(names)
                ]
                for room, names in final.items()
                if room.startswith("dorm")
            }
            for pending in self.tasks:
                if id(pending) in consumed:
                    self._capture_shift_refresh_rules(
                        task, getattr(pending, "backup_refresh_rules", {})
                    )
            resolve_mastery_backup_tasks(
                self.tasks,
                [pending for pending in self.tasks if id(pending) in consumed],
                task,
            )
            self.tasks[:] = [t for t in self.tasks if id(t) not in consumed]
            # 满心情兜底入住标记跟随最终名单，不提交预演中的其他状态。
            for room, names in final.items():
                if room.startswith("dorm"):
                    for name in names:
                        if name in self.op_data.operators:
                            self.op_data.operators[
                                name
                            ].dorm_mood_fallback = simulation.op_data.operators[
                                name
                            ].dorm_mood_fallback
            timing.result = "已收敛"
            logger.debug("完整换班收敛：副表 %s，最终安排 %s", conditions, final)
            summary = f"完整换班计划已确定，涉及{len(task.plan)}处设施"
            snapshot = {
                **build_task_presentation(task, self.op_data),
                "header": summary,
            }
            logger.info(
                format_task_log_message(snapshot, summary),
                extra={"log_task": snapshot},
            )
            return
        raise ValueError("完整换班预演未收敛，保留原任务，暂不执行换人")

    @log_mood_calculation("上下班副表")
    @_log_backup_calculation("上下班副表")
    def _prepare_shift_backup(self, task, *, now=None):
        """从原换班意图推演副表及其动作，只改待执行任务，不伪造实际驻员。"""
        if (
            (self._initial_mood_read_pending())
            or task.type
            not in (
                TaskTypes.SHIFT_ON,
                TaskTypes.SHIFT_OFF,
                TaskTypes.EXHAUST_OFF,
                TaskTypes.SELF_CORRECTION,
                TaskTypes.RE_ORDER,
            )
            or not getattr(self.op_data, "backup_plans", [])
            or getattr(task, "backup_shift_active", False)
        ):
            return
        replacements = [
            queued
            for queued in self.tasks
            if getattr(queued, "maintenance_replacement_run", False)
        ]
        blocked_orders = blocked_run_order_ids(self.tasks, self.op_data)
        if replacements and all(
            getattr(queued, "execution_failure", None) or id(queued) in blocked_orders
            for queued in replacements
        ):
            # 跑单等待原班释放或新实测时，先按原表完成纠错，不能提前切入维护主班。
            task.plan = copy.deepcopy(getattr(task, "backup_shift_intent", task.plan))
            task.backup_shift_conditions = list(self.op_data.plan_condition)
            remember_backup_changes(
                task,
                self.op_data,
                self.op_data.plan_condition,
                task.backup_shift_conditions,
            )
            task.backup_group = self.op_data.backup_group
            return
        charging = [
            t
            for t in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            if t.type == TaskTypes.FIAMMETTA
            and t.time
            <= (getattr(self.op_data, "_projection_now", None) or datetime.now())
        ]
        if charging:
            if hasattr(task, "backup_shift_conditions"):
                raise ProductSwitchDeferred(
                    "等待肥鸭任务完成后再执行最终换班", dependencies=charging
                )
            return
        active = [
            t
            for t in self.tasks
            if t is not task and getattr(t, "backup_shift_active", False)
        ]
        if active:
            slots = {
                (room, index)
                for room, row in task.plan.items()
                for index, name in enumerate(row)
                if name != "Current"
            }
            names = {
                name
                for row in task.plan.values()
                for name in row
                if name in self.op_data.operators
            }
            conflicting = [
                pending
                for pending in active
                if any(
                    name != "Current"
                    and (
                        (room, index) in slots
                        or name in names
                        or (op := self.op_data.get_current_operator(room, index))
                        is not None
                        and op.name in names
                    )
                    for room, row in pending.plan.items()
                    for index, name in enumerate(row)
                )
            ]
            if conflicting:
                raise ProductSwitchDeferred(
                    "等待上一轮最终换班释放共享岗位或干员", dependencies=conflicting
                )
            # 未完成的切表继续持有配置；独立换班仍按当前生效排班执行。
            # 真正共享的床位、干员与已开始交接由后续预约检查保护。
            task.plan = copy.deepcopy(getattr(task, "backup_shift_intent", task.plan))
            task.backup_shift_conditions = list(self.op_data.plan_condition)
            remember_backup_changes(
                task,
                self.op_data,
                self.op_data.plan_condition,
                task.backup_shift_conditions,
            )
            task.backup_group = self.op_data.backup_group
            return
        timing = _backup_timing_runtime.current
        timing.start()
        projection_now = now or getattr(self.op_data, "_projection_now", None)
        if projection_now is None and self.op_data.mood_calculation_enabled:
            projection_now = datetime.now()
        intent = copy.deepcopy(getattr(task, "backup_shift_intent", task.plan))
        original = list(self.op_data.plan_condition)
        explicit_slots = set(getattr(task, "backup_explicit_slots", ()))
        ordinary_policy = copy.copy(task)
        ordinary_policy_changed = False
        self._suppress_facility_arrangement(intent)
        seed = self.op_data.project_arrangements([intent], now=projection_now)
        seed.commit_group_shifts(getattr(task, "group_shift_transitions", {}))
        selection = self._evaluate_backup_selection(seed)
        conditions = selection.conditions
        seen = set()
        for _ in range(64):
            timing.rounds["上下班副表"] += 1
            key = (
                tuple(conditions),
                selection.group_id,
                tuple(sorted((room, tuple(names)) for room, names in intent.items())),
                tuple(sorted(explicit_slots)),
            )
            if key in seen:
                raise ValueError("上下班副表推演出现循环，保留原任务，暂不执行换人")
            seen.add(key)
            simulation = copy.copy(self)
            simulation.op_data = seed.project_arrangements([], now=projection_now)
            # 重算产品换班时，自身上轮预演的预约不能锁住本轮宿舍分配。
            simulation.tasks = [queued for queued in self.tasks if queued is not task]
            simulation._refresh_deferred_product_reservations()
            if error := simulation.op_data.swap_plan(
                conditions, refresh=True, backup_group=selection.group_id
            ):
                raise ValueError(f"上下班副表推演失败：{error}")
            if projection_now is not None:
                simulation.op_data._projection_deadlines.clear()
            if self._filter_ordinary_exhaust_departures(
                ordinary_policy, intent, simulation.op_data
            ):
                ordinary_policy_changed = True
                seed = self.op_data.project_arrangements([intent], now=projection_now)
                seed.commit_group_shifts(
                    getattr(ordinary_policy, "group_shift_transitions", {})
                )
                seed.commit_group_shifts(
                    {
                        group: False
                        for group in ordinary_policy.ordinary_exhaust_blocked_groups
                    }
                )
                selection = self._evaluate_backup_selection(seed)
                conditions = selection.conditions
                seen.clear()
                continue
            failure_reasons = []
            transition = simulation._backup_transition_plan(
                self.op_data.plan,
                original,
                conditions,
                copy.deepcopy(seed.all_dorms()),
                dorm_rebalance_signature(seed),
                self.op_data.config.free_room_exclusions,
                failure_reasons=failure_reasons,
            )
            if transition is None:
                if simulation._backup_departure_waiting_names:
                    raise GroupShiftBlocked(
                        recovery_names=simulation._backup_departure_waiting_names
                    )
                raise ProductSwitchDeferred(
                    "副表换班暂缓："
                    + ("；".join(failure_reasons) or "无法完成副表驻员与休息安排")
                    + "；保留原换班安排",
                    rooms=tuple(simulation.op_data.plan),
                )
            entry_slots = {
                (room, index)
                for room, index in self._backup_explicit_slots(original, conditions)
                if index < len(transition.get(room, ()))
                and transition[room][index] != "Current"
            }
            departing_names = {
                owner.name
                for room, index in entry_slots
                if not room.startswith("dorm")
                and index < len(simulation.op_data.plan.get(room, ()))
                and (
                    owner := simulation.op_data.operators.get(
                        simulation.op_data.plan[room][index].agent
                    )
                )
                is not None
                and transition[room][index]
                in simulation.op_data.replacement_candidates(owner)
            }
            entry_slots.update(
                (room, index)
                for room, names in transition.items()
                if room.startswith("dorm")
                for index, name in enumerate(names)
                if name in departing_names
            )
            entry = self._plan_for_slots(transition, entry_slots)
            if entry:
                # 本次显式任务撤销自身触发条件后，仍保留已触发的岗位安排。
                explicit_slots.update(entry_slots)
                _merge_shift_transition(intent, entry, simulation.op_data)
                explicit = self._plan_for_slots(intent, explicit_slots)
                departing = {
                    group
                    for group, resting in simulation.op_data.arrangement_group_transitions(
                        explicit
                    ).items()
                    if resting
                }
                for room, names in intent.items():
                    for index, name in enumerate(names):
                        op = simulation.op_data.operators.get(name)
                        if (
                            op is not None
                            and op.group in departing
                            and (op.room, op.index) == (room, index)
                            and (room, index) not in explicit_slots
                        ):
                            names[index] = "Current"
                seed = self.op_data.project_arrangements([intent], now=projection_now)
                seed.commit_group_shifts(
                    simulation.op_data.arrangement_group_transitions(intent)
                )
            merged = copy.deepcopy(intent)
            _merge_shift_transition(merged, transition, simulation.op_data)
            self._suppress_facility_arrangement(merged)
            # 从真实驻员重新投影，不能把上一轮的中间换人累积到下一轮。
            projected = self.op_data.project_arrangements([], now=projection_now)
            if error := projected.swap_plan(
                conditions, refresh=True, backup_group=selection.group_id
            ):
                raise ValueError(f"上下班副表推演失败：{error}")
            if projection_now is not None:
                projected._projection_deadlines.clear()
            projected._apply_projected_arrangements([merged])
            next_selection = self._evaluate_backup_selection(projected)
            next_conditions = next_selection.conditions
            if (
                next_conditions == conditions
                and next_selection.group_id == selection.group_id
            ):
                timing.result = "已收敛"
                task.backup_group = selection.group_id
                if ordinary_policy_changed:
                    for attr in (
                        "coordination_request_names",
                        "ordinary_exhaust_blocked_groups",
                        "group_shift_transitions",
                    ):
                        setattr(
                            task, attr, copy.deepcopy(getattr(ordinary_policy, attr))
                        )
                task.backup_explicit_slots = explicit_slots
                if (
                    conditions == original
                    and merged == intent
                    and selection.group_id == self.op_data.backup_group
                ):
                    task.plan = intent
                    for attr in ("backup_shift_intent", "backup_shift_conditions"):
                        if hasattr(task, attr):
                            delattr(task, attr)
                    if getattr(task, "product_shift_locked", False):
                        slots = {
                            (room, index)
                            for room, names in task.plan.items()
                            for index, name in enumerate(names)
                            if name != "Current"
                        }
                        self._reserve_deferred_product_shift(task, slots)
                        self._refresh_deferred_product_reservations()
                    return
                task.backup_shift_intent = intent
                task.backup_shift_conditions = conditions
                remember_backup_changes(task, self.op_data, original, conditions)
                task.plan = {
                    room: names
                    for room, names in merged.items()
                    if any(name != "Current" for name in names)
                }
                self._record_backup_retention(
                    task, self.op_data.config.free_room_exclusions, simulation.op_data
                )
                if getattr(task, "product_shift_locked", False):
                    self._reserve_deferred_product_shift(task, set())
                    self._refresh_deferred_product_reservations()
                logger.debug(
                    "上下班副表预演收敛：%s -> %s，最终安排：%s",
                    original,
                    conditions,
                    task.plan,
                )
                summary = f"上下班副表预演已收敛，涉及{len(task.plan)}处设施"
                snapshot = {
                    **build_task_presentation(task, self.op_data),
                    "header": summary,
                }
                logger.info(
                    format_task_log_message(snapshot, summary),
                    extra={"log_task": snapshot},
                )
                return
            conditions = next_conditions
            selection = next_selection
        raise ValueError("上下班副表推演未收敛，保留原任务，暂不执行换人")

    def _activate_shift_backup(self, task):
        """前置操作成功后启用最终排班配置；实际位置仍由逐房读屏更新。"""
        if self._initial_mood_read_pending():
            return
        conditions = getattr(task, "backup_shift_conditions", None)
        if conditions is None or (
            getattr(task, "backup_shift_active", False)
            and self.op_data.plan_condition == conditions
            and self.op_data.backup_group
            == getattr(task, "backup_group", self.op_data.backup_group)
        ):
            return
        if self._advance_orders_before_maintenance(
            conditions, getattr(task, "backup_group", None)
        ):
            raise ProductSwitchDeferred(
                "等待停服前提前跑单及原班恢复完成后再换班",
                dependencies=[
                    queued
                    for queued in task_view(
                        self.tasks, TaskScope.DISPATCH, self.op_data
                    )
                    if queued is not task
                    and getattr(queued, "maintenance_advance_before_backup", False)
                ],
            )
        previous = list(self.op_data.plan_condition)
        previous_group = self.op_data.backup_group
        previous_refresh = {
            name: (op.refresh_drained, op.refresh_order_room)
            for name, op in self.op_data.operators.items()
        }
        previous_exhaust = self._exhaust_task_signatures()
        if error := self.op_data.swap_plan(
            conditions, refresh=True, backup_group=getattr(task, "backup_group", None)
        ):
            self.op_data.swap_plan(previous, refresh=True, backup_group=previous_group)
            raise ValueError(f"上下班最终排班生效失败：{error}")
        self._sync_idle_release_tasks()
        task.backup_shift_active = True
        activated_changes = backup_changes(self.op_data, previous, conditions)
        if activated_changes:
            logger.info(
                format_backup_changes(activated_changes, completed=True),
                extra={"log_backups": activated_changes},
            )
        self._capture_shift_refresh_rules(task, previous_refresh)
        if previous != conditions and self._invalidate_changed_exhaust_tasks(
            previous_exhaust
        ):
            # 重排任务完成后仍需按实读驻员重新计算用尽时间。
            self.tasks.append(SchedulerTask())
        self._sync_run_order_tasks()

    @staticmethod
    def _plan_for_slots(plan, slots):
        return {
            room: [
                name if (room, index) in slots else "Current"
                for index, name in enumerate(names)
            ]
            for room, names in plan.items()
            if any((room, index) in slots for index in range(len(names)))
        }

    def _product_dependent_slots(self, plan, rooms, baseline, projected):
        """用单人变动及撤销单人变动的反事实找出触发副表的槽位。"""
        changed = {
            (room, index)
            for room, names in plan.items()
            for index, name in enumerate(names)
            if name != "Current"
        }
        occupants = {
            (op.current_room, op.current_index): op.name
            for op in self.op_data.operators.values()
        }
        involved = {}
        for room, index in changed:
            name = plan[room][index]
            for operator in (name, occupants.get((room, index))):
                if operator in self.op_data.operators:
                    involved.setdefault(operator, set()).add((room, index))
        held = set()
        for operator, slots in involved.items():
            only, _ = self._products_after_arrangement(
                self._plan_for_slots(plan, slots)
            )
            without, _ = self._products_after_arrangement(
                self._plan_for_slots(plan, changed - slots)
            )
            if any(
                only.get(room) != baseline.get(room)
                or without.get(room) != projected.get(room)
                for room in rooms
            ):
                held.update(slots)
                logger.debug("%s的排班动作影响副表产物", operator)
        return held or changed

    def _reserve_deferred_product_shift(
        self, task, slots, *, deferred=None, targets=None
    ):
        changed = {
            (room, index)
            for room, names in task.plan.items()
            for index, name in enumerate(names)
            if name != "Current"
        }
        if not changed:
            return
        if hasattr(task, "backup_shift_conditions"):
            # 收敛后的上下班是一个整体，不能拆出会让副表条件改变的中间态。
            slots = changed
        if failures := getattr(task, "arrangement_failures", None):
            # 原任务保留正在复核的房间，拆出的其他岗位不继承该房间的提交责任。
            slots = slots | {
                position for position in changed if position[0] in failures
            }
        independent_task = None
        if slots != changed:
            independent = self._plan_for_slots(task.plan, changed - slots)
            independent_task = SchedulerTask(
                task_plan=independent,
                task_type=task.type,
                meta_data=task.meta_data,
            )
            self.tasks.append(independent_task)
            task.plan = self._plan_for_slots(task.plan, slots)
        task.product_shift_locked = True
        task.product_lock_slots = slots
        task.product_lock_names = {
            name
            for room, names in task.plan.items()
            for name in names
            if name in self.op_data.operators
        }
        for room, index in slots:
            if room.startswith("dormitory_"):
                continue
            current = self.op_data.get_current_operator(room, index)
            if current is not None:
                task.product_lock_names.add(current.name)
        if (
            task.plan
            and (deferred is not None or independent_task is not None)
            and not (
                independent_task is None
                and getattr(task, "product_wait_return_task", None) is not None
                and any(
                    pending is task.product_wait_return_task for pending in self.tasks
                )
            )
        ):
            snapshot = build_task_presentation(task, self.op_data)
            descriptions = []
            waits = getattr(deferred, "room_deferrals", ()) or (deferred,)
            blocked = getattr(deferred, "rooms", ())
            for room, target in (
                targets or getattr(task, "pending_product_targets", {})
            ).items():
                if blocked and room not in blocked:
                    continue
                wait = next(
                    (item for item in waits if item is not None and room in item.rooms),
                    deferred,
                )
                definitions = (
                    MANUFACTURE_PRODUCTS
                    if target in MANUFACTURE_PRODUCTS
                    else TRADE_PRODUCTS
                )
                manufacture = target in MANUFACTURE_PRODUCTS
                actual = (
                    getattr(self.op_data, "facility_states", {})
                    .get(room, {})
                    .get("product")
                )
                before = definitions.get(actual)
                after = definitions.get(target)
                previous = (
                    (before.name if manufacture else before.strategy_name)
                    if before
                    else "尚未确认"
                )
                following = (
                    (after.name if manufacture else after.strategy_name)
                    if after
                    else "尚未确认"
                )
                operation = "切换产物" if manufacture else "切换订单类型"
                label = facility_label(room, self.op_data)
                if getattr(wait, "log_reason", None) == "production":
                    descriptions.append(
                        f"{label} 需等待当前产物完成，再{operation} {previous} → {following}"
                    )
                elif getattr(wait, "log_reason", None) == "confirmation":
                    descriptions.append(
                        f"{label} 需等待切换确认时间，再{operation} {previous} → {following}"
                    )
                elif wait is not None:
                    descriptions.append(
                        f"{label} 暂不能{operation} {previous} → {following}（{wait}）"
                    )
            reason = "；".join(descriptions)
            if not reason and deferred is not None:
                reason = str(deferred)
            header = (
                reason + "，" if reason else ""
            ) + f"任务「{snapshot['title']}」暂缓执行："
            snapshot["header"] = header
            logger.info(
                format_task_log_message(snapshot, header).replace("\n", "\n    "),
                extra={"log_task": snapshot},
            )
        if independent_task is not None:
            snapshot = build_task_presentation(independent_task, self.op_data)
            header = f"已生成可先执行的任务「{snapshot['title']}」，执行时间 {independent_task.time}"
            snapshot["header"] = header
            logger.info(
                format_task_log_message(snapshot, header).replace("\n", "\n    "),
                extra={"log_task": snapshot},
            )

    def _deferred_product_locks(self, exclude=None):
        return [
            task
            for task in self.tasks
            if task is not exclude and getattr(task, "product_shift_locked", False)
        ]

    def _refresh_deferred_product_reservations(self):
        locks = self._deferred_product_locks()
        self.op_data.reserved_product_beds = {
            (room, index): names[index]
            for task in locks
            for room, names in task.plan.items()
            if room.startswith("dormitory_")
            for index, name in enumerate(names)
            if name in self.op_data.operators
        }
        self.op_data.reserved_product_replacements = (
            set().union(*(task.product_lock_names for task in locks))
            if locks
            else set()
        )

    def _product_slot_conflicts(self, task):
        conflicts = []
        for lock in self._deferred_product_locks(exclude=task):
            if getattr(lock, "product_wait_return_task", None) is task:
                continue
            recovering = product_wait_resting_replacements(self.op_data, lock)
            slots = {
                (room, index)
                for room, row in task.plan.items()
                for index, name in enumerate(row)
                if name != "Current"
                and (
                    (room, index) in lock.product_lock_slots
                    or name in lock.product_lock_names
                    and not (room.startswith("dorm") and name in recovering)
                )
            }
            if slots:
                conflicts.append((lock, slots))
        return conflicts

    def _defer_conflicting_product_shift_slots(self, task):
        conflicts = self._product_slot_conflicts(task)
        if not conflicts:
            return
        conflicting = set().union(*(slots for _, slots in conflicts))
        changed = {
            (room, index)
            for room, names in task.plan.items()
            for index, name in enumerate(names)
            if name != "Current"
        }
        # 绑组换班保留完整安排和确认责任，不能只执行共享岗位就提交整组状态。
        independent = None
        if (
            changed - conflicting
            and not hasattr(task, "backup_shift_conditions")
            and not getattr(task, "group_shift_transitions", {})
            and not getattr(task, "group_shift_expected", {})
        ):
            if failures := getattr(task, "arrangement_failures", None):
                # 原任务已持有逐房进度，切产物只挂起实际冲突的房间。
                for room in sorted({room for room, _ in conflicting}):
                    if not failures.get(room):
                        self._retain_failed_task(
                            task,
                            "床位或替班已为切产物后的换班预留",
                            [room],
                            dependency=True,
                            arrangement_room=room,
                        )
                        task.execution_failure["product_reservation"] = True
                self._set_arrangement_dispatch(task)
                return
            independent = SchedulerTask(
                time=task.time,
                task_plan=self._plan_for_slots(task.plan, changed - conflicting),
                task_type=task.type,
                meta_data=task.meta_data,
            )
            self.tasks.append(independent)
            task.plan = self._plan_for_slots(task.plan, conflicting)
        dependencies = [lock for lock, _ in conflicts]
        snapshot = build_task_presentation(
            task, self.op_data, predecessors=dependencies
        )
        descriptions, agents = [], []
        for lock, slots in conflicts:
            owner = build_task_presentation(lock, self.op_data)
            agents.extend(
                action["subject"]
                for action in owner["actions"]
                if action["kind"] == "operator"
            )
            for room, names in task.plan.items():
                for index, name in enumerate(names):
                    if (room, index) not in slots:
                        continue
                    if (room, index) in lock.product_lock_slots:
                        position = (
                            f"第{index + 1}张床"
                            if room.startswith("dorm")
                            else f"第{index + 1}位"
                        )
                        label = f"{facility_label(room, self.op_data)} {position}"
                        reserved = lock.plan.get(room, [])
                        resident = reserved[index] if index < len(reserved) else None
                        if resident not in (None, "", "_", "Current", "Free"):
                            description = f"{label}已预留给{resident}"
                            agents.append(resident)
                        else:
                            description = f"{label}已被预留"
                    else:
                        description = f"干员{name}已被预留"
                        agents.append(name)
                    descriptions.append(
                        f"{description}，需等待任务「{owner['title']}」完成"
                    )
        header = (
            "；".join(dict.fromkeys(descriptions))
            + f"，任务「{snapshot['title']}」暂缓执行："
        )
        snapshot["header"] = header
        logger.info(
            format_task_log_message(snapshot, header).replace("\n", "\n    "),
            extra={"log_task": snapshot, "log_agents": list(dict.fromkeys(agents))},
        )
        if independent is not None:
            snapshot = build_task_presentation(independent, self.op_data)
            header = f"已生成可先执行的任务「{snapshot['title']}」，执行时间 {independent.time}"
            snapshot["header"] = header
            logger.info(
                format_task_log_message(snapshot, header).replace("\n", "\n    "),
                extra={"log_task": snapshot},
            )
        raise ProductSwitchDeferred(
            "床位或替班已为切产物后的换班预留", dependencies=dependencies
        )

    def _split_long_product_wait(self, task, error, baseline):
        """实测长等待允许先完成不改变产物的回班，原对象继续持有下班责任。"""
        if (
            task.type != TaskTypes.SHIFT_ON
            or getattr(task, "product_wait_return_task", None) is not None
            or task.retains_execution
            or getattr(task, "backup_shift_active", False)
            or any(
                getattr(task, field, False)
                for field in (
                    "group_shift_expected",
                    "initial_staffing",
                    "exhaust_support",
                    "coordination_admission_plan",
                    "urgent_recovery_request_names",
                    "urgent_recovery_support_names",
                )
            )
        ):
            return
        waits = error.room_deferrals or (error,)
        threshold = datetime.now() + timedelta(minutes=15)
        # 聚合异常给出最近进度时间；整批完成等待按所有已知房间中最晚者判断。
        if (
            any(wait.ready_at is None for wait in waits)
            or max(wait.ready_at for wait in waits) <= threshold
        ):
            return
        transitions = getattr(task, "group_shift_transitions", {})
        returning = {group for group, resting in transitions.items() if not resting}
        departing = {group for group, resting in transitions.items() if resting}
        if not returning or not departing:
            return
        simulation = copy.copy(self)
        simulation.op_data = self.op_data.project_arrangements([])
        simulation.tasks, simulation.waiting_group_shifts = copy.deepcopy(
            (
                [pending for pending in self.tasks if pending is not task],
                getattr(self, "waiting_group_shifts", []),
            )
        )
        simulation._refresh_deferred_product_reservations()
        intent = {}
        for group in returning:
            for name in simulation.op_data.shift_group_members(group):
                operator = simulation.op_data.operators[name]
                if operator.room and not operator.room.startswith("dorm"):
                    intent.setdefault(
                        operator.room,
                        ["Current"] * len(simulation.op_data.plan[operator.room]),
                    )[operator.index] = name
        if not intent:
            return
        early = SchedulerTask(task_type=TaskTypes.SHIFT_ON, task_plan=intent)
        simulation.task = early
        try:
            simulation._prepare_group_shift(early)
            simulation._prepare_shift_backup(early)
            simulation._prepare_group_shift(early)
            if any(getattr(early, "group_shift_transitions", {}).values()):
                return
            conditions = getattr(
                early, "backup_shift_conditions", simulation.op_data.plan_condition
            )
            backup_group = getattr(
                early, "backup_group", simulation.op_data.backup_group
            )
            if simulation.op_data.swap_plan(
                conditions, refresh=True, backup_group=backup_group
            ):
                return
            projected = simulation.op_data.project_arrangements([early.plan])
            projected.commit_group_shifts(early.group_shift_transitions)
            retained_dorm = {}
            for room, names in task.plan.items():
                if not room.startswith("dorm"):
                    continue
                for index, name in enumerate(names):
                    operator = projected.operators.get(name)
                    if operator is not None and (
                        operator.group not in departing
                        and not any(
                            binding["group"] in departing
                            for binding in operator.group_bindings
                        )
                        and not operator.is_working()
                    ):
                        retained_dorm.setdefault(room, ["Current"] * len(names))[
                            index
                        ] = name
            _merge_shift_transition(early.plan, retained_dorm, projected)
            projected = simulation.op_data.project_arrangements([early.plan])
            projected.commit_group_shifts(early.group_shift_transitions)
            simulation.op_data = projected
            reserved_names, reserved_slots, _, _ = (
                simulation._dorm_recovery_reservations(simulation.tasks)
            )
            count = len(simulation.tasks)
            try_add_release_dorm(
                {},
                None,
                projected,
                simulation.tasks,
                empty_only=True,
                reserved_names=reserved_names,
                reserved_slots=reserved_slots,
            )
            for fill in simulation.tasks[count:]:
                _merge_shift_transition(early.plan, fill.plan, projected)
            early.plan = prioritize_new_dorm_recovery(
                projected, early.plan, reserved_slots, reserved_names=reserved_names
            )
            early.plan = plan_dorm_isolation(
                projected, early.plan, reserved_slots, reserved_names=reserved_names
            )
            # 回班和补床也可能触发产物条件；这时两批均继续等待。
            products, _ = self._products_after_arrangement(early.plan)
            if products != baseline:
                return
            after_return = simulation.op_data.project_arrangements([early.plan])
            after_return.commit_group_shifts(early.group_shift_transitions)
            selection = self._evaluate_backup_selection(after_return)
            if selection.conditions != conditions or selection.group_id != backup_group:
                return
            simulation.op_data = after_return
            # 从原最终安排提取下班目标，再按提前回班后的真实位置重建恢复床位。
            slots = set()
            for room, names in task.plan.items():
                for index, name in enumerate(names):
                    if name == "Current":
                        continue
                    owner = (
                        self.op_data.operators.get(name)
                        if room.startswith("dorm")
                        else self.op_data.operators.get(
                            self.op_data.plan[room][index].agent
                        )
                    )
                    if owner is not None and (
                        owner.group in departing
                        or any(
                            binding["group"] in departing
                            for binding in owner.group_bindings
                        )
                    ):
                        slots.add((room, index))
            remaining = SchedulerTask(
                task_type=task.type,
                task_plan=self._plan_for_slots(task.plan, slots),
            )
            remaining.group_shift_transitions = {group: True for group in departing}
            remaining.coordination_request_names = [
                name
                for name in getattr(task, "coordination_request_names", ())
                if (operator := after_return.operators.get(name)) is not None
                and (
                    operator.group in departing
                    or any(
                        binding["group"] in departing
                        for binding in operator.group_bindings
                    )
                )
            ]
            if set(getattr(task, "coordination_request_names", ())) - set(
                remaining.coordination_request_names
            ):
                return
            remaining.ordinary_coordination = bool(remaining.coordination_request_names)
            simulation.task = remaining
            simulation.tasks = [
                pending for pending in simulation.tasks[:count] if pending is not early
            ]
            simulation._prepare_group_shift(remaining)
            simulation._prepare_shift_backup(remaining)
            simulation._prepare_group_shift(remaining)
            if any(
                group not in departing or not resting
                for group, resting in remaining.group_shift_transitions.items()
            ):
                return
            final_products, _ = simulation._products_after_arrangement(remaining.plan)
            original_products, _ = self._products_after_arrangement(task.plan)
            if final_products != original_products:
                return
            final = after_return.project_arrangements([])
            if final.swap_plan(
                getattr(remaining, "backup_shift_conditions", final.plan_condition),
                refresh=True,
                backup_group=getattr(remaining, "backup_group", final.backup_group),
            ):
                return
            final._apply_projected_arrangements([remaining.plan])
            for room, names in task.plan.items():
                for index, name in enumerate(names):
                    if name == "Current":
                        continue
                    if name == "":
                        if final.get_current_operator(room, index) is not None:
                            return
                        continue
                    if name == "Free":
                        if not any(
                            index < len(step.plan.get(room, ()))
                            and step.plan[room][index] != "Current"
                            for step in (early, remaining)
                        ):
                            return
                        continue
                    if room.startswith("dorm"):
                        if not final.operators[name].is_resting():
                            return
                    elif (
                        actual := final.get_current_operator(room, index)
                    ) is None or actual.name != name:
                        return
        except (ProductSwitchDeferred, ValueError):
            # 不能证明前后两批均可执行时保留原批次，不制造新的恢复或重试时间。
            return
        early.product_wait_independent_return = True
        early.execution_retained = True
        early.dorm_fill_plan = {
            room: list(names)
            for room, names in early.plan.items()
            if room.startswith("dorm")
        }
        for field in (
            "backup_shift_intent",
            "backup_shift_conditions",
            "backup_group",
            "backup_explicit_slots",
            "backup_retention_releases",
            "backup_retention_admissions",
            "backup_retention_empty_slots",
            "group_shift_transitions",
            "group_shift_expected",
            "dorm_fill_plan",
            "ordinary_coordination",
            "coordination_request_names",
        ):
            task.__dict__.pop(field, None)
            if hasattr(remaining, field):
                setattr(task, field, copy.deepcopy(getattr(remaining, field)))
        task.plan = remaining.plan
        task.product_wait_return_task = early
        self.tasks.append(early)
        retained_snapshot = build_task_presentation(
            task, after_return, predecessors=(early,)
        )
        retained_snapshot["backups"] = [
            change for change in retained_snapshot["backups"] if change["name"].strip()
        ]
        descriptions = []
        targets = getattr(task, "pending_product_targets", None) or {
            room: target
            for room, target in original_products.items()
            if target != baseline.get(room)
        }
        for room, target in targets.items():
            if error.rooms and room not in error.rooms:
                continue
            room_wait = next((item for item in waits if room in item.rooms), None)
            wait = room_wait or error
            definitions = (
                MANUFACTURE_PRODUCTS
                if target in MANUFACTURE_PRODUCTS
                else TRADE_PRODUCTS
            )
            manufacture = target in MANUFACTURE_PRODUCTS
            actual = self.op_data.facility_states.get(room, {}).get("product")
            before = definitions.get(actual)
            after = definitions.get(target)
            previous = (
                (before.name if manufacture else before.strategy_name)
                if before
                else "尚未确认"
            )
            following = (
                (after.name if manufacture else after.strategy_name)
                if after
                else "尚未确认"
            )
            operation = "切换产物" if manufacture else "切换订单类型"
            transition = f"{facility_label(room, self.op_data)} {operation} {previous} → {following}"
            reason = str(wait)
            if reason.startswith(("无人机不足", "批量切产物无人机不足")):
                transition += "时无人机不足"
            elif getattr(wait, "log_reason", None) == "production":
                transition += "时当前产物尚未完成"
            elif getattr(wait, "log_reason", None) == "confirmation":
                transition += "的确认时间尚未到达"
            else:
                transition += f"暂缓（{reason}）"
            ready_at = (
                room_wait.ready_at
                if room_wait is not None
                else max(item.ready_at for item in waits)
            )
            duration = format_wait_duration(
                math.ceil((ready_at - datetime.now()).total_seconds())
            ).replace(" 分", " 分钟")
            descriptions.append(f"{transition}，预计还需等待 {duration}")
        if not descriptions:
            duration = format_wait_duration(
                math.ceil(
                    (
                        max(item.ready_at for item in waits) - datetime.now()
                    ).total_seconds()
                )
            ).replace(" 分", " 分钟")
            descriptions.append(f"{error}，预计还需等待 {duration}")
        header = (
            "；".join(descriptions)
            + f"，任务「{retained_snapshot['title']}」暂缓执行："
        )
        retained_snapshot["header"] = header
        logger.info(
            format_task_log_message(retained_snapshot, header).replace("\n", "\n    "),
            extra={"log_task": retained_snapshot},
        )
        early_snapshot = build_task_presentation(early, self.op_data)
        early_snapshot["backups"] = [
            change for change in early_snapshot["backups"] if change["name"].strip()
        ]
        header = (
            f"已生成可先执行的任务「{early_snapshot['title']}」，执行时间 {early.time}"
        )
        early_snapshot["header"] = header
        logger.info(
            format_task_log_message(early_snapshot, header).replace("\n", "\n    "),
            extra={"log_task": early_snapshot},
        )

    def _switch_products_before_arrangement(self, task):
        """把将由本次换班触发的切产物作为换班的前置操作。"""
        if not self._product_switching_enabled():
            self._discard_product_switches()
            return
        if not (
            getattr(task, "pending_product_targets", {})
            or getattr(task, "product_shift_locked", False)
        ) and (
            any(
                pending is not task and getattr(pending, "backup_shift_active", False)
                for pending in self.tasks
            )
            or any(
                pending.type == TaskTypes.FIAMMETTA and pending.time <= datetime.now()
                for pending in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            )
        ):
            # 独立换人沿用生效配置，前一轮换班或充能完成后再推演产物。
            return
        if not getattr(self.op_data, "products", None) and not any(
            getattr(plan, "products", None)
            for plan in getattr(self.op_data, "backup_plans", [])
        ):
            return
        baseline = self.op_data.products
        baseline, _ = self._products_after_arrangement({})
        products, projected_plan = self._products_after_arrangement(task.plan)
        queued = [
            pending
            for pending in self.tasks
            if pending.type == TaskTypes.SWITCH_PRODUCT
            and pending.time <= datetime.now()
            and not getattr(pending, "execution_failure", None)
        ]
        queued_rooms = {
            parse_product_task_meta(pending.meta_data)[0] for pending in queued
        }
        targets = {}
        switches = []
        for room, target in products.items():
            if target == baseline.get(room) and room not in queued_rooms:
                continue
            room_plan = projected_plan.get(room) or []
            if not room_plan:
                continue
            facility = room_plan[0].facility
            valid = (facility == "制造站" and target in MANUFACTURE_PRODUCTS) or (
                facility == "贸易站" and target in TRADE_PRODUCTS
            )
            if not valid:
                continue
            actual = self.op_data.facility_states.get(room, {}).get("product")
            if actual == target or (
                actual is None and target == self.op_data.products.get(room)
            ):
                continue
            targets[room] = target
            switches.append(
                SchedulerTask(
                    task_type=TaskTypes.SWITCH_PRODUCT,
                    meta_data=product_task_meta(room, target),
                )
            )
        if switches:
            task.pending_product_targets = targets
            try:
                self.switch_base_products(switches, before_arrangement=True)
            except ProductSwitchDeferred as error:
                self._split_long_product_wait(task, error, baseline)
                slots = self._product_dependent_slots(
                    task.plan, targets, baseline, products
                )
                self._reserve_deferred_product_shift(
                    task, slots, deferred=error, targets=targets
                )
                self._refresh_deferred_product_reservations()
                raise
        unfinished = {
            room: target
            for room, target in targets.items()
            if self.op_data.facility_states.get(room, {}).get("product") != target
        }
        if unfinished:
            raise ProductSwitchFailed(
                f"换班前切换实测未达到目标：{unfinished}", unfinished
            )
        # 只撤销最终目标已实测满足的到期切换；未完成房间仍保留原任务。
        settled = {
            id(pending)
            for pending in queued
            for room, _ in (parse_product_task_meta(pending.meta_data),)
            if room in products
            and self.op_data.facility_states.get(room, {}).get("product")
            == products[room]
        }
        self.tasks[:] = [
            pending for pending in self.tasks if id(pending) not in settled
        ]
        if switches:
            task.product_switched_before_arrangement = True

    def _refresh_orders_after_product_switch(self):
        """产物切换及驻员安排完成后，作废旧订单估计并请求重新读取。"""
        rooms = set(self.op_data.run_order_rooms)
        if not rooms:
            return
        self._invalidate_order_estimates(rooms)
        refreshes = {}
        for room in sorted(rooms):
            refresh = self._queue_order_refresh(room)
            if refresh is not None:
                refreshes[room] = refresh
        if refreshes:
            self._remember_order_read_log_cohort(refreshes)

    def check_fia(self):
        if self._emergency_frozen():
            state = self.emergency_state
            targets = state.get("fia_targets", [])
            if not targets:
                return None, None
            fia = self.op_data.operators.get("菲亚梅塔")
            for room, row in state.get("dorm_layout", {}).items():
                if "菲亚梅塔" in row:
                    index = row.index("菲亚梅塔")
                    if (
                        fia is not None
                        and self.op_data.plan[room][index].agent == "菲亚梅塔"
                        and (fia.current_room, fia.current_index) == (room, index)
                    ):
                        return targets, room
            return None, None
        if "菲亚梅塔" in self.op_data.operators.keys() and self.op_data.operators[
            "菲亚梅塔"
        ].room.startswith("dormitory"):
            return self.op_data.operators[
                "菲亚梅塔"
            ].replacement, self.op_data.operators["菲亚梅塔"].room
        return None, None

    def _run_order_time_region(self):
        """#85：跑单剩余时间的双端坐标（三处调用点曾各自复制，UI 调整只改这里）。"""
        return (
            (int(self.recog.w * 650 / 2496), int(self.recog.h * 660 / 1404)),
            (int(self.recog.w * 815 / 2496), int(self.recog.h * 710 / 1404)),
        )

    @timed_step("order_navigation")
    def _wait_drone_interface(
        self,
        interval=0.2,
        accelerate_template=None,
        page_template=None,
        *,
        retry_after=0,
    ):
        """#85：等待进入订单或制造详情界面。

        ``accelerate_template`` 用于贸易站专属流程；未指定时制造站/贸易站任一
        加速按钮都视为成功。``page_template`` 用于没有加速按钮的空订单页面，
        且仅在已点击页面入口后才接受，避免把设施信息遮罩后的背景误判为成功。
        """
        templates = (
            (accelerate_template,)
            if accelerate_template is not None
            else ("manufacture_accelerate", "bill_accelerate")
        )
        pending = None
        retry_ready = False
        retry_at = 0
        attempts_left = 10
        while attempts_left:
            if self.find("connecting"):
                attempts_left -= 1
                retry_ready = False
                self.sleep()
                continue
            if any(self.find(template) is not None for template in templates):
                return
            close = self.find("arrange_check_in_on")
            action = "close_detail" if close is not None else "open_order"
            if (
                page_template is not None
                and pending == "open_order"
                and self.find(page_template) is not None
            ):
                return
            if pending == action and (remaining := retry_at - monotonic()) > 0:
                retry_ready = True
                self.sleep(min(0.2, remaining))
                continue
            attempts_left -= 1
            if pending == action and not retry_ready:
                # 等上次点击的反馈；旧面板仍在时先换帧，不连续戳同一入口。
                retry_ready = True
                self.sleep(0.2)
                continue
            retry_at = monotonic() + retry_after
            self.tap(
                close
                if close is not None
                else (self.recog.w * 0.05, self.recog.h * 0.95),
                interval=interval,
            )
            pending, retry_ready = action, False
        # 最后一次点击之后也要读到结果，再交回原有房间恢复流程。
        ready = any(self.find(template) is not None for template in templates)
        if page_template is not None and pending == "open_order":
            ready = ready or self.find(page_template) is not None
        if self.find("connecting") or not ready:
            raise RecognizeError("未成功进入订单或制造详情界面")

    def _remember_order_read_log_cohort(self, refreshes):
        """关联本轮实际保留的读取对象；展示状态不写入任务或存储。"""
        cohorts = getattr(self, "_order_read_log_cohorts", {})
        self._order_read_log_cohorts = cohorts
        for key, cohort in tuple(cohorts.items()):
            if any(
                owner is refresh
                for owner in cohort["owners"].values()
                for refresh in refreshes.values()
            ) or not any(
                owner is task
                for owner in cohort["owners"].values()
                for task in self.tasks
            ):
                self._publish_order_read_log(cohort, "failed")
                cohorts.pop(key, None)
        key = uuid4().hex
        cohort = {
            "key": key,
            "owners": dict(list(refreshes.items())[:32]),
            "rooms": [
                {
                    "room": room,
                    "label": facility_label(room, self.op_data),
                    "status": "pending",
                }
                for room in list(refreshes)[:32]
            ],
            "after_switch": True,
            "id": None,
        }
        cohorts[key] = cohort
        while len(cohorts) > 32:
            oldest = next(iter(cohorts))
            self._publish_order_read_log(cohorts[oldest], "failed")
            cohorts.pop(oldest, None)

    def _order_read_log_for_refresh(self, refresh):
        if refresh is not None:
            for cohort in reversed(
                tuple(getattr(self, "_order_read_log_cohorts", {}).values())
            ):
                if cohort["owners"].get(refresh.meta_data) is refresh:
                    if any(
                        item["room"] == refresh.meta_data
                        and item["status"] == "pending"
                        for item in cohort["rooms"]
                    ):
                        return cohort
        return None

    def _reset_order_read_log_attempt(self, cohort):
        cohorts = getattr(self, "_order_read_log_cohorts", {})
        if cohort.get("key") not in cohorts:
            return
        pending = [
            item
            for item in cohort["rooms"]
            if item["status"] == "pending"
            and any(cohort["owners"][item["room"]] is task for task in self.tasks)
        ]
        if not pending:
            cohorts.pop(cohort["key"], None)
            return
        cohort["id"] = None
        cohort["closed"] = False
        cohort["rooms"] = pending
        cohort["owners"] = {
            item["room"]: cohort["owners"][item["room"]] for item in pending
        }

    def _retire_order_read_log_refresh(self, refresh):
        cohort = self._order_read_log_for_refresh(refresh)
        if cohort is not None:
            self._publish_order_read_log(cohort, "failed")
            self._reset_order_read_log_attempt(cohort)

    def _prune_order_read_log_cohorts(self):
        for cohort in tuple(getattr(self, "_order_read_log_cohorts", {}).values()):
            if any(
                item["status"] == "pending"
                and not any(
                    cohort["owners"][item["room"]] is task for task in self.tasks
                )
                for item in cohort["rooms"]
            ):
                self._publish_order_read_log(cohort, "failed")
                self._reset_order_read_log_attempt(cohort)

    def _publish_order_read_log(self, cohort, phase, detail=None):
        if cohort.get("closed", False):
            return
        if cohort["id"] is None:
            if phase != "started":
                cohort["closed"] = True
                return
            cohort["id"] = uuid4().hex
        rooms = copy.deepcopy(cohort["rooms"])
        event = {
            "type": "order-read",
            "id": cohort["id"],
            "phase": phase,
            "anchor": phase == "started",
            "after_switch": cohort["after_switch"],
            "rooms": rooms,
        }
        labels = "、".join(item["label"] for item in rooms)
        if phase == "started":
            prefix = "产物切换和驻员安排已完成，" if cohort["after_switch"] else ""
            message = f"{prefix}正在读取{labels} 的订单倒计时"
        else:
            read = "、".join(
                item["label"] for item in rooms if item["status"] == "read"
            )
            paused = "、".join(
                item["label"] for item in rooms if item["status"] == "paused"
            )
            pending = "、".join(
                item["label"] for item in rooms if item["status"] == "pending"
            )
            parts = []
            if read:
                parts.append(f"已读取{read} 的订单倒计时")
            if paused:
                parts.append(f"{paused} 的订单暂停获取")
            if pending:
                parts.append(
                    f"{pending} 的订单倒计时读取未完成"
                    if phase == "failed"
                    else f"尚待读取{pending} 的订单倒计时"
                )
            message = "；".join(parts)
            if phase == "failed" and detail is not None:
                reason = str(detail).strip() or "操作已中断"
                event["detail"] = reason[:2048]
                message += f"：{reason}"
        logger.info(
            message,
            extra={
                "log_event": event,
                "log_parent": {"type": event["type"], "id": event["id"]},
            },
        )
        if phase in ("completed", "failed"):
            cohort["closed"] = True

    def _resolve_order_read_log(self, cohort, room, status):
        if cohort.get("closed", False):
            return
        for item in cohort["rooms"]:
            if item["room"] == room:
                item["status"] = status
        complete = all(item["status"] != "pending" for item in cohort["rooms"])
        self._publish_order_read_log(cohort, "completed" if complete else "updated")
        if complete:
            getattr(self, "_order_read_log_cohorts", {}).pop(cohort.get("key"), None)

    def get_run_order_time(self, room, *, read_mood=False) -> datetime | None:
        """读取跑单时刻；展示仅从实际订单页开始，不替代任务执行结果。"""
        request = getattr(self, "_order_read_log_request", None)
        cohort = request[1] if request is not None and request[0] == room else None
        if cohort is None:
            cohort = {
                "id": None,
                "after_switch": False,
                "rooms": [
                    {
                        "room": room,
                        "label": facility_label(room, self.op_data),
                        "status": "pending",
                    }
                ],
            }
        previous = getattr(self, "_active_order_read_log", None)
        self._active_order_read_log = cohort
        scope = (
            log_parent_context({"type": "order-read", "id": cohort["id"]})
            if cohort["id"] is not None
            else nullcontext()
        )
        try:
            with scope:
                return self._read_run_order_time(room, read_mood=read_mood)
        except BaseException as error:
            self._publish_order_read_log(cohort, "failed", str(error))
            self._reset_order_read_log_attempt(cohort)
            if isinstance(error, OrderReturnUnresolved):
                refresh = self._queue_order_refresh(room)
                if refresh is not None:
                    self._retain_failed_task(refresh, str(error), [room])
            raise
        finally:
            if previous is None:
                self.__dict__.pop("_active_order_read_log", None)
            else:
                self._active_order_read_log = previous

    def _read_run_order_time(self, room, *, read_mood=False) -> datetime | None:
        """读取跑单时刻；确认订单暂停时，本轮不安排跑单。"""
        finish_mood_calculation()
        # 点击进入该房间
        self.enter_room(room)
        pending_order = {}
        if read_mood:
            mood_data = self._read_room_mood(
                room,
                force_mood=True,
                strict_observation=True,
                pending_order=pending_order,
            )
            if not hasattr(self, "_startup_mood_observations"):
                self._startup_mood_observations = {}
            self._startup_mood_observations[room] = self._room_mood_signature(room)
        # 进入房间详情
        observed_product = None
        try:
            observed_product = self._observe_trade_strategy(room, interval=1)
        finally:
            if pending_order.get("order_pending"):
                pending_order["state_summary"] = (
                    f"订单类型为{observed_product[0]}"
                    if observed_product
                    else "订单类型未确认"
                )
                self._log_room_mood(room, mood_data, observation=pending_order)
        cohort = self._active_order_read_log
        if cohort["id"] is None:
            for item in cohort["rooms"]:
                item["label"] = facility_label(item["room"], self.op_data)
            self._publish_order_read_log(cohort, "started")
        with log_parent_context({"type": "order-read", "id": cohort["id"]}):
            if observed_product:
                logger.info(observed_product[1], extra={"log_room": room})
            # 正常倒计时用数字模板读取，失败后才 OCR 确认订单暂停。
            remaining = self.read_time(
                self._run_order_time_region(),
                None,
                use_digit_reader=True,
            )
            if remaining is None:
                status_scope = (
                    (self.recog.w * 405 // 1920, self.recog.h * 350 // 1080),
                    (self.recog.w * 725 // 1920, self.recog.h * 410 // 1080),
                )
                if "订单暂停获取中" in self._product_ocr_text(status_scope):
                    logger.info(
                        f"房间 {self.translate_room(room)} 订单暂停获取，检查是否缺少进驻干员"
                    )
                    if not read_mood:
                        self.scene_graph_navigation(Scene.INFRA_DETAILS)
                        self._read_room_mood(room, force_mood=True)
                    self.scene_graph_navigation(Scene.INFRA_MAIN)
                    self._resolve_order_read_log(cohort, room, "paused")
                    return None
                # 读取失败不能回退为当前时间，否则会误创建立即执行的跑单任务。
                raise RecognizeError("无法读取贸易站订单倒计时，未确认订单暂停")
            execute_time = self._order_completion_time(remaining)
            if not self.op_data.is_order_collection_room(room):
                execute_time -= timedelta(minutes=config.conf.run_order_delay)
            logger.info("下一次进行插拔的时间为：" + execute_time.strftime("%H:%M:%S"))
            self._return_after_order_countdown(room)
            self._resolve_order_read_log(cohort, room, "read")
            return execute_time

    def _recover_trade_room_return(self, room):
        """在两张新画面确认原贸易站的放大页后，点一次游戏内返回箭头。"""
        profile = self.performance_profile
        deadline = monotonic() + profile.transition_timeout
        self.recog.update()
        previous_detail = False
        tapped = False
        waited = set()
        for _ in range(profile.transition_attempts):
            scene = self.scene()
            if (
                scene in (Scene.INFRA_MAIN, Scene.ORDER_LIST, Scene.INDEX)
                or scene in ORDER_RETURN_LOGIN_SCENES
            ):
                return scene
            if scene in self.waiting_scene and scene != Scene.UNKNOWN:
                if scene in waited or not self.waiting_solver():
                    break
                waited.add(scene)
                previous_detail = False
                continue
            if scene != Scene.INFRA_DETAILS:
                break
            if not tapped:
                arrow = self.find("nav_button")
                detail = (
                    bool(arrow)
                    and not self.find("order_label")
                    and (
                        self.detect_room_type() == "贸易站"
                        and self.detect_room() == room
                    )
                )
                if detail and previous_detail:
                    with input_reconciliation_scope("scene"):
                        self.tap(arrow, x_rate=0.08, interval=profile.poll_interval)
                    tapped = True
                    continue
                previous_detail = detail
            remaining = deadline - monotonic()
            if remaining <= 0:
                break
            self.sleep(min(profile.poll_interval, remaining))
        raise OrderReturnUnresolved("读单后未确认退出原贸易站，保留订单刷新任务")

    def _return_after_order_countdown(self, room=None):
        """读到订单倒计时后逐页返回，每次按键都以新场景确认结果。"""
        profile = self.performance_profile
        previous = self.__dict__.get("_order_return_unresolved")
        if room is None:
            room = self.__dict__.get("_order_return_room")
        attempts = {previous: 2} if previous is not None else {}
        if previous == Scene.ORDER_LIST:
            # 上一轮已等过按键反馈，本轮重新取帧确认订单页后只补一次返回。
            self.recog.update()
            attempts[Scene.ORDER_LIST] = 1
            previous = None
        if previous == Scene.INFRA_DETAILS and room is not None:
            scene = self._recover_trade_room_return(room)
        else:
            scene = self.scene()
        deadline = monotonic() + profile.transition_timeout
        waited = set()
        failure = "读单后未确认返回基建地图，保留订单刷新任务"
        while scene != Scene.INFRA_MAIN:
            if scene in self.waiting_scene and scene != Scene.UNKNOWN:
                if scene in waited or not self.waiting_solver():
                    failure = "读单后返回基建时联网等待超时"
                    break
                waited.add(scene)
                scene = self.scene()
                continue
            if scene in (Scene.UNKNOWN, Scene.UNDEFINED) or scene == previous:
                remaining = deadline - monotonic()
                if remaining > 0:
                    self.sleep(min(profile.poll_interval, remaining))
                    scene = self.scene()
                    continue
                if scene in (Scene.UNKNOWN, Scene.UNDEFINED):
                    break
            if attempts.get(scene, 0) >= 2:
                failure = "读单后返回键未生效，保留订单刷新任务"
                break
            attempts[scene] = attempts.get(scene, 0) + 1
            previous = scene
            deadline = monotonic() + profile.transition_timeout
            if scene in ORDER_RETURN_LOGIN_SCENES:
                self.login()
                scene = self.scene()
                continue
            try:
                with input_reconciliation_scope("scene"):
                    if scene == Scene.INFRA_ARRANGE_CONFIRM:
                        # 订单读取没有提交排班的责任，只能点左侧取消。
                        self.tap(
                            (self.recog.w // 3, self.recog.h - 10),
                            interval=profile.poll_interval,
                        )
                    elif scene in (
                        Scene.ORDER_LIST,
                        Scene.INFRA_DETAILS,
                        Scene.INFRA_ARRANGE_ORDER,
                        Scene.RIIC_OPERATOR_SELECT,
                    ):
                        self.back(interval=profile.poll_interval)
                    elif scene == Scene.INDEX:
                        self.tap_index_element("infrastructure")
                    else:
                        break
            except TouchFailure as exc:
                if exc.reconciliation != "scene" or exc.cleanup_failed:
                    raise

                def resume_navigation():
                    self.device.reconnect()
                    self.recog.update()

                csleep(io_timeout(30))
                wait_for_recovery(
                    resume_navigation, retry_errors=RECOVERABLE_DEVICE_ERRORS
                )
                deadline = monotonic() + profile.transition_timeout
            scene = self.scene()
        if scene != Scene.INFRA_MAIN:
            self._order_return_unresolved = scene
            self._order_return_room = room
            raise OrderReturnUnresolved(failure)
        self.__dict__.pop("_order_return_unresolved", None)
        self.__dict__.pop("_order_return_room", None)

    def scene_graph_navigation(self, scene, *, restart_on_unknown=False):
        # 上层恢复仍须先取消读单后迟到的暂选，才能交回通用场景图。
        if "_order_return_unresolved" in self.__dict__:
            self._return_after_order_countdown()
            if scene == Scene.INFRA_MAIN:
                return
        return super().scene_graph_navigation(
            scene, restart_on_unknown=restart_on_unknown
        )

    def collect_recycling(self):
        """Collect only a visible ready marker in the recycling facility."""
        if getattr(self, "_recycle_unavailable", False) is True:
            return False
        central = self.find("control_central")
        if central is None:
            return False
        room = segment.base(
            self.recog.img,
            central,
            right_side_room_order=config.conf.right_side_room_order,
        )["recycle"]
        (left, top), _, (right, bottom), _ = room
        if left < 0 or top < 0 or right > 1920 or bottom > 1080:
            return False
        # The ready hexagon is cyan and overlaps the facility's upper-right edge.
        size = max(24, round((bottom - top) * 0.65))
        region = self.recog.img[
            max(0, round(top) - size // 4) : round(top) + size,
            round(right) - size : min(1920, round(right) + size // 4),
        ]
        hsv = cv2.cvtColor(region, cv2.COLOR_RGB2HSV)
        ready = cv2.inRange(hsv, (80, 80, 120), (100, 255, 255))
        if cv2.countNonZero(ready) < size * size * 0.08:
            return False
        self._tap_recycling_collection((int(right - size / 3), int(top + size / 3)))
        return True

    def _handle_room_entry_reward(self, room):
        if room != "recycle" or self.scene() != Scene.MATERIEL:
            return False
        if not getattr(self, "_recycling_pending", None):
            self._recycling_pending = {"id": str(uuid4())}
        self._finish_recycling_collection()
        return True

    def _tap_recycling_collection(self, pos):
        if getattr(self, "_recycle_unavailable", False) is True:
            return
        self._recycling_pending = {"id": str(uuid4())}
        self.tap(pos)
        for attempt in range(3):
            if self.scene() == Scene.MATERIEL:
                self._finish_recycling_collection()
                return True
            if attempt < 2:
                self.sleep(0.25)
        self._recycling_pending = None
        return False

    def _read_recycling_operators(self):
        if getattr(self, "_recycle_unavailable", False) is True:
            return None
        self.scene_graph_navigation(Scene.INFRA_MAIN)
        self.enter_room("recycle")
        if self.detect_room() != "recycle":
            return None
        self.turn_on_room_detail("recycle")
        names = []
        tops = (
            (135,) if getattr(self.op_data, "recycle_capacity", 2) == 1 else (135, 344)
        )
        for top in tops:
            if self.find("infra_no_operator", scope=((1288, top), (1869, top + 191))):
                continue
            name = self.read_screen(
                cropimg(self.recog.gray, ((1460, top + 25), (1785, top + 80))),
                type="name",
            )
            if not name or name in names:
                return None
            names.append(name)
        return names

    def _finish_recycling_collection(self):
        from arknights_mower.utils.recycling import (
            read_recycling_materials,
            recycling_notifications_overlap_reward_row,
        )

        event = self._recycling_pending
        if not event.get("recorded"):
            event.setdefault("at", datetime.now().timestamp())
            materials = None
            notification_deadline = None
            notification_waits = 0
            for attempt in range(5):
                observed = read_recycling_materials(self.recog.img)
                # 读不全且提示可能遮住奖励时，等待提示消失；整次确认共用五秒预算。
                while (
                    observed is None
                    and notification_waits < 10
                    and recycling_notifications_overlap_reward_row(self.recog.img)
                ):
                    if notification_deadline is None:
                        notification_deadline = monotonic() + 5
                    remaining = notification_deadline - monotonic()
                    if remaining <= 0:
                        break
                    self.sleep(min(0.5, remaining))
                    notification_waits += 1
                    observed = read_recycling_materials(self.recog.img)
                if observed:
                    materials = observed
                    break
                if attempt < 4:
                    self.sleep(0.3)
            if materials is None:
                self.recog.save_screencap("recycling")
                logger.error("回收站材料未完整识别，记录保留为未知，请查看收取截图")
            save_recycling_collection(event["id"], event["at"], None, materials)
            event["recorded"] = True
        if self.scene() == Scene.MATERIEL:
            self.tap((960, 960))
            if self.scene() == Scene.MATERIEL:
                return
        try:
            names = self._read_recycling_operators()
        except (MowerExit, DeviceRecoveryError, SharedADBError):
            raise
        except Exception as exc:
            logger.warning(f"回收站进驻干员读取失败，保留未知：{exc}")
            names = None
        if names is not None:
            update_recycling_operators(event["id"], names)
        else:
            logger.warning("回收站进驻干员未确认，本次收取记录保留未知")
        from arknights_mower.utils.recycling_report import report_recycling_collection

        report_recycling_collection(event["id"])
        self._recycling_pending = None
        self.scene_graph_navigation(Scene.INFRA_MAIN)

    def todo_list(self) -> None:
        """处理基建 Todo 列表"""
        tapped = False
        collect = {
            "bill": "订单",
            "factory": "制造站产物",
            "trust": "信赖",
            "recycle": "回收站产物",
        }
        if self.last_execution["todo"] is None or self.last_execution[
            "todo"
        ] <= datetime.now() - timedelta(minutes=15):
            for res, name in collect.items():
                if (
                    res == "recycle"
                    and getattr(self, "_recycle_unavailable", False) is True
                ):
                    continue
                if pos := self.find(f"infra_collect_{res}"):
                    logger.info(f"收取{name}")
                    if res == "recycle":
                        if self._tap_recycling_collection(pos):
                            self.last_execution["todo"] = datetime.now()
                            return
                    else:
                        self.tap(pos)
                    tapped = True
            self.last_execution["todo"] = datetime.now()
        if not tapped:
            # 点击右上角的通知图标
            # 可能被产物收取提示挡住，所以直接点位置
            self.tap((1840, 140))
            self.todo_task = True

    def _run_clue_flow(self):
        task = getattr(self, "task", None)
        if getattr(task, "credit_shop_continuation", None) is not None:
            result = self._continue_clue_shop(task)
        else:
            try:
                result = self.clue_new()
            except CreditShopIncomplete:
                self.last_clue = datetime.now()
                raise
            if result is False:
                self._retain_clue_access_record_failure(task)
            else:
                self.last_clue = datetime.now()
        if result is False:
            return False
        self.skip(["collect_notification"])

    def _clue_receipt_observation(self):
        revision = getattr(self.op_data, "room_observations", {}).get("meeting", 0)
        scene = getattr(self.recog, "scene", None)
        frame = getattr(self.recog, "_img", None)
        if frame is None or scene not in CLUE_RECEIPT_SCENES:
            scene = None
        card = None
        if scene == Scene.CLUE_RECEIVE:
            try:
                card = clue_card_number(frame[122:338, 1305:1467])
            except (OSError, cv2.error):
                # 原异常可能正是模板无法读取，保留失败任务时只记未知编号。
                pass
        return {"room": revision, "scene": scene, "card": card}

    @staticmethod
    def _resume_clue_receipt(task, current):
        previous = task.execution_failure["snapshot"]
        if (
            current["room"] > previous["room"]
            or current["scene"] not in (None, previous["scene"])
            or current["card"] not in (None, previous["card"])
        ):
            del task.execution_failure
            del task.clue_receipt_pending
            task.execution_retained = True

    def _retain_clue_receipt_failure(self, task, error):
        task.clue_receipt_pending = True
        self._retain_failed_task(
            task, str(error), ("meeting",), dependency=True, log_group="clue"
        )

    def _retain_clue_access_record_failure(self, task):
        if task is not None and task.type in (TaskTypes.CLUE, TaskTypes.CLUE_PARTY):
            task.__dict__.pop("credit_shop_pending", None)
            task.clue_access_record_pending = True
            self._retain_failed_task(
                task,
                "访问记录关闭未确认",
                ("meeting",),
                dependency=True,
                log_group="clue",
            )

    def _continue_clue_shop(self, task):
        result = self._run_clue_shop(resume=task.credit_shop_continuation)
        if result is False:
            self._retain_clue_access_record_failure(task)
        else:
            task.__dict__.pop("credit_shop_pending", None)
            task.__dict__.pop("credit_shop_continuation", None)
        return result

    def _resume_queued_clue_shop(self):
        task = next(
            (
                task
                for task in getattr(self, "tasks", ())
                if task.type in (TaskTypes.CLUE, TaskTypes.CLUE_PARTY)
                and getattr(task, "credit_shop_continuation", None) is not None
            ),
            None,
        )
        if task is None:
            return False
        if task.time > datetime.now():
            return True
        if pending := getattr(task, "credit_shop_pending", None):
            if self.scene() not in (
                Scene.SHOP_CREDIT,
                Scene.SHOP_CREDIT_CONFIRM,
                Scene.MATERIEL,
            ):
                self.scene_graph_navigation(Scene.SHOP_CREDIT)
            if not CreditShop.can_resume(self.recog, pending):
                return True
            task.__dict__.pop("execution_failure", None)
        elif getattr(task, "execution_failure", None):
            return True
        try:
            result = self._continue_clue_shop(task)
        except CreditShopIncomplete as error:
            self._retain_credit_shop_failure(task, error)
        else:
            if result is not False:
                self.tasks[:] = [queued for queued in self.tasks if queued is not task]
        return True

    def _run_clue_shop(self, *, settlement_checked=None, resume=None):
        on_demand = (
            resume["on_demand"] if resume is not None else self._clue_credit_enabled()
        )
        if on_demand:
            kwargs = {"settlement_checked": settlement_checked}
            if resume is None:
                kwargs["resume_queued"] = self._resume_queued_clue_shop
            else:
                kwargs["resume"] = resume
            return self._run_on_demand_clue_shop(**kwargs)
        conf = config.conf
        if getattr(
            conf,
            "should_run_mower_mall",
            getattr(conf, "maa_mall_enable", True)
            and getattr(conf, "maa_mall_mode", "maa") == "mower",
        ):
            if resume is None and self._resume_queued_clue_shop():
                return
            shop_solver = CreditShop(self.device, self.recog)
            try:
                if resume is None:
                    shop_solver.run()
                else:
                    shop_solver.run(resume=resume.get("reward"))
            except CreditShopIncomplete as e:
                e.continuation = {"on_demand": False, "reward": e.pending_reward}
                raise
            self.scene_graph_navigation(Scene.INFRA_MAIN)

    def _clue_receive_credit_capped(self):
        """确认接收页底部显示今日接受信用已达上限。"""
        if self.scene() != Scene.CLUE_RECEIVE:
            return False
        if rapidocr.engine is None:
            rapidocr.initialize_ocr()
        result = rapidocr.engine(
            cropimg(self.recog.img, ((1275, 900), (1920, 975))),
            use_det=True,
            use_cls=False,
            use_rec=True,
        )[0]
        return any(
            score >= 0.9 and "".join(text.split()) == "今日接受信用已达上限"
            for _, text, score in result or []
        )

    def clue_new(self):
        if getattr(self, "_clue_access_record_exhausted", False):
            self.recog.update()
            if not self._clue_access_record_cleared():
                return False
            self._clue_access_record_exhausted = False
        receiving_friend_clue = False
        try:
            settlement_checked = None
            logger.info("基建：线索", extra={"log_group": "clue"})
            self.scene_graph_navigation(Scene.INFRA_MAIN)
            if (
                getattr(self, "_clue_access_record_exhausted", False)
                and not self._clue_access_record_cleared()
            ):
                return False
            self.enter_room("meeting", log_group="clue")

            clue_size = (162, 216)
            clue_top_left = {
                "daily": (1118, 334),
                "receive": (1305, 122),
                "give_away": (30, 208),
                # 摆放线索界面，线索框的左上角
                1: (72, 228),
                2: (374, 334),
                3: (679, 198),
                4: (1003, 265),
                5: (495, 660),
                6: (805, 573),
                7: (154, 608),
            }
            dot_offset = (168, -8)
            main_offset = (425, 0)
            main_time_offset = (443, 257)

            def va(a, b):
                return a[0] + b[0], a[1] + b[1]

            def tl2p(top_left):
                return top_left, va(top_left, clue_size)

            def is_orange(dot):
                orange_dot = (255, 104, 1)
                return all([abs(dot[i] - orange_dot[i]) < 3 for i in range(3)])

            clue_scope = {}
            for index, top_left in clue_top_left.items():
                clue_scope[index] = tl2p(top_left)
            clue_dots = {}
            main_dots = {}
            main_time = {}
            main_scope = {}
            for i in range(1, 8):
                clue_dots[i] = va(clue_top_left[i], dot_offset)
                main_dots[i] = va(clue_dots[i], main_offset)
                main_time[i] = va(clue_top_left[i], main_time_offset)
                main_scope[i] = tl2p(va(clue_top_left[i], main_offset))

            class ClueTaskManager:
                def __init__(self):
                    # 操作顺序：信息板信用、领取每日线索、接收好友线索、摆线索、送线索、更新线索交流结束时间
                    self.task_list = [
                        "message_board",
                        "daily",
                        "receive",
                        "place",
                        "give_away",
                        "party_time",
                    ]
                    self.task = self.task_list[0]

                def complete(self, task):
                    task = task or self.task
                    if task in self.task_list:
                        self.task_list.remove(task)
                    self.task = self.task_list[0] if self.task_list else None

            tm_thres = 0.6

            def clue_cls(scope):
                scope_dict = clue_scope if isinstance(scope, str) else main_scope
                img = cropimg(self.recog.img, scope_dict[scope])
                for i in range(1, 8):
                    res = loadres(f"clue/{i}")
                    result = cv2.matchTemplate(img, res, cv2.TM_CCOEFF_NORMED)
                    min_val, max_val, min_loc, max_loc = cv2.minMaxLoc(result)
                    if max_val > tm_thres:
                        return i
                return None

            exit_pos = (1239, 144)

            ctm = ClueTaskManager()

            clue_status = {}
            placed_clues = frozenset()

            def place_index():
                for cl, st in clue_status.items():
                    if st in ["available", "self", "available_self_only"]:
                        return cl, st
                return None, None

            def detect_unlock():
                unlock_pos = self.find("clue/button_unlock")
                if unlock_pos is None:
                    return None
                color = self.get_color(self.get_pos(unlock_pos))
                if all(color > [252] * 3):
                    return unlock_pos
                return None

            while ctm.task:
                receiving_friend_clue = False
                scene = self.scene()

                if scene == Scene.INFRA_DETAILS:
                    logger.debug("INFRA_DETAILS", extra={"log_group": "clue"})
                    if ctm.task == "message_board":
                        if not config.conf.clue_message_board_enable:
                            self._prepare_clue_room()
                            ctm.complete("message_board")
                            continue
                        if self._clue_credit_enabled():
                            if get_server_weekday() == 6:
                                logger.info(
                                    "上周信息板结算将在周一 04:00 过期，准备打开信息板领取，本次不领取本周信用",
                                    extra={"log_group": "clue"},
                                )
                                settlement_checked = self._collect_clue_message_board(
                                    collect_current=False
                                )
                                if (
                                    getattr(
                                        self, "_clue_access_record_exhausted", False
                                    )
                                    and not self._clue_access_record_cleared()
                                ):
                                    return False
                                if not settlement_checked:
                                    self.scene_graph_navigation(Scene.INFRA_MAIN)
                                    if (
                                        getattr(
                                            self, "_clue_access_record_exhausted", False
                                        )
                                        and not self._clue_access_record_cleared()
                                    ):
                                        return False
                                    self.enter_room("meeting", log_group="clue")
                            else:
                                self._prepare_clue_room()
                            ctm.complete("message_board")
                            continue
                        # 普通领取与按需领取共用打开流程，领取规则保持原样。
                        bottom_left = (680, 1000)
                        logger.info(
                            "信息板按需领取未生效，按常规流程打开信息板领取可用信用",
                            extra={"log_group": "clue"},
                        )
                        if self._open_clue_message_board():
                            if collect := self.find("clue/message_board_collect"):
                                logger.info(
                                    "领取信息板信用", extra={"log_group": "clue"}
                                )
                                self.tap(collect)
                                for _ in range(6):
                                    self.sleep(0.5)
                                    self.recog.update()
                                    if not self.find("clue/message_board_collect"):
                                        # 领取后弹「领取物资」确认页，点任意位置关掉
                                        self.tap(bottom_left)
                                        break

                            self.back()
                            # 等淡出结束、确实回到房间详情页再往下走，否则后续的
                            # tap((330, 1000)) 会打在还在淡出的信息板上
                            for _ in range(4):
                                self.recog.update()
                                if self.scene() == Scene.INFRA_DETAILS:
                                    break
                                self.sleep(0.5)
                        if (
                            getattr(self, "_clue_access_record_exhausted", False)
                            and not self._clue_access_record_cleared()
                        ):
                            return False
                        ctm.complete("message_board")
                    elif ctm.task == "party_time":
                        self.wait_product_complete(log_group="clue")
                        if pos := self.find("clue/check_party"):
                            logger.debug("tap", extra={"log_group": "clue"})
                            self.tap(pos)
                        party_time = self.read_party_time()
                        if party_time is not None and party_time > datetime.now():
                            self.set_detected_party_time(party_time)
                            logger.info(
                                f"线索交流结束时间：{self.party_time}",
                                extra={"log_group": "clue"},
                            )
                            if not find_next_task(
                                self.tasks,
                                task_type=TaskTypes.CLUE_PARTY,
                                scope=TaskScope.PENDING,
                            ):
                                self.tasks.append(
                                    SchedulerTask(
                                        time=self._clue_flow_resume_time(
                                            self.party_time
                                        )
                                        or self.party_time - timedelta(milliseconds=1),
                                        task_type=TaskTypes.CLUE_PARTY,
                                    )
                                )
                        else:
                            self.set_detected_party_time(None)
                            logger.info(
                                "线索交流未开启或已结束", extra={"log_group": "clue"}
                            )
                        # party_time 是副表表达式可引用的状态。界面确认状态后立即
                        # 重算，不能等下一轮调度，否则跃跃等会客室副表不会及时触发。
                        self.backup_plan_solver()
                        ctm.complete("party_time")
                    else:
                        # 点击左下角，关闭进驻信息，进入线索界面
                        self.tap((330, 1000))

                elif scene == Scene.CLUE_ACCESS_RECORD:
                    if not self._wait_clue_message_board():
                        self._clue_access_record_exhausted = True
                        return False

                elif scene == Scene.CLUE_MESSAGE_BOARD:
                    # 停在信息板页面上：退回房间详情，后面的任务都在那里继续。
                    # 兜底用——message_board 分支正常会自己退出来，这里接住
                    # 淡出中途被识别成信息板、或者上一次没退干净的情况
                    logger.debug("CLUE_MESSAGE_BOARD", extra={"log_group": "clue"})
                    self.back()

                elif scene == Scene.INFRA_CONFIDENTIAL:
                    logger.debug("INFRA_CONFIDENTIAL", extra={"log_group": "clue"})
                    if ctm.task == "message_board":
                        # 进房后可能已在线索板，先返回房间处理信息板，再继续领取和摆放。
                        self.back()
                    elif ctm.task == "daily":
                        # 检查是否领过线索
                        daily_scope = ((1815, 200), (1895, 250))
                        if self.find("clue/badge_new", scope=daily_scope):
                            self.tap((1800, 270))
                        else:
                            ctm.complete("daily")
                    elif ctm.task == "receive":
                        receive_scope = ((1815, 360), (1895, 410))
                        if self.find("clue/badge_new", scope=receive_scope):
                            self.ctap((1800, 430))
                        else:
                            ctm.complete("receive")
                    elif ctm.task == "place":
                        if fast_place := self.find("clue/fast_place"):
                            logger.info("快速摆放线索", extra={"log_group": "clue"})
                            self.tap(fast_place, interval=2)
                            if unlock_pos := detect_unlock():
                                self.tap(unlock_pos)
                        ctm.complete("place")
                    elif ctm.task == "give_away":
                        observed_placed = self._read_placed_clue_numbers()
                        # 取帧时可能已进入赠送页，不能用非线索板的空结果覆盖已确认编号。
                        if observed_placed is None:
                            logger.debug(
                                "读取板上编号时页面已切换，保留上次结果：%s",
                                sorted(placed_clues),
                                extra={"log_group": "clue"},
                            )
                            continue
                        placed_clues = observed_placed
                        logger.debug(
                            "线索板已摆放编号：%s",
                            sorted(placed_clues),
                            extra={"log_group": "clue"},
                        )
                        self.ctap((1799, 578))
                    elif ctm.task == "party_time":
                        self.back()

                elif scene == Scene.CLUE_DAILY:
                    logger.debug("CLUE_DAILY", extra={"log_group": "clue"})
                    if not self.find(
                        "clue/icon_notification", scope=((1400, 0), (1920, 400))
                    ) and (clue := clue_cls("daily")):
                        logger.info(
                            f"领取今日线索（{clue}号）", extra={"log_group": "clue"}
                        )
                        self.tap_element("clue/button_get")
                        ctm.complete("daily")
                    else:
                        # 今日线索已领取，点X退出
                        self.tap((1484, 152))

                elif scene == Scene.CLUE_RECEIVE:
                    logger.debug("CLUE_RECEIVE", extra={"log_group": "clue"})
                    if ctm.task != "receive":
                        self.ctap(exit_pos)
                        continue
                    receiving_friend_clue = True
                    self.wait_product_complete(log_group="clue")
                    if self.scene() != Scene.CLUE_RECEIVE:
                        continue
                    if clue := clue_cls("receive"):
                        # 接收页的板位左移，须确认七张真实卡片，空槽数字不算已填满。
                        board_full = all(
                            clue_card_number(
                                cropimg(
                                    self.recog.img,
                                    (
                                        va(clue_top_left[number], (-16, -16)),
                                        va(clue_top_left[number], (178, 232)),
                                    ),
                                )
                            )
                            == number
                            for number in range(1, 8)
                        )
                        if board_full and self._clue_receive_credit_capped():
                            logger.info(
                                "线索板已填满，今日接受信用已达上限，暂不领取剩余好友线索",
                                extra={"log_group": "clue"},
                            )
                            ctm.complete("receive")
                            self.tap(exit_pos)
                            continue
                        name_scope = ((1580, 220), (1880, 255))
                        name_img = cropimg(self.recog.gray, name_scope)
                        name_img = cv2.copyMakeBorder(
                            name_img, 48, 48, 48, 48, cv2.BORDER_REPLICATE
                        )
                        sender_rows = rapidocr.engine(
                            name_img,
                            use_det=True,
                            use_cls=False,
                            use_rec=True,
                        )[0]
                        name = (sender_rows[0][1] or "").strip() if sender_rows else ""
                        logger.info(
                            f"接收{name or '好友'}的{clue}号线索",
                            extra={"log_group": "clue"},
                        )
                        self.tap(name_scope)
                    else:
                        ctm.complete("receive")
                        self.tap(exit_pos)

                elif scene == Scene.CLUE_PLACE:
                    logger.debug("CLUE_PLACE", extra={"log_group": "clue"})
                    cl, st = place_index()
                    if cl is None:
                        if unlock_pos := detect_unlock():
                            self.tap(unlock_pos)
                        else:
                            ctm.complete("place")
                            self.tap(exit_pos)
                        continue
                    if self.get_color((1328 + 77 * cl, 114))[0] < 150:
                        # 右上角 1-7
                        self.tap(clue_scope[cl])
                        continue
                    receive = st in ["available", "self"]
                    filter_receive = (1900, 45)
                    filter_self = (1610, 70)
                    filter_pos = filter_receive if receive else filter_self
                    if not all(self.get_color(filter_pos) > [252] * 3):
                        self.tap(filter_pos)
                        continue
                    clue_pos = ((1305, 208), (1305, 503), (1305, 797))
                    clue_list = []
                    for cp in clue_pos:
                        clue_img = cropimg(self.recog.img, tl2p(cp))
                        res = loadres(f"clue/{cl}")
                        result = cv2.matchTemplate(clue_img, res, cv2.TM_CCOEFF_NORMED)
                        min_val, max_val, min_loc, max_loc = cv2.minMaxLoc(result)
                        if max_val > tm_thres:
                            name_scope = (va(cp, (274, 99)), va(cp, (580, 134)))
                            name_img = cropimg(self.recog.gray, name_scope)
                            name_img = cv2.copyMakeBorder(
                                name_img, 48, 48, 48, 48, cv2.BORDER_REPLICATE
                            )
                            name = rapidocr.engine(
                                name_img,
                                use_det=True,
                                use_cls=False,
                                use_rec=True,
                            )[0][0][1]
                            if name:
                                name = name.strip()
                            time_scope = (va(cp, (45, 222)), va(cp, (168, 255)))
                            time_hsv = cropimg(self.recog.img, time_scope)
                            time_hsv = cv2.cvtColor(time_hsv, cv2.COLOR_RGB2HSV)
                            if 165 < time_hsv[0][0][0] < 175:
                                time_img = thres2(
                                    cropimg(self.recog.gray, time_scope), 180
                                )
                                time_img = cv2.copyMakeBorder(
                                    time_img, 48, 48, 48, 48, cv2.BORDER_REPLICATE
                                )
                                time = rapidocr.engine(
                                    time_img,
                                    use_det=True,
                                    use_cls=False,
                                    use_rec=True,
                                )[0][0][1]
                                if time:
                                    time = time.strip()
                            else:
                                time = None
                            clue_list.append(
                                {"name": name, "time": time, "scope": tl2p(cp)}
                            )
                        else:
                            break
                    if clue_list:
                        list_name = "接收库" if receive else "自有库"
                        logger.debug(
                            f"{cl}号线索{list_name}：{clue_list}",
                            extra={"log_group": "clue"},
                        )
                        selected = None
                        for c in clue_list:
                            if c["time"]:
                                selected = c
                                break
                        selected = selected or clue_list[0]
                        remaining_days = (
                            (selected["time"] or "").removeprefix("剩余").strip()
                        )
                        logger.info(
                            f"准备从{list_name}选取{cl}号线索，来源："
                            f"{selected['name'] or '未识别'}"
                            + (
                                f"，剩余天数：{remaining_days}"
                                if remaining_days
                                else ""
                            ),
                            extra={"log_group": "clue"},
                        )
                        self.tap(selected["scope"])
                        if clue_status[cl] == "available":
                            clue_status[cl] = "friend"
                        elif clue_status[cl] == "available_self_only":
                            clue_status[cl] = "self_only"
                        elif clue_status[cl] == "self":
                            clue_status[cl] = "friend"
                        else:
                            clue_status[cl] = None
                    else:
                        if clue_status[cl] == "available":
                            clue_status[cl] = "available_self_only"
                        elif clue_status[cl] == "available_self_only":
                            clue_status[cl] = None
                        elif clue_status[cl] == "self":
                            clue_status[cl] = "self_only"
                        else:
                            clue_status[cl] = None

                elif scene == Scene.CLUE_GIVE_AWAY:
                    if placed_clues:
                        self.wait_product_complete(log_group="clue")
                        self.recog.update()
                        capacity = self._read_clue_gift_capacity()
                        if capacity is not None:
                            self.clue_count = capacity[0]
                    give_away_true = self.leifeng_mode or (
                        not self.leifeng_mode
                        and self.clue_count > self.clue_count_limit
                    )
                    if give_away_true and (
                        fast_giveaway := self.find("clue/fast_giveaway")
                    ):
                        logger.info("快速送出线索", extra={"log_group": "clue"})
                        self.tap(fast_giveaway)
                    self._give_one_placed_clue(placed_clues)
                    ctm.complete("give_away")
                    self.tap((1868, 54))

                elif scene == Scene.CLUE_SUMMARY:
                    logger.debug("CLUE_SUMMARY", extra={"log_group": "clue"})
                    self.back()
                elif scene == Scene.INFRA_ARRANGE_ORDER:
                    self.back()
                elif scene in self.waiting_scene:
                    logger.debug("waiting_scene", extra={"log_group": "clue"})
                    self.waiting_solver()

                else:
                    self.scene_graph_navigation(Scene.INFRA_MAIN)
                    if (
                        getattr(self, "_clue_access_record_exhausted", False)
                        and not self._clue_access_record_cleared()
                    ):
                        return False
                    self.enter_room("meeting", log_group="clue")
            if self._clue_credit_enabled():
                shop_result = self._run_clue_shop(settlement_checked=settlement_checked)
            else:
                shop_result = self._run_clue_shop()
            if shop_result is False:
                return False
        except CreditShopIncomplete:
            raise
        except (MowerExit, DeviceRecoveryError, SharedADBError):
            raise
        except Exception as e:
            save_exception(e)
            logger.exception(e, extra={"log_group": "clue"})
            if receiving_friend_clue:
                raise FriendClueReceiptIncomplete(f"接收好友线索中断：{e}") from e
            return

    def adjust_order_time(self, accelerate, room, *, order_tasks=None):
        order_tasks = self.tasks if order_tasks is None else order_tasks
        action_required_task = scheduling(
            order_tasks, op_data=getattr(self, "op_data", None)
        )
        label = facility_label(room, self.op_data)
        extra = {"log_room": room}
        reserve = 20
        readbacks = 0
        latest_task = None
        try:
            while (
                action_required_task is not None
                and self.get_run_order_adjust_room(action_required_task) == room
            ):
                drone_count = self.digit_reader.get_drone(self.recog.gray)
                logger.debug("%s 当前无人机数量为 %s", room, drone_count)
                if drone_count <= reserve:
                    logger.error(
                        "%s：当前有 %s 架无人机，需保留 %s 架，停止加速",
                        label,
                        drone_count,
                        reserve,
                        extra=extra,
                    )
                    return False
                if readbacks == 0:
                    logger.info(
                        "%s：跑单时间过于接近，开始使用无人机加速", label, extra=extra
                    )
                self.tap(accelerate)
                if self.scene() in self.waiting_scene and not self.waiting_solver():
                    return None
                self.tap((self.recog.w * 1320 // 1920, self.recog.h * 502 // 1080))
                if self.scene() in self.waiting_scene and not self.waiting_solver():
                    return None
                self.tap((self.recog.w * 3 // 4, self.recog.h * 4 // 5))
                if self.scene() in self.waiting_scene and not self.waiting_solver():
                    return None

                self._wait_drone_interface(
                    interval=1, accelerate_template="bill_accelerate"
                )

                order_time = self.double_read_time(
                    (
                        (self.recog.w * 650 // 2496, self.recog.h * 660 // 1404),
                        (self.recog.w * 815 // 2496, self.recog.h * 710 // 1404),
                    ),
                    use_digit_reader=True,
                )
                task_time = order_time - timedelta(minutes=config.conf.run_order_delay)
                task = find_next_task(
                    order_tasks,
                    task_type=TaskTypes.RUN_ORDER,
                    meta_data=room,
                    op_data=self.op_data,
                )
                if task is None:
                    break
                # 实读是新的订单截止依据，即使时间数值相同也不能复用旧预览。
                task.__dict__.pop("run_order_network_timing", None)
                task.time = task_time
                latest_task = task
                readbacks += 1
                logger.debug("%s 加速后读回的跑单时间为 %s", room, task_time)
                action_required_task = scheduling(
                    order_tasks, op_data=getattr(self, "op_data", None)
                )
        finally:
            if latest_task is not None:
                logger.info(
                    "%s：无人机加速后已重读订单 %d 次，最新跑单开始时间为 %s",
                    label,
                    readbacks,
                    latest_task.time.strftime("%H:%M:%S"),
                    extra=extra,
                )
        return None

    def _tap_drone_accelerate(
        self,
        accelerate_res: str,
        all_in_res: str,
        max_retry: int = 3,
        interval: float = 1,
    ) -> Optional[tp.Scope]:
        """点击无人机加速按钮并确认加速面板打开，有界重试。

        首次点击可能因界面未响应而未打开面板，此时仍停留在详情页；若不确认
        all_in 出现就继续操作，会在详情页上误触。每次重试前重新识别加速按钮，
        确认仍处于可点击的详情页后再点击。持续失败时抛出异常，让上层保留任务
        并按既有策略退避，而不是把未执行的跑单当成已完成。
        """
        accelerate = self.find(accelerate_res)
        for _ in range(max_retry):
            if accelerate is None:
                break
            self.tap(accelerate, interval=interval)
            all_in = self.find(all_in_res)
            if all_in is not None:
                return all_in
            logger.debug(f"无人机加速面板未出现，重新识别 {accelerate_res} 后重试")
            accelerate = self.find(accelerate_res)
            if accelerate is None:
                # 加速按钮消失通常意味着面板已打开：等一帧再确认 all_in，避免误判
                self.sleep(0.5)
                all_in = self.find(all_in_res)
                if all_in is not None:
                    return all_in
                break
        raise RecognizeError(f"无人机加速面板未出现：未识别到 {all_in_res}")

    def _tap_product_point(self, point, interval=0.5):
        x, y = point
        self.tap(
            (self.recog.w * x // 1920, self.recog.h * y // 1080),
            interval=interval,
        )

    def _wait_product_resource(self, resource, *, present=True, retries=8):
        for _ in range(retries):
            found = self.find(resource)
            if bool(found) == present:
                return found
            self.sleep(0.5)
            self.recog.update()
        state = "出现" if present else "消失"
        raise RecognizeError(f"等待 {resource} {state}超时")

    def _product_ocr_text(self, scope) -> str:
        if rapidocr.engine is None:
            rapidocr.initialize_ocr()
        roi = cropimg(self.recog.img, scope)
        result = rapidocr.engine(
            roi,
            use_det=True,
            use_cls=False,
            use_rec=True,
        )[0]
        texts = []

        def collect(value):
            if isinstance(value, str):
                texts.append(value)
            elif isinstance(value, (list, tuple)):
                for item in value:
                    collect(item)

        collect(result)
        return "".join(texts).replace(" ", "")

    def read_manufacture_product(self) -> str:
        from arknights_mower.utils.product_recognition import manufacture_detail_product

        product_id = manufacture_detail_product(getattr(self.recog, "img", None))
        if product_id:
            logger.debug(f"识别到当前制造产物：{MANUFACTURE_PRODUCTS[product_id].name}")
            return product_id
        product_scope = (
            (self.recog.w * 1540 // 1920, self.recog.h * 330 // 1080),
            (self.recog.w * 1835 // 1920, self.recog.h * 430 // 1080),
        )
        text = self._product_ocr_text(product_scope)
        for product_id in ("gold", "exp3"):
            product = MANUFACTURE_PRODUCTS[product_id]
            if product.name in text:
                logger.debug(f"识别到当前制造产物：{product.name}")
                return product_id

        # 源石碎片标题位于复杂背景上，实机 OCR 可能为空；材料名位于纯色背景，
        # 同时还能直接区分固源岩和装置配方。
        material_scope = (
            (self.recog.w * 430 // 1920, self.recog.h * 330 // 1080),
            (self.recog.w * 650 // 1920, self.recog.h * 430 // 1080),
        )
        material_text = self._product_ocr_text(material_scope)
        material_products = {
            "固源岩": "orirock",
            "装置": "orirock_device",
        }
        for material, product_id in material_products.items():
            if material in material_text:
                logger.debug(
                    f"识别到当前制造产物：{MANUFACTURE_PRODUCTS[product_id].name}"
                )
                return product_id
        if "源石碎片" in text:
            raise RecognizeError(
                f"无法识别源石碎片配方：{material_text or 'OCR 无结果'}"
            )
        raise RecognizeError(f"无法识别当前制造产物：{text or 'OCR 无结果'}")

    def _work_room_panel(self, room):
        recog = getattr(self, "recog", None)
        frame = getattr(recog, "_img", None)
        if frame is None:
            frame = getattr(recog, "img", None)
        if getattr(frame, "shape", None) != (1080, 1920, 3):
            return None
        interval, attempts = self.selection_transition_timing()
        for attempt in range(attempts):
            if self.find("arrange_check_in_on"):
                state = "open"
            elif self.find("arrange_check_in"):
                state = "closed"
            else:
                state = None
            actual = self.detect_room()
            if actual == room and state:
                return state
            if actual != room:
                if attempt:
                    break
                self.recog.update()
            elif attempt + 1 < attempts:
                # 入房动画可能先显示房号，再显示可点击的进驻按钮。
                self.sleep(interval)
        raise RecognizeError(f"未确认{self.translate_room(room)}的房号与进驻按钮")

    def _visible_manufacture_product(self):
        from arknights_mower.utils.product_recognition import room_product_label

        label = self.recog.gray[925:975, 225:478]
        if not label.size:
            return None
        try:
            product = room_product_label(label)
            if product:
                return product
            if rapidocr.engine is None:
                rapidocr.initialize_ocr()
            normalized = cv2.normalize(label, None, 0, 255, cv2.NORM_MINMAX)
            lines = rapidocr.engine(
                normalized, use_det=False, use_cls=False, use_rec=True
            )[0]
            if lines and len(lines) == 1:
                text, confidence = lines[0]
                if confidence >= 0.98:
                    for product in ("gold", "exp3"):
                        if text == MANUFACTURE_PRODUCTS[product].name:
                            return product
        except MowerExit:
            raise
        except Exception as error:
            logger.debug(f"房间产物名称读取失败，进入制造详情：{error}")
        return None

    def _manufacture_is_idle(self) -> bool:
        """识别制造站因缺少材料且未补货而没有正在制造的状态。"""
        status_scope = (
            (self.recog.w * 1540 // 1920, self.recog.h * 430 // 1080),
            (self.recog.w * 1835 // 1920, self.recog.h * 700 // 1080),
        )
        text = self._product_ocr_text(status_scope)
        return "已完成" in text or "空闲中" in text or "00:00:00" in text

    def _cache_facility_state(self, room: str, facility: str, product: str) -> None:
        op_data = getattr(self, "op_data", None)
        if op_data is not None:
            op_data.update_facility_state(room, facility, product)

    def refresh_facility_state(
        self,
        room: str,
        *,
        facility_observation=None,
        facility_observation_scope: ExitStack | None = None,
        defer_trade_order=False,
        after_roster=None,
    ) -> bool:
        """进入房间读取心情时，按标题栏刷新实际设施类型、产物或订单。"""
        if not self._product_switching_enabled() and not getattr(
            self.op_data, "mood_calculation_enabled", False
        ):
            return False
        if not room.startswith("room_"):
            return False
        panel = self._work_room_panel(room)
        facility_by_name = {
            "制造站": "manufacture",
            "贸易站": "trade",
            "发电站": "power",
        }
        try:
            facility = facility_by_name.get(self.detect_room_type())
        except MowerExit:
            raise
        except Exception as e:
            logger.warning(f"刷新{self.translate_room(room)}设施类型失败：{e}")
            return False
        if facility is None:
            return False
        self.op_data.update_facility_state(room, facility)
        if facility == "power":
            return True
        if (
            facility == "trade"
            and getattr(getattr(self, "task", None), "type", None)
            == TaskTypes.RUN_ORDER
        ):
            logger.debug("跑单换人后跳过贸易站订单类型刷新")
            return False

        room_product = (
            self._visible_manufacture_product()
            if facility == "manufacture" and panel
            else None
        )
        read_with_countdown = (
            facility == "trade"
            and defer_trade_order
            and facility_observation is not None
        )
        if read_with_countdown or (
            after_roster is not None and panel == "open" and not room_product
        ):
            if read_with_countdown:
                facility_observation["order_pending"] = True
            else:
                after_roster.update(
                    facility=facility,
                    captured_at=getattr(self.recog, "capture_started_at", None),
                    frame=getattr(self.recog, "_img", None),
                )
            if facility_observation is not None:
                state_name = "产物" if facility == "manufacture" else "订单类型"
                self._start_facility_observation(
                    room,
                    facility_observation,
                    facility_observation_scope,
                    f"{state_name}待确认",
                )
            return False
        return self._read_room_facility_product(
            room,
            facility,
            room_product,
            facility_observation,
            facility_observation_scope,
        )

    def _check_room_roster_frame(self, room, observation, *, sampled=False):
        frame = getattr(self.recog, "_img", None)
        captured_at = getattr(self.recog, "capture_started_at", None)
        if observation["frame"] is frame and observation["captured_at"] == captured_at:
            return
        if self._work_room_panel(room) != "open":
            raise RecognizeError(f"未确认{self.translate_room(room)}已展开的进驻面板")
        verified_frame = getattr(self.recog, "_img", None)
        verified_at = getattr(self.recog, "capture_started_at", None)
        if sampled and (verified_frame is not frame or verified_at != captured_at):
            raise RecognizeError(
                f"{self.translate_room(room)}的岗位读数与已确认画面不一致"
            )
        observation.update(frame=verified_frame, captured_at=verified_at)

    def _read_room_facility_product(
        self, room, facility, room_product, observation, observation_scope
    ):
        observed_product = None
        try:
            if facility == "trade":
                observed_product = self._observe_trade_strategy(room, retry_after=3)
            else:
                if not room_product:
                    self._wait_drone_interface(
                        accelerate_template="manufacture_accelerate", retry_after=3
                    )
                observed_product = self._cache_facility_state_from_current_page(
                    room,
                    facility,
                    defer_log=True,
                    **({"room_product": room_product} if room_product else {}),
                )
            if observed_product and observation is None:
                logger.info(observed_product[1], extra={"log_room": room})
        except MowerExit:
            raise
        except Exception as e:
            logger.warning(f"刷新{self.translate_room(room)}设施状态失败：{e}")
        if observation is not None:
            state_name = "产物" if facility == "manufacture" else "订单类型"
            summary = (
                f"{state_name}为{observed_product[0]}"
                if observed_product
                else f"{state_name}未确认"
            )
            if observation:
                observation["state_summary"] = summary
            else:
                self._start_facility_observation(
                    room, observation, observation_scope, summary
                )
        if room_product:
            return observed_product is not None
        if facility == "manufacture" and observed_product:
            # 产物和加速按钮已确认。制造页淡入时场景识别可能仍读到加工站标题。
            interval, attempts = self.selection_transition_timing()
            for _ in range(2):
                self.back(interval=interval)
                deadline = monotonic() + interval * (attempts - 1)
                for sample in range(attempts):
                    if sample:
                        self.sleep(interval)
                    if (
                        not self.find("connecting")
                        and (
                            self.find("arrange_check_in")
                            or self.find("arrange_check_in_on")
                        )
                        and not self.find("manufacture_accelerate")
                        and self.detect_room() == room
                    ):
                        return True
                    if monotonic() >= deadline:
                        break
                # 仅在原房间仍显示制造加速按钮时补发返回，未知画面交由房间恢复。
                if (
                    self.find("connecting")
                    or not self.find("manufacture_accelerate")
                    or self.detect_room() != room
                ):
                    break
            raise RecognizeError(f"未确认从制造产物页返回{self.translate_room(room)}")
        self.scene_graph_navigation(Scene.INFRA_DETAILS)
        return observed_product is not None

    def _confirm_drone_count(self, count: int):
        """在已打开的加速面板中精确选择无人机数量并确认。"""
        if count <= 0:
            return
        for _ in range(count):
            self._tap_product_point((1320, 502), interval=0.1)
        self._tap_product_point((1440, 864), interval=0.5)
        if self.scene() in self.waiting_scene:
            if not self.waiting_solver():
                raise RecognizeError("无人机加速确认后界面未恢复")

    def _select_manufacture_product(
        self, target_product: str, confirm_after: datetime | None = None
    ):
        product = MANUFACTURE_PRODUCTS[target_product]
        self._select_manufacture_recipe(product, confirm_after=confirm_after)

    def _select_manufacture_recipe(self, product, *, confirm_after=None, count=None):
        """复用制造配方与双确认流程；双芯片只下达已核算的份数。"""
        self._tap_product_point((1680, 500))
        self._wait_product_resource("manufacture_product_select")
        self._tap_product_point(product.category)
        self._tap_product_point(product.recipe)
        self._wait_product_resource("manufacture_product_change_confirm")
        if count is not None:
            if not 1 <= count <= 99:
                raise ValueError("双芯片制造份数无效")
            for _ in range(count - 1):
                self._tap_product_point((1300, 305), interval=0.2)
            self.recog.update()
            selected = self._read_manufacture_queue_count()
            if selected != count:
                raise RecognizeError(
                    f"双芯片制造份数未确认：期望{count}，读到{selected or '未知'}"
                )
        self._tap_product_point((1425, 895))
        self._wait_product_resource("manufacture_product_change_confirm", present=False)

        # 更换配方还会二次确认取消旧制造计划。
        self._wait_product_resource("manufacture_product_cancel_confirm")
        if confirm_after is not None:
            remaining = (confirm_after - datetime.now()).total_seconds()
            if remaining > 0:
                logger.info("在制造计划取消确认页等待%.1f秒后确认", remaining)
                if count is None:
                    self.sleep(remaining)
                else:
                    while remaining > 0:
                        if self.find_next_task(datetime.now()) is not None:
                            raise ProductSwitchDeferred(
                                "双芯片切产物让出到期任务", ready_at=confirm_after
                            )
                        self.sleep(min(remaining, 1))
                        remaining = (confirm_after - datetime.now()).total_seconds()
                self.recog.update()
                self._wait_product_resource("manufacture_product_cancel_confirm")
        self._tap_product_point((1440, 742))
        self._wait_product_resource("manufacture_product_cancel_confirm", present=False)

        if count is None:
            self._fill_manufacture_queue(
                material_limited=product.name.startswith("源石碎片")
            )

    def _fill_manufacture_queue(self, *, material_limited=False):
        # 新配方默认只排一份；MAX 和数量确认都需要画面读数验证。
        for attempt in range(3):
            try:
                self.recog.update()
                self._tap_product_point((1450, 305), interval=1)
                selected_count = self._read_manufacture_queue_count()
                minimum_count = 2 if material_limited else 99
                if selected_count < minimum_count:
                    raise RecognizeError(
                        f"MAX 后生产份数为{selected_count}，期望至少{minimum_count}"
                    )
                if self.find("manufacture_product_change_confirm"):
                    self._wait_product_resource("manufacture_product_change_confirm")
                    self._tap_product_point((1425, 895))
                    self._wait_product_resource(
                        "manufacture_product_change_confirm", present=False
                    )
                self.recog.update()
                actual_count = self._read_manufacture_queue_count()
                if actual_count != selected_count:
                    raise RecognizeError(
                        f"确认后生产份数为{actual_count}，期望{selected_count}"
                    )
                logger.info("制造站 MAX 补货验证通过：生产份数=%d", actual_count)
                return
            except RecognizeError as error:
                logger.warning("制造站生产份数验证第%d次失败：%s", attempt + 1, error)
                if attempt < 2:
                    self.sleep(0.5)
        raise RecognizeError("制造站生产份数验证失败，未确认 MAX 补货生效")

    def _read_manufacture_queue_count(self) -> int:
        scope = (
            (self.recog.w * 1280 // 1920, self.recog.h * 450 // 1080),
            (self.recog.w * 1415 // 1920, self.recog.h * 530 // 1080),
        )
        text = self._product_ocr_text(scope)
        digits = re.sub(r"[^0-9]", "", text)
        if re.fullmatch(r"[0-9]{1,2}", digits):
            return int(digits)
        raise RecognizeError(f"无法识别制造站生产份数：{text or 'OCR 无结果'}")

    def _open_manufacture_product_detail(self, room: str):
        self.scene_graph_navigation(Scene.INFRA_MAIN)
        self.enter_room(room)
        self._wait_drone_interface(
            interval=3, accelerate_template="manufacture_accelerate"
        )

    def _read_manufacture_total_seconds(self) -> int:
        hours, minutes, seconds = self.digit_reader.识别制造加速总剩余时间(
            self.recog.gray, self.recog.h, self.recog.w
        )
        return hours * 3600 + minutes * 60 + seconds

    def _read_manufacture_adjusted_total_seconds(self) -> int:
        """读取制造站产品卡上计入生产力加成的总剩余时间。"""
        scope = (
            (self.recog.w * 1580 // 1920, self.recog.h * 615 // 1080),
            (self.recog.w * 1790 // 1920, self.recog.h * 680 // 1080),
        )
        text = self._product_ocr_text(scope).replace("：", ":")
        match = re.search(r"(\d{1,3}):(\d{2}):(\d{2})", text)
        if not match:
            raise RecognizeError(f"无法识别制造站实际剩余时间：{text}")
        hours, minutes, seconds = map(int, match.groups())
        if minutes >= 60 or seconds >= 60:
            raise RecognizeError(f"制造站实际剩余时间无效：{text}")
        return hours * 3600 + minutes * 60 + seconds

    def _read_manufacture_speed(self) -> float:
        """从制造站页面的生产力一栏读取 1 + 干员加成。"""
        scope = (
            (self.recog.w * 1130 // 1920, self.recog.h * 940 // 1080),
            (self.recog.w * 1380 // 1920, self.recog.h * 1000 // 1080),
        )
        text = self._product_ocr_text(scope).replace("−", "-").replace("－", "-")
        expression = re.match(r"1(?:[+-]\d+(?:\.\d+)?)*", text)
        if expression is None:
            raise RecognizeError(f"无法识别制造站生产力：{text}")
        speed = 1 + sum(
            float(value)
            for value in re.findall(r"[+-]\d+(?:\.\d+)?", expression.group())
        )
        if not 0.1 <= speed <= 10:
            raise RecognizeError(f"制造站生产力无效：{text}")
        return speed

    def _product_switch_drone_plan(self, remaining: int, unit: int, max_loss: int):
        count, wait = drone_plan(remaining, unit, max_loss)
        limit = getattr(
            getattr(config.conf, "product_switching", None),
            "max_drones_per_switch",
            0,
        )
        if limit and count > limit:
            count = limit
            wait = max(0, remaining - count * DRONE_SECONDS)
        return count, wait

    def _survey_manufacture_switch(
        self, room: str, target_product: str, *, growth_chip=False
    ) -> dict:
        """只读取一个制造站，为批量计划收集快照，不消耗无人机。"""
        self._open_manufacture_product_detail(room)
        current_product = self.read_manufacture_product()
        self._cache_facility_state(room, "manufacture", current_product)
        if not growth_chip:
            self._start_product_switch_log(room, target_product, current_product)
        observation = {
            "room": room,
            "facility": "manufacture",
            "target_product": target_product,
            "current_product": current_product,
            "needs_switch": current_product != target_product,
            **({"growth_chip": True} if growth_chip else {}),
        }
        if not observation["needs_switch"]:
            return observation

        observation["available_drones"] = self.digit_reader.get_drone(
            self.recog.gray, self.recog.h, self.recog.w
        )
        if self._manufacture_is_idle():
            observation.update(
                total_seconds=0,
                current_remaining=0,
                drone_count=0,
                wait_seconds=0,
            )
            logger.info(f"{self.translate_room(room)}当前空闲，无需使用无人机")
            return observation
        rate = 1.0
        adjusted_total = None
        rate = None
        try:
            rate = self._read_manufacture_speed()
        except MowerExit:
            raise
        except Exception as e:
            logger.warning("读取制造站生产力失败：%s，尝试用页面倒计时估算", e)
            try:
                adjusted_total = self._read_manufacture_adjusted_total_seconds()
                adjusted_at = datetime.now()
            except MowerExit:
                raise
            except Exception as timer_error:
                logger.warning("读取制造站实际倒计时失败：%s", timer_error)
        self._tap_drone_accelerate("manufacture_accelerate", "all_in")
        total_seconds = self._read_manufacture_total_seconds()
        self._tap_product_point((480, 864))
        if rate is None and adjusted_total:
            adjusted_now = max(
                1, adjusted_total - (datetime.now() - adjusted_at).total_seconds()
            )
            rate = total_seconds / adjusted_now
        rate_observed = rate is not None and 0.1 <= rate <= 10
        if not rate_observed:
            logger.warning("制造速度估算异常，使用基础速度")
            rate = 1.0
        unit_seconds = MANUFACTURE_PRODUCTS[current_product].unit_seconds
        setting = getattr(config.conf, "product_switching", None)
        max_loss_seconds = (
            getattr(setting, "drone_loss_seconds", 30)
            if getattr(setting, "grandet_mode", True)
            else DRONE_SECONDS
        )
        if growth_chip:
            max_loss_seconds = 30
        drone_count, wait_seconds = self._product_switch_drone_plan(
            total_seconds, unit_seconds, max_loss_seconds
        )
        natural_only = (
            not growth_chip
            and (getattr(setting, "grandet_mode", True))
            and not getattr(setting, "use_drones_when_leaving_orirock", True)
            and current_product in {"orirock", "orirock_device"}
            and target_product not in {"orirock", "orirock_device"}
        )
        if natural_only:
            logger.info(
                "%s切出源石碎片按设置等待当前一份自然完成，不使用无人机",
                self.translate_room(room),
            )
            drone_count = 0
        observation.update(
            total_seconds=total_seconds,
            current_remaining=current_unit_remaining(total_seconds, unit_seconds),
            drone_count=drone_count,
            wait_seconds=wait_seconds,
            production_rate=rate,
            production_rate_observed=rate_observed,
            observed_at=datetime.now(),
            natural_only=natural_only,
        )
        logger.info(
            f"{self.translate_room(room)}计划：使用{drone_count}架无人机，"
            f"余下至多等待{wait_seconds}秒"
        )
        return observation

    @staticmethod
    def _product_switch_entry_lead_seconds():
        """只在当前份即将完成时进入确认页，保留短暂界面等待。"""
        return 3

    def _estimate_product_switch_ready_at(self, observations, available):
        """基础剩余量按页面生产速度减少，同时估算无人机恢复。"""
        if not observations or any(
            not item.get("production_rate_observed", True)
            or not 0.1 <= item.get("production_rate", 0) <= 10
            or not isinstance(item.get("observed_at"), datetime)
            or "current_remaining" not in item
            for item in observations
        ):
            return None
        observed_at = max(item["observed_at"] for item in observations)
        setting = getattr(config.conf, "product_switching", None)
        max_loss = (
            getattr(setting, "drone_loss_seconds", 30)
            if getattr(setting, "grandet_mode", True)
            else DRONE_SECONDS
        )

        def required_after(seconds):
            required = 0
            for item in observations:
                remaining = max(
                    0,
                    math.ceil(
                        item["current_remaining"]
                        - item["production_rate"]
                        * (
                            seconds
                            + (observed_at - item["observed_at"]).total_seconds()
                        )
                    ),
                )
                unit = MANUFACTURE_PRODUCTS[item["current_product"]].unit_seconds
                required += self._product_switch_drone_plan(remaining, unit, max_loss)[
                    0
                ]
            return required

        high = max(
            math.ceil(item["current_remaining"] / item["production_rate"])
            for item in observations
        )
        low = 0
        while low < high:
            middle = (low + high) // 2
            # 充能加成、当前一架的部分进度只会使实际可用时间更早。
            if required_after(middle) <= available + middle // 360:
                high = middle
            else:
                low = middle + 1
        logger.debug(
            "切产物实测制造速率：%s",
            [round(item.get("production_rate", 1.0), 2) for item in observations],
        )
        ready_at = observed_at + timedelta(seconds=low)
        seconds = max(0, math.ceil((ready_at - datetime.now()).total_seconds()))
        if len(observations) == 1:
            efficiency = f"{observations[0]['production_rate'] * 100:g}%"
            detail = (
                f"无人机数量不足，当前生产效率为 {efficiency}，"
                f"预计 {seconds} 秒后可满足加速计划"
            )
        else:
            detail = f"无人机数量不足，预计 {seconds} 秒后可满足整批加速计划"
        for observation in observations:
            self._update_product_switch_log(observation.get("room"), "waiting", detail)
        return ready_at

    def _retain_manufacture_switch_progress(
        self, task, observation, before_arrangement
    ):
        """重试沿用原当前份的队列边界，换班前由实际换班任务持有。"""
        owner = (getattr(self, "task", None) or task) if before_arrangement else task
        progress = getattr(owner, "product_switch_progress", {})
        owner.product_switch_progress = progress
        room = observation["room"]
        if not observation["needs_switch"]:
            progress.pop(room, None)
            return observation
        if not all(
            key in observation
            for key in ("total_seconds", "current_remaining", "current_product")
        ):
            return observation
        op_data = getattr(self, "op_data", None)
        plan = getattr(op_data, "plan", {})
        operators = getattr(op_data, "operators", {})
        signature = (
            observation["facility"],
            observation["current_product"],
            observation["target_product"],
            tuple(
                (slot.agent, slot.facility)
                for slot in (plan.get(room, ()) if isinstance(plan, dict) else ())
            ),
            tuple(
                sorted(
                    (name, operator.current_index)
                    for name, operator in (
                        operators.items() if isinstance(operators, dict) else ()
                    )
                    if operator.current_room == room
                )
            ),
        )
        state = progress.get(room)
        if state is None or state["signature"] != signature:
            state = {
                "signature": signature,
                "boundary_total": observation["total_seconds"]
                - observation["current_remaining"],
            }
            progress[room] = state
        remaining = max(0, observation["total_seconds"] - state["boundary_total"])
        observation["current_remaining"] = remaining
        observation["switch_progress"] = state
        if remaining == 0:
            state.setdefault(
                "completed_at", observation.get("observed_at", datetime.now())
            )
        if state.get("accelerated") or remaining == 0:
            observation.update(natural_only=True, drone_count=0, wait_seconds=0)
        elif not observation.get("natural_only", False):
            setting = config.conf.product_switching
            max_loss = (
                getattr(setting, "drone_loss_seconds", 30)
                if getattr(setting, "grandet_mode", True)
                else DRONE_SECONDS
            )
            observation["drone_count"], observation["wait_seconds"] = (
                self._product_switch_drone_plan(
                    remaining,
                    MANUFACTURE_PRODUCTS[observation["current_product"]].unit_seconds,
                    max_loss,
                )
            )
        return observation

    def _execute_manufacture_acceleration(self, observation: dict) -> int:
        """按快照复核当前份进度，只允许把计划中的无人机数向下修正。"""
        self._open_manufacture_product_detail(observation["room"])
        current_product = self.read_manufacture_product()
        if current_product == observation["target_product"]:
            return 0
        if current_product != observation["current_product"]:
            raise RecognizeError(
                f"{self.translate_room(observation['room'])}产物在规划期间发生变化"
            )

        if self._manufacture_is_idle():
            logger.info(
                f"{self.translate_room(observation['room'])}当前空闲，直接切换产物"
            )
            return 0

        available_drones = self.digit_reader.get_drone(
            self.recog.gray, self.recog.h, self.recog.w
        )
        self._tap_drone_accelerate("manufacture_accelerate", "all_in")
        current_total = self._read_manufacture_total_seconds()
        progressed = max(0, observation["total_seconds"] - current_total)
        remaining = max(0, observation["current_remaining"] - progressed)
        setting = getattr(config.conf, "product_switching", None)
        max_loss_seconds = (
            getattr(setting, "drone_loss_seconds", 30)
            if getattr(setting, "grandet_mode", True)
            else DRONE_SECONDS
        )
        if observation.get("growth_chip"):
            max_loss_seconds = 30
        unit_seconds = MANUFACTURE_PRODUCTS[current_product].unit_seconds
        drone_count, wait_seconds = self._product_switch_drone_plan(
            remaining, unit_seconds, max_loss_seconds
        )
        drone_count = min(drone_count, observation["drone_count"])
        wait_seconds = max(0, remaining - drone_count * DRONE_SECONDS)
        observed_at = datetime.now()
        if available_drones < drone_count:
            self._tap_product_point((480, 864))
            observation.update(
                total_seconds=current_total,
                current_remaining=remaining,
                drone_count=drone_count,
                available_drones=available_drones,
                observed_at=observed_at,
            )
            raise ProductSwitchDeferred(
                f"无人机不足：需要{drone_count}架，当前{available_drones}架",
                ready_at=self._estimate_product_switch_ready_at(
                    [observation], available_drones
                ),
                rooms=[observation["room"]],
            )
        if wait_seconds:
            rate = observation.get("production_rate")
            timing_observed = (
                observation.get("production_rate_observed", True)
                and rate is not None
                and 0.1 <= rate <= 10
            )
            if not timing_observed:
                self._tap_product_point((480, 864))
                raise ProductSwitchDeferred(
                    f"{self.translate_room(observation['room'])}缺少有效生产倒计时，"
                    "等待新的制造站观测",
                    rooms=[observation["room"]],
                )
        # 加速后记录同一份产物的剩余量，中断恢复仍沿用原当前份。
        if drone_count:
            self._confirm_drone_count(drone_count)
        else:
            self._tap_product_point((480, 864))
        observation["remaining_after_acceleration"] = max(
            0, remaining - drone_count * DRONE_SECONDS
        )
        observation["accelerated_at"] = datetime.now()
        if "switch_progress" in observation:
            observation["switch_progress"]["accelerated"] = True
            if observation["remaining_after_acceleration"] == 0:
                observation["switch_progress"].setdefault(
                    "completed_at", observation["accelerated_at"]
                )
        logger.info(
            f"{self.translate_room(observation['room'])}执行计划："
            f"使用{drone_count}架无人机，余下至多等待{wait_seconds}秒"
        )
        return wait_seconds

    def _change_manufacture_product(self, observation: dict, direct=False):
        self._open_manufacture_product_detail(observation["room"])
        current_product = self.read_manufacture_product()
        self._cache_facility_state(observation["room"], "manufacture", current_product)
        self._start_product_switch_log(
            observation["room"], observation["target_product"], current_product
        )
        if current_product == observation["target_product"]:
            self._fill_manufacture_queue(
                material_limited=current_product in {"orirock", "orirock_device"}
            )
            self._update_product_switch_log(observation["room"], "completed")
            return
        confirm_after = None
        if (not direct) and not self._manufacture_is_idle():
            state = observation.get("switch_progress")
            remaining_base = None
            if "accelerated_at" not in observation or state is not None:
                self._tap_drone_accelerate("manufacture_accelerate", "all_in")
                current_total = self._read_manufacture_total_seconds()
                self._tap_product_point((480, 864))
                boundary = (
                    state["boundary_total"]
                    if state is not None
                    else observation["total_seconds"] - observation["current_remaining"]
                )
                remaining_base = max(0, current_total - boundary)
            elif observation["remaining_after_acceleration"] == 0:
                remaining_base = 0
            if remaining_base == 0:
                completed_at = (
                    state.setdefault("completed_at", datetime.now())
                    if state is not None
                    else observation.get("accelerated_at", datetime.now())
                )
            else:
                try:
                    rate = self._read_manufacture_speed()
                except MowerExit:
                    raise
                except Exception as e:
                    logger.warning("切换前重读生产力失败：%s，使用巡检值", e)
                    rate = (
                        observation.get("production_rate")
                        if observation.get("production_rate_observed", True)
                        else None
                    )
                if rate is None or not 0.1 <= rate <= 10:
                    raise ProductSwitchDeferred(
                        f"{self.translate_room(observation['room'])}缺少有效生产速度，"
                        "等待新的制造站观测",
                        rooms=[observation["room"]],
                    )
                if "accelerated_at" in observation:
                    conservative_rate = (
                        min(rate, observation["production_rate"])
                        if observation.get("production_rate_observed", True)
                        and observation.get("production_rate") is not None
                        else rate
                    )
                    completed_at = observation["accelerated_at"] + timedelta(
                        seconds=observation["remaining_after_acceleration"]
                        / conservative_rate
                    )
                else:
                    completed_at = datetime.now() + timedelta(
                        seconds=remaining_base / rate
                    )
            setting = config.conf.product_switching
            buffer_seconds = (
                getattr(setting, "waiting_seconds", 2)
                if getattr(setting, "grandet_mode", True)
                else 0
            )
            confirm_after = completed_at + timedelta(seconds=buffer_seconds)
            wait_seconds = max(
                0, math.ceil((confirm_after - datetime.now()).total_seconds())
            )
            lead = self._product_switch_entry_lead_seconds()
            if wait_seconds > lead and not getattr(
                self, "_product_batch_active", False
            ):
                raise ProductSwitchDeferred(
                    f"{self.translate_room(observation['room'])}当前一份尚需约"
                    f"{wait_seconds}秒，稍后进入切换确认页",
                    ready_at=confirm_after - timedelta(seconds=lead),
                    rooms=[observation["room"]],
                    log_reason="production"
                    if completed_at > datetime.now()
                    else "confirmation",
                )
        self._select_manufacture_product(
            observation["target_product"], confirm_after=confirm_after
        )
        self.recog.update()
        final_product = self.read_manufacture_product()
        self._cache_facility_state(observation["room"], "manufacture", final_product)
        if final_product != observation["target_product"]:
            raise RecognizeError(
                f"制造站产物切换校验失败：期望"
                f"{MANUFACTURE_PRODUCTS[observation['target_product']].name}，"
                f"实际{MANUFACTURE_PRODUCTS[final_product].name}"
            )
        self._update_product_switch_log(observation["room"], "completed")

    def _open_trade_product_detail(self, room: str):
        self.scene_graph_navigation(Scene.INFRA_MAIN)
        self.enter_room(room)
        self._wait_drone_interface(
            interval=3,
            accelerate_template="bill_accelerate",
            page_template="order_label",
        )

    def _observe_trade_strategy(self, room, **navigation):
        self._wait_drone_interface(
            accelerate_template="bill_accelerate",
            page_template="order_label",
            **navigation,
        )
        return self._cache_facility_state_from_current_page(
            room, "trade", defer_log=True
        )

    def _read_trade_product_card(self) -> tuple[str, bool]:
        """从订单列表右下角卡片读取订单类型及是否允许切换。"""
        from arknights_mower.utils.product_recognition import trade_strategy_card

        strategy = trade_strategy_card(getattr(self.recog, "img", None))
        if strategy is not None:
            product_id, switchable = strategy
        else:
            scope = (
                (self.recog.w * 1400 // 1920, self.recog.h * 840 // 1080),
                (self.recog.w * 1810 // 1920, self.recog.h * 1040 // 1080),
            )
            text = self._product_ocr_text(scope)
            locked = "3级后可切换" in text or ("3级" in text and "切换" in text)
            if "开采协力" in text:
                product_id = "orundum"
            elif "龙门商法" in text or locked:
                product_id = "lmd"
            else:
                raise RecognizeError(
                    f"无法识别当前贸易站订单类型：{text or 'OCR 无结果'}"
                )
            switchable = not locked
        logger.debug(
            f"识别到当前贸易站订单类型：{TRADE_PRODUCTS[product_id].strategy_name}"
        )
        if not switchable:
            logger.debug("识别到低等级贸易站，订单类型固定为龙门商法")
        return product_id, switchable

    def _cache_facility_state_from_current_page(
        self,
        room: str,
        facility: Literal["manufacture", "trade"],
        *,
        defer_log: bool = False,
        room_product: str | None = None,
    ) -> tuple[str, str] | None:
        """在当前生产页面顺带更新设施状态，不进入或退出任何页面。"""
        if not self._product_switching_enabled() and not getattr(
            self.op_data, "mood_calculation_enabled", False
        ):
            return
        if facility not in ("manufacture", "trade"):
            raise ValueError(f"未知设施类型：{facility}")
        try:
            if facility == "manufacture":
                product = room_product or self.read_manufacture_product()
                label = MANUFACTURE_PRODUCTS[product].name
            else:
                product, _ = self._read_trade_product_card()
                label = TRADE_PRODUCTS[product].strategy_name
            self._cache_facility_state(room, facility, product)
            description = "识别产物" if facility == "manufacture" else "识别订单类型"
            message = f"{facility_label(room, self.op_data)}：{description}为{label}，已更新设施状态记录"
            if defer_log:
                return label, message
            logger.info(message, extra={"log_room": room})
        except MowerExit:
            raise
        except Exception as e:
            logger.warning(f"刷新{self.translate_room(room)}设施状态失败：{e}")

    def _close_trade_product_select(self):
        # 订单类型点击后立即生效，但选择弹窗不会自行关闭。
        self._tap_product_point((1600, 200))
        self._wait_product_resource("trade_strategy_select", present=False)

    def _survey_trade_switch(self, room: str, target_product: str) -> dict:
        self._open_trade_product_detail(room)
        current_product, switchable = self._read_trade_product_card()
        self._cache_facility_state(room, "trade", current_product)
        self._start_product_switch_log(room, target_product, current_product)
        return {
            "room": room,
            "facility": "trade",
            "target_product": target_product,
            "current_product": current_product,
            "needs_switch": current_product != target_product,
            "switchable": switchable,
        }

    def _change_trade_product(self, observation: dict):
        self._open_trade_product_detail(observation["room"])
        current_product, switchable = self._read_trade_product_card()
        self._cache_facility_state(observation["room"], "trade", current_product)
        self._start_product_switch_log(
            observation["room"], observation["target_product"], current_product
        )
        if current_product == observation["target_product"]:
            self._update_product_switch_log(observation["room"], "completed")
            return
        if not switchable:
            if observation["target_product"] == "lmd":
                return
            message = (
                f"{self.translate_room(observation['room'])}实际贸易站未达到3级，"
                "无法切换至开采协力；请检查排班表设施等级与订单类型"
            )
            logger.error(message)
            raise ProductSwitchFailed(message, [observation["room"]])
        self._tap_product_point((1580, 955))
        self._wait_product_resource("trade_strategy_select")
        self._tap_product_point(TRADE_PRODUCTS[observation["target_product"]].option)
        self._close_trade_product_select()
        self.recog.update()
        final_product, _ = self._read_trade_product_card()
        self._cache_facility_state(observation["room"], "trade", final_product)
        if final_product != observation["target_product"]:
            raise RecognizeError(
                f"贸易站订单切换校验失败：期望"
                f"{TRADE_PRODUCTS[observation['target_product']].strategy_name}，"
                f"实际{TRADE_PRODUCTS[final_product].strategy_name}"
            )
        self._update_product_switch_log(observation["room"], "completed")

    def _admit_product_switch_batch(
        self,
        tasks,
        before_arrangement,
        observations=(),
        direct_rooms=(),
    ):
        """读数前和消耗无人机前复核整批窗口，已开始的批次不让出调度。"""
        if not tasks:
            return
        seconds = product_switch_seconds(len(tasks))
        if not observations:
            seconds = max(
                seconds,
                max(
                    getattr(task, "product_switch_budget_seconds", 0) for task in tasks
                ),
            )
        if observations:
            now = datetime.now()
            waits = 0
            setting = config.conf.product_switching
            buffer_seconds = setting.waiting_seconds if setting.grandet_mode else 0
            for item in observations:
                if (
                    item["facility"] != "manufacture"
                    or not item["needs_switch"]
                    or item["room"] in direct_rooms
                ):
                    continue
                remaining = max(
                    0,
                    item["current_remaining"]
                    - item.get("drone_count", 0) * DRONE_SECONDS
                    if "current_remaining" in item
                    else item.get("wait_seconds", 0),
                )
                rate = item.get("production_rate", 1.0)
                if (
                    not item.get("production_rate_observed", True)
                    or rate is None
                    or not 0.1 <= rate <= 10
                ):
                    continue
                elapsed = max(0, (now - item.get("observed_at", now)).total_seconds())
                completed_at = item.get("switch_progress", {}).get("completed_at")
                if completed_at is not None:
                    waits += max(
                        0, (completed_at - now).total_seconds() + buffer_seconds
                    )
                else:
                    waits += max(0, remaining / rate - elapsed + buffer_seconds)
            # 常规预算包含每站一分钟等待；长于该值时使用实测等待加操作时间。
            seconds = max(seconds, 60 + 60 * len(tasks) + math.ceil(waits))
        current = getattr(self, "task", None)
        for task in tasks:
            task.product_switch_budget_seconds = seconds
        duration = timedelta(seconds=seconds)
        if before_arrangement and current is not None:
            current.product_switch_budget_seconds = seconds
            staffing = copy.copy(current)
            staffing.pending_product_targets = {}
            staffing.product_switch_budget_seconds = 0
            duration += estimate_task_duration(
                staffing, op_data=getattr(self, "op_data", None)
            )
        has_dorm = (
            before_arrangement
            and current is not None
            and any(room.startswith("dormitory_") for room in current.plan)
        )
        finish = datetime.now() + duration + timedelta(seconds=60 if has_dorm else 15)
        deadline = next(
            (
                pending
                for pending in self._arrangement_priority_tasks()
                if (finish >= pending.time if has_dorm else finish > pending.time)
            ),
            None,
        )
        if deadline is not None:
            raise ProductSwitchPriorityDeferred(
                f"整批切产物预计需要{duration.total_seconds():.0f}秒，"
                f"先执行{deadline.type.display_value}（{deadline.meta_data}）"
            )

    def _product_switch_log_context(self, tasks, before_arrangement):
        """仅保留有限条展示状态，跨让出调度沿用同一任务的设施切换。"""
        if not self._product_switching_enabled():
            return {}
        states = getattr(self, "_product_switch_log_states", {})
        self._product_switch_log_states = states
        context = {}
        for task in tasks:
            room, target = parse_product_task_meta(task.meta_data)
            owner = (
                (getattr(self, "task", None) or task) if before_arrangement else task
            )
            key = (id(owner), room)
            state = states.get(key)
            if state is not None and state["target"] != target:
                self._publish_product_switch_log(
                    state, "failed", "切换目标已变更，原切换未完成"
                )
                states.pop(key, None)
                state = None
            if state is None:
                state = {
                    "id": uuid4().hex,
                    "owner": owner,
                    "target": target,
                    "key": key,
                    "event": None,
                }
                states[key] = state
                while len(states) > 32:
                    oldest = next(iter(states))
                    self._publish_product_switch_log(states[oldest], "failed")
                    states.pop(oldest, None)
            state["waiting_logged"] = False
            context[room] = state
            while len(context) > 32:
                context.pop(next(iter(context)))
        return context

    def _product_switch_log_scope(self, room):
        state = getattr(self, "_active_product_switch_logs", {}).get(room)
        if state is None or state.get("terminal"):
            return nullcontext()
        return log_parent_context({"type": "production-switch", "id": state["id"]})

    def _start_product_switch_log(self, room, target, previous=None):
        state = getattr(self, "_active_product_switch_logs", {}).get(room)
        if state is None or state["target"] != target:
            return
        manufacture = target in MANUFACTURE_PRODUCTS
        definitions = MANUFACTURE_PRODUCTS if manufacture else TRADE_PRODUCTS
        product = definitions.get(target)
        before = definitions.get(previous)
        if product is None:
            return
        if state["event"] is not None:
            if (
                "previous" not in state["event"]
                and before is not None
                and previous != target
            ):
                state["event"]["previous"] = (
                    before.name if manufacture else before.strategy_name
                )
            if state.get("phase") == "waiting":
                self._publish_product_switch_log(state, "started")
            return
        if previous == target:
            return
        event = {
            "type": "production-switch",
            "id": state["id"],
            "room": room,
            "label": facility_label(room, getattr(self, "op_data", None)),
            "facility": "manufacture" if manufacture else "trade",
            "product": product.name if manufacture else product.strategy_name,
        }
        if before is not None:
            event["previous"] = before.name if manufacture else before.strategy_name
        state["event"] = event
        self._publish_product_switch_log(state, "started")

    def _publish_product_switch_log(self, state, phase, detail=None):
        event = state["event"]
        if event is None or state.get("terminal"):
            return
        snapshot = {**event, "phase": phase, "anchor": phase == "started"}
        parent = {"type": event["type"], "id": event["id"]}
        log_context = {"log_parent": parent, "log_room": event["room"]}
        operation = "产物" if event["facility"] == "manufacture" else "订单类型"
        if phase == "waiting":
            reason = str(detail).strip() or "切换尚未完成"
            snapshot["detail"] = reason[:2048]
            message = f"等待切换{event['label']} 的{operation}"
            logger.info(reason, extra=log_context)
            state["waiting_logged"] = True
        elif phase == "failed":
            message = f"{event['label']} 的{operation}切换未完成"
            if detail is not None:
                reason = str(detail).strip() or "操作已中断"
                snapshot["detail"] = reason[:2048]
                message += f"：{reason}"
        elif phase == "completed":
            message = f"已将{event['label']} 的{operation}切换为{event['product']}"
        elif "previous" in event:
            message = f"正在切换{event['label']} 的{operation} {event['previous']} → {event['product']}"
        else:
            message = f"正在将{event['label']} 的{operation}切换为{event['product']}"
        state["phase"] = phase
        logger.info(message, extra={**log_context, "log_event": snapshot})
        if phase in ("completed", "failed"):
            state["terminal"] = True
            states = getattr(self, "_product_switch_log_states", {})
            if states.get(state["key"]) is state:
                states.pop(state["key"])

    def _update_product_switch_log(self, room, phase, detail=None):
        state = getattr(self, "_active_product_switch_logs", {}).get(room)
        if state is not None:
            self._publish_product_switch_log(state, phase, detail)

    def switch_base_products(
        self,
        tasks: list[SchedulerTask],
        before_arrangement: bool = False,
    ):
        """批次失败时解除连续执行状态，成功后覆盖依赖本次切换的换班。"""
        previous = getattr(self, "_active_product_switch_logs", None)
        self._active_product_switch_logs = self._product_switch_log_context(
            tasks, before_arrangement
        )
        try:
            self._execute_product_switch_batch(tasks, before_arrangement)
        except BaseException as error:
            self._product_batch_active = False
            rooms = getattr(error, "rooms", ())
            for room, state in self._active_product_switch_logs.items():
                if rooms and room not in rooms:
                    continue
                if isinstance(
                    error, (ProductSwitchDeferred, ProductSwitchPriorityDeferred)
                ):
                    if not state["waiting_logged"]:
                        self._publish_product_switch_log(state, "waiting", str(error))
                else:
                    self._publish_product_switch_log(state, "failed", str(error))
            raise
        finally:
            if previous is None:
                self.__dict__.pop("_active_product_switch_logs", None)
            else:
                self._active_product_switch_logs = previous
        if not before_arrangement:
            self._product_batch_active = False

    def _execute_product_switch_batch(self, tasks, before_arrangement):
        """先巡检全部目标站，再按等待余数从小到大逐站完成切换。"""
        if not self._product_switching_enabled():
            self._discard_product_switches()
            return
        self._admit_product_switch_batch(tasks, before_arrangement)
        task_observations = []
        for task in tasks:
            room, target_product = parse_product_task_meta(task.meta_data)
            try:
                with self._product_switch_log_scope(room):
                    if target_product in MANUFACTURE_PRODUCTS:
                        observation = self._survey_manufacture_switch(
                            room, target_product
                        )
                        self._retain_manufacture_switch_progress(
                            task, observation, before_arrangement
                        )
                    else:
                        observation = self._survey_trade_switch(room, target_product)
            except RecognizeError as error:
                raise ProductSwitchFailed(str(error), [room]) from error
            task_observations.append((task, observation))

        locked_trade = [
            (task, observation)
            for task, observation in task_observations
            if observation["facility"] == "trade"
            and observation["needs_switch"]
            and not observation.get("switchable", True)
        ]
        if locked_trade:
            rooms = "、".join(
                self.translate_room(observation["room"])
                for _, observation in locked_trade
            )
            message = (
                f"{rooms}实际贸易站未达到3级，无法切换订单类型；"
                "请检查排班表设施等级与订单类型"
            )
            logger.error(message)
            raise ProductSwitchFailed(
                message, [observation["room"] for _, observation in locked_trade]
            )

        pending_manufacture = [
            observation
            for _, observation in task_observations
            if observation["facility"] == "manufacture" and observation["needs_switch"]
        ]
        accelerated_manufacture = [
            item for item in pending_manufacture if not item.get("natural_only", False)
        ]
        planned_drones = sum(item["drone_count"] for item in accelerated_manufacture)
        available = min(
            (item["available_drones"] for item in accelerated_manufacture),
            default=planned_drones,
        )
        logger.info(
            f"制造站批量切产物计划共需至多{planned_drones}架无人机，"
            f"当前可用{available}架"
        )
        deferred = []
        deferred_rooms = set()
        insufficient_drones = planned_drones > available
        allow_direct = getattr(
            getattr(config.conf, "product_switching", None),
            "direct_when_drones_insufficient",
            False,
        )
        if insufficient_drones and not allow_direct:
            for item in accelerated_manufacture:
                try:
                    with self._product_switch_log_scope(item["room"]):
                        refreshed = dict(
                            self._survey_manufacture_switch(
                                item["room"], item["target_product"]
                            )
                        )
                except RecognizeError as error:
                    raise ProductSwitchFailed(str(error), [item["room"]]) from error
                source_task = next(
                    task
                    for task, observation in task_observations
                    if observation is item
                )
                self._retain_manufacture_switch_progress(
                    source_task, refreshed, before_arrangement
                )
                item.clear()
                item.update(refreshed)
            pending_manufacture = [
                item for item in pending_manufacture if item["needs_switch"]
            ]
            accelerated_manufacture = [
                item
                for item in pending_manufacture
                if not item.get("natural_only", False)
            ]
            planned_drones = sum(
                item["drone_count"] for item in accelerated_manufacture
            )
            available = min(
                (item["available_drones"] for item in accelerated_manufacture),
                default=planned_drones,
            )
            insufficient_drones = planned_drones > available
            if insufficient_drones:
                rooms = [item["room"] for item in accelerated_manufacture]
                deferred.append(
                    ProductSwitchDeferred(
                        f"批量切产物无人机不足：需要{planned_drones}架，当前{available}架",
                        ready_at=self._estimate_product_switch_ready_at(
                            accelerated_manufacture, available
                        ),
                        rooms=rooms,
                    )
                )
                deferred_rooms.update(rooms)

        direct_switch_rooms = (
            {item["room"] for item in accelerated_manufacture}
            if insufficient_drones and allow_direct
            else set()
        )
        self._admit_product_switch_batch(
            tasks,
            before_arrangement,
            [item for _, item in task_observations],
            direct_rooms=direct_switch_rooms,
        )
        self._product_batch_active = True
        # 独立订单不使用无人机，在制造站等待资源前完成。
        if not before_arrangement:
            for _, observation in task_observations:
                if observation["facility"] == "trade" and observation["needs_switch"]:
                    try:
                        with self._product_switch_log_scope(observation["room"]):
                            self._change_trade_product(observation)
                    except RecognizeError as error:
                        raise ProductSwitchFailed(
                            str(error), [observation["room"]]
                        ) from error
            resolved_trade = {
                id(task)
                for task, observation in task_observations
                if observation["facility"] == "trade"
            }
            self.tasks[:] = [
                task for task in self.tasks if id(task) not in resolved_trade
            ]

        # 配方已生效的重试仍需完成数量确认，再移除切换任务。
        for task, observation in task_observations:
            if (
                observation["facility"] == "manufacture"
                and not observation["needs_switch"]
            ):
                try:
                    with self._product_switch_log_scope(observation["room"]):
                        self._change_manufacture_product(observation)
                except RecognizeError as error:
                    raise ProductSwitchFailed(
                        str(error), [observation["room"]]
                    ) from error
                self.tasks[:] = [other for other in self.tasks if other is not task]

        execution_order = sorted(
            pending_manufacture,
            key=lambda item: (
                item.get("current_remaining", 0)
                if item.get("natural_only")
                else item.get("wait_seconds", 0)
            ),
        )
        for observation in execution_order:
            item = observation
            room = item["room"]
            if room in deferred_rooms:
                continue
            try:
                if not item.get("natural_only") and room not in direct_switch_rooms:
                    with self._product_switch_log_scope(room):
                        self._execute_manufacture_acceleration(item)
            except ProductSwitchDeferred as error:
                if not allow_direct or item["available_drones"] >= item["drone_count"]:
                    error.rooms = error.rooms or (item["room"],)
                    deferred.append(error)
                    deferred_rooms.add(item["room"])
                    continue
                logger.warning(
                    "%s无人机在执行前变得不足，直接切换产物",
                    self.translate_room(item["room"]),
                )
                direct_switch_rooms.add(item["room"])
            except RecognizeError as error:
                raise ProductSwitchFailed(str(error), [item["room"]]) from error

            try:
                if observation.get("natural_only") and observation.get(
                    "current_remaining", 0
                ):
                    rate = observation.get("production_rate")
                    observed_at = observation.get("observed_at")
                    if (
                        not observation.get("production_rate_observed", True)
                        or rate is None
                        or not 0.1 <= rate <= 10
                        or not isinstance(observed_at, datetime)
                    ):
                        raise ProductSwitchDeferred(
                            f"{self.translate_room(room)}缺少有效生产倒计时，等待新的制造站观测",
                            rooms=[room],
                        )
                with self._product_switch_log_scope(room):
                    if room in direct_switch_rooms:
                        self._change_manufacture_product(observation, direct=True)
                    else:
                        self._change_manufacture_product(observation)
            except ProductSwitchDeferred as error:
                error.rooms = error.rooms or (room,)
                deferred.append(error)
                continue
            except RecognizeError as error:
                raise ProductSwitchFailed(str(error), [room]) from error
            source = next(
                task for task, item in task_observations if item is observation
            )
            owner = (
                (getattr(self, "task", None) or source)
                if before_arrangement
                else source
            )
            getattr(owner, "product_switch_progress", {}).pop(room, None)
            self.tasks[:] = [task for task in self.tasks if task is not source]

        if deferred:
            timed = [error for error in deferred if error.ready_at is not None]
            next_wait = (
                min(timed, key=lambda error: error.ready_at) if timed else deferred[0]
            )
            raise ProductSwitchDeferred(
                str(next_wait),
                ready_at=next_wait.ready_at,
                rooms=tuple(
                    dict.fromkeys(room for error in deferred for room in error.rooms)
                ),
                room_deferrals=deferred,
                log_reason=getattr(next_wait, "log_reason", None),
            )
        if before_arrangement:
            for _, observation in task_observations:
                if observation["facility"] == "trade" and observation["needs_switch"]:
                    try:
                        with self._product_switch_log_scope(observation["room"]):
                            self._change_trade_product(observation)
                    except RecognizeError as error:
                        raise ProductSwitchFailed(
                            str(error), [observation["room"]]
                        ) from error

        task_ids = {id(task) for task, _ in task_observations}
        self.tasks[:] = [task for task in self.tasks if id(task) not in task_ids]
        self.tasks.sort(
            key=lambda task: (bool(getattr(task, "execution_failure", None)), task.time)
        )
        logger.info("基建批量切换完成，共处理%d个生产站", len(task_observations))

    def drone(
        self,
        room: str,
        not_customize=False,
        not_return=False,
        adjust_time=False,
        skip_enter=False,
        order_tasks=None,
    ):
        if self.op_data.is_orundum_trade_room(room):
            logger.info("卖玉贸易站不使用无人机加速：%s", room)
            return False
        if not adjust_time:
            logger.info("基建：无人机加速")
        retain_reserve = not not_customize
        # 点击进入该房间
        if not skip_enter:
            self.enter_room(room)
        # 进入房间详情

        self.tap((self.recog.w * 0.05, self.recog.h * 0.95), interval=3)
        # 关闭掉房间总览
        self._wait_drone_interface(interval=3)

        accelerate = self.find("manufacture_accelerate")
        if accelerate:
            self._cache_facility_state_from_current_page(room, "manufacture")
            drone_count = self.digit_reader.get_drone(self.recog.gray)
            logger.info(f"当前无人机数量为：{drone_count}")
            if drone_count < self.drone_count_limit or (
                retain_reserve and drone_count == self.drone_count_limit
            ):
                logger.info(
                    f"无人机数量{drone_count}未满足加速条件，阈值为{self.drone_count_limit}->停止"
                )
                return
            logger.info("制造站加速")
            all_in_scope = self._tap_drone_accelerate(
                "manufacture_accelerate", "all_in"
            )
            if retain_reserve:
                self._confirm_drone_count(drone_count - self.drone_count_limit)
            else:
                self.tap(all_in_scope)
                self.tap(accelerate, y_rate=1)
        else:
            product, _ = self._read_trade_product_card()
            self.op_data.update_facility_state(room, "trade", product)
            if self.op_data.is_orundum_trade_room(room):
                self.scene_graph_navigation(Scene.INFRA_MAIN)
                return False
            accelerate = self.find("bill_accelerate")
            while accelerate and not adjust_time:
                logger.info("贸易站加速")
                all_in_scope = self._tap_drone_accelerate("bill_accelerate", "all_in")
                self.tap(all_in_scope)
                self.tap((self.recog.w * 0.75, self.recog.h * 0.8))
                if self.scene() in self.waiting_scene:
                    if not self.waiting_solver():
                        return
                self.recog.update()
                self.accept_order(room=room)
                if not (
                    self.drone_room is None
                    or (
                        self.drone_room == room and room in self.op_data.run_order_rooms
                    )
                ):
                    break
                if not_customize:
                    drone_count = self.digit_reader.get_drone(self.recog.gray)
                    logger.info(f"当前无人机数量为：{drone_count}")
                    if drone_count < self.drone_count_limit:
                        logger.info(f"无人机数量小于{self.drone_count_limit}->停止")
                        break
                accelerate = self.find("bill_accelerate")
            if adjust_time:
                return self.adjust_order_time(
                    accelerate,
                    room,
                    **({"order_tasks": order_tasks} if order_tasks is not None else {}),
                )
        if not_return:
            return
        self.scene_graph_navigation(Scene.INFRA_MAIN)

