    def get_order(self, name):
        if name in self.op_data.operators:
            return True, self.op_data.operators[name].arrange_order
        else:
            return False, ["技能", "false"]

    def _same_run_order_restoration(self, room, target):
        pending = getattr(self.task, "run_order_confirmation_pending", None)
        return bool(
            pending
            and pending["room"] == room
            and pending["restoring"]
            and getattr(self.task, "run_order_restore_pending", False)
            and pending["target"]
            == target
            == getattr(self.task, "run_order_original_roster", {}).get(room)
        )

    def _prepare_run_order_confirmation(self, room, target):
        if room.startswith("dorm"):
            return
        if pending := getattr(self.task, "run_order_confirmation_pending", None):
            if pending["exhausted"] and self._same_run_order_restoration(room, target):
                # 相同原班沿用已耗尽的提交期限；重选不增加观察时间。
                return
            raise RunOrderConfirmationUnresolved(room)
        allowance = run_order_network_allowance(self.task, config.conf)
        if (
            not getattr(config.conf, "run_order_network_adaptive", False)
            or allowance <= 0
            or self._emergency_frozen()
        ):
            return
        self.task.run_order_confirmation_pending = {
            "room": room,
            "target": list(target),
            "restoring": list(target)
            == getattr(self.task, "run_order_original_roster", {}).get(room),
            "allowance": allowance,
            "submitted": False,
            "expires_at": None,
            "exhausted": False,
        }

    def _run_order_confirmation_deadline(self, *, start=False):
        pending = self.task.run_order_confirmation_pending
        if pending["expires_at"] is None:
            if not start:
                return None
            pending["expires_at"] = datetime.now() + timedelta(
                seconds=pending["allowance"]
            )
            recovery = getattr(self.task, "confirmation_recovery_rooms", {})
            recovery[pending["room"]] = "consumed"
            self.task.confirmation_recovery_rooms = recovery
            # 单调期限只保存在本次进程，存档仅保存绝对时间与未决责任。
            self._run_order_confirmation_clock = (
                pending,
                monotonic() + pending["allowance"],
            )
            try:
                if save_current_state() is False:
                    raise RecognizeError("无法保存干员确认观察期限，保留原任务")
            except BaseException:
                pending["exhausted"] = True
                raise
            logger.info(
                "%s 干员确认结果尚未核实，追加最多%s秒观察，页面变化不重新计时",
                pending["room"],
                f"{pending['allowance']:g}",
            )
        clock = self.__dict__.get("_run_order_confirmation_clock")
        if clock is None or clock[0] is not pending:
            remaining = max(
                0,
                min(
                    pending["allowance"],
                    (pending["expires_at"] - datetime.now()).total_seconds(),
                ),
            )
            clock = (pending, monotonic() + remaining)
            self._run_order_confirmation_clock = clock
        return clock[1]

    @contextmanager
    def _run_order_confirmation_observation(self):
        pending = self.task.run_order_confirmation_pending
        deadline = self._run_order_confirmation_deadline(start=True)
        try:
            if pending["exhausted"] or monotonic() >= deadline:
                raise ObservationTimeout("干员确认观察已超时")
            with self.observation_deadline(deadline):
                yield deadline
        except ObservationTimeout as exc:
            pending["exhausted"] = True
            raise RunOrderConfirmationUnresolved(pending["room"]) from exc

    def _observe_run_order_confirmation(self, room, template, observation):
        pending = getattr(self.task, "run_order_confirmation_pending", None)
        if not pending or not pending["submitted"] or pending["room"] != room:
            return False
        deadline = observation.enter_context(self._run_order_confirmation_observation())
        while True:
            remaining = deadline - monotonic()
            if remaining <= 0:
                raise ObservationTimeout("干员确认观察已超时")
            if self.find("connecting"):
                if not self.waiting_solver(restart_on_timeout=False):
                    raise ObservationTimeout("干员确认联网观察已超时")
                continue
            if any(
                self.find(other, score=0.9)
                for other in ("confirm_blue", "confirm_train", "arrange_confirm")
                if other != template
            ) or self.find("room_detail"):
                return True
            if self.find(template, score=0.9):
                # 原按钮仍在时回房读结果；按钮已消失则等待迟到的二次确认。
                self.back(interval=min(0.2, remaining))
                return True
            self.sleep(
                min(self.performance_profile.screenshot_interval / 1000, remaining)
            )

    def _verify_run_order_confirmation(self, room, current, target):
        pending = getattr(self.task, "run_order_confirmation_pending", None)
        if not pending or pending["room"] != room:
            return current
        if not pending["submitted"]:
            self.task.__dict__.pop("run_order_confirmation_pending", None)
            return current

        def confirmed(rows):
            return (
                len(rows) == len(pending["target"])
                and all(item.get("observed", True) for item in rows)
                and [item["agent"] for item in rows] == pending["target"]
            )

        if not confirmed(current):
            try:
                with self._run_order_confirmation_observation() as deadline:
                    while not confirmed(current):
                        remaining = deadline - monotonic()
                        if remaining <= 0:
                            raise ObservationTimeout("干员确认观察已超时")
                        self.sleep(
                            min(
                                self.performance_profile.screenshot_interval / 1000,
                                remaining,
                            )
                        )
                        # 后续联网或实读中断时，不能用上一帧的完整名单授权重选。
                        current = []
                        if self.find("connecting"):
                            if not self.waiting_solver(restart_on_timeout=False):
                                raise ObservationTimeout("干员确认联网观察已超时")
                        current = self.get_agent_from_room(room)
            except RunOrderConfirmationUnresolved:
                names = [row.get("agent") for row in current]
                named = [name for name in names if name]
                if (
                    self._same_run_order_restoration(room, target)
                    and len(current) == len(target)
                    and all(row.get("observed", True) for row in current)
                    and all(isinstance(name, str) for name in names)
                    and not any(name in ("Free", "Current") for name in named)
                    and len(named) == len(set(named))
                    and self.find("room_detail")
                ):
                    # 完整实读已知未恢复时，交回房间原有的有限重选。
                    # 同一原班的迟到提交不改变目标；旧换入和未知读数仍等待。
                    return current
                raise
        self.task.__dict__.pop("run_order_confirmation_pending", None)
        self.__dict__.pop("_run_order_confirmation_clock", None)
        agents = [item["agent"] for item in current if item["agent"]]
        names = "、".join(f"[[operator:{name}]]" for name in agents)
        label = facility_label(room, self.op_data)
        message = (
            f"已确认 {names} 进驻 {label}" if agents else f"已确认 {label} 无人进驻"
        )
        logger.info(message, extra={"log_room": room, "log_agents": agents})
        return current

    @contextmanager
    def _read_run_order_confirmation(self):
        pending = getattr(self.task, "run_order_confirmation_pending", None)
        if pending and pending["expires_at"] is not None and not pending["exhausted"]:
            with self._run_order_confirmation_observation():
                yield
        else:
            yield

    @timed_step("confirm")
    def tap_confirm(self, room, new_plan=None, *, training_slot=None):
        try:
            with ExitStack() as observation:
                return self._tap_confirm(room, new_plan, observation, training_slot)
        except RunOrderConfirmationUnresolved:
            # 追加观察已结束，沿用一次正常退页实读；不再获得额外等待。
            if self.find("room_detail"):
                return
            if self.scene() == Scene.INFRA_ARRANGE:
                self.back(interval=0.2)
                return
            raise

    def _tap_confirm(self, room, new_plan, observation, training_slot=None):
        if new_plan is None:
            new_plan = {}
        self.recog.update()
        self._validate_coordination_commit()
        finish_mood_calculation()
        if (
            self.task.type == TaskTypes.RUN_ORDER
            and not self.task.adjusted
            and room in self.op_data.run_order_rooms
            and self.task.meta_data
            and len(new_plan) == 1
            and config.conf.run_order_buffer_time > 0
        ):
            # 等待结束后仍须读取确认页；为当前截图后端的实测耗时预留时间。
            capture_seconds = (config.screenshot_avg or 0) / 1000
            wait_confirm = round(
                (
                    (
                        getattr(self.task, "run_order_calibrated_time", self.task.time)
                        - datetime.now()
                    ).total_seconds()
                    + run_order_entry_seconds(self.task, config.conf)
                    - run_order_buffer_seconds(self.task, config.conf)
                    - capture_seconds
                ),
                1,
            )
            if wait_confirm > 0:
                logger.info(f"等待跑单 {str(wait_confirm)} 秒")
                self.sleep(wait_confirm)
        templates = ("confirm_blue", "confirm_train", "arrange_confirm")
        if training_slot is not None:
            templates = (templates[training_slot], "arrange_confirm")
        for template in templates:
            verify_slot = training_slot is not None and template != "arrange_confirm"
            clicks = 0
            retry_ready = False
            submission_observed = False
            for _ in range(12):
                if self.find("connecting"):
                    retry_ready = False
                    submission_observed = clicks > 0
                    wait_options = {}
                    if clicks and self.task.type != TaskTypes.RUN_ORDER:
                        profile = self.performance_profile
                        wait_options["first_check"] = max(
                            profile.poll_interval, profile.screenshot_interval / 1000
                        )
                    if not self.waiting_solver(**wait_options):
                        # 联网超时已重启游戏；先完成登录，调用方再实读驻员。
                        self.back_to_infrastructure()
                        raise RecognizeError("干员确认联网等待超时，返回房间重试")
                # 已点击后提高按钮清晰度要求，避免再次点击淡出动画里的残影。
                # 初次按钮沿用原识别规则，兼容不同背景和训练室。
                if verify_slot and not clicks:
                    pos = self._require_training_selection(training_slot)
                else:
                    pos = (
                        self.find(template, score=0.9)
                        if clicks
                        else self.find(template)
                    )
                if pos is None:
                    if not clicks:
                        break
                    if any(
                        self.find(destination)
                        for destination in (
                            "confirm_blue",
                            "confirm_train",
                            "arrange_confirm",
                        )
                        if destination != template
                    ):
                        break
                    if any(
                        self.find(destination)
                        for destination in (
                            "room_detail",
                            "arrange_check_in",
                            "arrange_check_in_small",
                            "arrange_check_in_on",
                            "recycle/dashboard",
                        )
                    ):
                        return
                    # 按钮消失但目标页尚未出现也是过渡帧，不能漏掉迟到的二次确认。
                    retry_ready = False
                    self.sleep(0.2)
                    continue
                if submission_observed:
                    # 提交反馈结束后仍显示选人页，也可能已经进驻；返回房间由调用方实读核验。
                    self.back(interval=0.2)
                    break
                if clicks and not retry_ready:
                    # 可能仍是点击前的旧帧；再观察一次才判断点击未生效。
                    retry_ready = True
                    self.sleep(0.2)
                    continue
                if clicks >= 4:
                    if self._observe_run_order_confirmation(
                        room, template, observation
                    ):
                        break
                    raise RecognizeError("干员确认点击未生效，返回房间重试")
                if verify_slot and clicks:
                    pos = self._require_training_selection(training_slot)
                target = (
                    (self.recog.w // 3 * 2, self.recog.h - 10)
                    if template == "arrange_confirm"
                    else pos
                )
                # tap 自己完成一次等待及缓存失效，不再叠加 sleep(0.5)。
                if (
                    getattr(self.op_data, "mood_calculation_enabled", False)
                    or getattr(self.task, "exhaust_support", False)
                ) and not getattr(self.task, "mood_physical_started", False):
                    self._validate_coordination_commit()
                    finish_mood_calculation()
                    retained = getattr(self.task, "execution_retained", False)
                    self.task.mood_physical_started = True
                    self.task.execution_retained = True
                    try:
                        if save_current_state() is False:
                            raise RecognizeError("无法保存换班执行状态，取消首次提交")
                    except BaseException:
                        self.task.mood_physical_started = False
                        self.task.execution_retained = retained
                        raise
                pending = getattr(self.task, "run_order_confirmation_pending", None)
                if pending and not pending["submitted"]:
                    pending["submitted"] = True
                    try:
                        if save_current_state() is False:
                            raise RecognizeError(
                                "无法保存干员确认提交状态，取消本次提交"
                            )
                    except BaseException:
                        pending["submitted"] = False
                        raise
                self.tap(target, interval=0.2)
                clicks += 1
                retry_ready = False
            else:
                if self._observe_run_order_confirmation(room, template, observation):
                    continue
                raise RecognizeError("干员确认画面仍未稳定，返回房间重试")

    def _open_check_in_detail(self):
        """#92：训练室主页面点 arrange_check_in（屏幕左侧 ~(101,441)）开进驻信息浮窗。

        旧代码 tap((0.25w, 0.95h))=(480,1026)——该坐标在训练室落在左下角技能/进度
        面板，弹出技能详情浮窗而非进驻信息浮窗（Scene -1 空转 7s 后出房重进）。
        与 turn_on_room_detail 同源：找不到模板就 sleep 等动画重扫。
        """
        if pos := self.find("arrange_check_in"):
            self.tap(pos, interval=0.5)
        elif pos := self.find("arrange_check_in_small"):
            self.tap(pos, interval=0.5)
        else:
            self.sleep()

    @staticmethod
    def _training_slot_matches(index, target, occupant):
        return (
            occupant == target
            or target == "Current"
            or target == "Free"
            and (index == 0 or bool(occupant))
        )

    def _require_training_selection(self, index):
        expected = "confirm_train" if index == 1 else "confirm_blue"
        interval, attempts = self.selection_transition_timing()
        deadline = monotonic() + (attempts - 1) * interval
        for attempt in range(attempts):
            if attempt:
                remaining = deadline - monotonic()
                if remaining <= 0:
                    break
                self.sleep(min(interval, remaining))
            if self.recog.img.shape != (1080, 1920, 3):
                continue
            self.require_agent_selection_page()
            buttons = self._profession_filter_buttons(stationary_only=True)
            if len(buttons) == 1:
                resource, x, y = buttons[0]
                if resource != expected:
                    raise AgentSelectionPageChanged(
                        "训练室选人页与所点岗位不符，返回房间重试"
                    )
                h, w = loadres(resource).shape[:2]
                return ((x, y), (x + w, y + h))
        raise AgentSelectionNotReady("训练室选人页的确认按钮未稳定，返回房间重试")

    def choose_train(self, agents: list[str], fast_mode=True, choose_error=0):
        target = None
        submitted = None
        clicks = 0
        retry_at = 0.0
        unknown_cnt = 0
        deadline = monotonic() + 120
        while monotonic() < deadline:
            scene = self.scene()
            if scene == Scene.UNKNOWN:
                unknown_cnt += 1
                if unknown_cnt > 5:
                    unknown_cnt = 0
                    target = None
                    self.back_to_infrastructure()
                    self.enter_room("train")
                else:
                    self.sleep()
            elif scene == Scene.CONNECTING:
                self.sleep(1)
            elif scene == Scene.INFRA_MAIN:
                target = None
                self.enter_room("train")
            elif scene == Scene.INFRA_DETAILS:
                if not (self.find("room_detail") or self.find("arrange_check_in_on")):
                    self._open_check_in_detail()
                    continue
                remaining = retry_at - monotonic()
                if target is not None and remaining > 0:
                    self.sleep(min(remaining, 1))
                    continue
                observed = self.get_agent_from_room(
                    "train", departing_plan=agents, submitted_training_slot=submitted
                )
                occupants = BaseSchedulerSolver._observed_room_names(
                    "train", observed, RIGHT_SIDE_ROOM_CAPACITY["train"]
                )
                logger.debug("训练室两槽实际驻员：%s", occupants)
                missing = next(
                    (
                        (index, name)
                        for index, name in enumerate(agents)
                        if not BaseSchedulerSolver._training_slot_matches(
                            index, name, occupants[index]
                        )
                    ),
                    None,
                )
                if missing is None:
                    return
                if missing != target:
                    clicks = 0
                target, submitted = missing, None
                if clicks >= 2:
                    raise AgentSelectionNotReady("未能打开训练室选人页，返回房间重试")
                idx, _ = target
                retry_at = monotonic() + 10
                clicks += 1
                self.tap((self.recog.w * 0.82, self.recog.h * 0.18 * (idx + 1)))
            elif scene == Scene.TRAIN_FINISH:
                self.tap((self.recog.w * 0.05, self.recog.h * 0.95), interval=0.5)
            elif scene == Scene.TRAIN_MAIN:
                self._open_check_in_detail()
            elif scene == Scene.INFRA_ARRANGE_ORDER:
                if target is None:
                    self.back()
                    continue
                idx, name = target
                self._require_training_selection(idx)
                label = name if name in ("", "Free") else f"[[operator:{name}]]"
                logger.info(
                    "正在安排 %s 进驻训练室%s",
                    label,
                    "协助位" if idx == 0 else "训练位",
                    extra={
                        "log_room": "train",
                        "log_agents": [name] if name not in ("", "Free") else [],
                        "log_event": {
                            "type": "training-selection",
                            "positions": [{"agent": name, "index": idx}]
                            if name
                            else [],
                        },
                    },
                )
                options = {"choose_error": choose_error} if choose_error else {}
                if idx == 0:
                    self.choose_agent([name], "train", fast_mode, **options)
                else:
                    self.choose_train_ope(name, **options)
                self.tap_confirm("train", training_slot=idx)
                submitted, target = target, None
            else:
                target = None
                self.back_to_infrastructure()
        raise AgentSelectionNotReady("训练室选人超时，返回房间重试")

    @fixed_selection_profile
    def choose_train_ope(self, ope: str, choose_error=0):
        from arknights_mower.utils.selection_branch import branch_filter_state

        order = self.detect_arrange_order("train_trainee")
        if (
            not choose_error
            and ope not in ("Free", "Current", "阿米娅")
            and order is not None
            and order[0] in ("等级", "稀有度")
            and self._select_visible_trainee(ope)
        ):
            self.last_room = "train"
            return
        if order is None or order[0] == "信赖值":
            self.switch_arrange_order("等级", "train_trainee", refresh=False)
        profession = "ALL"
        branch = None
        if ope != "阿米娅" and ope not in ["Current", "Free"]:
            profession = agent_profession[ope]
            self.profession_filter(profession)
            if not choose_error and branch_filter_state(
                getattr(self.recog, "img", None), profession
            ) == (False, False):
                if self._select_visible_trainee(ope, sidebar_open=True):
                    self.last_room = "train"
                    return
                if self.op_data.profession_filter:
                    branch = agent_branch.get(ope)
        if ope in ("Free", "阿米娅"):
            self.profession_filter("ALL")
        # 训练卡片延伸到屏幕右侧，职业栏会遮住末列姓名。
        self._close_profession_filter()
        right_swipe = 0
        max_swipe = 50
        observation = None
        previous_page = None
        narrowed = False
        named_target = ope != "Free"
        profession_pages = []
        while True:
            try:
                candidates = [ope] if named_target else self.get_free_list([])
                sel, ret = self.scan_agent(
                    candidates,
                    max_agent_count=1,
                    train=True,
                    observation=observation,
                    respect_train_selection=ope != "Free",
                )
                observation = None
                if sel and (sel == [ope] or ope == "Free"):
                    ope = sel[0]
                    break
                if (
                    branch
                    and any(name and scope for name, scope in ret)
                    and not any(
                        self.same_agent_page(ret, page, allow_unknown=True)
                        for page in profession_pages
                    )
                ):
                    # 首屏和之后的两个不同页面；同一手势重试、尾页回弹均不算新页。
                    profession_pages.append(tuple(ret))
                if branch and len(profession_pages) == 3:
                    self._set_profession_filter_open(True)
                    narrowed = select_visible_branch(self, profession, branch)
                    branch = None
                    if not narrowed:
                        self.profession_filter("ALL")
                        self.profession_filter(profession)
                    self._close_profession_filter()
                    right_swipe = 0
                    previous_page = observation = None
                    continue
                if right_swipe >= max_swipe:
                    raise AgentPageNotAdvanced("训练干员搜索达到上限，返回房间重试")
                if (
                    not self.low_frame_rate_mode
                    and right_swipe >= 3
                    and ret == previous_page
                ):
                    if not narrowed and getattr(self, "choose_error", None) is not None:
                        self.choose_error.add(ope)
                    raise AgentPageNotAdvanced("训练干员列表已到末尾，返回房间重试")
                previous_page = ret
                moved, observation = self.swipe_agent_page(
                    ret, [ope], train=True, return_page=True
                )
                right_swipe += moved
            except (AgentPageNotAdvanced, AgentCardObservationNotReady) as error:
                if not narrowed:
                    if isinstance(error, AgentPageNotAdvanced):
                        raise TraineeCardUnavailable(
                            ope,
                            getattr(self, "op_data", None),
                            error,
                            candidates=None if named_target else tuple(candidates),
                        ) from error
                    raise
                self.require_agent_selection_page()
                self.profession_filter(profession)
                self._close_profession_filter()
                narrowed = False
                right_swipe = 0
                previous_page = observation = None
        if named_target:
            # 训练位一次只选一人；在当前列表的新帧核对姓名与蓝框即可结束。
            try:
                verified = self.verify_agent([ope], "train", train=True)
            except AgentSelectionPageChanged:
                raise
            except AgentSelectionNotReady:
                verified = False
            if verified:
                self.last_room = "train"
                return
            self.require_agent_selection_page()
            if not self.find("confirm_train"):
                raise AgentSelectionNotReady("训练选人页尚未确认，返回房间重试")
        if narrowed:
            self.profession_filter(profession)
            self._close_profession_filter()
        else:
            self.swipe_left(right_swipe, special_filter=profession, train=True)
        self.ctap((1280, 60), 0.3)
        self.ctap((1280, 60), 0.3)
        logger.debug("验证训练位干员选择")
        if not self.verify_agent([ope], "train", train=True):
            logger.debug([ope])
            raise Exception("检测到干员选择错误，重新选择")
        self.last_room = "train"

    def _select_visible_trainee(self, name, *, sidebar_open=False):
        img = getattr(self.recog, "_img", None)
        if not isinstance(img, np.ndarray):
            return False
        button_x = 1554 if sidebar_open else 1669
        if self._profession_filter_buttons(stationary_only=True) != (
            ("confirm_train", button_x, 997),
        ):
            return False
        try:
            page = self.agent_page_reader(train=True)(img)
        except (cv2.error, ValueError):
            self.require_agent_selection_page()
            return False
        target = [card for card in page if card[0] == name]
        if len(target) != 1 or (
            sidebar_open and not self._cards_before_profession_sidebar(target)
        ):
            return False
        self.require_agent_selection_page()
        if self.find("connecting"):
            raise AgentSelectionNotReady("训练选人页仍在连接，返回房间重试")
        try:
            selected, _ = self.scan_agent(
                [name],
                max_agent_count=1,
                train=True,
                observation=self.observe_agent_page(page, train=True),
                respect_train_selection=True,
                exclude_sidebar=sidebar_open,
            )
            if selected and self.wait_for_arranged_agents(
                [name], train=True, quick_check=True
            ):
                self.require_agent_selection_page()
                return True
        except AgentSelectionPageChanged:
            raise
        except AgentSelectionNotReady:
            pass
        self.require_agent_selection_page()
        if not self.find("confirm_train"):
            raise AgentSelectionNotReady("训练选人页尚未确认，返回房间重试")
        return False

    def get_free_list(
        self,
        agents: list[str] = None,
        *,
        include_full=False,
        current_resident="",
        room=None,
    ) -> list[str]:
        agents = agents or []
        candidates = self.get_dorm_candidates(
            agents, current_resident=current_resident, room=room
        )
        return candidates.filling if include_full else candidates.recovering

    def get_dorm_candidates(self, agents=(), *, current_resident="", room=None):
        excluded, _ = dorm_task_reservations(
            self.op_data, [self.task, *getattr(self, "tasks", [])], agents
        )
        waiting_names, _ = self._waiting_shift_reservations(
            current_task=getattr(self, "task", None)
        )
        excluded.update(waiting_names)
        # 当轮回班目标尚未落位时，宿舍补位不能把它当作候补占用。
        current_task = getattr(self, "task", None)
        if current_task is not None and current_task.type == TaskTypes.SHIFT_ON:
            excluded.update(
                name
                for target_room, row in current_task.plan.items()
                if not target_room.startswith("dorm")
                for name in row
                if name not in ("", "Current", "Free")
            )
        excluded.update(getattr(self.task, "backup_retention_releases", ()))
        residents = set(current_resident.split(",")) | set(
            getattr(self.task, "dorm_mood_residents", ())
        )
        if room is not None:
            residents = {
                name
                for name in residents
                if (op := self.op_data.operators.get(name)) is not None
                and op.current_room == room
            }
        return dorm_candidates(self.op_data, excluded, current_residents=residents)

    def dorm_mood_fallback_candidates(self, agents, room, candidates=None):
        """缓存无人需休息时仍搜索未知空闲者；原住者可参加最低心情比较。"""
        task = getattr(self, "task", None)
        if (
            (not room.startswith("dorm"))
            or task is None
            or task.type == TaskTypes.FIAMMETTA
        ):
            return []
        if candidates is None:
            candidates = self.get_dorm_candidates(
                agents,
                current_resident=(
                    task.meta_data if task.type == TaskTypes.RELEASE_DORM else ""
                ),
                room=room,
            )
        names = candidates.filling
        if (
            getattr(self.op_data, "idle_dorm_search_exhausted", False)
            and not candidates.estimated_recovering
        ):
            return []
        if (
            not any(
                not self.op_data.operators[name].current_room
                for name in candidates.recovering
            )
            and candidates.unknown
        ):
            # 空床、普通补床和清退共用游戏心情升序确认，未知缓存不能关闭搜索。
            return names
        resident_names = list(getattr(task, "dorm_mood_residents", ()))
        if task.type == TaskTypes.RELEASE_DORM:
            resident_names.extend(task.meta_data.split(","))
        if not resident_names:
            return []
        residents = [
            op
            for name in resident_names
            if (op := self.op_data.operators.get(name)) is not None
            and op.current_room == room
            and has_resting_mood(op)
            and resting_mood(op) >= op.upper_limit
            and not self.op_data.skip_idle_dorm_release(name)
            and not self.op_data.has_rest_mood_limit(name)
        ]
        if not residents:
            return []
        if self.op_data.config.mood_limits is None or not any(
            resting_mood(self.op_data.operators.get(name)) < resting_mood(current)
            for current in residents
            for name in names
        ):
            return []
        return names

    def _pending_group_transitions(self):
        """队列中已开始且仍待确认的换班保留已观测恢复上下文。"""
        transitions = {}
        for task in getattr(self, "tasks", ()):
            if getattr(task, "group_shift_expected", {}):
                transitions.update(
                    self.op_data.arrangement_group_transitions(
                        task.plan,
                        group_transitions=getattr(task, "group_shift_transitions", {}),
                    )
                )
        return transitions

    def _execution_group_transitions(self, plan=None):
        """执行与读房共用待确认状态，剩余明确安排优先覆盖。"""
        task = getattr(self, "task", None)
        return self.op_data.arrangement_group_transitions(
            (getattr(task, "plan", {}) if plan is None else plan) or {},
            group_transitions={
                **self._pending_group_transitions(),
                **getattr(task, "group_shift_transitions", {}),
            },
        )

    def _cancel_dorm_recovery_targets(self, plan, group_transitions, *, task=None):
        """整批合法取消先于任何容量检查，确认目标与首次改写同步。"""
        if task is None:
            task = getattr(self, "task", None)
        expected = getattr(task, "group_shift_expected", {})
        for room, names in plan.items():
            if not room.startswith("dorm"):
                continue
            for index, name in enumerate(names):
                current = self.op_data.get_current_operator(room, index)
                if (
                    getattr(task, "simple_dorm_fill", False)
                    and current is not None
                    and current.name == name
                ):
                    continue
                if name in (
                    "",
                    "Current",
                    "Free",
                ) or not self.op_data.is_dynamic_dorm_position(
                    room, index, name, group_transitions=group_transitions
                ):
                    continue
                capped = self.op_data.rest_mood_complete(name)
                if resting_tier(self.op_data, name) != RestingTier.EXCLUDED and (
                    not capped or self.op_data.is_free_room_excluded(name)
                ):
                    continue
                if expected.get((room, index)) == name:
                    expected.pop((room, index))
                    remaining = task.plan.get(room, [])
                    if remaining[index : index + 1] == [name]:
                        remaining[index] = "Free"
                logger.info(
                    "取消动态恢复目标：房间=%s，位置=%s，干员=%s，原因=%s",
                    room,
                    index + 1,
                    name,
                    "达到个人心情上限" if capped else "宿舍恢复排除",
                )
                names[index] = "Free"

    def _cancel_released_group_shift_targets(self, name):
        """个人上限清退实测完成后，同步其他换班任务的动态恢复目标。"""
        for task in [*self.tasks, *getattr(self, "waiting_group_shifts", ())]:
            plan = {}
            for (room, index), expected in getattr(
                task, "group_shift_expected", {}
            ).items():
                if expected == name:
                    plan.setdefault(room, ["Current"] * len(self.op_data.plan[room]))[
                        index
                    ] = name
            if not plan:
                continue
            transitions = self.op_data.arrangement_group_transitions(
                task.plan,
                group_transitions=getattr(task, "group_shift_transitions", {}),
            )
            pending_slots = {
                (room, index)
                for room, names in plan.items()
                for index, target in enumerate(names)
                if target == name
                and task.plan.get(room, [])[index : index + 1] == [name]
            }
            self._cancel_dorm_recovery_targets(plan, transitions, task=task)
            for room, index in pending_slots:
                if (room, index) not in task.group_shift_expected:
                    # 清退已经完成，原任务只保留其他动作，不再重选这个床位。
                    task.plan[room][index] = "Current"
            for room in {room for room, _ in pending_slots}:
                if all(target == "Current" for target in task.plan[room]):
                    del task.plan[room]

    def preserve_resting_crafters(self, agents, room, *, observed_candidates=()):
        """按统一层级解析 Free，并让实际选人遵守正在休息者的接管规则。"""
        if not room.startswith("dorm") or (
            getattr(getattr(self, "task", None), "type", None) == TaskTypes.FIAMMETTA
        ):
            return
        capacity_plan = dict(getattr(self.task, "plan", {}) or {})
        capacity_plan[room] = agents
        group_transitions = self._execution_group_transitions(capacity_plan)
        self._cancel_dorm_recovery_targets(capacity_plan, group_transitions)
        # 补床任务入队后名单也可能改变；执行时重新检查明确写入的姓名。
        for index, name in enumerate(agents):
            current = self.op_data.get_current_operator(room, index)
            if (
                getattr(self.task, "simple_dorm_fill", False)
                and current is not None
                and current.name == name
            ):
                continue
            if name in (
                "",
                "Current",
                "Free",
            ) or not self.op_data.is_dynamic_dorm_position(
                room, index, name, group_transitions=group_transitions
            ):
                continue
            if (
                current is None or current.name != name
            ) and not self.op_data.dorm_capacity_allows(
                name,
                (room, index),
                plan=capacity_plan,
                group_transitions=group_transitions,
            ):
                agents[index] = "Free"
                self._check_group_shift_targets(
                    agents, room, reason=f"具名入住 {name} 未通过绑组宿舍额度检查"
                )
        moving = (
            {
                name
                for target_room, names in self.task.plan.items()
                for target_index, name in enumerate(names)
                if name not in ("Current", "Free", "")
                and (
                    (op := self.op_data.operators.get(name)) is None
                    or (op.current_room, op.current_index)
                    != (target_room, target_index)
                )
            }
            if self.task is not None
            else set()
        )
        # 名单可能在任务入队后才修改；已写明新入住者的旧补床任务也须保床。
        # 本次已明确上班或换床的原入住者可移动，不能仅因上限清退为空闲。
        for index in range(len(agents)):
            current = self.op_data.get_current_operator(room, index)
            if (
                current is not None
                and current.name not in (set(agents) | moving)
                and self.op_data.is_free_room_excluded(current.name)
                and self.op_data.is_dynamic_dorm_position(
                    room, index, current.name, group_transitions=group_transitions
                )
            ):
                agents[index] = current.name
        if "Free" not in agents:
            return
        if self.task is not None:
            slots = getattr(self.task, "dorm_selection_free_slots", {})
            slots.setdefault(room, set()).update(
                index for index, name in enumerate(agents) if name == "Free"
            )
            self.task.dorm_selection_free_slots = slots
        now = datetime.now()
        current_resident = (
            self.task.meta_data
            if self.task is not None and self.task.type == TaskTypes.RELEASE_DORM
            else ""
        )
        candidates = self.get_dorm_candidates(
            agents, current_resident=current_resident, room=room
        )
        mood_fallback = self.dorm_mood_fallback_candidates(agents, room, candidates)
        replacements = [
            self.op_data.operators[name]
            for name in dict.fromkeys([*candidates.recovering, *observed_candidates])
            if name in candidates.filling
            and name in self.op_data.operators
            and not self.op_data.operators[name].current_room
        ]
        if observed_candidates:
            names = crafting_rest_order(
                self.op_data,
                sorted(
                    [op.name for op in replacements],
                    key=lambda name: resting_key(self.op_data, name, now),
                ),
            )
            replacements = [self.op_data.operators[name] for name in names]
            if replacements:
                mood_fallback = []
        for index, name in enumerate(agents):
            if name != "Free":
                continue
            current = self.op_data.get_current_operator(room, index)
            if (
                current is not None
                and resting_tier(self.op_data, current.name) == RestingTier.EXCLUDED
            ):
                # 满员兜底也不能重新安排被排除的原住者。
                current = None
            eligible = [
                candidate
                for candidate in replacements
                if self.op_data.dorm_capacity_allows(
                    candidate.name,
                    (room, index),
                    plan=capacity_plan,
                    group_transitions=group_transitions,
                )
            ]
            replacement = next(iter(eligible), None)
            if (
                current is not None
                and self.op_data.is_dynamic_dorm_position(
                    room, index, current.name, group_transitions=group_transitions
                )
                and current.name not in (set(agents) | moving)
                and not (
                    getattr(self.task, "strict_mood_limit", False)
                    and self.task.meta_data == current.name
                )
                and not self.op_data.rest_mood_complete(current.name)
                and not (
                    getattr(self.task, "type", None) == TaskTypes.RELEASE_DORM
                    and self.task.release_dorm_targets().get(current.name)
                    == (room, index)
                )
            ):
                replacement = next(
                    (
                        candidate
                        for candidate in eligible
                        if bed_takeover_allowed(
                            self.op_data, candidate.name, current.name
                        )
                    ),
                    None,
                )
                if replacement is None:
                    agents[index] = current.name
                    continue
            if mood_fallback and (
                current is None
                or has_resting_mood(current, now)
                and resting_mood(current, now) >= current.upper_limit
                and not self.op_data.is_free_room_excluded(current.name)
            ):
                # 保留 Free，实际选人时从心情升序列表第一页开始找。
                continue
            if (
                current is not None
                and getattr(self.task, "strict_mood_limit", False)
                and self.task.meta_data == current.name
                and self.op_data.has_rest_mood_limit(current.name)
                and not self.op_data.is_free_room_excluded(current.name)
            ):
                # 上限释放必须真正换出本人，不能被主班床位保护抵消。
                current = None
            if current is not None and current.name in (set(agents) | moving):
                current = None
            if current is not None:
                mood = resting_mood(current, now)
                bed = next(
                    (d for d in self.op_data.dorm if d.position == (room, index)),
                    None,
                )
                full = (
                    has_resting_mood(current, now) and mood >= current.upper_limit
                ) or (bed is not None and bed.time is not None and bed.time <= now)
                slot = self.op_data.plan[room][index]
                if (
                    current.is_high()
                    and not full
                    and self.op_data.is_auto_free_dorm_slot(
                        room, index, group_transitions=group_transitions
                    )
                    and slot.agent == current.name
                ):
                    continue
                if not full:
                    if (
                        replacement is None
                        or bed is None
                        or not self.op_data._slot_takable(
                            bed,
                            requester=replacement.name,
                            plan=capacity_plan,
                            group_transitions=group_transitions,
                        )
                    ):
                        agents[index] = current.name
                        continue
            if replacement is not None:
                agents[index] = replacement.name
                replacements.remove(replacement)
            elif (
                current is not None
                and self.op_data.is_dynamic_dorm_position(
                    room, index, current.name, group_transitions=group_transitions
                )
                and not self.op_data.rest_mood_complete(current.name)
            ):
                # 无人需要接替时保留原住者，满心情本身不应制造空床。
                agents[index] = current.name
                if has_resting_mood(current, now) and mood >= current.upper_limit:
                    current.dorm_mood_fallback = room
                    logger.info(
                        f"{room} 保留满心情干员 {current.name}："
                        "没有缓存有效且需要恢复的空闲候选，优先保持宿舍满员"
                    )
            else:
                full_candidates = [
                    name
                    for name in candidates.filling
                    if name not in candidates.recovering
                    and name not in candidates.unknown
                    and name not in agents
                    and self.op_data.dorm_capacity_allows(
                        name,
                        (room, index),
                        plan=capacity_plan,
                        group_transitions=group_transitions,
                    )
                    and (
                        name not in self.op_data.operators
                        or not self.op_data.operators[name].current_room
                    )
                ]
                known = next(iter(full_candidates), None)
                if known is not None:
                    if known in self.op_data.operators:
                        agents[index] = known
                        self.op_data.operators[known].dorm_mood_fallback = room
                    else:
                        agents[index] = "Free"
                else:
                    # 未知心情统一交给游戏页面，不能直接按默认24指定姓名。
                    agents[index] = "Free" if candidates.unknown else ""
        self._check_group_shift_targets(agents, room, reason="补位后恢复原任务目标")
        # 游戏确认后会把空位挤到末尾，后续读房和恢复计时使用同一位置。
        if "Current" not in agents:
            agents[:] = [name for name in agents if name] + [""] * agents.count("")
        return [name for name in mood_fallback if name not in agents]

    def _check_group_shift_targets(self, agents, room, *, reason):
        """原任务确认目标优先于执行期补位，返回是否需要重新选人。"""
        # 训练室分别选择协助位和训练位，单次选人名单不代表整房安排。
        if room == "train":
            return False
        task = getattr(self, "task", None)
        expected = getattr(task, "group_shift_expected", {})
        required = {
            index: name
            for (target_room, index), name in expected.items()
            if target_room == room
        }
        if required:
            targets = ["Current"] * (max(required) + 1)
            for index, name in required.items():
                targets[index] = name
            protected_plan = {room: targets}
            self._suppress_facility_arrangement(protected_plan)
            required = {
                index: name
                for index, name in enumerate(protected_plan.get(room, ()))
                if name != "Current"
            }
        conflicts = []
        for index, name in required.items():
            selected = agents[index] if index < len(agents) else ""
            if selected == name:
                continue
            if selected == "Current":
                actual = self.op_data.get_current_operator(room, index)
                if actual is not None and actual.name == name:
                    continue
            conflicts.append({"index": index, "expected": name, "selected": selected})
        duplicate_slots = [
            index
            for index, name in enumerate(agents)
            if name in required.values() and required.get(index) != name
        ]
        if not conflicts and not duplicate_slots:
            return False
        row = task.plan.setdefault(room, list(agents))
        for names in (agents, row):
            for index, name in enumerate(names):
                if name in required.values() and required.get(index) != name:
                    names[index] = "Free"
            for index, name in required.items():
                names.extend(["Current"] * max(0, index + 1 - len(names)))
                names[index] = name
        differences = "；".join(
            f"第{item['index'] + 1}位确认 {item['expected']}，选人 {item['selected'] or '空位'}"
            for item in conflicts
        )
        try:
            saved = save_current_state()
            save_error = ""
        except Exception as exc:
            saved, save_error = False, f"（{exc}）"
        preservation = (
            "恢复后的任务已保存"
            if saved
            else f"运行状态保存失败{save_error}，任务仅保留在内存，重启可能无法恢复本次目标"
        )
        logger.warning(
            f"换班确认目标冲突：任务={task.type.display_value}@{task.time.isoformat()}，"
            f"房间={room}，目标差异={differences}，重复位置={duplicate_slots}，"
            f"恢复名单={agents}，原因={reason}，"
            f"待确认换班={getattr(task, 'group_shift_transitions', {})}；"
            f"保留原任务目标，继续本次安排；{preservation}",
            extra={"archive_screenshots": False},
        )
        return True

    def prepare_dorm_selection(
        self, agents, room, *, preserve_dorm_occupants=False, observed_candidates=()
    ):
        """执行边界统一解析名单；解析结果同时交给单回排序和实际选人。"""
        # 充能和归位均使用肥鸭任务的明确名单；不养闲人、上限清退及
        # 普通补床不能把充能对象改成 Free，也不能用原入住者覆盖它。
        if getattr(getattr(self, "task", None), "type", None) == TaskTypes.FIAMMETTA:
            return []
        task = getattr(self, "task", None)
        for (target_room, index), expected in getattr(
            task, "backup_retention_empty_slots", {}
        ).items():
            if target_room != room or index >= len(agents) or agents[index] != "":
                continue
            current = self.op_data.get_current_operator(room, index)
            # 清空只作用于生成任务时的原住者，后续观测的其他住客不被误退。
            if current is not None and (
                current.name != expected
                or self.op_data.is_free_room_excluded(current.name)
                or self.op_data.operators[current.name].room
            ):
                agents[index] = current.name
        plan = dict(getattr(task, "plan", {}) or {})
        plan[room] = agents
        group_transitions = self._execution_group_transitions(plan)
        if not preserve_dorm_occupants:
            self._cancel_dorm_recovery_targets(plan, group_transitions)
        current_list = set()
        for idx, n in enumerate(agents):
            if getattr(getattr(self, "task", None), "simple_dorm_fill", False):
                current = self.op_data.get_current_operator(room, idx)
                if current is not None and current.name == n:
                    current_list.add(n)
                    continue
            if n not in current_list:
                current_list.add(n)
            elif n not in ("", "Free", "Current"):
                agents[idx] = "Free"
            if (
                preserve_dorm_occupants
                and room.startswith("dorm")
                and agents[idx] in self.op_data.operators
                and self.op_data.rest_mood_complete(agents[idx])
                and not self.op_data.is_free_room_excluded(agents[idx])
                and self.op_data.is_dynamic_dorm_position(
                    room, idx, agents[idx], group_transitions=group_transitions
                )
            ):
                self.op_data.operators[agents[idx]].depletion_rate = 0
                agents[idx] = "Free"
                logger.info("检测个人心情上限释放休息位")
        if not preserve_dorm_occupants:
            fallback = (
                self.preserve_resting_crafters(
                    agents, room, observed_candidates=observed_candidates
                )
                or []
            )
            expected = getattr(getattr(self, "task", None), "group_shift_expected", {})
            relocated = {}
            for slot, name in list(expected.items()):
                if slot[0] == room and name in agents:
                    # 空位整理可移动其他恢复目标；确认位置跟随最终名单。
                    relocated[room, agents.index(name)] = name
                    expected.pop(slot)
            expected.update(relocated)
            self._check_group_shift_targets(
                agents, room, reason="执行边界准入与床位整理"
            )
            return fallback
        return []

    def refresh_dorm_selection_candidates(self, agents, room):
        """补位前只核验心情升序首屏，缓存仍有恢复者时也发现新候选。"""
        task = getattr(self, "task", None)
        if (
            not room.startswith("dorm")
            or task is None
            or task.type == TaskTypes.FIAMMETTA
            or getattr(self.op_data, "idle_dorm_search_exhausted", False)
        ):
            return None
        slots = set(getattr(task, "dorm_selection_free_slots", {}).get(room, ()))
        slots.update(
            index
            for index, name in enumerate(
                getattr(task, "dorm_fill_plan", {}).get(room, ())
            )
            if name != "Current"
        )
        slots.update(index for index, name in enumerate(agents) if name == "Free")
        expected = getattr(task, "group_shift_expected", {})
        slots = {
            index
            for index in slots
            if index < len(agents)
            and (room, index) not in expected
            and (
                agents[index] == "Free"
                or (op := self.op_data.operators.get(agents[index])) is not None
                and not op.is_high()
                and not op.current_room
            )
        }
        if not slots:
            return None
        original = agents.copy()
        row = task.plan.get(room)
        original_row = row.copy() if row is not None else None
        try:
            # 清除本次普通补位的临时具名预约，再用共享规则筛选页面候选。
            for index in slots:
                agents[index] = "Free"
                if row is not None:
                    row[index] = "Free"
            snapshot = self.get_dorm_candidates(agents, room=room)
        finally:
            agents[:] = original
            if row is not None:
                row[:] = original_row
        takeovers = {}
        if task.type == TaskTypes.NOT_SPECIFIC and room in getattr(
            task, "dorm_fill_plan", {}
        ):
            recovering = set(snapshot.recovering) | set(snapshot.estimated_recovering)
            for bed in self.op_data.dorm:
                bed_room, index = bed.position
                if (
                    bed_room == room
                    and index in slots
                    and bed.name
                    and original[index] in recovering
                ):
                    takeovers[index] = bed
        if not snapshot.recovering and not takeovers:
            return None
        candidates = snapshot.filling
        self.switch_arrange_order("心情", room, True, refresh=False)
        self.swipe_left(1, "ALL")
        _, page = self.scan_agent([], full_scan=True)
        self.observe_agent_moods(
            page, candidates, self.op_data.dorm_mood_estimates, False
        )
        observed = []
        for name, _ in page:
            if name not in candidates or name in observed:
                continue
            mood = dorm_candidate_mood(self.op_data, name)
            if mood is None or mood >= getattr(
                self.op_data.operators.get(name), "upper_limit", 24
            ):
                continue
            if name not in self.op_data.operators:
                self.op_data.add(Operator(name, ""))
            observed.append(name)
        page_names = {name for name, _ in page}
        ranked = sorted(observed, key=lambda name: resting_key(self.op_data, name))
        for index in sorted(slots):
            target = "Free"
            planned = original[index]
            if index in takeovers and (
                planned in observed or planned not in page_names
            ):
                tier = resting_tier(self.op_data, planned)
                preferred = [
                    name
                    for name in ranked
                    if name not in agents and resting_tier(self.op_data, name) < tier
                ]
                preferred.append(planned)
                plan = {**task.plan, room: agents}
                transitions = self._execution_group_transitions(plan)
                target = next(
                    (
                        name
                        for name in preferred
                        if self.op_data._slot_takable(
                            takeovers[index],
                            requester=name,
                            plan=plan,
                            group_transitions=transitions,
                        )
                    ),
                    "Free",
                )
            agents[index] = target
            if row is not None:
                row[index] = target
        return observed

    def _check_workshop_selection_mood(self, name, mood):
        """选择加工干员前复用当前卡片，低心情取消换入，未知沿用入站实读。"""
        from arknights_mower.utils.workshop_automation import workshop_task_snapshot
        from arknights_mower.utils.workshop_limits import workshop_material_block_reason

        if name != self.task.meta_data or mood is None:
            return
        observed_at = datetime.now()
        self.op_data.dorm_mood_estimates[name] = (mood, observed_at)
        mood = int(mood)
        if getattr(self.op_data, "mood_calculation_enabled", False):
            self.op_data.mood_model.observe(name, mood, observed_at)
        snapshot = workshop_task_snapshot(self.task)
        setting = (
            next((item for item in snapshot.settings if item.operator == name), None)
            if snapshot is not None
            else None
        )
        if setting is None:
            raise WorkshopSelectionBlocked("加工配置已更新")
        reason = workshop_material_block_reason(
            name, setting.items, get_inventory_counts(), mood
        )
        if mood < 1 or reason:
            raise WorkshopSelectionBlocked(reason or "心情不足1点")

    def _select_sorted_dorm_targets(self, targets, *, mood_check, mood_estimates):
        if not isinstance(getattr(self.recog, "_img", None), np.ndarray):
            return []
        chosen = []
        visible = set(targets)
        for name in targets:
            if name not in visible:
                continue
            if chosen:
                self.recog.update()
            if self.find("connecting"):
                break
            if self._profession_filter_buttons(stationary_only=True) != (
                ("confirm_blue", 1724, 990),
            ):
                break
            self.require_agent_selection_page()
            page = self.current_search_page(full_scan=True)
            if page is None:
                break
            visible = {candidate for candidate, _ in page.page}
            matches = [scope for candidate, scope in page.page if candidate == name]
            if (
                len(matches) != 1
                or matches[0][1][0] > 1790
                or agent_card_selected(page.image, matches[0]) is None
            ):
                break
            hits, _ = self.scan_agent(
                [name],
                observation=page,
                mood_check=mood_check,
                mood_estimates=mood_estimates,
            )
            if not hits:
                break
            chosen.extend(hits)
        return chosen

    def _ranked_first_page_order(
        self,
        room,
        profession,
        target,
        selected,
        page,
        order,
        *,
        profession_page,
        product,
    ):
        """从已确认的排序页选择能容纳目标完整名次区间的排序。"""
        criterion, ascending = order
        if criterion != "技能" and (criterion != "效率" or not product):
            return None
        img = getattr(self.recog, "_img", None)
        if not isinstance(img, np.ndarray) or img.shape != (1080, 1920, 3):
            return None
        visible = self._cards_before_profession_sidebar(page)
        if not visible or not all(
            name
            and abs(scope[0][0] - (630 + i // 2 * 216)) < 30
            and abs(scope[0][1] - (488 + i % 2 * 421)) < 10
            for i, (name, scope) in enumerate(visible)
        ):
            return None
        names = [name for name, _ in visible]
        if len(set(names)) != len(names):
            return None
        available = len(names) - len(selected)
        if available < 1 or set(names[: len(selected)]) != selected:
            return None
        facility = {
            "meeting": "MEETING",
            "contact": "HIRE",
            "recycle": "RECYCLE",
            "factory": "WORKSHOP",
        }.get(room)
        if not facility and room.startswith("room_"):
            facility = next(
                (
                    game_type
                    for title, game_type in (
                        ("manufacture", "MANUFACTURE"),
                        ("trade", "TRADING"),
                        ("power", "POWER"),
                    )
                    if selection_title_matches(img, title)
                ),
                None,
            )
        if not facility:
            return None
        from arknights_mower.utils.selection_skill_rank import (
            selection_efficiency_rank,
            selection_skill_rank,
        )

        def lookup(name, by):
            if by == "技能":
                return selection_skill_rank(facility, profession, name, selected)
            return selection_efficiency_rank(
                facility, profession, name, selected, product=product
            )

        rank = lookup(target, criterion)
        if not rank:
            return None
        choice = order
        if profession_page:
            if rank[ascending][0] <= available:
                return None
            if rank[not ascending][1] <= available:
                choice = (criterion, not ascending)
            elif criterion == "技能" and product:
                efficiency = lookup(target, "效率")
                if not efficiency:
                    return None
                choice = next(
                    (
                        ("效率", direction)
                        for direction in (False, True)
                        if efficiency[direction][1] <= available
                    ),
                    None,
                )
                if choice is None:
                    return None
            else:
                return None
            if branch_filter_state(img, profession) != (False, False) or any(
                agent_profession.get(name) != profession
                for name in names[len(selected) :]
            ):
                return None
            # 已经亮起同一职业时，旧的滚动位置可能保留，需实证列表起点。
            unselected = names[len(selected) :]
            first = lookup(unselected[0], criterion)
            if not first:
                return None
            start, end = first[ascending]
            if start != 1 or end > available:
                return None
            for name in unselected[1:end]:
                member = lookup(name, criterion)
                if not member or member[ascending] != (start, end):
                    return None
        elif rank[ascending][1] > available:
            return None
        if any(
            agent_card_selected(img, scope) is not (name in selected)
            for name, scope in visible
        ):
            return None
        if self.detect_arrange_order(room) != order:
            return None
        self.require_agent_selection_page()
        return choice if station_filter_shows_all(img, self.read_screen) else None

    def _skill_profession_page(self, room, profession, order, selected, page, *, first):
        img = getattr(self.recog, "_img", None)
        if (
            not room.startswith("room_")
            or profession == "ALL"
            or order[0] != "技能"
            or not isinstance(img, np.ndarray)
            or img.shape != (1080, 1920, 3)
            or self.detect_arrange_order(room) != order
            or branch_filter_state(img, profession) != (False, False)
            or self._profession_filter_buttons(stationary_only=True)
            != (("confirm_blue", 1609, 990),)
        ):
            return None
        visible = self._cards_before_profession_sidebar(page)
        names = tuple(name for name, _ in visible)
        if (
            len(names) < 5
            or not all(names)
            or len(set(names)) != len(names)
            or (first and set(names[: len(selected)]) != set(selected))
            or any(
                abs(scope[0][0] - (630 + i // 2 * 216)) > 30
                or abs(scope[0][1] - (488 + i % 2 * 421)) > 10
                or agent_card_selected(img, scope) is not (name in selected)
                or (name not in selected and agent_profession.get(name) != profession)
                for i, (name, scope) in enumerate(visible)
            )
        ):
            return None
        facility = next(
            (
                name
                for name in ("manufacture", "trade", "power")
                if selection_title_matches(img, name)
            ),
            None,
        )
        if not facility:
            return None
        self.require_agent_selection_page()
        # 相同的已识别进驻标题才可复用，名称和坐标不跨选人输入保存。
        label = np.packbits(np.min(img[35:82, 1600:1715], axis=2) > 180).tobytes()
        prefix = names[: len(selected)] if first else tuple(selected)
        return (facility, profession, order, prefix, label), names

    def _remember_skill_successor(self, first, room, page):
        pairs = self.__dict__.get("_profession_search_pages")
        if pairs is None or not first:
            return
        key, left = first
        _, profession, order, selected, _ = key
        second = self._skill_profession_page(
            room, profession, order, selected, page, first=False
        )
        if not second or second[0] != key:
            return
        right = second[1]
        overlap = next(
            (
                n
                for n in range(min(len(left), len(right)) - 1, 1, -1)
                if left[-n:] == right[:n]
            ),
            0,
        )
        if not overlap or not set(left).isdisjoint(right[overlap:]):
            return
        key = (*key, left[-3:])
        if key not in pairs and not station_filter_shows_all(
            self.recog.img, self.read_screen
        ):
            return
        if key not in pairs and len(pairs) >= 24:
            pairs.pop(next(iter(pairs)))
        pairs[key] = left + right[overlap:]

    def _select_visible_profession_target(
        self, room, order, profession, target, selected, observation
    ):
        if observation is None or observation.image is not getattr(
            self.recog, "_img", None
        ):
            return False
        candidate = observation.page
        if self.low_frame_rate_mode:
            page = self.wait_for_agent_page(
                full_scan=False, observation=observation, exclude_sidebar=True
            )
            if not self.same_agent_page(page, candidate):
                return False
        else:
            page = observation.consume(self.recog, full_scan=False, train=False)
            if not page:
                return False
        img = self.recog.img
        self.require_agent_selection_page()
        if (
            self.find("connecting")
            or self.detect_arrange_order(room) != order
            or self._profession_filter_buttons(stationary_only=True)
            != (("confirm_blue", 1609, 990),)
            or branch_filter_state(img, profession) != (False, False)
        ):
            return False
        names = [name for name, _ in page]
        if (
            target not in names
            or len(set(names)) != len(names)
            or set(names[: len(selected)]) != selected
            or any(
                agent_card_selected(img, scope) is not (name in selected)
                or (name not in selected and agent_profession.get(name) != profession)
                for name, scope in page
            )
            or self.recog.img is not img
        ):
            return False
        self._select_named_card(
            target,
            page[names.index(target)][1],
            interval=0.2 if self.low_frame_rate_mode else 0,
        )
        return True

    @timed_step("selection")
    @fixed_selection_profile
    def choose_agent(
        self,
        agents: list[str],
        room: str,
        fast_mode=True,
        train_index=0,
        preserve_dorm_occupants=False,
        choose_error=0,
        dorm_mood_candidates=None,
        recovery_padding=False,
        fresh_room_entry=False,
        two_slot_room=False,
        selection_product=None,
    ) -> bool | None:
        """选择并校验目标名单；无需换人且已放弃暂选时返回 False。"""
        max_swipe = 50
        task = getattr(self, "task", None)
        named_dorm_entry = (
            fresh_room_entry
            and room.startswith("dorm")
            and fast_mode
            and not choose_error
            and not preserve_dorm_occupants
            and not recovery_padding
            and bool(agents)
            and all(name not in ("", "Free", "Current") for name in agents)
            and self._is_ordinary_facility_arrangement(task)
            and getattr(task, "type", None)
            not in (TaskTypes.RE_ORDER, TaskTypes.FILL_DORM, TaskTypes.RELEASE_DORM)
        )
        if getattr(task, "emergency_staffing", False):
            fast_mode = False
        observed_candidates = (
            self.refresh_dorm_selection_candidates(agents, room)
            if not preserve_dorm_occupants and not recovery_padding
            else None
        )
        mood_fallback = (
            self.prepare_dorm_selection(
                agents,
                room,
                preserve_dorm_occupants=preserve_dorm_occupants,
                observed_candidates=observed_candidates or (),
            )
            if dorm_mood_candidates is None or observed_candidates is not None
            else dorm_mood_candidates
        )
        if not preserve_dorm_occupants:
            self._check_group_shift_targets(agents, room, reason="选人前恢复原任务目标")
        fallback_selected = []
        padding_selected = []
        selection_mood_check = (
            self._check_workshop_selection_mood
            if room == "factory"
            and task is not None
            and task.type == TaskTypes.WORKSHOP
            and not task.plan
            and getattr(self, "_workshop_selection_target", None) == task.meta_data
            and task.meta_data in agents
            else None
        )
        if (
            room.startswith("dorm")
            and not preserve_dorm_occupants
            and not recovery_padding
            and getattr(task, "type", None) != TaskTypes.FIAMMETTA
        ):
            selection_mood_check = self._dorm_entry_mood_check(agents, room)
        # Free 已尝试满心情和未登记空闲者兜底，明确留空的位置不参与选人。
        room_targets = agents
        occupied_slots = [index for index, name in enumerate(agents) if name]
        if "" in agents:
            fast_mode = False
            agents = [item for item in agents if item != ""]

        def fill_free(name):
            index = agents.index("Free")
            agents[index] = name
            room_targets[occupied_slots[index]] = name

        agent = copy.deepcopy(agents)
        exists = []
        if fast_mode:
            current_room = self.op_data.get_current_room(room, True)
        is_dorm = room.startswith("dorm")
        default_order = ("心情", True) if is_dorm else ("工作状态", False)

        def name_search_order(name):
            if not name or name in ("Current", "Free"):
                return default_order
            _, (criterion, ascending) = self.get_order(name)
            if is_dorm and not (
                name in self.op_data.operators
                and self.op_data.operators[name].room.startswith("dormitory")
            ):
                return "心情", True
            if criterion == "信赖值":
                return default_order
            if isinstance(ascending, str):
                ascending = ascending == "true"
            return criterion, ascending

        entry_order = search_order = self.detect_arrange_order(room)
        assistant_page = None
        if (
            room == "train"
            and train_index == 0
            and fast_mode
            and not choose_error
            and len(agents) == 1
            and agents[0] not in ("", "Current", "Free")
            and current_room
            and not current_room[0]
            and agents[0] not in current_room
            and search_order is not None
            and search_order[0] != "信赖值"
            and isinstance(getattr(self.recog, "_img", None), np.ndarray)
        ):
            buttons = self._profession_filter_buttons(stationary_only=True)
            if len(buttons) == 1 and buttons[0][0] == "confirm_blue":
                page = self.current_search_page(full_scan=buttons[0][1] > 1650)
                if page and sum(name == agents[0] for name, _ in page.page) == 1:
                    self.require_agent_selection_page()
                    assistant_page = page
        entry_frame = getattr(self.recog, "_img", None) if fresh_room_entry else None
        if search_order is None or search_order[0] == "信赖值":
            entry_frame = None
            # 信赖排序用百分比覆盖姓名。差量撤人、识别卡片及读序号前先恢复姓名。
            wanted = next(
                (name for name in agents if name not in ("", "Current", "Free")), None
            )
            search_order = default_order if is_dorm else name_search_order(wanted)
            self.switch_arrange_order(
                search_order[0], room, search_order[1], refresh=False
            )
        sidebar_covers_cards = False
        dorm_scopes = {}
        if assistant_page is not None:
            sidebar_covers_cards = not assistant_page.full_scan
        elif (
            named_dorm_entry
            and fast_mode
            and not mood_fallback
            and "Free" not in agents
            and isinstance(entry_frame, np.ndarray)
            and self._profession_filter_buttons(stationary_only=True)
            == (("confirm_blue", 1609, 990),)
            and [
                label
                for i, label in enumerate(self.profession_labels)
                if self._profession_highlighted((1918, 135 + 110 * i))
            ]
            == ["ALL"]
        ):
            self.require_agent_selection_page()
            sidebar_covers_cards = True
        elif fresh_room_entry and not is_dorm and agents and "Free" not in agents:
            confirm = self.find("confirm_blue")
            if not confirm:
                entry_frame = None
            sidebar_covers_cards = not confirm or confirm[0][0] <= 1650
            if not room.startswith("room") and not (
                confirm
                and sidebar_covers_cards
                and self._profession_highlighted((1918, 135))
            ):
                self.profession_filter()
                sidebar_covers_cards = False
        else:
            self.profession_filter()
        if fast_mode:
            if room.startswith("dorm"):
                # 缓存只提供名单，差量取消必须使用页面实际卡片顺序。
                # 意外入住或缺人时完整重选，不能把错人当作原宿管保留。
                residents = [n for n in current_room if n]
                if sidebar_covers_cards:
                    try:
                        current_room = self.wait_for_arranged_agents(
                            residents,
                            ordered=False,
                            full_scan=False,
                            visible_only=True,
                            card_scopes=dorm_scopes,
                        )
                    except AgentSelectionPageChanged:
                        raise
                    except AgentSelectionNotReady:
                        current_room = None
                    if current_room is None or any(
                        not (scope := dorm_scopes.get(name)) or scope[1][0] > 1790
                        for name in residents
                    ):
                        self.profession_filter()
                        sidebar_covers_cards = False
                if not sidebar_covers_cards:
                    try:
                        current_room = self.wait_for_arranged_agents(
                            residents, ordered=False
                        )
                    except AgentSelectionPageChanged:
                        raise
                    except AgentSelectionNotReady:
                        current_room = None
                if current_room is None:
                    logger.info(f"{room} 实际已选名单与缓存不一致，改为完整选人")
                    fast_mode = False
                    current_room = []
            # 如果空位置进房间会被向前挤
            # 训练室的协助位和训练位固定，空协助位不能让训练位前移。
            if room != "train":
                current_room = sorted(current_room, key=lambda x: x == "")
            differences = []
            for i in range(len(current_room)):
                if current_room[i] not in agents:
                    differences.append(i)
                else:
                    exists.append(current_room[i])
            if room == "train":
                differences = [x for x in differences if x == train_index]
            differences = [pos for pos in differences if current_room[pos]]
            if differences and is_dorm and sidebar_covers_cards:
                points = [dorm_scopes[current_room[pos]] for pos in differences]
            elif differences and fresh_room_entry and room.startswith("room"):
                scopes = {}
                residents = [name for name in current_room if name]
                actual = self.wait_for_arranged_agents(
                    residents,
                    ordered=False,
                    full_scan=not sidebar_covers_cards,
                    visible_only=True,
                    card_scopes=scopes,
                )
                points = [scopes.get(current_room[pos]) for pos in differences]
                if actual is None or any(
                    scope is None or (sidebar_covers_cards and scope[1][0] > 1790)
                    for scope in points
                ):
                    fast_mode = False
                    exists.clear()
                    points = []
            else:
                points = [
                    (
                        self.recog.w * self.agent_selection_positions[pos][0],
                        self.recog.h * self.agent_selection_positions[pos][1],
                    )
                    for pos in differences
                ]
            for point in points:
                entry_frame = None
                self.tap(point, interval=0.2 if self.low_frame_rate_mode else 0)
            agent = [x for x in agents if x not in exists]
        room_name = self.translate_room(room)
        if agent:
            logger.info(
                f"安排干员：{'、'.join(agent)} → {room_name}",
                extra={"log_room": room, "log_agents": list(agent)},
            )
        else:
            logger.debug(f"{room_name} 没有需要新安排的干员")
        production = room.startswith("room")
        search_branches = bool(self.op_data.profession_filter)
        first_time = True
        free_num = agent.count("Free")
        agent = [name for name in agent if name != "Free"]
        right_swipe = 0
        logger.debug(f"上次进入房间为：{self.last_room},本次房间为：{room}")
        if not agents and not fast_mode:
            self.clear_agent_selection(room)
        last_special_filter = "ALL"
        observation = assistant_page
        previous_page = None
        last_scanned_page = ()
        profession_pages = (
            self.__dict__.get("_profession_search_pages") if production else None
        )
        pending_skill_page = None
        exhausted_filters = set()
        tried_branches = set()
        probed_pages = set()
        ranked_targets = set()
        active_branch = None
        station_filter_recovered = False

        def target_profession(name):
            profession = agent_profession.get(name)
            if (
                name == "阿米娅"
                or (production and not search_branches)
                or profession not in self.profession_labels
                or profession in exhausted_filters
            ):
                return "ALL"
            return profession

        def uses_tail_search(name):
            return (
                not self.low_frame_rate_mode
                and fast_mode
                and is_dorm
                and target_profession(name) != "ALL"
                and name in self.op_data.operators
                and self.op_data.operators[name].is_resting()
                and name not in self.choose_error
            )

        def set_search_profession(
            profession, *, clear_branch=False, visible_target=None
        ):
            nonlocal last_special_filter, sidebar_covers_cards, active_branch
            nonlocal right_swipe, observation, previous_page, pending_skill_page
            pending_skill_page = None
            if clear_branch and profession != "ALL":
                self.profession_filter("ALL")
            self.profession_filter(profession)
            last_special_filter = profession
            sidebar_covers_cards = True
            active_branch = None
            right_swipe = 0
            previous_page = observation = None
            if profession != "ALL":
                observation = self.current_search_page(
                    full_scan=False,
                    before=last_scanned_page,
                    profession=profession,
                    visible_target=visible_target,
                )

        def broaden_search(target):
            profession = last_special_filter
            if active_branch:
                logger.debug(f"{active_branch}分支未找到{target}，返回职业列表继续查找")
                set_search_profession(profession, clear_branch=True)
            else:
                logger.debug(f"{profession}筛选未找到{target}，改用全部职业继续查找")
                exhausted_filters.add(profession)
                set_search_profession("ALL")

        def recover_unreadable_filter(target):
            if not search_branches or last_special_filter == "ALL":
                return False
            self.require_agent_selection_page()
            if not self.find("confirm_blue") and not (
                room == "train" and self.find("confirm_train")
            ):
                return False
            broaden_search(target)
            return True

        def recover_station_filter(restrictions):
            nonlocal station_filter_recovered, right_swipe, observation, previous_page
            if station_filter_recovered:
                return False
            self.recog.update()
            self.require_agent_selection_page()
            if not self.find("confirm_blue"):
                return False
            try:
                current = self.agent_station_filter()
            except AgentSelectionPageChanged:
                raise
            except AgentSelectionNotReady:
                return False
            if current not in restrictions:
                return False
            self.agent_station_filter("全部")
            station_filter_recovered = True
            previous_page = observation = None
            if right_swipe or not fresh_room_entry:
                right_swipe, observation = self.swipe_left(1, "ALL", return_page=True)
            logger.debug(f"已解除进驻筛选“{current}”，继续查找{agent}")
            return True

        named_slots = (
            {name: slot for slot, name in enumerate(agents)}
            if production and len(agent) > 1
            else None
        )

        def scan_named():
            nonlocal last_scanned_page, pending_skill_page
            first, pending_skill_page = pending_skill_page, None
            chosen, last_scanned_page = self.scan_agent(
                agent,
                full_scan=not sidebar_covers_cards,
                exclude_sidebar=sidebar_covers_cards,
                target_slots=named_slots,
                observation=observation,
                mood_check=selection_mood_check,
                mood_estimates=self.op_data.dorm_mood_estimates
                if is_dorm and preserve_dorm_occupants
                else None,
            )
            if first:
                self._remember_skill_successor(first, room, last_scanned_page)
            return chosen, last_scanned_page

        def swipe_search_page(page, *, full_scan, first=None):
            nonlocal pending_skill_page
            pending_skill_page = None
            if (
                first is None
                and profession_pages is not None
                and not active_branch
                and last_special_filter != "ALL"
                and right_swipe == 0
                and search_order[0] == "技能"
                and self._is_ordinary_facility_arrangement(task)
            ):
                selected = set(agents) - set(agent) - {"", "Free", "Current"}
                first = self._skill_profession_page(
                    room, last_special_filter, search_order, selected, page, first=True
                )
            moved, after = self.swipe_agent_page(
                page, agent, full_scan=full_scan, return_page=True
            )
            if first and moved == 1:
                if after and after.page:
                    self._remember_skill_successor(first, room, after.page)
                else:
                    pending_skill_page = first
            return moved, after

        if agent:
            if not fast_mode:
                self.clear_agent_selection(room)
            elif (
                production
                and entry_frame is not None
                and entry_frame is getattr(self.recog, "_img", None)
            ):
                observation = self.current_search_page(
                    full_scan=not sidebar_covers_cards
                )
            try:
                scan_named()
            except AgentCardObservationNotReady:
                if not (is_dorm and sidebar_covers_cards):
                    raise
                self.require_agent_selection_page()
            observation = None
            if is_dorm and sidebar_covers_cards and agent:
                # 右栏外仍可能有目标；按原有全宽名单重新定位后再切职业。
                self.profession_filter()
                sidebar_covers_cards = False
                scan_named()
                observation = None
            if assistant_page is not None and agent:
                self.profession_filter()
                sidebar_covers_cards = False
                assistant_page = None
            if (
                production
                and any(
                    (op := self.op_data.operators.get(name)) is not None
                    and getattr(op, "current_room", "") not in ("", room)
                    and getattr(op, "current_index", -1) >= 0
                    for name in agent
                )
                and recover_station_filter(("未进驻",))
            ):
                scan_named()
                observation = None
        while agent:
            if uses_tail_search(agent[0]):
                # 同职业先顺路找普通目标，再跳末页。
                profession = target_profession(agent[0])
                for index, name in enumerate(agent[1:], 1):
                    if target_profession(name) == profession and not uses_tail_search(
                        name
                    ):
                        agent.insert(0, agent.pop(index))
                        break

            target = agent[0]
            profession = target_profession(target)
            tail_search = uses_tail_search(target)
            branch = (
                agent_branch.get(target)
                if search_branches and profession != "ALL" and not tail_search
                else None
            )
            if active_branch and (
                branch != active_branch or profession != last_special_filter
            ):
                set_search_profession(
                    profession, clear_branch=profession == last_special_filter
                )
            order = name_search_order(target)
            use_rank = (
                (production or room in ("meeting", "contact", "recycle", "factory"))
                and search_branches
                and profession != "ALL"
                and not active_branch
                and not choose_error
                and not getattr(task, "emergency_staffing", False)
                and target not in ranked_targets
                and (fresh_room_entry or fast_mode)
                and right_swipe == 0
            )
            selected = set(agents) - set(agent) - {"", "Free", "Current"}
            if (
                use_rank
                and order != search_order
                and profession != last_special_filter
                and self._ranked_first_page_order(
                    room,
                    profession,
                    target,
                    selected,
                    last_scanned_page,
                    search_order,
                    profession_page=False,
                    product=selection_product,
                )
            ):
                ranked_targets.add(target)
                previous_filter = last_special_filter
                try:
                    set_search_profession(profession)
                except AgentSelectionPageChanged:
                    raise
                except AgentSelectionNotReady:
                    self.require_agent_selection_page()
                    set_search_profession(previous_filter)
                else:
                    try:
                        changed, _ = scan_named()
                    except AgentCardObservationNotReady:
                        self.require_agent_selection_page()
                        changed = target not in agent
                    observation = None
                    if changed:
                        continue
            if not active_branch and search_order != order:
                prefiltered = (
                    production
                    and fresh_room_entry
                    and fast_mode
                    and first_time
                    and not choose_error
                    and self._is_ordinary_facility_arrangement(task)
                    and last_special_filter == "ALL"
                    and profession != "ALL"
                    and target in self.op_data.profession_filter
                    and search_order == entry_order
                    and search_order[0] in ("工作状态", "心情")
                    and isinstance(getattr(self.recog, "_img", None), np.ndarray)
                )
                if prefiltered:
                    # 配置要求切到此职业。先看原排序同一页的实名卡，再决定是否改排序。
                    try:
                        set_search_profession(profession, visible_target=target)
                        visible = (
                            {name for name, _ in observation.page}
                            if observation
                            else set()
                        )
                        found = self._select_visible_profession_target(
                            room,
                            search_order,
                            profession,
                            target,
                            selected,
                            observation,
                        )
                    except AgentSelectionPageChanged:
                        raise
                    except AgentSelectionNotReady:
                        self.require_agent_selection_page()
                        if last_special_filter != profession:
                            set_search_profession("ALL")
                            prefiltered = False
                    else:
                        if found:
                            agent.remove(target)
                            first_time = False
                            observation = None
                            if visible.intersection(agent):
                                try:
                                    scan_named()
                                except AgentCardObservationNotReady:
                                    self.require_agent_selection_page()
                            continue
                    if prefiltered and branch_filter_state(
                        getattr(self.recog, "_img", None), profession
                    ) != (False, False):
                        last_special_filter = None
                self.switch_arrange_order(order[0], room, order[1], refresh=False)
                search_order = order
                previous_page = observation = None
                if production and target not in self.op_data.profession_filter:
                    # 切换排序后先选可见目标，配置了职业筛选的干员直接进入对应职业。
                    changed, _ = scan_named()
                    if changed:
                        first_time = False
                        continue
                elif (
                    is_dorm
                    and fast_mode
                    and not choose_error
                    and target not in self.choose_error
                    and not self.low_frame_rate_mode
                    and last_special_filter == "ALL"
                    and profession != "ALL"
                    and not sidebar_covers_cards
                ):
                    chosen = self._select_sorted_dorm_targets(
                        [
                            name
                            for name in agent
                            if name not in self.choose_error
                            and target_profession(name) == profession
                        ],
                        mood_check=selection_mood_check,
                        mood_estimates=self.op_data.dorm_mood_estimates
                        if preserve_dorm_occupants
                        else None,
                    )
                    if chosen:
                        for name in chosen:
                            agent.remove(name)
                        first_time = False
                        continue
                if profession == last_special_filter and not prefiltered:
                    right_swipe, observation = self.swipe_left(
                        right_swipe, last_special_filter, return_page=True
                    )
            first_time = False
            if profession != last_special_filter:
                set_search_profession(profession)

            if tail_search:
                # 低帧率设备逐页确认，普通设备保留休息干员的末页快路。
                swipe_map = [20, 3, 5, 3, 3, 3, 3, 3, 3]
                right_swipe = swipe_map[self.profession_labels.index(profession)]
                for _ in range(right_swipe):
                    self.swipe_noinertia(
                        (0.8 * self.recog.w, 0.5 * self.recog.h), (-1900, 0), interval=0
                    )
                observation = None
                self.sleep(0.5 if self.performance_profile.mode == "high" else 1)
            try:
                changed, ret = scan_named()
            except AgentCardObservationNotReady:
                if recover_unreadable_filter(target):
                    continue
                raise
            observation = None
            if tail_search and target in agent:
                self.choose_error.add(target)
                right_swipe, observation = self.swipe_left(
                    right_swipe, last_special_filter, return_page=True
                )
                previous_page = None
                continue
            if changed:
                if production and profession != "ALL":
                    agent.sort(
                        key=lambda name: (
                            target_profession(name) != profession,
                            bool(active_branch)
                            and agent_branch.get(name) != active_branch,
                        )
                    )
                continue
            if (
                use_rank
                and target not in ranked_targets
                and (
                    ranked_order := self._ranked_first_page_order(
                        room,
                        profession,
                        target,
                        selected,
                        ret,
                        search_order,
                        profession_page=True,
                        product=selection_product,
                    )
                )
            ):
                ranked_targets.add(target)
                criterion, ascending = ranked_order
                logger.debug(
                    f"{room} {profession} 按{criterion}{'升序' if ascending else '降序'}首屏查找{target}"
                )
                try:
                    self.switch_arrange_order(criterion, room, ascending, refresh=False)
                    page = self.wait_for_agent_page(
                        full_scan=False, before=ret, exclude_sidebar=True
                    )
                except AgentSelectionPageChanged:
                    raise
                except AgentSelectionNotReady:
                    page = ()
                stable_image = self.recog.img if page else None
                target_scopes = [scope for name, scope in page if name == target]
                self.require_agent_selection_page()
                if (
                    len(target_scopes) == 1
                    and self.detect_arrange_order(room) == ranked_order
                    and branch_filter_state(self.recog.img, profession)
                    == (False, False)
                    and target
                    in self.observe_agent_moods(
                        page, [target], None, False, mood_check=selection_mood_check
                    )
                    and self.recog.img is stable_image
                ):
                    try:
                        self._select_named_card(
                            target,
                            target_scopes[0],
                            interval=0.2 if self.low_frame_rate_mode else 0,
                        )
                    except AgentCardObservationNotReady:
                        self.require_agent_selection_page()
                    else:
                        search_order = ranked_order
                        agent.remove(target)
                        continue
                self.switch_arrange_order(
                    search_order[0], room, search_order[1], refresh=False
                )
                observation = previous_page = None
                continue
            if (
                isinstance(branch, str)
                and branch
                and not active_branch
                and not choose_error
                and (right_swipe == 0 or (profession, branch) in probed_pages)
                and (profession, branch) not in tried_branches
            ):
                first = None
                probe = False
                if (
                    (profession, branch) not in probed_pages
                    and right_swipe == 0
                    and search_order[0] == "技能"
                    and profession_pages
                    and self._is_ordinary_facility_arrangement(task)
                ):
                    tail = tuple(name for name, _ in ret[-3:])
                    if any(
                        key[1] == profession
                        and key[2] == search_order
                        and set(key[3]) == selected
                        and key[-1] == tail
                        and self.next_page_may_contain(ret, history, target)
                        for key, history in profession_pages.items()
                    ):
                        first = self._skill_profession_page(
                            room, profession, search_order, selected, ret, first=True
                        )
                        probe = first is not None and self.next_page_may_contain(
                            ret, profession_pages.get((*first[0], tail), ()), target
                        )
                if probe:
                    probed_pages.add((profession, branch))
                    try:
                        moved, observation = swipe_search_page(
                            ret, full_scan=False, first=first
                        )
                    except (AgentPageNotAdvanced, AgentCardObservationNotReady):
                        self.require_agent_selection_page()
                    else:
                        right_swipe += moved
                        continue
                tried_branches.add((profession, branch))
                if select_visible_branch(self, profession, branch):
                    active_branch = branch
                    right_swipe = 0
                    sidebar_covers_cards = True
                    previous_page = None
                    observation = self.current_search_page(
                        full_scan=False,
                        before=ret,
                        profession=profession,
                        branch=branch,
                    )
                else:
                    set_search_profession(profession, clear_branch=True)
                continue
            try:
                if right_swipe >= max_swipe or (
                    not self.low_frame_rate_mode
                    and right_swipe >= 3
                    and ret == previous_page
                ):
                    raise AgentPageNotAdvanced("干员列表已到末尾，返回房间重试")
                previous_page = ret
                moved, observation = swipe_search_page(
                    ret, full_scan=not sidebar_covers_cards
                )
                right_swipe += moved
            except AgentCardObservationNotReady:
                if recover_unreadable_filter(target):
                    continue
                raise
            except AgentPageNotAdvanced:
                if sidebar_covers_cards or (search_branches and profession != "ALL"):
                    self.require_agent_selection_page()
                if sidebar_covers_cards:
                    self._close_profession_filter()
                    sidebar_covers_cards = False
                    try:
                        changed, _ = scan_named()
                    except AgentCardObservationNotReady:
                        if recover_unreadable_filter(target):
                            continue
                        raise
                    if changed:
                        continue
                if search_branches and profession != "ALL":
                    broaden_search(target)
                    continue
                if production and recover_station_filter(("未进驻", "宿舍锁定")):
                    continue
                self.choose_error.add(target)
                if choose_error >= 2 and room == "train":
                    logger.warning(
                        f"训练位干员列表中未找到{target}，请检查特别关注设置"
                    )
                raise

        if free_num and recovery_padding:
            from arknights_mower.utils.dorm_skills import is_single_recovery_manager

            self.profession_filter("ALL")
            last_special_filter = "ALL"
            right_swipe = self.swipe_left(right_swipe, last_special_filter)
            self.switch_arrange_order("心情", room, False)
            candidates = [
                name
                for name in self.get_dorm_candidates(agents, room=room).filling
                if not getattr(self.op_data.operators.get(name), "current_room", "")
                and not is_single_recovery_manager(name)
            ]
            estimates = self.op_data.dorm_mood_estimates
            observation = None
            for page_index in range(max_swipe + 1):
                if not candidates:
                    raise DormRecoveryPaddingUnavailable()
                chosen, page = self.scan_agent(
                    candidates.copy(),
                    max_agent_count=free_num,
                    observation=observation,
                    mood_estimates=estimates,
                    require_full_mood=True,
                    mood_check=self._allow_dorm_filler_mood,
                )
                padding_selected.extend(chosen)
                for name in chosen:
                    fill_free(name)
                    candidates.remove(name)
                free_num -= len(chosen)
                if not free_num:
                    break
                # 降序页面出现合格黄脸后，后续没有满心情者可补足垫位。
                if page_index == max_swipe or any(
                    name in candidates
                    and (estimate := estimates.get(name)) is not None
                    and estimate[0] < 24
                    for name, _ in page
                ):
                    raise DormRecoveryPaddingUnavailable()
                try:
                    moved, observation = self.swipe_agent_page(
                        page, candidates, return_page=True
                    )
                    right_swipe += moved
                except AgentSelectionPageChanged:
                    raise
                except AgentSelectionNotReady:
                    raise DormRecoveryPaddingUnavailable() from None

        # 安排空闲干员
        if free_num:
            if free_num == len(agents):
                self.clear_agent_selection(room)
            if last_special_filter != "ALL":
                # Free 搜索的目标就是 ALL；真实切换本身会复位列表，
                # 无需先恢复原职业再切一次 ALL。
                self.profession_filter("ALL")
                last_special_filter = "ALL"
                right_swipe = 0
            elif not first_time:
                right_swipe = self.swipe_left(right_swipe, last_special_filter)
            self.switch_arrange_order("心情", room, "true")
            # 满心情兜底按游戏心情顺序选人，普通补床仍遵守宿舍层级。
            free_list = (
                list(mood_fallback)
                if mood_fallback
                else self.get_free_list(agents, room=room)
            )
            idle_fallback = not free_list
            if idle_fallback:
                free_list = self.get_free_list(agents, include_full=True, room=room)
            if mood_fallback or idle_fallback:
                right_swipe = self.swipe_left(right_swipe, last_special_filter)
            selection_time = datetime.now()
            estimates = getattr(self.op_data, "dorm_mood_estimates", None)
            # 有可保留的实读满心情住客时，先筛选低心情卡片，避免满员试住。
            resident_names = list(getattr(self.task, "dorm_mood_residents", ()))
            if self.task is not None and self.task.type == TaskTypes.RELEASE_DORM:
                resident_names.extend(self.task.meta_data.split(","))
            retainable = [
                name
                for name in dict.fromkeys(resident_names)
                if name in free_list
                and (op := self.op_data.operators.get(name)) is not None
                and op.current_room == room
                and has_resting_mood(op)
                and resting_mood(op) >= op.upper_limit
                and not self.op_data.has_rest_mood_limit(name)
            ]
            screening = bool(
                mood_fallback and estimates is not None and len(retainable) >= free_num
            )
            rejected = set()

            def allow_free_card(name, mood):
                if self._allow_dorm_filler_mood(name, mood):
                    return True
                rejected.add(name)
                return False

            observation = None
            previous_page = None
            while free_num:
                if room.startswith("dorm"):
                    capacity_plan = dict(getattr(self.task, "plan", {}) or {})
                    capacity_plan[room] = room_targets
                    bed_position = (room, occupied_slots[agents.index("Free")])
                    free_list = [
                        name
                        for name in free_list
                        if name not in rejected
                        and self.op_data.dorm_capacity_allows(
                            name,
                            bed_position,
                            plan=capacity_plan,
                            group_transitions=getattr(
                                self.task, "group_shift_transitions", {}
                            ),
                        )
                    ]
                    if not free_list and not idle_fallback:
                        idle_fallback = True
                        free_list = self.get_free_list(
                            agents, include_full=True, room=room
                        )
                        right_swipe = self.swipe_left(right_swipe, last_special_filter)
                        observation, previous_page = None, None
                        continue
                if not free_list or right_swipe > max_swipe:
                    raise Exception("没有找到足够的可用宿舍候选干员")
                # scan_agent 按屏幕顺序点击，单纯排序名单不能保证层级和心情顺序。
                # 一次只允许选择当前最高优先级、最低已知心情的候选。
                if not (mood_fallback or idle_fallback):
                    first_key = resting_key(self.op_data, free_list[0], selection_time)
                    candidates = [
                        name
                        for name in free_list
                        if resting_key(self.op_data, name, selection_time) == first_key
                    ]
                else:
                    candidates = (
                        list(free_list) if mood_fallback or idle_fallback else free_list
                    )
                crafting = set(crafting_rest_candidates(self.op_data, free_list))
                if crafting:
                    boundary = next(
                        i for i, name in enumerate(free_list) if name in crafting
                    )
                    permitted = set(free_list[:boundary] if boundary else free_list[:1])
                    candidates = [name for name in candidates if name in permitted]
                selected_name, ret = self.scan_agent(
                    candidates,
                    max_agent_count=1
                    if room.startswith("dorm")
                    and any(
                        resting_tier(self.op_data, name)
                        <= RestingTier.PRIORITY_REPLACEMENT
                        for name in candidates
                    )
                    else free_num,
                    full_scan=last_special_filter == "ALL",
                    observation=observation,
                    mood_estimates=estimates,
                    skip_full_mood=screening,
                    mood_check=allow_free_card if is_dorm else None,
                )
                observation = None
                if screening and not selected_name:
                    visible = [name for name, _ in ret if name in candidates]
                    # 心情升序的首个合格候选已是满条，其后的候选不必逐个试住。
                    if (
                        visible
                        and (estimate := estimates.get(visible[0])) is not None
                        and estimate[0] >= 24
                    ):
                        self.op_data.stop_idle_dorm_search()
                        resolved = agents.copy()
                        for index, name in enumerate(resolved):
                            current = self.op_data.get_current_operator(
                                room, occupied_slots[index]
                            )
                            if (
                                name == "Free"
                                and current is not None
                                and current.name in retainable
                                and current.name in free_list
                                and current.name not in resolved
                            ):
                                resolved[index] = current.name
                        actual_room = self.op_data.get_current_room(room, True)
                        retained = room_targets.copy()
                        for slot, name in zip(occupied_slots, resolved):
                            retained[slot] = name
                        if retained == actual_room:
                            agents[:] = resolved
                            room_targets[:] = retained
                            self._cancel_unchanged_dorm_selection()
                            pending = getattr(self.task, "idle_dorm_search_names", {})
                            pending.setdefault(room, set()).update(retainable)
                            self.task.idle_dorm_search_names = pending
                            logger.info("候选均已满心情，放弃暂选并保留原驻员")
                            return False
                        # 同房仍需换人时直接选当前页的合格候选，不再找回原住者。
                        screening = False
                        continue
                if mood_fallback or idle_fallback:
                    fallback_selected.extend(selected_name)
                free_num -= len(selected_name)
                changed = bool(selected_name)
                while len(selected_name) > 0:
                    fill_free(selected_name[0])
                    free_list.remove(selected_name[0])
                    selected_name.remove(selected_name[0])
                if free_num == 0:
                    break
                elif changed or rejected.intersection(candidates):
                    right_swipe = self.swipe_left(right_swipe, last_special_filter)
                else:
                    if right_swipe >= max_swipe:
                        raise AgentSelectionNotReady(
                            "空闲干员搜索达到上限，返回房间重试"
                        )
                    if (
                        not self.low_frame_rate_mode
                        and right_swipe >= 3
                        and ret == previous_page
                    ):
                        raise AgentSelectionNotReady(
                            "空闲干员列表已到末尾，返回房间重试"
                        )
                    previous_page = ret
                    moved, observation = self.swipe_agent_page(
                        ret,
                        free_list,
                        full_scan=last_special_filter == "ALL",
                        return_page=True,
                    )
                    right_swipe += moved
        if not preserve_dorm_occupants and self._check_group_shift_targets(
            room_targets, room, reason="选人页最终名单与 Free 解析"
        ):
            # 页面已经选择过兜底人员，恢复名单后必须实际清空重选再校验。
            return self.choose_agent(
                room_targets,
                room,
                fast_mode=False,
                train_index=train_index,
                choose_error=choose_error,
                dorm_mood_candidates=mood_fallback,
                recovery_padding=recovery_padding,
            )
        if room != "train" and not recovery_padding:
            # 单个训练岗位和单回临时阵容不替换房间的完整目标。
            self._update_facility_arrangement_log(room, agents)
        verified = False
        if len(agents) == 1 and (
            room in ("factory", "contact")
            or (room == "train" and train_index == 0)
            or (production and selection_shows_power_plant(self.recog.img))
        ):
            # 发电站须在蓝框校验的同一帧仍能读出标题，房间配置不能证明实际容量。
            verified = (
                self.wait_for_arranged_agents(
                    agents, full_scan=False, visible_only=True
                )
                == agents
            ) and (not production or selection_shows_power_plant(self.recog.img))
        # 重排按完整已选名单的位置点击，不能保留最后一名干员的职业筛选。
        # 单回暂留名单没有 Free，也必须在重排和校验前恢复全部职业。
        if not verified and assistant_page is not None:
            self.profession_filter()
        elif not verified and last_special_filter != "ALL":
            self.profession_filter("ALL")
            last_special_filter = "ALL"
            right_swipe = 0
        # 排序
        reordered = False
        slot_numbers = {}
        target_slots = {name: slot for slot, name in enumerate(agents, 1)}
        full_room = (
            (production and (len(agents) == 3 or (two_slot_room and len(agents) == 2)))
            or ((is_dorm or room == "central") and len(agents) == 5)
            or (room in ("meeting", "recycle") and len(agents) == 2)
        )
        if fresh_room_entry and full_room and not right_swipe:
            card_scopes = {}
            self.wait_for_arranged_agents(
                agents,
                ordered=False,
                full_scan=False,
                slot_numbers=slot_numbers,
                visible_only=True,
                card_scopes=card_scopes,
            )
            verified = slot_numbers == target_slots
            if (
                not verified
                and slot_numbers.keys() == target_slots.keys()
                and set(slot_numbers.values()) == set(target_slots.values())
            ):
                ordered = sorted(slot_numbers, key=slot_numbers.get)
                retained = 0
                for name in ordered:
                    if name == agents[retained]:
                        retained += 1
                suffix = [card_scopes.get(name) for name in agents[retained:]]
                if all(scope is not None and scope[1][0] <= 1790 for scope in suffix):
                    if len(suffix) * 2 < len(agents) + 1:
                        for scope in suffix:
                            self.tap_reorder_card(scope)
                        verified = self.fill_visible_selection_suffix(
                            agents, retained, wait_for_feedback=True
                        )
                    else:
                        self.reorder_selected_agents(agents, ordered)
                        numbers = {}
                        self.wait_for_arranged_agents(
                            agents,
                            ordered=False,
                            full_scan=False,
                            slot_numbers=numbers,
                            visible_only=True,
                            quick_check=False,
                        )
                        verified = numbers == target_slots
                    if not verified:
                        self.require_agent_selection_page()
                        return self.choose_agent(
                            room_targets,
                            room,
                            fast_mode=False,
                            train_index=train_index,
                            preserve_dorm_occupants=preserve_dorm_occupants,
                            choose_error=choose_error,
                            dorm_mood_candidates=mood_fallback,
                            recovery_padding=recovery_padding,
                            two_slot_room=two_slot_room,
                        )
        if len(agents) != 1 and not verified:
            self.switch_arrange_order("技能", room)
            # 未翻页时先定位目标卡片，名字匹配后无需再切筛选复位。
            exists = None
            slot_numbers.clear()
            if right_swipe == 0:
                can_fill_last = (
                    fresh_room_entry and fast_mode and production and full_room
                )
                try:
                    exists = self.wait_for_arranged_agents(
                        agents,
                        ordered=False,
                        slot_numbers=slot_numbers,
                        quick_check=can_fill_last,
                    )
                except AgentSelectionPageChanged:
                    raise
                except AgentSelectionNotReady:
                    logger.debug("当前已选名单尚不能确认，筛选复位后再校验")
                if (
                    exists is None
                    and can_fill_last
                    and self.fill_visible_selection_suffix(agents, len(agents) - 1)
                ):
                    exists = agents.copy()
                    slot_numbers.update(target_slots)
            if exists is None:
                right_swipe, observation = self.swipe_left(
                    right_swipe, last_special_filter, return_page=True
                )
                exists = self.wait_for_arranged_agents(
                    agents,
                    ordered=False,
                    observation=observation,
                    slot_numbers=slot_numbers,
                )
            if exists is None:
                if fast_mode and room.startswith("room") and agents:
                    self.require_agent_selection_page()
                    logger.info("生产房差量选人名单不符，在当前选人页完整重选一次")
                    return self.choose_agent(
                        room_targets,
                        room,
                        fast_mode=False,
                        train_index=train_index,
                        preserve_dorm_occupants=preserve_dorm_occupants,
                        choose_error=choose_error,
                        dorm_mood_candidates=mood_fallback,
                        recovery_padding=recovery_padding,
                    )
                raise Exception("检测到干员选择错误，重新选择")
            selected_names = (
                "、".join(f"[[operator:{name}]]" for name in exists) or "无干员"
            )
            # 未坐满时，排序过渡帧可能尚有已选卡片留在屏外。
            verified = not agents or (full_room and slot_numbers == target_slots)
            pending = "" if verified else "，待排序核对"
            logger.info(
                f"{facility_label(room, self.op_data)}：选人页当前选中：{selected_names}{pending}",
                extra={"log_room": room, "log_agents": list(exists)},
            )
            # 只有每张已选卡片的序号都符合目标，才能直接确认岗位顺序。
            if not verified:
                self.reorder_selected_agents(agents, exists)
                reordered = True
        if not verified:
            logger.debug("验证干员选择..")
            self.switch_arrange_order("技能", room)
            verify_options = {"ordered": False} if reordered else {}
            if right_swipe == 0:
                try:
                    verified = self.verify_agent(agents, room, **verify_options)
                except AgentSelectionPageChanged:
                    raise
                except AgentSelectionNotReady:
                    logger.debug("当前已选顺序尚不能确认，筛选复位后再校验")
            if verified is False:
                _, observation = self.swipe_left(
                    right_swipe, last_special_filter, return_page=True
                )
                verified = self.verify_agent(
                    agents, room, observation=observation, **verify_options
                )
            if verified is None and reordered:
                self.reorder_selected_agents(agents, exists, confirm_each=True)
                verified = True
        if not verified:
            logger.debug(agents)
            logger.debug(room)
            raise Exception("检测到干员选择错误，重新选择")
        self.last_room = room
        for name in padding_selected:
            if name not in self.op_data.operators:
                self.op_data.add(Operator(name, ""))
        if fallback_selected and self.task is not None:
            # 查找机会由所有宿舍共享，必须等实际读回心情才判定耗尽。
            pending = getattr(self.task, "idle_dorm_search_names", {})
            pending.setdefault(room, set()).update(fallback_selected)
            self.task.idle_dorm_search_names = pending
        for name in fallback_selected:
            if name not in self.op_data.operators:
                self.op_data.add(Operator(name, ""))
            self.op_data.operators[name].dorm_mood_fallback = room
            self.op_data.operators[name].dorm_mood_peers = {
                peer: self.op_data.operators[peer].time_stamp
                for peer in mood_fallback
                if peer != name and peer in self.op_data.operators
            }
            logger.info(f"按心情升序补入{name}；读满后停止连续试住，个人上限仍强制离宿")

    def _cancel_unchanged_dorm_selection(self):
        """放弃未提交的暂选，确认返回房间后再由调用者核对实际驻员。"""
        for _ in range(8):
            self.recog.update()
            scene = self.scene()
            if scene in (Scene.INFRA_DETAILS, Scene.CTRLCENTER_ASSISTANT):
                return
            if scene == Scene.INFRA_ARRANGE_ORDER:
                self.back(interval=0.5)
            elif scene == Scene.INFRA_ARRANGE_CONFIRM:
                self.tap((self.recog.w // 3, self.recog.h - 10), interval=0.5)
            elif scene in self.waiting_scene:
                self.sleep(0.5)
            else:
                raise AgentSelectionNotReady("放弃宿舍暂选时未确认房间界面")
        raise AgentSelectionNotReady("放弃宿舍暂选后未在有限次数内返回房间")

    def reset_room_time(self, room):
        for _operator in self.op_data.operators.keys():
            if self.op_data.operators[_operator].room == room:
                self.op_data.operators[_operator].time_stamp = None

    @timed_step("room_detail")
    def turn_on_room_detail(self, room):
        for enter_times in range(3):
            pending = False
            for retry_times in range(19):
                if self.find("connecting"):
                    self.sleep()
                elif room == "recycle" and self.find("recycle/dashboard"):
                    # 材料转化页没有进驻信息按钮，先回到房间视图。
                    self.back()
                elif pos := self.find("room_detail"):
                    # 取面板内部的白色，避开左边缘；标题出现后仍可能处于展开动画中。
                    if all(self.get_color((1250, 1)) > [252] * 3):
                        return
                    logger.debug("等待进驻详情面板展开")
                    self.sleep(interval=0.5)
                elif (pos := self.find("arrange_check_in")) or (
                    pos := self.find("arrange_check_in_small")
                ):
                    if pending:
                        pending = False
                        self.sleep(0.2)
                    else:
                        self.tap(pos, interval=0.2)
                        pending = True
                else:
                    self.sleep()
            if (
                not self.find("connecting")
                and self.find("room_detail")
                and all(self.get_color((1250, 1)) > [252] * 3)
            ):
                return
            for back_time in range(3):
                if pos := self.find("control_central"):
                    break
                self.back()
            if not pos:
                self.back_to_infrastructure()
            self.enter_room(room)
        self.reset_room_time(room)
        raise Exception("未成功进入房间")

    def _room_list_at_end(self, bottom):
        point = (1800, 925 if bottom else 138)
        card_top = 532 if bottom else 344
        return (
            self.get_color(point)[0] <= 51
            and self.get_color((1800, card_top - 1))[0] >= 140
            and self.get_color((1800, card_top))[0] <= 70
        )

    def _require_room_list(self):
        if config.stop_mower.is_set():
            raise MowerExit
        if self.find("confirm") or self.find("double_confirm/main"):
            raise RecognizeError("读取房间名单时出现确认弹窗，返回场景导航处理")
        if not self.find("room_detail"):
            raise RecognizeError("读取房间名单时已离开房间详情，重新定位")

    def scroll_room_operators(self, *, bottom, room=None, read_near_bottom=None):
        """定位名单端点。未指定方向时接受当前端点，中段先定位到上端。"""
        requested = bottom
        rechecked_room = False
        previous_near = None
        swipes = 0
        retry_at = 0
        while True:
            self._require_room_list()
            if bottom is None and self._room_list_at_end(True):
                end = True
            else:
                bottom = bool(bottom)
                end = bottom if self._room_list_at_end(bottom) else None
            if end is not None:
                if room is not None and self.detect_room() != room:
                    if not rechecked_room:
                        rechecked_room = True
                        previous_near = None
                        bottom = requested
                        self.recog.update()
                        continue
                    raise RecognizeError(f"读取名单端点时未确认房间 {room}")
                return end
            if swipes and read_near_bottom is not None:
                frame = self.recog.img
                column = frame[:, 1800, 0]
                offset = next(
                    (
                        dy
                        for dy in range(1, 7)
                        if all(
                            column[top + dy - 1] >= 140 and column[top + dy] <= 70
                            for top in (323, 532, 741)
                        )
                    ),
                    None,
                )
                stamp = getattr(self.recog, "capture_started_at", None)
                if (
                    offset is not None
                    and isinstance(stamp, datetime)
                    and all(self.get_color((1250, 1)) > [252] * 3)
                    and self.detect_room() == room
                ):
                    if (
                        previous_near is not None
                        and previous_near[0] == offset
                        and previous_near[1] < stamp
                        and previous_near[2] is not frame
                        and read_near_bottom(offset)
                    ):
                        return True
                    previous_near = (offset, stamp, frame)
                else:
                    previous_near = None
            remaining = retry_at - monotonic()
            if remaining > 0:
                self.sleep(min(remaining, self.performance_profile.poll_interval))
                continue
            if swipes == 6:
                break
            previous_near = None
            # 在驻员卡片范围内完成整段手势，避开上方标题和底部进驻人数栏。
            start_y = 746 if bottom else 260
            self.swipe(
                (self.recog.w * 0.8, self.recog.h * start_y / 1080),
                (0, (-1 if bottom else 1) * self.recog.h * 0.45),
                duration=220
                if bottom and swipes == 0 and not self.low_frame_rate_mode
                else 500,
                interval=0,
            )
            self.recog.update()
            swipes += 1
            retry_at = monotonic() + 1
        raise RecognizeError("房间名单滚动六次仍未到达边界，返回房间重试")

    def _require_training_detail(self):
        if self.train_scene() != Scene.INFRA_DETAILS or self.detect_room() != "train":
            raise RecognizeError("未确认训练室进驻详情，不更新驻员缓存")

    def _observe_training_room(self, read_time_index, departing_plan, force_mood):
        """暂存两槽观察；未知姓名和错误场景不产生实际驻员副作用。"""
        for _ in range(6):
            scene = self.train_scene()
            if scene == Scene.INFRA_DETAILS:
                BaseSchedulerSolver._require_training_detail(self)
                break
            if scene == Scene.TRAIN_MAIN:
                self._open_check_in_detail()
            elif scene in (Scene.CONNECTING, Scene.UNKNOWN):
                self.sleep(0.25)
            else:
                raise RecognizeError("读取训练室驻员时场景不符")
        else:
            raise RecognizeError("训练室进驻详情未在有限重试内打开")
        self.wait_product_complete()

        def read_names():
            BaseSchedulerSolver._require_training_detail(self)
            names = []
            for index in range(RIGHT_SIDE_ROOM_CAPACITY["train"]):
                top = 135 + 209 * index
                slot_scope = ((1288, top), (1869, top + 191))
                if self.find("infra_no_operator", scope=slot_scope):
                    name = ""
                else:
                    name_scope = ((1460, top + 25), (1785, top + 80))
                    name = self.read_screen(
                        cropimg(self.recog.gray, name_scope), type="name"
                    )
                    if name not in agent_list:
                        break
                    if name in names:
                        raise RecognizeError("训练室两槽读到重复姓名，保留原驻员")
                names.append(name)
            return names

        for attempt in range(3):
            names = read_names()
            if len(names) == RIGHT_SIDE_ROOM_CAPACITY["train"]:
                break
            if attempt < 2:
                self.sleep(0.25)
        else:
            raise RecognizeError(
                f"训练室第 {len(names) + 1} 槽位姓名未识别，保留原驻员"
            )

        observed = []
        roster_frame = self.recog.gray
        for index, name in enumerate(names):
            data = {"agent": name, "mood": -1, "update_time": False}
            if name:
                agent = self.op_data.operators.get(name)
                update_time = (
                    getattr(self.op_data, "mood_calculation_enabled", False)
                    or agent is None
                    or force_mood
                    or agent.need_to_refresh(r="train")
                    or (self.tasks and self.tasks[0].type == TaskTypes.SHIFT_ON)
                    or index in read_time_index
                    or (
                        departing_plan is not None
                        and index < len(departing_plan)
                        and departing_plan[index] != "Current"
                        and name not in departing_plan
                    )
                    or (agent.current_room, agent.current_index) != ("train", index)
                )
                mood = (
                    self.read_accurate_mood(
                        cropimg(
                            roster_frame,
                            ((1470, 219 + 209 * index), (1780, 220 + 209 * index)),
                        )
                    )
                    if update_time
                    else agent.current_mood()
                )
                if (
                    not isinstance(mood, (int, float))
                    or not math.isfinite(mood)
                    or not 0 <= mood <= 24
                ):
                    raise RecognizeError(f"训练室第 {index + 1} 槽位心情未核实")
                data.update(
                    mood=mood,
                    update_time=update_time,
                    sample_mood=mood if update_time else agent.mood,
                )
                if index in read_time_index:
                    if mood == 24:
                        data["time"] = datetime.now()
                    else:
                        data["time"] = self.read_operator_time(
                            "train",
                            index,
                            ((1650, 270 + 210 * index), (1780, 305 + 210 * index)),
                        )
                        if (
                            self.recog.gray is not roster_frame
                            and read_names() != names
                        ):
                            raise RecognizeError(
                                "训练室倒计时与驻员名单不符，保留原驻员"
                            )
            observed.append(data)
        BaseSchedulerSolver._require_training_detail(self)
        return observed

    def _ordinary_work_room(self, room):
        return room.startswith("room_") and getattr(self.task, "type", None) in (
            TaskTypes.SELF_CORRECTION,
            TaskTypes.SHIFT_ON,
            TaskTypes.SHIFT_OFF,
        )

    def _count_visible_room_names(self, gray, count, capacity, visible, sampled=None):
        if (
            type(count) is not int
            or not 0 <= count <= len(visible)
            or any(
                gray[top - 1, 1800] < 140 or gray[top, 1800] > 70 for _, top in visible
            )
        ):
            return None
        # 姓名从左侧开始，空位图标居中。先数有字的卡片，收不齐时直接读两端。
        occupied = {
            i for i, top in visible if gray[top + 25 : top + 80, 1460:1532].max() > 200
        }
        if len(occupied) != count:
            return None
        names = [""] * capacity
        if len(occupied) < len(visible):
            # 端点已对齐，只在图标原位的两个像素误差内核对完整图案。
            icon = loadres("infra_no_operator", gray=True)
            h, w = icon.shape
            for i, top in visible:
                if i in occupied:
                    continue
                patch = gray[top + 36 : top + 40 + h, 1539 : 1543 + w]
                if cv2.matchTemplate(patch, icon, cv2.TM_CCOEFF_NORMED).max() < 0.9:
                    return None
        for i, top in visible:
            if i not in occupied:
                continue
            name = self.read_screen(gray[top + 25 : top + 80, 1460:1785], type="name")
            if name not in agent_list:
                name = ""
            if sampled is not None:
                sampled[i] = name
            if not name:
                return None
            if name in names:
                raise RecognizeError(f"同一帧的两个岗位都读到{name}，重新读取名单")
            names[i] = name
        return names

    def get_agent_from_room(
        self,
        room,
        read_time_index=None,
        related_operators=None,
        *,
        departing_plan=None,
        force_mood=False,
        strict_observation=False,
        expected_agents=None,
        submitted_training_slot=None,
        observed_facilities: set[str] | None = None,
        facility_observation=None,
        facility_observation_scope: ExitStack | None = None,
        defer_trade_order=False,
        read_dorm_evidence=False,
        record_dorm_evidence=False,
    ):
        """读取实际驻员；姓名未决槽位标记 observed=False，不据此确认离岗。

        expected_agents 仅核验本次执行名单，不改写任务的最终名单。
        """
        if room == "recycle" and getattr(self, "_recycle_unavailable", False) is True:
            return []
        force_mood = force_mood or getattr(
            self.op_data, "mood_calculation_enabled", False
        )
        training_observation = None
        if room == "train":
            training_observation = BaseSchedulerSolver._observe_training_room(
                self, read_time_index or [], departing_plan, force_mood
            )
            if submitted_training_slot is not None:
                index, target = submitted_training_slot
                interval, attempts = self.selection_transition_timing()
                deadline = monotonic() + (attempts - 1) * interval
                for attempt in range(attempts):
                    if BaseSchedulerSolver._training_slot_matches(
                        index, target, training_observation[index]["agent"]
                    ):
                        break
                    remaining = deadline - monotonic()
                    if attempt + 1 == attempts or remaining <= 0:
                        raise TrainingSubmissionUnconfirmed(index, target)
                    self.sleep(min(interval, remaining))
                    training_observation = BaseSchedulerSolver._observe_training_room(
                        self, read_time_index or [], departing_plan, force_mood
                    )
        # 只观察真实读房；初始化试住和肥鸭临时换位不产生新的休息周期。
        released_support = None
        if self._can_refresh_idle_dorm_search():
            released_support = self.op_data.get_current_operator("train", 0)
        retain_dorm_time = room.startswith("dorm")
        read_dorm_evidence = read_dorm_evidence or record_dorm_evidence
        if retain_dorm_time and departing_plan is not None:
            departing_plan = departing_plan + [""] * (
                len(self.op_data.plan[room]) - len(departing_plan)
            )
        group_transitions = (
            self._execution_group_transitions() if retain_dorm_time else {}
        )
        recovery_context = (
            {"group_transitions": group_transitions} if group_transitions else {}
        )
        if read_time_index is None:
            read_time_index = []
        if related_operators is None:
            related_operators = {}
        swap_target = None
        swap_recorded_at = None
        swap_target_snapshot = None
        swap_moods = {}
        if (
            related_operators
            and self.task is not None
            and self.task.type == TaskTypes.FIAMMETTA
            and self.task.meta_data in self.op_data.operators
        ):
            swap_target = self.task.meta_data
            swap_recorded_at = datetime.now()
            target = self.op_data.operators[swap_target]
            swap_target_snapshot = {
                "agent_current_room": target.current_room,
                "is_high": target.is_high(),
                "agent_group": target.group,
            }
        if room == "meeting" and not self.leifeng_mode:
            self.sleep(0.5)
            self.recog.update()
            clue_res = self.read_screen(
                self.recog.img, limit=10, cord=((439, 987), (577, 1033))
            )
            if clue_res != 11:
                self.clue_count = clue_res
                logger.info(
                    f"当前拥有线索数量为{self.clue_count}", extra={"log_group": "clue"}
                )
        after_roster = {}
        if (
            facility_observation is not None
            or observed_facilities is None
            or room not in observed_facilities
        ):
            observation_args = {}
            if facility_observation is not None:
                observation_args.update(
                    facility_observation=facility_observation,
                    facility_observation_scope=facility_observation_scope,
                    after_roster=after_roster,
                )
                if defer_trade_order:
                    observation_args["defer_trade_order"] = True
            elif observed_facilities is not None and self._ordinary_work_room(room):
                observation_args["after_roster"] = after_roster
            observed = self.refresh_facility_state(room, **observation_args)
            if observed and observed_facilities is not None:
                observed_facilities.add(room)
        if training_observation is None:
            self.turn_on_room_detail(room)
        # 如果是宿舍则全读取
        if room.startswith("dorm"):
            if self.task is not None and self.task.type == TaskTypes.FIAMMETTA:
                # 充能时菲亚梅塔会被临时换到任务指定的槽位，
                # 与静态排班中的位置无关；保留 agent_arrange 传入的
                # 实际槽位，否则无法采样并记录本次充能对象。
                read_time_index = list(dict.fromkeys(read_time_index))
            else:
                dorm_read_time_index = [
                    i
                    for i, obj in enumerate(self.op_data.plan.get(room, []))
                    if obj.agent in ("Free", "菲亚梅塔")
                ]
                read_time_index = list(
                    dict.fromkeys([*read_time_index, *dorm_read_time_index])
                )
        if training_observation is None:
            self.wait_product_complete()
        if room in RIGHT_SIDE_ROOM_CAPACITY:
            length = (
                1
                if room == "recycle"
                and getattr(self.op_data, "recycle_capacity", 2) == 1
                else RIGHT_SIDE_ROOM_CAPACITY[room]
            )
        else:
            length = len(self.op_data.plan.get(room, [])) or (
                5 if room.startswith("dorm") or room == "central" else 3
            )
        if after_roster:
            self._check_room_roster_frame(room, after_roster)
        # 小房间沿用进入详情时的房间核验。五岗的名单端点另行核验房号。
        recog = getattr(self, "recog", None) if training_observation is None else None
        counted_gray = getattr(recog, "gray", None)
        counted_rgb = getattr(recog, "_img", None)
        counted_at = getattr(recog, "capture_started_at", None)

        def same_capture(gray, rgb, stamp):
            return (
                gray is getattr(recog, "gray", None)
                and rgb is getattr(recog, "_img", None)
                and stamp == getattr(recog, "capture_started_at", None)
            )

        maximum = length
        if room.startswith("room_"):
            maximum = 3
        elif room.startswith("dorm") or room == "central":
            maximum = 5
        length = min(length, maximum)
        if room.startswith("room_") and not self.op_data.plan.get(room):
            # 初始化也会扫描未排班的工作间，清晰的人数栏给出实有岗位数。
            actual = read_room_occupancy(counted_gray)
            count = None
            if actual is not None and actual[1] <= maximum:
                count, length = actual
        else:
            count = (
                room_occupancy(counted_gray, length)
                if training_observation is None
                else None
            )

        def visible_work_slots(gray):
            if (
                room.startswith("room_")
                and isinstance(gray, np.ndarray)
                and gray.shape == (1080, 1920)
            ):
                for i in reversed(range(length, maximum)):
                    top = 135 + 209 * i
                    if gray[top - 1, 1800] >= 140 and gray[top, 1800] <= 70:
                        return i + 1
            return length

        if (
            length < maximum
            and (on_screen := visible_work_slots(counted_gray)) > length
        ):
            # 排班和人数栏都可能少一岗。后面仍有对齐的实卡时，逐槽读到该卡。
            length, count = on_screen, None
        if count is None and length < maximum:
            # 短排班不能把实有的后续岗位当作离岗。容量有出入时仍逐槽核对。
            actual = read_room_occupancy(counted_gray)
            if actual is not None and length < actual[1] <= maximum:
                length = actual[1]
        first_end = None
        if length == 5:
            first_end = self.scroll_room_operators(bottom=None, room=room)
        elif length > 3:
            self.scroll_room_operators(bottom=False)
        lower_visible = ((2, 323), (3, 532), (4, 741))
        visible = (
            lower_visible
            if first_end is True
            else [(i, 135 + i * 209) for i in range(min(length, 4))]
        )
        counted_names = None
        sampled_names = {}
        if training_observation is None and (
            length <= 3 or isinstance(first_end, bool)
        ):
            if not same_capture(counted_gray, counted_rgb, counted_at):
                counted_gray = getattr(recog, "gray", None)
                counted_rgb = getattr(recog, "_img", None)
                counted_at = getattr(recog, "capture_started_at", None)
                count = room_occupancy(counted_gray, length)
            if count is not None:
                counted_names = BaseSchedulerSolver._count_visible_room_names(
                    self, counted_gray, count, length, visible, sampled_names
                )

        slot_x = (1288, 1869)
        slot_y = [(135, 326), (344, 535), (553, 744), (532, 723), (741, 932)]
        offsets = [0] * len(slot_y)
        if counted_names is not None:
            for i, top in visible:
                offsets[i] = top - slot_y[i][0]
                slot_y[i] = (top, top + 191)
        slot_p = [tuple(zip(slot_x, y)) for y in slot_y]
        # 姓名从 x≈1470 开始；整张槽位卡片含头像和心情条，模板只保留
        # 左上角 265×46 像素时会截断长姓名。空槽检测仍使用完整槽位范围。
        name_x = (1460, 1785)
        name_p = [tuple(zip(name_x, (top + 25, top + 80))) for top, _ in slot_y]
        time_x = (1650, 1780)
        time_y = [(270, 305), (480, 515), (690, 725), (668, 703), (877, 912)]
        time_p = [
            ((time_x[0], top + dy), (time_x[1], bottom + dy))
            for (top, bottom), dy in zip(time_y, offsets)
        ]
        mood_p = [
            ((1470, y + dy), (1780, y + dy + 1))
            for y, dy in zip((219, 428, 637, 615, 823), offsets)
        ]
        lower_frame = None
        lower_gray = lower_captured_at = None
        lower_empty = {}
        at_bottom = False

        def save_lower_frame(offset=0):
            nonlocal lower_frame, lower_gray, lower_captured_at, lower_empty
            # 保留校准后的名单像素，后续仍使用各岗位原有的姓名、心情和计时坐标。
            lower_frame = self.recog.img[offset:]
            lower_gray = self.recog.gray[offset:]
            lower_captured_at = getattr(self.recog, "capture_started_at", None)
            lower_empty = {
                i: bool(
                    self.find(
                        "infra_no_operator",
                        scope=tuple((x, y + offset) for x, y in slot_p[i]),
                    )
                )
                for i in (3, 4)
            }

        if first_end is True and counted_names is None:
            save_lower_frame()
            self.scroll_room_operators(bottom=False, room=room)

        short_fallback = (
            counted_names is None
            and maximum <= 3
            and isinstance(counted_rgb, np.ndarray)
            and isinstance(counted_at, datetime)
            and isinstance(counted_gray, np.ndarray)
            and counted_gray.shape == (1080, 1920)
        )

        def check_roster_frame(current_slot=None):
            nonlocal counted_gray, counted_rgb, counted_at
            if same_capture(counted_gray, counted_rgb, counted_at):
                return
            self._require_room_list()
            gray = self.recog.gray
            rgb = getattr(recog, "_img", None)
            stamp = getattr(recog, "capture_started_at", None)
            verified_panel = (
                after_roster
                and rgb is not None
                and (rgb is not counted_rgb or stamp != counted_at)
                and after_roster["frame"] is rgb
                and after_roster["captured_at"] == stamp
            )
            if (
                (isinstance(first_end, bool) and not self._room_list_at_end(first_end))
                or self.find("connecting")
                or (not verified_panel and self.detect_room() != room)
            ):
                raise RecognizeError(f"换帧后未确认房间 {room} 的进驻面板，重新读房")
            if length < maximum and visible_work_slots(gray) > length:
                raise RecognizeError(f"换帧后房间 {room} 出现额外岗位，重新读房")
            if counted_names is not None:
                expected = [""] * length
                for j, _ in visible:
                    expected[j] = counted_names[j]
                matches = room_occupancy(gray, length) == count and (
                    BaseSchedulerSolver._count_visible_room_names(
                        self,
                        gray,
                        sum(bool(name) for name in expected),
                        length,
                        visible,
                    )
                    == expected
                )
            else:
                # 人数栏看不清时，只复核前面已实读的岗位和正在重读的岗位。
                known_slots = [
                    (j, row["agent"])
                    for j, row in enumerate(result)
                    if row.get("observed", True)
                ]
                if current_slot is not None:
                    known_slots.append(current_slot)
                matches = all(
                    self.read_screen(cropimg(gray, name_p[j]), type="name") == name
                    if name
                    else self.find("infra_no_operator", scope=slot_p[j])
                    for j, name in known_slots
                )
            if not matches or not same_capture(gray, rgb, stamp):
                raise RecognizeError(f"换帧后未能核实房间 {room} 的原名单，重新读房")
            sampled_names.clear()
            counted_gray, counted_rgb, counted_at = gray, rgb, stamp

        def open_lower_slots(anchor=None):
            nonlocal at_bottom, lower_frame
            lower_frame = None
            if anchor:

                def read_near_bottom(offset):
                    # 第三岗在下端上移到 y323，必须与上端已经实读的同一人对应。
                    name_scope = ((1460, 348 + offset), (1785, 403 + offset))
                    if (
                        self.read_screen(
                            cropimg(self.recog.gray, name_scope), type="name"
                        )
                        != anchor
                    ):
                        return False
                    save_lower_frame(offset)
                    return True

                self.scroll_room_operators(
                    bottom=True, room=room, read_near_bottom=read_near_bottom
                )
            else:
                self.scroll_room_operators(
                    bottom=True, room=room if length == 5 else None
                )
            at_bottom = True

        def frame_seconds(i, frame):
            try:
                return BaseMixin._time_seconds(
                    self.read_screen(frame, type="time", cord=time_p[i])
                )
            except (ValueError, OverflowError):
                return None

        def read_slot_time(i, name, *, same_frame_only=False):
            fourth_work_slot = i == 3 and not retain_dorm_time
            if (
                not isinstance(first_end, bool)
                and counted_names is None
                and not fourth_work_slot
            ):
                deadline = self.read_operator_time(room, i, time_p[i])
                if short_fallback:
                    if after_roster:
                        self._check_room_roster_frame(room, after_roster, sampled=True)
                    check_roster_frame((i, name))
                return deadline
            saved = i >= 3 and lower_frame is not None
            frame = lower_frame if saved else self.recog.img
            captured_at = (
                lower_captured_at
                if saved
                else getattr(self.recog, "capture_started_at", None)
            )
            if isinstance(captured_at, datetime):
                seconds = (
                    data["recovery_seconds"]
                    if "recovery_seconds" in data
                    else frame_seconds(i, frame)
                )
                if seconds is not None and seconds >= 0:
                    if "measured_mood" in data:
                        data["recovery_seconds"] = seconds
                    try:
                        return captured_at + timedelta(seconds=seconds)
                    except OverflowError:
                        pass
            if same_frame_only:
                return None
            if saved:
                open_lower_slots()
            if fourth_work_slot:
                # 第四岗可能只露出半行计时，重试耗尽也不能据此判定干员已耗尽。
                seconds = self.read_time(time_p[i], None)
                captured_at = getattr(self.recog, "capture_started_at", None)
                if seconds is None or not isinstance(captured_at, datetime):
                    raise RecognizeError(f"房间 {room} 第 4 岗的耗尽倒计时未核实")
                deadline = captured_at + timedelta(seconds=seconds)
            else:
                deadline = self.read_operator_time(room, i, time_p[i])
            if counted_names is not None:
                if after_roster:
                    self._check_room_roster_frame(room, after_roster, sampled=True)
                check_roster_frame()
                return deadline
            # 重试会重新截图；只接受仍属于原房间、原端点、同一干员的倒计时。
            self._require_room_list()
            if (
                not self._room_list_at_end(i >= 3)
                or self.detect_room() != room
                or self.find("infra_no_operator", scope=slot_p[i])
                or self.read_screen(cropimg(self.recog.gray, name_p[i]), type="name")
                != name
            ):
                raise RecognizeError(
                    f"计时重读后未确认房间 {room} 第 {i + 1} 岗的{name}"
                )
            return deadline

        result = []
        observation_complete = True
        reread_fourth = False
        while len(result) < length:
            i = len(result)
            if length == 5 and config.stop_mower.is_set():
                raise MowerExit
            if (
                counted_names is None
                and i >= 3
                and not at_bottom
                and lower_frame is None
            ):
                open_lower_slots(
                    result[2]["agent"] if i == 3 and first_end is False else None
                )
            data = {}
            _name = ""
            slot_observed = False
            if training_observation is not None:
                _name = training_observation[i]["agent"]
                slot_observed = True
            elif counted_names is not None:
                if after_roster:
                    self._check_room_roster_frame(room, after_roster)
                check_roster_frame()
                _name = counted_names[i]
                gray = counted_gray
                saved = False
                slot_observed = True
            else:
                for read_try in range(3):
                    if after_roster:
                        self._check_room_roster_frame(room, after_roster)
                    if short_fallback:
                        check_roster_frame()
                    saved = i >= 3 and lower_frame is not None
                    empty = (
                        lower_empty[i]
                        if saved
                        else self.find("infra_no_operator", scope=slot_p[i])
                    )
                    if empty:
                        _name = ""
                        slot_observed = True
                        break
                    gray = lower_gray if saved else self.recog.gray
                    if (
                        not saved
                        and i in sampled_names
                        and same_capture(counted_gray, counted_rgb, counted_at)
                    ):
                        _name = sampled_names.pop(i)
                    else:
                        _name = self.read_screen(cropimg(gray, name_p[i]), type="name")
                    if _name != "":
                        slot_observed = True
                        break
                    if read_try < 2:
                        logger.debug(
                            f"房间 {room} 第 {i + 1} 槽位干员未识别或置信度过低，等待 0.25s 原地重试 ({read_try + 1}/2)"
                        )
                        if saved:
                            open_lower_slots()
                        else:
                            self.sleep(0.25)
                            if isinstance(first_end, bool):
                                self.scroll_room_operators(bottom=i >= 3, room=room)
                if after_roster:
                    self._check_room_roster_frame(room, after_roster, sampled=True)
                if short_fallback:
                    check_roster_frame((i, _name) if slot_observed else None)
                    gray = counted_gray
                if _name and any(row["agent"] == _name for row in result):
                    raise RecognizeError(f"房间 {room} 的驻员姓名重复，重新核对岗位")
            if room == "recycle" and i == 1 and not slot_observed:
                self.op_data.recycle_capacity = 1
                if len(self.op_data.plan.get(room, ())) > 1:
                    self._disable_recycling()
                break
            observation_complete = observation_complete and slot_observed
            if not slot_observed:
                data["observed"] = False
            if strict_observation and not slot_observed:
                raise RecognizeError(
                    f"房间 {room} 第 {i + 1} 槽位未核实，不能恢复进程崩溃后的调度"
                )
            _mood = 24
            # 如果房间不为空
            update_time = False
            working_time = None
            slot_deadline = None
            full_bar_with_timer = False
            if _name != "":
                if _name not in self.op_data.operators.keys() and _name in agent_list:
                    self.op_data.add(Operator(_name, ""))

                agent = self.op_data.operators[_name]
                previous_position = (agent.current_room, agent.current_index)
                should_read_mood = (
                    force_mood
                    or self.op_data.operators[_name].need_to_refresh(r=room)
                    or (self.tasks and self.tasks[0].type == TaskTypes.SHIFT_ON)
                    or i in read_time_index
                    or (
                        departing_plan is not None
                        and i < len(departing_plan)
                        and departing_plan[i] != "Current"
                        and _name not in departing_plan
                    )
                    or previous_position != (room, i)
                )
                if (
                    room.startswith("dorm")
                    and self.task is not None
                    and self.task.type == TaskTypes.FIAMMETTA
                    and self.task.meta_data
                    and not force_mood
                    and departing_plan is None
                ):
                    fia_read_names = {"菲亚梅塔"}
                    if self.task.meta_data:
                        fia_read_names.add(self.task.meta_data)
                    should_read_mood = _name in fia_read_names and i in read_time_index
                refresh_fia = retain_dorm_time and _name == "菲亚梅塔"
                if refresh_fia:
                    # 充能后归位也要实读，不能沿用交换前心情或原槽位的倒计时。
                    should_read_mood = True
                    if i not in read_time_index:
                        read_time_index.append(i)
                evidence = retain_dorm_time and read_dorm_evidence and slot_observed
                measured = None
                release_bar = (
                    retain_dorm_time
                    and slot_observed
                    and isinstance(first_end, bool)
                    and getattr(self, "_release_dorm_readings", None) is not None
                )
                if training_observation is None and (
                    should_read_mood or evidence or release_bar
                ):
                    measured = self.read_accurate_mood(cropimg(gray, mood_p[i]))
                    if (
                        retain_dorm_time
                        and slot_observed
                        and type(measured) in (int, float)
                        and 0 <= measured <= 24
                    ):
                        data["measured_mood"] = measured
                        if isinstance(first_end, bool):
                            full_bar_with_timer = (
                                measured == 24
                                and np.max(cropimg(gray, time_p[i])) > 200
                            )
                            if (evidence and measured < 24) or (
                                full_bar_with_timer
                                and (evidence or i in read_time_index)
                            ):
                                frame = lower_frame if saved else self.recog.img
                                data["recovery_seconds"] = frame_seconds(i, frame)
                            if full_bar_with_timer and data.get("recovery_seconds"):
                                captured_at = (
                                    lower_captured_at
                                    if saved
                                    else getattr(self.recog, "capture_started_at", None)
                                )
                                if isinstance(captured_at, datetime):
                                    slot_deadline = read_slot_time(i, _name)
                            if full_bar_with_timer:
                                # 条宽已取整。同帧计时可用于床位期限，不能据此写入满心情。
                                if not data.get("recovery_seconds"):
                                    data.pop("measured_mood")
                            elif evidence and (
                                should_read_mood or record_dorm_evidence
                            ):
                                should_read_mood = True
                                data["mood_sampled"] = True
                if training_observation is not None:
                    _mood = training_observation[i]["mood"]
                    update_time = training_observation[i]["update_time"]
                elif should_read_mood and not full_bar_with_timer:
                    _mood = measured
                    if strict_observation and (
                        not isinstance(_mood, (int, float))
                        or not math.isfinite(_mood)
                        or not 0 <= _mood <= 24
                    ):
                        raise RecognizeError(f"房间 {room} 第 {i + 1} 槽位心情未核实")
                    update_time = True
                    if getattr(self.op_data, "mood_calculation_enabled", False) and (
                        not isinstance(_mood, (int, float))
                        or not math.isfinite(_mood)
                        or not 0 <= _mood <= 24
                    ):
                        _mood, update_time = agent.mood, False
                else:
                    _mood = agent.current_mood()
                    if full_bar_with_timer and _mood == 24:
                        _mood = -1
                edge_fourth = i == 3 and (offsets[i] > 0 or reread_fourth)
                requested_fourth_work = (
                    i == 3 and not retain_dorm_time and i in read_time_index
                )
                needs_time = False
                verify_working_zero = (
                    training_observation is None
                    and update_time
                    and _mood == 0
                    and _name != "菲亚梅塔"
                    and (
                        room in ("central", "contact", "meeting")
                        or room.startswith("room_")
                    )
                )
                if verify_working_zero:
                    if self._room_slot_distracted(gray, slot_y[i][0]):
                        sampled_at = (
                            lower_captured_at
                            if saved
                            else self.recog.capture_started_at
                        )
                        if isinstance(sampled_at, datetime):
                            working_time = sampled_at
                        elif i == 3:
                            raise RecognizeError(f"房间 {room} 第 4 岗的采集时刻未核实")
                        else:
                            working_time = datetime.now()
                    else:
                        needs_time = i != 3 or requested_fourth_work
                elif requested_fourth_work:
                    needs_time = 0 <= _mood <= 24
                elif (
                    isinstance(first_end, bool)
                    or counted_names is not None
                    or short_fallback
                ) and (full_bar_with_timer or 0 <= _mood < 24):
                    # 读时可能换帧。先核实本岗所需的倒计时，再写心情、驻员和床位。
                    needs_time = i in read_time_index or (
                        update_time and _name == "菲亚梅塔"
                    )
                    if retain_dorm_time and _name != "菲亚梅塔":
                        bed = next(
                            (
                                bed
                                for bed in self.op_data.all_dorms()
                                if bed.position == (room, i)
                                and self.op_data.is_recovery_dorm(
                                    bed, _name, **recovery_context
                                )
                            ),
                            None,
                        )
                        if bed is not None:
                            retained = (
                                previous_position == (room, i)
                                and bed.name == _name
                                and bed.time is not None
                            )
                            needs_time = not retained and (
                                needs_time or update_time or full_bar_with_timer
                            )
                if needs_time and slot_deadline is None:
                    slot_deadline = read_slot_time(
                        i, _name, same_frame_only=edge_fourth
                    )
                    if edge_fourth and slot_deadline is None:
                        if reread_fourth:
                            raise RecognizeError(f"房间 {room} 第 4 岗的倒计时未核实")
                        # 上端第四张卡的计时可能被遮挡。换端核实名单后重读整张卡。
                        first_end = self.scroll_room_operators(bottom=True)
                        if same_capture(counted_gray, counted_rgb, counted_at):
                            raise RecognizeError(f"房间 {room} 的下端画面未刷新")
                        visible = lower_visible
                        check_roster_frame()
                        dy = offsets[i]
                        offsets[i] = 0
                        slot_y[i] = tuple(y - dy for y in slot_y[i])
                        for scopes in (slot_p, name_p, time_p, mood_p):
                            scopes[i] = tuple((x, y - dy) for x, y in scopes[i])
                        reread_fourth = True
                        continue
                    if verify_working_zero:
                        working_time = slot_deadline
                if verify_working_zero and after_roster:
                    self._check_room_roster_frame(room, after_roster, sampled=True)
                if (
                    facility_observation
                    and update_time
                    and isinstance(_mood, (int, float))
                    and math.isfinite(_mood)
                    and 0 <= _mood <= 24
                ):
                    facility_observation["moods"][i + 1] = _mood
                # 估算值只用于本次读数，保留与原采样时间配对的心情，避免重复扣减。
                sample_mood = _mood if update_time else agent.mood
                if training_observation is not None:
                    sample_mood = training_observation[i]["sample_mood"]
                update_args = (
                    _name,
                    sample_mood,
                    room,
                    i,
                    update_time,
                )
                related_operator = related_operators.get(i)
                record_kwargs = {}
                if update_time:
                    if (
                        _mood == 0
                        and working_time is not None
                        and working_time <= datetime.now()
                    ):
                        record_kwargs["mood_event"] = "exhausted"
                    if _name == "菲亚梅塔" and related_operator:
                        record_kwargs = {
                            "related_operator": related_operator,
                            "mood_event": "fiammetta_charge",
                        }
                        if swap_recorded_at is not None:
                            record_kwargs["recorded_at"] = swap_recorded_at + timedelta(
                                seconds=1
                            )
                    if (
                        swap_recorded_at is not None
                        and _name == "菲亚梅塔"
                        and related_operator == swap_target
                    ):
                        swap_moods["before"] = _mood
                        swap_fia_snapshot = {
                            "agent_current_room": agent.current_room,
                            "is_high": agent.is_high(),
                            "agent_group": agent.group,
                        }
                    elif swap_recorded_at is not None and _name == swap_target:
                        record_kwargs = {
                            "related_operator": "菲亚梅塔",
                            "mood_event": "fiammetta_after",
                            "recorded_at": swap_recorded_at + timedelta(seconds=1),
                        }
                        swap_moods["after"] = _mood
                # 充能临时进出宿舍只更新心情采样，不清零工作消耗速度，
                # 也不把宿舍恢复或充能跳变计入工作消耗速度。
                charge_transition = (
                    self.task is not None
                    and self.task.type == TaskTypes.FIAMMETTA
                    and bool(self.task.plan)
                    and (
                        room.startswith("dorm") or agent.current_room.startswith("dorm")
                    )
                )
                if charge_transition:
                    record_kwargs["preserve_depletion_rate"] = True
                record_kwargs.update(recovery_context)
                high_no_time = self.op_data.update_detail(*update_args, **record_kwargs)
                if working_time is not None:
                    agent.exhaust_time = working_time
                    data["time"] = working_time
                BaseSchedulerSolver._record_dorm_admission(
                    self, _name, room, i, previous_position
                )
                pending = getattr(self.task, "idle_dorm_search_names", {}).get(
                    room, set()
                )
                if update_time and _name in pending:
                    pending.discard(_name)
                    if _mood >= agent.upper_limit:
                        self.op_data.stop_idle_dorm_search()
                data["depletion_rate"] = agent.depletion_rate
                if (
                    training_observation is None
                    and high_no_time is not None
                    and high_no_time not in read_time_index
                ):
                    logger.debug(
                        f"检测到高效组休息时间数据不存在:{room},{high_no_time}"
                    )
                    read_time_index.append(high_no_time)
            else:
                _mood = -1
            data["agent"] = _name
            data["mood"] = _mood
            if (
                retain_dorm_time
                and _name != "菲亚梅塔"
                and _name in self.op_data.operators
            ):
                _, bed = self.op_data.get_dorm_by_name(_name, **recovery_context)
                if bed is not None and bed.name == _name and bed.time is not None:
                    # 满条仍在读秒时，已读到的 24 点期限优先于旧记录。
                    if (
                        full_bar_with_timer
                        and agent.upper_limit == 24
                        and slot_deadline is not None
                    ):
                        bed.time = slot_deadline
                    data["time"] = bed.time
                    result.append(data)
                    continue
            if (
                i in read_time_index
                and _name != ""
                and room != "recycle"
                and (_mood >= 0 or full_bar_with_timer)
            ):
                if training_observation is not None:
                    data["time"] = training_observation[i]["time"]
                elif working_time is not None:
                    data["time"] = working_time
                elif slot_deadline is not None:
                    data["time"] = slot_deadline
                elif _mood == 24 or room in ["meeting", "factory"] and not update_time:
                    data["time"] = datetime.now()
                else:
                    logger.debug(f"开始记录时间:{room},{i}")
                    data["time"] = read_slot_time(i, _name)
                    if after_roster:
                        self._check_room_roster_frame(room, after_roster, sampled=True)
                self.op_data.refresh_dorm_time(room, i, data, **recovery_context)
                if refresh_fia and (update_time or full_bar_with_timer):
                    self._refresh_fiammetta_task(data["time"])
                logger.debug(f"停止记录时间:{str(data)}")
            result.append(data)
        if (
            observation_complete
            and swap_target_snapshot is not None
            and "before" in swap_moods
            and "after" in swap_moods
        ):
            if swap_moods["after"] == 24:
                self.task.fia_charge_confirmed = True
            save_agent_action(
                swap_target,
                swap_target_snapshot["agent_current_room"],
                room,
                swap_target_snapshot["is_high"],
                swap_target_snapshot["agent_group"],
                swap_moods["before"],
                related_operator="菲亚梅塔",
                mood_event="fiammetta_before",
                current_time=swap_recorded_at,
            )
            # 充能技能以满心情触发；补记自身交换前的 24，展示时间
            # 与实读的交换后心情相差一秒，不改写实际采样或恢复计时。
            save_agent_action(
                "菲亚梅塔",
                swap_fia_snapshot["agent_current_room"],
                room,
                swap_fia_snapshot["is_high"],
                swap_fia_snapshot["agent_group"],
                24,
                related_operator=swap_target,
                mood_event="fiammetta_charge",
                current_time=swap_recorded_at,
            )
        if after_roster:
            facility = after_roster["facility"]
            if facility_observation is not None:
                facility_observation["failure_detail"] = (
                    "订单详情读取未完成"
                    if facility == "trade"
                    else "产物详情读取未完成"
                )
            self._check_room_roster_frame(room, after_roster)
        if counted_names is not None or short_fallback:
            check_roster_frame()
        if after_roster:
            observed = self._read_room_facility_product(
                room, facility, None, facility_observation, facility_observation_scope
            )
            if observed and observed_facilities is not None:
                observed_facilities.add(room)
        self._reconcile_room_observation(
            room, result, expected_agents=expected_agents, **recovery_context
        )
        if (
            retain_dorm_time
            and observation_complete
            and self.task is not None
            and self.task.type != TaskTypes.FIAMMETTA
        ):
            from arknights_mower.utils.dorm_recovery import reconcile_recovery_marker

            reconcile_recovery_marker(self.op_data, room, result)
        if released_support is not None and (
            not released_support.current_room or released_support.is_resting()
        ):
            self.op_data.refresh_idle_dorm_search(
                reason="专精协助位干员已释放", names=[released_support.name]
            )
        if training_observation is not None:
            self.last_train_mood_read = datetime.now()
        return result

    def _reconcile_room_observation(
        self, room, observed, *, group_transitions=None, expected_agents=None
    ):
        """提交已确认岗位的驻员归属、离宿结果及恢复责任。"""
        slots = {
            index: item["agent"]
            for index, item in enumerate(observed)
            if item.get("observed", True)
        }
        complete = len(slots) == len(observed)
        task = self.task
        if expected_agents is not None and room.startswith("dorm"):
            # 两人充能等短名单会清空其余床位，读房仍返回完整宿舍。
            expected_agents = expected_agents + [""] * (
                len(self.op_data.plan[room]) - len(expected_agents)
            )
        confirmed_release = (
            room.startswith("dorm")
            and complete
            and task is not None
            and (task.plan.get(room) if expected_agents is None else expected_agents)
            == [item["agent"] for item in observed]
        )
        for name, operator in self.op_data.operators.items():
            if (
                operator.current_room != room
                or not complete
                and operator.current_index not in slots
                or slots.get(operator.current_index) == name
            ):
                continue
            confirmed_departure = confirmed_release or (
                room.startswith("dorm")
                and complete
                and getattr(task, "strict_mood_limit", False)
                and task.meta_data == name
                and self.op_data.has_rest_mood_limit(name)
                and getattr(task, "mood_limit", None) in (None, operator.upper_limit)
            )
            retain_dorm_sample = (
                confirmed_departure
                and name not in slots.values()
                and operator.time_stamp is not None
                and has_resting_mood(operator)
                and not operator.mood_is_prediction
            )
            if room.startswith("dorm"):
                _, bed = self.op_data.get_dorm_by_name(
                    name, group_transitions=group_transitions
                )
                if bed is not None and bed.name == name:
                    bed.reset()
                if (
                    getattr(self.task, "strict_mood_limit", False)
                    and self.task.meta_data == name
                ):
                    operator.rest_mood_release_limit = operator.upper_limit
            operator.current_room, operator.current_index = "", -1
            if (
                confirmed_release
                and name not in slots.values()
                and getattr(task, "strict_mood_limit", False)
                and task.meta_data == name
                and self.op_data.has_rest_mood_limit(name)
                and getattr(task, "mood_limit", None) in (None, operator.upper_limit)
            ):
                self._cancel_released_group_shift_targets(name)
            if retain_dorm_sample:
                # 离宿保留原实读及采样时间，待命后停止沿用宿舍恢复速度。
                operator.depletion_rate = 0
            else:
                operator.time_stamp = None
            if name == "菲亚梅塔":
                self._refresh_fiammetta_task(None)
            if self.task is not None and self.task.type != TaskTypes.SHIFT_OFF:
                release_task = self.find_next_task(
                    task_type=TaskTypes.RELEASE_DORM, meta_data=name
                )
                if release_task and self.task is not release_task:
                    release_task.remove_release_dorm_operator(name)
                    if not release_task.plan:
                        self.tasks.remove(release_task)
            logger.info(
                f"重设 [[operator:{name}]] 至空闲",
                extra={
                    "log_room": room,
                    "log_agents": [name],
                    "log_event": {"type": "operator-reset-idle"},
                },
            )
        if getattr(self.task, "emergency_staffing", False) and isinstance(
            self.emergency_state, dict
        ):
            targets = self.emergency_state.get("staffing_plan", {}).get(room, [])
            confirmed = [
                name if slots.get(index) == name else "Current"
                for index, name in enumerate(targets)
            ]
            self._emergency_sync_compensation({room: confirmed})
        if room.startswith("dorm") and slots:
            self._recovery_plan_dirty = True
        if not complete:
            logger.warning("%s 名单识别未决，保留未确认驻员与床位缓存", room)
            return
        # 完整空房间同样产生成功观测；部分名单只更新已确认岗位。
        observations = getattr(self.op_data, "room_observations", {})
        observations[room] = observations.get(room, 0) + 1
        self.op_data.room_observations = observations
        self._observe_rescue_staffing_log(room, observed)

    def refresh_current_room(self, room, current_index=None):
        _current_room = self.op_data.get_current_room(room, current_index=current_index)
        if _current_room is None:
            self.get_agent_from_room(room)
            _current_room = self.op_data.get_current_room(room, True)
        return _current_room

    def get_order_remaining_time(self):
        self._wait_drone_interface()
        # 订单剩余时间
        execute_time = self.double_read_time(
            self._run_order_time_region(),
            use_digit_reader=True,
        )
        return round((execute_time - datetime.now()).total_seconds(), 1)

    def _cancel_pending_shift_on(self, name):
        """实际上岗只撤销本人的旧工作目标，保留宿舍迁移和其他人的动作。"""
        locks_changed = False
        for task in task_view(self.tasks, TaskScope.REPLAN):
            if (
                task is getattr(self, "task", None)
                or task.type != TaskTypes.SHIFT_ON
                or getattr(task, "group_shift_expected", {})
                or not any(
                    name in names
                    for plan in (task.plan, getattr(task, "backup_shift_intent", {}))
                    for room, names in plan.items()
                    if not room.startswith("dorm")
                )
            ):
                continue
            if hasattr(task, "backup_shift_intent") and not getattr(
                task, "backup_shift_active", False
            ):
                task.plan = copy.deepcopy(task.backup_shift_intent)
                del task.backup_shift_intent
                del task.backup_shift_conditions
            task.plan = {
                room: names
                if room.startswith("dorm")
                else ["Current" if agent == name else agent for agent in names]
                for room, names in task.plan.items()
                if room.startswith("dorm")
                or any(agent not in (name, "Current") for agent in names)
            }
            locked = getattr(task, "product_shift_locked", False)
            locks_changed |= locked
            # 只剩清床动作时也移除，不能留下无人回班的旧清床任务。
            if not any(
                agent not in ("Current", "Free", "")
                for names in task.plan.values()
                for agent in names
            ):
                self.tasks[:] = [queued for queued in self.tasks if queued is not task]
            elif locked:
                slots = {
                    (room, index)
                    for room, names in task.plan.items()
                    for index, agent in enumerate(names)
                    if agent != "Current"
                }
                self._reserve_deferred_product_shift(task, slots)
            logger.info(f"{name}已重新上岗，撤销其旧上班安排")
        if locks_changed:
            self._refresh_deferred_product_reservations()

    def _record_dorm_admission(self, name, room, index, previous_position):
        """实际入住后区分普通补床与集中恢复正式批次。"""
        if not room.startswith("dorm"):
            return
        task = getattr(self, "task", None)
        names = getattr(task, "plan", {}).get(room, [])
        if index >= len(names) or names[index] not in (name, "Free"):
            return
        op = self.op_data.operators[name]
        from arknights_mower.utils.urgent_recovery import recovery_owner

        requested = set(getattr(task, "urgent_recovery_request_names", ()))
        if (
            name in requested
            and getattr(task, "urgent_recovery_support_names", ())
            and recovery_owner(self.op_data, op, requested)
        ):
            self.op_data.urgent_recovery_supporters[name] = list(
                task.urgent_recovery_support_names
            )
        ordinary_plan = getattr(task, "dorm_fill_plan", {}).get(room, [])
        if (
            getattr(task, "type", None) in (TaskTypes.FILL_DORM, TaskTypes.RELEASE_DORM)
            or any(name in row for row in getattr(task, "dorm_fill_plan", {}).values())
            or index < len(ordinary_plan)
            and ordinary_plan[index] in (name, "Free")
            or getattr(task, "simple_dorm_fill", False)
        ):
            if (
                previous_position != (room, index)
                and not (previous_position[0] or "").startswith("dorm")
                and not op.is_high()
                and self.op_data.is_dynamic_dorm_position(
                    room,
                    index,
                    name,
                    group_transitions=self._execution_group_transitions(),
                )
            ):
                op.temporary_dorm_fill = True
        elif getattr(task, "type", None) in (
            TaskTypes.SHIFT_OFF,
            TaskTypes.EXHAUST_OFF,
        ):
            op.temporary_dorm_fill = False

    def current_room_changed(self, instance, *, started_working=False):
        if self._initial_mood_read_pending():
            return
        # 构造干员及副表演算也可能设置位置；仅实际登记对象的上岗使预约失效。
        if self.op_data.operators.get(instance.name) is not instance:
            return
        if started_working:
            self._cancel_pending_shift_on(instance.name)
        if not self.op_data.first_init:
            logger.info(f"{instance.name} 房间变动")
            if instance.refresh_order_room[0]:
                ref_rooms = (
                    instance.refresh_order_room[1]
                    if instance.refresh_order_room[1]
                    else list(self.op_data.run_order_rooms.keys())
                )
                for ref_room in ref_rooms:
                    self.refresh_run_order_time(ref_room)
            if (
                instance.name in self.op_data.operators
                and self.op_data.operators[instance.name].refresh_drained
            ):
                self.refresh_drained_time()

    def refresh_drained_time(self):
        logger.debug("刷新用尽倒计时")
        invalidate_replacement_checks(self)
        solved = []
        for agent in self.op_data.exhaust_agent:
            if agent in solved:
                continue
            logger.debug(f"开始检查{agent}")
            shift_off = self.find_next_task(
                datetime.now() + timedelta(minutes=1),
                task_type=TaskTypes.EXHAUST_OFF,
                meta_data=agent,
                compare_type=">",
                scope=TaskScope.REPLAN,
            )
            if shift_off:
                logger.info(f"移除 {shift_off.meta_data} 用尽下班任务以刷新时间")
                exhausts = shift_off.meta_data.split(",")
                solved.extend(exhausts)
                self.tasks.remove(shift_off)
                for o in exhausts:
                    self.op_data.operators[o].time_stamp = None
                self.task
            else:
                self.op_data.operators[agent].time_stamp = None
        if solved:
            self.tasks.append(
                (
                    SchedulerTask(
                        time=datetime.now(),
                        task_plan={},
                        task_type=TaskTypes.NOT_SPECIFIC,
                    )
                )
            )

    def refresh_run_order_time(self, room):
        logger.debug("检测到插拔房间人员变动！")
        for pending in task_view(self.tasks, TaskScope.REPLAN):
            if pending.type != TaskTypes.RUN_ORDER or pending.meta_data != room:
                continue
            if pending is self.task or any(
                getattr(pending, field, False)
                for field in (
                    "run_order_original_roster",
                    "run_order_restore_pending",
                    "emergency_original_roster",
                    "maintenance_replacement_run",
                    "maintenance_advance_before_backup",
                )
            ):
                return
            self.tasks.remove(pending)
            self._queue_order_refresh(room)
            logger.info("实际驻员变化，重新读取 %s 的跑单时间", room)
            return

    def _retain_dorm_recovery_plan(self, room):
        rooms = getattr(self.task, "dorm_recovery_restore", ())
        if room not in rooms:
            self.task.dorm_recovery_restore = [*rooms, room]

    def _remove_trailing_dorm_recipient(
        self, room, observed, retained, target, recipient
    ):
        """仅在末床一人需要离宿时，核对本帧姓名和移出按钮。"""
        index = len(retained)
        if (
            index not in (3, 4)
            or not recipient
            or retained[-1] != target
            or [row["agent"] for row in observed]
            != retained + [recipient] + [""] * (4 - index)
            or not observed[index].get("mood_sampled")
            or self.op_data.is_free_room_excluded(recipient)
            or any(
                row.get("measured_mood") != 24
                or row.get("recovery_seconds") is not None
                for row in observed[: index - 1]
            )
        ):
            return False
        return self._tap_dorm_remove_button(room, index, recipient)

    def _dorm_removal_frame(
        self, room, observed, started_at, task
    ) -> _DormRemovalFrame | None:
        recog = getattr(self, "recog", None)
        device = getattr(self, "device", None)
        if (
            not isinstance(recog, Recognizer)
            or device is None
            or recog.device is not device
            or task is None
            or task is not self.task
            or room in getattr(task, "dorm_recovery_restore", ())
        ):
            return None
        image, gray, stamp = recog._img, recog._gray, recog.capture_started_at
        if (
            not isinstance(image, np.ndarray)
            or image.shape != (1080, 1920, 3)
            or not isinstance(gray, np.ndarray)
            or gray.shape != image.shape[:2]
            or not isinstance(stamp, datetime)
            or stamp < started_at
            or len(observed) != 5
        ):
            return None
        names = tuple(row["agent"] for row in observed)
        if (
            not all(names)
            or len(set(names)) != 5
            or names != tuple(task.plan.get(room, ()))
            or not all(row.get("observed", True) for row in observed)
        ):
            return None
        return _DormRemovalFrame(
            task=task,
            room=room,
            names=names,
            recognizer=recog,
            device=device,
            touch_control=getattr(device, "control", None),
            image=image,
            gray=gray,
            capture_started_at=stamp,
        )

    def _dorm_remove_position(self, room, index, resident, bottom, expected_third):
        if self.find("connecting"):
            raise RecognizeError("移出宿舍住客前正在联网，重新核对房间")
        top = (532 if bottom else 762) if index == 3 else 741
        gray = self.recog.gray
        if expected_third and (
            not self.find("infra_no_operator", scope=((1288, 741), (1869, 932)))
            or self.read_operator_in_room(cropimg(gray, ((1460, 348), (1785, 403))))
            != expected_third
        ):
            return None
        name = self.read_operator_in_room(
            cropimg(gray, ((1460, top + 25), (1785, top + 80)))
        )
        if name != resident:
            raise RecognizeError(f"{room} 第{index + 1}床住客已变化，重新核对房间")
        try:
            icon = loadres("dorm_remove_resident", gray=True)
        except (OSError, cv2.error):
            return None
        if (
            not isinstance(icon, np.ndarray)
            or icon.dtype != np.uint8
            or icon.shape != (47, 47)
            or not np.ptp(icon)
        ):
            return None
        button = cropimg(gray, ((1804, top + 64), (1862, top + 132)))
        _, score, _, (left, upper) = cv2.minMaxLoc(
            cv2.matchTemplate(button, icon, cv2.TM_CCOEFF_NORMED)
        )
        if score < 0.95:
            return None
        return 1804 + left + icon.shape[1] // 2, top + 64 + upper + icon.shape[0] // 2

    def _tap_dorm_remove_button(
        self,
        room,
        index,
        resident,
        *,
        expected_third=None,
        read_frame: _DormRemovalFrame | None = None,
    ):
        """移人前核对本人和床边按钮。第二次点击另取一帧核对第 3 人和第 5 床空位。"""
        position = None
        if read_frame is not None:
            image, read_frame.image = read_frame.image, None
            if (
                index in (3, 4)
                and expected_third is None
                and room == read_frame.room
                and resident == read_frame.names[index]
                and read_frame.is_current(self, image)
                and self.recog.check_current_focus() is False
                and read_frame.is_current(self, image)
            ):
                try:
                    self._require_room_list()
                    if self._room_list_at_end(True) and self.detect_room() == room:
                        position = self._dorm_remove_position(
                            room, index, resident, True, None
                        )
                except RecognizeError:
                    pass
                if not read_frame.is_current(self, image):
                    position = None
        if position is None:
            self.recog.update()
            bottom = self.scroll_room_operators(
                bottom=True if index == 4 or expected_third else None, room=room
            )
            position = self._dorm_remove_position(
                room, index, resident, bottom, expected_third
            )
            if position is None:
                return False
            if (
                read_frame is not None
                and room == read_frame.room
                and not read_frame.matches_plan(self.task)
            ):
                raise RecognizeError(f"{room} 最终名单已变，重新按当前任务核对床位")
        self._retain_dorm_recovery_plan(room)
        record_dorm_recovery()
        logger.info(
            f"{facility_label(room, self.op_data)}：暂时移出第{index + 1}床的{resident}，由本任务补回"
        )
        self.tap(position)
        return True

    def ensure_dorm_recovery_order(
        self,
        room,
        agents,
        fast_mode=True,
        *,
        allow_direct=True,
        correction_observation=None,
        continued=None,
    ) -> bool | list[dict] | DirectDormArrival:
        """先确认单回目标的入驻顺序，再由原任务恢复完整阵容。

        中间名单只用于这次点击，不能覆盖持久化任务中的完整恢复名单。
        完整读回的临时阵容可供随后补位复用。没有可复用的读数时，
        返回本房是否仍需恢复最终阵容。
        """
        from arknights_mower.utils.calculated_mood import known_operator_stages
        from arknights_mower.utils.dorm_candidates import full_dorm_candidate
        from arknights_mower.utils.dorm_recovery import (
            already_attempted_recovery,
            direct_recovery_arrival,
            fourth_bed_removals,
            observed_recovery_recipient,
            record_recovery_target,
            recovery_attempt_signature,
            recovery_managers,
            recovery_order_plan,
            recovery_target,
        )
        from arknights_mower.utils.dorm_skills import is_single_recovery_manager

        if not room.startswith("dorm") or self.task.type == TaskTypes.FIAMMETTA:
            return False
        pending = getattr(self.task, "dorm_recovery_restore", [])
        if (getattr(self.task, "simple_dorm_fill", False)) and room not in pending:
            return False
        reserved_names = {
            name
            for task in self.tasks
            for task_room, names in task.plan.items()
            if task is not self.task or task_room != room
            for name in names
        }
        plan = dict(self.task.plan)
        plan[room] = agents
        group_transitions = self._execution_group_transitions(plan)
        retained = recovery_order_plan(
            self.op_data,
            room,
            agents,
            reserved_names,
            group_transitions=group_transitions,
            continued=continued,
        )
        if retained is None:
            if room in pending:
                return self.get_agent_from_room(
                    room, departing_plan=agents, read_dorm_evidence=True
                )
            return False
        target = recovery_target(
            self.op_data,
            room,
            agents,
            group_transitions=group_transitions,
            continued=continued,
        )
        vip_index = agents.index(target.name)
        # 卡片观测随入住换位失效；本次确认保留选人时的证据供阵容读回使用。
        padding_estimates = self.op_data.dorm_mood_estimates.copy()
        # 一轮下班先替班接岗、再分床；不要为即将被下一条分床任务换走的
        # 原占位者额外清房。以队列中明确的目标覆盖为准，不猜测未来排班。
        for task in self.tasks:
            upcoming = task.plan.get(room, [])
            if (
                task is not self.task
                and self.task.time <= task.time <= self.task.time + timedelta(seconds=1)
                and len(upcoming) > vip_index
                and upcoming[vip_index] not in ("Current", "Free", "", target.name)
            ):
                return room in pending
        expected = retained + [""] * (len(agents) - len(retained))
        observed = correction_observation
        read_frame = None
        if (
            observed is None
            or [row["agent"] for row in observed]
            not in (agents, self.op_data.get_current_room(room, True))
            or not dorm_departures_sampled(observed, expected)
        ):
            read_indexes = {}
            if self.op_data.get_current_room(room, True) == agents:
                # 冷启动读回也可能是最终读房，不能漏掉绑组固定恢复位的期限。
                self.op_data.invalidate_dorm_time(room)
                read_indexes["read_time_index"] = self.op_data.get_refresh_index(
                    room, agents, group_transitions=group_transitions
                )
            read_task, read_started_at = self.task, datetime.now()
            observed = self.get_agent_from_room(
                room,
                departing_plan=agents if room in pending else expected,
                read_dorm_evidence=True,
                **read_indexes,
            )
            # 从这里到首次点床只计算归属和预约。外部传入的名单没有这段操作顺序。
            read_frame = self._dorm_removal_frame(
                room, observed, read_started_at, read_task
            )
        self._remember_facility_idle_origin(room, observed)
        if (
            room not in pending
            and len(observed) == len(agents)
            and any(not row.get("observed", True) for row in observed)
            and all(name and name not in ("Free", "Current") for name in agents)
            and any(
                row.get("observed", True) and row["agent"] != name
                for row, name in zip(observed, agents)
            )
        ):
            # 已读到另一床确实需要换班。未读全的原名单只供普通排班使用。
            return False
        current = self._observed_room_names(room, observed, len(agents))
        if target.name in current:
            slot = observed[current.index(target.name)]
            if slot.get("measured_mood") == 24 and slot.get("recovery_seconds") is None:
                return observed
        stages = known_operator_stages(self.op_data)
        managers = recovery_managers(
            self.op_data, room, agents, update_cache=False, stages=stages
        )
        recipient = observed_recovery_recipient(observed, stages)
        if current == agents:
            # 名单相同而缓存丢失不构成清房依据。只有读数明确指向别人时才调整。
            if recipient == target.name:
                record_recovery_target(
                    self.op_data, room, target, vip_index, managers, current, stages
                )
                return observed
            if recipient is None:
                return observed
            attempt = recovery_attempt_signature(
                self.op_data, current, recipient, stages, observed
            )
            if already_attempted_recovery(target, attempt):
                return observed
            if room in pending:
                target.dorm_recovery_attempt = attempt
                # 原任务已进入恢复阶段，游戏里也已是最终名单。断线后只登记这次结果。
                return observed
        elif (
            current != expected
            and allow_direct
            and room not in pending
            and direct_recovery_arrival(
                agents, target.name, observed, stages, recipient, continued=continued
            )
        ):
            # 尚未发生临时换人，不登记清房；重启后从原任务和游戏名单重新判断。
            return DirectDormArrival(observed)
        if room in pending and current != expected:
            # 中途退出时点击可能已生效。原任务按刚读到的实际名单补齐最终床位。
            return observed
        if current != expected:
            try:
                beds = ()
                if retained == agents[:3]:
                    beds = fourth_bed_removals(
                        agents, target.name, observed, recipient, stages
                    )
                # 床边只移一人时，其余人可以保留预约。切回选人页前另查临时名单。
                protected_beds = set()
                if recipient:
                    booked, slots, _, _ = self._dorm_recovery_reservations(
                        [task for task in self.tasks if task is not self.task],
                        current_task=self.task,
                    )
                    protected_beds = {
                        i
                        for i, name in enumerate(current)
                        if name
                        and name in agents
                        and (
                            name in reserved_names
                            or name in booked
                            or (room, i) in slots
                            or self.op_data.is_free_room_excluded(name)
                        )
                    }
                cannot_clear = any(current[i] not in retained for i in protected_beds)
                if protected_beds.intersection(beds) or (not beds and cannot_clear):
                    return observed
                vacancy = current.copy()
                if beds:
                    for index in beds:
                        if not self._tap_dorm_remove_button(
                            room,
                            index,
                            current[index],
                            expected_third=target.name
                            if index == 3 and beds == (4, 3)
                            else None,
                            read_frame=read_frame
                            if (index == 4 and beds == (4, 3))
                            or (beds == (3,) and current == agents)
                            else None,
                        ):
                            break
                        vacancy[index] = ""
                elif current == agents and self._remove_trailing_dorm_recipient(
                    room, observed, retained, target.name, recipient
                ):
                    vacancy[len(retained)] = ""
                if vacancy != current:
                    return self.get_agent_from_room(
                        room,
                        expected_agents=vacancy,
                        departing_plan=agents,
                        read_dorm_evidence=True,
                    )
                if cannot_clear:
                    return observed
                if current == agents:
                    target.dorm_recovery_attempt = attempt
                for attempt in range(5):
                    if self.find("confirm_blue") is not None:
                        break
                    if attempt == 4:
                        raise Exception("未成功进入干员选择界面")
                    # 首次点按可能被线索弹窗或过渡帧吞掉；ctap 的 10 秒去重
                    # 会使后续循环完全没有重试操作。
                    self.tap((self.recog.w * 0.82, self.recog.h * 0.2))
                observed_candidates = self.refresh_dorm_selection_candidates(
                    agents, room
                )
                if observed_candidates is not None:
                    self.prepare_dorm_selection(
                        agents, room, observed_candidates=observed_candidates
                    )
                    retained = recovery_order_plan(
                        self.op_data,
                        room,
                        agents,
                        reserved_names,
                        group_transitions=group_transitions,
                        continued=continued,
                    )
                    if retained is None:
                        # 新候选尚无实读时先完成普通入住，再由正常读房确认。
                        self.back()
                        return True
                    target = recovery_target(
                        self.op_data,
                        room,
                        agents,
                        group_transitions=group_transitions,
                        continued=continued,
                    )
                    vip_index = agents.index(target.name)
                label = facility_label(room, self.op_data)
                summary = (
                    f"{label}：准备将[[operator:{target.name}]]调整到第{vip_index + 1}位，"
                    "先安排临时阵容"
                )
                logger.debug("%s临时阵容：%s", label, retained)
                snapshot = {
                    "title": "临时驻员安排",
                    "header": summary,
                    "rooms": [{"id": room, "label": label, "agents": list(retained)}],
                    "backups": [],
                    "targets": [],
                    "actions": [],
                }
                logger.info(
                    format_task_log_message(snapshot, summary),
                    extra={
                        "log_room": room,
                        "log_agents": [target.name],
                        "log_task": snapshot,
                    },
                )
                record_dorm_recovery()
                self.choose_agent(
                    retained,
                    room,
                    fast_mode,
                    preserve_dorm_occupants=True,
                    recovery_padding=True,
                )
                expected = retained + [""] * (len(agents) - len(retained))
                padding_estimates = self.op_data.dorm_mood_estimates.copy()
                self._retain_dorm_recovery_plan(room)
                self.tap_confirm(room, {})
                # 临时名单确认也属于计划内离宿，不覆盖原任务的最终阵容。
                observed = self.get_agent_from_room(
                    room, expected_agents=expected, read_dorm_evidence=True
                )
                current = self._observed_room_names(room, observed, len(expected))
                if current != expected:
                    raise Exception("宿舍单回排序确认失败，保留原任务重试")
            except MowerExit:
                raise
            except DormRecoveryPaddingUnavailable:
                target.clear_dorm_recovery_target()
                self.back()
                logger.info(f"{room} 满心情空闲垫位不足，继续恢复正常阵容")
                return True
            except Exception as e:
                if (
                    isinstance(e, AgentSelectionNotReady)
                    or "检测到干员选择错误" in str(e)
                    or "宿舍单回排序确认失败" in str(e)
                    or (isinstance(e, RecognizeError) and str(e).startswith("干员确认"))
                ):
                    self.record_selection_failure()
                raise
        self._retain_dorm_recovery_plan(room)
        if current != agents:
            # 目标床位不再移动，不能因此沿用临时阵容下的恢复倒计时。
            # 补回宿管和其余入住者后，由紧接着的正常读房重新采样。
            _, bed = self.op_data.get_dorm_by_name(
                target.name, group_transitions=group_transitions
            )
            if bed is not None and bed.name == target.name:
                bed.time = None
        # 绿笑脸即可确认满心情；较新的低心情实读仍使本次确认失效。
        padding = {
            name
            for name in retained[:vip_index]
            if name != "菲亚梅塔" and not is_single_recovery_manager(name)
        }
        if any(
            not full_dorm_candidate(self.op_data, name, estimates=padding_estimates)
            for name in padding
        ):
            target.clear_dorm_recovery()
            logger.info(f"{room} 单回垫位者未确认满心情，恢复阵容后重新确认")
            return observed
        target_mood = (
            self.op_data.calculated_mood(target.name)
            if getattr(self.op_data, "mood_calculation_enabled", False)
            else target.mood
        )
        # 临时名单上的证据只对当前阵容有效；补齐住客后重新比较读数。
        managers = recovery_managers(
            self.op_data, room, agents, update_cache=False, stages=stages
        )
        if (
            target_mood is not None
            and target_mood < 24
            and len(managers) == 1
            and observed_recovery_recipient(observed, stages) == target.name
        ):
            record_recovery_target(
                self.op_data, room, target, vip_index, managers, current, stages
            )
        else:
            target.clear_dorm_recovery_target()
        logger.info(
            f"{facility_label(room, self.op_data)}：已确认[[operator:{target.name}]]位于第{vip_index + 1}位，"
            "继续按最终名单补齐其余位置",
            extra={"log_room": room, "log_agents": [target.name]},
        )
        return observed

    @staticmethod
    def _observed_room_names(room, observed, minimum_slots):
        required = observed[:minimum_slots]
        if len(observed) < minimum_slots or any(
            not item.get("observed", True) for item in required
        ):
            raise RecognizeError(f"房间 {room} 的驻员名单未读全，重新核对岗位")
        occupants = [item["agent"] for item in required if item["agent"]]
        if len(set(occupants)) != len(occupants):
            raise RecognizeError(f"房间 {room} 的驻员姓名重复，重新核对岗位")
        return [
            item["agent"] if item.get("observed", True) else None for item in observed
        ]

    def _room_matches_arrangement(self, room, targets, observed):
        charging = (
            room.startswith("dorm")
            and self.task.type == TaskTypes.FIAMMETTA
            and len(targets) == 2
            and "菲亚梅塔" in targets
        )
        slots = len(targets)
        if room != "train" and not charging:
            slots = max(
                slots, len(observed), len(self.op_data.get_current_room(room, True))
            )
        names = self._observed_room_names(room, observed, slots)
        if room == "train":
            return all(
                BaseSchedulerSolver._training_slot_matches(index, target, name)
                for index, (target, name) in enumerate(zip(targets, names))
            )
        return "Free" not in targets and names[:slots] == targets + [""] * (
            slots - len(targets)
        )

    def _open_room_selection(self, room):
        profile = self.performance_profile
        for _ in range(2):
            self._require_room_list()
            if self.find("connecting") or self.detect_room() != room:
                raise RecognizeError("打开选人页前未确认目标房间，返回房间重试")
            deadline = monotonic() + profile.transition_timeout
            self.tap((self.recog.w * 0.82, self.recog.h * 0.2), interval=0)
            if profile.low_frame_rate:
                self.sleep(min(1.0, profile.screenshot_interval / 1000))
            else:
                self.recog.update()
            while True:
                if self.find("double_confirm/main") or self.find("arrange_confirm"):
                    raise RecognizeError("打开选人页时出现确认弹窗，返回房间重试")
                if (
                    not self.find("connecting")
                    and self.find("confirm_blue")
                    and self.scene()
                    in (Scene.INFRA_ARRANGE_ORDER, Scene.RIIC_OPERATOR_SELECT)
                ):
                    self.require_agent_selection_page()
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    break
                self.sleep(min(profile.poll_interval, remaining))
        raise RecognizeError("未确认进入干员选人页，返回房间重试")

    def _wait_for_run_order_selection_page(self):
        """跑单入口未就绪时只观察，保留原按钮匹配和房间恢复。"""
        unready = (Scene.UNKNOWN, Scene.UNDEFINED, Scene.CONNECTING)
        scene = self.scene()
        if scene not in unready:
            return

        deadline = None
        network_waited = False
        while scene in unready:
            if scene == Scene.CONNECTING:
                if network_waited:
                    raise AgentSelectionNotReady("跑单选人页反复联网，返回房间重试")
                network_waited = True
                if not self.waiting_solver(restart_on_timeout=False):
                    raise AgentSelectionNotReady("跑单选人页联网等待超时，返回房间重试")
            else:
                if deadline is None:
                    profile = self.performance_profile
                    deadline = monotonic() + profile.transition_timeout
                    poll_interval = profile.poll_interval
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise AgentSelectionNotReady("跑单选人页场景仍未知，返回房间重试")
                self.sleep(min(poll_interval, remaining))
            scene = self.scene()

        if self.find("confirm_blue") is None:
            raise AgentSelectionNotReady("跑单选人页确认按钮已消失，返回房间重试")

    @staticmethod
    def _is_ordinary_facility_arrangement(task):
        return not getattr(task, "emergency_staffing", False) and getattr(
            task, "type", None
        ) not in (
            TaskTypes.RUN_ORDER,
            TaskTypes.FIAMMETTA,
            TaskTypes.WORKSHOP,
            TaskTypes.SKILL_UPGRADE,
            TaskTypes.SWAP_SUPPORT,
        )

    @staticmethod
    def _fiammetta_charge_target(task, room, agents):
        if (
            getattr(task, "type", None) == TaskTypes.FIAMMETTA
            and room.startswith("dormitory_")
            and isinstance(target := task.meta_data, str)
            and target not in ("", "_", "Current", "Free", "菲亚梅塔")
            and agents == [target, "菲亚梅塔"]
        ):
            return target

    @timed_room
    def agent_arrange_room(
        self,
        new_plan,
        room,
        plan,
        skip_enter=False,
        get_time=False,
        *,
        facility_observations=None,
    ):
        if room not in plan:
            return new_plan
        previous = getattr(self, "_active_facility_log", None)
        event = {
            "type": "facility-arrangement",
            "id": uuid4().hex,
            "phase": "started",
            "anchor": False,
            "room": room,
            "label": facility_label(room, self.op_data),
            "agents": [
                name for name in plan[room] if name not in ("", "_", "Current", "Free")
            ],
        }
        self._active_facility_log = event
        previous_scope = getattr(self, "_active_rescue_facility_scope", None)
        task = getattr(self, "task", None)
        task_type = getattr(task, "type", None)
        if (
            task_type == TaskTypes.RUN_ORDER
            and getattr(task, "meta_data", None) == room
            and not getattr(task, "run_order_collect_only", False)
            and not getattr(task, "run_order_restore_pending", False)
        ):
            order_agents = [
                name for name in event["agents"] if name in TRADE_ORDER_AGENTS
            ]
            if order_agents:
                event["run_order_agents"] = order_agents
        scope = self._rescue_staffing_log_parent(task, room, plan, event["id"])
        self._active_rescue_facility_scope = scope
        restoring_order = task_type == TaskTypes.RUN_ORDER and (
            getattr(task, "run_order_restore_pending", False)
            or room in getattr(task, "emergency_original_roster", {})
        )
        parent = scope
        if parent is None and (
            self._is_ordinary_facility_arrangement(task)
            or task_type == TaskTypes.FIAMMETTA
            or event.get("run_order_agents")
            or restoring_order
        ):
            parent = {"type": "facility-arrangement", "id": event["id"], "room": room}
        previous_idle = getattr(self, "_active_facility_idle_evidence", None)
        idle_evidence = {} if facility_observations is not None else None
        self._active_facility_idle_evidence = idle_evidence
        with log_parent_context(parent):
            try:
                result = self._arrange_room(new_plan, room, plan, skip_enter, get_time)
                if idle_evidence and "targets" in idle_evidence:
                    facility_observations[room] = (event["id"], idle_evidence)
                return result
            except BaseException as error:
                if scope is not None:
                    self._fail_rescue_staffing_log(self.task, str(error))
                raise
            finally:
                if event["phase"] == "started" and event["anchor"]:
                    event["phase"] = "failed"
                    event["anchor"] = False
                    self._log_facility_arrangement(event)
                    if scope is not None:
                        self._fail_rescue_staffing_log(self.task)
                self._prune_rescue_staffing_logs()
                if previous is None:
                    self.__dict__.pop("_active_facility_log", None)
                else:
                    self._active_facility_log = previous
                if previous_scope is None:
                    self.__dict__.pop("_active_rescue_facility_scope", None)
                else:
                    self._active_rescue_facility_scope = previous_scope
                if previous_idle is None:
                    self.__dict__.pop("_active_facility_idle_evidence", None)
                else:
                    self._active_facility_idle_evidence = previous_idle

    def _remember_facility_idle_origin(self, room, observed):
        evidence = getattr(self, "_active_facility_idle_evidence", None)
        event = getattr(self, "_active_facility_log", None)
        if (
            evidence is not None
            and "before" not in evidence
            and event is not None
            and event["room"] == room
        ):
            # 保留换人前的实读，后续临时阵容不覆盖原驻员。
            evidence["before"] = tuple(
                item["agent"] if item.get("observed", True) else None
                for item in observed
            )

    def _start_facility_arrangement_log(self, room, agents):
        event = getattr(self, "_active_facility_log", None)
        if (
            event is None
            or event["room"] != room
            or event["phase"] != "started"
            or event["anchor"]
        ):
            return
        event["label"] = facility_label(room, self.op_data)
        event["anchor"] = True
        event["agents"] = [
            name for name in agents if name not in ("", "_", "Current", "Free")
        ]
        self._start_rescue_staffing_log(getattr(self, "task", None), room, event["id"])
        if room == "train":
            positions = [
                {"agent": name, "index": index}
                for index, name in enumerate(agents)
                if name not in ("", "_", "Current", "Free")
            ]
            if positions:
                event["positions"] = positions
        if event.get("run_order_agents"):
            self._log_facility_arrangement(event)
            return
        target = self._fiammetta_charge_target(
            getattr(self, "task", None), room, agents
        )
        if target is not None:
            self._log_facility_arrangement(
                {
                    **event,
                    "summary": (
                        f"正在安排[[operator:菲亚梅塔]]为[[operator:{target}]]充能"
                        f"（{event['label']}）"
                    ),
                }
            )
            return
        logger.info(
            event["label"],
            extra={
                "log_event": copy.deepcopy(event),
                "log_room": room,
                "log_agents": list(event["agents"]),
            },
        )

    def _update_facility_arrangement_log(self, room, agents):
        event = getattr(self, "_active_facility_log", None)
        if (
            event is None
            or event["room"] != room
            or event["phase"] != "started"
            or not event["anchor"]
        ):
            return
        names = [name for name in agents if name not in ("", "_", "Current", "Free")]
        positions = (
            [
                {"agent": name, "index": index}
                for index, name in enumerate(agents)
                if name not in ("", "_", "Current", "Free")
            ]
            if room == "train"
            else None
        )
        if event["agents"] == names and event.get("positions") == (positions or None):
            return
        event["agents"] = names
        if positions:
            event["positions"] = positions
        else:
            event.pop("positions", None)
        # 名单更新沿用原入口；内部仍保持 started，等待读房确认完成。
        self._log_facility_arrangement({**event, "phase": "updated", "anchor": False})

    def _log_facility_arrangement(self, event):
        phase = event["phase"]
        order_agents = event.get("run_order_agents")
        if order_agents:
            if phase != "completed" or all(
                name in event["agents"] for name in order_agents
            ):
                names = "、".join(f"[[operator:{name}]]" for name in order_agents)
                prefix = {
                    "started": "正在",
                    "updated": "正在",
                    "completed": "已在",
                    "failed": "尚未确认在",
                }[phase]
                event["summary"] = f"{prefix} {event['label']} 安排 {names} 跑单"
            else:
                event.pop("summary", None)
        message = event.get("summary")
        if message is None:
            names = "、".join(f"[[operator:{name}]]" for name in event["agents"])
            if names:
                prefix = {
                    "started": "正在安排",
                    "updated": "正在安排",
                    "completed": "已安排",
                    "failed": "尚未确认",
                }[phase]
                if event.get("positions"):
                    message = (
                        prefix
                        + " "
                        + "、".join(
                            f"[[operator:{item['agent']}]] 进驻训练室"
                            + ("协助位" if item["index"] == 0 else "训练位")
                            for item in event["positions"]
                        )
                    )
                else:
                    message = f"{prefix} {names} 进驻 {event['label']}"
            else:
                prefix = {
                    "started": "正在调整",
                    "updated": "正在调整",
                    "completed": "已确认",
                    "failed": "尚未确认",
                }[phase]
                message = f"{prefix} {event['label']} 驻员安排"
        logger.info(
            message,
            extra={
                "log_event": copy.deepcopy(event),
                "log_room": event["room"],
                "log_agents": list(event["agents"]),
            },
        )

    def _confirm_facility_arrangement_log(
        self, room, agents, observed=None, *, unconfirmed=None
    ):
        event = getattr(self, "_active_facility_log", None)
        if (
            event is not None
            and event["room"] == room
            and event["phase"] == "started"
            and event["anchor"]
        ):
            event["phase"] = "failed" if unconfirmed else "completed"
            event["anchor"] = False
            event["agents"] = [
                name for name in agents if name not in ("", "_", "Current", "Free")
            ]
            task = getattr(self, "task", None)
            target = self._fiammetta_charge_target(task, room, agents)
            if unconfirmed:
                event.pop("run_order_agents", None)
                event["summary"] = f"{event['label']}：{unconfirmed}"
            elif (
                target is not None
                and observed is not None
                and len(observed) >= len(agents)
                and all(
                    item.get("observed", True) and item["agent"] == name
                    for item, name in zip(observed, agents)
                )
            ):
                event["summary"] = (
                    f"已在{event['label']}安排[[operator:菲亚梅塔]]充能[[operator:{target}]]"
                )
            if room == "train":
                positions = [
                    {"agent": name, "index": index}
                    for index, name in enumerate(agents)
                    if name not in ("", "_", "Current", "Free")
                ]
                if positions:
                    event["positions"] = positions
                else:
                    event.pop("positions", None)
            self._log_facility_arrangement(event)
            self._finish_rescue_staffing_room_log(task, room, event["id"])
            evidence = getattr(self, "_active_facility_idle_evidence", None)
            if evidence is not None:
                evidence["targets"] = tuple(agents)
                if observed is not None:
                    evidence["after"] = (
                        tuple(item["agent"] for item in observed)
                        if len(observed) == len(agents)
                        and all(item.get("observed", True) for item in observed)
                        else None
                    )

    def _arrange_room(
        self,
        new_plan,
        room,
        plan,
        skip_enter=False,
        get_time=False,
    ):
        self._prepare_group_shift_execution_targets(self.task)
        self._suppress_dispatchable_arrangement(self.task, plan)
        if room not in plan:
            return new_plan
        restoring_order = getattr(self.task, "run_order_restore_pending", False)
        finished = False
        # 延期重试也先读实际驻员，避免确认已成功却重复选人／充能。
        choose_error = int(
            getattr(self.task, "arrangement_retry_room", None) == room
            or room in getattr(self.task, "arrangement_failures", ())
        )
        retry_limit = 1 if room == "train" else 3
        checked = False
        reconcile_after_confirmation = False
        reconcile_after_selection = False
        submitted_training_slot = None
        allow_direct_recovery = True
        check_recovery_on_retry = False
        continued = None
        correction_observation = None
        while not finished:
            confirmation_pending = False
            selection_attempted = False
            selection_changed = True
            final_observation = None
            entry_intent = None
            departure_observed = False
            try:
                error_count = 0
                if not skip_enter:
                    self.enter_room(room)
                    if room == "train":
                        self.task.training_skipped_slots = set()
                        # 实读房态决定可换岗位；自动专精开启时顺路核对专精记录。
                        from arknights_mower.solvers.mastery_reader import (
                            _compute_protected,
                            read_room_state,
                            reconcile_short,
                        )

                        try:
                            room_state = read_room_state(self, enter=False)
                        except Exception as e:
                            logger.warning(f"训练室状态读取失败: {e}")
                            room_state = None
                        self.train_room_state = (
                            room_state if config.conf.mastery_enabled else None
                        )
                        if getattr(self.task, "emergency_staffing", False) and (
                            self._emergency_protect_training(plan, room_state)
                        ):
                            self.task.training_skipped_slots.update(
                                range(len(plan[room]))
                            )
                            self._emergency_protect_training(
                                self.emergency_state.setdefault("staffing_plan", {}),
                                room_state,
                            )
                            del plan[room]
                            self._prepare_group_shift_execution_targets(self.task)
                            self.back()
                            return new_plan
                        if config.conf.mastery_enabled:
                            if room_state is None:
                                from arknights_mower.solvers.mastery_reader import (
                                    RoomState,
                                )

                                self.train_room_state = RoomState(read_failed=True)
                            self.task.training_skipped_slots.update(
                                self._protected_training_slots()
                            )
                            self._suppress_dispatchable_arrangement(self.task, plan)
                            self._prepare_group_shift_execution_targets(self.task)
                            if room not in plan:
                                self.back()
                                return new_plan
                        if getattr(room_state, "amiya_form_waiting", False) is True:
                            self.task.training_skipped_slots.update(
                                range(len(plan[room]))
                            )
                            del plan[room]
                            self._prepare_group_shift_execution_targets(self.task)
                            self.back()
                            return new_plan
                        if room_state is not None and config.conf.mastery_enabled:
                            # #61 短动作排班路径内联：顺路核实/帮收/重置/更新状态，并据截图
                            # 修正 DB（空闲×DB active 冲突 → 重置 idle，以截图为准）。不
                            # 开始训练；退出训练室由本 gate 的跳过/冻结分支统一负责。
                            # #75 方案 C：defer_collect=True——待收取格若队列已有任一
                            # 专精任务则跳过收集（留给队列任务收，避免残留任务空闲房
                            # 触发开始训练）；队列空时照常收集兜底。
                            collected = False
                            try:
                                # #210：返回是否收集——收集后房间物理变空闲（面板全空），
                                # gate 用 ① 的槽位 + 状态设空闲 + 按空闲规则重算保护，
                                # 不再重读 read_room_state；没收集时状态/保护都没变。
                                collected = reconcile_short(
                                    self, room_state, defer_collect=True
                                )
                            except Exception as e:
                                logger.warning(f"训练室顺路更新状态失败: {e}")
                            if room_state.state == "waiting_collect" and collected:
                                if room_state.slots_read:
                                    # ① 在 TRAIN_MAIN 读过槽位（收集不挪人）→ 复用 +
                                    # 状态设空闲 + 按空闲规则重算保护（深读保留）
                                    room_state.state = "empty"
                                    room_state.protected = _compute_protected(
                                        self, room_state
                                    )
                                else:
                                    # ① 在 TRAIN_FINISH 横幅页首次进房，未读槽位 →
                                    # 收集后面板回到主页面，重读拿进驻数据 + 保护
                                    try:
                                        room_state = read_room_state(self, enter=False)
                                    except Exception:
                                        room_state = None
                                self.train_room_state = (
                                    room_state if config.conf.mastery_enabled else None
                                )
                        if config.conf.mastery_enabled:
                            self.task.training_skipped_slots.update(
                                self._protected_training_slots()
                            )
                            self._suppress_dispatchable_arrangement(self.task, plan)
                        elif room_state is None or room_state.locked:
                            # 未启用专精时也不能替换正在训练的训练位。
                            if len(plan[room]) > 1:
                                plan[room][1] = "Current"
                                self.task.training_skipped_slots.add(1)
                            if all(name == "Current" for name in plan[room]):
                                del plan[room]
                        self._prepare_group_shift_execution_targets(self.task)
                        if room not in plan:
                            self.back()
                            return new_plan
                skip_enter = False
                ordinary_work_room = self._ordinary_work_room(room)
                if not ordinary_work_room:
                    self.turn_on_room_detail(room)
                self._start_facility_arrangement_log(room, plan[room])
                if room == "recycle":
                    final_observation = self.get_agent_from_room(room)
                    self._suppress_dispatchable_arrangement(self.task, plan)
                    self._prepare_group_shift_execution_targets(self.task)
                    if room not in plan:
                        self.back()
                        return new_plan
                observation_context = (
                    {"expected_agents": plan[room]} if room.startswith("dorm") else {}
                )
                if room.startswith("room_") and self.task.type != TaskTypes.RUN_ORDER:
                    observation_context["observed_facilities"] = set()
                if restoring_order and getattr(
                    self.task, "run_order_confirmation_pending", None
                ):
                    # 旧换入的目标独立于恢复计划；旧原班不能证明换入已取消。
                    actual = self.get_agent_from_room(room)
                    self._verify_run_order_confirmation(room, actual, plan[room])
                if reconcile_after_confirmation:
                    refresh_indexes = []
                    if check_recovery_on_retry:
                        observation_context["read_dorm_evidence"] = True
                        if allow_direct_recovery:
                            observation_context["record_dorm_evidence"] = True
                    if (
                        room.startswith("dorm")
                        and self.task.type != TaskTypes.FIAMMETTA
                    ):
                        self.op_data.invalidate_dorm_time(room)
                        refresh_indexes = self.op_data.get_refresh_index(
                            room,
                            plan[room],
                            group_transitions=self._execution_group_transitions(plan),
                        )
                    observed = self.get_agent_from_room(
                        room, refresh_indexes, **observation_context
                    )
                    final_observation = observed
                    reconcile_after_confirmation = False
                    selection_was_attempted = reconcile_after_selection
                    reconcile_after_selection = False
                    if (
                        room not in getattr(self.task, "dorm_recovery_restore", ())
                        and self.task.type != TaskTypes.FIAMMETTA
                        and self._room_matches_arrangement(room, plan[room], observed)
                    ):
                        if check_recovery_on_retry:
                            from arknights_mower.utils.dorm_recovery import (
                                verify_final_recovery,
                            )

                            if verify_final_recovery(
                                self.op_data,
                                room,
                                plan[room],
                                observed,
                                group_transitions=self._execution_group_transitions(
                                    plan
                                ),
                                can_repair=allow_direct_recovery,
                                continued=continued,
                            ):
                                allow_direct_recovery = False
                                correction_observation = observed
                                skip_enter = True
                                continue
                        logger.info(f"{room} 确认后实际驻员已符合目标，结束排班")
                        self._complete_room_arrangement(
                            new_plan,
                            room,
                            plan,
                            observed=observed,
                        )
                        if selection_was_attempted:
                            self.record_selection_success()
                        finished = True
                        break
                error_count = 0
                if not checked:
                    roster = self.op_data.get_current_room(room, True)
                    if len(plan[room]) > len(roster):
                        extra = plan[room][len(roster) :]
                        message = (
                            f"{room} 排班超出当前设施的 {len(roster)} 个岗位：{extra}；"
                            "请检查主表、副表与游戏设施岗位数是否一致"
                        )
                        logger.error(message)
                        config.stop_mower.set()
                        raise MowerExit(message)
                    normal_order = (
                        self.task.type == TaskTypes.RUN_ORDER
                        and self.task.meta_data == room
                        and any(name in TRADE_ORDER_AGENTS for name in plan[room])
                        and not self._emergency_frozen()
                    )
                    if normal_order or getattr(
                        self.task, "run_order_restore_pending", False
                    ):
                        final_observation = self.get_agent_from_room(room)
                        actual = [
                            item["agent"] if item.get("observed", True) else ""
                            for item in final_observation
                        ]
                        if (
                            normal_order
                            and not getattr(
                                self.task, "run_order_restore_pending", False
                            )
                            and len(actual) == len(roster) == len(plan[room])
                            and actual
                            and len(set(actual)) == len(actual)
                            and all(
                                name not in ("", "Free", "Current") for name in actual
                            )
                            and all(
                                target == "Current" or target == current
                                for target, current in zip(plan[room], actual)
                            )
                        ):
                            self.task.__dict__.pop("run_order_staffing_wait", None)
                            logger.info("%s 实际驻员已符合跑单目标，直接处理订单", room)
                            self._confirm_facility_arrangement_log(
                                room, actual, final_observation
                            )
                            return new_plan
                        if normal_order and (
                            len(actual) != len(roster)
                            or not actual
                            or len(set(actual)) != len(actual)
                            or any(
                                name in ("", "Free", "Current", *TRADE_ORDER_AGENTS)
                                for name in actual
                            )
                        ):
                            logger.warning(
                                "%s 跑单前实际驻员不完整或仍含跑单干员：%s，先执行普通纠错",
                                room,
                                actual,
                            )
                            self.task.run_order_staffing_wait = True
                            self._retain_failed_task(
                                self.task,
                                "跑单等待实际驻员纠正",
                                [room],
                                dependency=True,
                            )
                            self.planned = False
                            self.back_to_infrastructure()
                            return False
                    if normal_order:
                        self.task.__dict__.pop("run_order_staffing_wait", None)
                    if (
                        self.task.type == TaskTypes.RUN_ORDER
                        and not getattr(self.task, "run_order_restore_pending", False)
                        and any(
                            any(char in item for item in plan[room])
                            for char in TRADE_ORDER_AGENTS
                        )
                        and not room.startswith("dormitory")
                        and room != "train"
                    ):
                        new_plan[room] = (
                            actual.copy()
                            if normal_order
                            else self.refresh_current_room(room)
                        )
                    if "菲亚梅塔" in plan[room] and len(plan[room]) == 2:
                        new_plan[room] = self.refresh_current_room(room)
                        target = self.op_data.operators[plan[room][0]]
                        working_room = (
                            target.current_room
                            if self._emergency_frozen()
                            else target.room
                        )
                        if working_room and working_room != room:
                            new_plan[working_room] = self.op_data.get_current_room(
                                working_room, True
                            )
                    if room != "train" and (
                        "Current" in plan[room] or "" in plan[room]
                    ):
                        if "Current" in plan[room]:
                            if final_observation is None:
                                # 解析 Current 本来就要读房。把原床目标的到满时间一起读出，
                                # 已经转移时可直接安排纠正，避免先提交一次已知给错的名单。
                                if (
                                    room.startswith("dorm")
                                    and self.task.type != TaskTypes.FIAMMETTA
                                    and not getattr(
                                        self.task, "simple_dorm_fill", False
                                    )
                                ):
                                    intended = [
                                        old if n == "Current" else n
                                        for old, n in zip(roster, plan[room])
                                    ]
                                    continued = continuing_roommate(
                                        self.op_data, room, intended
                                    )
                                    if continued:
                                        observation_context["read_dorm_evidence"] = True
                                        entry_intent = (tuple(intended), continued)
                                if room.startswith("dorm") and get_time:
                                    self.op_data.invalidate_dorm_time(room)
                                final_observation = self.get_agent_from_room(
                                    room,
                                    departing_plan=plan[room],
                                    **observation_context,
                                )
                                departure_observed = not room.startswith("dorm")
                                self._remember_facility_idle_origin(
                                    room, final_observation
                                )
                            _current_room = self._observed_room_names(
                                room, final_observation, len(plan[room])
                            )
                            if _current_room != roster:
                                entry_intent = None
                        for current_idx, _name in enumerate(plan[room]):
                            if _name == "Current":
                                plan[room][current_idx] = (
                                    _current_room[current_idx]
                                    if _current_room[current_idx] != ""
                                    else "Free"
                                )
                            if _name == "" and not (
                                getattr(self.task, "emergency_staffing", False)
                                or getattr(self.task, "emergency_dorm", False)
                                or (room, current_idx)
                                in getattr(
                                    self.task, "backup_retention_empty_slots", {}
                                )
                                or (
                                    self._emergency_frozen()
                                    and self.task.type
                                    in (TaskTypes.RUN_ORDER, TaskTypes.FIAMMETTA)
                                )
                            ):
                                plan[room][current_idx] = "Free"
                    if (
                        room in self.op_data.run_order_rooms
                        and len(new_plan) == 0
                        and self.task.type != TaskTypes.RUN_ORDER
                    ):
                        if plan[room] != self.op_data.get_current_room(room):
                            self.refresh_run_order_time(room)
                self._update_facility_arrangement_log(room, plan[room])
                checked = True
                confirmation_pending = True
                dorm_mood_candidates = None
                if room.startswith("dorm"):
                    dorm_mood_candidates = self.prepare_dorm_selection(plan[room], room)
                marked_recovery = False
                previous_roommate = getattr(self.task, "dorm_roommate_targets", {}).get(
                    room
                )
                if (
                    room.startswith("dorm")
                    and self.task.type != TaskTypes.FIAMMETTA
                    and not getattr(self.task, "simple_dorm_fill", False)
                ):
                    # 同一原任务可能在确认后重登。只保存要核对谁，归属仍由新名单实读决定。
                    continued = continuing_roommate(
                        self.op_data,
                        room,
                        plan[room],
                        previous=entry_intent or previous_roommate,
                    )
                    remember_roommate_target(self.task, room, plan[room], continued)
                    marked_recovery = continued is not None or any(
                        getattr(self.op_data.operators.get(n), "dorm_recovery_room", "")
                        == room
                        for n in plan[room]
                    )
                recovery = self.ensure_dorm_recovery_order(
                    room,
                    plan[room],
                    fast_mode=choose_error <= 0,
                    allow_direct=allow_direct_recovery,
                    correction_observation=correction_observation
                    or (
                        final_observation
                        if continued and observation_context.get("read_dorm_evidence")
                        else None
                    ),
                    continued=continued,
                )
                correction_observation = None
                recovery_ordered = bool(recovery)
                check_recovery_on_retry = marked_recovery or isinstance(
                    recovery, (DirectDormArrival, list)
                )
                if isinstance(recovery, DirectDormArrival):
                    final_observation = recovery.observed
                    departure_observed = dorm_departures_sampled(
                        final_observation, plan[room]
                    )
                elif isinstance(recovery, list):
                    final_observation = recovery
                    departure_observed = dorm_departures_sampled(recovery, plan[room])
                can_correct_recovery = allow_direct_recovery and (
                    isinstance(recovery, DirectDormArrival)
                    or marked_recovery
                    and not recovery
                )
                if check_recovery_on_retry:
                    observation_context["read_dorm_evidence"] = True
                if can_correct_recovery:
                    # 同帧心情条已经读出，记下采样，纠正前离宿者无需再读一遍。
                    observation_context["record_dorm_evidence"] = True
                read_time_index = []
                related_operators = {}
                fia_arrangement = (
                    self.task is not None
                    and self.task.type == TaskTypes.FIAMMETTA
                    and "菲亚梅塔" in plan[room]
                )
                if fia_arrangement:
                    fia_index = plan[room].index("菲亚梅塔")
                    # 菲亚梅塔的读数代表目标交换前心情；目标自身的
                    # 读数代表交换后心情，两点在历史曲线上相差一秒。
                    read_time_index.append(fia_index)
                    if self.task is not None and self.task.meta_data:
                        related_operators[fia_index] = self.task.meta_data
                        if self.task.meta_data in plan[room]:
                            read_time_index.append(
                                plan[room].index(self.task.meta_data)
                            )
                    read_time_index = sorted(set(read_time_index))
                    logger.debug("准备读取菲亚梅塔与充能目标交换后的心情")
                elif get_time or recovery_ordered:
                    recovery_context = (
                        {"group_transitions": self._execution_group_transitions(plan)}
                        if room.startswith("dorm")
                        else {}
                    )
                    refresh_indexes = self.op_data.get_refresh_index(
                        room,
                        plan[room],
                        **recovery_context,
                    )
                    if recovery_ordered:
                        refresh_indexes = sorted(
                            set(refresh_indexes)
                            | {
                                i
                                for i, slot in enumerate(self.op_data.plan[room])
                                if slot.agent == "Free"
                            }
                        )
                    if (
                        getattr(self.task, "emergency_dorm", False)
                        and "菲亚梅塔" in plan[room]
                    ):
                        refresh_indexes = sorted(
                            set(refresh_indexes) | {plan[room].index("菲亚梅塔")}
                        )
                    read_time_index = list(
                        dict.fromkeys([*read_time_index, *refresh_indexes])
                    )

                current_room = self.op_data.get_current_room(room, True)
                if choose_error and len(new_plan) > 1:
                    self.op_data.operators["菲亚梅塔"].time_stamp = None
                    self.op_data.operators[plan[room][0]].time_stamp = None
                if choose_error and related_operators:
                    final_observation = self.get_agent_from_room(
                        room, read_time_index, related_operators, **observation_context
                    )
                elif final_observation is None and (
                    choose_error
                    or previous_roommate
                    and previous_roommate[0] == tuple(plan[room])
                    or current_room == plan[room]
                    or not fia_arrangement
                    and current_room
                    == plan[room] + [""] * (len(current_room) - len(plan[room]))
                ):
                    if (
                        room.startswith("dorm")
                        and not fia_arrangement
                        and (choose_error or get_time)
                    ):
                        self.op_data.invalidate_dorm_time(room)
                        read_time_index = self.op_data.get_refresh_index(
                            room,
                            plan[room],
                            group_transitions=self._execution_group_transitions(plan),
                        )
                    final_observation = self.get_agent_from_room(
                        room, read_time_index, **observation_context
                    )
                if submitted_training_slot is not None:
                    index, target = submitted_training_slot
                    if (
                        index < len(plan[room])
                        and plan[room][index] == target
                        and not self._training_slot_matches(
                            index, target, final_observation[index]["agent"]
                        )
                    ):
                        raise TrainingSubmissionUnconfirmed(index, target)
                    submitted_training_slot = None
                same = final_observation is not None and self._room_matches_arrangement(
                    room, plan[room], final_observation
                )
                if choose_error and same:
                    confirmed_names = [
                        name
                        for name in plan[room]
                        if name not in ("Free", "Current", "")
                    ]
                    label = facility_label(room, self.op_data)
                    logger.debug("%s重试复核计划：%s", label, plan[room])
                    result = (
                        f"{'、'.join(f'[[operator:{name}]]' for name in confirmed_names)}"
                        "已在计划位置，跳过重复选人"
                        if confirmed_names
                        else "按当前计划无需重复选人"
                    )
                    logger.info(
                        f"重试时重新读取{label}：{result}",
                        extra={"log_room": room, "log_agents": confirmed_names},
                    )
                if (
                    not same
                    and (
                        self._emergency_active()
                        and room.startswith("dorm")
                        and self.task.type == TaskTypes.RELEASE_DORM
                        and getattr(self.task, "strict_mood_limit", False)
                        or self._can_refresh_idle_dorm_search()
                        and self.task.type != TaskTypes.RUN_ORDER
                        and room != "train"
                        or fia_arrangement
                    )
                    and (
                        fia_arrangement
                        or not departure_observed
                        and (
                            final_observation is None
                            or any(
                                not item.get("observed", True)
                                or item["agent"]
                                and item["agent"] not in plan[room]
                                for item in final_observation
                            )
                        )
                    )
                ):
                    before = self.get_agent_from_room(
                        room, departing_plan=plan[room], **observation_context
                    )
                    self._remember_facility_idle_origin(room, before)
                    if (
                        not fia_arrangement
                        and len(before) >= len(current_room)
                        and all(item.get("observed", True) for item in before)
                        and self._room_matches_arrangement(room, plan[room], before)
                    ):
                        same = True
                        if room.startswith("dorm") and get_time:
                            self.op_data.invalidate_dorm_time(room)
                            before = self.get_agent_from_room(
                                room, read_time_index, **observation_context
                            )
                            same = self._room_matches_arrangement(
                                room, plan[room], before
                            )
                        final_observation = before
                if not same:
                    # 换入前校准确认时刻；窗口失败后的新实测仍须重新校准。
                    if (
                        self.task.type == TaskTypes.RUN_ORDER
                        and not self.task.adjusted
                        and len(new_plan) == 1
                        and config.conf.run_order_buffer_time > 0
                        and (
                            choose_error <= 0
                            or not getattr(
                                self.task, "run_order_restore_pending", False
                            )
                        )
                    ):
                        remaining_time = self.get_order_remaining_time()
                        if (
                            0
                            < remaining_time
                            < run_order_entry_seconds(self.task, config.conf) + 600
                        ):
                            calibrated = (
                                datetime.now()
                                + timedelta(seconds=remaining_time)
                                - timedelta(
                                    seconds=run_order_entry_seconds(
                                        self.task, config.conf
                                    )
                                )
                            )
                            if self.task.retains_execution:
                                self.task.run_order_calibrated_time = calibrated
                            else:
                                self.task.time = calibrated
                            logger.info(f"订单倒计时 {remaining_time}秒")
                            self.back()
                            self.turn_on_room_detail(room)
                        else:
                            self._report_missed_order(room, remaining_time)
                            raise RunOrderMissed(room)
                    if room == "train":
                        # #59：idx1 冻结已在 gate L1 按锁定状态处理好（Current），
                        # 不再依赖 find_next_task(SKILL_UPGRADE) 的脆弱信号。
                        selection_attempted = True
                        self.choose_train(
                            plan[room],
                            fast_mode=choose_error <= 0,
                            choose_error=choose_error,
                        )
                    else:
                        fresh_room_entry = False
                        two_slot_room = False
                        while self.find("confirm_blue") is None:
                            if error_count > 3:
                                raise Exception("未成功进入干员选择界面")
                            if ordinary_work_room and error_count == 0:
                                self.turn_on_room_detail(room)
                            if room.startswith("room") and len(plan[room]) == 2:
                                two_slot_room = (
                                    room_shows_two_slots(
                                        getattr(self.recog, "_img", None)
                                    )
                                    and self.detect_room() == room
                                )
                            if self._is_ordinary_facility_arrangement(self.task):
                                self._open_room_selection(room)
                            else:
                                self.tap((self.recog.w * 0.82, self.recog.h * 0.2))
                            error_count += 1
                            fresh_room_entry = True
                        # 跑单及原班恢复等待未知／联网画面结束，再开始选人。
                        if self.task.type == TaskTypes.RUN_ORDER:
                            self._wait_for_run_order_selection_page()
                        elif self.scene() == Scene.UNDEFINED:
                            raise RecognizeError("选人页场景观测已失效，返回房间重试")
                        if normal_order and not getattr(
                            self.task, "run_order_restore_pending", False
                        ):
                            self.task.run_order_original_roster = copy.deepcopy(
                                new_plan
                            )
                            self.task.run_order_restore_pending = True
                        selection_attempted = True
                        selection_product = None
                        if (
                            ordinary_work_room
                            and fresh_room_entry
                            and room
                            in observation_context.get("observed_facilities", ())
                        ):
                            selection_product = self.op_data.facility_states.get(
                                room, {}
                            ).get("product")
                        selection_changed = (
                            self.choose_agent(
                                plan[room],
                                room,
                                fast_mode=choose_error <= 0,
                                preserve_dorm_occupants=recovery_ordered,
                                choose_error=choose_error,
                                dorm_mood_candidates=dorm_mood_candidates,
                                fresh_room_entry=fresh_room_entry,
                                two_slot_room=two_slot_room,
                                selection_product=selection_product,
                            )
                            is not False
                        )
                        if selection_changed:
                            confirmation_pending = True
                            self._prepare_run_order_confirmation(room, plan[room])
                            self.tap_confirm(room, new_plan)
                    if room.startswith("dorm") and not fia_arrangement:
                        # 放弃暂选不改变同住加成，保留现有恢复计时。
                        if selection_changed:
                            self.op_data.invalidate_dorm_time(room)
                        read_time_index = self.op_data.get_refresh_index(
                            room,
                            plan[room],
                            group_transitions=self._execution_group_transitions(plan),
                        )
                    if len(new_plan) > 1:
                        self.op_data.operators["菲亚梅塔"].time_stamp = None
                        self.op_data.operators[plan[room][0]].time_stamp = None
                    with self._read_run_order_confirmation():
                        if related_operators:
                            current = self.get_agent_from_room(
                                room,
                                read_time_index,
                                related_operators,
                                **observation_context,
                            )
                        else:
                            current = self.get_agent_from_room(
                                room, read_time_index, **observation_context
                            )
                    current = self._verify_run_order_confirmation(
                        room, current, plan[room]
                    )
                    if not self._room_matches_arrangement(room, plan[room], current):
                        logger.error(
                            "房间 %s 实读驻员 %s，目标 %s",
                            room,
                            [item["agent"] for item in current],
                            plan[room],
                        )
                        raise Exception("检测到安排干员未成功")
                    final_observation = current
                elif choose_error == 0:
                    logger.info(f"任务与当前房间相同，跳过安排{room}人员")
                if check_recovery_on_retry and final_observation:
                    from arknights_mower.utils.dorm_recovery import (
                        verify_final_recovery,
                    )

                    if verify_final_recovery(
                        self.op_data,
                        room,
                        plan[room],
                        final_observation,
                        continued=continued,
                        group_transitions=self._execution_group_transitions(plan),
                        can_repair=can_correct_recovery,
                        attempted=room
                        in getattr(self.task, "dorm_recovery_restore", ()),
                    ):
                        # 读数能证明单回给错了人才修复；一次最终安排最多补一次常规排序。
                        allow_direct_recovery = False
                        correction_observation = final_observation
                        skip_enter = True
                        continue
                if self.scene() in self.waiting_scene:
                    if not self.waiting_solver():
                        return
                self._complete_room_arrangement(
                    new_plan,
                    room,
                    plan,
                    settle_entry=choose_error == 0 and not selection_attempted,
                    observed=final_observation,
                )
                if selection_attempted or choose_error > 0:
                    self.record_selection_success()
                finished = True
            except (
                MowerExit,
                DeviceRecoveryError,
                SharedADBError,
                RoomArrangementDeferred,
                MoodArrangementChanged,
                ProductSwitchDeferred,
                RunOrderMissed,
                RunOrderConfirmationUnresolved,
                WorkshopSelectionBlocked,
            ):
                raise
            except Exception as e:
                correction_observation = None
                skip_enter = False
                if isinstance(e, TrainingSubmissionUnconfirmed):
                    submitted_training_slot = e.slot
                pending = getattr(self.task, "run_order_confirmation_pending", None)
                if pending and not pending["submitted"]:
                    self.task.__dict__.pop("run_order_confirmation_pending", None)
                save_exception(e)
                logger.exception(e)
                record_selection_retry()
                if selection_attempted and (
                    isinstance(e, AgentSelectionNotReady)
                    or "检测到干员选择错误" in str(e)
                    or "检测到安排干员未成功" in str(e)
                    or (isinstance(e, RecognizeError) and str(e).startswith("干员确认"))
                ):
                    self.record_selection_failure()
                if (
                    getattr(self.task, "run_order_restore_pending", False)
                    and self.task.meta_data
                    and not restoring_order
                ):
                    # 首次换入失败交回任务补偿边界，后续只恢复实测原班。
                    raise
                choose_error += 1
                self.recog.update()
                if confirmation_pending:
                    reconcile_after_confirmation = True
                    reconcile_after_selection = selection_attempted
                # 跑单和肥鸭有临时换入／恢复的连续步骤，保留原有原地重试。
                queued = (
                    self.task is not None
                    and self.task.type
                    not in (
                        TaskTypes.RUN_ORDER,
                        TaskTypes.FIAMMETTA,
                        TaskTypes.SKILL_UPGRADE,
                        TaskTypes.SWAP_SUPPORT,
                    )
                    and any(task is self.task for task in getattr(self, "tasks", []))
                )
                blocked_orders = (
                    blocked_run_order_ids(self.tasks, self.op_data) if queued else set()
                )
                urgent = (
                    queued
                    and not getattr(self.task, "dorm_recovery_restore", [])
                    and any(
                        task is not self.task
                        and id(task) not in blocked_orders
                        and task.type
                        in (
                            TaskTypes.FIAMMETTA,
                            TaskTypes.RUN_ORDER,
                            TaskTypes.SWAP_SUPPORT,
                            TaskTypes.SKILL_UPGRADE,
                        )
                        and task.time <= datetime.now() + timedelta(minutes=1)
                        for task in self.tasks
                    )
                )
                if queued:
                    deferred = RoomArrangementDeferred(
                        room, e, submitted_training_slot=submitted_training_slot
                    )
                    if (
                        isinstance(e, TraineeCardUnavailable)
                        and self._is_ordinary_facility_arrangement(self.task)
                        and submitted_training_slot is None
                    ):
                        deferred.training_selection_wait = e.selection_wait(
                            self, self.task
                        )
                    if (
                        choose_error > retry_limit
                        or urgent
                        or (deferred.training_selection_wait or {}).get("source")
                    ):
                        raise deferred from e
                if choose_error > retry_limit:
                    raise e
                # 确认后的失败统一返回再读实际驻员，由下一轮决定是否重选。
                back_count = 0
                while (scene := self.scene()) != Scene.INFRA_MAIN:
                    if scene in self.waiting_scene:
                        if not self.waiting_solver():
                            self.back_to_infrastructure()
                            if self.scene() != Scene.INFRA_MAIN:
                                if queued:
                                    raise deferred from e
                                raise e
                            break
                    else:
                        self.back(interval=0.5)
                    back_count += 1
                    if back_count > 3:
                        if queued:
                            raise deferred from e
                        raise e
                continue
        return new_plan

    def _complete_room_arrangement(
        self,
        new_plan,
        room,
        plan,
        *,
        settle_entry=False,
        observed=None,
    ):
        # 收尾返回仍属本轮安排；超时交回房间恢复，实读复核后再提交完成。
        keep_workshop = room == "factory" and (
            getattr(self, "_workshop_room_handoff", False) is True
        )
        if not keep_workshop and (
            len(new_plan) != 1 or config.conf.run_order_buffer_time <= 0
        ):
            early_feedback = room != "train" and self._is_ordinary_facility_arrangement(
                self.task
            )
            deadline = None
            should_exit = True
            if settle_entry and (room == "central" or room.startswith("room_")):
                # 返回前复核当前房间，和退出确认共用一次预算。
                deadline = monotonic() + self.performance_profile.transition_timeout
                should_exit = self._wait_for_room_entry_before_exit(
                    room, deadline=deadline
                )
            if should_exit:
                interval = 0.5
                if early_feedback:
                    profile = self.performance_profile
                    if deadline is None:
                        deadline = monotonic() + profile.transition_timeout + interval
                    interval = min(interval, 0.75 * profile.screenshot_interval / 1000)
                self.back(interval)
                self._wait_for_room_exit(
                    deadline=deadline, early_feedback=early_feedback
                )
        remember_roommate_target(self.task, room)
        if room in getattr(self.task, "dorm_recovery_restore", []):
            self.task.dorm_recovery_restore.remove(room)
        if getattr(self.task, "arrangement_retry_room", None) == room:
            del self.task.arrangement_retry_room
            del self.task.arrangement_retry_count
        self._confirm_facility_arrangement_log(room, plan[room], observed)
        if observed and getattr(self, "_release_dorm_readings", None) is not None:
            self._release_dorm_readings[room] = observed
        if (
            room.startswith("dorm")
            and getattr(self.op_data, "idle_dorm_release_suspended", False)
            and room in getattr(self.task, "idle_dorm_search_names", {})
        ):
            # 本次保留或补位自己的读回属于暂停收尾，不能用来立即解除暂停。
            self.op_data.idle_dorm_release_observations = dict(
                self.op_data.room_observations
            )
        del plan[room]

    def _wait_for_room_entry_before_exit(self, room, *, deadline):
        """跳过换人时，一次新帧确认目标房间即可返回。"""
        poll_interval = self.performance_profile.screenshot_interval / 1000
        while True:
            self.recog.update()
            scene = self.scene()
            if scene == Scene.INFRA_MAIN:
                return False
            confirmed = (
                scene in (Scene.INFRA_DETAILS, Scene.CTRLCENTER_ASSISTANT)
                and self.detect_room() == room
            )
            remaining = deadline - monotonic()
            if remaining <= 0:
                raise RecognizeError("返回前未确认目标房间，保留本房间安排")
            if confirmed:
                return True
            self.sleep(min(poll_interval, remaining))

    def _wait_for_room_exit(self, *, deadline=None, early_feedback=False):
        """确认已发送的返回键生效，再把地图交给下一次房间操作。"""
        profile = self.performance_profile
        if deadline is None:
            deadline = monotonic() + profile.transition_timeout
        while True:
            self.recog.update()
            if self.scene() == Scene.INFRA_MAIN:
                return
            remaining = deadline - monotonic()
            if remaining <= 0:
                raise RecognizeError("换人后未确认返回基建全局视角")
            poll_interval = (
                profile.poll_interval
                if early_feedback
                else profile.screenshot_interval / 1000
            )
            self.sleep(min(poll_interval, remaining))

    def accept_order(self, *, room=None):
        task = getattr(self, "task", None)
        if task is not None and task.type == TaskTypes.RUN_ORDER and task.meta_data:
            self._cache_facility_state_from_current_page(task.meta_data, "trade")
            if room is None:
                room = task.meta_data
        log_room = room
        if not isinstance(log_room, str) or not re.fullmatch(
            r"room_[1-3]_[1-3]", log_room
        ):
            log_room = getattr(self, "last_room", "")
        label = (
            facility_label(log_room, getattr(self, "op_data", None))
            if isinstance(log_room, str) and re.fullmatch(r"room_[1-3]_[1-3]", log_room)
            else "贸易站"
        )
        log_extra = (
            {"log_room": log_room}
            if isinstance(log_room, str) and re.fullmatch(r"room_[1-3]_[1-3]", log_room)
            else {}
        )
        wait = 0
        # 等待订单完成
        while self.find("order_ready", scope=((450, 675), (600, 750))) is None:
            if wait > 6:
                break
            self.recog.update()
            self.sleep(0.5)
            wait += 1
        not_take = not getattr(task, "run_order_collect_only", False)
        collected = False
        while self.find("order_ready", scope=((450, 675), (600, 750))) is not None:
            if not_take:
                # 动画过渡防抖：若首帧已充分定格则直接放行，否则最多等待 2 次采样 (~0.3s)
                scores = self.order_reader.get_buff_scores(self.recog.img)
                if not self.order_reader.has_distinct_buff(scores):
                    for _ in range(2):
                        self.sleep(0.15)
                        self.recog.update()
                        new_scores = self.order_reader.get_buff_scores(self.recog.img)
                        if self.order_reader.has_distinct_buff(
                            new_scores
                        ) or self.order_reader.is_stable(scores, new_scores):
                            break
                        scores = new_scores

                self.recog.save_screencap("run_order")
                if room:
                    room_label = (
                        self.translate_room(room)
                        if room in base_room_list
                        else str(room)
                    )
                    self.order_reader.save(
                        self.recog.img,
                        room=room_label,
                        screenshot_source=getattr(self, "device", None),
                        log_group="base-scheduler",
                    )
                else:
                    self.order_reader.save(self.recog.img, log_group="base-scheduler")
                not_take = False
            if not collected:
                logger.info(f"{label}：正在收取订单", extra=log_extra)
            self.tap((self.recog.w * 0.25, self.recog.h * 0.25), interval=0.5)
            collected = True
        logger.info(
            f"{label}：" + ("已收取订单" if collected else "未识别到可收取订单"),
            extra=log_extra,
        )

    def _can_refresh_idle_dorm_search(self):
        return (
            not getattr(self, "defer_backup_plan_until_mood_read", False)
        ) and getattr(self.task, "type", None) != TaskTypes.FIAMMETTA

    def _track_idle_dorm_shift(self, plan):
        """任务首次执行时记录成组下班者，延期重试沿用同一份名单。"""
        if (
            not self._can_refresh_idle_dorm_search()
            or self.task.type
            not in (
                TaskTypes.SHIFT_OFF,
                TaskTypes.EXHAUST_OFF,
                TaskTypes.SELF_CORRECTION,
                TaskTypes.RE_ORDER,
            )
            or hasattr(self.task, "idle_dorm_shift_groups")
        ):
            return
        groups = {}
        for room, names in plan.items():
            if not room.startswith("dorm"):
                continue
            for name in names:
                op = self.op_data.operators.get(name)
                if (
                    op is not None
                    and op.group
                    and op.is_high()
                    and not op.room.startswith("dorm")
                    and not op.workaholic
                    and not op.is_resting()
                ):
                    groups.setdefault(op.group, set()).add(name)
        self.task.idle_dorm_shift_groups = {
            group: names for group, names in groups.items() if len(names) >= 2
        }

    def _finish_idle_dorm_shift(self):
        if not self._can_refresh_idle_dorm_search():
            return
        groups = getattr(self.task, "idle_dorm_shift_groups", {})
        completed = [
            group
            for group, names in groups.items()
            if all(
                (op := self.op_data.operators.get(name)) is not None and op.is_resting()
                for name in names
            )
        ]
        if completed:
            self.op_data.refresh_idle_dorm_search(
                reason=f"成组下班已完成：{', '.join(completed)}",
                names={name for group in completed for name in groups[group]},
            )
            for group in completed:
                del groups[group]

    def _retain_run_order_restoration(self, *, failure=None):
        """保留实测原班，后续调度仅恢复驻员，不重复插拔。"""
        self.task.prepare_run_order_restoration()
        pending = getattr(self.task, "run_order_confirmation_pending", None)
        if pending and not pending["submitted"]:
            self.task.__dict__.pop("run_order_confirmation_pending", None)
            pending = None
        if pending and pending["exhausted"]:
            failure = str(RunOrderConfirmationUnresolved(pending["room"]))
        if failure is not None:
            self._retain_failed_task(
                self.task, failure, self.task.plan, dependency=bool(pending)
            )
        if not any(task is self.task for task in self.tasks):
            self.tasks.append(self.task)
        return False

    def _should_prepare_run_order_dorm(self, room):
        task = self.task
        conf = config.conf
        if task.adjusted:
            return True
        if conf.run_order_buffer_time <= 0:
            return False
        start = getattr(task, "run_order_calibrated_time", task.time)
        confirm_at = start + timedelta(
            seconds=run_order_entry_seconds(task, conf)
            - run_order_buffer_seconds(task, conf)
        )
        preparation = timedelta(
            minutes=estimate_dorm_minutes(room) + estimate_work_minutes(task.meta_data)
        )
        return datetime.now() + preparation < confirm_at

    def _prepare_run_order_dorm_departures(self, plan):
        """跑单先替换宿舍中的换入者，避免连续跑单长期留下空床。"""
        task = self.task
        if (
            task.type != TaskTypes.RUN_ORDER
            or not task.meta_data
            or getattr(task, "run_order_restore_pending", False)
        ):
            return True
        targets = set(plan.get(task.meta_data, ())) & set(TRADE_ORDER_AGENTS)
        source_slots = {}
        for name in targets:
            op = self.op_data.operators.get(name)
            if op is not None and op.current_room.startswith("dorm"):
                positions = source_slots.setdefault(op.current_room, set())
                if op.current_index >= 0:
                    positions.add(op.current_index)
        pending = getattr(task, "run_order_dorm_slots", {})
        saved_plan = getattr(task, "run_order_dorm_plan", {})
        rooms = source_slots.keys() | pending.keys() | saved_plan.keys()
        if rooms:
            task.__dict__.pop("run_order_staffing_wait", None)
        for room in sorted(rooms):
            if (
                room not in pending
                and room not in saved_plan
                and not self._should_prepare_run_order_dorm(room)
            ):
                logger.info(
                    "本次跑单跳过%s补位，直接前往%s",
                    self.translate_room(room),
                    self.translate_room(task.meta_data),
                    extra={"log_room": room},
                )
                continue
            slots = pending.setdefault(room, set())
            slots.update(source_slots.get(room, ()))
            task.run_order_dorm_slots = pending
            try:
                self.enter_room(room)
                self.turn_on_room_detail(room)
                observed = self.get_agent_from_room(room, strict_observation=True)
                actual = [item["agent"] for item in observed]
                if len(actual) != len(self.op_data.plan[room]) or any(
                    not item.get("observed", True) for item in observed
                ):
                    raise RecognizeError("跑单前宿舍实际驻员未读完整")
                slots.update(
                    index for index, name in enumerate(actual) if name in targets
                )
                departing = [
                    index
                    for index in slots
                    if 0 <= index < len(actual) and actual[index] in targets | {""}
                ]
                if not departing and room not in saved_plan:
                    pending.pop(room)
                    self.back()
                    self._wait_for_room_exit()
                    continue
                if room not in saved_plan:
                    row = actual.copy()
                    for index in departing:
                        row[index] = "Free"
                    saved_plan[room] = row
                row = saved_plan[room]
                task.run_order_dorm_plan = saved_plan
                task.execution_retained = True
                dorm_plan = {room: row}
                logger.info("跑单前先补位 %s 的宿舍床位", room)
                result = self.agent_arrange_room({}, room, dorm_plan, skip_enter=True)
                if result is False or result is None:
                    return False
                self.enter_room(room)
                observed = self.get_agent_from_room(
                    room, strict_observation=True, expected_agents=row
                )
                current = [item["agent"] for item in observed]
                if len(current) != len(row) or any(
                    not item.get("observed", True) for item in observed
                ):
                    raise RecognizeError("跑单前宿舍最终驻员未核实")
                if any(
                    name != "Current"
                    and (
                        not current[index] if name == "Free" else current[index] != name
                    )
                    for index, name in enumerate(row)
                ):
                    raise AgentSelectionNotReady("跑单前宿舍完整恢复阵容未确认")
                if any(
                    index >= len(current) or current[index] in targets | {""}
                    for index in departing
                ):
                    raise AgentSelectionNotReady("跑单前未确认宿舍床位已由其他干员补齐")
                self.back(0.5)
                self._wait_for_room_exit()
                pending.pop(room)
                saved_plan.pop(room)
            except (
                MowerExit,
                DeviceRecoveryError,
                SharedADBError,
                RoomArrangementDeferred,
            ):
                raise
            except Exception as exc:
                raise RoomArrangementDeferred(room, exc) from exc
        task.__dict__.pop("run_order_dorm_slots", None)
        task.__dict__.pop("run_order_dorm_plan", None)
        return True

    def _log_facility_idle_results(self, observations):
        if any(
            (actual := self.op_data.get_current_operator(room, index)) is None
            or actual.name != name
            for (room, index), name in getattr(
                self.task, "group_shift_expected", {}
            ).items()
        ):
            return
        destinations = set()
        for _, evidence in observations.values():
            final = evidence.get("after", evidence["targets"])
            if final is None or any(name in ("Current", "Free", "_") for name in final):
                return
            if "after" not in evidence and "" in final:
                return
            destinations.update(final)
        for room, (attempt, evidence) in observations.items():
            before, after = evidence.get("before", ()), evidence.get("after")
            if after is None or len(before) != len(after):
                continue
            agents = [
                name
                for name, replacement in zip(before, after)
                if name
                and replacement
                and name not in destinations
                and before.count(name) == 1
                and (operator := self.op_data.operators.get(name)) is not None
                and (operator.current_room, operator.current_index) == ("", -1)
            ]
            if not agents:
                continue
            names = "、".join(f"[[operator:{name}]]" for name in agents)
            logger.info(
                f"已确认 {names} 转为空闲",
                extra={
                    "log_room": room,
                    "log_agents": agents,
                    "log_event": {
                        "type": "facility-idle",
                        "id": attempt,
                        "room": room,
                        "agents": agents,
                    },
                    "log_parent": {
                        "type": "facility-arrangement",
                        "id": attempt,
                        "room": room,
                    },
                },
            )

    @with_run_order_network
    def agent_arrange(self, plan: tp.BasePlan, get_time=False):
        self._profession_search_pages = {}
        if (
            self.task.type == TaskTypes.FIAMMETTA
            and self.task.meta_data
            and len(plan) == 1
            and next(iter(plan.values())) == [self.task.meta_data, "菲亚梅塔"]
            and not self.task.retains_execution
            and not getattr(self.task, "mood_physical_started", False)
        ):
            self._refresh_fia_candidate_moods([self.task.meta_data])
            if self._fia_targets_all_full([self.task.meta_data]):
                logger.info("菲亚充能目标已满心情，跳过尚未开始的充能")
                return True
        restoring_order = getattr(self.task, "run_order_restore_pending", False)
        if restoring_order:
            self.task.prepare_run_order_restoration()
            plan = self.task.plan
        if id(self.task) in blocked_run_order_ids(self.tasks, self.op_data):
            return False
        if (
            self.task.type == TaskTypes.RUN_ORDER
            and getattr(self.task, "run_order_collect_only", False)
            and not restoring_order
        ):
            room = self.task.meta_data
            self.enter_room(room)
            self._read_room_mood(room, force_mood=True, strict_observation=True)
            if (
                not self.op_data.run_order_paused
                and self.op_data.is_order_collection_room(room)
            ):
                self._wait_drone_interface(
                    interval=1,
                    accelerate_template="bill_accelerate",
                    page_template="order_label",
                )
                self.accept_order()
            self.scene_graph_navigation(Scene.INFRA_MAIN)
            plan.clear()
            return True
        if self._emergency_frozen():
            if (
                self.task.type == TaskTypes.RUN_ORDER
                and hasattr(self.task, "emergency_original_roster")
                and not self._emergency_compensation_available(plan)
            ):
                self._retain_failed_task(
                    self.task,
                    "跑单原班恢复等待其他工作站释放原驻员",
                    plan,
                    dependency=True,
                )
                return False
            if self.task.type in (TaskTypes.RUN_ORDER, TaskTypes.FIAMMETTA):
                if not restoring_order and not hasattr(
                    self.task, "emergency_original_roster"
                ):
                    self.task.emergency_original_roster = {
                        room: self.op_data.get_current_room(room, True) for room in plan
                    }
            elif (
                not getattr(self.task, "emergency_staffing", False)
                and any(not room.startswith("dorm") for room in plan)
                and not (
                    self.task.type == TaskTypes.SELF_CORRECTION
                    and getattr(self.task, "exhaust_support", False)
                    and self._coordination_commit_started(self.task)
                    and plan == self.task.plan
                )
                and self.task.type
                not in (
                    TaskTypes.WORKSHOP,
                    TaskTypes.SKILL_UPGRADE,
                    TaskTypes.SWAP_SUPPORT,
                )
            ):
                raise RuntimeError("救急期间暂停普通工作站换班")
        held = (
            self._blocked_arrangement_rooms(self.task)
            if plan is self.task.plan
            and getattr(self.task, "arrangement_failures", None)
            else set()
        )
        self._suppress_dispatchable_arrangement(self.task, plan)
        if any(
            name in self.op_data.operators
            and self.op_data.operators[name].current_room == "train"
            for room, row in plan.items()
            if room not in held
            for name in row
        ) and (
            getattr(self.task, "emergency_staffing", False)
            or config.conf.mastery_enabled
        ):
            # 先核实源岗位，不能通过其他房间的换人间接打断训练。
            from arknights_mower.solvers.mastery_reader import (
                RoomState,
                read_room_state,
            )

            try:
                room_state = read_room_state(self)
            except (MowerExit, DeviceRecoveryError):
                raise
            except Exception as e:
                logger.warning(f"换人前训练室状态读取失败: {e}")
                room_state = None
            if config.conf.mastery_enabled:
                self.train_room_state = room_state or RoomState(read_failed=True)
                self._suppress_dispatchable_arrangement(self.task, plan)
            if getattr(self.task, "emergency_staffing", False):
                self._emergency_protect_training(plan, room_state)
                self._emergency_protect_training(
                    self.emergency_state.setdefault("staffing_plan", {}), room_state
                )
            for room in plan.keys() - held:
                if all(name == "Current" for name in plan[room]):
                    del plan[room]
            self.back_to_infrastructure()
        self._prepare_group_shift_execution_targets(self.task)
        logger.info("基建：排班")
        if (
            self.task.type in (TaskTypes.NOT_SPECIFIC, TaskTypes.FILL_DORM)
            and hasattr(self.task, "dorm_fill_plan")
            and not self.task.retains_execution
            and not getattr(self.task, "emergency_dorm", False)
            and not any(
                getattr(self.task, attribute, False)
                for attribute in (
                    "arrangement_retry_room",
                    "dorm_recovery_restore",
                    "product_shift_locked",
                    "backup_shift_active",
                    "strict_mood_limit",
                )
            )
            and not self._emergency_frozen()
        ):
            # 排队期间身份和恢复层级可以变化；复用分床规划器重新准入。
            pending = copy.deepcopy(
                [task for task in self.tasks if task is not self.task]
            )
            existing = {id(task): task for task in pending}
            projected = self.op_data.project_arrangements([{}])
            _, _, reserved_names, reserved_slots = self._dorm_recovery_reservations(
                pending, op_data=projected, current_task=self.task
            )
            try_add_release_dorm(
                {},
                None,
                projected,
                pending,
                reserved_names=reserved_names,
                reserved_slots=reserved_slots,
            )
            updated = next((task for task in pending if id(task) not in existing), None)
            self.task.plan.clear()
            self.task.plan.update(updated.plan if updated is not None else {})
            if updated is not None:
                self.task.type = updated.type
            for attribute in (
                "dorm_fill_plan",
                "dorm_mood_residents",
                "simple_dorm_fill",
            ):
                if hasattr(updated, attribute):
                    setattr(self.task, attribute, getattr(updated, attribute))
                elif hasattr(self.task, attribute):
                    delattr(self.task, attribute)
            if updated is not None:
                protect_priority_tasks(self.tasks, op_data=self.op_data)
                if (
                    self.task.time > datetime.now()
                    or not self.tasks
                    or self.tasks[0] is not self.task
                ):
                    return False
            for dorm_room, names in self.task.plan.items():
                if dorm_room.startswith("dorm"):
                    for name in names:
                        if name in self.op_data.operators:
                            self.op_data.operators[name].dorm_mood_fallback = (
                                dorm_room
                                if projected.operators[name].dorm_mood_fallback
                                else ""
                            )
            plan = self.task.plan
        self._track_idle_dorm_shift(plan)
        if self.task.type == TaskTypes.FILL_DORM and not getattr(
            self.task, "emergency_dorm", False
        ):
            simplify_dorm_fill(self.task, self.tasks, op_data=self.op_data)
            if getattr(self.task, "simple_dorm_fill", False):
                if (
                    self.task.plan
                    and not getattr(self, "_product_batch_active", False)
                    and defer_dorm_before_priority_task(
                        self.task,
                        self.tasks,
                        next(iter(self.task.plan)),
                        datetime.now(),
                        self.op_data,
                    )
                ):
                    return False
                # 任务等待期间床位可能已变化；简化补位只碰现在仍为空的床。
                vacancies = vacant_dorm_slots(self.op_data)
                remaining = {}
                for room, names in self.task.plan.items():
                    for index, name in enumerate(names):
                        if name == "Current" or (room, index) not in vacancies:
                            continue
                        op = self.op_data.operators.get(name)
                        if op is not None and op.current_room:
                            name = "Free"
                        remaining.setdefault(room, ["Current"] * len(names))[index] = (
                            name
                        )
                self.task.plan.clear()
                self.task.plan.update(remaining)
            plan = self.task.plan
        if self.task.type != TaskTypes.FIAMMETTA and not self._emergency_frozen():
            for dorm_room in list(plan):
                if dorm_room.startswith("dorm"):
                    self.preserve_resting_crafters(plan[dorm_room], dorm_room)
        if not self._prepare_run_order_dorm_departures(plan):
            return False
        rooms = _arrangement_room_order(plan, self.op_data)
        # 救急跑单失败沿用换入意图；普通跑单由实测原班补偿接续。
        original_plan = (
            copy.deepcopy(plan)
            if self.task.type == TaskTypes.RUN_ORDER and self._emergency_frozen()
            else None
        )
        new_plan = {}
        facility_observations = {}
        observation_args = (
            {"facility_observations": facility_observations}
            if plan is self.task.plan
            and self._is_ordinary_facility_arrangement(self.task)
            and not self._emergency_frozen()
            else {}
        )
        from arknights_mower.solvers.mastery_support_runtime import (
            central_training_occupants,
            refresh_after_central_change,
        )

        central_before = central_training_occupants(self)
        if plan is self.task.plan and getattr(self.task, "arrangement_failures", None):
            blocked = self._blocked_arrangement_rooms(self.task)
            rooms = [room for room in rooms if room not in blocked]
        for room in rooms:
            if not new_plan and self._defer_arrangement_for_priority_task(room, plan):
                self._finish_idle_dorm_shift()
                refresh_after_central_change(self, central_before)
                return False
            if (
                not new_plan
                and not getattr(self, "_product_batch_active", False)
                and defer_dorm_before_priority_task(
                    self.task, self.tasks, room, datetime.now(), self.op_data
                )
            ):
                return False
            try:
                new_plan = self.agent_arrange_room(
                    new_plan, room, plan, get_time=get_time, **observation_args
                )
            except BaseException as e:
                if getattr(self.task, "run_order_restore_pending", False):
                    self._retain_run_order_restoration(
                        failure=(
                            str(e)
                            if restoring_order
                            and isinstance(e, Exception)
                            and not isinstance(
                                e, (MowerExit, DeviceRecoveryError, SharedADBError)
                            )
                            else None
                        )
                    )
                raise
            if new_plan is False or new_plan is None:
                self._finish_idle_dorm_shift()
                refresh_after_central_change(self, central_before)
                if getattr(self.task, "run_order_restore_pending", False):
                    return self._retain_run_order_restoration(
                        failure="跑单原班恢复未完成" if restoring_order else None
                    )
                return False
        if plan is self.task.plan and getattr(self.task, "arrangement_failures", None):
            self._resume_arrangement_rooms(self.task)
            if plan:
                self._finish_idle_dorm_shift()
                refresh_after_central_change(self, central_before)
                return False
        if (
            rooms
            and not new_plan
            and self.task.type not in (TaskTypes.RUN_ORDER, TaskTypes.FIAMMETTA)
            and getattr(self, "_workshop_room_handoff", False) is not True
        ):
            self._read_arrangement_order_times(room)
        self._finish_idle_dorm_shift()
        if restoring_order:
            del self.task.run_order_original_roster
            del self.task.run_order_restore_pending
            finish_run_order_network(self.task, getattr(self, "recog", None))
            if getattr(self.task, "maintenance_replacement_run", False):
                self.maintenance_entry_pending = True
        if (
            rooms
            and room != "train"
            and self.task.type == TaskTypes.RUN_ORDER
            and (
                len(new_plan) == 1
                or not restoring_order
                and len(rooms) == 1
                and self.task.meta_data == room
            )
        ):
            missed_order = False
            try:
                if config.conf.run_order_buffer_time <= 0 or self.task.adjusted:
                    if self.task.adjusted:
                        logger.info("检测到跑单已调整，强制使用无人机跑单")
                    logger.info("开始插拔")
                    try:
                        self.drone(room, not_customize=True)
                    except Exception:
                        if original_plan is not None:
                            self.task.plan = original_plan
                        raise
                else:
                    # 葛朗台跑单模式
                    # agent_arrange_room 已完成换人并读屏校验进驻结果；
                    # 此时才进入订单页读倒计时，避免换人前往返进入房间。
                    wait_time = self.get_order_remaining_time()
                    logger.debug(f"订单剩余时间 {wait_time} 秒")
                    if (
                        0
                        < wait_time
                        < (
                            run_order_entry_seconds(self.task, config.conf)
                            + run_order_network_allowance(self.task)
                        )
                    ):
                        logger.info(f"停止{wait_time}秒等待订单完成")
                        self.sleep(wait_time)
                        # 等待服务器交互
                        if self.scene() in self.waiting_scene:
                            if not self.waiting_solver():
                                if getattr(
                                    self.task, "run_order_restore_pending", False
                                ):
                                    return self._retain_run_order_restoration()
                                return False
                    else:
                        self._report_missed_order(room, wait_time)
                        missed_order = True
                    self.accept_order()
                    if self.drone_room is None or (
                        self.drone_room == room and room in self.op_data.run_order_rooms
                    ):
                        drone_count = self.digit_reader.get_drone(self.recog.gray)
                        logger.info(f"当前无人机数量为：{drone_count}")
                        if drone_count >= self.drone_count_limit:
                            self.drone(
                                room,
                                not_return=True,
                                not_customize=True,
                                skip_enter=True,
                            )
                    if config.conf.run_order_buffer_time > 0:
                        while self.find("bill_accelerate") is not None:
                            self.back(interval=0.5)
                    else:
                        self.back(interval=0.5)
                        self.back(interval=0.5)
                if not new_plan:
                    del plan[room]
                    if getattr(self.task, "maintenance_replacement_run", False):
                        self.maintenance_entry_pending = True
                    if missed_order:
                        raise RunOrderMissed(room)
                    return True
                # 防止由于意外导致的死循环
                run_order_room = next(iter(new_plan))
                if getattr(self.task, "run_order_restore_pending", False):
                    new_plan = copy.deepcopy(self.task.run_order_original_roster)
                    if config.conf.run_order_buffer_time <= 0:
                        return self._retain_run_order_restoration()
                elif self._emergency_frozen() and hasattr(
                    self.task, "emergency_original_roster"
                ):
                    new_plan = copy.deepcopy(self.task.emergency_original_roster)
                if config.conf.run_order_buffer_time > 0 and (
                    not self._emergency_frozen()
                    or self._emergency_compensation_available(new_plan)
                ):
                    restoring_order = getattr(
                        self.task, "run_order_restore_pending", False
                    )
                    restored = self.agent_arrange_room(
                        {}, run_order_room, new_plan, skip_enter=True
                    )
                    if getattr(self.task, "run_order_restore_pending", False):
                        if restored is False or restored is None:
                            return self._retain_run_order_restoration(
                                failure="跑单原班恢复未完成"
                            )
                        del self.task.run_order_original_roster
                        del self.task.run_order_restore_pending
                        finish_run_order_network(
                            self.task, getattr(self, "recog", None)
                        )
                        if getattr(self.task, "maintenance_replacement_run", False):
                            self.maintenance_entry_pending = True
                else:
                    restore_task = SchedulerTask(
                        time=self.tasks[0].time,
                        task_plan=new_plan,
                        task_type=TaskTypes.RUN_ORDER,
                    )
                    if self._emergency_frozen():
                        restore_task.emergency_original_roster = copy.deepcopy(
                            self.task.emergency_original_roster
                        )
                    if getattr(self.task, "maintenance_advance_before_backup", False):
                        restore_task.maintenance_advance_before_backup = True
                    if getattr(self.task, "maintenance_replacement_run", False):
                        restore_task.maintenance_replacement_run = True
                    if hasattr(self.task, "maintenance_start"):
                        restore_task.maintenance_start = self.task.maintenance_start
                    self.tasks.append(restore_task)
                    self.skip()
                if missed_order:
                    raise RunOrderMissed(room)
            except BaseException as e:
                if getattr(self.task, "run_order_restore_pending", False):
                    self._retain_run_order_restoration(
                        failure=(
                            str(e)
                            if restoring_order
                            and isinstance(e, Exception)
                            and not isinstance(
                                e, (MowerExit, DeviceRecoveryError, SharedADBError)
                            )
                            else None
                        )
                    )
                raise
        elif self.task.type == TaskTypes.FIAMMETTA:
            if new_plan:
                restoration = SchedulerTask(
                    time=self.tasks[0].time,
                    task_plan=new_plan,
                    task_type=TaskTypes.FIAMMETTA,
                    initial_fia=getattr(self.task, "initial_fia", False),
                )
                for attribute in (
                    "fia_return_target",
                    "fia_return_time",
                    "fia_charge_confirmed",
                ):
                    if hasattr(self.task, attribute):
                        setattr(restoration, attribute, getattr(self.task, attribute))
                self.tasks.append(restoration)
                self.skip()
            else:
                self._queue_fia_return()
        refresh_after_central_change(self, central_before)
        if (
            facility_observations
            and not plan
            and not self.task.plan
            and set(facility_observations) == set(rooms)
        ):
            self._log_facility_idle_results(facility_observations)
        if getattr(self, "_workshop_room_handoff", False) is not True:
            logger.info("返回基建主界面")

    def skip(self, task_names="All"):
        if task_names == "All":
            task_names = ["planned", "collect_notification", "todo_task"]
        if "planned" in task_names:
            self.planned = True
        if "todo_task" in task_names:
            self.todo_task = True
        if "collect_notification" in task_names:
            self.collect_notification = True

    def no_pending_task(self, minute=0):
        return self.find_next_task(datetime.now() + timedelta(minutes=minute)) is None

    def reload(self):
        """按生效排班表配置的源石碎片房间补货，不读取当前产物。"""
        error = False
        pending_targets = {}
        for task in self.tasks:
            pending_targets.update(getattr(task, "pending_product_targets", {}))
            if task.type == TaskTypes.SWITCH_PRODUCT:
                room, target = parse_product_task_meta(task.meta_data)
                pending_targets[room] = target
        for room, product in self.op_data.products.items():
            if not room.startswith("room_") or product not in (
                "orirock",
                "orirock_device",
            ):
                continue
            if room in pending_targets and pending_targets[room] != product:
                logger.info(
                    "%s正在等待切换产物，本轮不补充旧配方队列",
                    self.translate_room(room),
                )
                continue
            try:
                self.enter_room(room)
                self._wait_drone_interface(
                    interval=0.25, accelerate_template="manufacture_accelerate"
                )
                logger.info(
                    f"开始搓玉补货:{room}（{MANUFACTURE_PRODUCTS[product].name}）"
                )
                self._fill_manufacture_queue(material_limited=True)
                self.scene_graph_navigation(Scene.INFRA_MAIN)
            except MowerExit:
                raise
            except Exception as e:
                save_exception(e)
                logger.exception(e)
                error = True
                self.recog.update()
                back_count = 0
                while self.scene() != Scene.INFRA_MAIN:
                    self.back()
                    back_count += 1
                    if back_count > 3:
                        raise e
        if not error:
            self.reload_time = datetime.now()

    def _maa_daily_done(self, key):
        today = get_server_time().date()
        if key == "visit_friends":
            return getattr(self, "daily_visit_friend", None) == today
        return getattr(self, "maa_daily_completed", {}).get(key) == today

    def _remember_maa_daily_task(self, task_id, chain, keys):
        if type(task_id) is not int or task_id <= 0 or not keys:
            return
        if not hasattr(self, "maa_daily_tasks"):
            self.maa_daily_tasks = {}
        self.maa_daily_tasks[task_id] = {
            "chain": chain,
            "day": get_server_time().date(),
            "keys": set(keys),
            "failed": False,
        }

    def _record_maa_daily_callback(self, msg, details):
        tasks = getattr(self, "maa_daily_tasks", {})
        task_id = details.get("taskid")
        task = tasks.get(task_id) if type(task_id) is int else None
        if task is not None and task["chain"] == details.get("taskchain"):
            completed = set()
            if msg == 20000:
                task["failed"] = True
            elif msg == 10002 and task["chain"] == "Award" and not task["failed"]:
                completed = set(task["keys"])
            elif msg == 20002 and task["chain"] == "Mall":
                inner = details.get("details")
                node = inner.get("task") if isinstance(inner, dict) else None
                if node in ("VisitLimited", "VisitNextBlack"):
                    completed = {"visit_friends"} & task["keys"]
                elif node == "StageDrops-Stars-3":
                    completed = {"credit_fight"} & task["keys"]
            if completed:
                if not hasattr(self, "maa_daily_completed"):
                    self.maa_daily_completed = {}
                for key in completed:
                    if key == "visit_friends":
                        self.daily_visit_friend = task["day"]
                    else:
                        self.maa_daily_completed[key] = task["day"]
                task["keys"].difference_update(completed)
                save_current_state()
            if msg in (10000, 10002, 10004):
                tasks.pop(task_id, None)
        if msg == 3:
            tasks.clear()

    @maa_control.execution()
    def run_maa_event_shop(self, deadline, *, manual=False):
        from time import monotonic

        from arknights_mower.solvers.event_shop import EventShopNavigation
        from arknights_mower.utils.config.weekly_plan_loader import (
            get_weekly_plan_manager,
        )
        from arknights_mower.utils.config_backup import backup_lock
        from arknights_mower.utils.device.io_budget import device_io_budget
        from arknights_mower.utils.maa_event_shop import (
            SHOP_SWIPE_LIMIT,
            ShopTaskProgress,
            select_shop,
            shop_identity,
            shop_params,
            switch_after_shop,
        )

        if config.stop_mower.is_set():
            raise MowerExit

        def defer_for_refresh():
            if (refresh := self._maa_refresh_deadline()) is not None:
                self._defer_maa_event_shop_for_refresh(refresh, manual=manual)
                return True
            return False

        if config.stop_maa.is_set():
            return
        with backup_lock:
            settings = config.conf.maa_event_shop.model_copy(deep=True)
            if not settings.enable:
                return
            manager = get_weekly_plan_manager()
            shop = select_shop(manager, manager._current_server_timestamp())
            if shop is None:
                logger.info(
                    "没有符合当前理智周计划的当期 SS 活动，跳过商店兑换",
                    extra={"log_group": "maa-integration"},
                )
                return
            activity_key = shop_identity(shop)
            if maa_event_shop_completed(*activity_key):
                logger.debug(
                    "活动「%s」的商店兑换已完成，跳过本次兑换", shop["activity"]
                )
                return
            source = manager.get_active_plan_key()
            task = {
                "settings": settings.model_dump(),
                "source": source,
                "target": manager.get_activity_fallbacks().get(source, ""),
                "revision": manager.get_active_plan_revision(),
            }
        if defer_for_refresh():
            return False
        if (deadline() - datetime.now()).total_seconds() <= 300:
            return
        self.release_maa()
        navigation_end = monotonic() + min(
            120, (deadline() - datetime.now()).total_seconds() - 300
        )

        def remaining():
            seconds = navigation_end - monotonic()
            if seconds <= 0:
                raise TimeoutError("活动商店导航超时")
            if config.stop_maa.is_set():
                raise InterruptedError("活动商店导航已停止")
            return seconds

        try:
            with device_io_budget(remaining):
                ready = EventShopNavigation(self.device, self.recog).run(shop)
        except (TimeoutError, InterruptedError):
            logger.warning(
                "活动商店导航超时或收到停止指令，跳过兑换",
                extra={"log_group": "maa-integration"},
            )
            return
        if not ready:
            logger.warning(
                "未确认活动商店页面，跳过兑换", extra={"log_group": "maa-integration"}
            )
            return
        if config.stop_mower.is_set():
            raise MowerExit
        if config.stop_maa.is_set():
            return
        if defer_for_refresh():
            return False
        with backup_lock:
            current_shop = select_shop(manager, manager._current_server_timestamp())
            if (
                manager.get_active_plan_revision() != task["revision"]
                or current_shop is None
                or shop_identity(current_shop) != activity_key
            ):
                logger.info(
                    "理智周计划或当期活动已更改，跳过本次活动商店兑换",
                    extra={"log_group": "maa-integration"},
                )
                return
        try:
            self.initialize_maa()
            if config.stop_mower.is_set():
                raise MowerExit
            if config.stop_maa.is_set():
                return
            if defer_for_refresh():
                return False
            task_id = self.MAA.append_task("Custom", shop_params(settings))
            if not task_id:
                raise ValueError("MAA 未接受活动商店任务，请检查核心与资源版本")
            progress = self.maa_event_shop_task = ShopTaskProgress(task_id)
            if defer_for_refresh():
                return False
            if config.stop_mower.is_set():
                raise MowerExit
            if config.stop_maa.is_set():
                return
            if not self.MAA.start():
                raise ValueError("MAA 活动商店任务启动失败")
            while self.MAA.running():
                if config.stop_mower.is_set():
                    raise MowerExit
                if (
                    config.stop_maa.is_set()
                    or (deadline() - datetime.now()).total_seconds() <= 300
                ):
                    self.maa_stop()
                    return
                csleep(1)
            if config.stop_mower.is_set():
                raise MowerExit
            if not config.stop_maa.is_set():
                # Close the native handle before applying a configuration change.
                self.release_maa()
                if (
                    not progress.completed
                    or progress.underfunded
                    or not (progress.finite_done or progress.scan_exhausted)
                ):
                    return
                with backup_lock:
                    mark_maa_event_shop_complete(*activity_key)
                    reason = (
                        "已遇到无限商品"
                        if progress.finite_done
                        else f"连续滑动 {SHOP_SWIPE_LIMIT} 次后仍未选中下一件商品"
                    )
                    logger.info(
                        "活动「%s」的商店%s，已记录兑换完成",
                        shop["activity"],
                        reason,
                        extra={"log_group": "maa-integration"},
                    )
                    if progress.finite_done and switch_after_shop(
                        task, config.conf.maa_event_shop, manager
                    ):
                        logger.info(
                            "活动商店有限商品已兑换完毕，刷理智方案从 %s 切换为 %s",
                            task["source"],
                            task["target"],
                            extra={"log_group": "maa-integration"},
                        )
        finally:
            if getattr(self, "MAA", None) is not None:
                self.maa_stop()
            self.release_maa()
            self.recog.reset_after_external_control()

    def _maa_copilot_run(self, conf, *, paradox=False):
        attr = "maa_paradox_progress" if paradox else "maa_copilot_progress"
        pending_attr = "_unsaved_" + attr
        if pending := getattr(self, pending_attr, None):
            finish_copilot_item(*pending, paradox=paradox)
            delattr(self, pending_attr)
        fallback = {}
        if not paradox and not getattr(self, "_maa_copilot_progress_loaded", False):
            fallback = getattr(self, attr, {})
        progress = prepare_copilot_progress(conf, fallback, paradox=paradox)
        if not paradox:
            self._maa_copilot_progress_loaded = True
        setattr(self, attr, progress)
        return progress

    def _finish_copilot_item(self, progress, token, outcome, *, paradox):
        attr = "maa_paradox_progress" if paradox else "maa_copilot_progress"
        pending_attr = "_unsaved_" + attr
        result = (progress["key"], token, outcome)
        try:
            saved = finish_copilot_item(*result, paradox=paradox)
        except Exception:
            setattr(self, pending_attr, result)
            apply_copilot_result(progress, *result)
            raise
        if saved is None:
            return False
        setattr(self, attr, saved)
        return True

    def _maa_blackflow_run(self, conf):
        from arknights_mower.utils.maa_long_task import (
            blackflow_boss_run_key,
            blackflow_preserved_run,
            blackflow_start_run_key,
        )

        boss = blackflow_preserved_run(conf) == "boss"
        key = (blackflow_boss_run_key if boss else blackflow_start_run_key)(conf)
        progress = load_maa_blackflow_progress(boss=boss)
        if progress.get("key") != key:
            progress = {"key": key, "completed": False}
            save_maa_blackflow_progress(progress, boss=boss)
        progress["kind"] = "boss" if boss else "opening"
        return progress

    def _record_maa_blackflow_callback(self, msg, details):
        task = getattr(self, "maa_blackflow_task", None)
        if (
            task is None
            or type(details.get("taskid")) is not int
            or details["taskid"] != task[0]
            or details.get("taskchain") != "Roguelike"
            or msg != 20003
        ):
            return
        inner = details.get("details")
        if not isinstance(inner, dict):
            return
        boss = task[1].get("kind") == "boss"
        if boss:
            completed = blackflow_boss_stop_reached(details)
        else:
            completed = (
                details.get("what") == "BlackFlowStartRun"
                and inner.get("status") == "completed"
            )
        if completed:
            task[1]["completed"] = True
            save_maa_blackflow_progress(task[1], boss=boss)

    def _record_maa_copilot_callback(self, msg, details, *, paradox=False):
        task_attr = "maa_paradox_task" if paradox else "maa_copilot_task"
        chain = "ParadoxCopilot" if paradox else "Copilot"
        name = "悖论模拟" if paradox else "自动战斗"
        task = getattr(self, task_attr, None)
        if (
            task is None
            or type(details.get("taskid")) is not int
            or details["taskid"] != task[0]
            or details.get("taskchain") != chain
            or msg not in (10000, 10002, 10004)
        ):
            return
        setattr(self, task_attr, None)
        progress = self.maa_paradox_progress if paradox else self.maa_copilot_progress
        if progress.get("key") != task[1]:
            return
        outcome = {10002: "completed", 10000: "failed", 10004: "stopped"}[msg]
        if not self._finish_copilot_item(progress, task[3], outcome, paradox=paradox):
            return
        if msg == 10002:
            self._completed_copilot_attempt = task[3]
            logger.info(
                f"{name}队列第 {task[2] + 1} 项已完成",
                extra={"log_group": "maa-integration"},
            )
        elif msg == 10000:
            logger.warning(
                "%s作业失败，保留进度，等待修改作业或手动调整该项状态",
                name,
                extra={"log_group": "maa-integration"},
            )

    def _maa_sss_run(self, conf):
        from arknights_mower.utils.maa_copilot import queue_key

        # Read the independent record for each dispatch, including after a profile switch.
        progress = load_maa_sss_progress()
        key = queue_key(conf)
        if progress.get("key") != key:
            progress = {"key": key, "next": 0, "completed": 0, "failed": False}
            save_maa_sss_progress(progress)
        self.maa_sss_progress = progress
        return progress

    def _record_maa_sss_callback(self, msg, details):
        task = getattr(self, "maa_sss_task", None)
        if (
            task is None
            or type(details.get("taskid")) is not int
            or details["taskid"] != task["id"]
            or details.get("taskchain") != "SSSCopilot"
        ):
            return
        progress = self.maa_sss_progress
        if (
            progress.get("key"),
            progress.get("next"),
            progress.get("completed"),
        ) != task["position"]:
            return
        if msg == 20003:
            if details.get("what") == "SSSGamePass":
                task["passed"] = True
            elif details.get("what") == "SSSSettlement":
                task["settled"] = True
            return
        if msg not in (10000, 10002, 10004):
            return
        self.maa_sss_task = None
        if msg == 10004:
            return
        if msg == 10002 and task["passed"] and not task["settled"]:
            progress["completed"] += 1
            logger.info(
                f"保全队列第 {progress['next'] + 1} 项已完成 {progress['completed']}/{task['times']} 轮",
                extra={"log_group": "maa-integration"},
            )
            if progress["completed"] >= task["times"]:
                progress["next"] += 1
                progress["completed"] = 0
        else:
            progress["failed"] = True
            logger.warning(
                "保全作业未通关，保留进度，等待修改队列或手动重新执行",
                extra={"log_group": "maa-integration"},
            )
        save_maa_sss_progress(progress)

    def on_maa_callback(self, msg, details, arg, *, observation_run=None):
        """MAA 回调入口：累积掉落统计、代发上报请求、输出可读日志行。"""
        d = parse_details(details)
        from arknights_mower.solvers.growth import record_growth_callback

        record_growth_callback(self, msg, d, observation_run)
        from arknights_mower.utils.maa_catalyst import record_callback

        record_callback(self, msg, d, observation_run)
        observe_maa_callback(self, msg, d, generation=observation_run)
        logger.debug("MAA 回调 %s %s", msg, d, extra={"log_group": "maa-integration"})
        try:
            self._record_maa_daily_callback(msg, d)
        except Exception:
            logger.exception(
                "保存 MAA 每日任务完成记录失败", extra={"log_group": "maa-integration"}
            )
        try:
            self._record_maa_copilot_callback(msg, d)
            self._record_maa_copilot_callback(msg, d, paradox=True)
        except Exception:
            logger.exception(
                "保存 MAA 自动战斗作业进度失败", extra={"log_group": "maa-integration"}
            )
        if (shop_task := getattr(self, "maa_event_shop_task", None)) is not None:
            shop_task.record(msg, d)
        try:
            self._record_maa_sss_callback(msg, d)
        except Exception:
            logger.exception(
                "保存 MAA 保全派驻进度失败", extra={"log_group": "maa-integration"}
            )
        try:
            self._record_maa_blackflow_callback(msg, d)
        except Exception:
            logger.exception(
                "保存 MAA 黑流树海刷开局完成记录失败",
                extra={"log_group": "maa-integration"},
            )
        if msg == 3:  # AllTasksCompleted follows the final StageDrops receipt.
            battle_inventory_active.clear()
        if msg == 20003 and d.get("what") == "StageDrops":
            try:
                from arknights_mower.utils.maa_inventory import MaaDropInventory

                if getattr(self, "maa_drop_inventory", None) is None:
                    self.maa_drop_inventory = MaaDropInventory()
                self.maa_drop_inventory.record(d)
                self.refresh_maa_inventory_targets()
            except Exception:
                logger.exception(
                    "MAA 掉落入库或停止目标更新失败，请检查库存",
                    extra={"log_group": "maa-integration"},
                )
            inner = d.get("details")
            inner = inner if isinstance(inner, dict) else {}
            drops = _drop_entries(inner.get("drops"))
            stats = _drop_entries(inner.get("stats"))
            if drops:
                stage_drop["details"].append(drops)
            if stats:
                stage_drop["summary"] = stats
        if msg in (10002, 10000, 10004) and type(d.get("taskid")) is int:
            getattr(self, "maa_inventory_tasks", {}).pop(d["taskid"], None)
        if msg == 10001 and d.get("taskchain") == "Fight":
            try:
                self.refresh_maa_inventory_targets()
            except Exception:
                logger.exception(
                    "MAA 库存目标更新失败", extra={"log_group": "maa-integration"}
                )
        if msg == REPORT_REQUEST:
            # 上报在守护线程里进行；此处仍要兜住线程创建失败，回调不得抛错。
            try:
                upload_report(d)
            except Exception as e:
                logger.warning(
                    f"MAA 上报请求处理失败：{e}", extra={"log_group": "maa-integration"}
                )
        if self.maa_callback is None:
            return
        line = self.maa_callback.describe(msg, d)
        if line is not None:
            logger.log(line.level, line.text, extra={"log_group": "maa-integration"})

    def refresh_maa_inventory_targets(self):
        """Update only inventory-bound Fight tasks; preserve all other parameters."""
        tasks = getattr(self, "maa_inventory_tasks", {})
        if not tasks:
            return
        from arknights_mower.utils.maa_stage_inventory import (
            load_inventory_snapshot,
            maa_fight_drop_targets,
        )

        inventory, _ = load_inventory_snapshot()
        for task_id, entry in list(tasks.items()):
            params, rules = entry
            targets = maa_fight_drop_targets(
                params["stage"],
                rules,
                inventory,
                self.maa_drop_inventory.accumulated(task_id),
            )
            updated = {**params, "drops": targets["drops"]}
            if targets["reached"]:
                updated.update(times=0, medicine=0, stone=0, expiring_medicine=0)
            if updated == params:
                continue
            if self.MAA.set_task_params(task_id, updated):
                tasks[task_id] = (updated, rules)
                if targets["reached"] and params["times"]:
                    logger.info(
                        "%s 库存已达上限，结束该关并继续后续任务",
                        params["stage"],
                        extra={"log_group": "maa-integration"},
                    )
            else:
                logger.warning(
                    "%s 库存停止目标未被 MAA 接受",
                    params["stage"],
                    extra={"log_group": "maa-integration"},
                )

    def report_maa_progress(self):
        """按间隔播报 MAA 进度；未到间隔不产生日志行。"""
        if self.maa_callback is None:
            return
        line = self.maa_callback.heartbeat()
        if line is not None:
            logger.log(line.level, line.text, extra={"log_group": "maa-integration"})

    def update_maa_navigation(self, path):
        """Download navigation atomically, falling back to an intact local cache."""
        from arknights_mower.utils.maa_runtime import navigation_cache_path
        from arknights_mower.utils.update_runtime import read_json, write_json

        ota_tasks_path = navigation_cache_path(
            path, android=os.environ.get("MOWER_ANDROID") == "1"
        )
        try:
            logger.debug(
                "开始更新MAA活动关卡导航……", extra={"log_group": "software-update"}
            )
            ota_tasks_url = (
                "https://api.maa.plus/MaaAssistantArknights/api/resource/tasks.json"
            )
            ota_tasks_path.parent.mkdir(parents=True, exist_ok=True)
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/133.0.0.0 Safari/537.36 Edg/133.0.0.0"
            }
            with requests.get(ota_tasks_url, headers=headers, timeout=60) as response:
                response.raise_for_status()
                res = response.content.decode("utf-8")
            tasks = json.loads(res)
            if (
                not isinstance(tasks, dict)
                or not tasks
                or not all(isinstance(task, dict) for task in tasks.values())
            ):
                raise ValueError("MAA 活动导航必须是非空任务定义对象")
            if getattr(config.conf, "maa_growth_enabled", False):
                from arknights_mower.utils.growth_execution import merge_growth_tasks

                tasks = merge_growth_tasks(tasks)
            write_json(ota_tasks_path, tasks)
            logger.info(
                "MAA 活动关卡导航下载完成，等待资源加载确认",
                extra={"log_group": "software-update"},
            )
            return tasks
        except Exception as e:
            logger.error(
                f"MAA活动关卡导航更新失败：{str(e)}",
                extra={"log_group": "software-update", "archive_screenshots": False},
            )
            save_exception(e)

        cached = read_json(ota_tasks_path, None)
        if (
            isinstance(cached, dict)
            and cached
            and getattr(config.conf, "maa_growth_enabled", False)
        ):
            from arknights_mower.utils.growth_execution import merge_growth_tasks

            guarded = merge_growth_tasks(cached)
            if guarded != cached:
                write_json(ota_tasks_path, guarded)
            return guarded
        return cached if isinstance(cached, dict) and cached else None

    def initialize_maa(self, *, on_task_event=None):
        from arknights_mower.utils.maa_backup import (
            MaaCallError,
            VerifiedAsst,
        )
        from arknights_mower.utils.maa_inventory import MaaDropInventory
        from arknights_mower.utils.update_runtime import read_json

        observation_run = begin_maa_observations(self)

        def callback(msg, details, arg):
            if on_task_event is not None and msg in (10000, 10002, 10004):
                on_task_event(msg, parse_details(details))
            return self.on_maa_callback(
                msg, details, arg, observation_run=observation_run
            )

        self.maa_drop_inventory = MaaDropInventory()
        self.maa_inventory_tasks = {}
        self.maa_daily_tasks = {}
        self.maa_copilot_task = None
        self.maa_paradox_task = None
        self.maa_sss_task = None
        self.maa_blackflow_task = None
        self.maa_event_shop_task = None
        battle_inventory_active.set()

        if os.environ.get("MOWER_ANDROID") == "1":
            from mower_android.maa import Asst

            self.maa_callback = MaaCallbackLog()
            self.MAA = VerifiedAsst(Asst, config.conf.maa_path, callback)
            self.stages = []
            navigation = self.update_maa_navigation(
                pathlib.Path(resolve_config_path(config.conf.maa_path))
            )
            if getattr(config.conf, "maa_growth_enabled", False):
                from arknights_mower.utils.growth_execution import merge_growth_tasks

                navigation = merge_growth_tasks(navigation or {})
                from arknights_mower.utils.maa_runtime import navigation_cache_path
                from arknights_mower.utils.update_runtime import write_json

                write_json(
                    navigation_cache_path(
                        pathlib.Path(resolve_config_path(config.conf.maa_path)),
                        android=True,
                    ),
                    navigation,
                )
            if navigation is not None:
                from arknights_mower.utils.maa_resource_update import (
                    load_android_maa_navigation,
                )

                if not load_android_maa_navigation(
                    pathlib.Path(resolve_config_path(config.conf.maa_path)), navigation
                ):
                    raise MaaCallError("load", detail="Android 活动导航加载失败")
                logger.info(
                    "MAA Android 活动关卡导航加载成功",
                    extra={"log_group": "maa-runtime"},
                )
            if not self.MAA.connect():
                raise RuntimeError("安卓 MAA 引擎未连接")
            return
        from arknights_mower.utils.maa_runtime import load_maa_with_navigation

        conf = config.conf
        path = pathlib.Path(resolve_config_path(conf.maa_path))
        self.maa_callback = MaaCallbackLog()
        self.MAA = load_maa_with_navigation(path, callback, self.update_maa_navigation)
        InstanceOptionType = self.MAA.instance_options

        resource = read_json(path / "resource" / "version.json", {})
        resource_version = (
            resource.get("last_updated", "未知")
            if isinstance(resource, dict)
            else "未知"
        )
        from arknights_mower.utils.maa_storage import storage_root

        logger.info(
            "MAA 资源加载成功 | core=%s | resource=%s | path=%s | incremental_path=%s",
            self.MAA.get_version(),
            resource_version,
            path,
            storage_root(path) / "cache",
            extra={"log_group": "maa-runtime"},
        )
        self.stages = []
        self.MAA.set_instance_option(
            InstanceOptionType.touch_type, conf.maa_touch_option
        )
        adb_path = getattr(self.device.client, "adb_bin", None) or resolve_config_path(
            conf.maa_adb_path
        )
        for name in ("adblite_enabled", "kill_on_adb_exit"):
            option = getattr(InstanceOptionType, name, None)
            if option is not None:
                self.MAA.set_instance_option(option, "0")
        guard_adb(adb_path, timeout=io_timeout(10))
        if self.MAA.connect(
            adb_path,
            self.device.client.device_id,
            conf.maa_conn_preset,
        ):
            logger.info("MAA 连接成功", extra={"log_group": "maa-runtime"})
        else:
            logger.info("MAA 连接失败", extra={"log_group": "maa-runtime"})
            raise Exception("MAA 连接失败")

    def append_maa_task(self, type, *, mall_action=None):
        if type == "StartUp":
            self.MAA.append_task(
                "StartUp",
                {"client_type": _maa_client_type(getattr(self, "device", None))},
            )
        elif type == "Fight":
            from arknights_mower.utils.config_backup import backup_lock
            from arknights_mower.utils.growth_farming import active_chip_farming_target
            from arknights_mower.utils.maa_stage_inventory import (
                load_inventory_snapshot,
                maa_fight_drop_targets,
            )

            with backup_lock:
                filter_by_availability = self.maybe_switch_expired_activity_plan()
                conf = config.conf
                _plan = conf.maa_weekly_plan[get_server_weekday()]
                use_all_medicine = is_game_date(
                    getattr(conf, "medicine_use_all_date", None)
                )
            logger.info(
                f"现在服务器是{_plan.weekday}", extra={"log_group": "maa-integration"}
            )
            growth = active_chip_farming_target(_plan.weekday, filter_by_availability)
            growth_rules = growth.rules if growth else {}
            stages = (
                (["Annihilation"] if "Annihilation" in _plan.stage else [])
                + list(growth_rules)
                if growth_rules
                else self.apply_maa_stage_inventory_rules(_plan.stage)
            )

            inventory, _ = load_inventory_snapshot()
            saved_rules = (
                copy.deepcopy(conf.maa_stage_limit_rules)
                if conf.maa_stage_inventory_enable
                else []
            )
            if not hasattr(self, "maa_inventory_tasks"):
                self.maa_inventory_tasks = {}
            for stage in stages:
                if growth_rules:
                    rules = [growth_rules[stage]] if stage in growth_rules else []
                else:
                    rules = saved_rules
                targets = maa_fight_drop_targets(stage, rules, inventory)
                if targets["reached"]:
                    continue
                logger.info(f"提交关卡:{stage}", extra={"log_group": "maa-integration"})
                params = {
                    # 空值表示上一次
                    # 'stage': '',
                    "stage": stage,
                    "medicine": _MAA_UNLIMITED_MEDICINE
                    if use_all_medicine
                    else _plan.medicine,
                    "stone": 999 if conf.maa_eat_stone else 0,
                    "times": 999,
                    "series": 0,
                    "report_to_penguin": conf.maa_report_to_penguin,
                    "client_type": _maa_client_type(getattr(self, "device", None)),
                    "penguin_id": conf.maa_penguin_id,
                    "DrGrandet": False,
                    "server": "CN",
                    "medicine_expire_days": max(0, conf.medicine_expire_days),
                    "report_to_yituliu": conf.maa_report_to_yituliu,
                    "yituliu_id": conf.maa_yituliu_id,
                }
                if targets["bound"]:
                    params.update(drops=targets["drops"])
                task_id = self.MAA.append_task("Fight", params)
                remember_maa_activity(self, task_id, "Fight", "stage-plan", stage=stage)
                if targets["bound"] and task_id:
                    self.maa_inventory_tasks[task_id] = (params, rules)
                self.stages.append(stage)
                logger.info(
                    "MAA 已接受关卡:%s | task_id=%s",
                    stage,
                    task_id,
                    extra={"log_group": "maa-integration"},
                )

        elif type == "Mall":
            conf = config.conf
            params = {
                "shopping": mall_action == "shopping"
                if mall_action
                else getattr(
                    conf,
                    "should_run_maa_mall",
                    getattr(conf, "maa_mall_enable", True)
                    and getattr(conf, "maa_mall_mode", "maa") == "maa",
                ),
                "buy_first": conf.maa_mall_buy.split(","),
                "blacklist": conf.maa_mall_blacklist.split(","),
                "credit_fight": not mall_action
                and conf.maa_credit_fight
                and "" not in self.stages
                and self.credit_fight is None
                and not self._maa_daily_done("credit_fight"),
                "formation_index": max(0, min(4, conf.credit_fight.squad)),
                "force_shopping_if_credit_full": conf.maa_mall_ignore_blacklist_when_full,
                "visit_friends": mall_action == "visit_friends"
                if mall_action
                else getattr(
                    conf,
                    "should_run_maa_visit_friend",
                    getattr(conf, "visit_friend_enable", False)
                    and getattr(conf, "visit_friend_mode", "maa") == "maa",
                ),
                "only_buy_discount": conf.maa_mall_only_buy_discount,
                "reserve_max_credit": conf.maa_mall_reserve_max_credit,
            }
            params["visit_friends"] = params[
                "visit_friends"
            ] and not self._maa_daily_done("visit_friends")
            task_id = self.MAA.append_task("Mall", params)
            self._remember_maa_daily_task(
                task_id,
                "Mall",
                [key for key in ("visit_friends", "credit_fight") if params[key]],
            )
        elif type == "Award":
            daily = ("recruit", "orundum", "mining", "specialaccess", "signinevent")
            params = {
                "award": True,
                "mail": config.conf.maa_mail,
                **{
                    key: getattr(config.conf, f"maa_{key}", False)
                    and not self._maa_daily_done(key)
                    for key in daily
                },
            }
            task_id = self.MAA.append_task("Award", params)
            if params["award"]:
                remember_maa_activity(self, task_id, "Award", "mission")
            self._remember_maa_daily_task(
                task_id,
                "Award",
                [key for key in daily if params[key]],
            )

    def maybe_switch_expired_activity_plan(self):
        """Apply any due plan switch and read the selected plan's growth setting."""
        try:
            from arknights_mower.utils.config.weekly_plan_loader import (
                get_weekly_plan_manager,
            )
            from arknights_mower.utils.config_backup import backup_lock

            with backup_lock:
                manager = get_weekly_plan_manager()
                manager.maybe_switch_expired_activity_plan()
                return manager.get_growth_chip_farming().get(
                    manager.get_active_plan_key()
                )
        except Exception:
            logger.exception(
                "检测活动结束并切换刷理智周计划失败，继续使用当前方案",
                extra={"log_group": "weekly-plan-editor", "archive_screenshots": False},
            )
            return None

    def maa_stop(self, stop=True):
        stopped = None
        if stop:
            stopped = self.MAA.stop()
            clear_maa_observations(self)
        battle_inventory_active.clear()
        logger.debug(stage_drop, extra={"log_group": "maa-runtime"})
        # 有掉落东西再发
        if stage_drop["details"] and not self.drop_send:
            send_message(
                maa_template.render(stage_drop=stage_drop),
                "MAA 作战掉落汇总",
                body_is_html=True,
            )
            self.drop_send = True
        return stopped

    def release_maa(self):
        return maa_control.release(self)

    def append_maa_theme_task(self):
        """将主题恢复追加到当前队列，由调用者统一启动并处理停止。"""
        conf = config.conf
        if not conf.maa_restore_theme_enable or self.MAA is None:
            return
        theme = conf.maa_restore_theme.strip()
        if not theme:
            logger.warning(
                "未选择目标主题，跳过恢复主题", extra={"log_group": "maa-integration"}
            )
            return
        if config.stop_maa.is_set() or config.stop_mower.is_set():
            return
        try:
            version = self.MAA.get_version()
            try:
                supported = Version(version) >= Version("6.17.3")
            except InvalidVersion:
                supported = False
            if not supported:
                logger.warning(
                    f"恢复主题需要 MAA v6.17.3 或更高版本，当前为 {version}，跳过恢复",
                    extra={"log_group": "maa-integration"},
                )
                return
            if not self.MAA.append_task("SwitchTheme", {"themes": [theme]}):
                logger.warning(
                    "添加恢复主题任务失败，请检查 MAA 核心及配套资源版本",
                    extra={"log_group": "maa-integration"},
                )
                return
            logger.info(
                f"已将恢复游戏主题加入 MAA 任务队列：{theme}",
                extra={"log_group": "maa-integration"},
            )
        except MowerExit:
            raise
        except Exception:
            logger.exception(
                "添加恢复主题任务失败，继续原定任务",
                extra={"log_group": "maa-integration"},
            )

    def has_maa_daily_tasks(self) -> bool:
        conf = config.conf
        if hasattr(conf, "has_maa_daily_tasks"):
            return conf.has_maa_daily_tasks
        return (
            getattr(conf, "maa_credit_fight", False)
            or (
                getattr(conf, "stage_plan_enable", True)
                and getattr(conf, "stage_plan_runner", "maa") == "maa"
            )
            or (
                getattr(conf, "maa_mall_enable", True)
                and getattr(conf, "maa_mall_mode", "maa") == "maa"
            )
            or (
                getattr(conf, "visit_friend_enable", False)
                and getattr(conf, "visit_friend_mode", "maa") == "maa"
            )
            or any(
                [
                    getattr(conf, "maa_mail", False),
                    getattr(conf, "maa_recruit", False),
                    getattr(conf, "maa_orundum", False),
                    getattr(conf, "maa_mining", False),
                    getattr(conf, "maa_specialaccess", False),
                    getattr(conf, "maa_signinevent", False),
                ]
            )
        )

    def has_maa_tasks(self) -> bool:
        conf = config.conf
        kind, _, _ = long_task_schedule(conf, datetime.now())
        return (
            self.has_maa_daily_tasks()
            or getattr(conf, "maa_growth_enabled", False)
            or kind in MAA_LONG_TASK_TYPES
        )

    def _maa_refresh_deadline(self):
        """用同一次观测判断禁启时段并返回其结束时间。"""
        from arknights_mower.utils.news_checker import NewsChecker

        now = datetime.now()
        refresh = NewsChecker.get_daily_reset(now).start
        return refresh if now >= refresh - timedelta(minutes=15) else None

    def _defer_maa_event_shop_for_refresh(self, refresh, *, manual=False):
        """将商店保留为独立剩余步骤，不重复执行已完成日常。"""
        if manual:
            pending = self.task
            steps = getattr(pending, "manual_steps", ["maa_event_shop"])
            if steps and steps[0] == "maa_daily":
                steps[0] = "maa_event_shop"
            pending.manual_steps = steps
        else:
            pending = next(
                (
                    task
                    for task in self.tasks
                    if task.type == TaskTypes.DAILY
                    and task.meta_data == "maa_event_shop_refresh"
                ),
                None,
            )
            if pending is None:
                pending = SchedulerTask(
                    time=datetime.now(),
                    task_type=TaskTypes.DAILY,
                    meta_data="maa_event_shop_refresh",
                )
                pending.manual_steps = ["maa_event_shop"]
                self.tasks.append(pending)
        pending.maa_daily_completion_pending = True
        pending.maa_refresh_until = refresh
        self._defer_maa_for_refresh(refresh)
        self._retain_failed_task(
            pending, "等待每日刷新后兑换活动商店", [], dependency=True
        )

    def _defer_maa_for_refresh(self, refresh, *, manual=False):
        """按每日刷新的确定时间恢复 MAA，不改变原任务时间。"""
        if manual:
            self.task.maa_refresh_until = refresh
        if refresh > datetime.now() and not any(
            getattr(task, "meta_data", "") == "maa_daily_refresh"
            and task.time == refresh
            for task in self.tasks
        ):
            self.tasks.append(
                SchedulerTask(time=refresh, meta_data="maa_daily_refresh")
            )
            self.tasks.sort(
                key=lambda task: (
                    bool(getattr(task, "execution_failure", None)),
                    task.time,
                )
            )
        logger.info("每日刷新前 15 分钟不启动 MAA，刷新后继续")
        return False

    def maa_plan_solver(
        self,
        tasks="All",
        one_time=False,
        *,
        manual=False,
        long_task=None,
        mall_action=None,
        outer_idle_loop=False,
    ):
        with maa_control.execution(), ExitStack() as run_files:
            result = self._run_maa_plan(
                tasks,
                one_time,
                manual=manual,
                long_task=long_task,
                mall_action=mall_action,
                outer_idle_loop=outer_idle_loop,
                run_files=run_files,
            )
        # 正常休息已经离开 MAA 执行范围，唤醒故障仍交回设备恢复。
        if result is True and not manual and not outer_idle_loop:
            self.rest_until_next_task()
        return result

    def _run_maa_plan(
        self,
        tasks,
        one_time,
        *,
        manual,
        long_task,
        mall_action,
        outer_idle_loop,
        run_files,
    ):
        """清日常"""
        copilot_run = None
        copilot_dir = None
        copilot_token = None
        copilot_conf = None
        paradox = False
        sss_run = None
        blackflow_run = None
        large_task_started = False
        shop_started = False
        daily_all = tasks == "All" and not one_time
        try:
            from arknights_mower.solvers.manual_tasks import (
                long_task_deadline,
                manual_task_deadline,
                resume_dorm_releases,
            )

            def release_copilot_attempt():
                if copilot_token is None:
                    return
                progress = (
                    self.maa_paradox_progress if paradox else self.maa_copilot_progress
                )
                if progress.get("attempt", {}).get("token") == copilot_token:
                    self._finish_copilot_item(
                        progress, copilot_token, "released", paradox=paradox
                    )

            run_files.callback(release_copilot_attempt)
            running_long_task = False
            long_limit = datetime.now() + timedelta(hours=24)

            refresh_deferred = False

            def defer_refresh(refresh):
                nonlocal refresh_deferred
                refresh_deferred = True
                return self._defer_maa_for_refresh(refresh, manual=manual)

            def deadline():
                if manual:
                    return manual_task_deadline(self)
                if running_long_task:
                    return long_task_deadline(self, long_limit)
                return self.tasks[0].time

            def large_task_start_allowed():
                if config.stop_mower.is_set():
                    raise MowerExit
                if (refresh := self._maa_refresh_deadline()) is not None:
                    defer_refresh(refresh)
                    return False
                return (
                    not config.stop_maa.is_set()
                    and (deadline() - datetime.now()).total_seconds() > 30
                )

            if config.stop_mower.is_set():
                raise MowerExit
            if (refresh := self._maa_refresh_deadline()) is not None:
                return defer_refresh(refresh)

            record_execution = not one_time and (
                not manual or tasks == "All" or "Fight" in tasks
            )
            self.drop_send = False
            conf = config.conf
            if (
                not one_time
                and not manual
                and tasks
                and len(self.tasks) > 0
                and (deadline() - datetime.now()).total_seconds() < 300
            ):
                logger.info(
                    "距离下次基建任务不足5分钟，跳过MAA日常任务",
                    extra={"log_group": "maa-integration"},
                )
                return
            if (
                not one_time
                and not manual
                and self.last_execution["maa"] is not None
                and (
                    delta := (
                        timedelta(hours=conf.maa_gap)
                        + self.last_execution["maa"]
                        - datetime.now()
                    )
                )
                > timedelta()
            ):
                logger.info(
                    f"{format_time(delta.total_seconds())}后开始做日常任务",
                    extra={"log_group": "maa-integration"},
                )
            elif not tasks or tasks == "All" and not self.has_maa_daily_tasks():
                logger.info(
                    "没有启用的 MAA 日常任务，跳过日常",
                    extra={"log_group": "maa-integration"},
                )
            else:
                if tasks == "All":
                    tasks = ["StartUp"]
                    if getattr(
                        conf,
                        "should_run_maa_stage_plan",
                        getattr(conf, "stage_plan_enable", True)
                        and getattr(conf, "stage_plan_runner", "maa") == "maa",
                    ):
                        tasks.append("Fight")
                    if getattr(
                        conf,
                        "should_run_maa_mall_task",
                        (
                            getattr(conf, "maa_mall_enable", True)
                            and getattr(conf, "maa_mall_mode", "maa") == "maa"
                        )
                        or (
                            getattr(conf, "visit_friend_enable", False)
                            and getattr(conf, "visit_friend_mode", "maa") == "maa"
                        )
                        or getattr(conf, "maa_credit_fight", False),
                    ):
                        tasks.append("Mall")
                    tasks.append("Award")
                if "Fight" in tasks and not one_time:
                    from arknights_mower.solvers.event_rerun import run_event_rerun

                    if run_event_rerun(self, deadline) is not None:
                        if (
                            config.maintenance_recheck.is_set()
                            or (deadline() - datetime.now()).total_seconds() < 300
                        ):
                            return False if manual else None
                        if (refresh := self._maa_refresh_deadline()) is not None:
                            return defer_refresh(refresh)
                send_message("启动MAA", subject="准备启动 MAA")
                self.back_to_index()
                # 任务及参数请参考 docs/集成文档.md
                self.initialize_maa()
                for maa_task in tasks:
                    if mall_action:
                        self.append_maa_task(maa_task, mall_action=mall_action)
                    else:
                        self.append_maa_task(maa_task)
                self.append_maa_theme_task()
                if (refresh := self._maa_refresh_deadline()) is not None:
                    self.maa_stop()
                    return defer_refresh(refresh)
                if config.stop_mower.is_set():
                    raise MowerExit
                if config.stop_maa.is_set():
                    self.maa_stop()
                    return not manual
                self.MAA.start()
                stop_time = None
                if one_time:
                    stop_time = datetime.now() + timedelta(minutes=5)
                else:
                    reset_stage_drop()

                logger.info("MAA 启动", extra={"log_group": "maa-integration"})
                hard_stop = False
                while self.MAA.running():
                    self.report_maa_progress()
                    self.recog.update()
                    self.recog.save_screencap(None)
                    # 单次任务默认5分钟
                    if one_time and stop_time < datetime.now():
                        self.maa_stop()
                        hard_stop = True
                    # 5分钟之前就停止
                    elif (
                        not one_time
                        and (deadline() - datetime.now()).total_seconds() < 300
                    ):
                        self.maa_stop()
                        hard_stop = True
                    elif config.stop_maa.is_set() or config.stop_mower.is_set():
                        self.maa_stop()
                        hard_stop = True
                    else:
                        self.sleep(5)
                if config.stop_mower.is_set():
                    raise MowerExit
                # MAA 运行期间只保存截图，没有连续执行 Mower 场景识别。
                self.recog.reset_after_external_control()
                if hard_stop and manual:
                    return False
                if hard_stop:
                    hard_stop_msg = "MAA任务未完成，等待3分钟后按空闲设置处理"
                    logger.info(hard_stop_msg, extra={"log_group": "maa-integration"})
                    send_message(hard_stop_msg, subject="MAA 任务未完成")
                    self.sleep(180)
                    next_task = self.find_next_task()
                    remaining_time = (
                        (next_task.time - datetime.now()).total_seconds()
                        if next_task is not None
                        else 0
                    )
                    if self._get_idle_action(remaining_time) not in ("exit", "close"):
                        self.device.exit()
                        self.device.check_current_focus()
                        self.recog.update()
                        # 返回游戏主页时完成登录，空闲处理再按设置切回安卓首页。
                        self.back_to_index()
                elif record_execution:
                    if daily_all and getattr(
                        getattr(config.conf, "maa_event_shop", None), "enable", False
                    ):
                        shop_started = True
                        if self.run_maa_event_shop(deadline, manual=manual) is False:
                            return False
                    logger.info(
                        "记录MAA 本次执行时间", extra={"log_group": "maa-integration"}
                    )
                    self.last_execution["maa"] = datetime.now()
                    logger.info(
                        self.last_execution["maa"],
                        extra={"log_group": "maa-integration"},
                    )
                    if "Mall" in tasks and self._maa_daily_done("credit_fight"):
                        self.maa_stop(False)
                elif not manual:
                    send_message("MAA单次任务停止", subject="MAA 单次任务停止")
                    if (
                        self.find_next_task(datetime.now() + timedelta(minutes=15))
                        is None
                    ):
                        logger.debug(
                            "MAA单次任务结束15分钟内没有其他任务，新增单次任务防止漏单",
                            extra={"log_group": "maa-integration"},
                        )
                        self.tasks.insert(0, SchedulerTask(time=datetime.now()))
            conf = config.conf
            now = datetime.now()
            selected_long = long_task
            if not manual:
                selected_long, cutoff, _ = long_task_schedule(conf, now)
                long_limit = min(long_limit, cutoff)
                if (
                    cutoff - now < timedelta(minutes=9)
                    or selected_long == "garrison"
                    or outer_idle_loop
                    and selected_long not in MAA_LONG_TASK_TYPES
                ):
                    selected_long = None
            running_long_task = True
            if selected_long and (refresh := self._maa_refresh_deadline()) is not None:
                return defer_refresh(refresh)
            if selected_long and deadline() - datetime.now() < timedelta(seconds=30):
                selected_long = None
            paradox = selected_long == "paradox"
            from arknights_mower.utils.maa_long_task import blackflow_preserved_run

            if (
                selected_long == "rogue"
                and conf.maa_rg_theme == "BlackFlow"
                and blackflow_preserved_run(conf.rogue) is not None
            ):
                blackflow_run = self._maa_blackflow_run(conf.rogue)
                if blackflow_run.get("completed") is True:
                    selected_long = None
            if selected_long in ("copilot", "paradox"):
                from arknights_mower.utils.config_backup import backup_lock

                with backup_lock:
                    copilot_conf = getattr(config.conf, selected_long)
                    copilot_run = self._maa_copilot_run(copilot_conf, paradox=paradox)
            if selected_long == "sss":
                sss_run = self._maa_sss_run(conf.sss)
            if (
                selected_long in ("rogue", "rcl")
                or (
                    sss_run is not None
                    and not sss_run["failed"]
                    and sss_run["next"] < len(conf.sss.scripts)
                )
                or (
                    copilot_run is not None
                    and not copilot_run["failed"]
                    and copilot_run["next"] < len(copilot_conf.scripts)
                )
            ):
                logger.info(
                    "准备开始 MAA 大型任务", extra={"log_group": "maa-integration"}
                )
                send_message("启动 MAA 大型任务", subject="准备启动 MAA 大型任务")
                while True:
                    if config.stop_mower.is_set():
                        raise MowerExit
                    if config.stop_maa.is_set():
                        break
                    if (refresh := self._maa_refresh_deadline()) is not None:
                        return defer_refresh(refresh)
                    if copilot_run is not None:
                        token = uuid4().hex
                        with backup_lock:
                            conf = config.conf
                            if not manual:
                                current_long, cutoff, _ = long_task_schedule(
                                    conf, datetime.now()
                                )
                                if current_long != selected_long:
                                    break
                                long_limit = min(long_limit, cutoff)
                            copilot_conf = getattr(conf, selected_long)
                            claim = claim_copilot_item(
                                copilot_conf, copilot_run["key"], token, paradox=paradox
                            )
                        if claim is None:
                            break
                        copilot_token = token
                        copilot_run = claim
                        copilot_index = claim["next"]
                        if paradox:
                            self.maa_paradox_progress = claim
                        else:
                            self.maa_copilot_progress = claim
                    self.release_maa()
                    if not paradox:
                        self.initialize_maa()
                    if selected_long not in ("sss", "rcl"):
                        from arknights_mower.utils.device.io_budget import (
                            device_io_budget,
                        )

                        large_task_started = True
                        navigation_end = monotonic() + 60

                        def navigation_remaining():
                            if config.stop_mower.is_set():
                                raise MowerExit
                            if (
                                config.stop_maa.is_set()
                                or (deadline() - datetime.now()).total_seconds() <= 30
                            ):
                                raise InterruptedError
                            seconds = navigation_end - monotonic()
                            if seconds <= 0:
                                raise TimeoutError("MAA 大型任务启动前导航超时")
                            return min(
                                seconds,
                                (deadline() - datetime.now()).total_seconds() - 30,
                            )

                        try:
                            with device_io_budget(navigation_remaining):
                                self.recog.reset_after_external_control()
                                self.back_to_index()
                                if paradox:
                                    ready = self.to_operator_list()
                                else:
                                    self.scene_graph_navigation(Scene.TERMINAL_MAIN)
                                    navigation_remaining()
                                    if selected_long == "copilot":
                                        from arknights_mower.utils.maa_copilot import (
                                            copilot_navigation_target,
                                        )

                                        target = copilot_navigation_target(
                                            copilot_conf.scripts[copilot_index]
                                        )
                                        navigator = NavigationSolver(
                                            self.device, self.recog
                                        )
                                        ready = navigator.run(target)
                                        navigation_remaining()
                                        if ready:
                                            ready = navigator.confirm_selected_stage()
                                        if ready:
                                            navigation_remaining()
                                            navigator.back()
                                    else:
                                        ready = self.scene() == Scene.TERMINAL_MAIN
                                navigation_remaining()
                                if not ready:
                                    if paradox:
                                        raise ValueError(
                                            "未确认干员列表，未启动悖论模拟"
                                        )
                                    if selected_long == "copilot":
                                        raise ValueError(
                                            "未确认作业关卡详情，请检查导航关卡名与 Mower AI 配置"
                                        )
                                    raise ValueError(
                                        "未确认终端首页，未启动 MAA 大型任务"
                                    )
                        except InterruptedError:
                            break
                        if paradox:
                            self.initialize_maa()
                        if config.stop_mower.is_set():
                            raise MowerExit
                        if (
                            config.stop_maa.is_set()
                            or (deadline() - datetime.now()).total_seconds() <= 30
                        ):
                            break
                    else:
                        self.recog.reset_after_external_control()
                        self.back_to_index()
                    if not large_task_start_allowed():
                        break
                    large_task_interrupted = False
                    if selected_long == "rogue":
                        professional = conf.rogue.squad in _PROFESSIONAL_SQUADS
                        rogue_params = {
                            "theme": conf.maa_rg_theme,
                            "squad": conf.rogue.squad,
                            "roles": conf.rogue.roles,
                            "core_char": conf.rogue.core_char,
                            "use_support": conf.rogue.use_support,
                            "use_nonfriend_support": conf.rogue.use_nonfriend_support,
                            "mode": conf.rogue.mode,
                            "starts_count": 9999999,
                            "investments_count": 9999999,
                            "difficulty": conf.rogue.difficulty,
                            "investment_enabled": conf.rogue.investment_enabled,
                            "refresh_trader_with_dice": (
                                conf.maa_rg_theme == "Mizuki"
                                and conf.rogue.refresh_trader_with_dice
                            ),
                        }
                        if conf.rogue.investment_enabled:
                            rogue_params["investment_with_more_score"] = (
                                conf.maa_rg_theme != "BlackFlow"
                                and conf.rogue.investment_with_more_score
                                and conf.rogue.mode == 1
                            )
                            rogue_params["stop_when_investment_full"] = (
                                conf.rogue.stop_when_investment_full
                                and conf.rogue.mode == 1
                            )
                        if conf.maa_rg_theme != "Phantom" and conf.rogue.mode == 0:
                            rogue_params["stop_at_final_boss"] = (
                                conf.rogue.stop_at_final_boss
                            )
                        if conf.rogue.mode == 0:
                            rogue_params["stop_at_max_level"] = (
                                conf.rogue.stop_at_max_level
                            )
                        if (
                            conf.maa_rg_theme == "Sami"
                            and conf.rogue.mode == 5
                            and conf.rogue.expected_collapsal_paradigms
                        ):
                            rogue_params["expected_collapsal_paradigms"] = (
                                conf.rogue.expected_collapsal_paradigms
                            )
                        if conf.rogue.mode == 4:
                            rogue_params["collectible_mode_shopping"] = (
                                conf.rogue.collectible_mode_shopping
                            )
                            rogue_params["collectible_mode_squad"] = (
                                conf.rogue.collectible_mode_squad
                            )
                            # 协议值语义：直升需与战术分队类同步，只凹仅受主题/策略限制
                            rogue_params["start_with_elite_two"] = (
                                conf.rogue.start_with_elite_two
                                and professional
                                and conf.maa_rg_theme in ("Mizuki", "Sami")
                            )
                            rogue_params["only_start_with_elite_two"] = (
                                conf.rogue.only_start_with_elite_two
                                and conf.maa_rg_theme in ("Mizuki", "Sami")
                            )
                            # 勾选「只凹开局干员直升精二」时不刷奖励，撤销下发
                            elite_two_only = (
                                conf.rogue.only_start_with_elite_two
                                and conf.rogue.start_with_elite_two
                                and conf.maa_rg_theme != "Phantom"
                                and professional
                            )
                            if not elite_two_only:
                                rogue_params["collectible_mode_start_list"] = {
                                    key: conf.rogue.collectible_mode_start_list.get(
                                        key, False
                                    )
                                    for key in _COLLECTIBLE_START_KEYS
                                }
                        if conf.rogue.mode == 6:
                            rogue_params["monthly_squad_auto_iterate"] = (
                                conf.rogue.monthly_squad_auto_iterate
                            )
                            if conf.rogue.monthly_squad_auto_iterate:
                                rogue_params["monthly_squad_check_comms"] = (
                                    conf.rogue.monthly_squad_check_comms
                                )
                        if conf.rogue.mode == 7:
                            rogue_params["deep_exploration_auto_iterate"] = (
                                conf.rogue.deep_exploration_auto_iterate
                            )
                        if (
                            conf.maa_rg_theme == "Sami"
                            and conf.rogue.mode == 4
                            and conf.rogue.first_floor_foldartal
                        ):
                            rogue_params["first_floor_foldartal"] = (
                                conf.rogue.first_floor_foldartal
                            )
                        if (
                            conf.maa_rg_theme == "Sami"
                            and conf.rogue.mode == 4
                            and conf.rogue.squad == "生活至上分队"
                            and conf.rogue.start_foldartal_list
                        ):
                            rogue_params["start_foldartal_list"] = (
                                conf.rogue.start_foldartal_list
                            )
                        if (
                            conf.maa_rg_theme == "BlackFlow"
                            and conf.rogue.mode == 30001
                        ):
                            # 协议固定刷襁褓动物策略，仅目标品种可选
                            rogue_params["blackflow_strategy"] = "baby_animal"
                            rogue_params["blackflow_cultivation_target"] = (
                                conf.rogue.blackflow_cultivation_target
                            )
                        if (
                            conf.maa_rg_theme == "JieGarden"
                            and conf.rogue.mode == 20001
                        ):
                            rogue_params["find_playTime_target"] = (
                                conf.rogue.find_playtime_target
                            )
                        recruits = getattr(conf.rogue, "core_char_list", [])
                        if recruits:
                            rogue_params["core_char_list"] = [
                                item.model_dump() for item in recruits
                            ]
                        if conf.maa_rg_theme == "Sami":
                            for key in (
                                "use_foldartal",
                                "check_collapsal_paradigms",
                                "double_check_collapsal_paradigms",
                            ):
                                value = getattr(conf.rogue, key, None)
                                checking = getattr(
                                    conf.rogue, "check_collapsal_paradigms", None
                                )
                                if checking is None:
                                    checking = conf.rogue.mode == 5
                                if value is not None and (
                                    key != "double_check_collapsal_paradigms"
                                    or checking
                                ):
                                    rogue_params[key] = value
                        if (
                            conf.maa_rg_theme == "Sarkaz"
                            and conf.rogue.mode == 1
                            and conf.rogue.squad in ("点刺成锭分队", "后勤分队")
                        ):
                            seed = getattr(conf.rogue, "start_with_seed", "")
                            if seed:
                                rogue_params["start_with_seed"] = seed
                        if conf.maa_rg_theme == "BlackFlow":
                            if conf.rogue.mode == 0:
                                rogue_params["blackflow_strategy"] = "ending1"
                            if conf.rogue.mode == 30003:
                                for key, default in (
                                    ("blackflow_start_animals", []),
                                    ("blackflow_start_rewards", 0),
                                    ("blackflow_start_utopia", False),
                                    ("collectible_mode_squad", ""),
                                ):
                                    rogue_params[key] = getattr(
                                        conf.rogue, key, default
                                    )
                                if rogue_params["blackflow_start_utopia"]:
                                    rogue_params["blackflow_start_reward_priority"] = (
                                        conf.rogue.blackflow_start_reward_priority
                                    )
                                if getattr(conf.rogue, "collectible_mode_roles", ""):
                                    rogue_params["collectible_mode_roles"] = (
                                        conf.rogue.collectible_mode_roles
                                    )
                                preparation = getattr(
                                    conf.rogue, "collectible_mode_core_char_list", []
                                )
                                if preparation:
                                    rogue_params["collectible_mode_core_char_list"] = [
                                        item.model_dump() for item in preparation
                                    ]
                            flight_prefix = None
                            if conf.rogue.mode == 0 and getattr(
                                conf.rogue, "blackflow_fast_flight", False
                            ):
                                flight_prefix = ""
                                rogue_params.pop("blackflow_strategy", None)
                            elif conf.rogue.mode == 30003 and getattr(
                                conf.rogue, "blackflow_start_run_fast_flight", False
                            ):
                                flight_prefix = "collectible_mode_"
                            if flight_prefix is not None:
                                rogue_params[flight_prefix + "squad"] = "特勤分队"
                                rogue_params[flight_prefix + "roles"] = "稳扎稳打"
                                rogue_params[flight_prefix + "core_char_list"] = [
                                    {"name": "机械师", "use_support": False}
                                ]
                                if not flight_prefix:
                                    rogue_params["core_char"] = "机械师"
                                    rogue_params["use_support"] = False
                        if not large_task_start_allowed():
                            break
                        task_id = self.MAA.append_task("Roguelike", rogue_params)
                        if (
                            blackflow_run is not None
                            and type(task_id) is int
                            and task_id > 0
                        ):
                            self.maa_blackflow_task = (task_id, blackflow_run)
                    elif selected_long in ("copilot", "paradox"):
                        from arknights_mower.utils.maa_copilot import (
                            build_copilot_params,
                            build_paradox_params,
                        )

                        if paradox:
                            params = build_paradox_params(
                                copilot_conf.scripts[copilot_index], copilot_index
                            )
                        else:
                            if copilot_dir is None:
                                copilot_dir = pathlib.Path(
                                    run_files.enter_context(
                                        TemporaryDirectory(
                                            dir=temporary_root(), prefix="copilot-"
                                        )
                                    )
                                )
                            params = build_copilot_params(
                                copilot_conf, copilot_dir, index=copilot_index
                            )
                            params["copilot_list"][0]["nav_name_override"] = target
                        if not large_task_start_allowed():
                            break
                        task_id = self.MAA.append_task(
                            "ParadoxCopilot" if paradox else "Copilot", params
                        )
                        if not task_id:
                            raise ValueError("MAA 未接受作业，请检查核心版本和作业文件")
                        setattr(
                            self,
                            "maa_paradox_task" if paradox else "maa_copilot_task",
                            (task_id, copilot_run["key"], copilot_index, copilot_token),
                        )
                    elif selected_long == "sss":
                        from arknights_mower.utils.maa_sss import build_sss_params

                        sss_index = sss_run["next"]
                        completed_before = sss_run["completed"]
                        item = conf.sss.scripts[sss_index]
                        params = build_sss_params(item)
                        if self.to_sss(item.type, item.ec):
                            raise ValueError("保全派驻导航失败")
                        if not large_task_start_allowed():
                            break
                        task_id = self.MAA.append_task("SSSCopilot", params)
                        self.maa_sss_task = {
                            "id": task_id,
                            "position": (sss_run["key"], sss_index, completed_before),
                            "times": item.times,
                            "passed": False,
                            "settled": False,
                        }
                    elif selected_long == "rcl":
                        self.to_reclamation(conf.maa_rcl_theme, conf.rcl.mode)
                        rcl_params = {
                            "theme": conf.maa_rcl_theme,
                            "mode": conf.rcl.mode,
                        }
                        if conf.maa_rcl_theme == "Tales":
                            if conf.rcl.mode == 0:
                                rcl_params["clear_store"] = getattr(
                                    conf.rcl, "clear_store", False
                                )
                            elif conf.rcl.mode == 1:
                                for key in (
                                    "tools_to_craft",
                                    "increment_mode",
                                    "num_craft_batches",
                                ):
                                    rcl_params[key] = getattr(conf.rcl, key)
                        if not large_task_start_allowed():
                            break
                        self.MAA.append_task("Reclamation", rcl_params)
                    if not large_task_start_allowed():
                        self.maa_stop()
                        break
                    logger.info("启动", extra={"log_group": "maa-integration"})
                    large_task_started = True
                    self.MAA.start()
                    while self.MAA.running():
                        csleep(5)
                        if config.stop_mower.is_set():
                            raise MowerExit
                        self.report_maa_progress()
                        self.recog.update()
                        self.recog.save_screencap(None)
                        if config.stop_mower.is_set():
                            raise MowerExit
                        if (
                            deadline() - datetime.now() < timedelta(seconds=30)
                            or config.stop_maa.is_set()
                        ):
                            self.maa_stop()
                            large_task_interrupted = True
                            break
                    if config.stop_mower.is_set():
                        raise MowerExit
                    self.recog.reset_after_external_control()
                    more_copilot = (
                        copilot_token is not None
                        and copilot_token
                        == getattr(self, "_completed_copilot_attempt", None)
                    )
                    more_sss = (
                        sss_run is not None
                        and (sss_run["next"], sss_run["completed"])
                        != (sss_index, completed_before)
                        and not sss_run["failed"]
                        and sss_run["next"] < len(conf.sss.scripts)
                    )
                    if (
                        (more_copilot or more_sss)
                        and not config.stop_maa.is_set()
                        and not config.stop_mower.is_set()
                        and not large_task_interrupted
                        and deadline() - datetime.now() > timedelta(seconds=30)
                    ):
                        continue
                    break

                if refresh_deferred:
                    return False

            elif not outer_idle_loop:
                if selected_long == "ra":
                    self.back_to_index()
                    ra_solver = ReclamationAlgorithm(self.device, self.recog)
                    try:
                        ra_solver.run(deadline() - datetime.now())
                    finally:
                        resume_dorm_releases(self)
                elif selected_long == "sf":
                    self.back_to_index()
                    sf_solver = SecretFront(self.device, self.recog)
                    try:
                        sf_solver.run(deadline() - datetime.now())
                    finally:
                        resume_dorm_releases(self)

            if not manual and (refresh := self._maa_refresh_deadline()) is not None:
                defer_refresh(refresh)
            self.release_maa()
        except MowerExit:
            maa_control.stop_for_mower_exit(self, large_task_started, shop_started)
            raise
        except (DeviceRecoveryError, SharedADBError):
            try:
                if getattr(self, "MAA", None) is not None:
                    self.maa_stop()
                    logger.info("停止MAA", extra={"log_group": "maa-integration"})
            finally:
                self.release_maa()
            raise
        except Exception as e:
            if sss_run is not None:
                sss_run["failed"] = True
                try:
                    save_maa_sss_progress(sss_run)
                except Exception:
                    logger.exception(
                        "保存 MAA 保全派驻进度失败",
                        extra={"log_group": "maa-integration"},
                    )
            if copilot_token is not None:
                try:
                    self._finish_copilot_item(
                        copilot_run, copilot_token, "failed", paradox=paradox
                    )
                except Exception:
                    logger.exception(
                        "保存 MAA 自动战斗作业进度失败",
                        extra={"log_group": "maa-integration"},
                    )
            save_exception(e)
            logger.exception(e, extra={"log_group": "maa-integration"})
            if getattr(self, "MAA", None) is not None:
                try:
                    self.MAA.stop()
                except (MowerExit, DeviceRecoveryError, SharedADBError):
                    raise
                except Exception:
                    logger.exception(
                        "MAA 异常后的任务清理失败，保留原始调用错误",
                        extra={"log_group": "maa-integration"},
                    )
            self.release_maa()
            battle_inventory_active.clear()
            send_message(str(e), "MAA 调用出错", level="ERROR")
            if manual:
                raise
            if large_task_started:
                resume_dorm_releases(self)
                large_task_started = False
            running_long_task = False
            self.recog.last_scene = None
        else:
            battle_inventory_active.clear()
            if large_task_started:
                resume_dorm_releases(self)
                large_task_started = False
        finally:
            if large_task_started:
                resume_dorm_releases(self)
            self.release_maa()
            battle_inventory_active.clear()
        return True

    def skland_plan_solver(self):
        today = get_server_time().date()
        solver = None
        try:
            solver = SKLand()
            completed = solver.start()
        except MowerExit:
            raise
        except Exception as e:
            secrets = getattr(solver, "_log_secrets", ()) if solver else ()
            message = (
                f"森空岛签到失败（{type(e).__name__}）："
                f"{redact_signing_text(e, *secrets)}"
            )
            save_log(message, level="ERROR")
            logger.error(
                message,
                extra={"log_group": "local-operation", "archive_screenshots": False},
            )
            send_message(message, subject="森空岛签到失败", level="ERROR")
            completed = False
        if completed is None:
            return False
        self.daily_skland_attempt = today
        if completed:
            self.daily_skland = today
        save_current_state()
        return completed

    def recruit_plan_solver(self):
        if self.last_execution[
            "recruit"
        ] is None or datetime.now() > self.last_execution["recruit"] + timedelta(
            hours=config.conf.recruit_gap
        ):
            RecruitSolver(self.device, self.recog).run()

            self.last_execution["recruit"] = datetime.now()
            logger.info(
                f"下一次公开招募执行时间在{config.conf.recruit_gap}小时之后",
                extra={"log_group": "recruitment"},
            )

    def apply_maa_stage_inventory_rules(self, stages) -> list[str]:
        conf = config.conf
        original = list(stages)
        if not conf.maa_stage_inventory_enable:
            return original

        from arknights_mower.utils.maa_stage_inventory import (
            default_materials_for_stage,
            load_inventory_snapshot,
            reached_stage_limit_materials,
            select_stages_by_inventory,
        )

        if not conf.maa_stage_limit_rules and not conf.maa_stage_ratio_rules:
            return select_stages_by_inventory(original)["stages"]

        inventory, updated_at = load_inventory_snapshot()
        selection = select_stages_by_inventory(
            original,
            limit_rules=conf.maa_stage_limit_rules,
            ratio_rules=conf.maa_stage_ratio_rules,
            inventory=inventory,
        )
        for stage in selection["limit_skipped"]:
            materials = reached_stage_limit_materials(
                stage, conf.maa_stage_limit_rules, inventory
            )
            stage_metadata = next(
                (item for item in stage_data_full if item.get("id") == stage), None
            )
            drops = [
                item["name"]
                for item in default_materials_for_stage(stage, stage_metadata)
                if item["name"] != item["id"]
            ]
            logger.info(
                "%s库存已达到设定上限，本轮跳过%s",
                "、".join(materials) or "对应材料",
                stage,
                extra={
                    "log_group": "weekly-plan-editor",
                    "log_event": {
                        "type": "stage-inventory-limit",
                        "stage": {"code": stage, "drops": drops},
                    },
                },
            )
        for decision in selection["ratio_decisions"]:
            logger.debug(
                "库存比例选关 | rule=%s | selected=%s | candidates=%s",
                decision["name"],
                decision["selected"],
                decision["candidates"],
                extra={"log_group": "weekly-plan-editor"},
            )
            ratios = [item["ratio"] for item in decision["candidates"]]
            ratio_text = ":".join(
                str(int(value)) if value.is_integer() else str(value)
                for value in ratios
            )
            rule = (
                f"比例规则「{decision['name']}」"
                if decision["name"].strip()
                else "比例规则"
            )
            comparison = (
                f"相同（{ratio_text}）"
                if all(value == ratios[0] for value in ratios)
                else f"为 {ratio_text}"
            )
            stage = decision["selected"]
            stage_metadata = next(
                (item for item in stage_data_full if item.get("id") == stage), None
            )
            drops = [
                item["name"]
                for item in default_materials_for_stage(stage, stage_metadata)
                if item["name"] != item["id"]
            ]
            logger.info(
                f"{rule}的刷取比例{comparison}，优先刷取库存相对不足的材料，本轮选择 {stage}",
                extra={
                    "log_group": "weekly-plan-editor",
                    "log_event": {
                        "type": "stage-inventory-ratio",
                        "stage": {"code": stage, "drops": drops},
                    },
                },
            )
        logger.debug(
            "库存选关完成 | snapshot=%s | original=%s | selected=%s",
            updated_at,
            original,
            selection["stages"],
            extra={"log_group": "weekly-plan-editor"},
        )
        self._log_stage_inventory_plan(selection["stages"])
        return selection["stages"]

    @staticmethod
    def _log_stage_inventory_plan(stages):
        """按实际结果显示刷取顺序，特殊关卡只转换名称，不虚构固定掉落。"""
        from arknights_mower.utils.maa_stage_inventory import (
            default_materials_for_stage,
        )

        aliases = {"Annihilation": "当期剿灭", "": "上次作战"}
        entries = []
        for stage in stages:
            stage_metadata = next(
                (item for item in stage_data_full if item.get("id") == stage), None
            )
            drops = (
                []
                if stage in aliases
                else [
                    item["name"]
                    for item in default_materials_for_stage(stage, stage_metadata)
                    if item["name"] != item["id"]
                ]
            )
            entries.append(
                {"code": stage, "label": aliases.get(stage, stage), "drops": drops}
            )
        message = (
            "接下来计划依次刷取" + " → ".join(item["label"] for item in entries)
            if entries
            else "当前没有待刷关卡"
        )
        logger.info(
            message,
            extra={
                "log_group": "weekly-plan-editor",
                "log_event": {"type": "stage-inventory-plan", "stages": entries},
            },
        )

    def mower_stage_plan(self, excluded_stages=(), attempted_growth=()):
        from arknights_mower.utils.config_backup import backup_lock
        from arknights_mower.utils.growth_farming import active_chip_farming_target

        with backup_lock:
            filter_by_availability = self.maybe_switch_expired_activity_plan()
            plan = config.conf.maa_weekly_plan[get_server_weekday()]
        growth = None
        if type(filter_by_availability) is bool:
            growth = active_chip_farming_target(plan.weekday, filter_by_availability)
        if growth and growth.rules:
            stages = [
                stage
                for stage in growth.rules
                if (growth.char_id, stage) not in attempted_growth
            ]
            if stages:
                if (
                    "Annihilation" in plan.stage
                    and "Annihilation" not in excluded_stages
                ):
                    stages.insert(0, "Annihilation")
                return stages, growth
        excluded = set(excluded_stages) | {stage for _, stage in attempted_growth}
        stages = [
            stage.strip()
            for stage in plan.stage
            if isinstance(stage, str)
            and stage.strip()
            and stage.strip() not in excluded
        ]
        return self.apply_maa_stage_inventory_rules(stages), None

    def mower_stage_ap_cost(self, stage_id: str) -> int | None:
        stage_meta = next(
            (item for item in stage_data_full if item.get("id") == stage_id),
            None,
        )
        if stage_meta is None:
            return self._ap_fallback_or_none()
        ap_cost = stage_meta.get("apCost")
        if not isinstance(ap_cost, int) or ap_cost <= 0:
            return self._ap_fallback_or_none()
        return ap_cost

    def _ap_fallback_or_none(self) -> int | None:
        from arknights_mower.utils.config import conf

        fallback = conf.ap_fallback
        if isinstance(fallback, int) and fallback > 0:
            return fallback
        return None

    def clear_local_operation_followups(self):
        existing_count = sum(
            1 for task in self.tasks if task.meta_data == FOLLOWUP_TASK_META
        )
        self.tasks = [
            task for task in self.tasks if task.meta_data != FOLLOWUP_TASK_META
        ]
        self.local_operation_followup_time = None
        if existing_count:
            logger.debug(
                "clear local operation follow-up tasks | count=%s",
                existing_count,
                extra={"log_group": "local-operation"},
            )

    def upsert_local_operation_followup(self, run_at: datetime | None):
        self.clear_local_operation_followups()
        if run_at is None:
            logger.debug(
                "skip local operation follow-up insert because run_at is empty",
                extra={"log_group": "local-operation"},
            )
            return
        self.tasks.append(SchedulerTask(time=run_at, meta_data=FOLLOWUP_TASK_META))
        self.tasks.sort(
            key=lambda task: (bool(getattr(task, "execution_failure", None)), task.time)
        )
        self.local_operation_followup_time = run_at
        logger.debug(
            "schedule local operation follow-up task | run_at=%s",
            run_at.strftime("%Y-%m-%d %H:%M:%S"),
            extra={"log_group": "local-operation"},
        )

    def get_local_operation_stage_target(
        self,
        stage: str,
        simulated_current_ap: int | None,
        threshold_control_failed: bool,
        threshold: int,
        maa_gap: float,
    ):
        ap_cost = self.mower_stage_ap_cost(stage)
        projection = None
        if threshold_control_failed:
            target_total_runs = get_stage_drain_runs_total(
                simulated_current_ap,
                ap_cost,
            )
        else:
            target_total_runs, projection = get_required_runs_total(
                simulated_current_ap,
                threshold,
                maa_gap,
                ap_cost,
            )
        return ap_cost, target_total_runs, projection

    def report_annihilation_agency_locked(self):
        subject = "剿灭代理指挥未解锁"
        body = (
            "本次刷理智跳过了剿灭，继续后面的关卡。"
            "请检查是否已在不使用助战干员的情况下手动通关当期剿灭并达到 400 击杀；"
            "解锁代理指挥后，下次刷理智会自动代理剿灭。"
        )
        today = get_server_time().date()
        if self.annihilation_lock_mail_day == today:
            # 同一游戏日只发一封邮件、归档一次截图，之后每次跳过只写日志。
            logger.error(
                "%s：%s",
                subject,
                body,
                extra={"log_group": "local-operation", "archive_screenshots": False},
            )
            return
        self.annihilation_lock_mail_day = today
        send_message(
            body,
            subject,
            level="ERROR",
            archive_screenshots=True,
            screenshot_source=getattr(self, "device", None),
        )
        try:
            save_current_state()
        except Exception as exc:
            if is_memory_error(exc):
                raise
            logger.warning(
                "未能保存剿灭代理指挥提醒日期：%s",
                exc,
                extra={"log_group": "local-operation"},
            )

    @observed_activity("stage-plan", "mower", stopped_exceptions=(MowerExit,))
    def run_local_operation_stage(
        self,
        stage: str,
        next_task_time: datetime,
        simulated_current_ap: int | None,
        ap_cost: int | None,
        target_total_runs: int | None,
        mode: str,
        threshold: int | None = None,
        inventory_limit_rules=None,
    ):
        remaining_runs = target_total_runs
        executed_any = False
        executed_runs = 0
        observe_activity(self, "stage-plan", "mower", "running", stage=stage)

        while True:
            if next_task_time - datetime.now() < timedelta(minutes=5):
                observe_activity(
                    self,
                    "stage-plan",
                    "mower",
                    "checked",
                    stage=stage,
                    executed_runs=executed_runs,
                    reason="stopped_by_deadline",
                )
                logger.info(
                    "离下一个任务开始不到 5 分钟，结束本次刷关",
                    extra={"log_group": "local-operation"},
                )
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": True,
                }
            if remaining_runs is not None and remaining_runs <= 0:
                observe_activity(
                    self,
                    "stage-plan",
                    "mower",
                    "checked",
                    stage=stage,
                    executed_runs=executed_runs,
                    reason="target_reached",
                )
                logger.debug(
                    "local operation stage completed | stage=%s | mode=%s",
                    stage,
                    mode,
                    extra={"log_group": "local-operation"},
                )
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                }

            if remaining_runs is not None:
                logger.info(
                    "前往 %s，计划打 %s 次",
                    stage,
                    remaining_runs,
                    extra={"log_group": "local-operation"},
                )
            else:
                logger.info(
                    "前往 %s，打一轮", stage, extra={"log_group": "local-operation"}
                )
            logger.debug(
                "start navigation before operation | stage=%s | mode=%s | simulated_current_ap=%s | ap_cost=%s | remaining_runs=%s",
                stage,
                mode,
                simulated_current_ap,
                ap_cost,
                remaining_runs,
                extra={"log_group": "local-operation"},
            )
            observe_activity(
                self,
                "stage-plan",
                "mower",
                "running",
                stage=stage,
                executed_runs=executed_runs,
            )
            if not NavigationSolver(self.device, self.recog).run(stage):
                observe_activity(
                    self,
                    "stage-plan",
                    "mower",
                    "incomplete",
                    stage=stage,
                    executed_runs=executed_runs,
                    reason="navigation",
                )
                logger.warning(
                    "导航到 %s 失败，跳过这一关",
                    stage,
                    extra={"log_group": "local-operation"},
                )
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                }

            logger.debug(
                "navigation succeeded, start operation | stage=%s | mode=%s | target_total_runs=%s",
                stage,
                mode,
                remaining_runs,
                extra={"log_group": "local-operation"},
            )
            result = OperationSolver(self.device, self.recog).run(
                next_task_time=next_task_time,
                stage_id=stage,
                target_total_runs=remaining_runs,
                simulated_current_ap=simulated_current_ap,
                ap_cost=ap_cost,
                sanity_threshold=threshold,
                inventory_limit_rules=inventory_limit_rules,
            )
            executed_runs += result["executed_runs"]
            reason = next(
                (
                    flag
                    for flag in (
                        "inventory_unconfirmed",
                        "annihilation_agency_locked",
                        "annihilation_reward_full",
                        "sanity_drain",
                        "stopped_by_deadline",
                        "stopped_by_inventory",
                    )
                    if result.get(flag)
                ),
                "returned",
            )
            observe_activity(
                self,
                "stage-plan",
                "mower",
                "incomplete" if result.get("inventory_unconfirmed") else "checked",
                stage=stage,
                executed_runs=executed_runs,
                reason=reason,
            )
            if result.get("annihilation_reward_full") or result.get(
                "annihilation_agency_locked"
            ):
                observe_activity(
                    self,
                    "annihilation",
                    "mower",
                    "agency_locked"
                    if result.get("annihilation_agency_locked")
                    else "reward_full",
                    stage=stage,
                )
            elif stage == "Annihilation" and result["executed_runs"] > 0:
                observe_activity(
                    self,
                    "annihilation",
                    "mower",
                    "completed",
                    stage=stage,
                    executed_runs=executed_runs,
                )
            logger.debug(
                "local operation stage result | stage=%s | mode=%s | result=%s",
                stage,
                mode,
                result,
                extra={"log_group": "local-operation"},
            )

            simulated_current_ap = (
                simulated_current_ap
                if result["simulated_current_ap"] is None
                else result["simulated_current_ap"]
            )
            if result["executed_runs"] > 0:
                executed_any = True
            if result.get("inventory_unconfirmed", False):
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": True,
                    "inventory_unconfirmed": True,
                }
            locked = result.get("annihilation_agency_locked", False)
            if locked or result.get("annihilation_reward_full", False):
                # A full weekly reward or locked Proxy Command ends only this stage,
                # before any battle, so later stages in this dispatch can still run.
                if locked:
                    self.report_annihilation_agency_locked()
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                    "annihilation_skipped": True,
                }
            if result["sanity_drain"] or result["stopped_by_deadline"]:
                logger.debug(
                    "stop local operation stage loop | stage=%s | mode=%s | sanity_drain=%s | stopped_by_deadline=%s",
                    stage,
                    mode,
                    result["sanity_drain"],
                    result["stopped_by_deadline"],
                    extra={"log_group": "local-operation"},
                )
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": True,
                }
            if result.get("stopped_by_inventory", False):
                logger.info(
                    "库存达到上限，结束当前本地刷关: %s",
                    stage,
                    extra={"log_group": "local-operation"},
                )
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                }
            if remaining_runs is None:
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                }

            next_remaining_runs = result["remaining_runs"]
            if next_remaining_runs is None or next_remaining_runs <= 0:
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                }
            if result["executed_runs"] <= 0:
                logger.warning(
                    "跳过 %s 剩下的 %s 次作战",
                    stage,
                    next_remaining_runs,
                    extra={"log_group": "local-operation"},
                )
                return {
                    "simulated_current_ap": simulated_current_ap,
                    "executed_any": executed_any,
                    "should_break": False,
                }

            remaining_runs = next_remaining_runs
            if remaining_runs is not None:
                logger.info(
                    "重新前往 %s，还要打 %s 次",
                    stage,
                    remaining_runs,
                    extra={"log_group": "local-operation"},
                )
            else:
                logger.info(
                    "重新前往 %s，打一轮", stage, extra={"log_group": "local-operation"}
                )
            logger.debug(
                "local operation stage has remaining runs, rerun after renavigation | stage=%s | mode=%s | remaining_runs=%s | simulated_current_ap=%s",
                stage,
                mode,
                remaining_runs,
                simulated_current_ap,
                extra={"log_group": "local-operation"},
            )

    def mower_plan_solver(self, one_time=False, *, manual=False):
        return run_local_operation(self, one_time=one_time, manual=manual)

    def mail_plan_solver(self):
        if config.conf.check_mail_enable:
            MailSolver(self.device, self.recog).run()
        return True

    def event_sign_in_plan_solver(self):
        if not config.conf.event_sign_in_enable:
            if self.daily_event_sign_in_attempt is not None:
                self.daily_event_sign_in_attempt = None
                save_current_state()
            return False
        today = get_server_time().date()
        if self.daily_event_sign_in >= today:
            return False

        from arknights_mower.solvers.event_sign_in import EventSignInSolver

        completed = EventSignInSolver(self.device, self.recog).run()
        self.daily_event_sign_in_attempt = today
        if completed:
            self.daily_event_sign_in = today
        save_current_state()
        return completed

    def report_plan_solver(self):
        if config.conf.report_enable:
            return ReportSolver(self.device, self.recog).run()

    def visit_friend_plan_solver(self):
        if config.conf.visit_friend_enable and config.conf.visit_friend_mode == "mower":
            if self._clue_credit_enabled():
                if config.stop_mower.is_set():
                    raise MowerExit
                solver = CreditSolver(self.device, self.recog)
                visit_day = get_server_time().date()
                try:
                    return solver.run()
                finally:
                    # 只记录实际执行过的游戏日；保留原返回值、异常及重试行为。
                    self.daily_visit_friend_attempt = visit_day
                    try:
                        save_current_state()
                    except Exception:
                        logger.exception(
                            "保存访友尝试日期失败",
                            extra={"log_group": "local-operation"},
                        )
            return CreditSolver(self.device, self.recog).run()

    def sign_in_plan_solver(self):
        if not config.conf.sign_in.enable:
            return
        try:
            import sign_in

            sign_in_solver = sign_in.SignInSolver(self.device, self.recog)
            return sign_in_solver.run()
        except MowerExit:
            raise
        except Exception as e:
            save_exception(e)
            logger.exception(e, extra={"log_group": "local-operation"})
            return True

    @observed_activity("depot", "mower", stopped_exceptions=(MowerExit,))
    def 仓库扫描(self):
        from arknights_mower.utils.depot import restore_cached_inventory

        parent = {"type": "depot-scan", "id": uuid4().hex}

        def log_status(status, *, phase="updated"):
            summary = f"仓库扫描 · {status}"
            logger.info(
                summary,
                extra={
                    "log_group": "depot-recognition",
                    "log_event": {
                        **parent,
                        "phase": phase,
                        "anchor": phase == "started",
                        "summary": summary,
                    },
                    "log_parent": None,
                },
            )

        def keep_cached_inventory():
            observe_activity(self, "depot", "mower", "incomplete", reason="cloud_sync")
            logger.warning(
                "森空岛同步未成功，跳过本次仓库扫描",
                extra={"log_group": "depot-recognition"},
            )
            restore_cached_inventory()
            log_status("森空岛库存同步失败", phase="failed")
            return False

        log_status("正在同步森空岛库存", phase="started")
        try:
            with log_parent_context(parent):
                try:
                    synchronized = cultivateDepotSolver().start(force_inventory=True)
                except (MowerExit, DeviceRecoveryError, SharedADBError):
                    raise
                except Exception as error:
                    logger.debug("森空岛库存同步异常（%s）", type(error).__name__)
                    synchronized = False
                if not synchronized:
                    return keep_cached_inventory()
                log_status("正在进入游戏内仓库")
                scanner = DepotSolver(self.device, self.recog)
                if not scanner.run(report_progress=log_status):
                    observe_activity(
                        self, "depot", "mower", "incomplete", reason="scan_unconfirmed"
                    )
                    log_status("扫描结果未确认", phase="failed")
                    return False
                item_count = len(scanner.结果字典)
        except MowerExit:
            log_status("已停止扫描", phase="stopped")
            raise
        except (DeviceRecoveryError, SharedADBError):
            log_status("设备异常，扫描中断", phase="failed")
            raise
        except Exception as e:
            observe_activity(self, "depot", "mower", "error", reason="exception")
            save_exception(e)
            logger.exception(
                "仓库扫描失败：%s",
                e,
                extra={"log_group": "depot-recognition", "log_parent": parent},
            )
            log_status("扫描未完成", phase="failed")
            return False
        log_status(
            f"已更新库存，识别 {item_count} 种物品"
            if item_count
            else "已更新库存，无需额外数量扫描",
            phase="completed",
        )
        self._auto_schedule_mastery_after_scan()
        observe_activity(self, "depot", "mower", "completed")
        return True

    def _auto_schedule_mastery_after_scan(self):
        try:
            from arknights_mower.utils.mastery_db import retry_failed_plans

            retried = retry_failed_plans()
            if retried > 0:
                logger.info(
                    f"仓库扫描: 已重置 {retried} 个失败的专精计划为待执行",
                    extra={"log_group": "growth-planning"},
                )

            from arknights_mower.utils.mastery_recommendation import (
                auto_schedule_mastery_tasks,
            )

            res = auto_schedule_mastery_tasks()
            logger.debug(
                "仓库扫描: 专精调度完毕, "
                f"scheduled={len(res.get('scheduled', []))}, "
                f"skipped={len(res.get('skipped', []))}",
                extra={"log_group": "growth-planning"},
            )

            # 扫描确认材料后，复用单个开始任务的派发入口。
            if config.conf.mastery_enabled:
                self._dispatch_scan_start_tasks(res.get("scheduled", []))

            from arknights_mower.utils.workshop_automation import update_workshop_config

            update_workshop_config()
        except Exception as e:
            logger.exception(
                f"自动安排专精/合成配置失败: {e}",
                extra={"log_group": "growth-planning", "archive_screenshots": False},
            )

    def _dispatch_scan_start_tasks(self, scheduled):
        """训练室没有训练或专精任务时，仅派发首个材料就绪的待执行计划。

        候选由 auto_schedule_mastery_tasks 核算，计划按 priority、id 选择。
        已有安排中、训练中、待收取的计划或已观测的占用均阻止新开始任务；
        跳过已观测保护不允许的干员，重复触发保留已排任务及时间。
        材料等待计划仍优先于其他待执行计划。
        """
        if not scheduled or not config.conf.mastery_enabled:
            return
        from arknights_mower.solvers.mastery_reader import (
            _notify_protected,
            _protected_trainee_matches,
            _schedule_scan_start,
        )
        from arknights_mower.utils.mastery_db import (
            get_all_plans,
            get_material_waiting_plan,
        )

        plans = get_all_plans()  # 非终态，按 priority, id 排序
        if any(
            plan["status"] in ("arranging", "training", "waiting_collect")
            for plan in plans
        ):
            return
        room = getattr(self, "train_room_state", None)
        if getattr(room, "state", None) in (
            "training",
            "waiting_collect",
        ) and not getattr(room, "collected", False):
            return
        current = getattr(self, "task", None)
        waiting_starts = {
            str(task.mastery_mood_wait["plan_id"])
            for task in getattr(self, "tasks", [])
            if task.type == TaskTypes.SKILL_UPGRADE
            and getattr(task, "execution_failure", None)
            and getattr(task, "mastery_mood_wait", None)
        }
        waiting_starts.update(
            str(task.plan_key)
            for task in getattr(self, "tasks", [])
            if task.type == TaskTypes.SKILL_UPGRADE
            and getattr(task, "execution_failure", None)
            and getattr(task, "mastery_trainee_wait", None)
        )
        if any(
            task is not current
            and task.type in (TaskTypes.SKILL_UPGRADE, TaskTypes.SWAP_SUPPORT)
            and not (
                task.type == TaskTypes.SKILL_UPGRADE
                and getattr(task, "execution_failure", None)
                and (
                    getattr(task, "mastery_mood_wait", None)
                    or getattr(task, "mastery_trainee_wait", None)
                )
            )
            for task in getattr(self, "tasks", [])
        ):
            return

        confirmed = {
            (entry.get("char_id"), entry.get("skill_index")): entry
            for entry in scheduled
        }
        waiting = get_material_waiting_plan(plans)
        if waiting is not None:
            plans = [waiting]
        protection_notified = False
        for plan in plans:
            if plan["status"] != "idle" or str(plan["id"]) in waiting_starts:
                continue
            key = (plan["char_id"], plan["skill_index"])
            entry = confirmed.get(key)
            if entry is None:
                continue
            if getattr(
                room, "protected", False
            ) is True and not _protected_trainee_matches(plan, room):
                if not protection_notified:
                    _notify_protected(self, room)
                    protection_notified = True
                continue
            step_level = entry.get("current_level", 0) + 1
            _schedule_scan_start(self, plan, step_level=step_level)
            logger.info(
                "已为 1 个材料足够的空闲专精计划安排开始训练",
                extra={"log_group": "growth-planning"},
            )
            return

    def _sync_idle_device(self):
        """接收空闲生命周期操作后设备控制持有的设备对象。"""
        if control := getattr(self.device, "session_control", None):
            device = control.start().unwrap()
            self.device = device
            self.recog.device = device

    def _stop_after_round(self, body=""):
        if not round_stop.finish_if_requested():
            return
        message = "本轮任务结束，已按要求停止"
        logger.info(message)
        try:
            if body:
                stopped_body = (
                    f"<p>以下是停止前尚未执行的任务，重新启动前不会自动执行。</p>{body}"
                )
                send_message(stopped_body, message, body_is_html=True)
            else:
                send_message(message, message)
        except Exception:
            logger.exception("发送本轮结束停止通知失败")
        raise MowerExit

    def _idle_sleep(
        self, remaining_time, allow_wakeup=True, *, round_end=False, cancelled=None
    ):
        """等待任务并统一维护 `sleeping` 与连续场景观测边界。

        普通等待响应调度器唤醒；维护等待响应停止或当前暂停的明确取消。
        长时间等待开始前释放缓存画面和本地 OCR 模型。
        成功恢复时清理标准画面帧、场景和计时；设备恢复失败时保留待完成的识别复位。
        主循环成功恢复设备后完成复位；取消与错误始终复位 `sleeping`。
        """
        restoration_failures = (
            self._run_order_restoration_failures()
            if allow_wakeup and remaining_time > 0
            else None
        )
        emergency_checkpoint = (
            self._emergency_continuation_checkpoint()
            if allow_wakeup and remaining_time > 0
            else None
        )
        release_idle_memory = remaining_time > _LONG_IDLE_SECONDS
        self.sleeping = True
        try:
            end_time = datetime.now() + timedelta(seconds=remaining_time)
            while datetime.now() < end_time:
                if config.software_update_shutdown_requested():
                    config.stop_mower.set()
                    raise MowerExit
                if cancelled is not None and cancelled():
                    break
                if round_end:
                    self._stop_after_round()
                refresh_resource_at_boundary()
                if allow_wakeup and config.wake_scheduler.is_set():
                    config.wake_scheduler.clear()
                    break
                if release_idle_memory and not config.stop_mower.is_set():
                    self.recog.release_frame()
                    rapidocr.release_idle_local_model()
                    release_idle_memory = False
                csleep(min(1, (end_time - datetime.now()).total_seconds()))
            if config.software_update_shutdown_requested():
                config.stop_mower.set()
            if config.stop_mower.is_set():
                raise MowerExit
            if round_end:
                self._stop_after_round()
            self._idle_observation_pending = True
            if restoration_failures is not None:
                self._idle_run_order_restoration_failures = restoration_failures
            if emergency_checkpoint is not None:
                self._idle_emergency_checkpoint = emergency_checkpoint
            refresh_resource_at_boundary()
            if allow_wakeup and config.maintenance_recheck.is_set():
                # 先交回主循环检查维护，保留关闭标记和待恢复的观察责任。
                config.wake_scheduler.clear()
                return
            if (
                config.conf.close_simulator_when_idle
                and self._simulator_closed_for_idle
            ):
                logger.info("休眠结束，启动自动关闭的模拟器")
                if not restart_simulator(stop=False, start=True):
                    raise ConnectionError("休眠结束后模拟器启动失败")
                # 启动成功即结束本轮的主动启动，后续连接故障交由正常重连恢复。
                self._simulator_closed_for_idle = False
                self._sync_idle_device()
                self.device.reconnect()
            BaseSchedulerSolver._complete_idle_observation(self)
        except MowerExit:
            self.__dict__.pop("_idle_run_order_restoration_failures", None)
            self.__dict__.pop("_idle_emergency_checkpoint", None)
            raise
        finally:
            self.sleeping = False

    def _complete_idle_observation(self):
        """画面成功复位后，完成原有正常等待的补充观察责任。"""
        self.recog.reset_after_external_control()
        failures = self.__dict__.pop("_idle_run_order_restoration_failures", None)
        if failures is not None:
            self._request_run_order_restoration_observations(failures)
        checkpoint = self.__dict__.pop("_idle_emergency_checkpoint", None)
        if checkpoint is not None:
            self._request_emergency_continuation_observation(checkpoint)
        self._idle_observation_pending = False

    def _refresh_workshop_inventory(self):
        """Reconcile committed drops after external control and before idle sleep."""
        from arknights_mower.utils.workshop_automation import (
            refresh_workshop_after_inventory_change,
        )

        if (
            not workshop_inventory_changed.is_set()
            or battle_inventory_active.is_set()
            or config.stop_mower.is_set()
            or getattr(self, "MAA", None) is not None
            or getattr(self, "op_data", None) is None
            or any(
                getattr(task, "emergency_staffing", False)
                for task in task_view(self.tasks, TaskScope.DISPATCH, self.op_data)
            )
            or any(task.type == TaskTypes.WORKSHOP and task.plan for task in self.tasks)
        ):
            return
        if not refresh_workshop_after_inventory_change():
            return
        if not self.find_next_task(datetime.now() + timedelta(minutes=5)):
            self._read_missing_calculated_moods()
            self._read_missing_workshop_moods()
            try_workshop_tasks(self.op_data, self.tasks)
            scheduling(self.tasks, op_data=self.op_data)

    def rest_until_next_task(self, *, window_observed_at=None):
        """完成本轮任务后，休息到下个可派发任务或大型任务时段开始。

        发休息通知、累计任务计数、并真正睡到下个任务。
        maa_plan_solver / mower_plan_solver / __main__ 主循环此前各自复制了
        一份几乎相同的实现，其中两份漏掉了 `sleeping`，正是 /status 卡在
        working 的根因。现在全部收口到这里，只有 `_idle_sleep` 一个状态写入点。
        """
        if config.maintenance_recheck.is_set():
            first = self.find_next_task()
            if first is None or first.time > datetime.now():
                self._stop_after_round()
            return
        opening_before_cleanup = None
        if config.conf.maa_rg_enable:
            _, opening_before_cleanup = long_task_window(
                config.conf, window_observed_at or datetime.now()
            )
        from arknights_mower.solvers.mastery_reader import (
            discard_completed_mastery_tasks,
        )

        discard_completed_mastery_tasks(self)
        from arknights_mower.solvers.growth import run_growth

        run_growth(self)
        self._refresh_workshop_inventory()
        self._refresh_observed_recovery_tasks()
        if any(getattr(task, "execution_failure", None) for task in self.tasks):
            # 本轮末尾可能已有新观测，或刚完成最后一单；休眠前恢复派发责任。
            self._resume_failed_tasks()
            self._queue_missing_run_order_reads()
            scheduling(self.tasks, op_data=getattr(self, "op_data", None))
        self._schedule_maintenance_backup_check()
        # 保留任务的原时间不代表当前可执行；休眠预算沿用关键任务避让顺序。
        protect_priority_tasks(self.tasks, op_data=getattr(self, "op_data", None))
        first = self.find_next_task()
        now = datetime.now()
        if first is None or (
            config.conf.maa_rg_enable
            and opening_before_cleanup is not None
            and opening_before_cleanup <= now
        ):
            self._stop_after_round()
            return
        wake_at = first.time
        if config.conf.maa_rg_enable:
            _, opening = long_task_window(config.conf, now)
            if opening is not None:
                wake_at = min(wake_at, opening)
        remaining_time = (wake_at - now).total_seconds()
        if remaining_time <= 0:
            return
        for pending in self.tasks:
            if failure := getattr(pending, "execution_failure", None):
                if failure.get("dependency", False):
                    continue
                logger.warning(
                    "未完成任务暂停派发：原时间=%s，任务=%s，原因=%s",
                    pending.time,
                    pending.display_name,
                    failure["reason"],
                )
        self.handle_idle_action(remaining_time)
        timezone_offset = config.conf.timezone_offset
        self.task_count += 1
        logger.info(f"第{self.task_count}次任务结束")
        body = task_template.render(
            tasks=[obj.format(timezone_offset) for obj in self.tasks],
            base_scheduler=self,
        )
        self._stop_after_round(body)
        window_opens_first = wake_at < first.time
        presentation = (
            {}
            if window_opens_first
            else build_task_presentation(first, getattr(self, "op_data", None))
        )
        forecast_now = datetime.now()
        display_remaining = max(0, (wake_at - forecast_now).total_seconds())
        next_time = wake_at.strftime(
            "%m-%d %H:%M:%S" if wake_at.date() != forecast_now.date() else "%H:%M:%S"
        )
        header = f"休息 {format_wait_duration(display_remaining)}，至 {next_time}"
        agents = []
        if window_opens_first:
            header += "，随后进入大型任务执行时段"
        elif presentation["title"]:
            header += f"，随后执行「{presentation['title']}」"
        if (
            not window_opens_first
            and first.type == TaskTypes.EXHAUST_OFF
            and not presentation["rooms"]
            and isinstance(first.meta_data, str)
            and first.meta_data
        ):
            agents = first.meta_data.split(",")
            header += "，目标干员：" + "、".join(
                f"[[operator:{name}]]" for name in agents
            )
        logger.info(
            header
            if window_opens_first
            else format_task_log_message(presentation, header),
            extra={
                "log_agents": agents,
                "log_task": {
                    **presentation,
                    "header": header,
                    "wait_seconds": display_remaining,
                },
            },
        )
        send_message(
            body,
            f"休息 {format_time(remaining_time)}，到{(wake_at + timedelta(hours=timezone_offset)).strftime('%H:%M:%S')}开始工作",
            body_is_html=True,
        )
        if window_opens_first:
            remaining_time = max(0, (wake_at - datetime.now()).total_seconds())
        self._idle_sleep(remaining_time, round_end=True)
        if config.maintenance_recheck.is_set():
            return
        self.check_current_focus()

    def _get_idle_action(self, remaining_time=0):
        if (
            config.conf.close_simulator_when_idle
            and remaining_time > _LONG_IDLE_SECONDS
        ):
            return "close"
        if config.conf.exit_game_when_idle and remaining_time > _LONG_IDLE_SECONDS:
            return "exit"
        if config.conf.return_home_when_idle:
            return "home"
        return "idle"

    def handle_idle_action(self, remaining_time=0):
        if getattr(self, "_simulator_closed_for_idle", False):
            return
        action = self._get_idle_action(remaining_time)
        if action == "close":
            if restart_simulator(start=False):
                self._simulator_closed_for_idle = True
            else:
                self._sync_idle_device()
                logger.warning(
                    "空闲关闭模拟器失败，继续等待；请检查所选实例和管理程序。"
                )
        elif action == "exit":
            self.device.exit()
        elif action == "home":
            self.device.return_home()
